INSERT INTO `article` VALUES ('आदि मानव का इतिहास','history-of-early-man',3,'<p>जिस काल में मनुष्य ने अपने जीवन-यापन की आवश्यकताओं की प्राप्ति के लिए पत्थरों का व्यवहार करना सीखा, उस युग को पूर्व पाषाण युग की संज्ञा दी गई है। पत्थरों को घिस कर वह अपने हथियार बनाता था। इन हथियारों को फेंक कर वह जंगली जानवरों से अपनी रक्षा करता था। इन्ही हथियारों के द्वारा शिकार से वह अपना भोजन भी जुटाता था ।</p><p>इस युग का मुनष्य बर्बर और जंगली था। उसका सामाजिक तथा धार्मिक जीवन विश्रृंखल था। वह जानवरों की तरह कच्चा मांस खाता तथा गुफाओं में रहता था। उसका मुख्य भोजन फल-मूल तथा कच्चा मांस था। शुरू में वह अपना शरीर नहीं ढँकता था, पर धीरे-धीरे उसमें लज्जा का भाव उत्पन्न हुआ औरर उसने ढँकने की आवश्यकता महसूस की। उसने पेड़ों की छाल, पत्तों या जानवरों की खाल पहनना और ओढ़ना प्रारंभ किया ।</p><p>पत्थरों के साथ घनिष्ठ संपर्क ने मनुष्य को आग पैदा करना सिखाया। इसी युग में पत्थरों को घिस कर आग पैदा करने का ज्ञान मनुष्य ने प्राप्त किया। यह इस युग की सबसे बड़ी उपलब्धि थी जिसने मनुष्य को क्रमशः सभ्यता के मार्ग की ओर अग्रसर किया ।</p><p>आग पैदा करने के ज्ञान ने मनुष्य के जीवन में बड़ा परिवर्तन ला दिया। अब वह कच्चे मांस की जगह मांस को भून कर खाने लगा। शीतकाल में आग जला कर उसने ठंढक का मुकाबला करना शुरू किया। अतः, आग का ज्ञान इस युग के लिए वरदान सिद्ध हुआ।</p><p>इस युग के मनुष्य में उस विवेक का जन्म नहीं हुआ था, जो सामाजिक व्यवस्था तथा धार्मिक चिंतन का जनक है। सामाजिक जीवन विश्रृंखल था। विवाह अथवा पारिवारिक संबंध की कल्पना भी नहीं थी। धार्मिक विश्वासों का जन्म नहीं हुआ था। वस्तुतः इस युग के मानव को अपने जीवन-यापन में संघर्ष से ही फुरसत नहीं थी। इसलिए इन क्षेत्रों में उसकी प्रगति शून्य थी ।</p><p>मृतक-संस्कार के भी कोई सुनिश्चित नियम नहीं थे। सुविधानुसार वह अपने मृतकों को कभी जलाता था या कभी यों ही फेंक देता था, जिसे पशु-पक्षी खाया करते थे। कभी- कभी मृतक दफनाए भी जाते थे।</p><p>पूर्व-पाषाण युग की सभ्यता का समय निश्चित करना कठिन है। पर, विद्वानों का अनुमान है कि यह युग 40 हजार ई. पू. से 15 हजार ई. पू. तक रहा होगा।</p>\r\n<h1 id=\"नव_पाषाण_युग\">नव-पाषाण युग</h1>\r\n<p>नव-पाषाण युग में मनुष्य निश्चित रूप से सभ्यता के पथ पर आगे बढ़ा। यदि यह कहा जाय कि इसी युग में मानव सभ्यता की नींव रखी गई, जिसका विकसित रूप हम आज भी पाते हैं तो कोई अत्युक्ति नहीं होगी। मानव जीवन की जितनी मौलिक आवश्यकताएँ हैं, उन सबों की पूर्ति के साधनों की ओर मानव इस काल में अग्रसर हुआ। उसका जो कुछ भी विकास इस युग में हुआ, वह उसके अनुभवों के आधार पर हुआ। अनुभव के</p>\r\n<p>साथ-साथ परंपरा और स्मरण शक्ति से लाभान्वित होकर मनुष्य ने अपने दैनिक जीवन में कुशल विविधता और सौंदर्य की ओर अभिरुचि दिखलायी ।</p><p>मनुष्य का कृषि-कार्य से परिचय इस युग का सबसे क्रांतिकारी परिवर्तन था। अपने दैनिक जीवन के कार्य-पालन में मनुष्य ने बीज अंकुरित होते देखा और इससे उसकी खेती में अभिरुचि हुई। कृषि का ज्ञान मनुष्य को संभवतः कंद-मूल, फलं इकट्ठा करने तथा उन्हें सँजोने के सिलसिले में ही हुआ। इसके परिणामस्वरूप मनुष्य ने अपने आसपास की भूमि में खेती करना शुरू किया। खेती के प्रारंभ से मनुष्य के जीवन में अधिक स्थिरता तथा व्यवस्था आ गई।</p><p>इसी प्रकार मनुष्य ने अनुभव किया कि केवल पशु-पक्षियों के शिकार से उसके भोजन की समस्या हल नहीं होती, क्योंकि शिकार से प्राप्त मांस उसकी आवश्यकता के लिए अपर्याप्त होता था। इसलिए उसे पशुपालन अधिक लाभकर प्रतीत हुआ और उसने इस व्यवसाय में अभिरुचि दिखलायी ।</p><p>इसी काल में अग्नि का प्रयोग अधिक होने लगा। मनुष्य ने कच्चे मांस और फल-फूल की जगह भोजन पकाना शुरू किया। इस क्षेत्र में स्त्रियों का योगदान अधिक था। अतः, इस काल के खाद्य पदार्थों में फल, कंद, मूल, अन्न और मांस आदि थे। पेय पदार्थों में दूध , ताड़ी तथा कई पौधों के रस सम्मिलित थे ।</p>\r\n<p>इसी काल में गृह-निर्माण की कला का भी विकास हुआ। खोहों और कंदराओं को त्याग कर मनुष्य ने झोपड़ियों का निर्माण किया। सबसे पहले उसने पशु-चर्मके तम्बुओं में रहना सीखा। बाद में उसने पेड़ों की टहनियों, नरकुल, घास-फूस तथा मिट्टी से झोपड़ियाँ बनाना आरंभ किया ।</p>\r\n<p>कृषि के विकास से मनुष्य में सँजोने और संग्रह की प्रवृत्ति का उदय हुआ । अनाज को रखने के लिए उसे पात्रों की आवश्यकता प्रतीत हुई। इसलिए उसने चाक का आविष्कार किया और मिट्टी के बड़े-बड़े बर्तन बनाए जाने लगे।</p>\r\n<p>संभवतः इसी युग में कपास की भी खेती होने लगी तथा मनुष्य ने वस्त्र-निर्माण करना सीख लिया। उसने पौधों के रेशों और पशुओं के बालों से भी एक प्रकार का वस्त्र तैयार करना शुरू किया। वनस्पति से तैयार किए गए रंगों से कपड़े लाल, पीले, हरे और नीले रंगों में रँगे जाने लगे ।</p>\r\n<p>क्रमशः शरीर के श्रृंगार में भी मनुष्य की अभिरुचि हुई। बाल सँवारने की प्रथा शुरू हुई और पत्थर, कौड़ी सीप तथा हड्डियों के आभूषण भी पहने जाने लगे।</p>\r\n<p>इस युग में औजारों तथा हथियारों में आश्चर्यजनक विकास हुआ। मनुष्य ने पत्थरों को रगड़-रगड़ कर चिकना और चमकदार बनाना प्रारंभ किया। इन हथियारों के जो नमूने पाए गए हैं, वे इनकी सुंदरता के प्रमाण हैं। वस्तुतः इस युग के औजार अधिक सुडौल, सुव्यवस्थित तथा विविध प्रकार के हैं। मनुष्य ने पत्थरों के साथ-साथ हड्डियों और लकड़ी से भी औजार बनाने शुरू किए।</p>\r\n<p>इन क्षेत्रों में विकास के कारण मनुष्य के सामाजिक तथा धार्मिक जीवन में भी परिवर्तन हुए। कृषि, पशु-पालन तथा गृह-निर्माण ने मनुष्य में सहयोग तथा सहकारिता की भावना को जन्म दिया, जिससे समाज का जन्म हुआ। मनुष्य का जीवन सामूहिक हो गया। सामूहिक आवास से गाँवों का जन्म हुआ और गाँवों में कार्य-विभाजन की सुविधा के लिए विभिन्न पेशों का उदय हुआ। क्रमशः विवाह एवं परिवार की संस्थाएँ भी विकसित हुईं।</p>\r\n<p>सामाजिक जीवन के विकास के साथ ही धार्मिक चिंतन का भी प्रादुर्भाव हुआ। जीवन के दुःख-सुख ने मनुष्य को दैवी और दानवी शक्तियों के विषय में सोचने को बाध्य किया। मनुष्य भौतिक पदार्थों में एक प्रकार की जीवन-शक्ति का अनुभव करने लगा। इस युग के धर्म को \'भूतवाद\' संज्ञा दी जा सकती है। इसी युग में पत्थरों और वृक्षों की पूजा प्रारंभ हुई। लिंग-पूजा क विकास भी इसी समय हुआ। जीवन-मरण के विषय में मनुष्य के विचार स्थिर हो चुके थे। वह शव को अधिकतर दफनाता या कभी-कभी जलाता भी था। कभी- कभी मृतकों के अस्थि-पात्रों के ऊपर समाधि भी बनायीं जाती थी।</p>\r\n<p>सामाजिक जीवन के विकास के साथ-साथ भाषा का भी क्रमशः विकास होने लगा और मनुष्य की कलात्मक अभिरुचि की भी अभिव्यक्ति होने लगी। मिट्टी के बने बर्तनों में इस प्रवृत्ति की प्रथम अभिव्यक्ति हुई। धीरे-धीरे मनुष्य शिलाओं और कन्दराओं में रेखाचित्र भी बनाने लगा, जो मान जाति के कलात्मक प्रयत्न के सबसे पुराने नमूने हैं।</p>\r\n<p>इस युग के आविष्कारों और परिवर्तनों ने मानव सभ्यता के विकास को अपूर्व बल प्रदान किया। इन अनुभवों के कारण मनुष्य में आत्मविश्वास का जन्म हुआ, जो उसे दिनोंदिन विकास की ओर बढ़ाता गया। पूर्व-पाषाण काल का प्रकृतिजीवी मनुष्य उद्योगजीवी तथा विकासोन्मुख हो गया। इस युग में वर्तमान मानव सभ्यता के अनेक अंग बीज रूप में विद्यमान थे। केवल लेखन-कला, धातुओं का प्रयोग तथा राज्य का प्रादुर्भाव होना ही शेष था। इस युग का प्रसार लगभग 15 हजार ई. पू. से 4 हजार ई. पू. तक था।</p>\r\n<h2 id=\"धातु_युग\">धातु युग</h2>\r\n<p>पाषाण युग के अन्तिम दिनों में धातुओं का सीमित प्रयोग शुरू हो गया था। संभवतः भट्ठी बनाने के काम में लाए हुए धातुमिश्रित पत्थरों से भोजन पकाते समय पिघली हुई अवस्था में जो धातु निकल पड़ता होगा, इसी से मनुष्य को धातुओं से परिचय हुआ होगा । धातुओं से परिचित होकर मनुष्य ने अधिकाधिक धातुओं का प्रयोग प्रथमतः औजार और हथियार बनाने में किया। इस युग के इतिहास को तीन भागों में बाँटा गया है-</p><ul>\r\n<li><p>ताँबे के प्रयोग का काल</p></li>\r\n<li><p>काँसे के प्रयोग का काल, और</p></li>\r\n<li><p>लोहे के प्रयोग का काल</p></li>\r\n</ul>\r\n<p>सबसे पहले ताँबे के औजार और हथियार बनाए जाने लगे। पत्थर के औजारों और हथियारों की तुलना में ताँबे के औजार अधिक सुंदर तथा मजबूत होते थे। ताँबा टूटने पर जुड़ सकता था और इसकी छोटी-बड़ी चादरें बनायी जा सकती थीं। इन गुणों से ताँबा शीघ्र ही लोकप्रिय हो गया।</p>\r\n<p>कालांतर में मनुष्य ने अनुभव किया कि कठोर कामों के लिए ताँबा उपयुक्त नहीं है और मनुष्य ने इस कारण ताँबे और टीन मिला कर काँसे का प्रयोग शुरू किया। काँसे के हथियार काफो कड़े और तीक्ष्ण होते थे। अन्त में मनुष्य ने लोहे को ढूँढ़ निकाला। विद्वानों का मत है कि सबसे पहले हिट्टाइट जाति ने 1300 ई. पू. में लोहे का ज्ञान प्राप्त किया । यहीं से एशियाई तथा भूमध्य सागरीय देशों ने इसका प्रयोग सीखा। लोहे के ज्ञान ने मनुष्य को अत्यंत तीव्र गति से सभ्यता के मार्ग पर अग्रसर किया। हम आज भी लौह युग में ही हैं। इसके बिना हमारी सभ्यता अधूरी ही रहती है।</p>\r\n<p>इन धातुओं के ज्ञान ने मनुष्य के जीवन को विविधता, सौंदर्य तथा कुशलता प्रदान की। मनुष्य की योग्यता, शक्ति तथा आत्मविश्वास में अभूतपूर्व प्रगति हुई। पूर्व-पाषाण काल का बर्बर मनुष्य अब सभ्य मानव में परिवर्तित हो चुका था और उसने पृथ्वी के विभिन्न भागों में ऐतिहासिक सभ्यताओं की सृष्टि की ।</p>',45,'2024-10-15 15:45:13','2024-10-15 16:02:32','','Publish',0,'open',4,1),('हड़प्पा सभ्यता के नगर निर्माण योजना','harappan-civilization-city-building-plan',2,'<p>हड़प्पा सभ्यता की नगर निर्माण योजना उन्नत और संगठित थी। शहरों में ग्रिड पैटर्न में सड़कों का निर्माण किया गया था, जिसमें मुख्य सड़कें एक दूसरे को समकोण पर काटती थीं। घर पक्की ईंटों से बने होते थे और कई में आंगन, कुएं और स्नानगृह होते थे। नालियों का एक सुव्यवस्थित जल निकासी प्रणाली थी जो गंदे पानी को बाहर निकालती थी। प्रमुख शहरों में एक दुर्ग (सिटाडेल) होता था, जिसमें सार्वजनिक और धार्मिक भवन स्थित होते थे। इस योजना से हड़प्पा सभ्यता की उच्चस्तरीय शहरीकरण और सामाजिक संगठन क्षमता का पता चलता है।</p>\r\n<h2 id=\"हड़प्पा_सभ्यता_के_नगर_निर्माण\">हड़प्पा सभ्यता के नगर निर्माण</h2>\r\n<p>हड़प्पा सभ्यता विश्व के प्राचीन सभ्यताओं में से एक है, इस सभ्यता का कालक्रम लगभग 2500 से 1500 ईसा पूर्व तक माना जाता है। इस सभ्यता के विशेषता यह थी कि यह सभ्यता एक नगरीय सभ्यता थी। इस सभ्यता के अंतर्गत कई शहरों के भग्नाअवशेष पाए गए हैं जैसे- हड़प्पा, मोहनजोदड़ो, चिहुन्दड़ो, लोथल, कालीबंगा, बनवाली इत्यादि। भग्नाअवशेषों को देखने से यह पता चलता है कि इस काल में नगरों का निर्माण एक निश्चित योजना के आधार पर किया गया था, इस सभ्यता के विषय में एक ब्रिटिश इतिहासकार ने लिखा है कि- <i>\"जब मैं मोहनजोदड़ो के खण्डहरों के बीच पहुंचा तो ऐसा मालूम हुआ कि वर्तमान लकाशायर नगर के भग्नाअवशेषों के बीच खड़ा हूँ।\"</i> हड़प्पा और मोहनजोदड़ो नगर सुव्यवस्थित योजना के अनुसार बनाए गए थे और इनकी आबादी काफी घनी थी। </p>\r\n<p>हड़प्पा नगर के खण्डरो का परीक्षण करने से ज्ञात होता है कि इस सभ्यता के निवासी नगर की स्थापना में बड़े कुशल थे नगरों की योजना अत्यंत वैज्ञानिक तथा सुव्यवस्थित था।</p>\r\n<h3 class=\"atech\" id=\"बाजारों_की_व्यवस्था\">बाजारों की व्यवस्था</h3>\r\n<p>हड़प्पा सभ्यता के शहरों में एक विशाल बाजार क्षेत्र था, जहाँ संभवत व्यापारी वस्तुओं का आदान-प्रदान होता था और लोगों की दैनिक आवश्यकताओं की पूर्ति के उद्देश्य से सड़क के किनारे दुकान की व्यवस्था की गई थी। हड़प्पा और मोहनजोदड़ो में सड़कों के पास कुछ ऐसे भवन मिले हैं जो दुकान रहे होंगे। दुकानों के साथ बड़े गोदाम भी जुड़े होते थे।</p>\r\n<h3 class=\"atech\" id=\"सड़कों_व_गलियों\">सड़कों व गलियों</h3>\r\n<p>हड़प्पा सभ्यता के नगर निर्माण योजना में सड़क को गलियों एवं नालियों पर विशेष ध्यान दिया गया था। सड़क काफी चौड़ी तथा छोटी-बड़ी उप सड़कों एवं गलियों के द्वारा जुड़ा होता था। सड़के पूर्व से पश्चिम की ओर तथा उत्तर से दक्षिण की ओर जाती थी। परिणाम स्वरूप शहर कई वर्गाकार आयतो या खण्डों में विभक्त नजर आता था। मोहनजोदड़ो का मुख्य <strong>सड़क या राजमार्ग </strong>उत्खनन द्वारा प्रकाश में आया है, यह सड़क 10 मीटर चौड़ा तथा 400 मीटर लंबी थी। </p>\r\n<p>सड़के यद्यपि कच्ची मिट्टी की बनी हुई थी फिर भी वे काफी मजबूत थी। उनकी सफाई का भी पर्याप्त ध्यान रखा जाता था, सडक के किनारे कूड़ेदान थी जिसमे सारी गन्दगी जमा कर दी जाती थी। सड़कों पर पानी का जमाव रोकने के लिए सड़कों के किनारो से ढलुआ बनाई जाती थी। इस सभ्यता के विषय में डॉ मैके लिखते हैं- <i>\"सड़क और गलियां इस प्रकार बनाई गई थी कि चलने वाली वायु एक कोने से दूसरे कोने तक शहर को स्वयं साफ कर दें।\"</i> सड़क के दोनों किनारे मकान भी बनाए गए थे।</p>\r\n<h3 class=\"atech\" id=\"नालियों_की_व्यवस्था\">नालियों की व्यवस्था</h3>\r\n<p>इस सभ्यता की सबसे आकर्षक बात यह है कि आजकल की भांति लोग सुव्यवस्थित और विज्ञानिक ढंग से नालियों का प्रबंध करना जानते थे। संपूर्ण नगर में योजनाबंध रूप से नालियां बनाई गई थी, प्रत्योक घर में छोटी नालियां होती थी जो घर का पानी सड़क के नीचे बनी हुई बड़ी नाली में गिरा देती थी। इस प्रकार घर का जल अन्य बड़ी नालियों से मिलकर शहर के बाहर निकल जाता था। </p>\r\n<p>नालियां खड़िया मिट्टी, चूने और एक प्रकार के सीमेंट से बनाई जाती थी। इन नालियों की आज कल के तहत ढंक दिया जाता था। इस संबंध में डॉ वाशग ने लिखा है कि-<i> \"तत्कालीन विश्व में ऐसी व्यवस्था अन्यत्र देखने को नहीं मिलती हैं।\"</i></p>\r\n<h3 class=\"atech\" id=\"दुर्ग_और_निचले_शहर\">दुर्ग और निचले शहर</h3>\r\n<p>हड़प्पा और मोहनजोदड़ो में दो स्तरीय शहर बसाने का प्रमाण मिलता है, पहला दुर्ग और दूसरा निचला शहर। दुर्ग संभवत शासक वर्ग का निवास था और इसमें महत्वपूर्ण राजकीय इमारत बनाई जाती थी। एवं दुर्ग के बाहर निचले शहर स्थित था जिसमें संभवतः सामान्य जन रहा करते थे। हड़प्पा के दुर्ग चतुर्भुज आकार की थी, इसका घेरा करीब 460 x 215 गज था। दुर्ग के भीतर भवनों का निर्माण काफी ऊंचे स्थान पर किया जाता था, दुर्ग पर जाने के लिए सीढ़ी बनाई गई थी। लगभग इसी प्रकार का दुर्ग मोहनजोदड़ो में भी बना हुआ था।</p>\r\n<h3 class=\"atech\" id=\"नगरों_की_सुरक्षा\">नगरों की सुरक्षा</h3>\r\n<p>हड़प्पा सभ्यता में नगरों की सुरक्षा पर विशेष ध्यान दिया गया था। इसकी रक्षा के लिये इसे चारों ओर से दीवार से घेर दिया गया था। यह अनुमान लगाया जाता है कि सुरक्षा के उद्देश्य से अन्य नगरों को भी दीवारों से घेर दिया जाता था। इससे बाहरी दुश्मनों से नगर वासियों को सुरक्षा प्राप्त होती थी और लोग सुख-शांति के साथ रहते थे।</p>\r\n<h3 class=\"atech\" id=\"निपुण_नागरिक_प्रबन्ध\">निपुण नागरिक प्रबन्ध</h3>\r\n<p>हड़प्पा सभ्यता में नगरों की स्वच्छता पर विशेष ध्यान दिया जाता था। सड़कों के किनारे कूड़ा फेंकने के बड़े-बड़े कूड़ेदान मिले हैं। नालियो की व्यवस्था, पानी का प्रबंध, कूड़ेदानों की व्यवस्था, सड़कों के किनारे रौशनी का प्रबंध इतियदि स्पष्ट करती है कि नागरिको के जीवन को सुखी बनाने के लिए जिस तरह का प्रबंध यहाँ किया गया था, उतना संभवतः किसी प्राचीन सभ्य देश में नहीं किया जा सका। गलियों में रौशनी का विशेष प्रबंधन था।</p>\r\n<p>यात्रियों के लिए सराएँ बनायी गई थी। रात को नागरिको की रक्षा के लिए पहरे का भी प्रबंधन था। शहर की गंदगी को शहर के बाहर खाइयों में फेंका जाता था, नागरिक घर का कूड़ा-कचड़ा गली या सड़कों पर नहीं फेंक सकते थे। इन सबको देखकर अनुमान किया जाता है कि यह नियमित नगर शासन की भी कोई व्यवस्था रही होगी। प्रसिद्ध इतिहासकार बी. गार्डन चाइल्ड कहते हैं- <i>\"गलियों की सुन्दरता पक्तियाँ तथा नालियों की उत्तम व्यवस्था एवं उनकी सतत स्वच्छता से इस बात की संकेत मिलता है कि यहाँ कोई नियमित नगर शासन था जो अपना कार्य सावधानी से संपन्न करता था।\"</i></p>\r\n<h2 class=\"atech\" id=\"निष्कर्ष\">निष्कर्ष</h2>\r\n<p>इस प्रकार हम देखते हैं कि हड़प्पा सभ्यता विश्व के प्राचीन नगरीय सभ्यताओं मे से एक है। जिसमें नगरों के स्वच्छता पर विशेष ध्यान दिया जाता था। नगरों को आज के आधुनिक नगर की तरह ही व्यवस्थित किया गया था। सड़के समकोण पर काटती थीं, छोटी नालियां के पानी सड़क के नीचे बड़ी नालियों में जाकर गिरती थी, मकान सड़क के दोनों किनारे तथा एक सामान्य आकार में बनाए जाते थे। व्यापार के लिये बाजार की व्यवस्था तथा सड़क के किनारे दुकान बनाए गए थे, जो एक बड़े गोदाम से जुड़े होते थे।</p>\r\n',127,'2024-10-16 03:13:23','2024-10-16 03:41:49','','Publish',0,'open',19,2),('स्पार्टा के मुख्य विशेषताओं का वर्णन','describe-the-main-features-of-sparta',2,'<p>स्पार्टा का इतिहास अपनी सैन्यवादी संस्कृति और महिला अधिकारों के लिए जाना जाता है। स्पार्टा प्राचीन ग्रीस का एक प्रमुख शहर-राज्य था, जो एक घाटी बीच में और पहाड़ों से घिरा हुआ था। जब स्पार्टा में किसी बच्चे की जन्म होती थी, तो उसका परीक्षण किया जाता था। यदि कोई बच्चा शारीरिक या मानसिक रूप से विकलांग पाया जाता था, तो उसे पहाड़ों से फेंककर मार दिया जाता था। इसी विषय में एक इतिहासकार लिखते हैं- <i>\"स्पार्टा का कभी बीमा नहीं किया गया था। स्पार्टन का मानना था कि दीवारों की आवश्यकता नहीं थी क्योंकि बहादुर नागरिक ने शहर की रक्षा की थी।\"</i> स्पार्टा के लोगों को इस तरह बनाया जाता था कि वह किसी भी परिस्थिति में जीवित रह सकते थे।</p>\r\n<h2 id=\"स्पार्टा_के_मुख्य_विशेषता_निम्नलिखि_हैं_\">स्पार्टा के मुख्य विशेषता निम्नलिखि हैं-</h2>\r\n<h3 class=\"atech\" id=\"सैन्य_व्यवस्था\">सैन्य व्यवस्था</h3>\r\n<p>स्पार्टा का सबसे प्रमुख विशेषता इसका सैन्य व्यवस्था था। स्पार्टा के सारे नागरिक सैनिक होते थे। जब बच्चों को जन्म होता था तो उसका परीक्षण किया जाता था। यदि बच्चा शारीरिक या मानसिक रूप से विकलांग पाया जाता था, तो उसे मार दिया जाता था और यदि बच्चा सवस्थ होता था तो उसे 7 वर्ष के बाद अपने घर को छोड़कर राज्य के छात्रावास में जाना पड़ता था। उन्हें वहाँ ऐसा बनाया जाता था, जो किसी भी परिस्थिति में अपने आप को जीवित रख सकता था। उन्हें वहाँ जमीन पर सोना पड़ता था, गंदे खाना खाने पड़ते थे। बच्चों को सभी प्रकार के बधाओं से लड़ने के लिए कठोर बनाया जाता था। जब वे 12 वर्ष की आयु के हो जाते थे, तो उन्हें एक कपड़ा दिया जाता था। जिससे वे शरीर ढकने के लिए उपयोग करते थे। यदि कपड़ा उससे कोई चुरा लेता तो उसकी बुरी तरह पिटाई की जाती थी। </p>\r\n<p>अतः 18 वर्ष के बाद जब उनके शिक्षा का परीक्षण के समय उन्हें रात में खूंखार भेड़ियों के सामने छोड़ दिया जाता था और यदि वे रातभर जीवित रहकर वापस आते थे, तो उसे सैनिकों में शामिल कर लिया जाता था।</p>\r\n<h3 class=\"atech\" id=\"लैकेडेमोनियन_प्रणाली\">लैकेडेमोनियन प्रणाली</h3>\r\n<p>स्पार्टन समाज में एक विशेष प्रकार की नृत्य व्यवस्था थी, जिसे लैकेडेमोनियन प्रणाली कहा जाता था। इस नृत्य में समाज को वर्गीकृत किया जाता था और सभी नागरिको को विशेष शैली में तैयार किया जाता था। नृत्य में सशस्त्र के साथ सभी तरह के सुरक्षा व्यवस्था का भी प्रदर्शन किया जाता था। जिसे सुरक्षा प्रणाली की सृष्टि करने में मदद करता था।</p>\r\n<h3 class=\"atech\" id=\"भोजनालय_प्रणाली_(helot_system)\">भोजनालय प्रणाली (Helot System)</h3>\r\n<p>स्पार्टन समाज में एक विशेष प्रकार की भोजनालय थी। जहाँ सभी स्पार्टन लोग भोजन करते थे तथा सभी को एक प्रकार का भोजन दिया जाता था। इस भोजन के लिए सभी लोगों से कर लिया जाता था यदि कोई कर न देता तो उसे देश निकाला घोषित कर दिया जाता था। 20 वर्ष की उम्र में ही, स्पर्ती नागरिक किसी भी एक सिस्किया (भोजनालयों अथवा क्लबों) का सदस्य बन जाता था</p>\r\n<h3 class=\"atech\" id=\"शिक्षा_व्यवस्था\">शिक्षा व्यवस्था </h3>\r\n<p>स्पार्टन समाज में स्पार्टा के सभी लोगों को एक सम्मान शिक्षा का नियम था। लड़के सामुदायिक मेसों में रहते थे और उन्हें जानबूझ कर अल्पाहार दिया जाता था ताकि उन्हें भोजन चुराने की कला में महारत हासिल करने के लिए प्रोत्साहित किया जाए। शारीरिक और शास्त्र शिक्षा के अलावे, लड़कों को पठन, लेखन, संगीत और नृत्य का अध्ययन करना पड़ता था।  लड़का या लड़की दोनों को सख्त नियमों का पालन करना पड़ता था तथा दोनों को कठोर शिक्षा दी जाती थी। लड़कियों को बुनाई कटाई आदि के साथ-साथ घरों का काम भी सिखाया जाता था।</p>\r\n<h3 class=\"atech\" id=\"सामूहिकता_और_समाजिक_समानता\">सामूहिकता और समाजिक समानता</h3>\r\n<p>स्पार्टा में सामूहिकता और समाजिक समानता का भावना थी। समाज में व्यक्ति की आत्मनिर्भरता की बजाय समृद्धि और सुरक्षा के लिए सामूहिक प्रयासों को प्रोत्साहित किया जाता था।</p>\r\n<h3 class=\"atech\" id=\"संविदानिक_सरकार_प्रणाली\">संविदानिक सरकार प्रणाली</h3>\r\n<p>स्पार्टा में एक संविदानिक सरकार प्रणाली थी, जिसमें दो राजा या बासिलेस, एक सिनेट (गेरोसिय) और और अन्य स्थानीय प्रणालियाँ शामिल थीं। स्थानीय प्रणालियाँ एक समूह का राजा हुआ करता था, जो उस समूह का परीक्षण करता था तथा अन्य राजा के ऊपर सिनेट राजा हुआ करता था।</p>\r\n<p>इस प्रकार हम देखते हैं कि स्पार्टा अपनी सैन्य शक्ति के लिए जाना जाता था तथा स्पार्टन लोगों को न तो विचारों की स्वतंत्रता थी और न जीवन को प्रफूलता। सारा देश एक सैनिक शिविर की भांति हो गया था। स्पार्टन ने एकमात्र सैनिक उत्पन्न किए और कुछ भी नहीं।</p>',14,'2024-10-16 03:13:23','2024-10-16 03:49:28','','Publish',0,'open',26,3),('पूर्व वैदिक आर्यों ऋग्वेदिक की राजनीतिक समाजिक स्थिति','political-and-social-condition-of-the-pre-vedic-aryans-rigvedic',2,'<p>सैन्धव सभ्यता के पतन के बाद भारत में जिस सभ्यता का उदय हुआ उसे आर्य सभ्यता या वैदिक सभ्यता कहते हैं। क्योंकि के निर्माता आर्य थे इसीलिए इसे आर्य सभ्यता कहते हैं। एवं इस सभ्यता की जानकारी हमें वेदों से प्राप्त होती है, अतः इसे वैदिक सभ्यता के नाम से भी पुकार ते हैं। पूर्व वैदिक काल में ऋग्वेद की रचना हुई थी जिससे उस समय राजनीतिक व सामाजिक स्थिति का ज्ञान प्राप्त होता है, जो निम्नलिखित हैं।-</p>\r\n<h2 id=\"राजनीतिक_स्थिति\">राजनीतिक स्थिति </h2>\r\n<p>आर्यों के सामाजिक एवं राजनीतिक संगठन का मूल्य आधार परिवार था। परिवार का प्रधान गृहपति अथवा कुलपति कहलाता था। समाज का संगठन कबिले के रूप में था, कबिले को \"<strong>जन</strong>\" कहकर पुकारा जाता था। एक जन के सारे सदस्यों को सामाजिक रूप से \"<strong>विश</strong>\" कहकर पुकारा जाता था। प्रत्योक विश का एक प्रधान होता था, जो राजा कहलाता था। प्रत्योक में अनेक टुकड़ियां होती थी जो ग्राम कहलाती थी और इसका प्रधान \"<strong>ग्रामणी</strong>\" कहलाता था।</p>\r\n<h3 class=\"atech\" id=\"राजा\">राजा</h3>\r\n<p>ऋग्वेद में राजा की तुलना इंद्र और वरुण से की गई है। राजा का पद वंशानुगत होता था, परन्तु जनता की स्वीकृति आवश्यक थी। सिंहासरोहण के साथ-साथ राज्यअभिषेक की भी परंपरा थी। राज्यअभिषेक के समय राजा को अपनी प्रजा की रक्षा का संकल्प लेना होता था। लोगों के हृदय में राजा के प्रति भक्ति की भावना रहती थी, राजा से हर प्रकार के सहायता की आशा की जाती थी। राजा प्रधान न्यायाधीश था और अपराधियों को उचित दण्ड देता था। दीन-दुखियों को हुआ सहायता भी करता था, वह योग्य पात्रो को उपहार भी देता दिया करता था।</p>\r\n<p>राजा जन अथवा विश का राजा होता ना की भूमि का। प्रजा को राजा को राजपथ से हटाने का अधिकार भी प्राप्त था। राजा के प्रमुख तीन कार्य थे- राज्य की सुरक्षा तथा विस्तार करना, प्रजा का पालन करना और राज्य तथा प्रजा की कल्याण के उद्देश्य से यज्ञ आदि करना। राजा उपज का छठा अंश राज्य कर के रूप में लेता था।</p>\r\n<h3 class=\"atech\" id=\"राज्य_कर्मचारी\">राज्य कर्मचारी</h3>\r\n<p>राजा की सहायता के लिए पुरोहित, सेनानी तथा अनेक कर्मचारी होते थे, इनमें पुरोहित सबसे प्रधान था। पुरोहित का मुख्य कार्य राजपरिवार के धार्मिक गुरु के रूप में था। इन मुख्य सहयोगी इसके अतिरिक्त ऋग्वेद में ग्रामणी, सुत, रथकार और कुर्म्मार जैसे अधिकारियों का उल्लेख मिलता है। इन्हें \"<strong>रत्नी</strong>\" कहा जाता था। ग्रामणी गांव का शासक होता था इसका मुख्य कार्य गांव में शांति स्थापित रखना तथा गांव की समस्याओं को राजा तक पहुंचाना था।</p>\r\n<h3 class=\"atech\" id=\"सभा_और_समिति\">सभा और समिति</h3>\r\n<p>राजा निरंकुश नहीं होता था। विदथ,सभा और समिति जैसे जन संस्थाएँ राजा पर नियंत्रण रखती थी। सभा श्रेष्ठ जनों की सभा थी, समिति बैठक में राजा और प्रजा सामान्य रूप से उपस्थित होते थे। राजा का चुनाव, राजा को सिंहासन से हटाने और उनके स्थान पर अन्य राजा को चयन करने का काम समिति ही करती थी। राजकीय प्रश्नों का निर्णय लेने का अधिकार इसे ही प्राप्त था। </p>\r\n<p>अति प्राचीन काल से आर्यों की जो संस्था चली आ रही थी उसे हम \"<strong>विदथ</strong>\" के नाम से जानते हैं, विदथ जनसभा कहा गया है। अनुमानत: सभा और समिति कलांतर में विदथ से ही निकली।</p>\r\n<h3 class=\"atech\" id=\"न्याय_प्रशासन\">न्याय प्रशासन</h3>\r\n<p>पूर्व वैदिक काल में न्याय का सर्वोच्च अधिकारी राजा होता था। साधारण मामले परिवार के मुखिया या गांव के मुखिया द्वारा सुलझाया जाता था। इसके बाद राजा के पास जाते थे, गंभीर आरोपों में मौत की सजा के पर्वधान था। संभवत: \"<strong>जैसे को तैसा</strong>\" अथवा \"<strong>खून के बदला खून</strong>\", इसी वजह से इस काल में न्याय प्रशासन की कम जानकारी मिलती हैं।</p>\r\n<h3 class=\"atech\" id=\"युद्ध_व्यवस्था\">युद्ध व्यवस्था</h3>\r\n<p>ऋग्वेद का युद्ध का महत्वपूर्ण स्थान था, आर्य लोग लड़ाकू प्रवृत्ति के थे। वे भारत में अनार्यों से तो युद्ध करते ही थे साथ ही आपस में भी लड़ते थे। अधिकतर युद्ध आत्मरक्षा, विजय व लूट के लिए किए जाते थे। युद्ध लड़ने के लिए आधुनिक काल की तरह उस युग में कोई नियमित सेना नहीं थी, जरूरत पड़ने पर नागरिक पैदल, घुड़सवार व रथ का संचालन करने लगते थे। इस युग में घोड़े का प्रयोग अधिक होता था। सेना अपनी रक्षा के लिए तलवार, ढ़ाल, शिरस्त्रण के अलावा धनुषबाण, भाला, फरसा, बरछी आदि का प्रयोग करते थे।</p>\r\n<h2 id=\"सामाजिक_स्थिति\">सामाजिक स्थिति</h2>\r\n<p>ऋग्वैदिक काल में सामाजिक व्यवस्था सहयोग व सहभागिता पर आधारित थी। इस समय समाज पृत सत्तात्मक होने के बावजूद स्त्री-पुरुष में विभेध नहीं था। पुत्रीयो को पुत्र के समान माना जाता था एवं उनकी शिक्षा का अधिकार भी सम्मान थी। इस समय लोग खानाबदोश नहीं थे ये, झोपड़ी या घर बनाकर रहते थे। ऋग्वेद काल की समाजिक स्थिति इस प्रकार हैं।-</p>\r\n<h3 class=\"atech\" id=\"पारिवारिक_जीवन\">पारिवारिक जीवन</h3>\r\n<p>पूर्व वैदिक काल में परिवार का विशेष महत्त्व था। प्रत्योक परिवार में एक मुखिया हुआ करता था, जो उम्र में सबसे बड़ा होता था। परिवार के अन्य सदस्य उसकी आज्ञा का पालन करते थे। इस समय पुत्र न होने पर गोद लेने की प्रथा थी। अतिथियों का सम्मान किया जाता था, इसके अलावा घर में गृह कार्य स्त्री करती थी।</p>\r\n<h3 class=\"atech\" id=\"पोशाक_या_वस्त्र\">पोशाक या वस्त्र</h3>\r\n<p>पूर्व वैदिक काल में स्त्री-पुरुष के लिए अलग-अलग वेशभूषा थी। वस्त्र उन, सूती और चमड़े के बने होते थे, एवं रंग-बिरंगे होते थे। स्त्रियों के तहत पुरुष भी गहनों का प्रयोग करते थे। विवाह के समय एक विशेष प्रकार का वस्त्र धारण करते थे जिसे \"<strong>वधुय</strong>\" कहा जाता था।</p>\r\n<h3 class=\"atech\" id=\"विवाह_व_धार्मिक_कार्य\">विवाह व धार्मिक कार्य</h3>\r\n<p>पूर्व वैदिक काल में लोग विवाह को एक धार्मिक व पवित्र कार्य मानते थे। विवाह में पुत्र-पुत्री तथा अन्य सदस्यों की सहमति ली जाती थी। एक पति रखने की प्रथा थी, इस समय बहुविवाह एवं विधवा विवाह का भी उल्लेख किया गया है। परंतु बाल विवाह का प्रचलन नहीं था। इस समय कन्या का जन्म शुभ माना जाता था।</p>\r\n<h3 class=\"atech\" id=\"भोजन\">भोजन</h3>\r\n<p>पूर्व वैदिक काल में लोग शाकाहारी और मांसाहारी दोनों प्रकार के भोजन करते थे। दूध से बनी वस्तुओं का बड़ा महत्त्व था, वे लोग साग-सब्जियों के अलावा भेड़, बकरी, बैल आदि खाते थे, परंतु गाय को पवित्र माना जाता था। इस समय मदिरापान का भी लोग सेवन करते थे, हालांकि ऋग्वेद में मदिरापान को अपराध प्रेरक बताया गया है। </p>\r\n<h3 class=\"atech\" id=\"मनोरंजन\">मनोरंजन</h3>\r\n<p>पूर्व वैदिक काल के लोक मनोरंजन के शौकीन थे। उनके मनोरंजन के अनेक साधन थे, घुड़दौड़ा, जुआ, शिकार, मछली पकड़ना, कुश्ती और नृत्य संगीत आदि मनोरंजन का प्रमुख साधन था।</p>\r\n<h3 class=\"atech\" id=\"शिक्षा\">शिक्षा</h3>\r\n<p>पूर्व वैदिक काल में स्त्री-पुरुष दोनों को सामान्य शिक्षा का अधिकार था। इन लोगों को औषधियों का अच्छा ज्ञान था, ऋग्वेद में विभिन्न प्रकार के औषधियों के बारे में बताया गया है। यह मुख्यतः जड़ी-बूटियों के द्वारा बनाए करते थे।</p>\r\n<h2 id=\"निष्कर्ष\">निष्कर्ष</h2>\r\n<p>इस प्रकार उपरोक्त अध्ययन से हम पाते हैं कि ऋग्वेद काल में समाज सहयोग व सहभागिता पर आधारित थी। जिसमें बुजुर्ग व्यक्ति को परिवार का मुखिया माना जाता था। झगड़े का निपटारा गांव का मुखिया या राजा करता था। </p>',268,'2024-10-16 03:13:23','2024-10-16 03:52:28','','Publish',0,'open',27,4),('अखनाटन की उपलब्धियों का संक्षिप्त विवरण','brief-description-of-akhenaten\'s-achievements',2,'<p>अखनाटन, जिसे अमेनहोटेप IV भी कहा जाता है, प्राचीन मिस्र के 18वें राजवंश के एक फिरौन थे। उनका शासनकाल (1353-1336 ईसा पूर्व) महत्वपूर्ण धार्मिक और सांस्कृतिक परिवर्तनों के लिए जाना जाता है। अखनाटन की सबसे प्रमुख उपलब्धि उनका धार्मिक सुधार था। उन्होंने पारंपरिक बहुदेववादी धर्म को बदलकर एकेश्वरवादी धर्म की स्थापना की, जिसमें केवल सूर्य देवता \"अतेन\" की पूजा की जाती थी। इस नए धर्म को \"अतेनवाद\" कहा गया। इस धार्मिक क्रांति ने मिस्र के समाज और संस्कृति पर गहरा प्रभाव डाला।</p>\r\n<p>अखनाटन ने अपने नाम में परिवर्तन कर \"अखनाटन\" (अतेन के लिए प्रभावी) कर लिया और नई राजधानी \"अखेत-अतेन\" (वर्तमान अमार्ना) की स्थापना की। अमार्ना कला और स्थापत्य में भी क्रांति हुई, जिसमें अधिक यथार्थवादी और प्राकृतिक चित्रण को प्राथमिकता दी गई।</p>\r\n<p>हालांकि, उनके धार्मिक सुधारों का विरोध भी हुआ और उनकी मृत्यु के बाद पारंपरिक धर्म और राजधानी को फिर से स्थापित किया गया। अखनाटन की उपलब्धियों का मूल्यांकन इस दृष्टि से महत्वपूर्ण है कि उन्होंने धार्मिक और सांस्कृतिक संरचना को चुनौती दी और एक नए दृष्टिकोण को प्रस्तुत किया, जिसका प्रभाव उनके उत्तराधिकारियों और मिस्र की दीर्घकालिक धार्मिक धारणाओं पर पड़ा।</p>',17,'2024-10-16 03:13:23','2024-10-16 03:55:22','','Publish',0,'open',34,5),('असीरियन साम्राज्य के पतन के क्या कारण थे','what-caused-the-fall-of-the-assyrian-empire',2,'<p>मेसोपोटामिया की सभ्यता का अंतिम स्वरूप असीरियन साम्राज्य था। दरअसल, असुरबनिपाल असीरियाई साम्राज्य का सबसे शक्तिशाली राजा था, किंतु उसकी मृत्यु के कुछ वर्षों के भीतर ही असीरियाई साम्राज्य बिखर गया। इसके पतन के लिए अनेक कारक उत्तरदायी थे-</p>\r\n<h2 id=\"असीरियन_साम्राज्य_के_पतन_के_कारण\">असीरियन साम्राज्य के पतन के कारण</h2>\r\n<h3 class=\"atech\" id=\"असीरियन_क्रूरता\">असीरियन क्रूरता</h3>\r\n<p>असीरियन जाति के लोग अर्धसभ्य थे तथा उसके शासक क्रूरता पूर्वक व्यवहार करते थे। विजित राज्यों को भयभीत रखने के लिए उन्होंने उन पर बहुत अत्याचार किए। इन सबका प्रतिकूल प्रभाव हुआ, यही कारण था कि विद्रोह कम नहीं हुए। असीरियनो के अत्याचार बढ़ने के साथ-साथ विद्रोहियों की संख्या में भी वृद्धि होती चली गई।</p>\r\n<h3 class=\"atech\" id=\"दोषपूर्ण_प्रांतीय_व्यवस्था\">दोषपूर्ण प्रांतीय व्यवस्था</h3>\r\n<p>असीरियन साम्राज्य की दुर्बलता का प्रमुख कारण दोषपूर्ण प्रांतीय व्यवस्था थी। साम्राज्य की प्रारंभिक अवस्था में सम्राटो ने विजित देशों को प्रांतों के रूप में संगठित करने का प्रयास नहीं किया। वे केवल लूटपाट के द्वारा ही संतुष्ट हो जाते थे, उनके लौटते ही यह विजित राज्य पुनः विद्रोह कर देते थे। इस ओर सर्वप्रथम ध्यान तिगलक पिलेसर तृतीय ने दिया। उसने कतिपय राज्यों को प्रांतों के रूप में परिवर्तित कर दिया किंतु इसके सकारात्मक परिणाम नहीं हुए क्योंकि तिगलक के उत्तराधिकारियों ने इन प्रांतों के साथ उचित व्यवहार नहीं किया। उन्होंने प्रांतों से करो व सैनिक सेवा के रूप में राज्य के अंश को बहुत बढ़ा दिया था। इसके अतिरिक्त विजित राज्यों की आबादी को दूसरे प्रदेशों में बसा दिया। इसके परिणामस्वरूप विजित राज्य की जनता के हृदय निराशा एवं विद्रोह की भावना से परिपूर्ण हो गए।</p>\r\n<h3 class=\"atech\" id=\"दोषपूर्ण_आर्थिक_व्यवस्था\">दोषपूर्ण आर्थिक व्यवस्था</h3>\r\n<p>असीरियन आर्थिक जीवन का आधार व्यापार न होकर कृषि था। किंतु निरंतर होने वाले युद्धो का कृषि पर प्रतिकूल प्रभाव पड़ा। सैनिकों की संख्या बढ़ने के साथ-साथ कृषकों की संख्या घटती चली। गयी धीरे-धीरे कृषि का पूर्णतः पतन हो गया और असीरियन राज्य के आर्थिक जीवन का आधार लूट-खसोट रह गया। यह आधार तभी तक कायम रह सकता था जब तक की सेनाएं युद्धरत रहती और विजय प्राप्त करती रहती। एक बार की पराजय से ही आर्थिक व्यवस्था छिन्न-भिन्न हो सकती थी।</p>\r\n<h3 class=\"atech\" id=\"दलीय_संघर्ष\">दलीय संघर्ष</h3>\r\n<p>असीरियन के प्रारंभ से ही दो दल रहे थे सैनिक और धार्मिक दल। प्रत्येक सम्राट के लिए दोनों दलों का सहयोग प्राप्त करना आवश्यक होता था क्योंकि सैनिक दल की सहायता के बिना साम्राज्य की स्थापना नहीं की जा सकती थी तथा धार्मिक दल उस साम्राज्य को स्थायित्व प्रदान करने में सहायक होता था, किंतु दोनों दलों में सामंजस्य स्थापित करना दुष्कर कार्य था। इन दोनों दलों में निरंतर संघर्ष होते रहते थे, जिससे निपटने के लिए सम्राट की काफी शक्ति व्यय होने लगी।</p>\r\n<h3 class=\"atech\" id=\"दैवीय_प्रकोप\">दैवीय प्रकोप</h3>\r\n<p>असीरिया के पतन के लिए दैवीय प्रकोप भी एक प्रमुख कारण था। असीरिया ने दो वर्ष तक निनवेह का घेरा सहन किया किंतु दजला-फरात नदी में आयी बाढ से निनवेह की दीवार तोड़ दी। परिणाम स्वरूप ईरानियों ने निनवेह में प्रवेश किया और असुरबनिपाल के भव्यराज प्रसाद, गौरवशाली मंदिर, असुरबनिपाल का पुस्तकालय सभी को नष्ट कर दिया। नागरिको का सामूहिक वध कर दिया गया। इस प्रकार निनवेह का पूर्णरूपेण विध्वंस कर दिया गया।</p>\r\n<h3 class=\"atech\" id=\"अन्य_कारण\">अन्य कारण</h3>\r\n<p></p>\r\n<ul>\r\n<li><p>प्रांतीय शासक अधिकांशत: राजपरिवार के होते थे अतः उनका पुजारी वर्ग से सदैव संघर्ष होता रहता था।</p></li>\r\n<li><p>असीरियन सम्राटो की आंतरिक व्यवस्था भी दोषपूर्ण थी।</p></li>\r\n<li><p>असीरिया के पतन के लिए ईरान, ईलम व बाबुल के राज्यों भी उत्तरदाई थे। ये शक्तियां उस समय संयुक्त हो गई जबकि असीरियन सम्राट युद्ध त्याग कर चूके थे।</p></li>\r\n<li><p>असीरिया का प्रधान सेनापति नवीपलेखर इरानी सेना से मिल गया था जिसके कारण समस्त असीरियन सेना भी ईरानियों की ओर हो गई थी।</p></li>\r\n</ul>\r\n<p>इसप्रकार हम देखते है की असीरियनो को अपनी अमानुषिक नीति का दुखद परिणाम भुगतना पड़ा। असीरियनो जिस क्रूरता व अत्याचार का व्यवहार अपने विजित राज्यों के साथ किया था, बिल्कुल वैसा ही व्यवहार असीरिया के साथ किया गया। राजधानी निनवेह को पूर्णतः ध्वस्त कर दिया गया। भयंकर प्रतिशोध की भावना से प्रेरित होकर कैल्डियनों एवं मीडो ने ना केवल असीरियन नगरों को वरन् असीरियन सभ्यता को ही पूर्णतया नष्ट भ्रष्ट कर दिया।</p>',27,'2024-10-16 03:13:23','2024-10-16 03:58:22','','Publish',0,'open',34,6),('अखनाटन की उपलब्धियों का मूल्यांकन करें','evaluate-the-achievements-of-akhenaten',2,'<p>अमेनहोटेप III की मृत्यु के बाद मिस्र की गद्दी पर उसका पुत्र अमेनहोटेप चतुर्थ बैठा, जो आगे चलकर विश्व इतिहास में अखनाटन के नाम से प्रसिद्ध हुआ। वह बचपन से ही धार्मिक प्रवृति का था, जो उसके शासन कार्यों से स्पष्ट परिलक्षित होता है। अखनाटन के पिता कला प्रेमी तथा विलासी प्रवृत्ति के व्यक्ति थे परंतु उसकी माता व्यवहार कुशल चतुर महिला थी। अखनाटन पर बाल्यावस्था से ही माता-पिता के चारित्रिक गुणों का गहरा प्रभाव था।</p>\r\n<p>अखनाटन ने अपने राज्यारोहण के तुरंत बाद <strong>एटन देवता</strong> को विश्व का सर्वोच्च देवता घोषित किया और मिस्र धर्म में क्रांतिकारी परिवर्तन लाने के कारण उसका नाम अखनाटन पड़ा। अमेनहोटेप III की मृत्यु के बाद मिस्र को बाह्य एवं आंतरिक कई समस्याओं का सामना करना पड़ा। इस कठिन परिस्थिति का सामना करने के लिए एक शक्तिशाली और व्यावहारिक शासक की आवश्यकता थी जो अराजक स्थितियों को अपने नियंत्रण में ला सके तथा क्षेत्रीय शासकों को अपने अधीन कर सके। लेकिन मिस्र को ऐसा शासक मिला जो आदर्शवादी था। वह धर्म में ज्यादा रुचि रखता था तथा अपने शासन को धर्म के अनुसार चलाना चाहता था।</p>\r\n<p>इस प्रकार अखनाटन ने अपने आदर्शवाद के कारण मिस्र को भयानक खतरे में डाल दिया। जब वह गद्दी पर बैठा तब उसकी उम्र बहुत कम थी, किंतु इस उम्र में भी उसने ज्ञान और दर्शन के क्षेत्र में काफी ख्याति प्राप्त कर ली थी लेकिन राजनीतिक क्षेत्र में वह व्यावहारिक नहीं था। वह आदर्शों और सपनों की दुनिया में खोया रहता था, जबकि मिस्र को इस समय गहन अंधकार की बेला में शासन की अराजक स्थिति को समाप्त कर सुव्यवस्थित शासन की आवश्यकता थी। अतः परिस्थिति के बिल्कुल विपरीत मिस्र को ऐसा फराओ मिला जो तलवार की जगह धर्म की कहानी सुनाया करता था। वास्तव में मिस्र को इस समय चतुरमस तृतीय जैसे शासकों की आवश्यकता थी, जो अपनी कठोर शासन व्यवस्था से मिस्र की चतुर्दिक विकास कर सके, लेकिन विडंबना यह रही की अखनाटन जो इस समय गद्दी पर बैठा था वह धार्मिक सुधारों के क्षेत्र में निपुण था परंतु साम्राज्य की दूसरी समस्या को समझने में असफल रहा था। दूसरे शब्दों में अखनाटन केवल सैद्धांतिक समस्याओं को समझता था, लेकिन उसमें व्यावहारिक राजनीतिज्ञता का अभाव था। इसलिए उसके समय में मिस्र के साम्राज्य में कई तरह के विद्रोह हुए और अखनाटन को परेशानियों का सामना करना पड़ा।</p>\r\n<p>वास्तव में अखनाटन कला प्रेमी और विलासी पिता का पुत्र था। उसकी माँ धर्म परायण और व्यवहार कुशल महिला थी। अखनाटन का बाल्यकाल की सेवा हेतु अनेक दसियों की नियुक्ति की गई थी जो, सदैव अखनाटन की सेवा में लगी रहती थी। स्त्रियों से अधिक प्रभाव में आने के कारण इसकी व्यवहारिक बुद्धिमता कुंठित हो गई थी। यूं तो एक प्रभावशाली व्यक्ति था लेकिन साम्राज्य की वास्तविक समस्याओं की ओर ध्यान न देकर उसने धार्मिक क्षेत्र में ज्यादा दिलचस्पी दिखाएं।</p>\r\n<p>सबसे महत्वपूर्ण बात यह है यह की साम्राज्य में विकेंद्रीकरण की प्रवृत्ति बढ़ रही थी, लेकिन अखनाटन में विद्रोह को दबाने के लिए सेना के संगठन की और कोई दिलचस्पी नहीं ली। उसने मिस्र में धर्म और दर्शन में मौलिक परिवर्तन लाने की कोशिश की और अपने विचारों और सिद्धांतों का प्रतिपादन किया। इस कारण उस समय मिस्र के शासकों में एक विशेष स्थान प्राप्त कर लिया जो उसकी सबसे बड़ी उपलब्धि थी।</p>\r\n<p>अपने धार्मिक और दार्शनिक विचारों के कारण व प्राचीन विश्व के इतिहास में पहला धार्मिक व्यक्ति माना जाता है। उसेने धर्म में आमूल परिवर्तन किए <strong>एमन</strong> देवता उस समय के पारंपरिक देवता थे। पांच वर्षों तक उसने <strong>एमन</strong> देवता की पूजा की, लेकिन शासन के छठे वर्ष जब उसकी उम्र 15 वर्ष की थी, तब उसने खुलेआम अपने आप को विधाता घोषित किया और <strong>एटन देवता</strong> को साम्राज्य का सर्वश्रेष्ठ देवता घोषित किया। <strong>एटन</strong> सूर्य देवता का एक रूप था और उसकी अराधना से अखनाटन के द्वारा मिस्र धर्म में क्रान्ति की शुरुआत हुई। अखनाटन ने <strong>एटन देवता</strong> के अतिरिक्त अन्य देवताओं की पूजा बंद करवा दी। जिससे मिस्र की प्रजा नाखुश तो हुई ही, साथ ही साथ उसके क्रांतिकारी विचारों का प्रभाव मिस्र की जनता पर अच्छा नहीं हुआ। अखनाटन ने यह घोषित किया की मिस्र का सारा धार्मिक संगठन गलत था। <strong>एटन देवता</strong> ही वास्तविक था। उसने यह प्रचार करना शुरू किया <strong>एटन देवता</strong> अपने आप को सूर्य के चक्र द्वारा प्रकट करता हैं जिसे बराबर देखा जा सकता है।</p>\r\n<p>अखनाटन द्वारा प्रतिपादित नये धर्म की झलक हमें <strong>एटन देवता</strong> के प्रति रचित प्रार्थनाओं की रचना से मिलती है।  उन प्रार्थनाओं की रचना राजा की व्यक्तिगत पूजा के लिये की गयी थी। इन प्रार्थनाओं की रचना स्वयं अखनाटन ने की थी इन रचनाओं को उसकी मृत्यु के बाद उसकी कब्र की दीवार पर अंकित कर दिया गया था। उसने जीतने भी स्मारक बनवाये उन सभी पर अपनी धार्मिक प्रार्थनाओं को अंकित करवाया। उसकी मुख्य प्रार्थना थी- <i>\"हे <strong>एटन देवता</strong> तुम्ही ने स्त्रियों से मनुष्य को पैदा किया है। तुम्ही बच्चों की माँ के शरीर में जीवनदान करते हो। तुम्ही माँ के गर्भ से बच्चों को सात्वना देते हो। इस प्रकार तुम गर्भ में भी धाय काम करते हो।\"</i></p>\r\n<p>इसमें कोई संदेह नहीं कि अखनाटन की प्रार्थनाएँ उच्च धार्मिक कीर्तन और विश्व बंधुता के आदर्श उपस्थित करती है। जो कोई इन प्रार्थनाओं को सुनता था, वह इस युवा शासक की उदारता और उच्च कल्पना से प्रभावित हुए बिना नहीं रह सकता था। अखनाटन विश्वास करता था कि <strong>एटन देवता</strong> सभी प्राणियों के माता-पिता हैं तथा वे सभी से प्रेम करते हैं। इस प्रकार वह विश्व बंधुत्व के सिद्धांत का प्रथम प्रचारक था। इस दृष्टिकोण से अखनाटन मानव इतिहास का पहला पैगम्बर माना जा सकता है। इसका व्यक्तिगत जीवन भी आदर्शनिय था। इस प्रकार उसने अपने आदर्श को अपने जीवन में कार्यान्वित करने का प्रयत्न किया तथा अपने समस्त जीवन को एक नया धर्म के प्रचार में लगा दिया।</p>\r\n<p>अखनाटन की विशेषताओं बावजूद भी अनेक इतिहासकारों ने उसकी आलोचना की है। उसने अपने समस्त जीवन को एक को नए धर्म के प्रचार में लगा दिया तथा राज्य की अन्य समस्याओं की ओर ध्यान नहीं दिया। धीरे-धीरे मिस्र देश की कठिनाई बढ़ती गई और उसके शत्रु देश उसपर आक्रमण की तैयारी करने लगे। अखनाटन युद्ध और विजय से घृणा करता था। इसी कारण उसने अपने शत्रुओं के आक्रामक नीतियों के बावजूद भी उन पर आक्रमण नहीं किया। यह उसकी महान भूल थी। इस प्रकार जिस राज्य की स्थापना उसके पूर्वजों ने की व टुकड़ों में विभाजित होना प्रारंभ हो गया। इसलिए उसके सिद्धांत और उसके सारा जीवन एक शासक के रूप में असफल रहा। उसकी मृत्यु के बाद सदियों का पुराना धर्म पुनः प्रचलित हुआ तथा अखनाटन द्वारा स्थापित नया शहर अखनाटन पूरी तरह से विरान हो गया। पुनः <strong>एटन</strong> के स्थान पर <strong>एमन</strong> देवता की पूजा शुरू हो गई। इस तरह अखनाटन के द्वारा स्थापित नया धर्म बालू की बनी हुई दीवार सिद्ध हुई।</p>\r\n<h2 class=\"atech\">निष्कर्ष</h2>\r\n<p>इस प्रकार उपरोक्त अध्ययन से हम इस निष्कर्ष पर पहुँचते हैं कि अखनाटन का संपूर्ण जीवन एवं उसकी उपलब्धियां धर्म के इर्द-गिर्द घूमती रही है। उसने अपने संपूर्ण शासन में अन्य क्षेत्रों पर बिल्कुल ध्यान नहीं दिया केवल धर्म को ही आधार मानकर उसने मिस्र पर शासन किया। इस कारण कई इतिहासकारों ने अखनाटन की तीव्र आलोचना की है परंतु इन आलोचनाओं के बावजूद अखनाटन विश्व इतिहास में एक महत्वपूर्ण स्थान रखता है। हम अखनाटन की तुलना भारत के अशोक महान तथा सम्राट अकबर से भी कर सकते हैं। जहाँ अशोक ने बौद्ध धर्म के मूल स्वरूप को अपनाकर अपने धर्म का प्रचार किया था, जिसके कारण उसके धर्म की ख्याति विश्व में फैली। वहीं दूसरी ओर सम्राट अकबर ने भी दिन-ए-इलाही धर्म की स्थापना की थी परंतु वह धर्म केवल राजधर्म बनकर रह गया था। इसमें कोई संदेह नहीं कि अपने धार्मिक सिद्धांतों और आदर्शों के कारण वह बहुत साहसी शासक और विचारक था। विश्व का वह पहला धर्म प्रचारक था जिसने मानव जाति की उस अवस्था में इतने ऊंचे धार्मिक आदर्शों की कल्पना की। यदि वह असफल हुआ तो इसका कारण यह है कि वह अपने समय से काफी आगे था। यदि उसका जन्म कुछ शताब्दियों के पश्चात होता तो निशानदेह वह दुनिया के बड़े पैगम्बरों में अग्रिम रहता।</p>',41,'2024-10-16 03:13:23','2024-10-16 04:00:25','','Publish',0,'open',34,7),('Privacy Policy','privacy-policy',0,'<p>हम समझते हैं कि ऑनलाइन गोपनीयता हमारे उपयोगकर्ताओं के लिए अत्यंत महत्वपूर्ण है, खासकर जब वे हमारी सेवाओं का उपयोग कर रहे हों।</p>\r\n\r\n<p>यह गोपनीयता नीति उन उपयोगकर्ताओं (\"विज़िटर\") पर लागू होती है जो बिना पंजीकरण के साइट का उपयोग करते हैं, और उन उपयोगकर्ताओं पर भी जो साइट पर पंजीकरण करते हैं एवं {{appname}} द्वारा प्रदान की जा रही सेवाओं (\"अधिकृत ग्राहक\") का उपयोग करते हैं।</p>\r\n\r\n<h2>व्यक्तिगत रूप से पहचान योग्य जानकारी</h2>\r\n<p>इसमें वह सभी जानकारी शामिल होती है जिससे किसी व्यक्ति की पहचान की जा सके — जैसे नाम, पता, फोन नंबर, ईमेल, वित्तीय विवरण आदि। इसमें गुमनाम जानकारी या वह जनसांख्यिकीय जानकारी शामिल नहीं है जिससे व्यक्ति की पहचान नहीं हो सकती।</p>\r\n\r\n<h2>एकत्र की जाने वाली जानकारी</h2>\r\n<p>हम सभी विज़िटर से बुनियादी प्रोफ़ाइल जानकारी एकत्र कर सकते हैं। अधिकृत ग्राहकों से हम अतिरिक्त जानकारी जैसे नाम, व्यवसाय का प्रकार, ईमेल, फोन नंबर और अन्य प्रासंगिक जानकारी एकत्र करते हैं।</p>\r\n\r\n<h2>कौन जानकारी एकत्र करता है?</h2>\r\n<p>हमारे साथ जुड़े तृतीय-पक्ष सेवा प्रदाता (जैसे पेमेंट गेटवे, बैंक आदि) भी जानकारी एकत्र कर सकते हैं। {{appname}} यह नियंत्रित नहीं करता कि वे जानकारी का उपयोग कैसे करते हैं, लेकिन हम उनसे पारदर्शिता की अपेक्षा करते हैं।</p>\r\n\r\n<h2>जानकारी का उपयोग कैसे होता है?</h2>\r\n<p>हम जानकारी का उपयोग सेवाओं को वैयक्तिकृत करने, उपयोगकर्ता अनुभव सुधारने और संचार के लिए करते हैं। हम उपयोगकर्ताओं को ईमेल या नोटिफिकेशन द्वारा अपडेट्स, ऑफ़र, या सेवा संबंधी सूचनाएँ भेज सकते हैं।</p>\r\n\r\n<h2>जानकारी किसके साथ साझा की जा सकती है?</h2>\r\n<p>अधिकृत ग्राहकों की जानकारी अन्य ग्राहकों, संबद्ध एजेंसियों और तृतीय-पक्ष विक्रेताओं के साथ साझा की जा सकती है। उपयोगकर्ता चाहें तो इस साझा प्रक्रिया से बाहर (opt-out) हो सकते हैं।</p>\r\n\r\n<h2>जानकारी की सुरक्षा</h2>\r\n<p>{{appname}} पर एकत्र की गई जानकारी सुरक्षित सर्वर में संग्रहित की जाती है और केवल अनुमत कर्मचारियों द्वारा एक्सेस की जा सकती है। संवेदनशील जानकारी एन्क्रिप्शन प्रोटोकॉल द्वारा संरक्षित होती है। हालांकि, कोई भी डिजिटल सिस्टम 100% सुरक्षित नहीं होता, इसलिए हम किसी डेटा उल्लंघन की पूर्ण गारंटी नहीं दे सकते।</p>\r\n\r\n<h2>कुकीज़ का उपयोग</h2>\r\n<p>हम उपयोगकर्ता की पसंद और सत्र प्रबंधन के लिए कुकीज़ का उपयोग करते हैं। उदाहरण के लिए, लॉगिन के बाद निष्क्रियता के आधार पर ऑटोमेटिक लॉगआउट।</p>\r\n\r\n<h2>सेवा प्रदाताओं की जानकारी तक पहुँच</h2>\r\n<p>{{appname}} ने कुछ सेवा प्रदाताओं से साझेदारी की हुई है जो आवश्यकता अनुसार जानकारी तक पहुँच सकते हैं। हमारी गोपनीयता नीति उनके उपयोग पर लागू नहीं होती। किसी भी कानूनी आदेश या सुरक्षा आवश्यकता के अंतर्गत हम जानकारी साझा कर सकते हैं।</p>\r\n\r\n<h2>उपयोगकर्ताओं के विकल्प</h2>\r\n<p>उपयोगकर्ता {{appmail}} पर ईमेल करके या हमारे फॉर्म का उपयोग कर जानकारी साझा न करने का अनुरोध कर सकते हैं।</p>\r\n\r\n<h2>गोपनीयता नीति में परिवर्तन</h2>\r\n<p>हम समय-समय पर इस नीति में बदलाव कर सकते हैं और इसका नोटिस साइट पर प्रकाशित किया जाएगा। यदि कोई बड़ा बदलाव होगा, तो हम सीधे संबंधित उपयोगकर्ता से संपर्क करेंगे।</p>\r\n\r\n<p><strong>अंतिम बार अपडेट किया गया:</strong> अगस्त 08, 2025</p>\r\n',84,'2024-10-16 05:07:44','2024-10-16 05:10:08','','Publish',0,'open',0,8),('Disclaimer','disclaimer',0,'<p>नमस्ते दोस्तों, आपका <a href=\"/\">{{appname}}</a> पर एक बार फिर से स्वागत है। यह हमारा Disclaimer पेज है, कृपया इसे ध्यानपूर्वक शुरू से अंत तक पढ़ें। इस पृष्ठ में उल्लिखित शर्तें हमारे प्लेटफॉर्म के सभी उपयोगकर्ताओं पर लागू होती हैं।</p>\r\n\r\n<h2>सामग्री और जानकारी</h2>\r\n<p><a href=\"/\">{{appname}}</a> पर प्रकाशित की जाने वाली सभी सामग्री हमारे स्वयं के अनुभव, ज्ञान और अनुसंधान पर आधारित होती है। हम कॉपी की गई सामग्री का समर्थन नहीं करते हैं और न ही ऐसी सामग्री साझा करते हैं। हमारी कोशिश होती है कि सभी जानकारी उपयोगकर्ताओं के लिए उपयोगी और सटीक हो।</p>\r\n\r\n<h2>उपयोग की शर्तें</h2>\r\n<p>हमारी वेबसाइट पर दी गई जानकारी का उपयोग आप अपने विवेक से करें। यदि कोई उपयोगकर्ता हमारी सामग्री का दुरुपयोग करता है या किसी प्रकार की गैरकानूनी गतिविधि में इसका उपयोग करता है, तो उसके लिए केवल उपयोगकर्ता स्वयं जिम्मेदार होंगे।</p>\r\n\r\n<h2>दायित्व की सीमा</h2>\r\n<p>यदि किसी भी जानकारी के उपयोग से किसी व्यक्ति, संस्था या तृतीय पक्ष को कोई नुकसान, परेशानी या विवाद उत्पन्न होता है, तो <a href=\"/\">{{appname}}</a> उसके लिए उत्तरदायी नहीं होगा।</p>\r\n\r\n<h2>व्यवहार और टिप्पणी नीति</h2>\r\n<p>हम सभी उपयोगकर्ताओं से उम्मीद करते हैं कि वे प्लेटफॉर्म का सम्मानपूर्वक और उचित तरीके से उपयोग करेंगे। अपमानजनक या अनुचित टिप्पणी, स्पैम, या अवैध गतिविधियों के संदर्भ में किए गए किसी भी कार्य के लिए हम संबंधित उपयोगकर्ता की पहुँच को सीमित या प्रतिबंधित कर सकते हैं।</p>\r\n\r\n<h2>संपर्क करें</h2>\r\n<p>यदि आपको हमारे किसी भी कंटेंट से संबंधित कोई समस्या है या आप किसी स्पष्टीकरण की आवश्यकता महसूस करते हैं, तो आप हमारी <a href=\"/about\">About</a> या <a href=\"/help/contact\">Contact</a> पेज के माध्यम से हमसे संपर्क कर सकते हैं। हम आपकी समस्याओं को सुलझाने का प्रयास करेंगे।</p>\r\n\r\n<h2>सहमति</h2>\r\n<p>इस वेबसाइट या एप्लिकेशन का उपयोग करके, आप हमारे Disclaimer से सहमति जताते हैं और इसकी सभी शर्तों को स्वीकार करते हैं।</p>\r\n\r\n<p><strong>अंतिम बार अपडेट किया गया:</strong> अगस्त 08, 2025</p>\r\n',51,'2024-10-16 05:07:44','2024-10-16 05:11:11','','Publish',0,'open',0,9),('Terms and Conditions','terms-and-conditions',0,'<h2>परिचय</h2>\r\n<p>इस पेज पर लिखे गए नियम और शर्तें {{appname}} एप्लिकेशन के आपके उपयोग को नियंत्रित करते हैं। ये शर्तें पूरी तरह से लागू होती हैं और {{appname}} के आपके उपयोग को प्रभावित करती हैं। इस ऐप का उपयोग करके, आप यहां दी गई सभी शर्तों को स्वीकार करते हैं। यदि आप इनमें से किसी भी शर्त से सहमत नहीं हैं, तो कृपया ऐप का उपयोग न करें।</p>\r\n<p>18 वर्ष से कम आयु के उपयोगकर्ताओं को भी इस एप्लिकेशन का उपयोग करने की अनुमति है।</p>\r\n\r\n<h2>बौद्धिक संपदा अधिकार</h2>\r\n<p>आपके द्वारा स्वामित्व में रखी गई सामग्री को छोड़कर, {{appname}} और/या इसके लाइसेंसधारकों के पास इस ऐप में उपलब्ध सभी बौद्धिक संपदा अधिकार हैं। इस ऐप की सामग्री को देखने के लिए आपको एक सीमित लाइसेंस दिया जाता है।</p>\r\n\r\n<h2>प्रतिबंध</h2>\r\n<p>आप निम्नलिखित कार्यों को करने से स्पष्ट रूप से प्रतिबंधित हैं:</p>\r\n<ul>\r\n    <li>ऐप की सामग्री को किसी अन्य मीडिया में प्रकाशित करना,</li>\r\n    <li>सामग्री को बेचना, लाइसेंस देना या व्यावसायिक लाभ के लिए उपयोग करना,</li>\r\n    <li>सार्वजनिक रूप से सामग्री को दिखाना या प्रसारित करना,</li>\r\n    <li>ऐसा कोई कार्य करना जिससे ऐप को क्षति पहुँच सकती है,</li>\r\n    <li>ऐसा कोई प्रयास करना जो उपयोगकर्ताओं की पहुँच को बाधित करे,</li>\r\n    <li>गैरकानूनी या नुकसानदायक उद्देश्यों से ऐप का उपयोग करना,</li>\r\n    <li>डेटा माइनिंग, डेटा हार्वेस्टिंग, डेटा एक्सट्रैक्शन करना,</li>\r\n    <li>बिना अनुमति के किसी भी प्रकार का प्रचार या विज्ञापन करना।</li>\r\n</ul>\r\n\r\n<p>{{appname}} कुछ विशेष फ़ीचर्स या सेक्शन तक आपकी पहुँच को कभी भी प्रतिबंधित कर सकता है। लॉगिन की जानकारी गोपनीय रखना आपकी ज़िम्मेदारी है।</p>\r\n\r\n<h2>आपकी सामग्री</h2>\r\n<p>\"आपकी सामग्री\" से तात्पर्य है – कोई भी ऑडियो, वीडियो, टेक्स्ट, चित्र या फ़ाइल जिसे आप इस ऐप के ज़रिए साझा करते हैं। अपनी सामग्री साझा करके आप {{appname}} को यह अधिकार देते हैं कि वह इसे किसी भी मीडिया में उपयोग, प्रकाशित या वितरित कर सके। यह लाइसेंस गैर-अनन्य, विश्वव्यापी और उप-लाइसेंस योग्य होगा।</p>\r\n<p>आपकी सामग्री आपकी अपनी होनी चाहिए और किसी तीसरे पक्ष के अधिकारों का उल्लंघन नहीं करना चाहिए। {{appname}} को यह अधिकार है कि वह आपकी किसी भी सामग्री को किसी भी समय, बिना सूचना के, हटा सके।</p>\r\n\r\n<h2>कोई वारंटी नहीं</h2>\r\n<p>{{appname}} \"जैसा है\" के आधार पर उपलब्ध कराया जाता है, और इसमें किसी प्रकार की वारंटी नहीं दी जाती है। ऐप में दी गई जानकारी को पेशेवर सलाह के रूप में नहीं लिया जाना चाहिए।</p>\r\n\r\n<h2>दायित्व की सीमा</h2>\r\n<p>{{appname}} किसी भी अप्रत्यक्ष, आकस्मिक या विशेष हानि के लिए उत्तरदायी नहीं होगा जो इस ऐप के उपयोग से उत्पन्न हो सकती है।</p>\r\n\r\n<h2>क्षतिपूर्ति</h2>\r\n<p>यदि आप इन शर्तों का उल्लंघन करते हैं और उससे किसी प्रकार की क्षति होती है, तो आप {{appname}} को उसके खिलाफ पूरी तरह क्षतिपूर्ति करने के लिए बाध्य होंगे।</p>\r\n\r\n<h2>विभाजनीयता</h2>\r\n<p>यदि इन शर्तों का कोई भी भाग अमान्य या अवैध पाया जाता है, तो वह हिस्सा हटाया जा सकता है और बाकी शर्तें प्रभाव में बनी रहेंगी।</p>\r\n\r\n<h2>नियमों में परिवर्तन</h2>\r\n<p>{{appname}} को किसी भी समय इन शर्तों को संशोधित करने का अधिकार है। आपसे अपेक्षा की जाती है कि आप समय-समय पर इन्हें पढ़ते रहें।</p>\r\n\r\n<h2>अधिकारों का हस्तांतरण</h2>\r\n<p>{{appname}} अपने अधिकारों और दायित्वों को बिना किसी सूचना के ट्रांसफर कर सकता है। परंतु, आप ऐसा नहीं कर सकते।</p>\r\n\r\n<h2>पूर्ण समझौता</h2>\r\n<p>ये नियम और शर्तें {{appname}} और आपके बीच इस एप्लिकेशन के उपयोग के संबंध में पूर्ण समझौते का निर्माण करती हैं और इससे पहले की सभी समझौतों को रद्द करती हैं।</p>\r\n\r\n<h2>शासन कानून और अधिकार क्षेत्र</h2>\r\n<p>ये शर्तें उत्तराखंड राज्य के कानूनों के अंतर्गत आती हैं और किसी भी विवाद की स्थिति में उत्तराखंड के न्यायालयों का विशेष अधिकार क्षेत्र होगा।</p>\r\n\r\n<h2>अध्ययन सामग्री, लेख और प्रश्न पत्र अपलोड करना</h2>\r\n<p>आप हमें ईमेल या ऐप के ज़रिए अध्ययन सामग्री, प्रश्नपत्र या लेख भेज सकते हैं। यह प्रक्रिया एक तृतीय-पक्ष सेवा के माध्यम से हो सकती है। यदि किसी तीसरे पक्ष की सेवा से कोई हानि या समस्या होती है, तो {{appname}} इसके लिए जिम्मेदार नहीं होगा।</p>\r\n<p>आप जो भी सामग्री भेजते हैं, {{appname}} को उसे संपादित, प्रकाशित, पुनः उपयोग और यदि आवश्यक हो तो व्यावसायिक उपयोग का अधिकार प्राप्त होगा। हमारा उद्देश्य यह है कि अधिक से अधिक उपयोगकर्ताओं को शैक्षणिक सामग्री तक मुफ़्त या सुलभ पहुँच दी जा सके।</p>\r\n\r\n<p><strong>अंतिम बार अपडेट किया गया:</strong> जनवरी 04, 2023</p>\r\n',68,'2024-10-16 05:07:44','2024-10-16 05:11:59','','Publish',0,'open',0,10),('मध्य प्रदेश पर संक्षिप्त टिप्पणी','madhya-pradesh',2,'<h2>ऐतिहासिक पृष्ठभूमि</h2>\r\n<h3 class=\"atech\">प्राचीन काल</h3> <p>मध्य प्रदेश का इतिहास प्राचीन है और यहाँ पर चंदेल, परमार, गुप्त और मौर्य जैसे राजवंशों का शासन रहा है। राज्य में कई महत्वपूर्ण प्राचीन शहर और स्थल हैं, जैसे उज्जैन, जो प्राचीन समय में महत्वपूर्ण व्यापारिक और धार्मिक केंद्र था।</p>\r\n<h3 class=\"atech\">मध्यकाल</h3> <p>मध्य प्रदेश के विभिन्न क्षेत्रों पर मुस्लिम शासकों, मुगलों और बाद में मराठों का शासन रहा। इस काल के दौरान यहाँ कई महत्वपूर्ण किले और महल बनाए गए।</p>\r\n<h3 class=\"atech\">ब्रिटिश काल</h3> <p>ब्रिटिश शासन के दौरान मध्य प्रदेश कई रियासतों और प्रांतों में बंटा हुआ था। स्वतंत्रता के बाद इन रियासतों को मिलाकर मध्य प्रदेश राज्य का गठन किया गया।</p>\r\n<h2>भूगोल</h2>\r\n<p>मध्य प्रदेश भारत के केंद्र में स्थित है और इसकी सीमाएँ उत्तर में उत्तर प्रदेश, पूर्व में छत्तीसगढ़, दक्षिण में महाराष्ट्र, पश्चिम में गुजरात और राजस्थान से मिलती हैं। नर्मदा और ताप्ती जैसी प्रमुख नदियाँ यहाँ बहती हैं। सतपुड़ा और विंध्याचल पर्वत श्रृंखलाएँ राज्य की भूगोलिक विशेषताएँ हैं।</p>\r\n\r\n<h2>अर्थव्यवस्था</h2>\r\n<h3 class=\"atech\">कृषि</h3> <p>मध्य प्रदेश की अर्थव्यवस्था में कृषि का महत्वपूर्ण योगदान है। यहाँ गेहूँ, सोयाबीन, चना, मक्का और धान की खेती प्रमुख रूप से की जाती है। हाल के वर्षों में राज्य ने कृषि उत्पादन में महत्वपूर्ण प्रगति की है।</p>\r\n<h3 class=\"atech\">खनिज</h3> <p>मध्य प्रदेश खनिज संपदा में भी समृद्ध है। यहाँ कोयला, चूना पत्थर, बॉक्साइट और डायमंड के भंडार हैं।</p>\r\n<h3 class=\"atech\">उद्योग</h3> <p>राज्य में ऑटोमोबाइल, सूचना प्रौद्योगिकी, और कपड़ा उद्योग का भी विकास हो रहा है। इंदौर और भोपाल राज्य के प्रमुख औद्योगिक केंद्र हैं।</p>\r\n<h2>सामाजिक और सांस्कृतिक जीवन</h2>\r\n<p>मध्य प्रदेश की संस्कृति विविध और समृद्ध है। यहाँ के लोक नृत्य (जैसे भगोरिया और नृत्यांगना), लोक संगीत, और हस्तशिल्प (जैसे चंदेरी और महेश्वरी साड़ी) प्रसिद्ध हैं। राज्य में कई महत्वपूर्ण धार्मिक और सांस्कृतिक त्योहार मनाए जाते हैं, जैसे कुंभ मेला, तीज, दिवाली, और होली।</p>\r\n\r\n<h2>प्रमुख पर्यटन स्थल</h2>\r\n<h3 class=\"atech\">खजुराहो</h3> <p>खजुराहो अपने प्राचीन मंदिरों और अद्वितीय वास्तुकला के लिए विश्व प्रसिद्ध है। यह यूनेस्को विश्व धरोहर स्थल है।</p>\r\n<h3 class=\"atech\">सांची</h3> <p>सांची का स्तूप बौद्ध धर्म के महत्वपूर्ण स्थलों में से एक है और यह भी यूनेस्को विश्व धरोहर स्थल है। कंचनगंगा राष्ट्रीय उद्यान: यह पार्क अपनी जैव विविधता और वन्यजीवों के लिए प्रसिद्ध है।</p>\r\n<h3 class=\"atech\">कांची</h3> <p>यह एक ऐतिहासिक स्थल है जहाँ कई प्राचीन मंदिर और स्मारक हैं।</p>\r\n<h3 class=\"atech\">उज्जैन</h3> <p>यह एक प्राचीन शहर है और हिन्दू धर्म के महत्वपूर्ण तीर्थ स्थलों में से एक है। यहाँ का महाकालेश्वर मंदिर प्रसिद्ध है।</p>\r\n<h2>शिक्षा</h2>\r\n<p>मध्य प्रदेश में शिक्षा के क्षेत्र में भी प्रगति हो रही है। यहाँ कई प्रतिष्ठित शिक्षण संस्थान हैं, जैसे भारतीय प्रौद्योगिकी संस्थान (आईआईटी), भारतीय प्रबंधन संस्थान (आईआईएम), और महात्मा गांधी चित्रकूट ग्रामोदय विश्वविद्यालय।</p>\r\n\r\n<h2>चुनौतियाँ</h2>\r\n<p>मध्य प्रदेश को भी कई चुनौतियों का सामना करना पड़ता है, जैसे कि गरीबी, अशिक्षा, स्वास्थ्य सेवाओं की कमी, और जल संकट। राज्य सरकार इन चुनौतियों का समाधान करने के लिए विभिन्न योजनाएँ और नीतियाँ लागू कर रही है।</p>\r\n\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>मध्य प्रदेश, जिसे \"भारत का हृदय\" कहा जाता है, अपनी ऐतिहासिक धरोहर, सांस्कृतिक विविधता, और प्राकृतिक सौंदर्य के लिए जाना जाता है। यहाँ की समृद्ध परंपराएँ, कला, और विरासत इसे विशिष्ट बनाती हैं। साथ ही, राज्य में हो रहे आर्थिक और शैक्षिक विकास, और प्राकृतिक संसाधनों का समृद्ध भंडार इसे एक महत्वपूर्ण राज्य बनाते हैं। राज्य की जनता की मेहनत और सरकार की नीतियों से भविष्य में और भी अधिक प्रगति की उम्मीद की जा सकती है।</p>\r\n',4,'2024-10-23 14:11:14','2024-10-23 15:52:15','','Publish',0,'open',21,11),('राजस्थान पर संक्षिप्त टिप्पणी','brief-note-on-rajasthan',2,'<p>राजस्थान भारत का सबसे बड़ा राज्य है, जो अपने समृद्ध इतिहास, जीवंत संस्कृति और राजसी स्थापत्य के लिए प्रसिद्ध है। यह राज्य पश्चिमी भारत में स्थित है और अपनी अनूठी भौगोलिक विविधता, जिसमें थार मरुस्थल भी शामिल है, के लिए जाना जाता है। राजस्थान की ऐतिहासिक और सांस्कृतिक संपन्नता इसे भारत के सबसे प्रमुख पर्यटन स्थलों में से एक बनाती है।</p>\r\n<h2>ऐतिहासिक पृष्ठभूमि</h2>\r\n<h3 class=\"atech\">प्राचीन काल</h3> <p>राजस्थान का इतिहास प्राचीन काल से ही गौरवशाली रहा है। यहाँ कई राजपूत राजाओं और रानियों ने शासन किया और अनेक महल, किले और मंदिर बनवाए।</p>\r\n<h3 class=\"atech\">मध्यकालीन इतिहास</h3> <p>मध्यकाल में राजस्थान में कई शक्तिशाली राजपूत राज्य स्थापित हुए। इनमें मेवाड़, मारवाड़, आमेर और बीकानेर प्रमुख थे। महाराणा प्रताप और पृथ्वीराज चौहान जैसे वीर योद्धाओं की गाथाएँ आज भी यहाँ सुनाई जाती हैं।\r\n<h3 class=\"atech\">ब्रिटिश काल</h3><p>अंग्रेजों के शासन के दौरान राजस्थान कई रियासतों में बंटा हुआ था। स्वतंत्रता के बाद इन रियासतों को मिलाकर राजस्थान राज्य का गठन किया गया।</p>\r\n<h2>भूगोल</h2>\r\n<p>राजस्थान की सीमाएँ पश्चिम में पाकिस्तान, उत्तर में पंजाब, उत्तर-पूर्व में हरियाणा और उत्तर प्रदेश, दक्षिण-पूर्व में मध्य प्रदेश, और दक्षिण-पश्चिम में गुजरात से मिलती हैं। थार मरुस्थल राज्य के पश्चिमी हिस्से में फैला हुआ है। अरावली पर्वत श्रृंखला राज्य के मध्य से होकर गुजरती है और इसे दो भागों में विभाजित करती है।</p>\r\n<h2>अर्थव्यवस्था</h2>\r\n<h3 class=\"atech\">कृषि</h3> <p>राजस्थान की अर्थव्यवस्था में कृषि का महत्वपूर्ण योगदान है। यहाँ गेहूँ, जौ, बाजरा, सरसों, और कपास की खेती प्रमुख रूप से की जाती है।</p>\r\n<h3 class=\"atech\">खनिज</h3><p>राजस्थान खनिज संपदा के लिए भी प्रसिद्ध है। यहाँ संगमरमर, चूना पत्थर, जिप्सम, और लिग्नाइट के भंडार हैं।</p>\r\n<h3 class=\"atech\">पर्यटन</h3><p>पर्यटन राज्य की अर्थव्यवस्था का एक महत्वपूर्ण हिस्सा है। जयपुर, उदयपुर, जोधपुर, जैसलमेर और चित्तौड़गढ़ जैसे शहर अपनी ऐतिहासिक धरोहरों और राजसी स्थापत्य के लिए प्रसिद्ध हैं।</p>\r\n<h2>सामाजिक और सांस्कृतिक जीवन</h2>\r\n<p>राजस्थान की संस्कृति रंगीन और विविधतापूर्ण है। यहाँ के लोक गीत, नृत्य (जैसे घूमर और कालबेलिया), कला और हस्तशिल्प बहुत प्रसिद्ध हैं। यहाँ के प्रमुख त्योहारों में दिवाली, होली, तीज, गणगौर और डेजर्ट फेस्टिवल शामिल हैं। राजस्थान के लोग अपने पारंपरिक परिधानों, जैसे कि घाघरा-चोली और पगड़ी के लिए भी जाने जाते हैं।</p>\r\n<h3 class=\"atech\">शिक्षा</h3>\r\n<p>राजस्थान में शिक्षा के क्षेत्र में लगातार सुधार हो रहा है। जयपुर, जोधपुर और उदयपुर में कई प्रतिष्ठित शिक्षण संस्थान हैं। राजस्थान विश्वविद्यालय, एमएनआईटी और बिट्स पिलानी यहाँ के प्रमुख शैक्षिक संस्थान हैं।</p>\r\n<h3 class=\"atech\">चुनौतियाँ</h3>\r\n<p>राजस्थान को कई चुनौतियों का भी सामना करना पड़ता है, जैसे पानी की कमी, सूखा, और बुनियादी ढांचे की कमी। राज्य सरकार और केंद्रीय सरकार इन समस्याओं के समाधान के लिए कई पहल कर रही हैं।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>राजस्थान अपनी ऐतिहासिक धरोहर, सांस्कृतिक विविधता और प्राकृतिक सौंदर्य के लिए विश्वविख्यात है। यहाँ की समृद्ध परंपराएँ और जीवंत संस्कृति इसे एक अनूठा राज्य बनाती हैं। राज्य की जनता का उत्साह और समर्पण इसे और अधिक प्रगति की ओर ले जाएगा।</p> ',25,'2024-10-23 14:11:14','2024-10-23 15:54:19','','Publish',0,'open',24,12),('भारत की राजव्यवस्था पर संक्षिप्त टिप्पणी','brief-note-on-bharat-polity',2,'<p>भारत की राज्यव्यवस्था एक संघीय संसदीय लोकतंत्र है, जिसमें केंद्र और राज्यों के बीच शक्तियों का विभाजन होता है। इसका आधार भारतीय संविधान है, जो देश की सबसे महत्वपूर्ण कानूनी दस्तावेज है।</p>\r\n\r\n<h2>कार्यपालिका</h2>\r\n<p>भारत के कार्यकारी अंग की प्रमुख शक्ति राष्ट्रपति में निहित होती है, जो राष्ट्र का औपचारिक प्रमुख है। हालांकि, वास्तविक कार्यकारी शक्ति प्रधानमंत्री और उनकी मंत्रिपरिषद के हाथों में होती है। प्रधानमंत्री, जो संसद के निचले सदन (लोकसभा) में बहुमत दल का नेता होता है, नीतियों और सरकारी कार्यों का संचालन करता है।</p>\r\n\r\n<h2>विधायिका</h2>\r\n<p>भारतीय संसद द्विसदनीय है, जिसमें दो सदन हैं: लोकसभा और राज्यसभा। लोकसभा, जिसे \'जनता का सदन\' भी कहा जाता है, में सदस्य सीधे जनता द्वारा चुने जाते हैं। राज्यसभा, जिसे \'राज्यों का सदन\' कहा जाता है, में सदस्य राज्यों और केंद्र शासित प्रदेशों के प्रतिनिधियों द्वारा चुने जाते हैं। संसद का मुख्य कार्य कानून बनाना, सरकार की गतिविधियों की निगरानी करना और राष्ट्रीय नीतियों को दिशा देना है।</p>\r\n\r\n<h2>न्यायपालिका</h2>\r\n<p>भारतीय न्यायपालिका स्वतंत्र और निष्पक्ष है। इसका सर्वोच्च निकाय सर्वोच्च न्यायालय है, जो संवैधानिक मुद्दों और अन्य महत्वपूर्ण मामलों में अंतिम निर्णय देता है। उच्च न्यायालय प्रत्येक राज्य में उच्चतम न्यायिक प्राधिकरण होता है, जबकि जिला और निचली अदालतें स्थानीय स्तर पर न्याय प्रदान करती हैं। न्यायपालिका का मुख्य कार्य संविधान की रक्षा करना, कानूनों की व्याख्या करना और नागरिकों के अधिकारों की सुरक्षा सुनिश्चित करना है।</p>\r\n\r\n<p>इस प्रकार, भारत की राज्यव्यवस्था का ढांचा लोकतंत्र, संघवाद और न्याय की अवधारणाओं पर आधारित है, जो देश के सामाजिक, आर्थिक और राजनीतिक विकास को सुनिश्चित करता है।</p>',4,'2024-10-23 14:11:14','2024-10-23 15:58:48','','Publish',0,'open',17,13),('उन्नीसवीं-बीसवीं शताब्दी के गैर-ब्राह्मण आंदोलन','non-brahmin-movement',2,'<p>उन्नीसवीं शताब्दी के उत्तरार्द्ध में गैर-ब्राह्मण आंदोलन प्रारम्भ हुये जो बीसवीं शताब्दी के पूर्वार्द्ध में पश्चिमी भारत एवं दक्षिणी भारत में व्यापक रूप से प्रभावी बने। इन आंदोलनों की पृष्ठभूमि एवं कारण इन क्षेत्रों की विशिष्ट ऐतिहासिक संरचना से सम्बद्ध थे। इन क्षेत्रों के गैर-ब्राह्मणों में अंग्रेजी शिक्षा के प्रचार, इससे प्रभावित सामाजिक-आर्थिक स्थिति तथा इस शिक्षा से विकसित नवीन इतिहास दृष्टि इन आंदोलनों के मूल में निहित तथ्य थे। दूसरी ओर ब्राह्मणों ने भी शिक्षा के क्षेत्र में अपने परम्परागत एकाधिकार का प्रदर्शन कर अँग्रेजी शिक्षा में भी एकाधिकार प्राप्त कर लिया तथा नवीन औपनिवेशिक व्यवस्था के सभी क्षेत्रों वकालत, प्रशासन, शिक्षा, आदि में अपना वर्चस्व स्थापित कर लिया। इससे गैर-ब्राह्मण वर्ग में असुरक्षा की भावना दृष्टिगत हुई जो पहले से ही ब्राह्मणवादी व्यवस्था से दुखी थे। नवीन इतिहास लेखन (साम्राज्यवादी इतिहासकारों द्वारा लिखित) ने भी यह स्पष्ट कर दिया कि आर्य भी अंग्रेजों की भाँति बाहर से आये थे और उन्होंने बलात् अपनी संस्कृति तथा सामाजिक स्तरीकरण पश्चिमी एवं दक्षिणी भारत के समतावादी समाज (द्रविड़ समाज आदि) पर थोप कर अपनी श्रेष्ठता स्थापित कर ली थी, गैर-ब्राह्मण वर्ग को और भी त्रस्त कर दिया।</p>\r\n<p>इस प्रकार गैर-ब्राह्मण वर्ग में यह भावना उत्पन्न हो गयी कि ब्राह्मण वर्ग उसी बलात् आर्यीकरण का प्रतीक है; अन्ततः गैर-ब्राह्मणों की अतीत की प्रतिक्रियावादी नीतियों का प्रतिफलन जाति-व्यवस्था में समझकर उसका घोर विरोध करना प्रारम्भ कर दिया। गैर-ब्राह्मण आंदोलन के नेताओं (ज्योतिबा फुले, नायकर आदि) ने धर्मग्रन्थों की पुनर्व्याख्या तथा अपनी विस्तृत आलोचनात्मक टिप्पणियों द्वारा इस विरोध को व्यापक बनाने का उपक्रम किया। ज्योतिबा फुले ने स्पष्ट किया कि ब्राह्मणों ने निम्नजातियों को वेद इसलिये नहीं पढ़ने दिया था कि वेदों में अनार्यों पर किये गये अत्याचारों का उल्लेख है। इसी प्रकार दक्षिण भारत में पाण्डव की अपेक्षा कौरव, राम की अपेक्षा रावण पूज्य सिद्ध किये गये; शम्बूक वध आदि के द्वारा राम पर ब्राह्मणवादी होने का आरोप मंडित हुआ। इन नवीन प्रवृत्तियों के अतिरिक्त कुछ पारम्परिक कारणों ने भी गैर-ब्राह्मण आंदोलनों को गति प्रदान कर दी थी। पश्चिमी एवं दक्षिणी भारत में अनेक ऐसी गैर-ब्राह्मण जातियाँ थीं जो आर्थिक दृष्टि से उन्नत व समृद्ध थीं परन्तु ब्राह्मणों ने उन्हें सामाजिक प्रतिष्ठा नहीं दी थी, वे हेय दृष्टि से देखी जाती थीं। </p>\r\n<p>अधिकांश गैर-ब्राह्मण आंदोलन आर्थिक एवं शैक्षिक दृष्टि से सशक्त परन्तु सामाजिक दृष्टि से हेय समझे जाने वाले गैर-ब्राह्मणों द्वारा ही हुये थे; इनका उद्देश्य भी अपनी जातियों को अधिकार प्रदान करने तक ही सीमित रहा था- अछूतों, हरिजनों के पक्ष में इन अधिकांश गैर-ब्राह्मण आंदोलनों ने आवाज तक न उठायी। इन आंदोलनों में ज्योतिबा फुले एवं अम्बेडकर इसके अपवाद हैं; वह भी सम्भवतः इसलिये कि वे स्वयं इस वर्ग से सम्बद्ध थे तथा उन्हें सामाजिक प्रतिष्ठा के साथ-साथ आर्थिक सुविधायें भी प्राप्त करनी थीं। केरल का मन्दिर प्रवेश आंदोलन भी इसी कड़ी में स्वीकार किया जा सकता है, परन्तु इस आंदोलन का चरित्र विवेच्य \'गैर-ब्राह्मण आंदोलनों\' से पूर्णतः भिन्न था। ज्योतिबा फुले का \'सत्यशोधक समाज\' भी उनकी मृत्यु के पश्चात् अछूतों की समस्याओं की उपेक्षा कर गया था, अम्बेडकर का आंदोलन भी राजनीतिक सुविधायें प्राप्त करने तक ही सीमित रहा था।</p>\r\n<h2>ज्योतिबा फूले व पेरियार का आन्दोलन</h2>\r\n<p>ब्राह्मण वर्चस्व विरोधी आन्दोलन में ज्योतिबा फूले व पेरियार का नाम काफी गर्व के साथ लिया जाता है। ज्योतिबा फूले ने 1853 ई. में सत्य शोधक समाज का गठन कर मुख्यतः ब्राह्मणवादी हिन्दू पुनरुत्थानवाद के खिलाफ संघर्ष किया। लेकिन इस आन्दोलन ने शुरू से ही जनवादी रवैया अपनाया और साथ ही साथ, जातीय शोषण, विधवा विवाह, शराबखोरी, नौकरशाही का दमन, महाजनों की लूट, किसानों की भूमि से बेदखली, भारतीय सम्पदा की साम्राज्यवादियों द्वारा की जा रही लूट जैसे मामलों को भी उठाया। इस तरह फूले ने देशी सामन्ती प्रतिक्रियावादी आधार व इसके उपरी ढाँचा के साथ-साथ ब्रिटिश शासन पर ही हमला किया। इसी आंदोलन के द्वारा निम्न जातियों में अपने बच्चों को शिक्षित बनाने की ललक उत्पन्न हुई थी।</p>\r\n<p>ज्योतिबा फुले ने 1851 ई. में एक विद्यालय शूद्रों के बच्चों के लिये तथा एक बालिका विद्यालय स्थापित किया था; कालान्तर में इसी \'सत्यशोधक आंदोलन\' के नेता साहू महाराज ने दलित वर्ग के छात्रों के लिये छात्रावास एवं छात्रवृत्तियों की व्यवस्था की थी। इनगैर-ब्राह्मण आंदोलनों ने स्त्रियों की दशा में सुधार हेतु उन्हें साक्षर बनाने व शिक्षित करने के महत्त्वपूर्ण प्रयास किये थे। लेकिन इसके पहले कि उनका संघर्ष बुनियादी भूमि सम्बन्धों को चुनौती देता, उनकी मौत हो गयी। उनकी मृत्यु के बाद आन्दोलन का नेतृत्व कोल्हापुर के सामन्ती महाराजा के हाथों में आ गया और इसका जनवादी सर्वव्यापी चरित्र कायम नहीं रह सका। आगे चलकर इस आन्दोलन का मूल चरित्र ही बदल गया और अब इसका लक्ष्य ब्राह्मणों की जगह क्षत्रियों/मराठों को बेहतर स्थान दिलाने तक सीमित हो गया। इस निहित स्वार्थ की प्राप्ति के लिए इसके नेताओं ने ब्रिटिश साम्राज्यवाद से समझौता तक किया।</p>\r\n<p>सर्वाधिक महत्त्वपूर्ण तथ्य इन गैर-ब्राह्मण आंदोलनों में यह उद्भासित हुआ कि तमिलनाडू में सर्वथा उपेक्षित हजारों वर्ष प्राचीन गौरवमयी \'संगम साहित्य की ओर भारतीयों की दृष्टि गयी; इससे तमिल भाषा का विकास हुआ; इतिहास के नवीन स्त्रोत उजागर हुये। प्राचीन भारत के गौरवमयी इतिहास के अनेक तथ्य लोगों को ज्ञात हुये। दक्षिण भारत की सभी क्षेत्रीय भाषायें विकसित हुई।</p>\r\n<p>इ.वी. रामास्वामी, जिन्हें पेरियार के नाम से जाना जाता है, शुरू में काँग्रेस पार्टी के साथ जुड़े थे। लेकिन कॉंग्रेसी नेताओं के जातिवादी पूर्वाग्रहों से उन्हें काफी घृणा हुई और उससे बाहर आकर उन्होंने 1925 में \'आत्म-सम्मान आन्दोलन की शुरुआत की। इसके पूर्व तमिलनाडु में \'जस्टिस पार्टी बन चुकी थी और 1920 के मद्रास प्रेसीडेंसी चुनाव में उसे बहुमत भी प्राप्त हो चुका था। पेरियार आमतौर पर जस्टिस पार्टी के मंच का इस्तेमाल किया करते थे, लेकिन इस पार्टी की प्रान्तीय सरकार बनने के बाद उनके रुख में परिवर्तन आया। उन्होंने इस सरकार की जन विरोधी व दलित विरोधी कार्रवाइयों की तीखी आलोचना की। नतीजतन उन्हें ब्रिटिश सरकार के दमन का शिकार बनना पड़ा। उन्होंने 1942 ई. में द्रविड़ कड़गम पार्टी का गठन किया जो आगे चलकर डी. के. और डी.एम. के. में विभाजित हो गयी। उन्होंने 15 अगस्त 1947 को शोक दिवस\' के रूप में मनाने का आह्वान किया और \'आजाद भारत\' के कॉंग्रेसी राज को \'ब्राह्मण राज\' की संज्ञा दी।</p>\r\n<p>अरव्विपुरम् आंदोलन\' केरल के महान् धार्मिक-सामाजिक सुधारक श्री नारायण गुरु द्वारा 1888 ई. में प्रारम्भ किया गया था, इन्होंने 1888 ई. में शिवरात्रि पर्व के अवसर पर अरव्विपुरम् में शिव की प्रतिमा की प्राण प्रतिष्ठा कर इस आंदोलन का सूत्रपात किया तथा व्यक्त किया कि निम्न जाति का व्यक्ति भी प्रतिमाभिषेक कर सकता है, मन्दिर में पुजारी का कार्य सम्पादित कर सकता है। वे स्वयं भी निम्न जाति के थे। यह आंदोलन \'ऐतिहासिक महत्व का घटनाक्रम\' था क्योंकि तत्कालीन समय में निम्न जाति के व्यक्ति के लिये मन्दिर में प्रवेश सम्भव ही नहीं था; श्री नारायण गुरु ने मन्दिर में जाकर शिव की मूर्ति का अभिषेक कर मन्दिर.. की दीवाल पर लिखा \'जाति या नस्ल की विभाजक प्राचीरों अथवा प्रतिस्पर्धी धर्म की घृणा से रहित हम सभी यहाँ भाईचारे के साथ रहते हैं।</p>\r\n<p>श्री नारायण गुरु को लाखों लोगों ने संत, दूरदर्शी समाज सुधारक के रूप में स्वीकार कर निम्न जाति के उत्थान में योग किया। - निःस्सन्देह दक्षिण भारत के इतिहास में इस आंदोलन (अरव्विपुरम् आंदोलन) का बहुत बड़ा योगदान है। इस आंदोलन ने अनेकानेक धार्मिक सामाजिक सुधारवादी आंदोलनों का पथ प्रशस्त किया था। अन्ततः मन्दिर प्रवेश आंदोलन का यह आंदोलन अग्रदूत बना। 1924 ई. में दलित वर्गों के लिये मन्दिरों के प्रवेश-द्वार खोलने की व्यापक मुहिम हुई। मन्दिर प्रवेश आंदोलन ने राष्ट्रवादी संघर्ष में सभी पक्षों का ध्यान अपनी ओर आकृष्ट कर लिया था। नवम्बर 1936 ई. में त्रावणकोर के महाराजा ने जाति का विचार किये बिना सभी हिन्दुओं के लिये सरकारी नियन्त्रण वाले सभी मन्दिरों के द्वार खोलने की घोषणा कर दी। 1936 ई. में मद्रास ने इसका अनुसरण किया। इसी प्रकार केरल में \'नायर सेवा समाज\' (मन्नथ पद्मनाभ पिल्लई द्वारा स्थापित) ने जाति शोषण (निम्न जातियों के शोषण) के विरुद्ध आंदोलन प्रारम्भ किया था।</p>\r\n<p>1910 ई. के उपरान्त ज्योतिबा फुले के विचारों से प्रेरित होकर मुकुन्दराव पाटिल एवं शंकर राव जाधव ने एक ब्राह्मण विरोधी \'बहुजन समाज की स्थापना की। यह आंदोलन कालान्तर में सामाजिक एवं राजनीतिक रूप में विघटनकारी और ब्रिटिश सरकार का समर्थक बन गया था। यह आंदोलन मूलतः एक \'दलित\' आंदोलन था; दलितों की बहुत संख्या के आधार पर इसे \'बहुजन\' नाम प्रदान किया गया था। इस आंदोलन ने जाति प्रथा पर प्रहार कर ब्राह्मणों के विरुद्ध दलित जनों को संगठित किया था। 1910 ई. से मुकुन्द राव, पाटिल ने सत्यशोधक समाचार-पत्र \'दीन मित्र\' का प्रकाशन प्रारम्भ किया था, जिसके प्रचार-प्रसार ने बहुजन समाज को महाराष्ट्र, दक्कन, विदर्भ में अपना सशक्त जनाधार बनाने में सहयोग किया।</p>\r\n<p>राष्ट्रवादी आंदोलन से गैर-ब्राह्मण आंदोलनों के सम्बन्ध में यह तथ्य प्रगट होता है कि समय और स्थान की दृष्टि से इनमें पर्याप्त असमानतायें विद्यमान थीं। महाराष्ट्र में ज्योतिबा फुले अपनी अधिकाधिक सामाजिक प्रगतिशीलता के होते हुये भी औपनिवेशिक शासन के वास्तविक स्वरूप को समझ नहीं पाये, वे उसे सामाजिक परिवर्तन में सहायक स्वीकार करते रहे। तमिलनाडू में \'आत्मसम्मान आंदोलन\' राष्ट्रीय आंदोलन का विरोधी था। इसके प्रणेता नायकर ने गैर-ब्राह्मणों के कांग्रेस के प्रति बढ़ते लगाव से भयभीत होकर \'जस्टिस पार्टी\' से अपने को पृथक कर \'आत्मसम्मान आंदोलन\' के रूप में गैर राजनीतिक आंदोलन से सम्बद्ध किया था। इस दृष्टि से आन्ध्र प्रदेश के आंदोलन का स्वरूप, अत्यधिक सकारात्मक माना जा सकता है</p>',33,'2024-10-23 14:11:14','2024-10-23 16:10:17','','Publish',0,'open',35,14),('जार अलेक्जेंडर द्वितीय के सुधार आंदोलन','reform-movement-of-alexander-2',2,'<p>1855 ई। में रूस के जार निकोलस प्रथम की मृत्यु हो गई। इसके बद उसका पुत्र अलेक्जेंडर द्वितीय रूस का सम्राट बना। उसने अपने पिता के विपरीत उदारवादी शासन को अपनाया। उसने अपने पिता के द्वारा किए गए दमनकारी शासन के कारण उपजे जनता की असंतोष और अव्यवस्था को देखते हुए बहुत से सुधार करने के प्रयास किया।</p>\r\n<h2>जार अलेक्जेंडर द्वितीय के द्वारा किए गए सुधार कार्य</h2>\r\n<h3 class=\"atech\">दास प्रथा का अंत</h3>\r\n<p> इस समय रूस में दास व्यवस्था काफी चरम पर था 1860 ईस्वी में रूस के जनसंख्या का लगभग आधा भाग आधी जनसंख्या अर्थात चार करोड़ लोग कृषि दास थे इनमें से दो करोड़ लोग राजकीय भूमि पर काम करने वाले दास थे। बागी 2 करोड़ दासों पर चर्च तथा कुलीन वर्गों का अधिकार था। रूस के सुधारवादियों के अनुसार जब तक रूस में से दास प्रथा को खत्म न किया जाए तब तक रूस का विकास संभव नहीं। अतः जान ने दास प्रथा को खत्म करने की दिशा में प्रयास करने लगा। इस संबंध में उसने 1856 ई। में एक घोषणापत्र प्रकाशित कराया। इस घोषणापत्र में उसने सबके लिए समान न्याय संबंधी कानूनों की आवश्यकता पर बल दिया। 19 फरवरी 1961 को राजाज्ञा द्वारा कृषि-दासता समाप्त कर दिया गया। इसके बाद जार अलेक्जेंडर द्वितीय को मुक्तिदाता जार कहा जाने लगा। कृषि-दासत्व से स्वतंत्रता प्राप्त हो जाने के बाद कृषकों को स्वतंत्र आजीविका का साधन प्राप्त हो गया। कृषकों की दशा सुधारने से उनको समाज में विशिष्ट स्थान प्राप्त हो गया। बहुत से कृषक मिलों और फैक्ट्रियों में काम करने लगे। इसके बाद रूस का औद्योगिक विकास होना शुरू हो गया।</p>\r\n<h3 class=\"atech\">न्याय व्यवस्था में सुधार</h3>\r\n<p>तत्कालीन शासन व्यवस्था के न्याय व्यवस्था में भेदभाव, भ्रष्टाचार आदि चरम पर थी। न्यायालय के न्यायाधीश कानूनों की उचित जानकारी नहीं रखते थे। इसी वजह से निष्पक्ष न्याय नहीं कर पाते थे। मुकदमे काफी लंबे समय तक चलते थे। ऐसे में लोगों को समय पर न्याय नहीं मिल पाता था। इन सब के कारण रूस के जार एलेग्जेंडर द्वितीय ने न्याय संबंधी सुधारों को करने की दिशा में प्रयास किया। उन्होंने सन 1858 ई। में विधि मंत्रालय के उच्च अधिकारियों की अध्यक्षता में एक आयोग का गठन किया। इसके पश्चात सन 18 सो 62 ईस्वी में आयोग द्वारा प्रस्तुत सुझावों के आधार पर एक नई एवं उन्नत न्याय प्रणाली लागू की।</p>\r\n<h3 class=\"atech\">स्थानीय शासन में सुधार</h3>\r\n<p> जनवरी 1864 ई। में एक राजाज्ञा प्रकाशित की गई। इसके अनुसार स्थानीय शासन के लिए कई प्रशाससिक सुधार किए गए। प्रत्येक जिलों में दो नई स्थानीय परिषदों का गठन किया गया। ये परिषदें समाज के कृषक, कुलीन और व्यापारी वर्ग का प्रतिनिधित्व करती थी। सड़क एवं पुलों का जीर्णोद्धार करना, शिक्षा एवं सफाई की देखभाल एवं व्यवस्था करना, अकाल के समय व्यवस्था करना एवं स्थानीय झगड़ों का निपटारा करना आदि जिला एवं प्रांतीय परिषदों के कार्य क्षेत्र में दे दिए गए। इसके अलावा 1870 ई। में प्रत्येक नगरों में म्युनिसिपल काउंसिल का भी गठन किया गया।</p>\r\n<h3 class=\"atech\"> सेना में सुधार</h3>\r\n<p>1824 में उन्होंने एक कानून पारित किया गया। इस कानून के अंतर्गत 20 वर्ष के नवयुवकों के लिए 6 वर्षीय सैन्य सेवा अनिवार्य घोषित कर दी गई। इसके अलावा सेना के विभिन्न विभागों की पुनर्गठन की गई और कई सुधार किए गए। इन सब सुधारों के परिणामस्वरूप रूस की सेना की क्षमता में निरंतर वृद्धि होती चली गई।</p>\r\n<h3 class=\"atech\">शिक्षा में सुधार</h3>\r\n<p>जार अलेक्जेंडर द्वितीय ने शिक्षा के क्षेत्र में बहुत से सुधार किए। उनहोंने 1864 ई के एक अधिनियम के आधार पर विभिन्न संस्थाओं और व्यक्तियों को प्राथमिक विद्द्यालय खोलने की अनुमति प्रदान की। विद्यालयों के प्रबंधनों में भी बहुत से सुधार किये। उनहोंने जार निकोलस के समय विश्वविद्यालयों पर लगाए प्रतिबन्धों को समाप्त कर दिया। 1870 ई के बाद स्त्रियों को भी उच्च शिक्षा का भी अधिकार दिया।</p>\r\n<h3 class=\"atech\">आर्थिक सुधार</h3>\r\n<p>जार एलेग्जेंडर द्वितीय के द्वारा किए गए गए सुधारों के परिणामस्वरूप रूस में तेजी से औद्योगिकरण हुआ। परिणाम स्वरूप कारखानों की संख्या में वृद्धि होती गई और मशीनों का प्रयोग किया जाने लगा। 1861 ई। में व्यापार और उद्योगों को प्रोत्साहित करने के लिए बैंक ऑफ रशिया के स्थापना की गई। 1860 से 1870 के दौरान रूस में विदेशी व्यापार काफी बढ़ गया। रेलवे के विस्तार से व्यापार और उद्योग में काफी प्रगति होती गई।</p>\r\n<h3 class=\"atech\">अन्य सुधार</h3>\r\n<p>इसके अलावा उन्होंने बहुत से अन्य सुधार भी किए। जार निकोलस शासन काल में निकोलस प्रथम के विरुद्ध विद्रोह करने के कारण साइबेरिया डिकोब्रिस्टो को जार ने मुक्त कर दिया। तमाम राजनीतिक बंदियों को आजाद कर दिए गए। विश्वविद्यालयों को स्वायत्तता दी गई तथा प्रत्येक वर्ग के छात्रों को प्रवेश करने की सुविधाएं दी गई। विदेश यात्रा पर लगे प्रतिबंध को समाप्त कर दिया गया। समाचार पत्र संबंधित प्रतिबंध के कठोर नियमों को उदार कर दिया गया। रेलवे तथा विदेश यात्री संबंधी सुधार में भी उदार नीति का परिचय दिया।</p>',13,'2024-10-23 14:11:14','2024-10-23 16:12:15','','Publish',0,'open',25,15),('द्वितीय अफीम युद्ध के कारण और परिणाम','causes-and-consequences-of-the-second-opium-war',2,'<p>द्वितीय अफीम युद्ध 1856-60 ई. में हुआ था। प्रथम अफीम युद्ध में चीन को परास्त तो ब्रिटेन ने किया मगर उसके पश्चात धीरे- धीरे अन्य यूरोपीय शक्तियों ने भी चीन के साथ संधि कर सुविधाएँ प्राप्त की। अमेरिका के साथ की गई ह्वागिया एवं फ्रांस के साथ संपन्न हवामपोआ की संधियों में यह व्यवस्था थी कि 10 वर्ष पश्चात् पुन: संधियों का पुनरीक्षण किया जायेगा। उधर ब्रिटेन, चीन में और अधिक सुविधाएँ प्राप्त करना चाहता था। विदेशी शक्तियों ने जब चीन के समक्ष संधियों के पुनरीक्षण की माँग रखी तो चीन ने उनकी ओर कोई ध्यान नहीं दिया। अब अंग्रेजों को समझ में आ गया कि बिना युद्ध किये चीन से माँग मनवाना आसान नहीं है। इस प्रकार द्वितीय अफीम युद्ध की परिस्थितियाँ निर्मित हुई।</p>\r\n<h2>द्वितीय अफीम युद्ध के कारण</h2>\r\n<h3 class=\"atech\">चीनी शासकों का भ्रम एवं अयोग्यता</h3>\r\n<p>प्रथम अफीम युद्ध के पश्चात् भी चीनी शासकों को यह मिथ्या भ्रम था कि वे विदेशियों को नियंत्रित करने में समर्थ हैं। उधर मंचू शासकों की अयोग्यता के कारण देश में भ्रष्टाचार, शोषण, बेकारी, भुखमरी, षड़यंत्र एवं अफीम की तस्करी के कारण स्थिति दुर्बल एवं अराजकतापूर्ण होती जा रही थी। इन परिस्थितियों का लाभ साम्राज्यवादी शक्तियाँ उठाना चाहती थीं। </p>\r\n<h3 class=\"atech\">नानकिंग की संधि से उत्पन्न असंतोष</h3>\r\n<p> चीनी लोग 1849 ई. की नानकिंग संधि को अपने लिये अपमानजनक मानते थे। इस कारण चीनवासियों के मन में विदेशियों के प्रति घृणा की भावना व्याप्त थी।</p>\r\n<h3 class=\"atech\">चीनियों को बलात मजदूर बनाना</h3>\r\n<p> चीन में व्याप्त बेरोजगारी, बेकारी एवं भुखमरी का लाभ उठाकर विदेशी लोग चीनियों को मजदूर के रूप में जबरन क्यूबा एवं पेरू भेज रहे थे। जब मंचू शासन ने इसका विरोध किया तो संघर्ष की स्थिति निर्मित हुई।\r\n</p>\r\n<h3 class=\"atech\">चीनी जहाजों से वसूली</h3>\r\n<p> जल दस्युओं को पकड़ने के बहाने विदेशियों ने चीनी जहाजों से उनकी रक्षा के नाम पर काफी धन वसूल किया।</p>\r\n<h3 class=\"atech\">व्यापारिक सुविधाओं के विस्तार की इच्छा</h3>\r\n<p> ब्रिटेन, फ्रांस एवं अमेरिका चीन में व्यापारिक सुविधाओं का विस्तार चाहते थे। उनकी प्रमुख माँगें निम्न थीं – </p>\r\n<ul>\r\n    <li><p>चीन के आंतरिक भागों में प्रवेश की सुविधा। </p></li>\r\n    <li><p>पीकिंग में राजदूत रखने की सुविधा। </p></li>\r\n    <li><p>शुल्क दरें समाप्त करने की सुविधा। </p></li>\r\n</ul>\r\n<p>फरवरी, 1854 ई. में ब्रिटिश उच्चायुक्त लार्ड बेंटिंग ने यह प्रस्ताव रखे। चीनी प्रशासन ने इन माँगों की उपेक्षा की अत: इन परिस्थितियों में बल प्रयोग अपरिहार्य हो गया।फ्रांसीसी पादरी को फाँसी चीन के क्वांगत्सी स्थित अधिकारियों ने फरवरी 1856 ई. में फ्रांस के कैथोलिक पादरी अगास्टे चेपरीलेन को विद्रोह के आरोप में बन्दी बनाकर फाँसी दे दी। फ्रांस इससे अत्यधिक नाराज हुआ। वह अब इसका बदला लेना चाहता था।</p>\r\n<h3 class=\"atech\">लोर्चा एरो जहाज की घटना </h3>\r\n<p>द्वितीय अफीम युद्ध का तात्कालिक कारण लोर्चा एरो जहाज की घटना सिद्ध हुआ। लोर्चा ऐरो जहाज का मालिक एक चीनी था मगर उसका कप्तान अंग्रेज था। जहाज पर अंग्रेजी झण्डा फहराया था। चीनी अधिकारी जलदस्युओं को पकड़ना चाहते थे। इसी तारतम्य में उन्होंने लोर्चा ऐरो जहाज की तलाशी ली एवं उसके 12 चालकों को बंदी बना लिया। ब्रिटिश वाणिज्य दूत ने चीन के सम्मुख 2 माँग रखीं - </p>\r\n<ul>\r\n    <li><p>12 जहाज चालकों को मुक्त किया जावे। </p></li>\r\n    <li><p>इस घटना के लिये चीन माफी माँगे।</p></li>\r\n</ul>\r\n<p>चीनी शासन ने जहाज चालकों को तो मुक्त कर दिया मगर माफी माँगने से साफ इन्कार कर दिया। अंग्रेज तो युद्ध का कोई न कोई बहाना ढूँढ़ ही रहे थे। इसी बात को लेकर अंग्रेजों ने चीन के विरूद्ध युद्ध की घोषणा कर दी।</p>\r\n<h2  class=\"atech\">परिणाम</h2>\r\n<p>द्वितीय अफीम युद्ध का परिणाम चीन के लिए राजनीतिक रूप से अत्यंत दूरगामी सिद्ध हुआ. युद्ध के अंत में तिन्तसीन की संधि हुई. इसके पश्चात पीकिंग समझौते ने चीन के दरवाजे को पश्चिमी देशों के लिए पूर्ण रूप से खोल दिया. इनके बाद अमेरिका, इंग्लैंड, फ्रांस जैसे देश चीन पर अपने अपने प्रभाव का विस्तार करने में लगे रहे. यह देखकर रूस ने भी चीन में अपने प्रभाव का विस्तार करने शुरू कर दिए. 1853 ईस्वी तक उन्होंने सखालिन द्वीप पर कब्जा कर लिया. 1807 ईस्वी तक रूस ने चीन की 3 लाख 50 हजार वर्ग मील की भूमि पर अपना आधिपत्य स्थापित कर लिया. पश्चिमी धर्म प्रचारक चीन में अपना जमीन की चीन में जमीन खरीद कर अपना आलीशान भवन बनाने लग. पश्चिमी देशों का व्यापार भी दिन प्रतिदिन चीन में बढ़ता चला गया. धीरे-धीरे कुल चीन के कुल 16 बंदरगाह पश्चिमी देशों के व्यापारियों के लिए खुल गए. पश्चिमी व्यापारियों को राज्य क्षेत्रातीताधिकार प्राप्त हो गया. इस प्रकार द्वितीय अफीम युद्ध के कारण चीन में पूरी तरह पश्चिमी देशों को पूरी तरह अपना प्रभाव जमाने कि रास्ता खुल गए।</p>',37,'2024-10-23 14:11:14','2024-10-23 16:14:43','','Publish',0,'open',35,16),('भारत में उदारवादी आन्दोलन पर एक निबंध लिखें।','liberal-movement-in-bharat',2,'<h2>उदारवादी काँग्रेसियों का आन्दोलन </h2>\r\n<p> सन् 1885 ई. के दिसम्बर माह में भारतीय राष्ट्रीय काँग्रेस का जन्म एक ऐसी संस्था के रूप में हुआ था, जिसे ब्रिटिश सरकार का आशीर्वाद और वरदान प्राप्त था। अँगरेज शासकों की कल्पना में कांग्रेस की स्थापना इंगलैण्ड में विरोधी दल द्वारा किये जानेवाले कार्यों के संपादन के लिए हुई थी । वस्तुतः जिन दिनों कॉंग्रेस पालने में थी, उन दिनों कॉंग्रेस के हुए अधिवेशनों में वक्ताओं द्वारा सरकार के गुणों का गान किया जाता था, अँगरेजों की न्यायप्रियता में विश्वास किया जाता था तथा सरकार के प्रति राजभक्ति प्रदर्शित की जाती थी। यही कारण था कि कॉंग्रेस को बचपन में अँगरेजों का पूरा-पूरा सहयोग प्राप्त रहा। सरकार कॉंग्रेस की स्थापना को \'ब्रिटिश सरकार की विजय और गौरव की वस्तु\' समझती थी।</p>\r\n<h2>अँगरेजों का सिरदर्द </h2>\r\n<p>परन्तु यह स्थिति अधिक दिनों तक नहीं चली। सन् 1888 ई. से काँग्रेस भारतीय राष्ट्रवाद के विचारों और आकांक्षाओं को एक स्पष्ट और संगठनात्मक रूप देने लगी। फलतः भारत में राष्ट्रीयता की भावना बहुत तेजी से प्रगति करने लगी। इसी क्रम में काँग्रेस द्वारा जब भारत में शीघ्र ही प्रजातंत्रात्मक शासन और संसदीय प्रणाली लागू करने की माँग की गयी, तो उस माँग से अँगरेज घबरा उठे। उन्हें भय होने लगा कि जिस प्रकार पिछले तीन-चार वर्षों में काँग्रेस की प्रगति हुई है, यदि वही क्रम जारी रहा तो शीघ्र ही ब्रिटिश साम्राज्य को बहुत बुरे दिन देखने पड़ेंगे। फल यह हुआ कि जिस काँग्रेस को प्रारम्भिक तीन वर्षों में अँगरेजों का वरदान प्राप्त हुआ, उसे ही अब उनका कोपभाजन बनना पड़ा। अँगरेजों की दृष्टि में अब काँग्रेस एक \'भयानक शिशु\' दिखाई पड़ने लगी तथा उनके द्वारा काँग्रेस की खुलेआम आलोचना होने लगी। लॉर्ड डफरिन ने कहा- \"अब काँग्रेस का झुकाव राजद्रोह की ओर हो रहा है। यह हानिरहित साधन नहीं रहा । काँग्रेस एक ऐसा नगण्य अल्पमत है, जिसे एक शानदार और विभिन्न रूपवाले साम्राज्य के शासन की बागडोर हरगिज नहीं दी जा सकती।” अँगरेजी समाचार-पत्रों में कहा गया- “काँग्रेस छद्मवेश में एक ऐसी राजद्रोही संस्था है, जिसे न तो जनता का प्रतिनिधित्व प्राप्त है और न जिसका कोई मूल्य ही है\"।\r\n</p>\r\n<h2>काँग्रेस के खिलाफ कार्रवाई </h2>\r\n<p>सन् 1889 ई. में काँग्रेस के इलाहाबाद सम्मेलन में अँगरेजों द्वारा काफी बाधाएँ पहुँचायी गयीं तथा उसमें भाग लेनेवाले प्रतिनिधियों पर काफी निगरानी रखी गयी। मुसलमानों को यह कहकर बहकाया गया कि काँग्रेस हिन्दुओं की संस्था है। सन् 1890 ई. तक सरकार स्पष्ट रूप से काँग्रेस-विरोधी बन गयी तथा उसी वर्ष सभी सरकारी अफसरों को एक आदेश द्वारा काँग्रेस से सम्पर्क रखने की मनाही कर दी गयी। सन् 1897 ई. में राजद्रोहात्मक भाषणों और कार्यवाहियों पर अंकुश लगाने हेतु भी कई कानून बनाये गये। प्रेस पर भी बहुत से प्रतिबन्ध लगा दिये गये। अँगरेजों के रुख का पता कर्जन द्वारा भारत सचिव को लिखे उस पत्र से मिलता है, जिसमें कहा गया था कि- \"काँग्रेस का भवन अब शीघ्र ही ढहने को है और जब तक मैं भारत में हूँ, मेरी यही इच्छा है कि इसे शान्तिपूर्वक कब्र तक पहुँचा हूँ।\"</p>\r\n<p>इस प्रकार हम पाते हैं कि काँग्रेस को अपनी स्थापना : के कुछ ही दिनों के बाद सरकारी संरक्षण से हाथ धोना पड़ा। परन्तु काँग्रेस को इससे हानि के बदले लाभ ही हुआ। ज्यों-ज्यों सरकार का दमन चक्र बढ़ता गया, त्यों-त्यों कॉंग्रेस की लोकप्रियता बढ़ती गयी। काँग्रेस को अब सरकार की आलोचना करने में झिझक नहीं रही। जनता की माँगों का जोरदार समर्थन काँग्रेस द्वारा होने लगा तथा अब काँग्रेस द्वारा सामाजिक और संवैधानिक सुधारों के अतिरिक्त आर्थिक उन्नति के क्षेत्र में भी सुधार हेतु प्रस्ताव पारित किये जाने लगे।</p>\r\n<h2>उदारवादियों की माँगों ने जोर</h2>\r\n<p>सन् 1885 ई. से 1905 ई. तक काँग्रेस के माध्यम से उदारवादियों ने समय-समय पर प्रस्तावों द्वारा निम्नलिखित संवैधानिक, आर्थिक और सामाजिक सुधारों की माँग की-</p>\r\n<ul>\r\n    <li><p>सन् 1861 ई. के अधिनियम द्वारा स्थापित वायसराय और गवर्नरों की विधान परिषदों का विस्तार एवं उसमें निर्वाचित सदस्यों की संख्या में वृद्धि।</p></li>\r\n    <li><p>भारत में आई. सी. एस. परीक्षा की व्यवस्था।</p></li>\r\n    <li><p>सेना के व्यय में कटौती।</p></li>\r\n    <li><p>भारत सचिव के भारत-परिषद् की समाप्ति।</p></li>\r\n    <li><p>न्यायपालिका और कार्यपालिका का पृथक्करण। </p></li>\r\n    <li><p>समाचारपत्रों पर से प्रतिबन्ध की समाप्ति।</p></li>\r\n    <li><p>उच्च नागरिक एवं सैनिक पदों पर भारतीयों की नियुक्ति।</p></li>\r\n    <li><p>भारतीयों को सैनिक-शिक्षा</p></li>\r\n    <li><p>भूमि कर की दर में स्थायित्व एवं निश्चितता।</p></li>\r\n    <li><p>भारतीय उद्योग-धंधों का संरक्षण। </p></li>\r\n    <li><p>जमींदारों का शोषण समाप्त करने के लिए किसानों को सस्ते दर पर ऋण 12. भारत में शैल्पिक एवं औद्योगिक संस्थाओं की स्थापना।</p></li>\r\n    <li><p>स्थानीय संस्थाओं को अधिकाधिक अधिकार।</p></li>\r\n    <li><p>भारत में गरीबी के कारणों का पता लगाने एवं उन्हें दूर करने की माँग।</p></li>\r\n    <li><p>नमक पर कर में कमी।</p></li>\r\n    <li><p>विदेशों में रहने वाले भारतीयों की रक्षा।</p></li>\r\n    <li><p>भारत में आनेवाले विदेशी मालों पर कर की व्यवस्था तथा बाहर भेजे जाने वाले अनाजों पर प्रतिबन्ध।</p></li>\r\n    <li><p>खेती हेतु सिंचाई की व्यवस्था, तथा नशाबंदी ।</p></li>\r\n</ul>\r\n<h2>उदारवादियों की विशेषताएँ</h2>\r\n<p>इस प्रकार हम पाते हैं कि काँग्रेस ने अपने जन्मकाल के प्रारम्भिक 20 वर्षों में विभिन्न संवैधानिक, आर्थिक एवं सामाजिक सुधारों की माँग की। परन्तु इस अवधि में कॉंग्रेस पर उदारवाद का जादू चढ़ा रहा । काँग्रेस पर उदारवादियों का आधिपत्य था तथा उनकी कार्य-पद्धति \'भिक्षां देहि\' की थी। उदारवादियों की निम्नलिखित विशेषताएँ थीं</p>\r\n<ul>\r\n    <li><p>उदारवादी, ब्रिटिश शासन के समर्थक और राजभक्त थे,</p></li>\r\n    <li><p>वे क्रमिक सुधारों में विश्वास करते थे,</p></li>\r\n    <li><p>वे भारत के हितार्थ इंगलैण्ड से स्थायी सम्बन्ध कायम करने के पक्षपाती थें,</p></li>\r\n    <li><p>उन्हें अँगरेजों की न्यायप्रियता में विश्वास था,</p></li>\r\n    <li><p>वे विद्रोह और बगावत के विरोधी थे तथा उन्हें वैधानिक तरीकों में विश्वास था,</p></li>\r\n    <li><p>राजनीतिक स्वशासन की प्राप्ति उनकी माँग थी।</p></li>\r\n</ul>\r\n<p>अँगरेजों द्वारा कॉंग्रेस के प्रति विपरीत रुख अपनाये जाने के बावजूद काँग्रेस के अग्रण्य नेता ब्रिटिश शासक के प्रशंसक एवं राजभक्त थे, क्रमिक सुधारों एवं अँगरेजों की न्यायप्रियता में विश्वास रखते थे एवं विद्रोह तथा बगावत के विरोधी थे। इसी कारण उन्हें उदारवादी कहा गया तथा उनके द्वारा चलाये गये आन्दोलन को उदारवादी आन्दोलन कहा गया। सन् 1885 ई. से 1905 ई. तक कॉंग्रेस पर उदारवादियों का आधिपत्य रहा, अतः इस युग को भारतीय राजनीति में उदारवाद का युग कहा जाता है।</p>\r\n<h2>उदारवादी आन्दोलन की अवनति </h2>\r\n<p>उपर्युक्त अवधि में भारत के राजनीतिक जीवन में पूर्णतया शान्ति रही। सरकार की प्रतिक्रियावादी एवं दमनपूर्ण नीर्ति, सन् 1892 ई. के अधिनियम में भारतीय माँगों की उपेक्षा आदि कारणों से बहुत से राष्ट्रीय नेताओं ने ऐसे विचारों को व्यक्त करना प्रारम्भ कर दिया जो क्रान्तिकारी भावनाओं से परिपूर्ण थे। तिलक का यह नारों कि \"स्वराज्य हमारा जन्मसिद्ध अधिकार है\" तथा विपिन चन्द्र पाल का यह कथन कि- \"स्वराज्य, जनता के प्रयत्न से प्राप्त करना चाहिए, सरकार के उपहार या पुरस्कार से नहीं\" इन्हीं भावनाओं के द्योतक थे। सन् 1888 ई. के बाद ज्यों-ज्यों सरकार का काँग्रेस के प्रति रुख खराब होता गया तथा सरकार साम्राज्यवादी और प्रतिक्रियावादी नीति का आश्रय लेती गयी, त्यों-त्यों उदारवादियों की \'भिक्षां देहि\' की नीति में लोगों की आस्था घटने लगी। 1906 ई. में भारतीय राष्ट्रीयता ने निष्क्रियता के केंचुल का परित्याग कर सक्रिय रूप धारण किया। उदारवादियों के प्रति लोगों की आस्था धीरे-धीरे कम होती गयी। इसके कारण निम्नलिखित थे-</p>\r\n<ul>\r\n    <li><p>सरकार के सुधारों से पर्याप्त असंतोष,</p></li>\r\n    <li><p>सरकार की प्रतिक्रियावादी नीति,</p></li>\r\n    <li><p>अकाल, महामारी तथा उसको रोकने के लिए सरकार द्वारा किये गये अपर्याप्त प्रयास</p></li>\r\n    <li><p>सरकार की आर्थिक नीति तथा देश की दयनीय स्थिति,</p></li>\r\n    <li><p>सरकारी नौकरियों में सरकार की पक्षपातपूर्ण नीति, </p></li>\r\n    <li><p>लॉर्ड कर्जन की दमनकारी नीति, जिसमें भारतीयों को हर तरह से सताने तथाराष्ट्रीय आन्दोलन को कुचलने का प्रयास किया गया था।</p></li>\r\n</ul>\r\n<h2>जुझारू मनोवृत्ति का विकास </h2>\r\n<p>सन् 1905 ई. के बाद राष्ट्रीय आन्दोलन ने सक्रिय राष्ट्रीयता का रूप धारण किया जिसकी आधारशिला थी- भारतीयों द्वारा अपने को संगठित कर तथा सशक्त बनाकर अँगरेज शासकों से अपने अधिकारों की प्राप्ति के लिए युद्ध करने की मनोवृत्ति। इस नयी विचारधारा की कार्यविधि थी-सीधी कार्रवाई</p>\r\n<h2>काँग्रेस में विभाजन</h2>\r\n<p>जुझारू मनोवृत्ति के विकास के साथ 1906 ई. में कलकत्ता में होनेवाले काँग्रेस अधिवेशन में उदारवादियों और उग्रवादियों के बीच संघर्ष की आशंका उत्पन्न हुई हालाँकि दादाभाई नौरोजी के चातुर्य्य से उस समय यह संकट टल गया, किन्तु सन् 1907 ई. के सूरत अधिवेशन में दोनों दलों में संघर्ष मुखर हो गया तथा कॉंग्रेस गरम दल और नरम दल-दो दलों में विभक्त हो गयी। इस प्रकार जो उदारवादी सम्पूर्ण काँग्रेस का ही नेतृत्व करते थे वे अब केवल एक गुट का ही नेतृत्व करने लगे।</p>\r\n<p>सक्रिय राष्ट्रीयता में विश्वास करने वाले लोगों में कुछ लोग आक्रामकता में विश्वास रखते थे। फलतः सक्रिय राष्ट्रीयता की दो शाखाएँ हो गयीं— उग्रवादी और अग्रघष राष्ट्रवादी (Aggressive Nationalists) । जो लोग सक्रियता में विश्वास रखते थे, उन्हें उग्रवादी कहा गया तथा जो लोग आक्रामकता में विश्वास रखते थे उन्हें अग्रघर्षी राष्ट्रवादी कहा गया। बाद में सन् 1916 ई. में एनी बेसेण्ट की मध्यस्थता एवं बीच-बचाव के कारण नरम दल और गरम दल में पुनः मेल हो गया। परन्तु, उस मेल से उदारवादियों को कोई खास राहत न मिली। मॉण्टफोर्ड योजना की स्वीकृति के प्रश्न को लेकर पुनः दोनों दलों में मतभेद हो गया तथा उदारवादियों ने कॉंग्रेस से अलग होकर एक नया दल बनाया। सन् 1919 ई. के बाद जब गाँधीजी असहयोगी गाँधी के रूप में भारतीय रंगमंच पर आये, तो उदारवादियों ने उनका विरोध किया। परन्तु उस समय भी उदारवादियों की हार हो गयी। तत्पश्चात् गाँधीजी के सबल नेतृत्व के कारण धीरे-धीरे गरम और नरम दल का झगड़ा ही समाप्त हो गया</p>',8,'2024-10-23 16:19:01','2024-10-23 16:21:41','','Publish',0,'open',35,17),('राष्ट्रीय आन्दोलन में महात्मा गाँधी के योगदान','contribution-of-mahatma-gandhi-to-the-national-movement',2,'<p>आधुनिक भारत के इतिहास में महात्मा गाँधी को बहुत उच्च एवं महत्त्वपूर्ण स्थान प्राप्त है। वे हमारे राष्ट्रीय आन्दोलन के सबसे बड़े सेनानी, महान् नेता तथा भारत माता के सच्चे सपूत थे। उन्होंने अपनी मेधाशक्ति, दृढ़संकल्प, कुशाग्रबुद्धि, धैर्य एवं असीम साहस से अँगरेजों के विरुद्ध भारत के संघर्ष की नाव को स्वतंत्रता की मंजिल तक पहुँचाया। उनके त्याग और बलिदान के कारण ही उन्हें राष्ट्रपिता कहा जाता है। हमारे देश के लाखों लोगों का त्याग शहीदों का लहू बेकार जाता यदि राष्ट्रीय आन्दोलन को गाँधीजी का मार्गदर्शन नहीं मिलता। गाँधीजी के मार्गदर्शन के कारण ही हमारा देश स्वतंत्र हो सका।</p>\r\n<p>देश के इस महान् सपूत का जन्म 2 अक्टूबर, 1869 को गुजरात के पोरबन्दर में एक सम्पन्न वैश्य परिवार में हुआ था। इनके पिता करमचन्द गाँधी राजकोट रियासत के दीवान थे। 1887 ई. में राजकोट से ही मैट्रिक की परीक्षा पास करने के उपरान्त ये बैरिस्ट्री पढ़ने के लिए इंगलैण्ड चले गये। बैरिस्ट्री की परीक्षा पास कर ये स्वदेश लौटे और अपनी वकालत प्रारम्भ की। 1893 ई. में एक मुकदमे के सिलसिले में इन्हें दक्षिण अफ्रीका जाना पड़ा। अफ्रीका में उनका प्रवास उनके जीवन की एक अविस्मरणीय घटना बन कर रह गयी क्योंकि इस काल में वे घटनायें घटीं जिसने उन्हें संसार के इतिहास में अमर बना दिया। उस समय दक्षिण अफ्रीका की गोरी सरकार रंगभेद की नीति का पालन कर रही थी। </p>\r\n<p>सरकार की इस नीति के कारण वहाँ के भारतीयों की स्थिति अत्यन्त दयनीय थी। आये दिन अँगरेजों के हाथों उन्हें अपमानित होना पड़ता था। महात्मा गाँधी ने अँगरेजों की इस नीति का घोर विरोध किया और अपने विरोध को एक आन्दोलन का रूप देने के लिए \"नेटाल इण्डियन कॉंग्रेस\" का संगठन किया। लोगों को संगठित करने तथा प्रचारकार्य के लिए उन्होंने कुछ अखबार का भी प्रकाशन किया। उन्होंने रंगभेद की नीति के विरुद्ध सत्याग्रह एवं अहिंसात्मक आन्दोलन चलाया। प्रथम बार किसी व्यक्ति ने निरंकुश राजनीतिक सत्ता के विरुद्ध सत्याग्रह और अहिंसा जैसे अस्त्रों का प्रयोग किया था और इसमें सफलता मिली थी। राजनीतिक संघर्ष में अहिंसा और सत्याग्रह का अस्त्र गाँधीजी की अनोखी देन थी। गाँधीजी के आन्दोलन के समक्ष सरकार को झुकना पड़ा और भारतीयों को कई अमानुषिक कानूनों से मुक्ति मिली। गाँधीजी की इस विजय से उनकी ख्याति सा विश्व में फैल गयी। इसका प्रभाव भारत के राष्ट्रीय आन्दोलन पर भी पड़ा। उनके आन्दोलन ने यहाँ क्रांतिकारियों को बहुत प्रेरित किया।</p>\r\n<p>इस आन्दोलन के दौरान ही गाँधीजी का भारत के अन्य राष्ट्रीय आन्दोलन के नेताओं से परिचय हुआ। गाँधीजी गोपाल कृष्ण गोखले से बहुत प्रभावित हुए और उन्हें अपना राजनीतिक गुरु स्वीकार किया। 1912 ई. में गोखले दक्षिण अफ्रीका भी गये और गाँधीजी से उनकी आत्मीयता और बढ़ गयी।</p>\r\n<p>अफ्रीका में अपनी विजय पताका फहराने के पश्चात् 1915 ई. में गाँधीजी भारत लौटे। उनके महान् कार्यों के बदले कृतज्ञ देशवासियों ने उनका शानदार स्वागत किया। यहाँ आने के बाद एक वर्ष तक मौन रहकर वे भारत की स्थिति का अध्ययन करते रहे।</p>\r\n<p>गाँधीजी ने भारत में अपने राजनीतिक जीवन की शुरुआत बिहार के चम्पारण जिले से की। वहाँ के एक किसान ने इन्हें निलहे अँगरेज जमीन्दारों के अत्याचारों के बारे में बताया और किसानों को इन अत्याचारों से मुक्ति दिलाने की याचना की। गाँधीजी ने अपना अचूक अस्त्र अहिंसात्मक सत्याग्रह का व्यवहार किया और किसानों को अँगरेज जमीन्दारों के शोषण से मुक्त कराया। 1918 ई. में उन्होंने गुजरात के खेड़ा नामक स्थान में भी किसानों के समर्थन में अपना आन्दोलन चलाया और सरकार को समझौता करने पर विवश किया।</p>\r\n<p>सन् 1919 ई. से गाँधीजी भारत की राजनीतियों में सक्रिय रूप से कूद पड़े। इसलिए इतिहासकारों ने 1919 से ही \'गाँधी युग\" का प्रारम्भ माना है। गाँधीजी ने राष्ट्रीय आन्दोलन को एक नया दर्शन, एक नयी विचारधारा प्रदान की और इसके प्रमुख नायक बन गये। 1919 ई. में पास हुए दमनकारी काला कानून रॉलेट ऐक्ट ने गाँधीजी को अँगरेज सरकार के विरुद्ध अहिंसात्मक आन्दोलन एक बड़े पैमाने पर प्रारम्भ करने का अवसर प्रदान किया। गाँधीजी गिरफ्तार कर लिये गये। इस आन्दोलन की प्रतिक्रिया पंजाब में भी हुई। लेकिन वहाँ अप्रील 1919 ई. में अमृतसर के जालियाँवाला बाग में एक निहत्थी एवं शान्तिपूर्ण सभा पर अँगरेजों ने अन्धाधुन्ध गोलियाँ चलायीं और सैकड़ों भारतीयों को मार डाला और हजारों को घायल कर दिया। अँगरेजों की इस पाशविकता से गाँधीजी बहुत दुःखी हुए और उन्होंने अपने आन्दोलन को और तीव्र करने का निश्चय किया।</p>\r\n<p>प्रथम विश्व-युद्ध के पश्चात् अँगरेजों द्वारा तुर्की के साथ अपमानजनक व्यवहार के विरुद्ध भारत के मुसलमानों ने खलीफा को बचाने के लिए 1919 ई. में खिलाफत आन्दोलन प्रारम्भ किया। गाँधीजी ने हिन्दू-मुस्लिम एकता स्थापित करने के उद्देश्य से खिलाफत आन्दोलन का समर्थन किया। यद्यपि खिलाफत आन्दोलन अपने लक्ष्यों को प्राप्त करने में निष्फल रहा, तथापि इससे देश में हिन्दू-मुस्लिम एकता स्थापित हुई और गाँधीजी को असहयोग आन्दोलन प्रारम्भ करने की प्रेरणा मिली।</p>\r\n<p>1 अगस्त 1920 ई. को गाँधीजी ने ब्रिटिश राज्य के विरुद्ध उनके शासन को पंगु बनाने के उद्देश्य से असहयोग आन्दोलन प्रारम्भ किया। इस आन्दोलन के आह्वान में उन्होंने सभी स्तर पर सरकार से असहयोग करने की अपील भारतीयों से की। उनके आह्वान पर हजारों विद्यार्थियों ने शिक्षण संस्थाओं का बहिष्कार किया बुकीलों ने अदालतों का बहिष्कार किया और बहुत से लोगों ने सरकारी नौकरियों पर लात मार दी। गाँधीजी ने स्वयं सरकार को अपनी उपाधिं लौटा दी। आन्दोलन पूर्ण अहिंसात्मक था तथा इसका प्रभाव देश के एक बड़े भाग में था। किन्तु उत्तरप्रदेश के चौरी-चौरा कस्बे में आन्दोलनकारियों की एक क्रोधित भीड़ ने एक थाने में आग लगा दी और 22 सिपाहियों और एक दारोगा को जला कर मार डाला। आन्दोलन में हिंसा के प्रवेश से गाँधीजी को अत्यन्त दुःख हुआ और उन्होंने आन्दोलन को स्थगित कर दिया। ब्रिटिश सरकार ने उन्हें गिरफ्तार कर राजद्रोह के अपराध में उन पर मुकदमा चलाया और छः वर्ष कैद की सजा दी। लेकिन दो वर्ष बाद ही अस्वस्थता के कारण गाँधीजी जेल से छोड़ दिये गये।</p>\r\n<p>जेल से छूटने के पश्चात् गाँधीजी ने अपना समय रचनात्मक कार्यक्रमों में लगाया। अपने रचनात्मक कार्यक्रमों में हरिजनोद्धार, खादी, साम्प्रदायिक सद्भावना एवं एकता, ग्रामोद्योग, मद्य-निषेध, राष्ट्रभाषा का प्रचार, आर्थिक समानता, विद्यार्थियों एवं मजदूरों का संगठन, ग्राम एवं नारी उत्थान आदि विषयों पर जोर दिया। इन कार्यक्रमों के द्वारा गाँधीजी देश में जागरण लाना चाहते थे तथा देश की गरीबी एवं पिछड़ेपन को दूर करना चाहते थे।</p>\r\n<p>1927 ई. में देश की राजनीतिक स्थिति का अध्ययन करने के उद्देश्य से भारत में साइमन कमीशन का आगमन हुआ। इस कमीशन के सभी सदस्य अँगरेज थे। इस कमीशन से न्याय की आशा करना बेकार था। अतः गाँधीजी के नेतृत्व में इस कमीशन का देशव्यापी बहिष्कार किया गया। यह कमीशन जहाँ कहीं भी गया इसका स्वागत हड़ताल, जुलूस एवं \"साइमन वापस जाओ\" के नारे से किया गया। इस बहिष्कार के आन्दोलन ने राष्ट्रीय जागरण के कार्य को आगे बढ़ाया।</p>\r\n<p>26 जनवरी 1930 ई. को सारे देश में स्वाधीनता दिवस मनाया गया। इसी वर्ष गाँधीजी ने ब्रिटिश राज्य के विरुद्ध सविनय अवज्ञा आन्दोलन प्रारम्भ किया। 6 अप्रैल 1930 को दंडी पहुँचकर उन्होंने अपने अनुयायियों के साथ नमक-कानून को भंग किया। इसके बाद देश में जगह-जगह नमक बनाकर अँगरेजों के इस काले कानूनों को तोड़ा। जगह-जगह विदेशी वस्तुओं का बहिष्कार हुआ, दुकानों पर धरना दिया तथा विद्यार्थियों ने स्कूल-कॉलेजों का बहिष्कार किया। 60,000 लोगों के साथ गाँधीजी को जेल में ठूंस दिया गया।</p>\r\n<p>अक्टूबर महीने में लंदन में गोलमेज सम्मेलन का आयोजन हुआ। इस सम्मेलन में भाग लेने के लिए सरकार ने गाँधीजी को मुक्त कर दिया। परन्तु मुस्लिम लीग तथा अन्य साम्प्रदायिक तत्त्वों के कारण यह सम्मेलन असफल रहा। लंदन से गाँधीजी खाली हाथ लौटे। भारत लौटकर गाँधीजी ने पुनः सविनय अवज्ञा आन्दोलन चलाने का निश्चय किया। गाँधीजी पुनः गिरफ्तार कर लिये गये और काँग्रेस एक अवैध संस्था घोषित कर दी गयी। 1932 ई. में ब्रिटिश शासन के साम्प्रदायिक निर्णय के विरुद्ध जेल में ही उन्होंने आमरण अनशन प्रारम्भ किया। अन्त में हरिजन नेता डॉ. अम्बेदकर की मध्यस्थता में पूना पैक्ट हुआ और हरिजनों के प्रश्न पर गाँधीजी एक सम्मानजनक समझौता करने में सफल हुए। 1939 ई. में जब द्वितीय विश्व-युद्ध प्रारम्भ हुआ तो ब्रिटिश सरकार ने कॉंग्रेस से पूछे बगैर भारत को युद्ध में शामिल होने की घोषणा की। गाँधीजी ने इसका विरोध किया और युद्ध के उद्देश्यों की घोषणा की माँग की। इधर भारत पर जापानी आक्रमण का खतरा बढ़ता ही जा रहा था। अतः गाँधीजी ने अँगरेजों के विरुद्ध आन्दोलन प्रारम्भ करने के पूर्व सरकार से समझौता करने का प्रयास किया। परन्तु सरकार गाँधीजी की बातों को मानने के लिए तैयार नहीं थी । अतः 1940 ई. में उन्होंने \"व्यक्तिगत सत्याग्रह\" के द्वारा सरकार को झुकाने का प्रयास किया परन्तु इसका कोई उल्लेखनीय परिणाम नहीं निकला।</p>\r\n<p>अतः 7 अगस्त 1942 ई. को गाँधीजी ने \'भारत छोड़ो\' आन्दोलन प्रारम्भ किया। 8 अगस्त को गाँधीजी तथा देश के सभी प्रमुख नेता गिरफ्तार कर लिये गये। नेताविहीन जनता भटक गयी और भारत छोड़ो आन्दोलन हिंसात्मक हो गया तथा देश के कई भागों में आगजनी, तोड़-फोड़ तथा हिंसा की घटनायें हुई। पूना के आगा खाँ पैलेस में बन्दी गाँधीजी को अपने प्रिय सचिव एवं पत्नी कस्तूरबा की मृत्यु का दुःख झेलना पड़ा। 1944 ई. में अस्वस्थता के कारण गाँधीजी जेल से मुक्त कर दिये गये।</p>\r\n<p>सितम्बर 1944 ई. में गाँधीजी ने बम्बई में जिन्ना से मुलाकात की और वार्ता के द्वारा हिन्दू-मुस्लिम समस्या का हल ढूँढ़ने की कोशिश की। लेकिन जिन्ना की हठधर्मी के कारण इस समस्या का कोई हल नहीं निकला और लीग अपनी पाकिस्तान की माँग पर अड़ी रही। जुलाई 1946 ई. में संविधान सभा के निर्वाचन में कॉंग्रेस को स्पष्ट बहुमत प्राप्त हुआ। अपनी माँग को मनवाने के लिए 16 अगस्त को मुस्लिम लीग ने \"प्रत्यक्ष कार्यवाही\" (Direct Action) प्रारम्भ की और हिन्दुओं पर भयंकर आक्रमण आरम्भ हुआ। देश में दंगे बड़े पैमाने पर भड़क उठे। गाँधीजी ने दंगा पीड़ित क्षेत्रों का दौरा किया और दंगाइयों को शान्त करने की कोशिश की। वे नोवाखाली भी गये और घूम-घूम कर अपने शान्ति-संदेशों का प्रचार किया। उन्होंने बिहार के दंगा पीड़ित क्षेत्रों का भी दौरा किया। 15 अगस्त 1947 ई. को जिस दिन देश आजाद हुआ उस दिन भी गाँधीजी कलकत्ता के दंगा पीड़ित क्षेत्रों का दौरा करने में लगे हुए थे।</p>\r\n<p>आजादी के बाद से जनवरी 1948 ई. तक अर्थात् अपने मृत्यु के दिनों तक गाँधीजी दंगा से पीड़ित लोगों के आँसू पोंछने में लगे रहे। अन्त में 30 जनवरी 1948 ई. को एक धर्मान्ध हिन्दू ने गाँधीजी को गोली मारकर उसकी हत्या कर दी। इस प्रकार साम्प्रादायिक सौहार्द स्थापित करने के प्रयत्न में ही गाँधीजी की जान गयी। उनकी हत्या से भारत ही नहीं, वरन् सम्पूर्ण विश्व दुःख के महासागर में डूब गया। क्योंकि गाँधीजी केवल भारत के ही नहीं, वरन् सम्पूर्ण मानवजाति के नेता थे, मित्र थे, पथप्रदर्शक थे। उनकी मृत्यु ने आधुनिक काल के मसीहा को हमसे छीन लिया। महात्मा गाँधी भारतीय राष्ट्रीयता के प्रतीक, सत्य, अहिंसा के सच्चे उपासक थे। उन्होंने भारतीय जनता को अभय का पाठ पढ़ाया। वे गरीबों के मसीहा थे तथा साम्प्रदायिक एकता के सच्चे समर्थक थे। हरिजनोद्धार, नारी उत्थान तथा ग्राम-उत्थान के लिए उनके द्वारा किया गया कार्य स्तुत्य है। वे आधुनिक भारत के निर्मात्ता थे। इसीलिए उन्हें राष्ट्रपिता की सम्मानजनक उपाधि दी गयी। भारत की जनता अपने प्यारे नेता को बापू कहते हर्ष से फूले नहीं सनाती थी।</p>',1,'2024-10-23 16:19:01','2024-10-23 16:25:05','','Publish',0,'open',35,18),('चीन में साम्यवाद का विकास उदय के कारण','reasons-for-the-rise-of-communism-in-china',2,'<p>चीन में साम्यवाद का विकास विश्व की एक महत्त्वपूर्ण घटना थी। चीन में इसके उदय के निम्नलिखित कारण थे-</p>\r\n<h2>चीन में साम्यवाद उदय के कारण</h2>\r\n<h3 class=\"atech\">रूसी क्रांति का प्रभाव</h3>\r\n<p> पेरिस शांति सम्मलेन के पश्चात चीन के लोगों की यह धारणा बन गई कि बोल्शेविक विचारधारा के माध्यम से ही चीन का उद्धार संभव है। परिणामस्वरूप चीन में कई साम्यवादी संस्थाओं की स्थापना की गई और वहाँ संगठित साम्यवादी आंदोलन का आरंभ हुआ।</p>\r\n<h3 class=\"atech\">पश्चिमी शक्तियों के प्रति चीन में असंतोष</h3>\r\n<p> चीन की जनता चीन में विदेशियों के प्रभाव से बहुत असंतुष्ट थी। अपने विरोध को ऊर्जा देने के लिये उसे एक सशक्त और क्रांतिकारी दल की आवश्यकता थी। यह शक्ति और भावना उन्होंने साम्यवादियों में देखी।</p>\r\n<h3 class=\"atech\">चीन में आर्थिक विकास</h3>\r\n<p> साम्यवाद मुख्यतः एक आर्थिक विचार था। साम्यवाद का घोषित उद्देश्य वर्ग-संघर्ष को समाप्त करके इसके स्थान पर आर्थिक समानता स्थापित करना था। उस समय चीन में आर्थिक असमानता की अतिव्याप्ति ने साम्यवाद के उदय के लिये माहौल तैयार कर दिया।</p>\r\n<h3 class=\"atech\">शिक्षा का प्रसार</h3>\r\n<p> 19वीं सदी के अंत तक चीन में शिक्षा के कई केंद्र स्थापित हो चुके थे। शिक्षित जनता को भ्रमित नहीं किया जा सकता था। वह रूस में हो रही घटनाओं के प्रभावों को ग्रहण कर रही थी। इस प्रकार जनता साम्यवाद की ओर आकर्षित हुई।</p>\r\n<h3 class=\"atech\">माओ का नेतृत्व</h3>\r\n<p> इस समय चीन में माओत्से तुंग जैसे क्रांतिकारी नेता का मज़दूर और निम्न वर्ग पर व्यापक प्रभाव था। माओ में असाधारण सांगठनिक क्षमता थी। माओ के प्रयासों से ही चीन में संगठित साम्यवादी आंदोलन आरंभ हुआ।</p>\r\n<h2>चीन की साम्यवादी क्रांति का विश्व राजनीति पर प्रभाव</h2>\r\n<p>जब माओ ने संपूर्ण चीन में एक सत्ता की घोषणा की तो साम्यवाद की इस विजय ने एशिया और अफ्रीका के कई देशों को साम्यवाद की ओर आकर्षित किया।साम्यवाद की बढ़ती शक्ति के कारण पश्चिमों ताकतों और साम्यवादियों के मध्य एक प्रकार से शक्ति-संतुलन स्थापित हुआ।</p>\r\n<p>चीन में साम्यवाद की स्थापना के बाद यह अनुमान लगाया गया कि चीन , सोवियत रूस का नेतृत्व स्वीकार करेगा, परंतु कुछ ही वर्षों में वह रूस का प्रतिद्वंद्वी बन गया।अमेरिका ने जापान के लोकतंत्र को दृढ़ता प्रदान करने वाली नीति अपनाई, ताकि जापान अपने पड़ोसी साम्यवादी देशों के प्रभाव से बचा रहे।</p>\r\n<p>इस तरह साम्यवाद की राह पर चलकर चीन ने एक उभरते शक्तिशाली राष्ट्र की छवि पेश करते हुए दुनिया को यह संदेश दिया कि अब विश्व राजनीति के मुद्दों पर निर्णय केवल वाशिंगटन और मॉस्को में नहीं होंगे, उनमें अब बीजिंग भी भागीदार होगा।</p>\r\n',28,'2024-10-23 16:19:01','2024-10-23 16:26:49','','Publish',0,'open',7,19),('ब्रह्म समाज का सिद्धांत और योगदान','objective-principles-and-contribution-of-brahmo-samaj',2,'<p>राजा राममोहन राय भारतीय समाज में प्रचलित कुरीतियों से बड़े दुःखी रहते थे और उनको दूर करना चाहते थे। अपने उद्देश्य पूर्तिके लिए अथार्त धर्म और समाज के दोष में सुधार के लिए उन्होंने 20 अगस्त 1898 में एक संस्था\" ब्रह्म सभा की स्थापना की जिसकोबाद मे नाम बदलकर \"ब्रह्म समाज\" कर दिया। इस समाज के कार्यक्रम में हिन्दू, मुस्लिम और इसाई तीनों धर्मों के अच्छे गुणों कासमावेश किया गया।</p>\r\n<p>राजा राम मोहन राय के प्रभावशाली नेतृत्व में ब्राह्म समाज ने चतुर्मुखी उन्नति की। उन्होंने जिस आन्दोलन का पुत्रणा किया उनका उत्त उसकी मृत्यु के बाद भी न हो सका। उनके अपने कामों को पूरा करने का भार <strong>श्री देवेन्द्रनाथ टेगोर</strong> तथा <strong>केशवचन्द्र सेन</strong> ने किया। इनलोगों से ब्रह्म समाज को नियमबध कर उसे पुनजीवित किया तथा राजा साहब के विचारों का उत्साह से प्रचार किया। लेकिन दुर्भाग्यवश, इसी समय केशवचन्द्र सेन रतथा अन्य ब्रहम समाजियों में मतभेद हो गया। जिसके फलस्वरूप मौलिक ब्रह्म समाज से अलग होकर केशवचन्द्र सेन से एक नवीन ब्रह्म समाज की स्थापना की। केशवचन्द्र सेन की इस संस्था ने समाज सुधार के कार्यों को बहुत आगे बढ़ाया। इस संघ की अनेक शाखाएँ बंगाल से बाहर कायम हुई। वास्तव में, राजा राममोहन राय स्थापित ब्रह्म समाज भारतीय समाज-सुधार-आन्दोलन का आधा साबित हुआ। इस इसी का अनुसरण करते हुए देश के अन्य आगों में और कई संस्थाएँ कायम हुई।</p>\r\n<h2>ब्रह्म समाजा उद्देश्य </h2>\r\n<ul>\r\n    <li><p>हिन्दू समाज मे व्याप्त बुराइयों को दूर करना।</p></li>\r\n    <li><p>सभी धर्मों का आपसी मेल मिलाप हो।</p></li>\r\n    <li><p>इसाइयों के धर्म का भारत में बढ़ता प्रभाव को रोकना।</p></li>\r\n    <li><p>एकेश्वरवाद में आसका आस्था और उसके सर्वशक्तिमान होने विश्वास।</p></li>\r\n    <li><p>सभी को पूजा का अधिकार हो।</p></li>\r\n    <li><p>सच्चे हृदय से प्रार्थना करना।</p></li>\r\n    <li><p>आत्मा के अजर-अमर होने में विश्वास करना।</p></li>\r\n    <li><p>सभी धर्मों के प्रति की आदर भावना</p></li>\r\n    <li><p>मोक्ष की प्राप्ति के लिए पाप का त्याग एवं प्रयाशिचत करना आवश्यक है।</p></li>\r\n</ul>\r\n<h2>ब्रह्म समाज के सिद्धांत</h2>\r\n<h3>धार्मिक</h3>\r\n<ul>\r\n    <li><p>ईश्वर एक है। वह संसार का स्रष्टा पालक और रक्षक है; उसकी शक्ति, प्रेम, न्याय और पवित्रता असिमित है। </p></li>\r\n    <li><p>जीवात्मा अमर है; उसमें उन्नति करने की असीज़ क्षमता है और वह अपने कार्यों के लिए भगवान के सामने उत्तरदायी है। आध्यात्मिक उन्नति के लिए प्रार्थना, भगवान का आश्रय और उसके अस्तित्व की अनुभूति आवश्यक है।</p></li>\r\n    <li><p>किसी भी बनाई हुई वस्तु को ईश्वर समझकर नहीं पूजना चाहिए और न की किसी पुस्तक या पुरुष को निर्वाह अथवा मोक्ष का एकमात्र साधन मानना चाहिए।</p></li>\r\n</ul>\r\n<h3>सामाजिक</h3>\r\n<ul>\r\n    <li><p>अस्पृश्यता का विनाश होना आवश्यक है।</p></li>\r\n    <li><p>बाल विवाह पर रोक लगाना परम आवश्यक है।</p></li>\r\n    <li><p>विधवा-विवाह का प्रचार</p></li>\r\n    <li><p>बाल-हत्या अपराध है।</p></li>\r\n</ul>\r\n<h2>विचारधारा</h2>\r\n<h3>ब्रह्म समाज की विचारधाराएँ समर्थक के अनुसार</h3>\r\n<p>एकेश्वरवाद ,आत्मा की अमरता, स्त्रि शिक्षा, विधवा विवाह, स्त्रि का उत्तराधिकार , अंतरजातिय विवाह, सर्वधर्म का समर्थन, अंग्रेजी शिक्षा का समर्थन</p>\r\n<h3>ब्रह्म समाज की विचारधाराएँ विरोधी तत्य अनुसार</h3>\r\n<ul>\r\n    <li><p>समाजिक कुरितियों का विरोध जैसे - सती प्रथा, बाल विवाह, दुविवाह, कन्याओं की हत्या, इत्यादि का विरोध। </p></li>\r\n    <li><p>धार्मिक बुराइयों का विरोध पर्दा प्रथा, छुआ - छुत, जति एय मूर्ति पूजा का विरोध: पुरोहितवाद का विरोध, कर्मकाण्ड, आडम्बर विरोध अविश्वास का</p></li>\r\n</ul>\r\n\r\n<h2>ब्रह्म समाज का योगदान/ देन</h2>\r\n<h3 class=\"atech\">सामाजिक सुधार</h3>\r\n<p>ब्रहन समाज ने बाल विवाह, कन्या व वर का क्रय विक्रय, कन्या वध, सती प्रथा आदि का विरोध किया, विधवा विवाह का समर्थन किया। छुआ-छूत, अस्पृश्यता, जाति पाँति आदि के विरुद्ध बीड़ा उठाया।</p>\r\n<h3 class=\"atech\">धार्मिक सुधार</h3>\r\n<p>पाखण्ड, आडम्बर, पुरोदिववाद, कर्मकांड का विरोधा मूर्ति-पूजा, अनेकेश्वरवाद के विरुद्ध आवाज उठाई, मानव धर्म ची थी की दुहाई दी। इस विश्वास का प्रसार किया कि आत्मा एक है।</p>\r\n<h3 class=\"atech\">शिक्षा में सुधार</h3>\r\n<p>हिन्दू कॉलेज, रुइंगलिश स्कूल आदि शिक्षा की संस्थाओं दुवारा भारतीय को पाश्चात्य विज्ञान का अध्ययन करवाया। और स्त्रियों के लिए भी \"बैथून कॉलेज\" तथा अन्य शिक्षणालयों की स्थापना की। आज भी अनेक स्थानों पर ब्रह्म समाज के स्कूल आदि चल रहे हैं</p>\r\n<h2 class=\"atech\">निसकर्ष</h2>\r\n<p>इस तरह हम देखते है की राजा राममोहन राय द्वारा स्थापित ब्रह्म समाज ने हिंदू कानून में सुधार करने के लिए आवाज उठाई मुद्रणालयों पर लगे प्रतिबंध का विरोध किया राजाराम मोहन राय एवं अन्य ब्रह्म समाजियों ने भारतीय में नई चेतना जागृति की और देश को राष्ट्रीयता के विकास-पथ पर बढ़ाया। </p>',39,'2024-10-23 16:19:01','2024-10-24 08:32:49','','Publish',0,'open',60,20),('1911 ई की चीन की क्रांति की कारण और परिणाम','causes-and-consequences-of-the-chinese-revolution-of-1911',2,'<p>1899 ईo में हुए बॉक्सर विद्रोह भले असफल हो गया था लेकिन इस विद्रोह ने 1911 ईo में हुई चीन की क्रांति की नीव खड़ी कर दी थी। जनता में कमजोर मांचू सरकार के खिलाफ लगातार असंतोष बढ़ता जा रहा था। लोग इस कमजोर चीनी सरकार को उखाड़ फेकने के किये अमादा थे। अत: चीन में क्रांति की शुरुआत हुई.</p>\r\n<h2>चीन हुई 1911 ईo की क्रांति के प्रमुख कारण</h2>\r\n<h3 class=\"atech\">चीन में विदेशी हस्तक्षेप का बढ़ना</h3>\r\n<p> चीन में बॉक्सर विद्रोह के बाद इंग्लॅण्ड, अमेरिका, फ्रांस, रूस और जापान जैसे देशों का हस्तक्षेप बहुत बाद गया था। इन देशों ने चीन के साथ संधि करके चीन पर अपना प्रभुत्व स्तापित कर लिया था। पश्चिमी और यूरपीय देशों ने चीन में जमकर शोषण करना आरम्भ कर दिया। चीन के महत्वपूर्ण व्यापारिक केंद्रों पर अपना प्रभुत्व स्थापित कर लिया। चीन की सरकार नाममात्र की सरकार थी। चीन के लगभग सभी फैसले विदेशी ताकतें ही करती थी। इस सबको देख कर चीनी जनता में असंतोष की भावना बढ़ने लगी। वे तत्कालीन चीनी सरकार और इन विदेशी ताकतों को देश से बहार निकलना चाहते थे। </p>\r\n<h3 class=\"atech\">मांचू सरकार के प्रति घृणा</h3>\r\n<p> मांचु सरकार विदेशी ताकतों की मदद से चल रही थी। देश में होने वाले विद्रोहों को कुचलने के लिए भी विदेशी ताकतों का सहारा लेती थी। देश में विदेशी ताकतों की मनमानी का विरोध भी नहीं कर पाती थी। ऐसे में मांचू सरकार की कमजोरियों का पता चीन की जनता को पता चल गया। उनको पता था कि ऐसी कमजोर सरकार देश की रक्षा नहीं कर सकती थी। वह विदेशी ताकतों की कठपुतली बन गई थी। इसीलिए चीनी जनता में मांचू सरकार के प्रति घृणा बढ़ती चली गई। </p>\r\n\r\n<h3 class=\"atech\">जनसँख्या में वृद्धि</h3>\r\n<p> 20 वीं शताब्दी की शुरुआत तक चीन की जनसँख्या में काफी तेजी से वृद्धि हुई। 1911 ई तक चीन की आबादी में लगभग 5 करोड़ की वृद्धि हुई। लेकिन चीन की सरकार ने जनसँख्या वृद्धि के अनुपात में न कृषि उत्पादन को बढ़ाया और न आवश्यक संसाधनों को बढ़ाने की कोशिश की। नतीजतन देश में खाने- पीने की वस्तुओं से लेकर अन्य दैनिक जरुरत की वस्तुओं की कमी हो गई। इस वजह से भुखमरी, भ्रष्टाचार, गरीबी जैसे समस्याऐं पैदा होने लगी। लोग अपनी जरूरतों को पूरा करने के लिए लूटपाट भी करने लगे थे। सरकार इन सब से निपटने में नाकाम रही। इसीलिए लोगों म असंतोष बढ़ता चला गया। </p>\r\n<h3 class=\"atech\">प्राकृतिक आपदाएं</h3>\r\n<p> 1910-11 में चीन की कई नदियों में भीषण बाढ़ आई। इतिहासकारों में मुताबिक ये पिछले 40 वर्षों की सबसे विकराल और भयानक बाढ़ थी। इस बाढ़ से जान माल की भीषण क्षति हुई। लाखों लोग बेघर हो गए। मांचू सरकार इस गंभीर संकट का सामना न कर सका। चीनी सरकार के द्रारा इस संकट के प्रति उपेक्षापूर्ण नीति ने देश में भीषण असंतोष को जन्म दिया। </p>\r\n\r\n<h3 class=\"atech\">प्रवासी मजदूर वर्ग का प्रभाव</h3>\r\n<p> चीन में बढ़ती आर्थिक संकट के कारण चीन के लोगों को अन्य देशों में पलायन करने पर मजबूर कर दिया। बड़ी संख्या में चीनी अमेरिका, फिलीपींस, कनाडा और सिंगापुर जैसे देशों की ओर अपनी आजीविका की खोज में चले गए। ऐसे प्रवासी चीनी मजदूरों की संख्या लगभग 25 लाख के आसपास थी। इन लोगों ने वहां से धन भेजना शुरू कर दिया। वे जब भी चीन आते थे वे उस देश की आर्थिक सम्पन्नता की बखान करते थे। ऐसे में चीन के मजदूर वर्ग के लोगों के मन में भी क्रांति की भावना का विकास होता गया.</p>\r\n<h3 class=\"atech\">बौद्धिक जागरण</h3>\r\n<p> 1905 में चीन में प्राचीन शिक्षा पद्धति का अंत हुआ। इसके बाद चीन के छात्रों को आधुनिक शिक्षा के लिए विदेश जाने को प्रेरित हुए। चीन की ईसाई मिशनरी भी प्रतिभावान छात्रों को उच्च शिक्षा के लिए विदेश भेजती थी। चीन के छात्रों पर वहां की शिक्षा, शासन पद्धति, और रहन सहन का काफी प्रभाव पड़ा। उन पर खासकर पश्चिमी सभ्यता के समानता, स्वतंत्रता और बंधुत्व के सिद्धांतों का गहरा प्रभाव पड़ा.<br> अत: चीनी विद्यार्थियों ने चीन की और पश्चिमी देशों की स्थिति का तुलनात्मक स्थिति का अध्ययन करना आरम्भ कर दिया। </p>\r\n<h3 class=\"atech\">तात्कालीन कारण</h3>\r\n<p> 1909 और 1911 के बीच पीकिंग के केंद्रीय सरकार के द्वाराअपनाई गई रेलवे निर्माण नीति और हॉकों की घटना इस विद्रोह की तात्कालीन कारण बनी। रेलवे लाइन की निर्माण विदेशी फर्मों अनुबंध किया गया थे। ये विदेशी फर्म ही इन रेलवे लाइनों का निर्माण कर रही थी। इस बात का विरोध करने के लिए चीनी नागरिक आंदोलन करना शुरू कर दिए थे। आंदोलनकारियों को सरकार गिरफ्तार करने लगी। आंदोलन जब चरम पर था। उसी समय 10 अक्टूबर 1911 को हॉकों में स्थित रुसी बस्ती के एक घर में बम विस्फोट हो गया। ये घर क्रांतिकारियों के बम निर्माण अड्डा था। इस विस्फोट के बाद रुसी अधिकारीयों ने तुरंत कार्रवाई करते हुए बहुत से क्रांतिकारियों को गिरफ्तार कर लिया। इसके बाद क्रांतिकारियों ने वायसराय के दफ्तर में आग लगा दी और क्रांति की आग भड़क गई.</p>\r\n<h2  class=\"atech\">1911 की चीनी क्रांति की परिणाम</h2>\r\n<p>चीन की 1911 की क्रांति के फलस्वरूप चीन के अन्तिम राजवंश (चिंग राजवंश) की समाप्ति हुई और चीनी गणतंत्र बना। यह एक बहुत बड़ी घटना थी। मंचू लोगों का शासन चीन पर पिछले तीन सौ वर्षों से चला आ रहा था जिसका अंत हो गया। बीसवीं शताब्दी में चीन एशिया का प्रथम देश था, जहाँ गणतांत्रिक सरकार की स्थापना हुई। चीन के क्रांतिकारियों ने फ्रांसवालों का अनुकरण किया और राजतंत्र का सदा के लिए अंत कर दिया।</p>',33,'2024-10-23 16:19:01','2024-10-24 08:34:01','','Publish',0,'open',6,21),('जालियाँवाला बाग हत्याकांड की उत्तरदायी परिस्थितियों का वर्णन','circumstances-responsible-for-the-jallianwala-bagh-massacre',2,'<p>भारतीय स्वतन्त्रता-संग्राम के इतिहास में सन् 1919 ई. का जालियाँवाला बाग हत्याकाण्ड सबसे दुःखद, निन्दनीय, प्राणहर एवं रोंगटे खड़ा कर देनेवाला बर्बर अत्याचार था। यह हत्याकाण्ड भारतवासियों को ही क्या, समस्त सभ्य संसार के रोंगटे खड़ा कर देनेवाला काण्ड था। इस घटना को सुनकर सभी ईमानदार एवं विचारसम्पन्न अँगरेज भी स्तब्ध रह गये। रामगोपाल के शब्दों में \"<i>यह अकृतज्ञ शासकों की कहानी है।</i> \"</p>\r\n<h2>जालियाँवाला बाग हत्याकाण्ड की उत्तरदायी परिस्थितियाँ</h2>\r\n<h3 class=\"atech\">दमनकारी कानूनों एवं मॉण्टफोर्ड सुधारों का विरोध</h3>\r\n<p>प्रथम विश्वयुद्ध के दौरान विद्रोहात्मक कार्रवाइयों के चलते \'भारत सुरक्षा अधिनियम पारित किया गया था। युद्ध समाप्ति के बाद यह अधिनियम अपने आप समाप्त हो जाता। परन्तु, सरकार को डर था कि रूसी क्रान्ति एवं भारतीय क्रान्तिकारी नेताओं से प्रभावित होकर कहीं भारतीय क्रांतिकारी भी सरकार के तख्ते को न उखाड़ फेंके। चूँकि युद्ध के दौरान भारतीयों का सहयोग प्राप्त करने के लिए अँगरेजों ने तरह-तरह के वादे किये थे, अतः समाप्ति के बाद कांग्रेस ने उन वचनों को पूरा करने को कहा। कांग्रेस ने अपने 1918 ई. के दिल्ली अधिवेशन में एक प्रस्ताव पारित कर सरकार से यह माँग की कि \"<i>उन समस्त कानूनों,     अध्यादेशों, अधिनियमों (Regulations) को समाप्त कर दिया जाय, जिनके चलते भारत का राजनीतिक समस्याओं पर स्वतन्त्रतापूर्वक     वाद-विवाद करना कठिन है तथा नेताओं को गिरफ्तार कर लिया जाता है और उन्हें देश से निर्वासित कर दिया जाता है।</i>\" इतना ही नहीं, कांग्रेस द्वारा मॉण्टफोर्ड सुधारों का डटकर विरोध किया गया। इस परिस्थिति में अँगरेजों को राष्ट्रीय आन्दोलन की गति तीव्र होने की आशंका थी। सरकार को अफगानिस्तान की ओर से भारतीय सीमा पर गड़बड़ी होने एवं उसी ओर से रूस द्वारा भारत पर आक्रमण होने का भी भय था। </p>\r\n<h3 class=\"atech\">नौकरशाही का कड़ा रुख</h3>\r\n<p> उपर्युक्त परिस्थितियों में राष्ट्रीय आन्दोलन को \'कुचलने एवं क्रान्तिकारियों का सामना करने के लिए नौकरशाही को ऐसे कानूनों की आवश्यकता थी, जो उसे असाधारण अधिकार प्रदान करे। अतः कांग्रेस की उचित माँग का उत्तर सरकार ने \'रॉलेट ऐक्ट\' जैसे काले कानून के रूप में दिया, जिसका समस्त भारत में व्यापक रूप से विरोध हुआ। </p>\r\n<h3 class=\"atech\">रॉलेट ऐक्ट का विरोध </h3>\r\n<p>\'रॉलेट ऐक्ट\' के प्रावधान बहुत ही कठोर और दमनात्मक थे। उसके अन्तर्गत सरकार किसी भी संदेहपूर्ण व्यक्ति को मुकदमा चलाये बिना ही नजरबन्द कर सकती थी। उस विधेयक की व्यवस्थाओं से ऐसा महसूस हुआ कि सरकार वैधानिक आन्दोलनों को भी कुचल देना चाहती है। उस विधेयक को \'काला - विधेयक\' की संज्ञा देकर संपूर्ण देश में उसका व्यापक विरोध किया गया। उस विधेयक का विरोध व्यवस्थापिका के गैर-सरकारी भारतीय, निर्वाचित तथा नामजद सभी सदस्यों ने समान रूप से किया। परन्तु, सरकार अपनी बात पर अड़ी रही और जरा भी नहीं झुकी। जनता के तीव्र विरोध के बावजूद वह विधेयक पारित हो गया। </p>\r\n<h3 class=\"atech\">हड़ताल व हिंसात्मक वारदातें</h3>\r\n<p> गाँधीजी \'रॉलेट ऐक्ट\' की धाराओं को पढ़कर  अत्यन्त दुःखी हुए और उन्होंने घोषणा की कि यदि \'रॉलेट ऐक्ट\' को असली रूप दिया गया, तो वे सत्याग्रह छेड़ देंगे। परन्तु, सरकार ने गाँधीजी की धमकी की तनिक भी परवाह नहीं की। फलतः गाँधीजी ने उस कानून का विरोध करने के लिए 30 मार्च, 1919 ई. की तिथि निश्चित की। यद्यपि बाद में इस तिथि को बदलकर 6 अप्रील कर दिया गया, परन्तु पकी सूचना हर जगह न पहुँच सकी। फलतः दिल्ली में हड़ताल 30 मार्च को ही शुरू गयी। </p>\r\n<p>स्वामी श्रद्धानन्द के नेतृत्व में दिल्ली में एक विशाल जुलूस निकाला गया तथा पुलिस और हड़तालियों के बीच हुए संघर्ष में 8 व्यक्ति मारे गये। तत्पश्चात् निश्चित कार्यक्रम के अनुसार समस्त देश में प्रदर्शन हुआ, शोकदिवस मनाया गया तथा उपवास रखे गये। बम्बई, कलकत्ता तथा पंजाब आदि स्थानों में पुलिस और जनता के बीच डटकर संघर्ष हुए। पंजाब और दिल्ली की घटनाओं को सुनकर गाँधीजी पंजाब एवं दिल्ली की ओर रवाना हुए। परन्तु, उन्हें रास्ते में ही गिरफ्तार करके बम्बई भेज दिया गया। गाँधीजी की गिरफ्तारी की खबर सर्वत्र जंगल की आग की तरह फैल गयी। गिरफ्तारी के विरोध में पंजाब में दंगे हुए, परन्तु सरकार ने उसे निर्दयतापूर्वक दबा दिया। 8 अप्रील को विधानसभा में यह घोषणा की गयी कि जो लोग उस आन्दोलन में भाग ले रहे हैं, उन्हें भयंकर परिणाम भुगतने होंगे। 10 अप्रील को अमृतसर के जिलाधीश ने डॉ. सत्यपाल और डॉ. किचलू (पंजाब के प्रभावशाली कांग्रेसी नेताद्वय) को गिरफ्तार कर किसी अज्ञात स्थान पर भेज दिया।</p>\r\n<p>डॉ. सत्यपाल और डॉ. किचलू की गिरफ्तारी ने जनता में सनसनी पैदा कर दी तथा जुलूस और मारपीट का दौर शुरू हो गया। अपने नेताओं की रिहाई की माँग को लेकर जब जनता का एक जुलूस मजिस्ट्रेट बंगले की ओर चला, तो फौजी सेना को बुलाकर उस पर गोलियाँ चलवायी गयीं, जिसमें दो व्यक्ति मरे और अनेक घायल हुए। क्रुद्ध भीड़ ने लौटते समय एक नेशनल बैंक में आग लगा दी तथा उसके मैनेजर को मार डाला। सरकार एवं सार्वजनिक इमारतों में भी आग लगायी गयी। इस दौर में 5 अँगरेजों को मार डाला गया तथा एक ईसाई पादरी महिला शोरऊड अघमरी अवस्था में पायी गयी।</p>\r\n<h2>जालियाँवाला बाग हत्याकाण्ड</h2>\r\n<h3 class=\"atech\">अमृतसर में फौजी शासन की बर्बरता</h3> \r\n<p>10 अप्रील की उपर्युक्त घटना के बाद सरकार ने भी बदले की भावना से काम करने का निश्चय किया। 10 अप्रील को ही अमृतसर में फौजी शासन की घोषणा कर दी गयी। जेनरल डायर को अमतृसर का सैनिक प्रशासक नियुक्त किया गया। 12 अप्रील को सभा-सम्मेलनों पर प्रतिबन्ध लगाने की घोषणा की गयी। स्मरण रहे कि अमतृसर की जनता ने इस घोषणा के पूर्व ही 10 अप्रील को हुई घटना के विरोध में 13 अप्रील को जालियाँवाला बाग में विशाल सभा करने का निश्चय किया था। सरकार की उपर्युक्त घोषणा की खबर लोगों तक अच्छी तरह नहीं पहुँच सकी थी। </p>\r\n<p>फलतः, हजारों लोग सभा में एकत्र हो गये। जब सभा में लगभग 20 हजार व्यक्ति एकत्रित हो गये, तो जेनरल डायर ने 200 भारतीय तथा 50 अँगरेज सैनिकों को लाकर बिना कोई पूर्व सूचना दिये निहत्थी भीड़ पर अंधाधुंध गोलियाँ चलवा दीं। गोलियाँ 10 मिनट तक चलती रहीं तथा 1650 गोलियाँ चलायी गयीं जिसमें, सरकारी प्रतिवेदन के अनुसार 400 लोग मरे तथा लगभग 1137 व्यक्ति घायल हुए। इंटर कमीशन के समक्ष बयान देते हुए गिरधारी लाल ने बताया था “मैंने सैकड़ों व्यक्ति को वहीं मरते देखा। सबसे खराब बात यह थी कि गोली उस दरवाजे की तरफ से चलायी जा रही थी जिससे होकर लोग भाग रहे थे। बहुत से लोग भागती हुई भीड़ के पैरों तले कुचलते गये। खून की धारा बह रही थी मेरा अनुमान है कि उस समय वहाँ एक हजार से अधिक आहत और मृत व्यक्ति थे। इस प्रकार यह हत्याकाण्ड सम्पूर्ण संसार के रोंगटे खड़ा कर देने वाला काण्ड था। </p>\r\n<h3 class=\"atech\">हंटर समिति की नियुक्ति</h3>\r\n<p>अमृतसर की घटना से भारतीयों की आत्मा काँप उठी। इस काण्ड का हर क्षेत्र में विरोध किया गया तथा चारों ओर इसकी निन्दा की गयी। रवीन्द्रनाथ ठाकुर ने इसके विरोध में \'सर\' की अपनी उपाधि सरकार को लौटा दी। पंजाब हत्याकाण्ड की जब चारों ओर निन्दा की गयी, तो सरकार ने हंटर की अध्यक्षता में एक जाँच समिति नियुक्त की। समिति ने अपने प्रतिवेदन में सरकार के अत्याचारों पर पर्दा डालने की कोशिश की। उसने सरकार के कार्यों को उचित ठहराया, परन्तु सरकार द्वारा अपनाये गये साधनों को अनुचित बतलाया। कांग्रेस ने भी महात्मा गाँधी, सी. आर. दास तथा मोतीलाल नेहरू को मिलाकर एक जाँच समिति की नियुक्त की।</p>\r\n<p>गाँधीजी के शब्दों में- \"<i>जैसे-जैसे जाँच बढ़ती गयी मुझे सरकार की निरंकुशता तथा उसके     तानाशाही रवैयों के ऐसे-ऐसे अत्याचारों का पता चलता गया, जिनके लिए मैं बिल्कुल तैयार न था और मुझे इससे बहुत पीड़ा     हुई।</i>\" हंटर समिति की जाँच के फलस्वरूप यद्यपि डायर को नौकरी से अलग कर दिया गया, लेकिन उसके द्वारा की गयी सेवाओं के लिए उसे 200 पौंड और एक सम्मान की तलवार भेंट की गयी। उसे ब्रिटिश साम्राज्य का \'शेर\' कहा गया।</p>\r\n<h2 class=\"atech\">परिणाम </h2>\r\n<p>जालियाँवाला बाग हत्याकाण्ड की जाँच के लिए गठित हंटर-समिति का प्रतिवेदन तथा प्रतिवेदन के आधार पर सरकार द्वारा की गयी कार्रवाइयों से यह स्पष्ट हो गया कि सरकार को भारतीयों के प्रति थोड़ी भी सहानुभति नहीं है। इस घटना के चलते गाँधीजी के मन से अँगरेजों की न्यायप्रियता के प्रति बचा खुचा विश्वास समाप्त हो गया। इस घटना ने, असहयोग आन्दोलन का मार्ग प्रशस्त कर दिया। इसके बाद राष्ट्रीय आन्दोलन का वैधानिक युग समाप्त हो गया तथा राष्ट्रीय आन्दोलन ने एक जन-आन्दोलन का रूप धारण किया।</p>',53,'2024-10-23 16:19:01','2024-10-24 08:35:07','','Publish',0,'open',19,22),('जापान में सैन्यवाद वर्णन ','militarism-in-japan-description',2,'<p>सैन्यवाद से तात्पर्य उस राज्य से है जिस राज्य के अंतर्गत सेना देश के प्रशासन में निर्णायक भूमिका अदा करती है जिसके अंतर्गत आर्थिक एक राजनीतिक नीतियों के मुख्य निर्माता सेना ही होती है और जहां सेना के अधीन विदेशी संबंधों में एक अकर्मक एवं प्रसार वादी नीति का अनुसरण किया जाता।</p>\r\n<p>सामंतवाद के पतन के बाद, आधुनिक राज्य का उदय हुआ, जिसमें आर्थिक प्रगति, उद्योग और घर पर सैन्य प्रभुत्व के साथ-साथ जापान में त्वरित विजय और विस्तार हुआ, जिसके परिणामस्वरूप राष्ट्रीय आपदा आई। जापानी शहरों की तबाही, विदेशी कब्जे के लिए जापानी सैन्य बलों के आत्मसमर्पण और चीन के साथ जापान के युद्ध ने बहाली की अवधि के अंत और जापानी सैन्यवाद के एक नए युग की शुरुआत का संकेत दियाजापान में सैन्यवाद का उदय आधुनिकीकरण, राष्ट्रीय गौरव की भावना, जनसंख्या वृद्धि और औद्योगिक समृद्धि से हुआ। यह बदलाव 1920 के दशक के अंत और 1930 के दशक की शुरुआत में शुरू हुआ और 1937 तक यह भयावह अनुपात तक पहुंच गया था। यह दक्षिणपंथी राजनीतिक दलों और सेना का निर्माण था। </p>\r\n<p>जापानी राजनीति पर हावी होने वाली सेना युद्ध विजय के लिए उत्सुक थी; इसके अधिकारियों को अंतरराष्ट्रीय राजनीति का बहुत कम ज्ञान था, जो द्वितीय विश्व युद्ध के बाद एक राष्ट्रीय आपदा में परिणत होने वाले बल द्वारा साम्राज्य के विस्तार की वकालत करते थे। जापानी सैन्यवाद प्रकृति में लोकतांत्रिक और सत्तावादी था। यह सैन्य सरदारों द्वारा शासित था, जिन्होंने महसूस किया कि जापान के हितों की रक्षा केवल एक अधिनायकवादी राज्य के तहत ही की जा सकती है। जापानी राजनीति को नियंत्रित करने वाले युद्ध मंत्री और नौसेना मंत्री ने प्रभाव डाला।</p>\r\n<p>जापानी सैन्यवाद के सत्तावादी पहलू ने यह भी खुलासा किया कि यह एक शांतिपूर्ण आंदोलन नहीं था, ISI बल्कि अति राष्ट्रवाद द्वारा शासित था। जापान में, अतिराष्ट्रवादियों ने उदारवादी संगठनों के प्रभाव का प्रतिकार करने के लिए कार्य करना शुरू किया। ग्रेटर जापान नेशनलिस्ट ऑर्गनाइजेशन की स्थापना 1919 में एक अल्ट्रानेशनलिस्ट सोसाइटी की स्थापना के बाद 1910 में हुई थी। उन्होंने महसूस किया कि सेना के पास एक अद्भुत भविष्य की कुंजी है।</p>\r\n<p>जापान का सैन्यवाद साम्यवाद विरोधी और पूंजीवादी समर्थक था। मंचूरिया और एशिया के अन्य क्षेत्रों पर उनके हितों का टकराव होने के कारण, रूस जापान का एक स्वाभाविक दुश्मन था। बोल्शेविकों के उदय ने उनके बीच संबंधों को और खराब कर दिया। जापान पूंजीवादी लाइनों पर आधारित औपनिवेशिक विस्तार से भी चिंतित था जिसका रूस ने विरोध किया था। यह एक विशेषता थी जिसने जापान को नाजी जर्मनी और फासीवादी इटली के साथ एंटी-कॉमिन्टन संधि पर हस्ताक्षर करने के लिए मजबूर किया।</p>\r\n<p>जापानी अधिनायकवाद ने व्यक्तिवाद की अनुपस्थिति के आकार के जापानी पैटर्न को बरकरार रखा। व्यक्तित्व पंथ अनुपस्थित था और सम्राट को अभी भी पूरे देश के लिए एकता और आम रैली बिंदु के प्रतीक के रूप में माना जाता था। जापान में सत्ता पर कब्जा करने के लिए सैन्यवादियों के प्रयास एक महत्वपूर्ण मोड़ पर पहुंच गए जब मिनसेटो पार्टी ने 1936 में चुनाव जीता। चुनाव परिणामों के चार दिन बाद, कुछ जूनियर रेजिमेंटल अधिकारियों ने सरकार को उखाड़ फेंकने के लिए टोक्यो में विद्रोह किया। यद्यपि यह तख्तापलट विफलता में समाप्त हुआ, लेकिन सैन्यवादियों की शक्ति में वृद्धि हुई और नरमपंथियों ने इस मांग को स्वीकार कर लिया कि युद्ध मंत्री और नौसेना मंत्री को सक्रिय सेवा पर सैन्य अधिकारी होना चाहिए जो कि सैन्यवादियों की बड़ी जीत को चिह्नित करता है।</p>',7,'2024-10-23 16:19:01','2024-10-24 08:36:27','','Publish',0,'open',8,23),('चीन का विभाजन या चीनी तरबूज का बँटवारा','division-of-china',2,'<p>सन 1894-95 के चीन-जापान युद्ध में चीन की पराजय हुई, इस पराजय के बाद उसे एक बहुत बड़ी धनराशि हर्जाने के रूप में जापान को देनी थी, लेकिन चीन की आर्थिक स्थिति ऐसी नहीं थी कि वह 15 करोड़ डॉलर की रकम जापान को दे सकता था। अतः फ्रांस, ब्रिटेन, रूस और जर्मनी ने मिलकर हर्जाना चुकाने के लिए चीन को धन उपलब्ध कराया इसके बदले में इन देशों ने चीन को अपने अपने प्रभाव क्षेत्र में बांट दिया इस विभाजन को ही चीनी खरबूजे का काटा जाना कहा जाता है।1895 ई॰ तक चीन में पश्चिमी राष्ट्रों की मुख्य दिलचस्पी वाणिज्य के लिए ही थी । व्यापारी चीन का रेशम और चाय खरीदते थे और बदले में चीन को चाँदी, अफीम, चन्दन, फर तथा अनेक प्रकार की निर्मित वस्तुएँ बेचते थे ।</p>\r\n<p>लेकिन, 1895 ई॰ में यह स्थिति एकाएक बदल गयी । चीन अब ‘एशिया का मरीज’ के रूप में प्रकट हुआ और पश्चिमी राज्यों के मुँह में उसके बँटवारे के लिए पानी भर आया । अब तक चीन का विभाजन नहीं हो सका था । इसका मुख्य कारण था पाश्चात्य देशों के बीच आपसी प्रतिस्पर्धा ।</p>\r\n<p>लेकिन, जापान की सफलता ने उन्हें नयी नीति का अवलम्बन करने की प्रेरणा दी । फलत: यूरोपीय देश अब चीन के विभिन्न क्षेत्रों पर अपना-अपना दावा पेश करने लगे और चीन को विविध प्रभाव-क्षेत्रों में बाँटने लगे । इस तरह, ‘चीनी तरबूज’ को काटने की प्रक्रिया आरम्भ हुई ।</p>\r\n<p>कई कारणों से अब चीन पर पाश्चात्य देशों का शिकंजा कसता गया और वे सब नयी-नयी सुविधाओं की माँग करने लगे । इसे लेकर उनके बीच आपसी होड़ आरम्भ हो गयी, जिसे ‘सुविधाओं का युद्ध’ कहते हैं । इसका प्रभाव चीन की प्रादेशिक एकता पर बड़ा घातक सिद्ध हुआ । चीन के भू-भाग धीरे-धीरे केन्द्रीय सरकार के अधिकार से निकलने लगे और उन पर विदेशियों का आधिपत्य कायम होता गया चीन की लूट-खसोट की असली प्रक्रिया अब शुरू हुई ।</p>\r\n<p>कोरिया को लेकर जो चीन-जापान युद्ध हुआ था, उसका अन्त शिमोनोस्की की सन्धि से हुआ था । इस सन्धि के कारण चीन को अत्यधिक नुकसान पहुँच रहा था । पश्चिमी राज्यों की आकांक्षा भी सीमित हो रही थी । अतएव फ्रांस, जर्मनी और रूस हम देख चुके है- हस्तक्षेप कर शिमोनोस्की सन्धि में संशोधन कराया जिससे लियाओतुंग प्रायद्वीप चीन के हाथ से निकलने से बच गया । इसके अतिरिक्त, जापान को क्षतिपूर्ति भी देनी थी । इसके लिए चीन को इन्हीं तीनों देशों ने कर्ज दिया । इस प्रकार, चीन इन तीनों देशों के प्रति कृतज्ञ हो गया । किन्तु, इसका त्त्व भी उसे शीघ्र ही चुकाना पड़ा । तीनों शक्तियों ने चीन को जो लाभ पहुँचाया था, उसके एवज में वे चीन से रियायतें और सुविधाएँ माँगने लगे ।</p>\r\n<p>फ्रांस का हिस्सा-चीन को जापान को जो युद्ध का हरजाना देना था उसके लिए जुलाई, 1895 में फ्रांस ने एक ऋण जारी किया जिसकी गारण्टी रूस ने ली । कर्ज के रूप में धन देने के पहले फ्रांस ने चीन से यह वादा करा लिया कि वह हैनान का द्वीप किसी अन्य राज्य को नहीं देगा । कुछ ही दिनों के अन्दर फ्रांस को चीन में अग्रलिखित सुविधाएँ प्राप्त हो गयीं ।युद्धान, क्वांगसी और क्वांगतुंग की खानों को खोदने का एकाधिकार और दक्षिणी चीन में अनाम रेलवे के विस्तार का अधिकार उसे मिला । दक्षिणी चीन में फ्रांसीसी माल पर चुंगी भी घटा दी गयी । इस प्रकार, फ्रांस ने चीन-जापान- युद्ध की समाप्ति के तुरंत बाद ही चीन में सुविधाओं के युद्ध का आरम्भ कर दिया । 1897-98 में फ्रांस ने और नये अधिकार और सुविधाएं प्राप्त कीं </p>',11,'2024-10-23 16:19:01','2024-10-24 08:37:29','','Publish',0,'open',6,24),('धर्म-सुधार के क्षेत्र में रामकृष्ण मठ एवं मिशन के महत्व','importance-of-ramakrishna-math-and-mission-in-the-field-of-religious-reform',2,'<p>रामकृष्ण मिशन की स्थापना स्वामी विवेकानंद ने सन् 1897 ई. में अपने गुरू राम कृष्ण परमहंस के नाम को उजागर करने के लिए की थी। रामकृष्ण परमहंस (1836-1885) उन्नीसवीं शताब्दी में भारत के महान साधक एवं सन्त थे। वे कलकत्ते के निकट दक्षिणेश्वर के काली मंदिर के पुजारी थे। यद्यपि वे पढ़े लिखे नहीं थे, तथापि अपनी साधना और भक्ति के सहारे उन्होंने आध्यात्मिक क्षेत्र में अपूर्व सफलता प्राप्त की थी। वे काली के अनन्य भक्त थे तथा उनकी पूजा इतनी तन्मयता से करते थे कि आत्मविभोर हो जाते थे। वे सभी धर्मों को ईश्वर को पाने का अलग-अलग रास्ता मानते थे। वे काली को जगदम्बा एवं संसार की रक्षिका मानते थे। अपनी साधना के द्वारा उन्होंने अपूर्व आध्यात्मिक सिद्धि प्राप्त कर ली थी तथा सरल भाषा में दिये गये उपदेशों से वे अपने सुननेवालों को मंत्रमुग्ध कर लेते थे।</p>\r\n<p>शीघ्र ही उनकी ख्याति पूरे देश में फैल गयी। जो भी उनके सम्पर्क में आता था, उनकी साधना, भक्ति और उनके संवेदनशील व्यक्तित्व से प्रभावित हुए बिना नहीं रहता था। कलकत्ता के बहुत से प्रतिष्ठित एवं प्रभावशाली व्यक्तियों ने उनको अपना गुरू माना। इन्हीं शिष्यों में स्वामी विवेकानन्द प्रमुख थे।</p>\r\n<h2> विवेकानन्द</h2>\r\n<p>विवेकानन्द का वास्तविक नाम नरेन्द्रनाथ दत्त (1862-1902) था। नरेन्द्रनाथ दत्त कलकता विश्वविद्यालय से बी.ए. की परीक्षा पास करने के बाद रामकृष्ण परमहंस के संपर्क में आये और शीघ्र ही उनके सबसे प्रिय शिष्य बन गये। रामकृष्ण के प्रभाव में आकर नरेन्द्रनाथ दत्त ने संन्यास ग्रहण किया और वे स्वामी विवेकानन्द के नाम से मशहुर हुए। 1886 में रामकृष्ण परमहंस की मृत्यु के बाद विवेकानन्द ने भारत का भ्रमण किया तथा भारतीय संस्कृति और दर्शन का गम्भीर अध्ययन किया। 1893 ई. में उनके कुछ श्रद्धालु भक्तों एवं मित्रों ने उन्हें अमेरीका के शिकागो शहर में होने वाले \"<b>पार्लियामेंट आफ रिलीजन्स</b>\"\r\n  (Parliament of Religions) नामक एक धर्म-सम्मेलन में भाग लेने के लिए भेजा।</p><p> स्वामी विवेकानन्द ने इस सम्मेलन में अपनी वक्तत्व कला एवं प्रभावशाली व्यक्तित्व से श्रोताओं को मंत्रमुग्ध एवं चकित कर दिया। यद्यपि उन्हें शुरू में पाँच मिनट तक ही बोलने का समय दिया गया, पर श्रोताओं ने और अधिक बोलने का बार-बार अनुरोध किया। अपने भाषण के द्वारा उन्होंने हिन्दू धर्म की प्रतिष्ठा सारे विश्व में स्थापित कर दी तथा यह सिद्ध कर दिया कि हिन्दू-धर्म विश्व के महान धर्मों में एक है। विवेकानन्द की सफलता से भारतीय संस्कृति की प्रतिष्ठा में चार चाँद लग गये और साई मिशनरियों द्वारा हिन्दू-धर्म के विरूद्ध फैलाई गई अपवाहें खोखली साबित हुई।</p>\r\n<p>भाषण के द्वारा उन्होंने हिन्दू धर्म की प्रतिष्ठा सारे विश्व में स्थापित कर दी तथा यह सिद्ध कर दिया कि हिन्दू-धर्म विश्व के महान धर्मों में एक है। विवेकानन्द की सफलता से भारतीय संस्कृति की प्रतिष्ठा में चार चाँद लग गये और साई मिशनरियों द्वारा हिन्दू-धर्म के विरूद्ध फैलाई गई अपवाहें खोखली साबित हुई।</p>\r\n<p>बहुत से अमेरीकी और यूरोपीय लोगों ने स्वामी विवेकानन्द का शिष्य बनकर हिन्दू धर्म ग्रहण किया। इस प्रकार अमेरिका और यूरोप में विजय पताका फहराते हुए विवेकानन्द भारत लौटे। यहाँ पहुँचने पर उनका अपूर्व स्वागत हुआ। वे जहाँ कहीं जाते, उनके दर्शन और भाषण सुनने के लिए हजारों की भीड़ इकट्टी हो जाती। विवेकानन्द ने अपनी लोकप्रियता के माध्यम से राष्ट्रीय जागरण एवं हिन्दू धर्म के उत्थान की प्रक्रिया को गतिशील बनाया। अपने धार्मिक एवं सामाजिक विचारों को कार्यान्विन्त करने\r\n  के लिए स्वामी विवेकानन्द ने 1897 में \"<b>रामकृष्ण मठ मिशन</b>\' की स्थापना की।</p>\r\n<h2>रामकृष्ण मिशन के उद्देश्य एवं कार्य</h2>\r\n<ul>\r\n    <li><p>इस संस्था का उद्देश्य रामकृष्ण परमहंस द्वारा दिये गये उपदेशों का प्रचार करना एवं उनके उपदेशों के आधार पर मानवता का कल्याण करना था।</p></li>\r\n    <li><p>यह संस्था विभिन्न धर्मों के अनुयायियों के बीच प्रेम और सद्भाव स्थापित करना चाहती थी, क्योंकि सभी धर्म एक शाश्वत धर्म के ही विभिन्न रूप हैं।</p></li>\r\n    <li><p>यह संस्था ऐसे लोगों को प्रशिक्षित करेगी जो जनता के भौतिक एवं आध्यात्मिक कल्याण के लिए ज्ञान-विज्ञान, कला एवं उद्योगों की शिक्षा दें। यह संस्था जनता में रामकृष्ण के धार्मिक विचार एवं वेदान्त का प्रचार करेगी।</p></li>\r\n    <li><p>यह संस्था अपने मठों एवं आश्रमों में ऐसे सन्यासियों को शिक्षा देगी जो देश और विदेश में पूर्ण निष्ठा के साथ इन उद्देश्यों का प्रचार करें। </p></li>\r\n</ul>\r\n<p>स्वामी विवेकानन्द ने इस संस्था के माध्यम से अपने विचारों को कार्यान्वित किया।</p>\r\n<h2>उनके प्रमुख धार्मिक विचार निम्नलिखित थे-</h2>\r\n<ul>\r\n    <li><p>हिन्दू धर्म संसार का प्राचीनतम एवं श्रेष्ठतम धर्म है तथा प्राचीन भारत संसार का गुरू \'था।</p></li>\r\n    <li><p>ईश्वर निराकार है तथा वह मनुष्य की बुद्धि के परे है। फिर भी उसे समस्त संसार में, सभी जीवों में तथा सभी देवताओं में परखा जा सकता है।</p></li>\r\n    <li><p>हिन्दू धर्म में प्रचलित मूर्ति पूजा ईश्वर की उपासना का आध्यात्मिक ढंगे है। अतः मूर्तिपूजा करने में कोई हानि नहीं है। </p></li>\r\n    <li><p>हिन्दू संस्कृति संसार की प्राचीनतम संस्कृति है तथा यह पूर्णतया आध्यात्मिक तथा सुन्दर है। इसकी तुलना में पश्चिमी सभ्मता भौतिकी स्वार्थपरक और वासनापरक है। </p></li>\r\n    <li><p>संसार में जीवित रहने के लिए हिन्दू संस्कृति को क्रियाशील एवं सजग होना पड़ेगा। हिन्दुओं को पश्चिमी देशों से वैज्ञानिक एवं तकनीकी ज्ञान प्राप्त करना चाहिए। जिससे वे सभ्यता की दौड़ में पीछे न छूट जाएँ।</p></li>\r\n    <li><p>हिन्दू धर्म में समाज-सेवा को प्रमुख स्थान मिलना चाहिए। गरीबों को खिलाना, अनाथ बच्चों को पालना तथा रोगियों की सेवा करना हिन्दूधर्म का प्रमुख अंग\' बनना चाहिए। इन आदर्शों को क्रियान्वित करने के लिए स्वामी विवेकानन्द ने अथक प्रयत्न किया। उन्होंने देश-विदेश में रामकृष्ण मिशन की शाखाएँ स्थापित कीं तथा घूम-घूमकर अपने प्रभावशाली, भाषणों से हिन्दू जाति की निद्रा एवं उन्द्रा को भंग कर जागरूक बनाया। वास्तव में उन्होंने अपने व्यक्तित्व से हिन्दू समाज को जगा कर उसे आधुनिक युग की चुनौतियों का सामना करने के लायक बनाया। तत्कालीन युवकवर्ग के वे हृदय सम्राट बन गये। </p></li>\r\n</ul>\r\n<p>विवेकानन्द अपने दृष्टिकोण में पूर्णतया आधुनिक थे और वे हिन्दूधर्म की प्राचीन गरिमा में विश्वास करने के साथ-साथ उसे आधुनिक एवं शक्तिशाली बनाना चाहते थे। उन्होंने \"प्रबुद्ध भारत\" एवं \"उद्बोधन\" नामक दो मासिक पत्रिकाओं के द्वारा अपने विचार का प्रचार किया। उन्होंने रामकृष्ण मिशन के कार्यक्रम में शिक्षा प्रसार, समाज-सेवा तथा रोगियों के इलाज को प्रमुख स्थान दिया। मिशन ने देश के विभिन्न भागों में अनेक स्कूल, कॉलेज, अस्पताल तथा दातव्य औषधालय स्थापित किए जिसका संचालन आज भी मिशन के सन्यासियों द्वारा होता है। मिशन ने अकाल महामारी एवं बाढ़ आदि प्राकृतिक विपत्तियों के समय बहुत बड़े पैमाने पर पीड़ितों की सेवा की है।</p>\r\n<p>मिशन की शाखाएँ विदेशों में भी स्थापित हुई। अमेरिका के न्यूयार्क, बॉस्टन वाशिंग्टन तथा सान-फ्रांसीसकों नगरों में रामकृष्ण मिशन हिन्दूधर्म का प्रचार करता है। . वेदान्त के सिद्धान्तों का प्रचार करने के लिए कई वेदान्त- सोसाइटियाँ मिशन द्वारा चलाई जाती हैं। समाज सेवा एवं हिन्दूधर्म के पुरनरूत्थान के क्षेत्र में रामकृष्ण मिशन ने • महत्वपूर्ण भूमिका अदा की है।</p>\r\n<p>स्वामी विवेकानन्द भारतीय इतिहास के रंगमंच पर ऐसे समय में आये, जब उनके गतिशील नेतृत्व ने हिन्दूधर्म के सुधार एवं राष्ट्रीय जागरण में अभूतपूर्व काम किया। विवेकानन्द ने अपने गुरू के संदेश को व्यावहारिक रूप देकर उन्हें अमर कर दिया। विवेकानन्द में संगठन एवं नेतृत्व की अपूर्व प्रतिभा एवं क्षमता थी। उनके प्रभाव से देशभक्ति की भावना जोर पकड़ती गई। वे देश के युवकों को शक्तिशाली एवं क्रियाशील बनाना चाहते थे।</p>\r\n<p>उनके धार्मिक एवं सामाजिक कार्यों के पीछे मूल उद्देश्य भारतीय संस्कृति की सोयी हुई आत्मा को जगाकर सक्रिया बनाना था। इसलिए उन्होंने एक भाषण में कहा था - \"<i>हमारे देश को आज किस चीज की जरूरत हैं? हमें ऐसे नौजवानों की आवश्यकता है जिनकी मांसपेशियाँ लोहे की और जिनकी नसें फौलाद की बनी हों। हमें ऐसे नवयुवक चाहिए जो विश्व के रहस्यों का उद्घाटन कर सके।</i>\"</p>\r\n<p>इस प्रकार स्वामी विवेखानन्द ने अपने ओजस्वी भाषणों एवं अपनी संगठनशक्ति के द्वारा सामाजिक एवं धार्मिक प्रक्रिया को गतिशील बनाया तथा देश के सांस्कृतिक जागरण को एक नयी दिशा दी</p>',22,'2024-10-23 16:19:01','2024-10-24 08:38:52','','Publish',0,'open',11,25),('1904-1905 रूस-जापान युद्ध के कारण, प्रभाव और परिणाम','causes-effects--and-consequences-russo-japanese-war-1904-1905',2,'<p>रूस को बीसवीं शताब्‍दी के आरंभ में एशिया का बहुत शक्ति संपन्न देश समझा जाता था। रूस भी इंग्‍लैण्‍ड और फ्रांस की तरह साम्राज्‍यवाद नीति का अनुगमन करने मे लगा था। दूसरी ओर जापान भी अपनी शक्ति वृद्धि कर चीन में साम्राज्‍य वृद्धि के लिये प्रयत्‍नशील था। चीन ने रूस-जापान के साम्राज्‍यवादी और सैन्‍यवादी कार्यो और उद्देश्‍यों में तनाव होना स्‍वाभाविक था। अतः दोनों में 1904 - 05 में युद्ध हो गया।</p>\r\n<h2>रूस और जापान के मध्‍य युद्ध के निम्‍नलिखित कारण थे -</h2>\r\n<h3 class=\"atech\">रूस का चीन में हस्‍तक्षेप और मंचूरिया का प्रश्‍न </h3>\r\n<p> जापान रूस में अनबन का प्रमुख कारण मंचूरिया पर दोनो के प्रभाव को लेकर था। मंचूरिया चीनी साम्राज्‍य का एकमात्र प्रांत था। इसलिए जापान और रूस में तकरार होना स्‍वाभाविक थीं। जापान अपनी मानसिकता को बदलते हुए वह साम्राज्‍यवादी होता जा रहा था। शिमोनास्‍की की संधि का विरोध कर रूस ने चीन से अपना विरोध बताया। 1895 ई. में चीन से संधि कर ली। मंचूली से ब्‍लादीवोस्‍तक तक रेल्‍वे लाइन बिछाने की अनुमति प्राप्‍त कर रूस से सूदूर पूर्व में अपने प्रसार हेतु अग्रिम कार्यवाही प्रारंभ कर दी। पोर्ट आर्थर एंव उसके समीप का प्रदेश रूस से 25 वर्ष तक पट्टे पर प्राप्‍त कर लिया और यहां की किलेबंदी शुरू की। रूस मंचूरिया में प्रभाव बढ़ाने लगा। रूस का विचार यहां विस्‍तार करना था। मंचूरिया के रंगमंच पर रूसी चालें चली गई। रूस की इन चालों से जापान नाराज हो गया। जापान अपनी जनसंख्‍या को मंचूरिया में बसाना चाहता था। इसके कारण वह ऐसा नहीं कर पा रहा था। रूस ने पोर्ट आर्थर और मास्‍कों के बीच रेल्‍वे लाइन बनाई। पूर्वी एशिया के लिए एक रूसी वायसराय नियुक्‍त किया। जापान के‍ लिए यह असहनीय था।</p>\r\n<h3 class=\"atech\">रूस से बदला लेने की भावना </h3>\r\n<p> जापान का चीन से युद्ध के बाद एक संधि हुई, जिसमें जापान को लिआओतुंग का प्रायद्वीप मिला था, परंतु रूस और फ्रांस और जर्मनी के विरोध के कारण उसे उस द्वीप पर उसे अपना अधिकार छोड़ना पड़ा था। अपनी इस क्षति का कारण वह रूस को मानता था और उससे बदला लेना चाहता था। इस युद्ध के कारणों में यह भी एक कारण था।</p>\r\n<h3 class=\"atech\">रूस के प्रभाव को समाप्‍त करना और मित्र की खोज </h3>\r\n<p> जापान के द्वारा चीन की पराजय के बाद कोरिया रूस का प्रभाव बढ़ता जा रहा था। चीन में जापान को रोकने के लियें 1895 ई. के समान रूस, जर्मनी और फ्रांस कोई संयुक्‍त हस्‍तक्षेप न कर पाये इसलिए जापान ने अपने मित्रों की खोज आरम्‍भ की। इसी कारण आंग्‍ल-जापान संधि 1902 ई. में सम्‍पन्‍न हुई जिसमें इंग्‍लैण्‍ड़ ने जापान के कोरिया में विशेष हित और जापान चीन में इंग्‍लैण्‍ड़ के हितों को स्‍वीकार कर अन्‍य देश के आक्रमण के समय स्‍वंय तटस्‍थ रहने तथा अन्‍य देशों को तटस्‍थ रखने का प्रयास करने के आश्‍वासन दिया। इस संधि के बाद जापान का कोरिया में प्रवेश और रूस-जापान युद्ध का रास्‍ता साफ हो गया। इंग्‍लैण्‍ड़ भी इस समय रूस के प्रभाव को काम करना चाहता था और रूस-जापान युद्ध से अच्‍छा कोई उपाय नहीं था। उधर इंग्‍लैण्‍ड़ को जर्मनी की नौसेनिक शक्ति से भी भय था इसलियें उसने जापान से संधि करना उचित माना। दूसरी ओर जर्मनी, आस्ट्रिया और इटली ने भी जापान से सहानुभूति प्रगट की जबकि आंग्‍ल-जापान संधि के समय रूस अकेला था।</p>\r\n<h3 class=\"atech\">बाक्‍सर विद्रोह </h3>\r\n<p> सन् 1900 ई. में चीन में एक विद्रोह हुआ। जिसे बाक्‍सर विद्रोह के नाम से जाना जाता हैं। इस विद्रोह का प्रभाव रूस के अधिकार क्षेत्र में मौजूद मंचूरिया तक इसका विस्‍तार हुआ तो रूस ने अपने आर्थिक हितों की सुरक्षा के बहाने वहां सेना उतार दी और यह कहा कि जैसे ही विद्रोह समाप्‍त होगा वह अपनी सेना को वापस बुला लेगा, परंतु उसने ऐसा नहीं किया। इससे उसके इरादे स्‍पष्‍ट हो गए थें। अंततः जापान और रूस का संघर्ष अनिवार्य हो गया था।</p>\r\n<h2>रूस-जापान युद्ध के परिणाम </h2>\r\n<p>इस युद्ध के बाद रूस का अभिमान चूर-चूर हो गया। फलस्‍वरूप जापान का कोरिया में हस्‍तक्षेप बढ़ने लगा और वह 1910 ई. तक जापान का अंग बन गया। कोरिया में जापानी भाषा, धर्म, व्‍यापार, पूलिस तथा सेना का प्रवेश हुआ तथा जापान के हित में कोरिया का आर्थिक विकास किया गया। रेल्‍वे, यातायात में उन्‍नति हुई।</p>\r\n<ul>\r\n    <li><p>कोरिया को जापान के प्रभाव क्षेत्र के रूप में मान्यता दी गई थी</p></li>\r\n    <li><p>जापान ने दक्षिण सखालिन पर कब्जा कर लिया</p></li>\r\n    <li><p>जापान को रूसी तट पर मछली का अधिकार प्राप्त हुआ</p></li>\r\n    <li><p>रूस ने लियाओडोंग प्रायद्वीप और पोर्ट आर्थर को जापान को पट्टे पर दिया था।</p></li>\r\n</ul>\r\n\r\n<h2>रूस-जापान युद्ध के निम्‍नलिखित प्रभाव पड़े--</h2>\r\n<h3 class=\"atech\"> रूस पर प्रभाव </h3>\r\n<p> इस युद्ध के बाद रूस की आंतरिक राजनीति पूरी तरह डामाडोल हो गई, और रूसी जनता जार के एकतंत्र शासन का विरोध करने लगी। इस युद्ध के कारण ही रूस में सन् 1917 ई. की क्रांति हो गई थी।</p>\r\n<h3 class=\"atech\">एशिया पर प्रभाव </h3>\r\n<p> रूस पर जापान की जीत से एशिया के राष्‍ट्रों में नवचेतना एंव उत्‍साह का संचार हो गया। भारत में राष्‍ट्रीय आंदोलन तीव्र गति से प्रारंभ हो गया। यह युद्ध एक युगांतकारी घटना बन गया।</p>\r\n<h3 class=\"atech\">यूरोप की राजनीति पर प्रभाव </h3>\r\n<p> इस युद्ध के उपरांत रूस का पूर्वी एशिया का प्रभाव रूक गया तथा यूरोपीय शक्तियों ने चीन में लूट-खसोट की नीति पर अमेरिका के मुक्‍त व्‍यापार का समर्थन किया। रूस बाल्‍कन समस्‍या में उलझ गया। यूरोप में गुटबंदी प्रांरभ हो गई और यूरोप दो गुटों में विभाजित हो गया। जापान विश्‍व में एक प्रमुख शक्ति बन गया।</p>',32,'2024-10-23 16:19:01','2024-10-24 08:40:12','','Publish',0,'open',25,26),('कैंटेन व्यापार व्यवस्था','canteen-trading-system',2,'<p>16वीं शताब्दी के प्रारंभ में पुर्तगालियों के दक्षिणी चीनी समुद्र तट पर पहुंचने के बाद से ही चीनी और यूरोप के बीच समुद्री व्यापार का प्रचलन हो गया था । 17 वीं शताब्दी के मध्य से 18वीं शताब्दी के दौर में इन समुद्री व्यापार में कई उतार-चढ़ाव आए । 17 वीं शताब्दी में अमेरिका को छोड़कर प्रायः सभी देशों से व्यापार कर रहे थे किंतु चीन में विदेशी व्यापार पर कई तरह के प्रतिबंध लगा दिए गए कैंटेन बंदरगाह को छोड़कर बाकी सारे बंदरगाहों को विदेशियों के लिए बंद कर दिया गया।</p>\r\n<p>1757 ईसवी में कैंटेन व्यवस्था की स्थापना हुई, जो अफीम युद्ध तक चीन और पश्चिमी देशों के बीच व्यापारिक संबंध का एकमात्र मान्य स्वरूप बनी रही । </p>\r\n<p>कैंटन व्यवस्था से आशय उन तमाम व्यापारिक प्रबंधों से है जो 1757 और 1842 के बीच पश्चिमी देशों के लिए उपलब्ध थे। विदेशी व्यापारियों ने कैंटन में व्यापारिक प्रतिष्ठान बनाकर रखे, जिन्हें गोदामों के तौर पर भी इस्तेमाल किया जाता था इन्हें \"फैक्ट्री\' या कारखाना कहा जाता था। वे लोग साल के अधिकांश समय मकाओ में रहते थे, लेकिन हर साल जब उनके देश से उनके जहाज आते तो ये व्यापारी पर्ल नदी के मुहाने से जहाज से कैंटन चले जाते थे, जहाँ वे अगस्त से मार्च तक के व्यापार के समय तक रहते थे। उन्हें अपने साथ अपने परिवारों को लाने की अनुमति नहीं थीं और वे व्यापार के ठिकाने के अंदर ही आ जा सकते थे।</p>\r\n<p>कँटन में, पश्चिमी व्यापारियों के सभी व्यापारिक लेन-देन \"को हाँग\" के माध्यम से होते थे। \"को हाँग\" जाने-माने स्थानीय सौदागरों की एक श्रेणी थी, जिसके व्यापार पर एकाधिकार को छिंग सरकार की मान्यता मिली हुई थी। इस सरकारी मान्यता के बदले में, हाँग सौदागर व्यापार के तमाम प्रबंधों को देखते थे, विदेशी व्यापारियों को आवश्यक सुविधाएं उपलब्ध कराते थे और उनके अच्छे व्यवहार की जमानत देते थे। वे सामूहिक रूप से शाही सरकार के अधिकारियों के प्रति जिम्मेदार थे, जिनमें सबसे महत्त्वपूर्ण थेलियांगगुवांग ( जिसमे कैंटन या गुआंगजोउ आता था ) का वाइसराय और समुद्री सीमा शुल्क का अधीक्षक ( जिसे \"होप्पो\' कहा जाता था) इनका काम कैंटन के व्यापार से राजस्व इकट्ठा करके उसे बीजिंग स्थित शाही सरकार के पास जमा कराना था।</p>\r\n<p>पश्चिमी व्यापारियों को किसी भी कारण से सीधे शाही अधिकारियों से संपर्क करने की छूट नहीं थी, लेकिन वे अपनी तमाम शिकायतों, निवेदनों आदि को हाँग सौदागरों के जरिए संबंधित अधिकारी तक पहुँचा सकते थे। हाँग सौदागरों के अलावा अगर वे और किसी चीनी के साथ सीधे कोई आदान-प्रदान करते थे, तो वे लोग थे जो उन्हें आवश्यक सेवाएं प्रदान करते थे - जैसे उनके घरेलू नौकर, भाषाविद् (दुभाषिए और रक्षक), और सबसे महत्वपूर्ण \"कम्प्रराडोर\' (Compradore) लोग, जो चीनी ही होते थे और जिनका काम विदेशी कंपनियों के लिए व्यापार का स्थानीय पहलू संभालना था ।</p>\r\n<p>19वीं शताब्दी की शुरुआत में, ब्रिटिश व्यापारियों ने इन प्रतिबंधों से चिढ़ना शुरू कर दिया था। 1834 में ईस्ट इंडिया कंपनी के एकाधिकार को समाप्त करने और चीन में निजी व्यापारियों के आगमन के साथ शिकायतें और अधिक बढ़ गईं। उसी समय, ब्रिटिश \"देश व्यापार\" चाय और रेशम की ब्रिटिश खरीद के भुगतान के साधन के रूप में भारत से चीन में अफीम के अवैध आयात पर केंद्रित था। चीन द्वारा अफीम के व्यापार को रोकने का प्रयास , जिसने सामाजिक और आर्थिक व्यवधान पैदा किया था, का पहला परिणाम हुआब्रिटेन और चीन के बीच अफीम युद्ध (1839-42)। इस संघर्ष में ब्रिटेन की जीत ने चीनियों को कैंटन प्रणाली को खत्म करने और इसे पांच संधि बंदरगाहों के साथ बदलने के लिए मजबूर किया, जिसमें विदेशी चीनी कानूनी अधिकार क्षेत्र के बाहर रह सकते थे और काम कर सकते थे, जिसके साथ वे प्रसन्न होते थे</p>',1,'2024-10-23 16:19:01','2024-10-24 08:41:27','','Publish',0,'open',28,27),('आर्य समाज के सिद्धान्त','arya-samaj-principles',2,'<p>धार्मिक एवं सामाजिक परिवर्तन के क्षेत्र में उन्नीसवीं शताब्दी के उतरार्द्ध में आर्य समाज नामक संस्था ने भी\r\n    महत्त्वपूर्ण भूमिका अदा की। इसके संस्थापक स्वामी दयानन्द सरस्रती (1824-1883) थे। दयानन्द का जन्म गुजरात के मौर्वी\r\n    राज्य के टंकारा नामक स्थान में एक ब्राह्मण परिवार में हुआ। पंद्रह वर्ष की अवस्था में ही मूर्तिपूजा के प्रश्न को लेकर\r\n    उन्हें अपने पिता से मतभेद हो गया और घर छोड़कर सन्यासी हो गये। उन्होंने मथुरा में स्वामी विरजानन्द नामक एक अन्धे\r\n    संयासी के पास रहकर कई वर्षों तक वेदों और शास्त्रों का गंभीर अध्ययन किया।</p>\r\n<p>शिक्षा समाप्त होनो पर स्वामी विरजानन्द ने उनसे वचन लिया कि वे वैदिक धर्म में निहित तथ्य के प्रचार में अपना जीवन\r\n    लगायेंगे तथा पुराणों पर आधारित धार्मिक विश्वासों का खण्डन करेंगे। इसके साथ ही वे सच्ची शिक्षा-पद्धति की स्थापना\r\n    करेंगे। दयानन्द ने इस प्रतिज्ञा का अक्षरशः पालन किया। इस उद्देश्य से उन्होंने \"सत्यार्थ प्रकाश\", वेद भाष्य भूमिका\r\n    एवं \"वेद भाष्य\" जैसी पुस्तकों की रचना की तथा पूरे देश में घूम-घूमकर अनेक शास्त्रार्थों में पौराणिक मत का खण्डन\r\n    किया।</p>\r\n<p>अपने धार्मिक एवं सामाजिक सिद्धान्तों का प्रचार करने के लिए स्वामी दयानन्द सरस्वती ने 10 अप्रैल, 1875 को बम्बई में\r\n    आर्य समाज नामक संस्था की स्थापना कीं। इस संस्था ने धार्मिक और सामाजिक सुधार के क्षेत्र में शक्तिशाली नेतृत्व किया-\r\n    तथा धीरे-धीरे यह संस्था उत्तर भारत और पश्चिमी भारत में एक लोकप्रिय एवं प्रभावशाली संस्था के रूप में उभरी। आर्य समाज\r\n    के सिद्धान्त निम्नलिखित थे-</p>\r\n<ul>\r\n    <li><p>इस संसार में ज्ञान का वास्तविक एवं परम कारण ईश्वर है।</p></li>\r\n    <li><p>ईश्वर सत्, चित, आनन्द है। वह निराकार, सर्वशक्तिमान, न्यायपूर्ण, परमकृपालु, अनादि-अनंत, अपरिवर्तनीय, सबका स्वामी परम पवित्र एवं शाश्वत है।</p></li>\r\n    <li><p>वेद ही ऐसा धर्म-ग्रन्थ है जिसमें सच्चा ज्ञान भरा हुआ है। इसलिये वेदों को पढ़ना, पढ़ाना उनका उच्चारण करना और उनका श्रवण करना। प्रत्येक आर्य का परम कर्तव्य है।</p></li>\r\n    <li><p>मनुष्य को सदैव सत्य के ग्रहण और असत्य के परित्याग के लिये तैयार रहना चाहिये। </p></li>\r\n    <li><p>प्रत्येक कार्य धर्म के सिद्धान्तों को ध्यान में रखकर उचित एवं अनुचित का विचार करके करना चाहिये।</p></li>\r\n    <li><p>आर्य-समाज पूरी मानव जाति के शारीरिक, सामाजिक एवं आध्यात्मिक उन्नति के लिए सचेष्ट रहेगा।</p></li>\r\n    <li><p>दूसरों के साथ व्यवहार धर्म को ध्यान में रखकर प्रेम और न्याय के आधार पर होना चाहिये।</p></li>\r\n    <li><p>प्रत्येक व्यक्ति को अविद्या के नाश और विद्या के प्रसार के लिए प्रयत्नशील रहना चाहिए।</p></li>\r\n    <li><p>प्रत्येक व्यक्ति को दूसरों के कल्याण और विकास को ही अपना कल्याण और विकास मानना चाहिए। </p></li>\r\n    <li><p>व्यक्तिगत मामलों में प्रत्येक मनुष्य को आवरण की स्वतन्त्रता है पर सामाजिक मामलों में परोपकार की भावना से काम करना चाहिए</p></li>\r\n</ul>',14,'2024-10-23 16:19:01','2024-10-24 08:44:28','','Publish',0,'open',27,28),('1917 ई. के बोल्शेविक क्रांति के परिणामों एवं महत्त्व की विवेचना करें।','results-and-significance-of-the-bolshevik-revolution',2,'<p>1917 ई. के क्रांति के फलस्वरूपप रूस में करेन्स्की की सरकार का पतन और लेनिन के नेतृत्त्व में बोल्शेविक सत्ता की स्थापना आधुनिक युग की एक महान घटना थी। इसके अत्यंत दूरगामी परिणाम हुए तथा विश्व इतिहास में इसे महत्त्वपूर्ण घटना के रूप में विशिष्ट स्थान प्राप्त है।</p>\r\n<h2>बोल्शेविक क्रांति के निम्नलिखित महत्त्वपूर्ण परिणाम हुए -</h2>\r\n<h3>रूस द्वारा युद्ध का अन्त एवं संधि </h3>\r\n<p>सत्ताग्रहण के पूर्व क्रान्ति-काल में लेनिन ने शांति, भूमि एवं रोटी का नारा दिया था। अतः क्रांति के पश्चात् रूसी जनता एवं सेना को युद्ध की विभीषिका से मुक्त कराने के लिए तथा क्रांति को सुदृढ़ करने के लिए लेनिन ने विश्वयुद्ध से रूस को अलग करने का निश्चय किया। बोल्शेविक सरकार ने 3 मार्च 1918 ई. को जर्मनी के साथ ब्रेस्टलिटोवस्क (Brestlitovsk) की संधि की। इसके अनुसार रूस को यूरोपीय प्रदेशों के चौथाई भाग-पौलेण्ड, लिथुआनिया, स्टोनिया, लैटेविया और फिनलैण्ड के प्रदेश से अपना दावा छोड़ना पड़ा। तुर्की साम्राज्य पर से भी रूस को अपने सारे अधिकारों का परित्याग करना पड़ा।</p>\r\n<h3>बोल्शेविक सरकार द्वारा राष्ट्रीयकरण की नीति </h3>\r\n<p> लेनिन ने अपने दो अन्य नारे-भूमि और राटी, को पूर्ण करने की दिशा में अगला कदम उठाया। क्रांति को सुदृढ़ करने के लिए क्रांति के मुख्य भागीदारों अर्थात् किसान, श्रमिक एवं रूसी सैनिकों की आकांक्षाओं को पूर्ण करना आवश्यक था। युद्ध का अन्त कर बोल्शेविक सरकार ने जनता को शांति तो दीदी, किन्तु उसकी क्षुधा की तृप्ति करना अगला तार्किक कदम था। अतः नयी सरकार ने भूमि के राष्ट्रीयकरण की घोषणा की। भूमि पर से निजी स्वामित्व को समाप्त कर उन्हें जमींदारों से छीन लिया गया और गरीब किसानों में बाँट दिया गया।</p>\r\n<p> इसके साथ ही साथ निजी कारखानों का भी अधिग्रहण कर लिया गया तथा उसका प्रबन्ध श्रमिकों को सौंप दिया गया। इस प्रकार रेलवे, बैंक, खान तथा अन्य उद्योग-धन्धों पर नई सरकार का अधिकार स्थापित हो गया। बोल्शेविक सरकार के बिना कोई मुआवजा चुकाये चर्च की सम्पूर्ण सम्पति पर कब्जा कर लिया। </p>\r\n<p>युद्धकाल में तथा युद्ध से पूर्व रूस की जारशाही सरकार ने देशी पूँजीपतियों तथा विदेशों से जितने ऋण लिये थे, उसे बोल्शेविक सरकार से मान्यता प्रदान नहीं की तथा चुकाने से इन्कार कर दिया। नये शासन के प्रबन्ध के लिए निष्ठावान तथा विश्वसनीय पदाधिकारियों को रखा गया, साथ ही पार्टी के सदस्यों को भी बिना उनकी योग्यता पर विचार किये शासन के उच्च पदों पर भी नियुक्त किया गया।</p>\r\n<h3>आन्तरिक विद्रोह एवं बाह्य आक्रमण </h3>\r\n<p> बोल्शेविक क्रांति यद्यपि सफल हो गयी, किन्तु नई सरकार की नीति एवं कार्यों के फलस्वरूप आन्तरिक विद्रोह एवं बाह्य आक्रमण की स्थिति पैदा हो गयी। नई सरकार की पूँजीवाद विरोधी नीति ने उसे यूरोप के पूँजीवादी राष्ट्रों की आँखों का काँटा बना दिया। अतः 1919 ई. में यूरोप के अनेक राष्ट्रों ने मिलकर रूस पर आक्रमण कर दिया।</p>\r\n<p> रूस के प्रतिक्रियावादी तत्त्व, जार के समर्थक, जमीन्दारों एवं सामन्तों, पूँजीपतियों एवं पादरियों ने आक्रमणकारियों की सहायता की। रूस की नवगठित सरकार के लिए निश्चय ही यह गम्भीर संकट की घड़ी थी। किन्तु रूस के सौभाग्य से उसके शत्रु देश विश्वयुद्ध से लड़ते हुए इतने थक एवं पस्त हो गये कि वे पूरी शक्ति से रूस पर आक्रमण नहीं कर सके।</p>\r\n<p> लेनिन के नेतृत्त्व में बोल्शेविक सरकार ने दृढ़ता से इन आन्तरिक एवं बाह्य शत्रुओं का सामना किया। बाह्य आक्रमणकारियों से निबटने के लिए ट्राटस्की एवं स्टालिन के नेतृत्त्व में लाल सेना (Red Army) का गठन किया गया, तथा आन्तरिक शत्रुओं का सामना करने के लिए \"चेका\" नामक पुलिस संगठन का जन्म हुआ। ट्राटस्की एवं स्टालिन के नेतृत्त्व में लाल सेना ने 1920 ई. तक बाह्य शत्रुओं को मार भगाया। विदेशी राष्ट्रों को रूस के विरूद्ध नाकाबन्दी को समाप्त करना पड़ा। 1922 ई. को जापान साइबेरिया से हट गया। 1924 ई. तक इटली जर्मनी एवं इंगलैण्ड ने रूस की नई सरकार को मान्यता प्रदान की।</p>\r\n<p>देश के अन्दर के दुश्मनों के साथ भी बोल्शेविक सरकार बड़ी सख्ती से पेश आयी। बोल्शेविक सत्ता के विरूद्ध बगावत को बहुत क्रूरतापूर्वक दबा दिया गया। क्रांति की रक्षा के लिये नये पुलिस संगठन “चेका\" ने देश में आतंक का राज्य कायम कर दिया। 1918 एवं 1922 ई. के बीच लगभग तेहर हजार व्यक्तियों की क्रांति-विरोधी होने के आरोप में फाँसी पर लटका दिया गया। लेनिन ने सर्वहारा वर्ग के अधिनायकत्व की स्थापना के लिए खून की नदी बहाने से कोई परहेज न थी। नई सरकार के ये कार्य इतिहास में \"लाल आंतक\" (Red Terror) के नाम से विख्यात हैं।</p>\r\n<h3>आर्थिक जीवन </h3>\r\n<p> विश्वयुद्ध में पराजय के कारण अपार धन-जन की क्षति एवं क्रांति के पश्चात् विदेशी आक्रमण तथा आन्तरिक विद्रोहों ने रूस की आर्थिक स्थिति को अत्यन्त जर्जर कर दिया था। अतः नई सरकार के समक्ष सबसे बड़ा संकट अर्थ का था। नई सरकार की राष्ट्रीयकरण की नीति का एक बड़ा दुष्परिणाम यह हुआ कि खेतों एवं कारखानों में उत्पादन पहले की अपेक्षा घट गया।</p>\r\n<p> नई सरकार ने इस व्यवस्था में परिवर्तन करना आवश्यक समझा। लेनिन एक यथार्थवादी एवं दूरदर्शी प्रशासक था। अतः उसने नई व्यवस्था में कुछ पूँजीवादी तत्त्वों को अपनाने की चेष्टा की। उसने अपनी नई आर्थिक नीति (New Economic Policy) को घोषणा की। इसके द्वारा आर्थिक व्यवस्था में क्रांतिकारी परिवर्तन लाये गये।</p>\r\n<p>पहले किसानों को उनकी आवश्यकता के अनुसार अनाज देकर बाकी अनाज ले लिया जाता था। उन्हें अनाज बेचने की आज्ञा नहीं थी। अब उन्हें आवश्यकता से अधिक बचे हुए अनाज को मंडी में बेचने की स्वतंत्रता दी गयी। इससे किसानों को अधिक उत्पादन की प्रेरणा मिली। उन्हें अब सरकार को कर देना पड़ता था।</p>\r\n<p> औद्योगिक क्षेत्र में भी सरकार ने छोटे-कारखानों के प्रबन्धन एवं नियंत्रण से हाथ खींच लिया। उनका नियंत्रण अब केवल बड़े कारखानों पर ही रहा। देश में पूँजी का आमंत्रित किया गया। मुद्रा का पुनः प्रचलन किया गया।</p>\r\n<p> इस नई आर्थिक नीति के परिणामस्वरूप आर्थिक अवस्था में पहले की अपेक्षा काफी सुधार हुआ। लेकिन लेनिन का यह एक अस्थाई प्रयोग था। बाद में जब सरकार की स्थिति सुदृढ़ हो गयी तो लेनिन ने मध्यम वर्ग के पूँजीपतियों एवं किसानों के उत्पादन पर पुनः अधिकार जमा लिया। नई आर्थिक नीति का काल 1921 से 1927 ई. तक था। लेनिन की यह नीति थी कि आर्थिक स्थिति में सुधार के पश्चात् पुनः साम्यवादी व्यवस्था लागू की जाय।</p>\r\n<h3>सामाजिक एवं धार्मिक परिवर्त्तन </h3>\r\n<p>बोल्शेविक क्रांति के फलस्वरूप रूस के सामाजिक एवं धार्मिक क्षेत्र में भी क्रांतिकारी परिवर्तन दृष्टिगोचर हुए। गरीबों, दलितों, शोषितों एवं पीड़ितों को आगे आने का अवसर प्राप्त हुआ। स्त्रियों को विशेष सम्मानजनक स्थान दिया गया। उन्हें पुरूषों के समकक्ष सामाजिक, राजनीतिक तथा आर्थिक अधिकार प्रदान किये गये। देश का घोर प्रतिक्रियावादी तत्त्व चर्च था। यह जारशाही का समर्थक तथा नई सरकार का घोर विरोधी था। अतः बोल्शेविक सरकार ने इसके विरूद्ध सख्ती से कदम उठाया और इसकी सारी सम्पति जब्त कर ली। लोगों को धार्मिक मामलों में स्वतंत्रता प्रदान की गयी।</p>\r\n<h3>राजनीति परिवर्तन </h3>\r\n<p> बोल्शेविक क्रांति के फलस्वरूप राजनीति क्षेत्र में क्रांतिकारी परिवर्तन हुए। जारशाही के पतन के पश्चात् जिस साम्यवादी व्यवस्था की स्थापना हुई वह विश्व में सर्वथा एक नई व्यवस्था थी। अतः लेनिन एवं स्टालिन के नेतृत्त्व में केन्द्रीय कार्यपालिका समिति (Central Executive Committee) द्वारा नियुक्त एक कमीशन ने देश के लिए एक संविधान बनाया। सोवियतों की राष्ट्रीय कांग्रेस ने 10 जुलाई 1918 ई. को इसे मान्यता प्रदान की। इस नये संविधान में सर्वहारा का गहरा प्रभाव था। इसका उद्देश्य पूँजीवादी व्यवस्था को समाप्त करना था। इसमें श्रमिकों, किसानों एवं सैनिकों को प्रतिनिधित्व प्रदान किया गया।</p>\r\n<p>सीमित रूप में जनता को कुछ मौलिक अधिकार भी दिये गये। मनुष्य के काम करने के अधिकार को प्रथम बार मान्यता प्रदान की गयी। सीमित अर्थों में यदि स्थापित समाजवादी व्यवस्था को कोई खतरा नहीं हो तो लोगों को अभिव्यक्ति की स्वतंत्रता प्रदान की गयी। सम्पूर्ण देश में समाजवादी प्रजातंत्रों का देश घोषित किया गया।</p>\r\n<p>देश की कुछ प्रमुख जातियों को सोवियत संघ में रहने या निकल जाने का अधिकार दिया गया। देश की सर्वोच्च सत्ता सोवियतों ने कांग्रेस में निहित थी। पादरियों, जमींदारों एवं पूँजीपतियों को मताधिकार के अधिकार से वंचित कर दिया गया। सोवियत की कांग्रेस को केन्द्रीय कार्यपालिका के निर्माण को अधिकार दिया गया। संविधान में साम्यवादी पार्टी के गठन, सदस्यता एवं अधिकार तथा कार्यों की गहन व्याख्या की गयी थी। इस प्रकार नये संविधान के अन्तर्गत देश में एक नई राजनीतिक तंत्र या व्यवस्था का सृजन किया गया।</p>\r\n<p>लेनिन की साम्यवादी व्यवस्था केवल रूस तक सीमित नहीं थी। वह साम्यवाद का प्रचार एवं प्रसार सारे विश्व में करना चाहता था। वह संसार के सारे पीड़ित एवं शोषित मजदूरों को एक मंच पर लाना चाहता था। इसलिए उसने \"दुनिया के मजदूरों एक हो\" का नारा दिया था। देश-विदेश में साम्यवाद के प्रचार एवं प्रसार के लिए लेनिन ने कॉमिण्टर्न (Commintern-The Third International) की स्थापना की जिसका केन्द्र मॉस्को में रखा गया।</p>\r\n<h2>1917 ई. के बोल्शेविक क्रांति का महत्त्व</h2>\r\n<p>1917 ई. की क्रांति के तात्कालिक एवं दूरगामी परिणामों के अध्ययन से स्पष्ट हो जाता है कि आधुनिक सदी के इतिहास में उसको अत्यन्त महत्त्वपूर्ण स्थान प्राप्त है । कतिपय विद्वानों ने तो इसे 1789 ई. के फ्रांस की राज्यक्रांति से अधिक महत्त्वपूर्ण माना है। उनके मतानुसार फ्रांस की क्रांति ने तो एकता, स्वतंत्रता एवं समानता (Equality, liberty and unity), लोकतंत्र एवं राष्ट्रवाद सम्बन्धी नई विचारधारा एवं भावना को जन्म दिया।</p>\r\n<p> किन्तु 1917 की रूसी क्रांति ने उससे आगे बढ़कर एक नई सामाजिक व्यवस्था का आदर्श प्रस्तुत किया। साम्यवाद के रूप में उसने विश्व को एक नई विचारधारा प्रदान की जो एक समाज, नई सभ्यता एवं संस्कृति का संदेशवाहक था। फ्रांस की क्रांति के फलस्वरूप राजनीतिक सत्ता कुलीन वर्ग के हाथों से फिसलकर मध्यम वर्ग या बुर्जुआ के हाथों में आ गयी।</p>\r\n<p> किन्तु रूसी क्रांति ने कुलीन एवं बुर्जुआ दोनों वर्ग को नाश करके सत्ता किसानों एवं श्रमिकों को सौंप दी तथा सर्वहारा वर्ग का अधिनायकत्व (Dictatorship of the Proletariat ) स्थापित किया। रूस में सर्वहारा वर्ग का अधिनायकत्व इसलिए स्थापित किया गया कि गरीब एवं शोषित श्रमिकों एवं किसानों की हितों की रक्षा की जा सके, उन्हें सुखी बनाया जा सके तथा पूँजीवाद का अन्त किया जा सके। </p>\r\n<p>लेनिन के नेतृत्व में एक वर्गविहीन समाज (Classless society) की स्थापना की गयी जिसमें शोषण के लिए कोई स्थान न था। रूस के श्रमिकों एवं किसानों को उनके परिश्रम से कोई नहीं वंचित कर सकता था। रूस की क्रांति के अत्यधिक महत्त्व का द्योतक है- इसके बाद राजनीतिक, सामाजिक एवं आर्थिक क्षेत्र में प्रारम्भ हुए क्रांतिकारी परिवर्तन- जिसकी चर्चा हम ऊपर कर चुके हैं।</p>\r\n<p>लेनिन ने जिस व्यवस्था की आधारशिला रखी उसे उसके उत्तराधिकारी स्टालिन तथा अन्य ने एक ठोस एवं विराट् रूप प्रदान किया। स्टालिन ने लेनिन द्वारा स्थापित सोवियत व्यवस्था के लिए दृष्टिकोण की नीति अपनायी। उसने योजनाकरण की नीति को अपना कर सम्पूर्ण सोवियत के जीवन-व्यवस्था में क्रांतिकारी परिवर्तनों का श्रीगणेश किया।</p>\r\n<p> देश में बड़े-बड़े कल-कारखाने तथा उद्योग-धन्धे स्थापित किये गये। कृषि के क्षेत्र में सामूहिक फार्म तथा यंत्रीकरण एवं खेती की अत्याधुनिक पद्धति को अपनाया गया। आर्थिक क्षेत्र में मात्र दस साल के अन्दर रूस ने आश्चर्यजनक प्रगति की। समाजवाद के रास्ते पर चलकर रूस तथा उसकी जनता पूँजीवादी व्यवस्था की बुराइयों सेदूर हटती चली गयी।</p>\r\n<p> बेकारी की समस्या समाप्त हो गयी। एक निम्नतम आय निर्धारित कर देने से लोगों को एक निश्चित जीवन-स्तर प्राप्त हुआ। यह सोवियत रूस से समाजवादी कार्यक्रम का कमाल था कि उसका हर नागरिक सरकार की उपलब्धियों को अपनी व्यक्तिगत उपलब्धि मानता था और देश की प्रगति के लिए हर सम्भव प्रयत्न करने को तैयार था।</p>\r\n<p>बोल्शेविक क्रांति के परिणामस्वरूप स्थापित सोवियत व्यवस्था ने सारे संसार के समक्ष एक चुनौती सी प्रस्तुत कर दी। मात्र दो दशकों के अन्दर इसने प्रमाणित कर दिया कि. यह संसार की सर्वश्रेष्ठ व्यवस्था थी । यह मात्र एक स्वप्न था इसके सिद्धान्त अव्यावहारिक नहीं थे। यह पूँजीवाद का एक ठोस विकल्प था। रूस की महान् उपलब्धियों से घबराकर पूँजीवादी एवं साम्राज्यवादी व्यवस्था के रक्षात्मक रूख अपना लिया।</p>\r\n<p>नया रूस शोषण, अन्याय, अत्याचार एवं पूँजीवाद व्यवस्था के विरूद्ध ब्रिदोह का प्रतीक था। इस अर्थ में यह संसार का आदर्श था। रूसी समाजवाद ने यूरोप के कई अन्य राष्ट्रों को भी आकर्षित करना प्रारम्भ किया। यूरोप के विश्वविद्यालयों में बुद्धिजीवियों के बीच यह चर्चा का एक रोचक विषय था- रूसी समाजवाद । इस तथ्य से बोल्शेविक क्रांति के महत्त्व का प्रमाण मिलता है।</p>\r\n<p>संसार के अन्य पराधीन एवं यूरोपीय साम्राज्यवादी राष्ट्रों द्वारा शोषित देश रूस की ओर आशाभरी नैत्रों से देखने लगे। इसलिए पराधीन राष्ट्रों को उनके स्वतंत्रता संग्राम में सहायता करने तथा यूरोप के साम्राज्यवादी देशों को सबक सिखाने के उद्देश्य से ही रूस ने \"कॉमिण्टर्न इन्टनेशनल\" नामक संस्था की स्थापना की थी।</p>',36,'2024-10-23 16:19:01','2024-10-24 08:46:32','','Publish',0,'open',16,29),('सुमेरियन धर्म की विशेषताएं','features-of-sumerian-religion',2,'<p>मोसोपोटामिया में जिन प्रसिद्ध सभ्यताओं का विकास हुआ उसमें सुमेरियन सभ्यता का महत्वपूर्ण स्थान है। <b>दजला और फरात की घाटी का दक्षिणी भाग </b> से मिले श्रोतो एवं मंदिरो के अवशेषो से हमें <b> सुमेरियनों के धार्मिक विश्वासो की जानकारी मिलती है।</b> सुमेर की संस्कृति में धर्म और मंदिरों को विशिष्ट स्थान प्राप्त था। मंदिरों को देवताओं का निवास स्थल माना जाता था, यह मंदिरों को उच्च स्थानों पर बनाया करते थे। पर्व एवं त्योहारों के दिन मंदिरों में ऐसे उत्सव हुआ करते थे, जो धार्मिक भावनाओं के साथ-साथ राष्ट्रीय भावना भी जागृत करते थे। इन उत्सवों में संगीत का काफी महत्त्व था, इस धर्म के कुछ महत्वपूर्ण विशेषताएं निम्नलिखित है-</p>\r\n    <h2 class=\"atech\">बहुदेववादी</h2>\r\n    <p>सुमेर वासी बहुदेववादी थे। कुछ इतिहासकारों का मानना है कि सुमेरियन प्रारंभ में ऐकश्वरवादी थे, किंतु कलांतर में अनेक देवताओं की उपासना करने लगे। प्रथम में आकाश देव \'<b>अन्</b>\' को प्रमुख देवता माना जाता था। जिसका प्रमुख मंदिर \'<b>एरेक</b>\' में स्थित था। 3000 ईसा पूर्व तक अन् देवता को प्रमुखता प्रदान की जाती रही। धीरे-धीरे अन्य देवताओं को भी प्रमुखता प्रदान किया जाने लगा जैसे- वायु एवं वर्षा का देवता \'<b>एनजिल</b>\' यह ऋग्वेदकाल के इंद्र से मिलते-जुलते हैं। प्रकाश का देवता \'<b>शमश</b>\',  चन्द्र देवता \'<b>ईसिन</b>\' समस्त सृष्टि का पिता \'<b>अप्सु</b>\',  सबकी माता \'<b>तीयमत</b>\',  स्वर्ग की राजा \'<b>अनु</b>\',  मृत्युलोक का राजा \'<b>एनोमिल</b>\',  समुद्र का राजा \'<b>ईर्या</b>\' आदि। इन समस्त के ऊपर एक देवता था, जिसे सुमेरियन \'<b>इल्ल</b>\' नाम से पुकारते थे। सुमेर से प्राप्त एक त्रिमूर्ति में सन (सूर्य) सिन (चन्द्रमा) एवं वृत्त (वायु) का सम्मिलित रूप से दर्शाया गया हैं।</p>\r\n    <h2 class=\"atech\">देवियो पर विश्वास</h2>\r\n    <p>विभिन्न देवताओं के साथ-साथ <strong>सुमेर वासी इन देवताओं की पत्नियों के भी देवीयों के रूप में आराधना करते थे</strong>, उनका विश्वास था कि प्रत्येक देवता की पत्नी छाया सदृश उनके साथ रहती है। \'<b>अनु</b>\' की पत्नी \'<b>अनुता</b>\' थी, एनजिल की पत्नी \'<b>अन्नता</b>\',  ईर्या की पत्नी \'<b>देवकिन</b>\',  मादुर्क की पत्नी <b>सिनू-वनिता</b> इत्यादि। सुमेरवासियों की मान्यता थी कि पृथ्वी देवी देव संसद में अन् एवं एनिजिल के साथ बैठती है। <strong>इन छोटे देवताओं के रूप में पृथ्वी माता की कई रूपों में पूजा की जाती थी।</strong> इन सभी देवताओं में सबसे प्रसिद्ध \'<b>इन्नेनी</b>\'( Inneni ) नाम की देवी थी।</p>\r\n    <h2 class=\"atech\">देवताओं का मानवीकरण</h2>\r\n    <p>सुमेरियनों का यह विश्वास था कि देवता मानवीय गुणों से युक्त है। देवताओं का आचार-विचार एवं व्यवहार मनुष्यों के समान है, देवता भी मानवीय दुर्बलताओं के शिकार हैं। <strong>इन देवताओं का निवास एक पर्वत माना गया था।</strong> सुमेरियनों की दृष्टि में मनुष्य एवं देवता में प्रमुख अंतर यह था कि देवता अमर थे और मनुष्य नश्वर, इसके अतिरिक्त देवता मनुष्यों से अधिक बलवान थे। सुमेरियनों के अनुसार मनुष्य अधिक से अधिक नगरों का निर्माण कर सकते थे, तथा देवता सृष्टि के निर्माता थे।</p>\r\n    <h2 class=\"atech\">ग्रहो पर विश्वास</h2>\r\n    <p>सुमेर वासी देवी देवताओं के अतिरिक्त ग्रह पर भी विश्वास करते थे। ये- निमिब (शनि), नाबू (बुद्ध), नरगल (मंगल), मार्दुक (बृहस्पति), ईश्तर ( शुक्र), सिन ( चन्द्रमा ) शमाश ( सुर्य ) आदि।</p>\r\n    <h2 class=\"atech\">दानवो की कल्पना</h2>\r\n    <p>सुमेर वासी दानवो के अस्तित्व में भी विश्वास करते थे तथा इनका मानना था कि यह दानवीय शक्तियां मनुष्य को बुरे मार्ग पर ले जाती है। और उनकी यह भी मान्यता थी कि दानवो की शक्ति देवताओं से कम होती है।</p>\r\n    <h2 class=\"atech\">बली प्रथा</h2>\r\n    <p>सुमेर वासी में बलि प्रथा भी परचलीत थी। सुमेर वासी देवताओं को प्रसन्न करने के लिए या मानव कल्याणार्थ बली दी जाती थी। देवताओं के साथ-साथ दानवों को भी बलि चढ़ाई जाती थी। सर्वाधिक बली सृष्टि के देवता को चढ़ाई जाती थी।</p>\r\n    <h2 class=\"atech\">कर्म-काण्ड</h2>\r\n    <p>सुमेरियनो के धर्म में कर्म-काण्ड की प्रधानता थीं। उनके माताअनुसार धार्मिक अनुष्ठानों को करके बुरा व्यक्ति भी अच्छा बन सकता था। इस धर्म में ईश्वर प्राप्ति कल्पनाओं की लिए कोई स्थान नहीं था। सुमेरियन नगरों के उत्खनन मैं प्राप्त पात्रों एवं रिलिफ चित्रों से ज्ञात होता है <strong>ये लोग मंदिरों में दूध, मक्खन, रोटी एवं मदीरा चढ़ाते थे। पुजारी उनके ओर से पूजा करके देवताओं को भोग लगाता था।</strong> इस प्रकार देवताओं के समक्ष भेंट अर्पित करके सुमिरन अधिक कृषि, उत्पादन, पर्याप्त सिंचाई, जल एवं बाढ़ मुक्ति के लिए प्रार्थना करते थे।</p>\r\n    <h2 class=\"atech\">पाप-पुण्य</h2>\r\n    <p>सुमेर वासी का विश्वास था कि मनुष्य के कर्मों का फल इसी जन्म में प्राप्त हो जाता है। देवताओं की पूजा के अभाव में मानव कल्याण संभव नहीं है, सुमेरियनो ने आठ प्रकार की पाप बताए हैं- ईश्वर के प्रति श्रद्धा न रखना, झूठ बोलना, पड़ोसियों को धोखा देना, आपसी फूट फैलाना, वयभिचार करना, पड़ोसियों से दुर्व्यवहार करना, लड़ाई करना, व्यापार में बेमानी करना आदि। पाप से मुक्ति के लिए देवताओं की उपासना करना एकमात्र साधन हैं।</p>\r\n    <h2 class=\"atech\">परलोक विषयक कल्पना</h2>\r\n    <p><strong>सुमेर वासियों का विश्वास था कि \'<b>कुर</b>\' अथवा पाताल पृथ्वी के नीचे स्थित एक ऐसा अंधकारमय स्थान था जहाँ अच्छी एवं बुरी आत्माये रहती है। तथा इसमें प्रवेश हेतु मृत्यु की नदी \'<b>वैतरणी</b>\' को पार करना होता था।</strong> इरेसकीगल तथा नेरगल पाताल लोक पर शासन करते थे। गिल्गामेश वाहाँ का न्यायाधीश थे। इसके संबंध में एक आख्यान प्राप्त हुआ है। जिसमें बताया गया है कि- स्वर्ग की रानी इन्ना को एक बार पाताल पर अधिकार करने की इच्छा हुई लेकिन वह पाताल जाकर वापस लौट नहीं पाई वरन् मृत्यु को प्राप्त हो गई। तत्पश्चात एनकी की सहायता से उसे इस आधार पर पुनर्जीवन मिला कि वह अपने स्थान पर किसी अन्य देवता को पाताल लोग भेज देंगी। इन्नाने वापस आकर अपने पति को मारकर पाताल भेज दिया। प्रथम बार किसी प्राणी के पाताल से लौटने का वर्णन है। यही कारण है कि इस आख्यान का अत्यधिक महत्त्व है।</p>\r\n    <h2 class=\"atech\">मृतक संस्कार</h2>\r\n    <p>सुमेरियन धर्म में मृतक संस्कार को पर्याप्त महत्त्व प्राप्त था। प्रायः मृतकों को मकान के प्रांगण ( आंगन ) अथवा कमरे में दफना दिया जाता था। नगर के बाहर भी समाधियाँ देखने को मिली है। समाधियों के साथ दैनिक उपयोग की सम्रागी भी प्राप्त हुई हैं।</p>\r\n    <h2 class=\"atech\">देवालय एवं पुरोहित</h2>\r\n    <p>सुमेर वासी के प्रत्योक नगर में एक बहुत बड़ा देवालय था \'<b>जिगुरत</b>\' कहा जाता था। यह मंदिर अथवा देवालय अत्यंत विशाल होते थे तथा धन-धान्य से परिपूर्ण होते थे। इन मंदिरों में एक मुख्य पुरोहित होता था कुछ अन्य पुरोहित भी होते थे- यथा गाने वाले ,जादू जानने वाले, भविष्यवाणी करने वाले। पुरोहितों को समाज में बहुत बड़ा प्रभाव था।</p>\r\n    <p>इस प्रकार उपरोक्त अध्ययनो से यह स्पष्ट होता है कि सुमेरियनों द्वारा स्थापित धर्म का एकमात्र उद्देश्य सांसारिक सुखों की प्राप्ति थीं। वे धार्मिक क्रियाकलापों का आयोजन परलौकिक जीवन के लिए नहीं बल्कि पृथ्वी पर शारीरिक लाभ हेतु करते थे।</p>',0,'2024-10-23 16:19:01','2024-10-24 08:47:44','','Publish',0,'open',0,30),('साम्राज्यवाद - उदय के कारण, विशेषताएं और प्रभाव','imperialism-causes-features-and-effects-of-rise',2,'<p>जब कोई राज्य शक्ति द्वारा अथवा अन्य उपायों से अपनी सत्ता और प्रभुता का विस्तार अपने राज्य की सीमाओं से बाहर करने लगता है तो वह राज्य साम्राज्य का रूप धारण कर लेता है उसकी यह नीती  <strong>साम्राज्यवाद</strong> कहलाती है। साम्राज्यवाद वह दृष्टिकोण है जिसके अनुसार कोई महत्वाकांक्षी राष्ट्र अपनी शक्ति और गौरव को बढ़ाने के लिए अन्य देशों के प्राकृतिक और मानवीय संसाधनों पर अपना नियंत्रण स्थापित कर लेता है, यह हस्तक्षेप राजनीतिक, आर्थिक, सांस्कृतिक या अन्य किसी भी प्रकार से हो सकता है।</p>\r\n    <p>चार्ल्स ए वेयर्ड के अनुसार- <i>\"सभ्य राष्ट्रों की कमजोर एवं पिछड़े लोगों पर शासन करने की इच्छा व नीति ही साम्राज्यवाद कहलाती हैं।\"</i> प्रथम विश्व युद्ध के पूर्व यूरोप की राजनीति का केंद्र साम्राज्यवाद था। साम्राज्यवाद के विकास के कई कारण थे।-</p>\r\n    <h2>साम्राज्यवाद के उदय के कारण</h2>\r\n    <h3 class=\"atech\">औद्योगिक क्रांति</h3>\r\n    <p>औद्योगिक क्रांति के परिणामस्वरूप यूरोप के देशों में धन का अत्यअधिक संचय हुआ। इस धन को वह यूरोप के देशों में व्यय करते हैं तो उन्हें लाभ की संभावना बहुत कम थी जबकि पिछड़े हुए देशों में उन्हें अत्यधिक लाभ की संभावना थी। इसका मुख्य कारण वहाँ श्रम (मजदूरी) सस्ता तथा लोगो की बहुसंख्य आदि थीं, इसी कारण से लोगों में इन देशों में अपनी पूंजी लगाने की होड़ प्रारंभ हुई।</p>\r\n    <h3 class=\"atech\">कच्चे माल की आवश्यकता</h3>\r\n    <p>साम्राज्यवाद का एक प्रमुख कारण औद्योगिक देशों द्वारा कच्चे माल की आवश्यकता थी। जैसे कपास, रबर, टीन, झूट, लोहा आदि इसी कारण इन देशों ने ऐसे उपनिवेश पर अधिकार करने का प्रयास करने लगे जहाँ पर्याप्त कच्चा माल आसानी से प्राप्त हो जाए।</p>\r\n    <h3 class=\"atech\">बाजार की आवश्यकता</h3>\r\n    <p>औद्योगिक देशों को अपने निर्मित माल की बिक्री के लिए बड़े बाजार की जरूरत थी। ऐसे में बाजारों की खोज के तहत उपनिवेश स्थापित किए गए एवं उपनिवेशिक स्थानों पर मनमाने ढंग से माल की बिक्री के लिए उपनेवशिक साम्राज्य की आवश्यकता महसूस हुई और वे मनमाने ढंग से एकाअधिकार करना शुरू किया और मनमाने ढंग से अपना माल बेचने लगे।</p>\r\n    <h3 class=\"atech\">यातायात और संचार के साधन का विकास</h3>\r\n    <p>18 वीं- 19 वीं शताब्दियों में यातायात तथा संचार के साधनों का अत्यधिक विकास हुआ। सड़कों, रेलों से एक दूसरे क्षेत्र की को जोड़ा गया। रेल, डाक-तार व्यवस्था, टेलीग्राफ, समुद्री जहाजों के प्रयोग से उपनिवेशों पर नियंत्रण करना आसान हो गया।  वाष्प चलित बड़े जहाज बनने लगे जिसकी मदद से ज्यादा भार के सामानों को दूर देशों से लाना आसान हो गया।</p>\r\n    <p>टेलीग्राफ और तार के द्वारा सुदूर देशों से घर बैठे ही व्यापारिक सौदे किए जाने लगे। इसने शासन वर्ग व व्यापारी वर्ग की अनेक समस्याओं का समाधन कर दिया यूरोप की साम्राज्यवादी शक्तियों ने इन सबका पर्याप्त मात्रा में लाभ उठाया।</p>\r\n    <h3 class=\"atech\">जनसंख्या में वृद्धि</h3>\r\n    <p>19 वीं सदी में यूरोप में बढ़ती हुई जनसंख्या ने औद्योगिक देशों को चिंता में डाल दिया इस बढ़ती आबादी से रोजगार और आवास की समस्या पैदा हुई। इस समस्या का एक ही उपाय था कि यूरोपिय देश अपने लोगों को बसाने के लिए उपनिवेशों की स्थापना करें। उपनिवेश इन्हें रोजगार और आवास दोनों ही सुविधा उपलब्ध करा सकते थे।</p>\r\n    <h3 class=\"atech\">ईसाई मिशनरियों की भूमिका</h3>\r\n    <p>यूरोपीय ईसाई मिशनरियों ने अपने धर्म प्रचार के उद्देश्य से उपनिवेशिक विस्तार को अपनाया। ईसाई मिशनरियों ने अपने धर्म को समस्त लोगों में फैलाना चाहते थे इसी कारण वे उपनिवेश स्थापित किए तथा वह अपना वर्चस्व कायम किया। इसी संदर्भ में इंग्लैंड के डॉक्टर डेविड लिगस्टोन कहते हैं- <i>जिसने अफ्रीका में जैम्बेजी और कांगो नदी क्षेत्र की खोज कर अफ्रीका में ईसाई धर्म के प्रचार प्रसार के साथ-साथ अपने देश के राजनीतिक, आर्थिक, साम्राज्य की वृद्धि के लिए प्रयत्न किया।</i></p>\r\n    <h2>साम्राज्यवाद की विशेषता</h2>\r\n    <p>साम्राज्यवाद की कुछ विशेषताएं निमलिखित हैं-</p>\r\n    <ul>\r\n        <li><p>साम्राज्यवाद अपने राज्य की सीमाओं में वृद्धि करने में विश्वास रखता है ताकि वे अपना शासन के शक्ति प्रदान कर सकें। सीमाओं के विस्तार से लोगों के साथ अपने वर्चस्व कायम कर सके।</p></li>\r\n        <li><p>साम्राज्यवादी देश अपने हितों की रक्षा के लिए सभी प्रकार के साधनों का प्रयोग करता है।</p></li>\r\n        <li><p>साम्राज्यवाद का मुख्य उद्देश्य अपने से अधीन देशों को अपने शक्ति से उनपर शासन कर शोषण करना है।</p></li>\r\n        <li><p>साम्राज्यवाद का प्रमुख आधार सैनिक शक्ति होता हैं।</p></li>\r\n        <li><p>साम्राज्यवाद का मुख्य उद्देश्य तो आर्थिक होता है, परंतु कभी कभी सैनिक व राजनीतिक शोषण भी हो सकता हैं।</p></li>\r\n    </ul>\r\n    <h2>साम्राज्यवाद का प्रभाव</h2>\r\n    <p>आर्थिक शोषण साम्राज्यवाद का सबसे बड़ा प्रभाव है उदाहरण के लिए अंग्रेजो ने भारत में चाय, नील और कॉफी के बगान स्थापित किए और अपार धन संचय करने के लिए स्थानीय प्राकृतिक साधनों का दोहन किया। साही शक्ति ने अपने आयातित इंजनों को चलाने के लिए स्थानीय कोयला खदानों का शोषण किया, साथ ही नमक उत्पादन पर भी इन्हीं का अधिकार था। स्थानीय लोगों पर नमक बनाने या बेचने पर प्रतिबंध लगा दिया, जिससे इन्हें महंगा भारी कर वाला नमक खरीदना पड़ता था।</p>\r\n    <p>एक और महत्वपूर्ण कारण सांस्कृतिक वर्चस्व था जिसमें स्वदेशी संस्कृतियों और परंपराओं को दबाया जाने लगा और उपनिवेशी लोगों द्वारा भाषा, धर्म और अन्य रीती-रिवाजों को जबरन थोपा जाने लगा। उपनिवेशो को कोई स्वतंत्र नहीं थी उनका शोषण किया जाता था और उनके साथ गुलामों जैसा व्यवहार किया जाता था।</p>\r\n    <p>स्वदेशी उद्योग धंधे समाप्त होने के कारण उपनिवेश गरीब और बेरोजगारी में डूब गए। कृषि का पारंपरिक विधि पूरी तरह बदल गई क्योंकि अब खाद्य फसलों की तुलना में कच्चे माल की खेती करने के लिए मजबूर किया गया। आर्थिक स्तर पर उद्योग सड़क एवं रेल जैसे ढांचागत परियोजनाओं के विकास से आवागमन को गति मिला और लोगों के बीच की दूरी समाप्त हुई। </p>\r\n    <p><i>\"फूट डालो राज़ करो\"</i> की नीती से विभिन्न समुदायों से सांप्रदायिकता का विकास हुआ जो वर्तमान में भी गंभीर चुनौती बनी हुई है।</p>\r\n    <h2 class=\"atech\">निष्कर्ष</h2>\r\n    <p>इस प्रकार उपरोक्त अध्ययनों से हम इस निष्कर्ष पर पहुँचते हैं कि यूरोपीय देशों में औद्योगिक क्रांति के पश्चात उत्पन्न परिस्थितियों ने उपनिवेशवाद को बढ़ावा दिया जो आगे चलकर साम्राज्यवाद में परिवर्तित हो गया। सबसे पहले उन्होंने अफ्रीकी देशों को निशाना बनाया जिसके बाद वे एशिया पर भी अपना प्रभाव बढ़ाने लगे। इस प्रकार 20 वीं शताब्दी तक यूरोपीय शक्तियों ने अफ्रीका एवं एशिया में अपनी साम्राज्यवादी भूख को काफी हद तक शांत कर लिया था किंतु उसकी वह विजय स्थाई न रह सकी, आगे चलकर यही सम्यवादी विचारधारा ने विश्व को दो-दो विश्व युद्ध की विभिसीका में धकेलने का भी कार्य किया।</p>',19,'2024-10-23 16:19:01','2024-10-24 08:48:39','','Publish',0,'open',29,31),('शांग राजवंश - आर्थिक एवं धार्मिक स्थिति','shang-dynasty-economic-and-religious-situation',2,'<p>शांग राजवंश प्राचीन चीन में लगभग 1786 ईसा पूर्व से 122 ईसा पूर्व तक राज़ करने वाला राजवंश था। इस राजवंश ने चीन की सभ्यता में कई योगदान दिये- लेखन का आविष्कार, युद्ध में रथ और कांस्य हथियारों का इस्तेमाल, योजनाबद्ध तरीकों से खेती, समय का मापदंड आदि। इस राजवंश की जानकारी अधिकतर <strong>ह्वाग-हो नदी (पीली नदी)</strong> के पास अन्यांग नाम की जगह खुदाई से प्राप्त औजारो, शीलालेखों से होती है।</p>\r\n<p>कुछ इतिहासकारों के अनुसार लगभग 1400 से 1320 ईसा पूर्व में पान-किंग(Pan-Keng) नाम का एक राजा अपनी राजधानी अन्यांग नामक शहर में बनाई थी। यह शहर ह्वाग-हो नदी के किनारे बनाया गया था, इस नगर को <strong>शांग लोगों का महानगर ( The Great City of Shang )</strong> कहा गया। अन्यांग शहर से जिस राज्य पर शासन होता था उसे शांग राजवंश का राज्य कहा जाता था। शांग राजवंश के राजाओं को शत्रुओं के आक्रमण के कारण अपनी राजधानी पांच बार बदलनी पड़ी थी। अन्यांग शहर इनका अंतिम राजधानी था।</p>\r\n<p>शांग राजवंश के शासन से पहले शिया राजवंश का शासन था। ये लोग पथरो को औज़ारों के रूप में प्रयोग करते थे, और यह खानाबदोश थे। शांग राजवंश ने इन पर विजय प्राप्त कर इनको अपना दास बना लिया था, इन लोगों से ही नगर निर्माण कार्य में काफी सहायता ली होगी।</p>\r\n<p>शांग राजवंश के समय नगरों का अत्यधिक विकास हो चुका था। वे अपने घर मिट्टी का बनाते थे और दीवारों को रंगकर सजाएँ करते थे। घर क बीच में एक बड़े आंगन हुआ करता था, घरों के निर्माण में अत्यधिक लकड़ियों का उपयोग किया जाता था। शांग युग में ईंटों का प्रयोग नहीं होता था, खुदाई में एक बड़ा सा कमरा मिला है जिसकी लंबाई चौड़ाई 92x29 फुट है। घरों के आंगन में कब्र भी पाई गई है, कब्ररों की रंगाई भी की जाती थी। शांग राजवंश के समय दास और नौकरों के लिए घर जमीन के अंदर गड्ढो में बनाया जाता था, जिसकीकी ऊँचाई करीब छह से सात फुट तथा इनका ब्यास 10 फुट होता था। इस समय बहुत से झोपड़ियां भी पाई जाती थी संभवतः मध्यम वर्ग के लोग इन झोपड़ियों में रहते होंगे।</p>\r\n<p>खुदाई से यह भी पता चलता है कि शांग युग के राजा और कुलीन अपनी बहुमूल्य वस्तुओं गड्ढा खोदकर जमीन में रखा करते थे। ऐसा एक खाई खुदाई में मिली है, जिनमें 5801 वस्तुएं प्राप्त हुई हैं जिनमें अच्छे बर्तन, हड्डियॉ, कछुवे की खोपड़ी, कांसा, सोना आदि मिले हैं।</p>\r\n<p>शांग युग में नगरों की रक्षा के लिए एक दिशा में मिट्टी की दीवार बनाई गई थी, बाकी तीनों ओर से ह्वाग-हो नदी बहती थी। संभवतः यह दीवार सुरक्षा की दृष्टि से बनाई गई होगी। 193 ईस्वी में हुआंग नदी से कछुए की खोपड़ी पर कुछ लेख प्राप्त हुए हैं, इन लेखों को<strong>\"ओरेकल बोन\"</strong> कहा जाता है। इस लेखों से हमें शांग वंस के अत्यधिक जानकारी प्राप्त होती हैं।</p>\r\n\r\n<h2>शांग राजवंश के समय आर्थिक एवं धार्मिक स्थिति का वर्णन</h2>\r\n<p>चीन के इतिहास में शांग वंश का इतिहास काफी महत्वपूर्ण माना जाता है। चीन के ह्वाग-हो नदी के पास अन्यांग नामक संस्थान पर खुदाई से बहुत सारी सामग्री प्राप्त हुई है, जिससे हमे शांग वंश के इतिहास का ज्ञान होता है। इस खुदाई से प्राप्त अवशेष के अनवेशन से उस समय की धार्मिक एवं आर्थिक स्थिति का ज्ञान होता है, इस युग की आर्थिक एवं धार्मिक स्थिति का संक्षिप्त विवेचना निम्नलिखित है- </p>\r\n<h3 class=\"atech\">आर्थिक व्यवस्था</h3>\r\n<p>शांग वंश के लोग मुख्य रूप से अपनी जीविका के लिए खेती पर निर्भर रहते थे। ये लोग घरेलू जानवर भी पालते थे एवं ये लोग शिकार भी किया करते थे। इनके शिकार के कई उद्देश्य थे शिकार से इन लोगों को भोजन, मनोरंजन, कुछ पहनने का सामान तथा सेना को लड़ने का अभ्यास आदि कार्य एक साथ हो जाता था। इसकी पुष्टि ओरेकल बोन से प्राप्त लेखों से होती है।</p>\r\n<p>इस काल में कई जानवर पाले जाते थे, कुत्ते, सुअर, भेड़, बकरी, बैल एवं बंदर। घोड़े एवं हाथी को लेकर विद्वानों में मतभेद हैं परंतु इस काल में हाथी के हड्डियों पर उकेरे लेख मिले हैं, जिससे इस बात की पुष्टि होती है कि इस काल में हाथी भी पाले जाते थे। क्रील के अनुसार <i>लोग घोड़े भी पालते थे जिसका प्रयोग रथो को हांकने के लिए किया जाता था।</i> इस समय अधिकतर मात्रा में रथ पाए गए हैं। इस काल में भोजन के लिए जिन जानवरों को उपयोग होता था उनमें गाय, कुत्ते, भेड़, बकरी, सुअर आदि थे। कुत्ता एवं सुअर बड़े चाव से खाया जाता था, बड़ी संख्या में दूध देने वाली जानवर पाली जाती थी।</p>\r\n<p>कुछ विद्वानों के अनुसार शांग युग में चारागाह काफी संख्या में थी। <strong>कुछ ओरेकल बोन के लेखों पर चारागाह से संबंध झगड़ों का भी उल्लेख है।</strong> इस आधार पर कुछ विद्वान् ने यह मान लिया था कि इस युग में लोग <strong>खानाबदोश</strong> थे, जिन्होंने हाल ही में खेती करना सीखा था। लेकिन प्रोफ़ेसर क्रील इस मत को नहीं मानते उनका कहना है- <i>इस युग में चीनी कृषक थे, जो घर बना कर गांव और शहरों में रहा करते थे और काफी संख्या में पालतू जानवर रखते थे।</i> और उनका यह भी मानना है कि चीनीयों के अधिकांश पूर्वज किसी भी समय में मवेशियों को लेकर घूमने वाले खानाबदोश नहीं थे बल्कि शुरू से ही घर बनाकर रहते थे।</p>\r\n<p>शांग युग के लोगों के जीविका का प्रमुख साधन खेती थी, ये बहुत योजनाबद्ध तरीकों से खेती किया करते थे। ये लोग बसंत ऋतु के दूसरे या तीसरे महीने में पूजा-पाठ के द्वारा यह निश्चित करते थे कि इस बार कौन सी फसल बोएंगे। इस समय ये लोग अपने पूर्वजों की विशिष्ट पूजा करते थे और उनसे प्रार्थना करते थे कि उनकी फसल अच्छी हो और पूजा के बाद ही फसल बोई जाती थी। उनका मानना था कि पूर्वज व पितरों (देवता) उनके फसल को अच्छी और प्रचुर मात्रा में फसल उपज करने में मदद करते हैं।</p>\r\n<p>इस काल में गेहूं, बाजरा, जौ आदि की खेती मुख्य रूप से की जाती थी, लेकिन चावल के विषय में विद्वानों में मतभेद हैं। इस युग में उतरी चीनी क्षेत्र की जलवायु चावल की खेती की लाइट थी और जमीन भी उपयुक्त थी। इसलिए ये लोग संभवतः चावल की खेती किया करते थे। बाजरे से ये लोग एक प्रकार का पेय पदार्थ बनाते थे।</p>\r\n<p>इस काल के लोग कपड़े बनाने के पौधों को भी उगाना जानते थे। पुरात्ववेता के अनुसार नवपसान युग से ही उत्तरी चीन में कई ऐसे पौधे उगाया जाता था, जिनसे कपड़े बनाए जाते थे। संभवत: यह पौधा एक प्रकार का सन(Jute) था, जिसके रेसो से कपड़े बनाए जाते थे।</p>\r\n<p>खेती काम अधिकतर पुरुष किया करते थे, लेकिन कुछ पौधों को स्त्रियाँ भी करती थी। संभवतः कपड़े बनाने वाले पौधों को उगाती थी, जिसमें रेशम तथा सन था। खेती के लिए जिन औज़ारों का प्रयोग करते थे वे संभवतः लकड़ी के बने होते थे। खेती के लिए जिन जानवरों का उपयोग लिया जाता था, उनमें बैल एवं गद्हा थे, इनसे वे खेत की जुताई करते थे।</p>\r\n<p><strong>शांग युग में आर्थिक समृद्धि के तीन साधन थे- कृषि, पशुपालन और शिकार करना।</strong> इन तीनों के साथ यूद्ध को भी जोड़ सकते हैं, युद्ध के साथ काफी लूट का माल आता था। शांग युग में थोड़ा <strong>वाणिज्य-व्यापार</strong> भी होता था, गाय, घोड़े और अनाज विनिमय के साधन माने जाते थे। संभवत: नागरों के बीच यह व्यापार होता था, इस समय केंद्रीय राजनीतिक सत्ता का अभाव था। इस युग में संभवतः कौड़ियों का प्रयोग सिक्कों की तरह होता था। 163 कौड़िया पाई गई है जो काफी बेशकीमती किस्म के हैं, इस वंश के समय पुरस्कार के रूप में कौड़िया दिया जाता था। जो संभवत: आज भी चीन में पुरस्कार के रूप में जो शब्द मिलता है उसमें <strong>\"कौड़ी\"</strong> का चित्र बना होता हैं।</p>\r\n<p>शांग युग के लोग छपाई एवं बटन बनाने की कला में माहिर थे। छपाई के अलावा ये लोग चटाई और टोकरी बनाने भी जानते थे। इन लोगों को पॉलिश करने का भी ज्ञान था क्योंकि अन्यांन शहर के लोग पॉलिश की हुई कुल्हाड़ियों का प्रयोग करते थे। शांग लोग को पत्थर के कंगन और अंगूठी भी बनाने जानते थे, ये लोग मिट्टी के सुन्दर-सुन्दर बर्तन एवं दीवारें पर रंगों की डिजाइन बनाने अच्छी तरह जानते थे। इनकी बनाई हुई सामानों को एक जगह से दूसरी जगह भी ले जाया जाता था, इससे यह पुष्टि होती है कि व्यापार एक शहर से दूसरे शहरों में भी होता था परंतु सिक्कों के अभाव की वजह से उनतीशील व्यापार होना संभव नहीं हैं।</p>\r\n<h3 class=\"atech\">धार्मिक व्यवस्था</h3>\r\n<p>शांग युग में धर्म का मुख्य रूप पितरो और पूर्वजों की पूजा से संबंध था। प्राचीन चीन में पूर्वजों का अत्यंत महत्वपूर्ण स्थान था, उनको मृत व्यक्ति न मानकर शक्तिशाली देवता माना जाता था। ऐसा विश्वास किया जाता था कि मरने के बाद पूर्वज के हाथों में आशिम शक्ति आ जाती है, ऐसा भी माना जाता था कि लड़ाई तथा अन्य कार्यों में सफलता या विफलता पूर्वजों की कृपा दृष्टि पर निर्भर करती थी और अप्रसंन होने पर ये पूर्वज अकाल, पराजय, बिमारी और मौत भेजकर दण्ड देते हैं। यह मानना गलत होगा कि शांग युग के निवासी अपने पूर्वजों को केवल भय या आतंक की दृष्टि से देखते हैं वास्तव में अपने पूर्वजों के प्रति गहरी निष्ठा और भक्ति रखते थे। घर में बड़े बुजुर्गों को मरने पर वास्तविक और गहरा शोक व्यक्त किया जाता था।</p>\r\n<p>अन्यांग के पास शांग युग के 300 कब्रों की खुदाई हुई। इस खुदाई से उन लोगों के शव-संस्कार की प्रक्रिया का पता चलता है। इनकी शव-संस्कार के बारे में एक विचित्र बात देखने को मिलती है, ये लोग मुरदों को मुँह के बल सुलाया करते थे। किसी भी कब्र में शवपेटीका नहीं पाई गई है, इससे यह अंदाजा लगाया जाता है कि शव को दफनाने से पहले चटाई मे लपेटा जाता था। शव के साथ ये लोग कांसे के सामान भी गाड़ दिए जाते थे एवं मृतक के हैसियत अनुसार कब्र में वस्तुएं भी रखी जाती थी। बहुत से कब्रों में कांसे के बनी हुई कटारी नुमा कुल्हाड़ी एवं कुछ मिट्टी के बर्तन मिले हैं। धनी लोगों के कब्रों में कांस्य की सुन्दर-सुन्दर बर्तन भी रखे जाते थे।</p>\r\n<p>राजाओं की कब्र में बहुत बहुमूल्य पदार्थ रखे जाते थे और इन कब्रों की रंगाई भी किया जाता था। दुर्भाग्यवस राजाओं के कब्रों से वस्तुएं चुरा भी लिया जाता था। राजाओं के शव-संस्कार के समय बहुत से मनुष्यों को बलिदान भी चढाया जाता था। ऐसा विश्वास किया जाता था कि मरे हुए पूर्वज अंतरिक्ष में निवास करते हैं और उन्हें लोगों की आवश्यकता पड़ती होगी। ओरेकल बोन के लेखों से यह पता चलता है कि शांग युग के लोग अपने पूर्वजों से सहायता मांगते थे और उनको उतना ही बलिदान देते थे। मृत रानियों को भी पूजा और बलिदान चढ़ाए जाते थे, उनका मानना था कि स्त्रियों को संतान स्त्री पूर्वज की कृपा पर निर्भर माना जाता था।</p>\r\n<p>पूर्वजों के अलावा इनमें कुछ प्रमुख देवता थे- सरदार-सर्व-स्त्री (Dragon Woman)। बाद में पहाड़ों और नदियों की पूजा होने लगी, इसके अलावा वायु देवता, सर्प देवता एवं टी (Ti) नामक दूसरा देवता होता था। उनका मानना था कि टी ने ही इस पृथ्वी का निर्माण किया।</p>\r\n<p>शांग युग में चीनी कई तरीकों से देवताओं की इच्छा जानने की कोशिश करते थे, खासकर कछुए की हड्डियों पर लिखकर देवताओं से प्रार्थना किए जाते थे एवं जवाब के रूप में उन्हें स्वपन आता था।</p>\r\n<p>शांग युग के लोग बलिदान को विशेष महत्त्व देते थे। उनका मानना था कि मृत व्यक्तियों को भी भोजन की आवश्यकता होती है। बलिदान देते समय बहुत से पेय पदार्थ(सराब) भी जमीन पर गिराए जाते थे। जानवरों को भी कभी-कभी जमीन में गाड़ दिया जाता था, जिन जानवरों को बलिदान दिया जाता था उनमें प्रमुख गाय, सुअर, बकरी, भेड़ आदि है कभी-कभी मुर्गों को भी चढ़ाया जाता था। कुछ लेखों से यह पता चलता है कि शांग युग के लोग मंदिरों में भी बलिदान चढ़ाएं करते थे।</p>\r\n<p>शांग युग के लोग अधिकतर बलिदान बसंत ऋतु में फसलों की बुआई करते समय चढ़ाते थे। संभवत: उनका मानना था कि बलिदान से फसल अच्छे होगी, यह भी संभव है कि हेंमत ऋतु में भी फसल काटने के बाद भी कृतज्ञाता-ज्ञापन के रूप में बलिदान चढ़ाए जाते होंगें। एक बलिदान के समय 10 तक जानवर चढ़ाए जाते थे, कभी-कभी 50-100 या 200 जानवर का भी बलिदान चढ़ाया जाते थे।</p>\r\n<h2 class=\"atech\">निष्कर्ष</h2>\r\n<p>इस प्रकार उपरोक्त अध्ययनों से हम पाते हैं कि चीन की इतिहास में शांग वंश का काल आर्थिक व धार्मिक दृष्टि से संपन्न एवं समृद्ध काल था। इस वंश के दौरान चीन में अद्भुत संस्कृतियों, गतिविधियाँ संचालित हुई। इसलिए ऐतिहासिक दृष्टि से चीनी सभ्यता के विकास में शांग वंश का काफी महत्त्व हैं।</p>\r\n',0,'2024-10-23 16:19:01','2024-10-24 08:49:43','','Publish',0,'open',26,32),('वैदिक साहित्य क्या है','what-is-vedic-literature',2,'<p>वैदिक साहित्य हिंदू धर्म के प्राचीनतम स्वरूप पर प्रकाश डालने वाला तथा विश्व का प्राचीनतम स्रोत है। वेद शब्द संस्कृत भाषा के \"<strong>विद्</strong>\" धातु से बना है, इसका अर्थ \"<strong>ज्ञान होना</strong>\" है। वेदों को \"<strong>अपौरुषेय</strong>\" (किसी पुरुष द्वारा न बनाया हुआ) या ईश्वर द्वारा रचित माना गया है। अर्थात वेदों की रचना ईश्वरीय प्रेरणा के आधार पर ऋषियों ने की है, इसलिए ये शाश्वत है। वैदिक साहित्य को श्रुति कहा जाता है, क्योंकि <strong>(सृष्टि/नियम) कर्ता ब्रह्मा ने विराटपुरुष भगवान् की वेदध्वनि को सुनकर ही प्राप्त किया है।</strong> अन्य ऋषियों एवं ऋषिकाओं ने भी इस साहित्य को श्रवण-परम्परा से ही ग्रहण किया था तथा आगे की पीढ़ियों में भी ये श्रवण परम्परा द्वारा ही स्थान्तरित किये गए। इस परम्परा को श्रुति परम्परा भी कहा जाता है तथा श्रुति परम्परा पर आधारित होने के कारण ही इसे श्रुति साहित्य भी कहा जाता है।</p>\r\n    <p>अध्ययन की सुविधा के लिए वैदिक साहित्य को तीन युगों में बांटा जा सकता है- प्रथम काल संहिताओं का युग, द्वितीय काल ब्राह्मण ग्रंथों का युग और तृतीय काल उपनिषदों, अरण्यको, विदांग और सूत्र साहित्य का युग।</p>\r\n    <h2>प्रथम काल</h2>\r\n    <h3 class=\"atech\">संहिता </h3>\r\n    <p>संहिता का अर्थ संग्रह होता हैं संहिताओं में विभिन्न देवताओं के स्तुतिपरक मंत्रों का संकलन है। संहिताएँ चार है- ऋक्, यजुष्, साम और अथर्व। इन चारों संहिताओं अथवा वेदों का संक्षिप्त विवरण निम्नलिखित हैं-</p>\r\n    <h4 class=\"atech\">ऋग्वेद</h4>\r\n    <p>इसमें 10,627 मंत्र और 1020 सुक्त है, यह 10 मंडलों में विभक्त है। इसकी रचना 1500 से 1000 ईसा पूर्व में हुई थी, इसके उच्चारण करता को \"<strong>होत्र</strong>\" कहते हैं। इसके मंत्र में देवताओं की स्तुति की गई है, इनमें 33 देवताओं का उल्लेख है। इस वेद में सूर्य, उषा तथा अदित्य जैसी देवताओं का वर्णन किया गया है। इनमें 25 नदियों का उल्लेख किया गया है, जिनमें सर्वाधिक नदी सिन्धु का वर्नर अधिक है। सर्वाधिक पवित्र नदी सरस्वती को माना गया है, गंगा का एक बार तथा यमुना का तीन बार प्रयोग किया गया है। इसके द्वारा हमें ऋग्वेदकालीन राजनीतिक, सामाजिक, आर्थिक व धार्मिक दशा की जानकारी प्राप्त होती हैं।</p>\r\n    <h4 class=\"atech\">सामवेद</h4>\r\n    <p>इसमें 1550 मंत्र है। इसकी रचना 1000 से 500 ईसा पूर्व में हुई थी, इसके उच्चारणकर्ता को \"<strong>उद्गात्री</strong>\" कहते हैं। इसमें केवल 75 मंत्र नए हैं और इन मंत्रों को छोड़कर सभी मन्त्र ऋग्वेद से लिया गया है। यह गायन प्रधान वेद हैं। इसलिए इसे भारतीय संगीत का मूल्य माना जाता हैं।</p>\r\n    <h4 class=\"atech\">यजुर्वेद</h4>\r\n    <p>इसमें 40 अध्याय एवं 1975 मंत्र है। इसकी रचना काल भी 1000 से 500 ईसा पूर्व में हुई थी, इसकी उच्चारण करता को \"<strong>अध्वार्यु</strong>\" कहते हैं। इसमें यज्ञ विधियों एवं नियमों का उल्लेख मिलता है। इसकी दो शाखाएं हैं- कृष्ण यजुर्वेद और शुक्ल यजुर्वेद। इस ग्रंथ से हमें आर्यों के सामाजिक व धार्मिक जीवन के बारे में ज्ञात होता हैं।</p>\r\n    <h4 class=\"atech\">अथर्ववेद</h4>\r\n    <p>इसमें 50 मण्डल, 73 गद्य एवं पद्य सुक्त तथा 5977 मंत्र हैं। इनमें लगभग 1200 ऋग्वेद से लिए गए हैं, इनकी रचना 1000 से 500 ईसा पूर्व में हुई थी। इसके उच्चारणकर्ता को \"<strong>अथर्व</strong>\" कहते हैं। इनमें चिकित्सा, धनुर्विद्या, जादू-टोना, भूत-प्रेत आदि से संबंधित मंत्र है इनमें से कुछ मंत्र देवताओं की प्रशंसा में लिखे गए हैं।</p>\r\n    <h2>द्वितीय काल</h2>\r\n    <h3 class=\"atech\">B. ब्राह्मण ग्रंथ  </h3>\r\n    <p>चारों वेदों के संस्कृत भाषा में प्राचीन समय में जो अनुवाद थे, वे ब्राह्मण ग्रंथ कहे जाते हैं। वेद संहिताओं के बाद ब्राह्मण ग्रंथ का निर्माण हुआ। ब्राह्मण ग्रंथ को वेद का टीका भी कहा जाता है। इसमें यज्ञों के कर्मकाण्ड विस्तृत वर्णन है। साथ ही शब्दों की व्युत्पत्तियाँ तथा प्राचीन राजाओं और ऋषियों की कथाएँ तथा सृष्टि-सम्बन्धी विचार हैं।</p>\r\n    <p>ब्राह्मण ग्रंथ संसार के स्तुति के प्रथम उदाहरण हैं। वे वैदिक समाज के उत्तरकालीन ब्राह्मण समाज में परिवर्तन का बोध कराते हैं। वे यज्ञ का अर्थ बताते हुए उनके अनुष्ठान के रीति बताते हैं, जिन वेदों के साथ वे संबंधित हैं उनमें विभिन्न सूक्तों के वे भाष्य है। प्रत्येक ब्राह्मण ग्रंथ संहिता या वेद से संबंधित है। ये छ: प्रकार के होते हैं- <strong>ऐतरेय, कौषीतकी, शतपथ, पंचविंश, ताण्ड्य तथा गोपथ।</strong> ऐतरेय तथा कौषीतकी ब्राह्मण ग्रंथ ऋग्वेद से संबंधित है, शतपथ ब्राह्माण ग्रंथ का संबंध यजुर्वेद, पंचविंश ब्राह्मण ग्रंथ का संबंध सामवेद तथा गोपथ ब्राह्मण ग्रंथ का अथर्ववेद से संबंधित हैं।</p>\r\n    <h2>तृतीय काल</h2>\r\n    <h3 class=\"atech\">अरण्यक</h3>\r\n    <p>ब्राह्मणों के अन्त में कुछ ऐसे अध्याय मिलते हैं जो गाँवों या नगरों में नहीं पढ़े जाते थे। इनका अध्ययन-अध्यापन गाँवों से दूर (अरण्यों/वनों) में होता था, अतः इन्हें अरण्यक कहते हैं। <strong>इनमें दर्शन और ज्ञान की बातें लिखी हुई है।</strong> गृहस्थाश्रम में यज्ञविधि का निर्देश करने के लिए ब्राह्मण-ग्रन्थ उपयोगी थे और उसके बाद वानप्रस्थ आश्रम में संन्‍यासी आर्य यज्ञ के रहस्यों और दार्शनिक तत्त्वों का विवेचन करने वाले अरण्यकों का अध्ययन करते थे। उपनिषदों का इन्हीं अरण्यकों से विकास हुआ। ये तीन प्रकार के होते थे ऐतरेय, तैतिरीय तथा मैत्रायणी।</p>\r\n    <h3 class=\"atech\">उपनिषद</h3>\r\n    <p>इसका शाब्दिक अर्थ है- \"<strong>निकट बैठना</strong>\"। इसका वास्तविक अर्थ है कि जिज्ञासु शिष्य अपने गुरु के पास बैठता है और रहस्य सिद्धांत पर विचार-विनिमय करता है। वह ब्रह्मा और जीव के संबंध पर विचार करता है। यह रहस्यमयी ज्ञान प्रत्योक व्यक्ति को नहीं दिया जाता, अपितु केवल सुयोग्य पात्रो को ही दिया जाता था। 800 से 500 ईसा पूर्व के मध्य विभिन्न ऋषियों ने 108 उपनिषद् लिखे हैं।</p>\r\n    <p>उपनिषदों में कोई एक ही दार्शनिक धारा नहीं है इनमें कई ऐसे विद्वानों के मत हैं जो दर्शन और धर्म के ज्ञाता थे। एक आधारभूत सिद्धांत समान रूप से प्रत्योक उपनिषद में पाया जाता है। और उस सिद्धांत को इसप्रकार कहा जा सकता है- <i>\"विश्व ब्रम्हा है किन्तु ब्रह्मा आत्मा है अथवा ब्राम्हाण्ड ईश्वर है तथा ईश्वर मेरी आत्मा है।\"</i> ब्रह्मा तथा आत्मा की ये कल्पनाओ का उपनिषदों में समावेश किया गया हैं।</p>\r\n    <p>दरअसल उपनिषदों में मानव जीवन और विश्व के गुढ़तम प्रश्नों को सुलझाने का प्रयत्न किया गया है। उपनिषद् भारतीय सभ्यता की अमूल्य धरोहर है। वैदिक साहित्य के सबसे अंत में होने के कारण ये \"<strong>वेदांत</strong>\" भी कहलाते हैं। मनुष्य जीवन-मूत्यू के इस वास्तविक चक्र को समझ सके, इसी उद्देश्य से उपनिषदों की रचना हुई हैं।</p>\r\n    <h3 class=\"atech\">सूत्र साहित्य </h3>\r\n    <p>वैदिक साहित्य के विशाल एवं जटिल होने पर कर्मकाण्ड से सम्बद्ध सिद्धान्तों को एक नवीन रूप दिया गया। कम-से-कम शब्दों में अधिक-से-अधिक अर्थ-प्रतिपादन करने वाले छोटे-छोटे वाक्यों में सब महत्त्वपूर्ण विधि-विधान प्रकट किये जाने लगे। इन सारगर्भित वाक्यों को सूत्र कहा जाता था। कर्मकाण्ड-सम्बन्धी <strong>सूत्र-साहित्य को चार भागों में बाँटा गया- श्रौत सूत्र, गृह्य सूत्र, धर्म सूत्र और शुल्ब सूत्र।</strong></p>\r\n    <h3 class=\"atech\">वेदांग</h3>\r\n    <p>काफी समय बीतने के बाद वैदिक साहित्य जटिल एवं कठिन प्रतीत होने लगा। उस समय वेद के अर्थ तथा विषयों का स्पष्टीकरण करने के लिए अनेक सूत्र-ग्रन्थ लिखे जाने लगे। इसलिए इन्हें वेदाङ्ग कहा गया। <strong>वेदाङ्ग छः हैं- शिक्षा, छन्द, व्याकरण, निरुक्त, कल्प और ज्योतिष।</strong></p>\r\n    <p>पहले चार वेदांग, मन्त्रों के शुद्ध उच्चारण और अर्थ समझने के लिए तथा अन्तिम दो वेदांग धार्मिक कर्मकाण्ड और यज्ञों का समय जानने के लिए आवश्यक हैं। व्याकरण को वेद का मुख कहा जाता है, ज्योतिष को नेत्र, निरुक्त को श्रोत्र, कल्प को हाथ, शिक्षा को नासिका तथा छन्द को दोनों पैर।</p>\r\n    <h2 class=\"atech\">निष्कर्ष</h2>\r\n    <p>इस प्रकार उपरोक्त अध्ययनों से हम इस निष्कर्ष पर पहुंचते हैं कि वैदिक साहित्य का प्रारंभ साहित्यों अर्थात वेदो से प्रारंभ हुआ। इससे पश्चयत ब्राह्मण ग्रंथों की रचना हुई ब्राह्मण ग्रंथों का अंतिम भाग अरण्यक कहा गया, जिससे दार्शनिक विचारधारा का सूत्रपात हुआ। इसके पश्चात उपनिषदों का उदय अरण्यकों से हुआ। तत्पश्चात वैदिक साहित्य के जटिल स्वरूप को सरल भाषा में समझने के लिए सूत्र साहित्य का रचना हुई। वेद को और सरल तरीकों से समझने के लिए वेदांत का सृजन हुआ। इसप्रकार हम पाते हैं कि हमारी भारतीय संस्कृति के महत्वपूर्ण स्रोत वैदिक साहित्य हैं।</p>\r\n    ',13,'2024-10-23 16:19:01','2024-10-24 08:51:26','','Publish',0,'open',27,33),('पूँजीवाद की विशेषता तथा उदय के कारण','characteristics-and-reasons-for-the-rise-of-capitalism',2,'<p>वैसी अर्थव्यवस्था जिसमें उत्पादन के सभी साधनों पर निजी व्यक्तियों का अधिकार और नियंत्रण होता है। तथा सभी आर्थिक क्रियाएं निजी हित एवं लाभ के लिए किया जाता है। जिसमें सरकार का कोई हस्तक्षेप नहीं होता है उसे <strong>पूँजीवाद अर्थव्यवस्था</strong> कहते हैं </p>\r\n    <p>पूँजीवाद में तीन चीजें  शामिल होते हैं। <strong>श्रम</strong> ( वेतन के आधार पर काम करना ) <strong>साधनों का निजी स्वामित्व</strong> ( जैसे कृषि भूमि मशीनें आदि ) विनिमय तथा लाभ कमाने के लिए उत्पादन के साधनों के स्वामी जिसे <strong>बुर्जुआ</strong> या <strong>पूँजीपति</strong> कहा जाता है। बेन्हम के अनुसार- <i>\"पूँजीवादी अर्थव्यवस्था तानाशाही की प्रतिरोधी है। उत्पादन के क्षेत्र में कोई केन्द्रीय योजना नहीं होती। राज्य के द्वारा लगाए गए प्रतिबंधों को छोड़कर प्रत्योक व्यक्ति अपनी इच्छा के अनुसार कार्य करने को स्वतंत्र होता हैं।\"</i></p>\r\n    <p>डॉ भारतन कुमारप्पा ने अपनी पुस्तक <i>\"Capitalism Socialism and Villagism\"</i> में पूँजीवाद को प्रभावित करते हुए लिखा है- <span>यह एक आर्थिक व्यवस्था है जिसमें वस्तुओं का उत्पादन व वितरण व्यक्तिगत इकाई या व्यक्तिगत के समूह द्वारा किया जाता है ये व्यक्ति अपने संचित धन का प्रयोग और आर्थिक धन का संचय के लिए करते हैं।</span> इस प्रकार पूँजीवाद के लिए दो तत्व महत्वपूर्ण है निजी पूंजी एवं निजी लाभ।</p>\r\n    \r\n    <h2>पूँजीवाद की विशेषता</h2>\r\n    <h3 class=\"atech\">निजी स्वामित्व</h3>\r\n    <p>पूँजीवादी व्यवस्था में उत्पादन के साधनों अर्थात भूमि, पूंजी आदि पर निजी स्वामित्व होता है। व्यक्ति अपने इच्छा और आवश्यकता के अनुसार अपना उद्यम स्थापित कर सकता है। उसकी प्रबंधकीय व्यवस्था भी वह स्वयं करता है। वह निजी संस्थाओं या व्यवसायों को संचालित और नियंत्रित कर सकता हैं।</p>\r\n    <h3 class=\"atech\">उद्यम की स्वतंत्रता</h3>\r\n    <p>व्यक्ति अपनी इच्छा के अनुसार कोई भी उद्यम चुन सकता है। वह जब चाहे अपना उद्यम स्थापित कर सकता है। और अकेला भी कोई कार्य कर सकता है। उसे किसी तरह का कोई बंधन नहीं होता है।</p>\r\n    <h3 class=\"atech\">उपभोक्ता की पसंद</h3>\r\n    <p>पूँजीवादी व्यवस्था में उपभोक्ता की पसंद पर ध्यान रखा जाता है क्योंकि उपभोक्ता को जीस चीज़ की मांग अधिक होती है उसकी कीमतें अधिक होता है। और अगर चीजें की मांग कम होती है तो इस वस्तुओं की कीमतें गिर जाती है। जिससे काफी हानि होती है और इसी कारण उपभोक्ता के पसंद पर ध्यान रखा जाता है।</p>\r\n    <h3 class=\"atech\">प्रतिस्पर्धा</h3>\r\n    <p>प्रतिस्पर्धा भी पूँजीवादी व्यवस्था की एक महत्वपूर्ण विशेषता है क्योंकि पूँजीवादी का मुख्य उद्देश्य लाभ कमाना है। इसमें लोग अपने वस्तुओं के गुणवत्ता को विज्ञापन आदि द्वारा लोगों को बताते हैं ताकि उनकी सामान्य (वस्तु) को लोग अधिक पसंद करें।</p>\r\n    <h3 class=\"atech\">बाज़ार</h3>\r\n    <p>पूँजीवाद में बाजार की स्वतंत्रता होती है, वे अपनी वस्तुओं का कीमतें स्वय निधन करते हैं। वस्तुओं की बढ़ोतरी होने पर कभी-कभी ये मुल्क कम भी कर सकते हैं। क्योंकि इन सभी पर इनका निजी अधिकार होता हैं।</p>\r\n    \r\n    <h2>पूँजीवाद के उदय के कारण</h2>\r\n    <p>पूँजीवाद के उदय के निम्नलिखित कारण है-</p>\r\n    <h3 class=\"atech\">पुनर्जागरण</h3>\r\n    <p>पूँजीवाद के उदय में पुनर्जागरण का महत्वपूर्ण योगदान है। पुनर्जागरण ने लोगों को तर्कशील एवं भौतिकवादी बना दिया था और मानवतावाद को बल मिला। अब ये लोगों परलोक को सुखी बनाने की बजाय वर्तमान जीवन को सुखी एवं आरामदायक बनाने में रुचि लेने लगे। धन का संग्रह करना शुरू किया, लोगों में धन कमाने और अपनी जीवन को सुखी बनाने की लालसा बड़ी। जिससे व्यापार-वाणिज्य का विकास हुआ इस उन्नति एवं समृद्धि की भावना ने पूँजीवाद को प्रोत्साहित किया।</p>\r\n    <h3 class=\"atech\">धर्म सुधार आंदोलन</h3>\r\n    <p>धर्म सुधार आंदोलन आधुनिक यूरोप की प्रथम सामाजिक राजनीतिक क्रांति थी, जिसने यूरोपीय देशों की आर्थिक व्यवस्था को प्रभावित किया। कैथोलिक चर्च का मुख्य उद्देश्य मुनाफा कमाना, ब्याज पर धन उधार देना आदि था। इस आंदोलन के प्रमुख नेता मार्टिन लूथर ने लोगों को उपदेश दिया कि जो लोग धन नहीं कमाते वे ईश्वर की सेवा नहीं करते इस बात को लोगों पर गहरा प्रभाव पड़ा क्योंकि लोग इस समय आस्था में विश्वास करते थे। जिससे लोगों ने व्यापार-वाणिज्य अधिक रुचि लेना शुरू की। प्रोटेस्टेंट को मानने वाले लोग कैथोलिक चर्च के बधंनो की परवाह ना करके व्यापार एवं उद्योग को अपनाना प्रारंभ किया जिसे पूँजीवाद का विकास हुआ।</p>\r\n    <h3 class=\"atech\">राष्ट्रीय राज्यों का उत्थान</h3>\r\n    <p>मध्यकालीन सामंति व्यवस्था के कारण मध्यम वर्ग एवं व्यापारी वर्ग के सहयोग से कई शासकों ने सामंतों की शक्ति को दुर्बल करके शक्तिशाली राष्ट्रीय स्थापित करने के प्रयास किया। 16 वीं - 18 वीं सदी के बीच अनेक शक्तिशाली निरंकुश राज्य स्थापित हुए। इन शासकों ने अपने-अपने देश के व्यापार-वाणिज्य के विकास, धान दौलत में वृद्धि के लिए अनेक प्रयास किए, जिससे पूँजीवाद का विकास हुआ।</p>\r\n    <h3 class=\"atech\">भौगोलिक खोजें</h3>\r\n    <p>15 वीं तथा 16 वीं शताब्दियों में यूरोपीय देशों के नाविकों के साहसपुर्ण प्रयत्नों के फलस्वरूप अनेक नए समुद्री मार्गों एवं देशों की खोज हुई। इस समय हल्के जहाज बनने लगे तथा नाविकों को प्रशिक्षित करने के लिए स्कूल खोले गए। <strong>कम्पास के आविष्कार से समुद्री यात्रा सुरक्षित और सुगम हो गई।</strong> नई जगहो की खोज से वहाँ बस्तियां बसाई गई यानी उपनिवेश स्थापित हुआ। व्यापार-वाणिज्यिक का विकास हुआ तथा वाणिज्यवाद को प्रोत्साहन मिला। समुद्री मार्ग की खोजों ने पश्चिमी यूरोपीय देशों में व्यापारिक क्रान्ति का जन्म दिया। लोग पूँजीपति बनने लगे इससे पूँजीवाद को बल मिला।</p>\r\n    <h3 class=\"atech\">संयुक्त पूंजी कंपनियों की स्थापना</h3>\r\n    <p>15 वीं 16 वीं शताब्दियों में व्यापारी अधिक मुनाफा कमाने के लिए मिलकर व्यवसाय करने लगे। समुद्र व्यापार जोखिम भरा होता था, विशाल पूंजी का सौदा था किसी एक व्यापारी के लिए यह कठिन कार्य था। इस बीच यूरोप में संयुक्त पूंजी कंपनियों का उदय हुआ जो व्यवसायी ऐसी कंपनियों में पूंजी लगाता था उसे अपनी पूंजी के अनुरूप शेयर मिलता था।</p>\r\n    <p>विश्व में पहली संयुक्त कंपनी 15 वीं शताब्दी में जर्मन एवं इटली में स्थापित की गई थी। जिन्होंने कुछ खास क्षेत्रों में व्यापार करने का अधिकार दिया जाता था। और इस तरह की कंपनियों की वजह से पूँजीवाद के विकास को बल मिला। </p>\r\n    <h3 class=\"atech\">आधुनिक बैंकिंग प्रणाली का विकास</h3>\r\n    <p>आधुनिक बैंको ने पूँजीवाद के उदय एवं विकास में महत्वपूर्ण भूमिका निभाई। 15 वीं -16 वीं शताब्दी में अनेक बैंक स्थापित हुए। अब पूँजीपति अपना अतिरिक्त धन बैंको में सुरक्षित रखने लगे, जरूरत पड़ने पर बैंको से ब्याज पर ऋण भी ले सकते थे। इन बैंको से व्यवसायियों की जरूरते को पूरा करके पूँजीवादी व्यवस्था को मजबूती प्रदान की। </p>\r\n    <p>इसके साथ ही लोगों को अब बीमा जेसी सुविधा भी मिलने लगी। पहले लोगों को समुद्री व्यापार करते समय कई सामग्रियां या कभी-कभी जहाजों डूब जाते थे, जिससे व्यपरियों का काफी नुकसान हो जाता था। पर अब बीमा कंपनियां माल की क्षतिपूर्ति करती थी।</p>\r\n    <h3 class=\"atech\">हिसाब किताब रखने की विधि में सुधार</h3>\r\n    <p>15 वीं सदी तक यूरोप में व्यापार संबंधी हिसाब किताब रखने की विधि दोषपूर्ण थी। 15 वीं सदी के बाद ज्ञान के विकास के साथ हिसाब-किताब पर रखने की नई विधि प्रचलित हुई। अब दैनिक राजिस्टर तथा बहीखाता दोनों में ही व्यापार संबंधी आंकड़ों का विवरण विभिन्न खानों में दर्ज किया जाने लगा। इस नई विधि से व्यापार एवं वाणिज्य का हिसाब किताब रखना सरल हो गया।</p>\r\n    \r\n    <h2 class=\"atech\">निष्कर्ष</h2>\r\n    <p>इस प्रकार उपरोक्त कथनों से हम इस निष्कर्ष पर पहुँचते हैं कि समांतवादी व्यवस्था के पतन में पूँजीवाद का विकास मे पृष्ठभूमि के निर्माण किया। इसके पश्चात भौगोलिक खोजो, उपनिवेशीकरण, शहरीकरण एवं तकनीकी विकास आदि ने मिलकर इसका बढ़ावा दिया। पूँजीवाद के निर्माण में ब्रिटेन अग्रणी राहा क्योंकि इसकी भौतिक दशा एवं शासकों के संरक्षणों में वहाँ पूंजी का तेजी से विकास हुआ। पूँजीवाद में समाज दो वर्गों में विभाजित हुआ। इसके बाद वर्ग संघर्ष प्रारंभ हुआ।</p>    \r\n',12,'2024-10-23 16:19:01','2024-10-24 08:52:43','','Publish',0,'open',13,34),('इस्लामिक समाज में गुलामो की स्तिथ','status-of-slaves-in-Islamic-society',2,'<p>इस्लामिक समाज में गुलाम एक प्रमुख वर्ग माना गया है। इस्लाम समाज का निम्नतर वर्ग दासों का था। इस्लाम में दासता का अंत तो नहीं किया गया, परंतु इस व्यवस्था में कुछ सुधार अवश्य किए गए। गुलामों का व्यापार इस्लाम के उदय काल से ही होता था। यह् दास विभिन्न देशों में होने के कारण अपनी शारीरिक बनावट में भी भिन्नता रखते थे तथा इनका मूल्य भी अलग-अलग होता था।</p>\r\n    <p>इस्लाम धर्म में मुसलमानों को दास बनाने की आज्ञा नहीं दी है और यदि कोई दास इस्लाम स्वीकार कर लें तो उसे मुक्ति को आवश्यक भी नहीं दतलाया है। इसमें मालिक और दास के समागम से यदि कोई बच्चा होता था तो वह गुलामी से भी आजाद हो जाता था।</p>\r\n    <p>इस्लाम काल में दास लड़ाइयों में पराजित होने वाले पक्ष के लोग युद्धबंदी दास होते थे। इस काल में दासों को सुरक्षित करने के लिए कोई कानून नहीं था और उन्हें पूरी तरह अपने स्वामियों की मर्जी पर छोड़ दिया जाता था। इस्लाम धर्म दास प्रणाली को मान्यता तो देता था पर उसे विनियमित और सीमित कर दिया गया था। स्वामी पर दासों के स्वामित्व का अधिकार था किंतु उन्हें आदेश दिया गया कि उनके साथ दयालुता का बर्ताव करें और यदि संभव हो तो दासता से मुक्त हो अथवा धन देकर स्वयं अपनी स्वतंत्रता खरीद सकते थे।</p>\r\n    <p>कानूनी स्तर पर दांतों की स्थिति निम्न थी। दास कई प्रकार के होते थे पहले दास वैसे जो दास के यहाँ जन्म लेते थे, दूसरे जो युद्धबंदी के रूप में दास बनाए जाते थे, तीसरे दास वैसे होते थे जो कर्म के रूप में इसे अपना लेते थे और चौथे दास वैसे थे जो क्रिय गए दास होते थे। इन दासों का व्यापार साम्राज्य विस्तार के साथ-साथ बढ़ता चला गया।</p>\r\n    <p>इस्लाम के साम्राज्य विस्तार के कारण इन्हें विभिन्न देशों द्वारा प्राप्त होते थे। स्त्री बच्चे भी गुलाम बनाए जाते थे, अरब मे स्त्री की देखभाल के लिए हिजड़े दास नियुक्त किए जाते थे जिन्हें \'<b>खिसमान</b>\' कहा जाता था। हिजड़ों का एक अलग वर्ग भी होता था जिन्हें \'<b>गिलमान</b>\' कहा जाता था। वे आकर्षक व्यक्तित्व के होते थे उन पर उनके स्वामियों की विशेष कृपा होती थी। इन श्वेत एवं अश्वेत दासों को कई परियोजनाओं अथवा कार्यों में लगाया जाता था। <strong>मुख्य रूप से दास घरेलू कार्यों और सैनिक परियोजनाओं में नियुक्त किए जाते थे।</strong> स्त्री दास बड़ी संख्या में रखैल एवं घरेलू कार्यों में रखी जाती थी। सुंदर और आकर्षक स्त्री दासों को लोकप्रियता अधिक थी। सामान्यतः स्त्रियाँ नाच-गान कर अपने स्वामियों का मनोरंजन करती थी, कभी-कभी सुंदर स्त्री (दास नर्तकियाँ) अपने स्वामियों को इस सीमा में मोह लेती थी कि वह उन्हें रखैल के रूप में रख लेते थे। ऐसे रखैलो को \'<b>जवारी</b>\' कहा जाता था। कुछ सुंदर जवारी स्त्रियों ने खलीफ़ा को भी अपनी ओर आकर्षित किया।</p>\r\n    <p>कुछ जवारी ने विदुसी के रूप में भी प्रसिद्धि पाई। साधारण दासियाँ गृहकार्य में पारंगत होती थी। अत: लोग: इस उद्देश्य से उन्हें अपने घरों में सेविका के रूप में रखते थे। अरब समाज में दास-दासियों को रखना संपन्नता का प्रतीक माना जाता था। उन दिनों ये प्रथा सी चल पड़ी थी कि प्रांत के गवर्नर तथा सेनापति अपने खलीफ़ा तथा वजीर को अपने उपहारों के साथ कुवारियों को प्रदान करते थे।</p>\r\n    <p>यद्यपि अरब समाज में गुलामों की संख्या काफी अधिक थी, किंतु उनकी स्थिति अपेक्षाकृत संतोषजनक थी। सामान्यत: उनका जीवन सुखी था और उनके साथ अच्छा बर्ताव किया जाता था। उनके जीवन का सबसे बड़ा अभिशाप उनके पैरों में पड़ी गुलामी की ज़ंजीर थी, अन्यथा उन्हें बहुत सारी सुविधाएँ प्राप्त थी। गुलामो को मुक्त करना एक पुण्य कार्य माना जाता था।</p>\r\n    <p>लोगों का ऐसा विश्वास था कि गुलामों को मुक्त कर देने से उन्हें स्वर्ग की प्राप्ति होगी। अतः बड़ी संख्या में लोग गुलामों को मुक्त भी कर देते थे। इस्लाम के इतिहास में इस प्रकार के अनेक उदाहरण मिले हैं, जब अपनी योग्यता से गुलामों ने अपने स्वामी को प्रसन्न कर लिया तथा स्वतंत्र हो गए। लोग स्वतंत्र गुलामों के साथ शादी ब्याह भी करते थे, भारत में तो कुतुबुद्दीन के द्वारा गुलाम राजवंश की स्थापना की गई।</p>\r\n    <p>कुरान की शिक्षाओं और हदीस में दिए गए हजरत मोहम्मद के आदेशों के अनुसार दासो के प्रति दया का व्यवहार होना चाहिए। मुस्लिम देशों में दासों के साथ अच्छा बर्ताव किया जाता था। हजरत मोहम्मद ने अपनी शिक्षाओं में दासों के प्रति दया का बर्ताव का आदेश दिया है। हजरत मोहम्मद ने कहा है कि- <i>\"अपने दासों को वही भोजन दो जो तुम स्वयं खाते हो, और वैसे ही काम करने का आदेश दो जिसे करने की शक्ति उनमें हो।\"</i></p>\r\n    <p>इन आदेशों का सामान्यत: पूरी तरह या फिर कुछ हद तक पालन होना आवश्यक था। दासों को कोई नागरिक स्वतंत्रता प्राप्त नहीं थी, स्वामी का दासों पर पूरा अधिकार रहता था। दासों का अपनी कोई संपत्ति नहीं होती थी और वह कोई भी संपत्ति बिना मालिक की अनुमति के नहीं रख सकता था।</p>\r\n    <p>इस्लामी कानून के अनुरूप एक गुलाम स्त्री एक गुलाम पुरुष अथवा पति को छोड़कर अन्य पुरुष के साहयता से बच्चा पैदा करती थी तो उसका बच्चा गुलाम हो जाता था। किंतु अगर एक गुलाम पुरुष के सहयोग से कोई स्वतंत्र स्त्री से बच्चा होता तो वह गुलाम नहीं माना जाता था।</p>\r\n    <p>स्वामी अपने दास को किसी को भी दे सकता था अथवा किसी के हाथ बेच सकता था। स्वामी दास या दासी का विवाह भी अपनी इच्छानुसार कर सकता था। इस्लाम विधिवेत्ताओं के अनुसार दास एक ही साथ दो पत्नी नहीं रख सकते थे। अपने स्वामी की मृत्यु के पश्चात दास उसके उत्तराधिकारी की संपत्ति बन जाते थे।</p>\r\n    <p>चुंकी दास को स्वतंत्र व्यक्ति से कम अधिकार प्राप्त थे, इसलिए उनके द्वारा अपराध किए जाने पर स्वतंत्र व्यक्ति की तुलना में आधा दंड ही दिए जाते थे। यदि दास को अपराध के लिए जुर्माना या अधिक दंड देना आवश्यक होता था तो उसका भुगतान स्वामी ही करता था।</p>\r\n    <p>एक प्रसिद्ध इस्लामी पुस्तक \'अखलाक-इज-जिलाली\' जो मुस्लिमों के बीच व्यावहारिक दर्शन किए एक लोकप्रिय प्रबंध है उसमें कहा गया है कि- <i>\"एक स्वतंत्र व्यक्ति के मुकाबले दासों से सेवा लेना अच्छा है दास को अपने स्वामी की आदतों और कार्यों के साथ सामंजस्य के लिए हमेशा तैयार रहना चाहिए। उनकी आज्ञा माननी चाहिए और अपने को उनकी इच्छाओं के अनुरूप ढालना चाहिए।\"</i></p>\r\n    <p>गुलाम विभिन्न विजित देशों के होने के कारण उनकी शारीरिक बनावट और रंग रूप में काफी भिन्नता थी। उदाहरणस्वरूप मध्य अफ्रीका के गुलाम काले, फरगना तथा चीनी तुर्किस्तान के पीले और निकटपूर्व तथा दक्षिण पूर्वी यूरोपीय देशों के गुलाम गोरे होते थे। गुलामों की कीमतें उनकी शारीरिक बनावट, लिंग, रंगरूप आदि के आधार पर भिन्न-भिन्न होती थी।</p>\r\n    <p>गुलामों के विषय पर कुछ आधुनिक मुस्लिम लेखक कहते हैं कि हजरत मोहम्मद ने दास प्रथा को अस्थायी रूप से स्वीकार किया वे लोग कहते हैं कि मुस्लिम विचारों की प्रगति या परिस्थितियों में बदलाव से दास प्रथा का उन्मूलन निश्चित है। लेकिन वास्तविकता यह है कि इस्लाम में दाश प्रथा उनके विवाह, बिक्री और उत्तराधिकार संबंधी कानूनों के साथ घनिष्ठ रूप से संबद्ध है। उनके उन्मूलन से मुस्लिम धर्म की नींव पर कुठाराघात होगा।</p>\r\n    <p><strong>निष्कर्ष</strong>: इस प्रकार उपरोक्त तथ्यों के विश्लेषण से हम इस निष्कर्ष पर पहुँचते हैं कि दास प्रथा इस्लाम की भावना के साथ पूरा सामंजस्य रखता है। इसमें कोई संदेह नहीं है की अरबों में गैर-इस्लाम कानून के अधीन दासों की जो स्थिति थी उसमें हजरत मोहम्मद साहब ने सुधार किए। परंतु इसके साथ ही यह भी निश्चित है कि अरब विधि विशेषज्ञों ने दास प्रथा को स्थायी संस्था का रूप देने की कोशिश की।</p>    ',10,'2024-10-23 16:19:01','2024-10-24 08:57:30','','Publish',0,'open',5,35),('धर्म सुधार आंदोलन','about-of-religious-reform-movement',2,'<p>15वीं शताब्दी के पूर्व प्राचीन धर्म में व्याप्त बुराइयों एवं कर्मकांडों के प्रति था। दरअसल चर्च ने जनमानस को विभिन्न प्रकार के क्रमकांडों से जकड़ रखा था जिसे बाद में कुछ बुद्धिजीवों द्वारा प्रकाश में लाकर उसे समाप्त किया गया इसी को हम <strong>\"धर्म सुधार आंदोलन\"</strong> के नाम से जानते हैं</p>\r\n<p>इस आंदोलन का मुख्य उद्देश्य धार्मिक अनुष्ठान रीति-रिवाज और सामाजिक न्याय से होता है इसके अंतर्गत लोग अक्सर असामाजिक या अनैतिक मान्यताओं के खिलाफ और तथ्यों के द्वारा समाज को बताने का प्रयास करते हैं। धर्म सुधार आंदोलन का शुरुआत 1517 में जर्मनी में रहने वाले \"मार्टिंग लूथर\" के नेतृत्व में हुई थी <b>इस आंदोलन का मुख्य उद्देश्य  ईसाई लोगों के नैतिक एवं आध्यात्मिक जीवन को पुन: समुनत करना तथा रोम के पोप के व्यापक धर्म संबंधित अधिकारों को नष्ट करना था।</b ></p>\r\n<h2>धर्म सुधार आंदोलन के कारण</h2>\r\n<p>यूरोप में धर्म सुधार आंदोलन के मुख्य निम्नलिखित कारण थे -</p>\r\n<h3 class=\"atech\">पुनर्जागरण</h3>\r\n<p>पुनर्जागरण से पूर्व यूरोप पर कैथोलिक चर्च का एकमात्र साम्राज्य कायम था व्यक्ति जान्म से लेकर मरण तक चर्च से नियंत्रित रहता था चर्च का संगठन मजबूत होने से चर्च का विरोध मुश्किल था चर्च का प्रभाव इतना अधिक था कि चर्च भी जन लोगों से कर (Text) वसूल करते थे।  इतना ही नहीं सम्राटों को भी पोप के सामने झुकना पड़ता था सारा साम्राज्य या समाज धर्म केंद्रित, धर्म प्रेरित और धर्म नियंत्रित था।</p>\r\n<p>16वीं शताब्दी आते-आते यह अधिकार बिखरने लगा क्योंकि पुनर्जागरण ने जो चेतना पैदा की, जिसने चर्च की मान्यता धुमिल होने लगी लोग अब तर्कवादी हो गए। अब वे <strong> अपर्याप्त प्रमाण के अभाव में किसी सिद्धांत अथवा बात को स्वीकार करने के लिए तैयार न थे \"छापाखाना\" के आविष्कार ने जन लोगों को जागृत करने का महत्वपूर्ण भूमिका निभाई।</strong> धर्म निरपेक्ष के अध्ययन से ईसाई धर्म की बुराइयां दिखने लगी एवं बाइबल की सामान्य भाषा में अनुवाद होने से जनमानस ने धर्म के मूल को समझने लगे।</p>\r\n<p>बहुत से विद्वान जो इटली गए थे इन्होंने पोप के बुराइयों को देखा तथा वह पुनः यूरोप जाकर पोप एवं धर्म में व्याप्त बुराइयों को जनता के समक्ष रखा इस प्रकार पुनर्जागरण ने धर्म सुधार आंदोलन का मार्ग प्रस्तुत किया।</p>\r\n<h3 class=\"atech\">धार्मिक कारण</h3>\r\n<p>15वीं शताब्दी के अंतिम वर्षों में रोमन कैथोलिक चर्च के अंतर्गत अनेक दोष वह बुराइयों का समावेश हो गया था। वह अपनी असीमित शक्तियों व अधिकारों के अहंकार में अंधा होकर पथभ्रष्ट हो गया था। वह इसका दुरुपयोग करने लगा, कैथोलिक चर्च को <strong>पवित्र और धार्मिक चिंतन का केंद्र</strong> माना जाता था किंतु चर्च भ्रष्टाचार व दुराचार का केंद्र बन चुका था।</p>\r\n<p>पोप का अनेक विशेषाधिकार के पद की भी <strong>खरीद-बिक्री</strong> होने लगा था जिसके कारण लाखों डॉलर पोप के पास जमा हो गया था और कोई भी व्यक्ति पैसा देकर चर्च के  <strong>कानूनी प्रतिबंधों </strong>से आजाद हो जाता था इसी कारण लोगों ने इसका विरोध करना शुरू कर दिया। जहां योग्यता की वजह से पैसा यानी धन स्थान ले चुका था। इसी प्रकार चर्च एवं पोप के सभी अधिकारी भ्रष्ट हो चुके थे चर्च का समस्त वातावरण दूषित हो गया था।</p>\r\n<h3 class=\"atech\">राजनीतिक कारण</h3>\r\n<p>यद्यपि इस आंदोलन का शुरुआत धार्मिक आंदोलन के रूप में हुआ था तथापि इस आंदोलन के राजनीतिक स्वरूप को भी नकारा नहीं जा सकता। 16वीं शताब्दी के शुरुआत में कैथोलिक चर्च धार्मिक संस्थाओं के साथ-साथ राजनीतिक संस्थाओं के रूप में भी परिवर्तन हो चुका था। चर्च का अपना स्वतंत्र अस्तित्व था, जैसा कि मैं पहले ही बता चुका हूं कि चर्च के पास अपार धन आने की वजह से वह राजा को भी अपने से अधीन समझने लगे थे और शासन एवं चर्च के बीच आपस में संघर्ष भी होता रहता था।</p>\r\n<p>चर्च भी न्याय संबंधी समस्याओं का निपटारा करने लगी थी और प्रत्योक चर्च का एक राजा भी हुआ करता थे, जो बिलासपूर्ण जीवन व्यतीत करने लग गए थे और राजनीतिक शक्तियां भी अपने अधीन कर रखी थी।</p>\r\n<h3 class=\"atech\">पूंजीवादी भावना का उदय</h3>\r\n<p>पूंजीवादी भावना के फल स्वरुप कैथोलिक चर्च में भयंकर आर्थिक दोष्त उत्पन्न हो गया था। चर्च के अधिकारी चर्च में मौजूद धन को अपना व्यक्तिगत अधिकार समझने लगे थे और उन्होंने विभिन्न प्रकार के कर एवं अंधविश्वास से अधिक धन अर्जित कर लिए थे। लेकिन चर्च का सिद्धांत यह था कि चर्च के धन को जनलोगों के उपयोग के लिए इस्तेमाल किया जाना चाहिए। परंतु उन्होंने इसका विपरीत किया। जिसके फलस्वरुप लोगों ने इसका विरोध करना शुरू कर दिया और इस आंदोलन को प्रारंभ करने का निश्चय किया। धर्म सुधार आंदोलन इसी निश्चय का परिणाम है।</p>\r\n<h3 class=\"atech\">बौद्धिक जागरण</h3>\r\n<p> धर्म सुधार आंदोलन का प्रमुख पक्ष इतिहासकारों को जाता है क्योंकि इन्होंने अपने लेखन की माध्यम से चर्च तथा पोप के बुराइयों को जन-समाज के सामने लाएं। <strong>इरास्मस, थॉमस मूर, जॉन कालेट </strong>आदि ने अपनी रचनाओं के माध्यम से चर्च की कुरीतियों को प्रकाश में लाये।</p>\r\n<p>धर्म सुधार आंदोलन के प्रति बौद्धिक जागरण के योगदान की चर्चा करते हुए इतिहासकार <strong>H.A.L फिशर</strong> ने लिखा हैं। -<i>\"16वीं शताब्दी का बौद्धिक जागरण यद्यपि प्रोटेस्टेंट आंदोलन से भिन था तथापि यह धर्म सुधार आंदोलन अथवा प्रोटेस्टेंट आंदोलन के अनेक कारणों में से एक था। नवीन जागरण ने रोमन चर्च के अनुमोदित विश्वासो, अधिकारों एवं रीति-रिवाज के प्रति लोगों को परंपरागत श्रद्धा को कम कर दिया। जनता में प्राचीन अनुशासन के प्रति प्रतिक्रिया हुई चिंतन तथा प्रतिबंध समाप्त हुए। संदेह आलोचना तथा विद्रोह की हजारों पृथक छोटे-छोटे धाराएं जो पीडिया से एकत्रित हो रही थी अकस्मात मिलकर एक विरोध रूपी नदी की भांति बहने लगी। यूरोप में एक प्रगतिशील बौद्धिक जागृति का उदय हुआ जिसने परंपरागत ज्ञान तथा पुराने दोष और अंधविश्वासों का परिहास एवं निंदा करते हुए उन्होंने चुनौती दी।\"</i></p>\r\n<h3 class=\"atech\" >चर्च में फूट</h3>\r\n<p>15वीं शताब्दी में चर्च के आंतरिक विवादों ने भी चर्च के महत्व को गिरा दिया। अब एक पोप की बजाय दो पोप की नियुक्ति की जाने लगी।  एक फ्रांस द्वारा तो दूसरा इटली द्वारा इस दौरान चर्च एवं पाप की प्रतिष्ठा एवं उनके प्रति श्रद्धा कम होती चली गई। आगे चलकर और स्थिति खराब हो गई। अतः 1409 ईस्वी में संयुक्त सभा के प्रधान ने तीसरे पोप को भी नियुक्ति कर दी यह घटना पश्चिम की <strong>\"महान फुट\"</strong> के नाम से जाना जाता है।</p>\r\n<h3 class=\"atech\" >तात्कालिक कारण</h3>\r\n<p>धर्म सुधार आंदोलन के तात्कालिक कारण खुले आम लोगों में  <strong>\"क्षमापत्रों\"</strong> की बिक्री था। जब <strong>मार्टिंग लूथर</strong> ने 1511 में रोम की यात्रा पर गया तो उसने चर्च की व्यापक भ्रष्टाचार को देखा। इस समय पोप ने क्षमापत्र निकाला जिसके तहत लोग पैसों से वह अपने पापों से मुक्ति पाने के लिए क्षमापत्र खरीदते। जिससे उन्हें सभी तरह के पाप से मुक्ति हो सकते थे क्योंकि पोप ने उन्हें विश्वास दिला दिया था कि अगर वह इस क्षमापत्र को खरीदने हैं तो उन्हें नर्क में नहीं जाना पड़ेगा। अपितु उन्हें स्वर्ग प्राप्त होगा और इस क्षमापत्रों का मूल्य निर्धारण नहीं किया गया। इसका मूल्य खरीदने वाले की हैसियत पर निर्भर करती थी।</p>\r\n<p>जब इन क्षमता पत्रों की खुले आम बिक्री होने लगा तो मार्टिंग लूथर ने इस प्रथा का विरोध करने का संकल्प लिया और <strong>विटेनबर्ग चर्च की दीवारों पर 95 थीसिस चिपका दी</strong>। इन थीसिस के द्वारा उसने मुक्ति पत्र ( क्षमापत्र ) के औचिल्य की चुनौती दी और इस प्रकार उसने <strong>धर्म सुधार आंदोलन</strong> का झंडा गढ़ दिया।</p>\r\n\r\n\r\n<h2>धर्म सुधार आंदोलन के स्वरूप</h2>\r\n<p>जब पोप या चर्च ने लोगों को अपने बस में पूरी तरह जकड़ रखा था इस बीच अनेक बुद्धिजीवी लोग प्रकाश में आए क्योंकि पुनर्जागरण में एक <strong>नवीन चेतना</strong> का विकास हुआ। लोगों <strong>\"मानो तब जनो के जगह अब जानो तब मानो</strong> में विश्वास रखने लगे। इसी बीच कैथोलिक चर्च भी अपने अस्तित्व के लिए चिंता करने लगे तथा नए-नए प्रकार के व्यवस्था बनाने लगे। इसी बीच उन्होंने <strong>क्षमापत्र</strong> निकला यह फैसला उन्हें भारी पड़ा। क्योंकि सब अब तर्कपूर्ण बातों में विश्वास करने लगे थे इसी बीच कई बुद्धिजीवी लोगो ने इसका विरोध करना प्रारंभ कर दिया और अनेक समूह का निर्माण किया इसी कड़ी में <strong>मार्टिंग लूथर</strong> जैसे सुधारक प्रकाश में आए। जिन्होंने लोगो को चर्च के कुरीतियों को बताया और यहीं से धर्म सुधार आंदोलन के पृष्ठभूमि तैयार हो गया।</p>\r\n<p>इस आंदोलन के कुछ अग्रदूत <strong>जॉन वाइक्लिफ(1330-1384), जॉन हस(1369-1415 ), सेवोनारोला तथा इरेस्मस</strong> प्रमुख है।</p>\r\n<p><strong>जॉन वाइक्लिफ (1330-1384) :</strong> यह ऑक्सफोर्ड विश्वविद्यालय के प्राध्यापक थे एडवर्ड iii के समय इसने अनेक गिरजाघर के विरोध आवाज़ उठाएं और उसने धर्म में व्याप्त कृतियों को जनमानस के बीच रखा और कहा -</p>\r\n<ul>\r\n    <li><p>पोप पृथ्वी पर ईश्वर के प्रतिनिधि नहीं तथा भ्रष्ट एवं विवेकहीं पादरियों द्वारा दिए जाने वाले धार्मिक उपदेश व्यर्थ हैं।</p></li>\r\n    <li><p>प्रत्योक ईसाइयों को बाइबल के अनुसार कार्य करना चाहिए ना कि चर्च और पादरी के मुताबिक।</p></li>\r\n    <li><p>उसने मांग की की चर्च की विपुल धन संपत्ति पर राज्य को अधिकार कर लेना चाहिए।</p></li>\r\n    <li><p> वह जनसाधारण भाषा में धार्मिक ग्रंथो के अनुवाद के पक्ष में था। वह अनुवाद पर जोर दिया क्योंकि कैथोलिक चर्च की भाषा लैटिन भाषा में होता था। जिससे लोग समझ नहीं पाते थे वाइक्लिफ की प्रेरणा से ही बाइबल का अंग्रेज़ी अनुवाद हुआ। यह अनुवाद से लोगों ने चर्च के दोषपूर्ण कार्यों को समझा इसी वजह से वाइक्लिफ <strong>\"The Morning Of Reformation\"</strong> को कहा जाता है</p></li>\r\n</ul>\r\n<p>इस प्रकार हम देखते हैं जब लोगों ने पोप तथा चर्च के दुर्व्यवस्था तथा अन्यायपूर्ण व्यवस्था को समझा तो वे इसका विरोध करना शुरू कर दिया। तथा मार्टिन लूथर के सहयोग से विद्रोह शुरू कर दिए तत्यपश्चात धर्म में व्याप्त कृतियों में सुधार किया गया।</p>\r\n<h2>धर्म सुधार आंदोलन का महत्व एवं परिणाम</h2>\r\n<p>यूरोप के इतिहास में धर्म सुधार आंदोलन का बड़ा महत्व है। इसने सामाजिक राजनीतिक आर्थिक धार्मिक व सांस्कृतिक व्यवस्था में क्रांतिकारी परिवर्तन किए। यूरोप में <strong>आधुनिकीकरण</strong> को तेज देने वाले कारण में से एक था। यदि हम 1517 से 1618 के समय के अध्ययन करें तो पाते हैं की धार्मिक आंदोलन का निम्नलिखित परिणाम मिलते हैं। -</p>\r\n<ul>\r\n    <li><p>धर्म सुधार आंदोलन के फल स्वरुप <strong>पूरा यूरोप समाज दो भागों में बट गया</strong> था। उत्तरी यूरोप में लूथर ने धर्म में परिवर्तन कर उसका नाम <strong>\"प्रोटेस्टेंट\"</strong> तथा दक्षिण और पश्चिमी यूरोप में पूर्णत: कैथोलिक बना रहा अपितु प्रोटेस्टेंट तथा कैथोलिक के बीच संघर्ष चलता रहा। <strong>30 वर्षों तक प्रोटेस्टेंट को दबाने का प्रयास किया जाता रहा</strong>। वस्तुत: 1550 ईस्वी में असवर्ग में समझौता हुआ प्रस्ताव स्वीकृत किया गया लूथर के लूथारवादी धर्म और रोमन कैथोलिक धर्म को छोड़कर अन्य कोई धर्म नहीं बना सकता। अब पोप तथा चर्च जनता के समक्ष कार्य करने लगी।</p></li>\r\n    <li><p>धर्म सुधार आंदोलन से पोप तथा चर्च की शक्ति कम हो गई। अब शासको द्वारा चर्च के कब्जे हिस्सों पर कब्जा किया जाने लगे। <strong>इंग्लैंड,स्वीडन, हॉलैंड</strong> आदि देशों में राजतंत्र का उद्भव को देखा जा सकता है।</p></li>\r\n    <li><p>रोमन कैथोलिक चर्च ने वाणिज्य व्यापार की विरुद्ध थी। उन्हें लगता था कि उनकी विकास हमारी संकट का कारण बन सकता था और वह लोगों को अपने जाल में फंसाए रखते थे। परंतु जब प्रोटेस्टेंट ने कहा कि जो लोग धन प्राप्त करने का अवसर से लाभ नहीं उठाते है। वे ईश्वर की सेवा नहीं करते हैं। इस प्रकार <strong>प्रोटेस्टेंट के द्वारा कठोर श्रम पर जोड़ दिया गया</strong> और इसी मनोभाव ने <strong>वाणिज्य-व्यापार</strong> के विकास में महत्वपूर्ण भूमिका निभाई।</p></li>\r\n    <li><p>धर्म सुधार आंदोलन के बाद <strong>शिक्षा व कानून</strong> के क्षेत्र में अधिक बल दिया जाने लगा। लोग अपने बच्चों को शिक्षा देने में अधिक दिलचस्पी लेने लगे उनको लगने लगा था अगर वह पढ़ेंगे तभी वह अपना जीवन सुखद व्यतीत करेंगे। इसके साथ-साथ न्याय में भी कई तरह का सुधार किया गया अब वह धन से अपने सजावो को माफ या काम नहीं करवा सकते थे। और उन्हें सामान्य भाषा में न्याय की बातों से परिचित होने लगे। जिससे वह सभी तरह के सजावो और गुनाहों को जाने लगे। अब <strong>पीड़ित व्यक्ति को भी अपना पक्ष रखने का आज्ञा दी जाने लगी</strong>।</p></li>\r\n    <li><p>विज्ञान व तकनीकी के क्षेत्र में भी अभूपूर्ण प्रगति हुई इसका मुख्य कारण - </p>\r\n        <ol>\r\n            <li><p>प्रोटेस्टेंट धर्म मनुष्य को धार्मिक नियंत्रण से मुक्त कर स्वतंत्र रूप से विचार का अवसर प्रदान किया।</p></li>\r\n            <li><p>तर्कवाद से बौद्धिक विकास हुआ।</p></li>\r\n            <li><p>दार्शनिकों को विचारों में परिवर्तन आया और वह भविष्य के विषय में सोचने लगे।</p></li>\r\n        </ol>\r\n        <p>भौतिकी के क्षेत्र में गिल्वर्ट ने चुंबकीय गुणधर्म के विकास एवं अध्ययन से इसने विद्युत शक्ति को अविष्कार का मार्ग प्रस्तुत किया।</p>\r\n    </li>\r\n</ul>\r\n<h2 class=\"atech\">मूल्यांकन</h2>\r\n<p>धर्म सुधार आंदोलन <strong>आधुनिकरण</strong> में बहुत बड़ा योगदान दिया। वस्तुत जब वह पोप या चर्च के अधिकारी अपने भोग विलास जीवन के लिए लोगों को मूर्ख बनाकर धन अर्जित कर रहे थे। और लोगों को अपने बस में किए हुए थे। जिसके वजह से कला, व्यापार आदि का विकास धीमी गति हो गई थी। अपितु जब लोगो ने इस दुनिया से बाहर निकाला तो एक अलग अंदाज में विकास होने लगा। क्योंकि उन्होंने बाइबल और तर्कपूर्ण बातों को मनाना चालू कर दिया था। अब वह अपने आप के कामों पर विश्वास करने लगे अब उन्हें ईश्वर की बीमारी या और कोई कार्यों में रुकावट को अपनी नई सोच से प्राकृतिक समस्या समझाने लगे तथा इसकी समाधान ढूंढने लगे।</p>\r\n<p>इस प्रकार धर्म सुधार आंदोलन ने यूरोप में एक नई चेतना को जन्म दिया जिसके फल स्वरुप यूरोप ने मध्य युग से आधुनिक युग की ओर कदम बढ़ाया।</p>',9,'2024-10-23 16:19:01','2024-10-24 08:58:25','','Publish',0,'open',11,36),('स्वदेशी आन्दोलन','swadeshi-movement',2,'<p>1905 ई. का बंग-भंग आधुनिक भारतीय इतिहास की एक अत्यन्त महत्त्वपूर्ण घटना है। इसने हमारे राष्ट्रीय आन्दोलन में प्राणों का संचार किया। साम्राज्यवादी लॉर्ड कर्जन का यह सबसे काला कारनामा था। इसके द्वारा लॉर्ड कर्जन ने हिन्दू मुस्लिम फूट के बीज बोने का प्रयत्न कर राष्ट्रीय आन्दोलन को कुचलने की चेष्टा की। भारत की जनता ने उसकी इस कुचेष्टा का जमकर विरोध किया। सारे देश में बंग-भंग आन्दोलन प्रारम्भ हुआ, जिसने राष्ट्रीय आन्दोलन को एक नई दिशा प्रदान की। हिन्दू मुसलमान, शिक्षकों, छात्रों आदि सभी ने इसके विरुद्ध आन्दोलन चलाया।</p>\r\n<p>बंग-भंग आन्दोलन अंततोगत्वा बहिष्कार और स्वदेशी आन्दोलन में परिणत हो गया। बंगालियों ने अनुभव किया कि संवैधानिक आन्दोलन अर्थात् भाषण, प्रेस द्वारा प्रचार, निवेदन, प्रार्थना पत्र एवं सम्मेलन आदि बेकार हैं। ब्रिटिश सरकार का विरोध बहिष्कार और स्वदेशी आन्दोलन द्वारा किया जाना चाहिए। बहिष्कार के मूल में आर्थिक अवधारणा है। इसके दो अर्थ हैं—प्रथम, विदेशी वस्तुओं या अँगरेजी मालों का बहिष्कार कर अँगरेजों को आर्थिक नुकसान पहुँचाना। द्वितीय, स्वदेशी वस्तुओं के प्रयोग द्वारा स्वदेशी उद्योग-धन्धों को प्रोत्साहन देना।</p>\r\n<p>बहिष्कार की विचारधारा कोई नयी बात नहीं थी। पूर्व में भी अँगरेजों को सबक सिखाने के लिए मैनचेस्टर के बने हुए सूती कपड़ों के बहिष्कार की बात कही गयी थी। 1905 ई. में चीनियों ने अमेरीकी वस्तुओं का बहिष्कार किया था। सम्भवतः इससे प्रभावित होकर भारतीयों ने बहिष्कार की नीति ग्रहण की। आगे चलकर गाँधी-युग में बहिष्कार या स्वदेशी वस्तुओं का व्यवहार राष्ट्रीय आन्दोलन का एक अमोघ अस्त्र बन गया। वस्तुतः राजनीति में 19वीं शताब्दी के अंतिम भाग में ही बहिष्कार या स्वदेशी वस्तुओं का आन्दोलन शुरू हो गया था। </p>\r\n<p>इसके मूल में विदेशी वस्तुओं का बहिष्कार और स्वदेशी वस्तुओं का व्यवहार था। बहिष्कार का अर्थ न केवल मैनचेस्टर में बने हुए सूती कपड़ों का बहिष्कार, बल्कि प्रत्येक अँगरेजी वस्तु का बहिष्कार करना था। स्वदेशी का अर्थ भारतीय वस्तुओं का व्यवहार करना था। राष्ट्रीय आन्दोलन का यह एक प्रमुख आर्थिक कार्यक्रम बन गया। 1891 ई. में काँग्रेस के नागपुर अधिवेशन में पंजाब के लाला मुरलीधर ने प्रतिनिधियों पर विदेशी वस्तुओं के व्यवहार के लिए व्यंग्य किया। उन्होंने बताया कि विदेशी वस्तुओं की खपत ने भारतीय उद्योग-धन्धों को नष्ट कर दिया है। उन्होंने परतंत्र भारत की निन्दा की और भारतीय उद्योग-धन्धों के लिए संरक्षण की माँग की। इसी तरह 1893 ई. में लाहौर अधिवेशन में पं. मदन मोहन मालवीय ने बतलाया कि विदेशी कपड़े भारत को बर्बाद कर रहे हैं। 1904 ई. में बम्बई अधिवेशन में आर. पी. करदीकर ने बताया कि किस प्रकार भारत के नवजात उद्योगों को नष्ट किया जा रहा है।</p>\r\n<p>एक ओर ब्रिटिश उद्योगपतियों और ब्रिटिश शासकों तथा दूसरी ओर भारतीय उद्योगपतियों और आम भारतवासियों के बीच बढ़ते अन्तर्विरोध के कारण भारत में स्वदेशी आन्दोलन चल पड़ा। यह राष्ट्रीय आन्दोलन का एक अभिन्न अंग बन गया। नवोदित मध्यम वर्ग इस आन्दोलन का नेता बनकर सामने आया और उसने स्वदेशी वस्तुओं का व्यवहार और विदेशी वस्तुओं के बहिष्कार का नारा बुलन्द किया। स्वदेशी उद्योग-धन्धे तथा कला-कौशल को प्रोत्साहन दिया गया। नवोदित पूँजीपति वर्ग के समाचारपत्रों ने आर्थिक दुर्दशा के लिए देश की आर्थिक नीतियों को जिम्मेवार बताया। देश की आर्थिक दुर्दशा पर आँसू बहाकर स्वदेशी वस्तुओं के व्यवहार की अपील की गयी और ब्रिटिश शासकों से भारतीय उद्योग-धन्धों की रक्षा के लिए कानूनी कार्यवाही की माँग की गयी।</p>\r\n<p>19वीं शताब्दी में बंगाल के राजनारायण बसु तथा नंदगोपाल पिंग, पंजाब के रामसिंह कूका, बम्बई के वासुदेव जोशी तथा हिन्दीभाषी क्षेत्र में भारतेन्दु हरिश्चन्द्र ने अपने कार्यक्रमों के द्वारा स्वदेशी आन्दोलनों को आगे बढ़ाया।</p>\r\n<p>प्रारम्भ में तो केवल मैनचेस्टर की सूती मिलों में बने कपड़ों का बहिष्कार किया गया, किन्तु बाद में हर अँगरेजी माल के बहिष्कार की नीति अपनायी गयी। नमक, चीनी, एवं विलासमयी वस्तुओं का बहिष्कार किया गया। भारत में पाया जानेवाला सेंधा नमक, यहाँ के देहातों में बने गुड़ या चीनी तथा अन्य देशी चीजों की माँग बढ़ गयी। किन्तु देशी सूती कपड़ों की आपूर्ति माँग की तुलना में कम हो जाती थी। अतः बम्बई और अहमदाबाद की सूती मिलों में उत्पादन बढ़ा दिया गया। बम्बई के देशी उद्योगपतियों ने स्वदेशी आन्दोलन से काफी मुनाफा कमाया। बंगाल की दस्तकारी तथा कुटीर उद्योगों एवं हस्तकरघे को पुनर्जीवित किया गया।</p>\r\n<p>बंग-भंग आन्दोलन ने तो बहिष्कार और स्वदेशी आन्दोलन का रूप धारण कर लिया। अनेक समितियाँ गठित की गयीं जिसमें अधिकांश विद्यार्थी थे। कलकत्ता और पूरे बंगाल में इस तरह की समितियों का जाल बिछ गया। इनका एक ही उद्देश्य था-बहिष्कार आन्दोलन। इस आन्दोलन में सभी का सहयोग और सहानुभूति प्राप्त करने का प्रयास किया गया। न केवल जमींदार, वकील, छात्र, नौजवान, किसान एवं दुकानदार, अपितु डॉक्टर, देशी सेना, ब्राह्मण, पुरोहित, नाई, धोबी आदि सभी ने बहिष्कार एवं स्वदेशी आन्दोलन में भाग लिया</p>\r\n<p>लोगों की धार्मिक भावना भी उभारी गयी। प्रचार किया गया कि विदेशी नमक और चीनी को सूअर और गाय की हड्डी से साफ किया जाता है। बहिष्कार और स्वदेशी आन्दोलन को जारी रखने के लिए अनेक तरीके अपनाये गये। समाचारपत्र, जुलूस, लोकगीत, स्वयंसेवकों की भर्ती, विदेशी वस्तुओं का होलिका-दहन आदि अनेक साधन अपनाये गये।</p>\r\n<p>बहिष्कार आन्दोलन को सफल बनाने के लिए अन्य तरीके भी अपनाये गये। बांकुड़ा के मिठाई बनाने वालों ने घोषणा की कि यदि उनमें से कोई मिठाई बनाने के लिए विदेशी चीनी का प्रयोग करेगा, तो उसे एक सौ रुपये जुर्माना देना पड़ेगा। वीरभूम में सुरी बाजार के सभी विदेशी सिगरेट खरीदकर गलियों में जला डाले गये। ब्राह्मणों ने एक सभा करके विदेशी नमक और चीनी का प्रयोग करने वालों के यहाँ पूजापाठ नहीं करने का एलान किया। दीनाजपुर में डॉक्टर, वकील, मुख्तार आदि ने वहाँ के मारवाड़ियों के लिए काम बन्द करने की धमकी दी, यदि वे विदेशी वस्तुओं का आयात करेंगे। जलपाईगुड़ी में छात्रों ने सिगरेट, क्रिकेट के बल्लों, फुटबॉल, कपड़े एवं यहाँ तक कि कर्जन के पुतले भी जलाये । विदेशी वस्त्र बेचने वाले दुकानदारों की दुकानों पर धरना दिया जाने लगा। शांतिपूर्वक धरना देने की यह शुरूआत थी, जो कालान्तर में राजनीतिक आन्दोलन का एक महत्त्वपूर्ण अस्त्र बन गया।</p>\r\n<p>विदेशी माल के बहिष्कार एवं स्वदेशी आन्दोलन को कुचलने के लिए सरकार ने दमनकारी नीति का सहारा लिया। घरना देने के विरुद्ध पुलिस कार्रवाई की गयी। धरना देने वाले विद्यार्थियों को पुलिस द्वारा बेरहमी से पीटा गया, उन्हें कोड़े लगाये गये, अर्थदण्ड दिया गया तथा कॉलेज एवं विश्वविद्यालयों से निष्कासित किया गया। देहातों में जमींदारों को ब्रिटिश सरकार ने इस बात के लिए दबाव डाला कि वे बाजारों का नियंत्रण कर बहिष्कार आन्दोलन को असफल बनावें। मुसलमानों को भी धरना देने वालों के विरुद्ध प्रोत्साहित किया गया। इस प्रकार सरकार ने हर सम्भव प्रयास से बहिष्कार एवं स्वदेशी आन्दोलन को कुचलना चाहा।</p>\r\n<p>किन्तु ब्रिटिश सरकार की दमनात्मक कार्रवाइयों ने आन्दोलन को और भी उग्र बना दिया। उन्होंने बहिष्कार को सफल बनाने तथा उसे तीव्रतर करने के लिए चार सूत्री कार्यक्रम निश्चित किया।</p>\r\n<ul>\r\n    <li>अँगरेजी वस्त्र, चीनी, नमक आदि का त्याग।</li>\r\n    <li>अँगरेजी में भाषण देना बन्द ।</li>\r\n    <li>अवैतनिक सरकारी पदों का और परिषदों के पदों का त्याग। </li>\r\n    <li> विदेशी वस्तुओं का व्यवहार करनेवालों का सामाजिक बहिष्कार। </li>\r\n</ul>\r\n<h2>स्वदेशी आन्दोलन परिणाम</h2>\r\n<p>बहिष्कार एवं स्वदेशी आन्दोलन के निम्नलिखित परिणाम हुए-</p>\r\n<p><h3>आन्दोलन का दमन </h3><p> बहिष्कार एवं स्वदेशी आन्दोलन से ब्रिटिश सरकार को बहुत नुकसान हो रहा था। अतः इसे कुचलने के लिए सरकार ने अनेक हथकंडे अपनाये, जैसे - लाठीचार्ज, आपराधिक अभियोग, बंदी बनाना, छात्रों को कोड़ों से पीटना, उनके अभिभावकों को दंडित करना, छात्रों को शिक्षण संस्थाओं से निष्कासित करना इत्यादि </p>\r\n<p><h3>मुक्ति युद्ध </h3><p> बहिष्कार एवं स्वदेशी आन्दोलन का उद्देश्य वृहत् और व्यापक बन गया। कालान्तर में इसका उद्देश्य ब्रिटिश साम्राज्यवाद से लोहा लेना बन गया। अतः इसने व्यापक राष्ट्रीय आन्दोलन या मुक्ति युद्ध का रूप धारण कर लिया।</p>\r\n<p><h3> राष्ट्रीयता </h3><p> इस आन्दोलन के फलस्वरूप लोगों में राष्ट्रीयता की भावना जागृत हुई। उनमें राजनीतिक जागरण एवं देश-भक्ति की भावना आयो । तत्कालीन साहित्य, उपन्यास, नाटक, कहानियों एवं कविताओं में राष्ट्रीयता की पूर्ण अभिव्यक्ति हुई।</p>\r\n<p><h3>उग्रवाद </h3><p> कुछ आन्दोलनकारियों ने यह सोचना शुरू किया कि ब्रिटिश सरकार की पाश्विक शक्ति का सामना सत्याग्रह या अहिंसात्मक साधनों से सम्भव नहीं है। बल का सामना बल से होना चाहिए। अतः उग्रपंथियों ने हिंसात्मक साधनों के प्रयोग पर जोर दिया। गुप्त क्रांतिकारी संगठनों का निर्माण किया जाने लगा। भारतीय राजनीति में उग्रवाद और आतंकवादियों का आगमन हुआ।</p>\r\n<p><h3>राजद्रोह </h3><p> बंगाल के लोगों और सरकार के बीच जो मुठभेड़ हुई, उसका भारत के दूसरे भागों पर प्रभाव पड़ा। ब्रिटिश राज के उन्मूलन के लिए षड्यंत्र और कुचक्र का सहारा लिया जाना अनिवार्य हो गया। लोग राजद्रोही बन गये। छात्र भी हत्या की राजनीति में अन्तर्लिप्त हो गये।</p>\r\n<p><h3>ब्रिटिश माल के आयात में कमी </h3><p> आन्दोलन के फलस्वरूप भारत में ब्रिटिश माल की खपत बहुत कम हो गयी। बाजार की हालत बहुत खराब हो गयी। कोई भी आदमी अँगरेजी कपड़ा नहीं खरीदना चाहता था। बंग-भंग के बाद ब्रिटिश माल की खपत और भी कम हो गयी।</p>\r\n<p><h3>स्वदेशी वस्तुओं की खपत में वृद्धि </h3><p> इस आन्दोलन के फलस्वरूप नमक, गुड़ आदि की माँग अधिक होने लगी। फलतः गृह उद्योग-धन्धों को प्रोत्साहन मिला। अहमदाबाद तथा बम्बई की सूती मिलों के उद्योगपतियों ने बड़ा मुनाफा कमाया।</p>\r\n<p><h3>राष्ट्रीय शिक्षण संस्थाओं की स्थापना </h3><p> बहिष्कार एवं स्वदेशी आन्दोलन की जान छात्र एवं नवयुवक थे। अतः सरकार ने उन्हें इस आन्दोलन से अलग रखने के लिए कदम उठाया। सरकार ने शिक्षा विभाग का पूरा इस्तेमाल छात्रों को बहिष्कार एवं स्वदेशी आन्दोलन से दूर रखने के लिए किया। शिक्षण संस्थाओं को सरकारी सहायता रोकने की चेतावनी दी गयी तथा अनेक छात्र और शिक्षक शिक्षण संस्थाओं से निकाल बाहर किये गये।</p>\r\n<p>आन्दोलनकारियों ने इसका जवाब विदेशी शिक्षण संस्थाओं के बहिष्कार एवं स्वदेशी या राष्ट्रीय शिक्षण संस्थाओं की स्थापना से दिया। राष्ट्रीय शिक्षा परिषद् (National Council of Education) की स्थापना की बात कही गयी तथा राष्ट्रीय शिक्षा की आवश्यकता महसूस की गयी। परिणामस्वरूप बंगाल में अनेक राष्ट्रीय स्कूल एवं कॉलेज स्थापित किये गये। बंगाल के बाहर बम्बई, पूना, मछलीपट्टम, संयुक्त प्रदेश आदि में राष्ट्रीय शिक्षण संस्थाओं की स्थापना जोर-शोर से होने लगी। 1906 में कलकत्ता में काँग्रेस अधिवेशन में राष्ट्रीय शिक्षण संस्थाओं की स्थापना सम्बन्धी एक प्रस्ताव पेश करते हुए हिरेन्द्रनाथ दत्त ने कहा था, \"मैं सोचता हूँ कि स्वदेशी एक त्रिमुखाकृति देवी है। इसका एक मुख राजनीतिक, दूसरा आर्थिक एवं तीसरा शैक्षिक है।\"</p>\r\n<p><h3>स्वदेशी आन्दोलन देशव्यापी हो गया </h3><p> बंगाल से प्रारम्भ होकर स्वदेशी -आन्दोलन देश के एक बड़े हिस्से में फैल गया। संयुक्त प्रदेश, मध्यप्रदेश, बम्बई महाप्रान्त पंजाब एवं मद्रास प्रान्त के सभी बड़े शहरों में फैल गया। इसने आखिल भारतीय आन्दोलन का रूप धारण कर लिया और इसकी गूँज चारों दिशाओं में सुनाई पड़ने लगी। \"Boycot and Swadeshi Movement assumed an all India character even towards, the end of 1905.\"</p>\r\n<p><h3>आतंक का राज </h3><p> स्वदेशी आन्दोलन को दबाने के लिए सरकार ने दमनात्मक उपायों का सहारा लिया। अँगरेजों ने बंगाल एवं असम में वस्तुतः आतंक का राज कायम कर दिया था। लोगों को स्वदेशी वस्तुओं के बेचने की मनाही तथा ब्रिटिश माल बेचने के लिए बाध्य किया गया। </p>\r\n<p><h3>काँग्रेस में फूट </h3><p> बंग-भंग से उत्पन्न परिस्थिति का एक प्रत्यक्ष परिणाम यह हुआ कि भारतीय राष्ट्रीय काँग्रेस के अन्दर उग्रवादियों और उदारवादियों के बीच मतभेद और विरोध तीव्र हो गया और 1907 ई. में कॉंग्रेस के दो टुकड़े हो गये। इन दोनों ने अलग-अलग रास्तों पर चलना प्रारम्भ किया और 9 वर्षों तक वे अलग-अलग चलते रहे</p>',3,'2024-10-23 16:19:01','2024-10-24 08:59:53','','Publish',0,'open',35,37),('द्वितीय विश्वयुद्ध में जापान की पराजय के कारण','reason-for-japan-defeat-in-second-world-war',2,'<p>दक्षिण और दक्षिण पूर्व एशिया में जापान की लगातार होने वाली जीत से ब्रिटेन और अमेरिका काफी परेशान हो चूके थे 14 अगस्त 1941 को अमेरिकी राष्ट्रपति रूजवेल्ट तथा ब्रिटेन के प्रधानमंत्री सर विंस्टन चर्चिल ने अटलांटिक चार्टर पर हस्ताक्षर किए कुछ समय से दोनों देश चीन की आर्थिक और सैनिक सहायता कर रहे थे ब्रिटेन ने अमेरिका के प्रत्येक निर्णय को समर्थन देने की घोषणा कर दी थी जापान का मुकाबला करने के लिए अमेरिका, इंग्लैंड और हॉलैंड के प्रदेश में समस्त जापानी वहाँ के प्रदेशों में इस्तेमाल की गई समस्या जापानी पूंजी को जब्त कर लिया गया है इस तरह इस कार्य से जापान की अर्थव्यवस्था पर काफी प्रभाव पड़ा इस घटना के कारण आर्थिक युद्ध भी आरंभ हो गया तथा ईस्ट इंडीज से कई महत्वपूर्ण वस्तुओं का आना जाना बंद हो गया। </p>\r\n<p>1942 के मध्य से युद्ध की दिशा में परिवर्तन होने लगा तीन से छे जून के बीच प्रशांत महासागर के मिड डे द्वीप की लड़ाई में पहली बार जापान को बड़ी हार का सामना करना पड़ा इस घटना से मीडिया और संभव हवाई द्वीपों पर अधिकार का जापानी मनसूबा खत्म हो गया </p>\r\n<p>1943 से ही प्रशांत महासागर के क्षेत्र में व्यापारी उन्हें पीछे हटना आरंभ कर दिया मित्र राष्ट्रों ने जापान के सात प्रति रक्षात्मक युद्ध के स्थान पर इसके विरुद्ध आक्रमणात्मक युद्ध की नीती अपनाने न्यूजीलैंड और ऑस्ट्रेलिया के सैनिक अड्डों से मित्र राष्ट्रों की सेनाएं लगातार जापानी संपर्क लाइन और उनकी सेनाओं पर हमला करते रहे 1943 के मध्य तक जापान युद्ध में काफी थक चुका था उसका साथी जर्मनी, यूरोप में रूसी मोर्चे से पीछे हटने लगा था तथा उत्तरी अमेरिका के युद्ध में मित्र राष्ट्रों की जीत हो चुकी थी </p>\r\n<p>11-24 अगस्त 1943 तक अमेरिका, ब्रिटेन और चीन के राष्ट्रध्यक्षों ने राष्ट्राध्यक्ष कनाडा से मिले और वहाँ यह तय किया गया कि जापान पर हमला करने के लिए चीन को अधिक से अधिक सहायता दी जाए सोवियत संघ से भी इस युद्ध में सहयोग की मांग की गई इस घटना के पश्चात 19-30 अक्टूबर को ब्रिटेन सोवियत संघ तथा अमेरिका के विदेश मंत्रियों का एक और सम्मेलन मास्को में हुआ जहाँ फासिस्ट वाद की समाप्ति और युद्ध अपराधियों के विरुद्ध न्यायिक कार्यवाही करने का निश्चय किया गया पूर्वी एशिया के युद्ध की घटनाओं को के लिए पुन काहिरा में अमेरिका, ब्रिटेन और चीन के बीच वार्ता हुई यह निश्चय किया गया है कि युद्ध तब तक जारी रखा जाए जब तक जापान बिना शर्त आत्मसमर्पण के लिए तैयार नहीं हो जाता । </p>\r\n<p>उसके पश्चात चीन का समस्त इलाका उसे वापस लौटा दिया जाएगा और कोरिया को आजाद कर दिया जाएगा इस घटना के पश्चात इन तीनों देशों के नेताओं ने तेहरान में स्टालिन से भी बातचीत की सोवियत संघ ने भी जापान के विरुद्ध युद्ध में उतरने का वचन दिया ये तय किया गया कि कोरिया को वर्ष के लिए संकेत संरक्षण में रखा जाएगा दाय रन के बंदरगाह को अंतरराष्ट्रीय व्यापार के लिए खोल दिया जाएगा और कुरील तथा सखालिन द्वीप जरू उसको दे दिया जाएगा आपसी सहयोग स्थापित करने से पूर्व ही मित्र राष्ट्र अपनी लड़ाइयों को जीतने लगे थे के मध्य में हुए बड़े संघर्ष में ऑस्ट्रेलियाई और अमेरिकी सेनाओं ने मिलकर दक्षिण पश्चिम प्रशांत महासागर के मुख्य सैनिक अड्डे को नष्ट कर दिया पश्चिम की ओर अमेरिकी बमवर्षक विमानों ने कैरोलिन इसकी जापानी अड्डे पर हमला किया और दक्षिण पूर्व एशिया के साथ जापान की रसीद और संचार व्यवस्था को नष्ट करने का प्रयास किया</p>\r\n<p>मुख्य भूमि के साथ साथ जापान के तटीय नगरों पर भी समुद्री जहाजों से गोलीबारी हो रही थी युद्ध के अंतिम महीने में अमेरिकी और ब्रिटिश विमानों ने लगभग तीन हज़ार जापानी विमानों को नष्ट कर दिया तथा सोलह जहाज डूबा दिया गया यह फिर उन्हें क्षतिग्रस्त कर दिया गया एक अगस्त तक जापानी नौसेना और वायुसेना की शक्ति नष्ट हो चुकी थी वहाँ के रेल मार्ग टूट फूट चूके थे कोयले की कमी हो गयी, तेल की समाप्त होने लगा और गैर सैनिक सामान्य का निर्माण करना बंद होगा इसके बावजूद जापानियों का साहस कम नहीं हुआ और वे अपनी समर्पण के लिए तैयार नहीं हुए 1945 के मध्य तक जापान की सैनिक शक्ति पूरी तरह से नष्ट हो, चुकी थी यूरोप में जर्मनी आत्मसमर्पण कर चुका था और जापान अकेला हो चुका था उसे कई चेतावनियां दी गई पर वह आत्मसमर्पण के लिए तैयार नहीं हुआ </p>\r\n<p>जापानी प्रतिरोध और द्वितीय युद्ध को अंतिम रूप से समाप्त करने के उद्देश्य अमेरिका ने 6 अगस्त 1945 को जापान के हिरोशिमा नगर पर पहली बार परमाणु बम का प्रयोग किया इस बमबारी से नगर और उसके आसपास के क्षेत्रों में लगभग साठ, हज़ार लोग मारे गए और दो दिन बाद दूसरा परमाणु बम नागासाकी पर गिराया गया इसमें चालीस हज़ार नागरिको की मृत्यु हो गई दोनों नगरों का पूरी तरह से विनाश हो गया इस स्थिती में जापान के समक्ष आत्मसमर्पण के सिवा कोई रास्ता नहीं रहा </p>\r\n<p>9-10 अगस्त को व्यापन के सम्राट की अध्यक्षता में युद्ध परिषद की बैठक हुई युद्धमंत्री तथा कुछ लोगों को छोड़कर अन्य सभी लोग आत्मसमर्पण करने के पक्ष में थे कतर जापान ने आत्मसमर्पण की मांग को कुछ शर्तों के साथ स्वीकार कर ली ये सरते सम्राट की शक्ति, अधिकार और प्रतिष्ठा से संबंधित थी मित्र राष्ट्रों ने इसे अस्वीकृत कर दिया चौदह अगस्त को युद्ध परिषद की दूसरी बैठक हुई युद्धमंत्री तथा दोनों सेनाध्यक्षों के विरोध के बावजूद परिषद के अन्य सदस्यों ने युद्ध बंद करने का समर्थन किया और बिना शर्त आत्मसमर्पण की बात स्वीकार कर ली सम्राट ने अपनी प्रजा को सूचित किया कि जापान में आत्मसमर्पण कर दिया है 17 अगस्त को नयी सरकार बनायी गयी, इसमें आत्मसमर्पण के कार्य को पूरा करने की जिम्मेदारी दी गई 30 अगस्त 1945 को मित्र राष्ट्रों का सर्वोच्च सेनापति जनरल मैकऑर्थर जापान पहुंचा तथा आत्मसमर्पण की अंतिम कार्रवाई टोंका में अमेरिकी युद्धपोत पर संपन्न हुई प्रकार जापान के साम्राज्यवादी जीवन का अंत होगा </p>',119,'2024-10-23 16:19:01','2024-10-24 09:01:19','','Publish',0,'open',8,38),('सन् 1942 ई. के भारत छोड़ो आन्दोलन के कारण एवं परिणामों पर प्रकाश डालें। ','reasons-and-results-of-quit-bharat-movement',2,'<p>भारतीय राष्ट्रीय आन्दोलन के इतिहास में सन् 1942 ई. के \'भारत छोड़ो आन्दोलन\' का एक महत्त्वपूर्ण स्थान है। इस आन्दोलन ने ब्रिटिश सरकार को बहुत बड़ा धक्का पहुँचाया तथा ब्रिटिश सरकार यह स्पष्ट रूप से समझ गयी कि अब उसका भारतीय भूमि पर अधिक दिनों तक टिक सकना सम्भव नहीं है। क्योंकि आजादी के बावले और दीवाने भारतीय आजादी हासिल करने हेतु हर तरह की कुर्बानी देने को तैयार है। चूँकि यह आन्दोलन 1942 ई. के अगस्त महीने में हुआ था, अतः इस आन्दोलन को \'अगस्त क्रान्ति\' की संज्ञा दी जाती है।</p>\r\n<h2>भारत छोड़ो आन्दोलन के कारण </h2>\r\n<p> प्रो. के. वर्मा के शब्दों में- \"यदि हम संसार की क्रान्तियों का अध्ययन करें तो हमें यह मालूम होता है कि वे एकाएक पैदा नहीं हो जातीं, उनके अधिकांश कारण पूर्ववर्ती होते हैं। देखने में तो ऐसा लगता है कि वातावरण शान्त है, लेकिन भीतर ही भीतर आग सुलगती रहती है और उपयुक्त अवसर पाकर वह विस्फोट की भाँति फूट कर क्रान्ति का रूप धारण कर लेती है।\" सन् 1942 ई. की क्रान्ति के संदर्भ में उपर्युक्त कथन पूर्णतः सत्य है। इस क्रान्ति के भी कई पूर्ववर्ती कारण थे।</p>\r\n<p><h3>क्रिप्स मिशन की असफलता: </h3><p>क्रिप्स मिशन की असफलता अगस्त क्रान्ति की प्रमुख तात्कालिक कारण माना जाता है। वस्तुतः, क्रिप्स को भारत इसलिए नहीं भेजा गया था कि वह भारतीय समस्यओं का समाधान करे, बल्कि उसके द्वारा ब्रिटिश सरकार मित्रराष्ट्रों की आँखों में धूल झोंकना चाहती थी। युद्ध की विभीषिका को देखकर मित्रराष्ट्रों की सरकारें ब्रिटिश सरकार पर भारतीय समस्याओं के समाधान हेतु दबाव डाल रही थीं ताकि उन्हें युद्ध में भारत का पूर्ण सहयोग मिल सके। परन्तु जिस नाटकीय ढंग से क्रिप्स भारत छोड़ कर एकाएक चला गया</p>\r\n<p>उससे अँगरेजों के नाटकीय स्वांग का पता तो चल ही गया, भारतवासी उसके व्यवहार से और भी क्षुब्ध हो उठे। देश में अँगरेजों के प्रति निराशा सर्वत्र व्याप्त हो गयी। संयोग से उस समय भारत की पूर्वी सीमा पर जापानी सेना बहुत तेजी से बढ़ रही थी। इस परिस्थिति में भारतीयों को अँगरेजों को सबक सिखाने का अच्छा मौका मिला तथा भारतवासियों ने अँगरेजों, \'भारत छोड़ो\' के नारे से अगस्त क्रान्ति का प्रारम्भ किया।</p>\r\n<p><h3>युद्ध के कारण बढ़ते कष्ट से असन्तोष : </h3><p>द्वितीय विश्वयुद्ध के समय भारतीयों के कष्ट बहुत बढ़ गये थे। चूँकि अँगरेज अपनी प्रतिष्ठा की रक्षा हेतु भारत में जापान से लोहा लेने के लिए जी-जान से तैयारी कर रहे थे, अतः, युद्ध की तैयारी के नाम पर हजारों लोगों को घर से निकाल दिया गया तथा लोगों से युद्धकोष में जबर्दस्ती चन्दा लिया जाने लगा। फलतः लोगों में काफी असन्तोष फैल गया।</p>\r\n<p><h3>जापान की बढ़ती हुई शक्ति :</h3><p>ब्रिटिश सरकार युद्ध में जापान का सफलतापूर्वक सामना नहीं कर सकी। उसे मलाया, सिंगापुर, बर्मा आदि देशों से पीछे हटना पड़ा। तत्पश्चात् युद्ध में भारत को जापान से खतरा था। भारतवासी यह समझ रहे थे कि जापान के विरुद्ध भारत की रक्षा करने में ब्रिटेन समर्थ न हो सकेगा। साथ ही भारतवासियों को यह भी विश्वास था कि जापान भारत के विरुद्ध नहीं, बल्कि ब्रिटिश साम्राज्यवाद के विरुद्ध युद्ध कर रहा है। अतः यदि भारत में ब्रिटिश साम्राज्य की समाप्ति हो जायगी, तो युद्ध का संकट टल जायगा। \'भारत छोड़ो\' आन्दोलन प्रारम्भ करने में भारतीय नेताओं को इस तथ्य से भी प्रेरणा मिली।</p>\r\n<p><h3>ब्रिटिश सरकार की घोषणा : </h3><p>देश में अँगरेजों के विरुद्ध वातावरण तो था ही; किन्तु अँगरेजों की 27 जुलाई 1942 ई. की यह घोषणा कि भारत को युद्ध का आधार बनाया जायगा और इसके लिए सभी सम्भव और आवश्यक कार्रवाई की जायगी, आग में घी साबित हुई। इससे अँगरेजों की मंशा और अधिक स्पष्ट हो गयी। कांग्रेस ऐसी परिस्थिति में भला कैसे चुप बैठ सकती थी? उसने गाँधीजी के नेतृत्व में \'भारत छोड़ो आन्दोलन\' आरम्भ करने का निश्चय किया।</p>\r\n<h2>भारत छोड़ो आन्दोलन के परिणाम </h2>\r\n<p>भारत छोड़ो आन्दोलन असफल हो गया, परन्तु इसकी असफलता का मतलब यह नहीं कि इससे किसी प्रकार का लाभ ही नहीं हुआ। इस आन्दोलन से कई प्रकार के लाभ भी हुए- इस आन्दोलन ने यह स्पष्ट कर दिया कि अब भारत को बहुत दिनों तक अपने कब्जे में रखना ब्रिटेन के लिए सम्भव नहीं है।</p>\r\n<p>सरकार को यह पता चल गया कि भारतीयों में ब्रिटिश शासन के विरुद्ध व्यापक असन्तोष है तथा भारत में ब्रिटिश शासन को कायम रखने के लिए एक बहुत बड़ी फौज की आवश्यकता है, जिसके लिए अँगरेज सरकार असमर्थ थी।</p>\r\n<p>आन्दोलन ने औपनिवेशिक स्वराज्य की माँग को पूर्णरूप से मिट्टी में गाड़ दिया तथा भारतीय स्वतंत्रता की भूमिका तैयार कर दी।</p>\r\n<p>क्रान्ति में भारतीय युवकों एवं छात्रों ने अपूर्व साहस एवं धैर्य का परिचय दिया तथा अब स्वतंत्रताप्राप्ति के लिए जेल जाना उनके लिए एक साधारण बात हो गयी। डॉ. राजेन्द्र प्रसाद के शब्दों में- “आन्दोलन के कारण लोगों में सरकार का मुकाबला करने की हिम्मत और शक्ति बढ़ गयी।”</p>\r\n<p>डॉ. ईश्वरी प्रसाद ने इस आन्दोलन की महत्ता प्रकट करते हुए कहा है- \"इस विद्रोह की आग में औपनिवेशिक स्वराज्य की सारी बात जल गयी। भारत अब पूर्ण स्वतंत्रता से कुछ कम नहीं चाहने लगा। अँगरेजों का भारत छोड़ना निश्चित हो गया। इससे ब्रिटिश साम्राज्यवाद को बहुत बड़ा धक्का लगा।”</p>\r\n<p>इसलिए पंडित नेहरू ने लिखा है- \"सन् 1942 ई. में जो कुछ हुआ, उसके लिए मुझे गर्व है।\'</p>',67,'2024-10-23 16:19:01','2024-10-24 09:02:29','','Publish',0,'open',35,39),('Help','help',0,'<style>\r\n        .index-page{\r\n          background: url(\"/media/img/header-light.png\");\r\n            background-position: center;\r\n            background-size: cover;\r\n            text-align: center;\r\n            padding: 50px 20px;\r\n            margin-top: 20px;\r\n            margin-bottom: 20px;\r\n        }\r\n        .basic-addon {\r\n            margin: 0 auto;\r\n            margin-top: 30px;\r\n            max-width: 600px;\r\n        }\r\n        .basic-addon {\r\n            margin: 0 auto;\r\n            margin-top: 30px;\r\n            max-width: 600px;\r\n        }\r\n      </style>\r\n      <div class=\"index-page\">\r\n        <h2> Hello, how can we help? </h2>\r\n        <p>or choose a category to quickly find the help you need</p>\r\n        <div class=\"basic-addon\">\r\n          <span id=\"basic-addon\"><i></i></span>\r\n          <input type=\"text\" name=\"help\" placeholder=\"Ask a question....\" aria-label=\"Search\" aria-describedby=\"basic-addon1\">\r\n        </div>\r\n      </div>\r\n<p>नमस्ते! {{sitename}} पर आपका स्वागत है। यदि आपको हमारी सेवाओं के उपयोग में किसी भी प्रकार की समस्या आ रही है, तो नीचे दिए गए सेक्शन आपकी मदद कर सकते हैं।</p>\r\n\r\n<hr/>\r\n\r\n<h2>1. अकाउंट से जुड़ी समस्याएं</h2>\r\n<ul>\r\n  <li><strong>लॉगिन नहीं हो रहा?</strong> कृपया सुनिश्चित करें कि आपने सही ईमेल और पासवर्ड डाला है।</li>\r\n  <li><strong>पासवर्ड भूल गए?</strong> लॉगिन पेज पर \"पासवर्ड भूल गए?\" लिंक पर क्लिक करें और निर्देशों का पालन करें।</li>\r\n  <li><strong>रजिस्ट्रेशन में दिक्कत?</strong> सुनिश्चित करें कि सभी आवश्यक जानकारी सही ढंग से भरी गई है।</li>\r\n</ul>\r\n\r\n<h2>2. परीक्षा (Online Exam) संबंधित सहायता</h2>\r\n<ul>\r\n  <li>परीक्षा शुरू करने से पहले सुनिश्चित करें कि आपका इंटरनेट कनेक्शन स्थिर है।</li>\r\n  <li>यदि परीक्षा के दौरान तकनीकी समस्या आती है, तो कृपया उसी समय स्क्रीनशॉट लेकर हमें भेजें।</li>\r\n  <li>परीक्षा का समय समाप्त होते ही उत्तर सबमिट हो जाएंगे, कृपया समय रहते पूरा करें।</li>\r\n</ul>\r\n\r\n<h2>3. प्रश्न/उत्तर, लेख या सामग्री अपलोड करना</h2>\r\n<ul>\r\n  <li>आप अपना कंटेंट (जैसे PDF, DOC, Images) {{sitename}} पर अपलोड कर सकते हैं।</li>\r\n  <li>हम अपलोड की गई सामग्री को समीक्षा के बाद पब्लिश करते हैं।</li>\r\n  <li>अगर किसी अपलोड में समस्या है, तो कृपया हमसे ईमेल द्वारा संपर्क करें।</li>\r\n</ul>\r\n\r\n<h2>4. तकनीकी समस्याएं</h2>\r\n<ul>\r\n  <li>साइट या ऐप लोड नहीं हो रही? एक बार ब्राउज़र का cache क्लियर करें और दोबारा प्रयास करें।</li>\r\n  <li>कोई बटन काम नहीं कर रहा? कृपया अपडेटेड ब्राउज़र या ऐप वर्जन का उपयोग करें।</li>\r\n</ul>\r\n\r\n<h2>5. संपर्क करें</h2>\r\n<p>यदि ऊपर दी गई जानकारी आपकी समस्या का समाधान नहीं करती, तो आप हमसे सीधे संपर्क कर सकते हैं:</p>\r\n<ul>\r\n  <li>ईमेल: <a href=\"\">help@{{sitename}}.com</a></li>\r\n  <li>संपर्क फ़ॉर्म: <a href=\"/help/contact\">यहाँ क्लिक करें</a></li>\r\n</ul>\r\n\r\n<p>हम आपकी सहायता के लिए हमेशा तत्पर हैं। धन्यवाद!</p>\r\n',236,'2024-10-24 16:50:19','2024-10-24 17:30:10','','Publish',0,'open',0,40),('सन् 1942 ई. के भारत छोड़ो आन्दोलन प्रारम्भ एवं असफलताओं के कारण','quit-bharat-movement-started-and-reasons-for-failures',2,'<h2>क्रांति का प्रारम्भ :</h2>\r\n<p> ब्रिटिश सरकार द्वारा प्रमुख नेताओं की गिरफ्तारी की खबर बिजली की तरह सम्पूर्ण देश में फैल गयी। सम्पूर्ण देश में जनता स्तब्ध रह गयी। अपने प्रिय नेताओं की गिरफ्तारी तथा सरकारी दमन के चलते जनता में विद्रोह की भावना और भी जाग्रत हो उठीं। जनता अधीर हो उठी तथा सम्पूर्ण देश में जन-विप्लव प्रारम्भ हो गया। यद्यपि सभी बड़े-बड़े नेता गिरफ्तार हो गये थे, फिर भी गाँधीजी के \'करो या मरो\' के सिद्धान्त ने उनका नेतृत्व किया। जगह-जगह सभाएँ हुई, हड़तालें की गयीं तथा लोगों ने सरकारी सम्पत्ति को लूटना एवं बर्बाद करना प्रारम्भ कर दिया। जगह-जगह आवागमन के साधनों को तोड़-तोड़ दिया गया। रेलवे स्टेशनों एवं पुलिस थानों को जला दिया गया। सरकारी इमारतें जला दी गयीं तथा तार के खम्भे एवं लाइनें तोड़ दी गयीं।</p>\r\n<p> अहमदाबाद, मद्रास, बड़ौदा, इन्दौर तथा नागपुर के कपड़ा मिलों में हड़तालें हुई। मद्रास और बंगाल में जनता ने सशस्त्र आक्रमण शुरू कर दिया तथा बहुत से प्रान्तों में बल का भी व्यवहार किया गया। बिहार में टाटा के लोहे के कारखाने में चौदह दिनों तक हड़ताल रही। कई स्थानों में तो ऐसा लगता था कि सरकारी शासन ही समाप्त हो गया है। भारत सरकार के गृहमंत्री द्वारा दिये गये आँकड़ों के आधार पर 1 महीने के अन्दर 250 रेलवे स्टेशन नष्ट कर दिये गये थे, 24 रेलगाड़ियाँ पटरियाँ से उतार दी गयी थीं तथा एक लाख रुपये के डाक टिकट नष्ट कर दिये गये थे। इस आन्दोलन में छात्रों का भी पर्याप्त सहयोग था ।</p>\r\n<p>परन्तु आन्दोलन की प्रगति के साथ सरकार भी आन्दोलन को कुचल देने के लिए कटिबद्ध थी। आन्दोलन को दबाने के लिये सरकार ने हर सम्भव उपायों का सहारा लिया। प्रारम्भ में आन्दोलन को रोकने के लिए सरकार ने लाठी और गोली का सहारा लिया तथा लोगों को गिरफ्तार करना शुरू किया। परन्तु जब इससे भी आन्दोलन नहीं रुका, तो सरकार ने निर्दयतापूर्वक क्रूर उपायों का सहारा लिया। निरपराध लोगों को गोलियों से छलनी किया जाने लगा तथा छात्रों पर जघन्य अत्याचार किये गये। बड़े नगरों से लेकर छोटे गाँवों तक की जनता को आतंकित करने के लिए पुलिस और फौज ने काफी लूटमार की।</p>\r\n<p> लोगों के घरों में आग लगा दी गयी तथा हवाई जहाज से मशीनगनों की गोलियाँ बरसायी गयीं। बच्चों को अपनी माताओं के सामने ही भून डाला गया। पटना में सचिवालय पर राष्ट्रीय झंडा लगाते समय ग्यारह छात्रों पर गोलियाँ चलायी गयीं, जिनमें सात की मृत्यु हो गयी। सरकारी सूचनाओं के अनुसार पुलिस और सेना को 538 बार गोलियाँ चलानी पड़ी, जिसमें 850 आदमी मारे गये और 1360 छात्र घायल हुए।</p>\r\n<p>आन्दोलन का अन्त: सरकारी दमन चक्र का प्रभाव यह हुआ कि फरवरी, 1943 के बाद आन्दोलन की गति धीमी पड़ गयी । यद्यपि इसका वाह्य प्रदर्शन धीरे-धीरे समाप्त हो गया, फिर भी जयप्रकाश नारायण, अरुणा आसफअली आदि नेताओं ने छिपकर गुप्त रूप से आन्दोलन को चालू रखा। लेकिन ये लोग भी अधिक समय तक कार्य नहीं कर सके, क्योंकि ऐसे लोगों को भी गिरफ्तार कर लिया गया। इसके बाद आन्दोलन मई 1944 ई. तक धीमी गति से चला और फिर दब गया।</p>\r\n<h2>असफलताओं के कारण</h2>\r\n<p>इस आन्दोलन को जिस उत्साह एवं जोश से चालू किया गया था, उसके अनुपात में वैसा फल नहीं मिला, क्योंकि इस आन्दोलन को सरकार ने अन्ततः दबा ही डाला। इसकी असफलता के निम्नलिखित कारण थे-</p>\r\n<ul>\r\n    <li>आन्दोलन प्रारम्भ होने के पहले ही सभी बड़े-बड़े नेताओं को गिरफ्तार कर लिया गया था। अतः आन्दोलन को योग्य नेतृत्व     प्राप्त नहीं हो सका।</li>\r\n    <li>सरकार की दमन तथा कठोर नीति एवं अमानुषिक अत्याचारों के चलते आन्दोलन पनप नहीं सका।</li>\r\n    <li>आन्दोलन के लिए जिस तैयारी की आवश्यकता होती है, वह न थी, क्योंकि आन्दोलन एकाएक चालू हो गया था।</li>\r\n    <li>आन्दोलन अहिंसात्मक ढंग से चालू हुआ था, लेकिन बाद में इसने हिंसात्मक रूप धारण कर लिया। अतः, आन्दोलन प्रगति नहीं     कर सका।</li>\r\n    <li>आन्दोलनकारियों को उन लोगों का सहयोग प्राप्त नहीं हो सका जो आन्दोलन की सफलता की कामना करते थे।</li>\r\n    <li>आन्दोलन में साम्यवादी दल ने धोखा दिया। इस दल ने सरकार से साँठ-गाँठ करके काँग्रेस-विरोधी भावना का प्रचार किया तथा     जनता को सरकार की सहायता करने की प्रेरणा दी।</li>\r\n    <li>मुस्लिम लीग का रवैया आन्दोलन के विरुद्ध था।</li>\r\n    <li>सेना, पुलिस और सरकारी कर्मचारी प्रायः सभी सरकार के वफादार बने रहे।</li>\r\n<ul>',143,'2024-10-26 17:49:51','2024-10-26 18:32:35','','Publish',0,'open',35,41),('भारतीय स्वातंत्र्य आन्दोलन पर प्रथम विश्वयुद्ध के प्रभाव का वर्णन कीजिये।','effects-of-the-first-world-war-on-the-bharat-independence-movement',2,'<p>प्रथम विश्वयुद्ध सन् 1914 ई. में आरम्भ हुआ। यह युद्ध मुख्यतः इंगलैण्ड और जर्मनी के बीच था। इस महायुद्ध के राजनीतिक\r\n    परिणाम ही महत्त्वपूर्ण हुए। प्रथम महायुद्ध की समाप्ति के बाद लोकतंत्र और राष्ट्रवाद को सत्य रूप में स्वीकार कर लिया\r\n    गया और इस प्रकार एक नये युग का सूत्रपात हुआ।</p>\r\n<p>प्रथम महायुद्ध में भारत के समस्त दलों तथा वर्गों ने अँगरेजों को पूरा समर्थन दिया। लाखों भारतीयों ने सेना में भर्ती\r\n    होकर साथी देशों की ओर से विभिन्न जगहों पर लंड़ाइयाँ लड़ीं। समस्त भारतीय जनता ने तन-मन-धन से अँगरेजों की मदद की।\r\n    महात्मा गाँधी, जो दक्षिण अफ्रीका से लौटकर भारतीय राजनीति में सक्रिय भाग लेने लगे थे, भी अँगरेजों को तन-मन-धन से\r\n    युद्ध में सहयोग देने के पक्ष में रहे। भारतीयों से सहयोग दिलाने के लिए उन्होंने पूरा प्रयत्न किया। केवल आतंकवादी तथा\r\n    क्रांतिकारी नेताओं ने ही अँगरेजों को युद्ध में भारतीयों द्वारा सहयोग का विरोध किया।</p>\r\n<h2>प्रथम महायुद्ध में भारतीयों के सहयोग देने के कारण</h2>\r\n<p> प्रथम महायुद्ध में भारतीयों द्वारा अँगरेजों को सहयोग दिये जाने के निम्नलिखित कारण थे : -</p>\r\n<ul>\r\n    <li>लॉर्ड हार्डिज की उदारवादी नीति से भारतीय काफी प्रभावित हुए। लॉर्ड हार्डिज ने भारतीयों के साथ प्रेम तथा सहानुभूति\r\n        का वर्ताव किया। दक्षिण अफ्रीका में रहनेवाले भारतीयों के प्रति होनेवाले अत्याचारों का उन्होंने विरोध किया तथा\r\n        उनके प्रति सहानुभूति दिखलायी। लॉर्ड कर्जन के बंगाल विभाजन को रद्द कर हार्डिज ने बंगाल को पुनः एक कर दिया। युद्ध\r\n        में भारतीय सेनाओं को यूरोपियन सेनाओं के समान अधिकार दिलाने पर उन्होंने जो बल दिया इन्हीं सब बातों को लेकर\r\n        भारतीयों में अँगरेजों के प्रति श्रद्धा बढ़ी।</li>\r\n    <li>युद्ध प्रारम्भ होते ही मित्र राष्ट्रों की ओर से लोकतन्त्रवाद तथा राष्ट्रवाद की रक्षा की घोषणा की गयी। ब्रिटेन के\r\n        प्रधानमंत्री ऐस्किवथ ने कहा था “भविष्य में भारत के प्रश्न को एक नये दृष्टिकोण से देखा जायगा।\" लॉयड जॉर्ज ने यह\r\n        घोषणा की थी \"सभी को अपने-अपने भाग्य के निर्णय का अधिकार दिया जायगा ।\" ब्रिटिश राजनेताओं के समय-समय पर दिये गये\r\n        वचनों पर भारतीयों ने विश्वास किया। भारतीयों ने पश्चात् अँगरेजों द्वारा स्वशासन प्रदान किये जाने की आशा की।</li>\r\n</ul>\r\n<p>अँगरेज युद्ध के समय चाहते थे कि भारत में हिन्दू मुसलमानों में एकता हो जाय, जिससे उन्हें युद्ध में पूर्णरूप से सहयोग\r\n    प्राप्त हो। सन् 1916 ई. में लखनऊ-कॉंग्रेस के अधिवेशन के समय काँग्रेस तथा मुस्लिम लीग में समझौता हो गया और दोनों ने\r\n    मिलकर एक मिलाजुला घोषणा-पत्र निकाला। दोनों सम्प्रदायों में मेल होने से अँगरेजों को समस्त भारतीयों द्वारा युद्ध में\r\n    सहयोग प्राप्त हुआ।</p>\r\n<p>भारतीयों को यह आशा थी कि युद्ध के बाद भारतीयों को स्वशासन का अधिकार प्राप्त होगा, अतः उन्होंने तन-मन-धन से संकट के\r\n    समय अँगरेज़ों की सहायता की। काँग्रेस ने कुछ समय के लिए अपना आन्दोलन भी स्थगित कर दिया। उग्रवादी नेता बाल गंगाधर तिलक\r\n    तथा एनी बेसेंट ने यूरोप के युद्ध से प्रभावित होकर तथा ऐसे समय में अच्छी सफलता की आशा में होमरूल आन्दोलन को पूरे\r\n    जोरों से चलाया।</p>\r\n<p>भारतीय राष्ट्रीय आन्दोलन पर प्रथम महायुद्ध का गहरा प्रभाव पड़ा और भारतीय अब स्वराज्य का स्वप्न देखने लगे। अँगरेजों ने\r\n    युद्ध में सहयोग के लिए भारतीयों की भूरि-भूरि प्रशंसा की, लेकिन उनकी माँगों के प्रति कोई सहानुभूति नहीं दिखलायी।\r\n    तुर्की के विरुद्ध मेसोपोटामिया के युद्ध का पूर्ण उत्तरदायित्व भारत के शासन पर था और युद्ध का संचालन बहुत अकुशलता के\r\n    साथ किया गया था। अतः अँगरेजों को बड़ी हानि हुई। इस असफलता की जाँच के लिए नियुक्त कमीशन ने इस का पूर्ण उत्तरदायित्व\r\n    भारत के अँगरेजी शासन पर रखा और भारत में उत्तरदायित्वपूर्ण शासन की स्थापना की सिफारिश की। परिणामस्वरूप तत्कालीन भारत\r\n    मंत्री को त्याग-पत्र देना पड़ा और उनके स्थान पर मॉण्टेग्यू भारत-मंत्री बनाये गये। इस रिपोर्ट के फलस्वरूप भारत की\r\n    भावनाएँ और अधिक उग्र हो गयीं।</p>\r\n<p>युद्ध के पश्चात् स्वशासन की आशा करने वाले भारत को अँगरेजों ने रॉलेट ऐक्ट जैसे काले कानून के रूप में तोहफा दिया। इस\r\n    ऐक्ट के अनुसार किसी को भी संदेह की स्थिति में गिरफ्तार किया जा सकता था। परिणामस्वरूप उस ऐक्ट का भारतीयों द्वारा डटकर\r\n    विरोध किया गया। उसके विरुद्ध जगह-जगह जुलूस निकाले गये तथा हड़तालें हुई। ऐसी ही एक हड़ताल के कारण जलियाँवाला बाग की\r\n    दुर्घटना भी हुई। इस घटना ने भारतीयों की आँखें खोल दीं और भारतीय राष्ट्रीय आन्दोलन का इतिहास ही बदल गया। जो भारतीय\r\n    अँगरेजी शासन को सहयोग देते थे, उससे विमुख हो गये। इससे असहयोग का युग प्रारम्भ हुआ। सहयोगी गाँधी अब असहयोगी बन गये\r\n    तथा असहयोग आन्दोलन द्वारा स्वराज्य की माँग की गयी।</p>\r\n<p>प्रथम विश्वयुद्ध के दौरान भारतीयों को दिये गये आश्वासन की पूर्ति हेतु मॉण्डफोर्ड सुधार योजना के आधार पर सन् 1919 ई.\r\n    का भारत सरकार अधिनियम पारित किया गया था। भारतवासियों की दृष्टि में वह योजना न केवल अपर्याप्त, असंतोषजनक एवं\r\n    अनुपयुक्त थी, बल्कि निराशाजनक भी थी। फलतः भारतीयों में काफी असंतोष फैला तथा काँग्रेस द्वारा सन् 1920 ई. में असहयोग\r\n    आन्दोलन का प्रस्ताव पारित किया गया। इस प्रकार सन् 1920 ई. का असहयोग आन्दोलन प्रथम विश्वयुद्ध का ही परिणाम था।</p>',123,'2024-10-26 17:49:51','2024-10-26 18:33:52','','Publish',0,'open',35,42),('भारतीय स्वतंत्रता आंदोलन में प्रेस की भूमिका','role-of-press-in-bharat-independence-movement',2,'<p>अंग्रेज़ी तथा भारतीय भाषाओं के पत्रों ने भारतीय राजनीतिक चेतना के प्रसार-प्रचार में उल्लेखनीय भूमिका निभाई। 1857 के विद्रोह से लेकर भारत की स्वतन्त्रता प्राप्ति तक राष्ट्रीय आन्दोलन के हर चरण में भारतीय पत्रकारिता ने राजनीतिक चेतना के विकास में उल्लेखनीय योगदान दिया था। आधुनिक भारतीय पत्रकारिता के जनक राजा राममोहन राय की सम्बाद कौमुदी तथा अक्षय कुमार दत्त की तत्व बोधिनी पत्रिका, लोकहितवादी के पत्र हितवादी में सरकार की आर्थिक नीतियों की आलोचना की गई थी।</p><p> द्वारिकानाथ टैगोर के पत्र बैंगाल हरकारा के 1843 के अंकों में भारत में भी जनता की समस्याओं का निराकरण करने के लिए 1830 की फ्रांस की जुलाई क्रान्ति का अनुकरण करने की बात कही गई थी। स्वतंत्रता आंदोलन को सफल करने में पत्रकारिता का महत्वपूर्ण योगदान रहा है। </p><p>उस समय पत्रकारिता को मिशन के तौर पर लिया जाता था और पत्रकारिता के माध्यम से निःस्वार्थ भाव से सेवा की जाती थी। भारत में पत्रकारिता की नींव रखने वाले अँगरेज ही थे। भारत में सबसे पहला समाचार पत्र जेम्स अगस्टस हिक्की ने वर्ष 1780 ई. में बंगाल गजट निकाला । अँगरेज होते हुए भी उन्होंने अपने पत्र के माध्यम से अँगरेजी शासन की आलोचना की, जिससे परेशान गवर्नर जनरल वारेन हेस्टिंग्स ने उन्हें प्रदत्त डाक सेवाएँ बंद कर दी और उनके पत्र प्रकाशन के अधिकार समाप्त कर दिए। उन्हें जेल में डाल दिया गया और जुर्माना लगाया गया। जेल में रहकर भी उन्होंने अपने कलम की पैनी धार को कम नहीं किया और वहीं से लिखते रहे। हिक्की ने अपना उद्देश्य घोषित किया था-<i>अपने मन और आत्मा की स्वतंत्रता के लिए अपने शरीर को बंधन में डालने में मुझे मजा आता है।</i><br /></p><p>हिक्की गजट द्वारा किए गए प्रयास के बाद भारत में कई समाचार पत्र आए जिनमें ब्रिटिश शासन के खिलाफ आवाजें उठने लगी थी। समाचार पत्रों की आवाज दबाने के लिए समय-समय पर प्रेस सेंसरशिप व अधिनियम लगाए गए लेकिन इसके बावजूद भी पत्रकारिता के उद्देश्य में कोई परिवर्तन नहीं आया। भारत में सर्वप्रथम वर्ष 1816 ई. में गंगाधर भट्टाचार्य ने बंगाल गजट का प्रकाशन किया। इसके बाद कई दैनिक, साप्ताहिक व मासिक पत्रों का प्रकाशन प्रारंभ हुआ जिन्होंने ब्रिटिश अत्याचारों की जमकर भर्त्सना की।</p><p>राजा राममोहन राय ने पत्रकारिता द्वारा सामाजिक पुनर्जागरण में अपना महत्त्वपूर्ण योगदान दिया। ब्रामैनिकल मैगजीन के माध्यम से उन्होंने ईसाई मिशनरियों के साम्प्रदायिक षड्यंत्र का विरोध किया तो संवाद कौमुदी द्वारा उन्होंने महिलाओं की स्थिति में सुधार करने का प्रयास किया। मीरात उल अखबार के तेजस्वी होने के कारण इसे अँग्रेज शासकों की कुदृष्टि का शिकार होना पड़ा। जेम्स बकिंघम ने वर्ष 1818 ई. में कलकत्ता कोनिकल का संपादन करते हुए अँग्रेजी शासन की कड़ी आलोचना की, जिससे घबराकर अँग्रेजों ने उन्हें देश निकाला दे दिया। इंगलैंड जाकर भी उन्होंने आरियेंटल हेराल्ड पत्र में भारतीयों पर हो रहे अत्याचारों को उजागर किया।<br /><br /></p><p>हिन्दी भाषा में प्रथम समाचार पत्र लाने का श्रेय पं. जुगल किशोर को जाता है। उन्होंने 1826 ई. में उदन्त मार्तण्ड पत्र निकाला और अँग्रेजों की दमनकारी नीतियों की आलोचना की। उन्हें अँग्रेजों ने प्रलोभन देने की भी कोशिश की लेकिन उन्होंने इसे ठुकरा दिया और आर्थिक समस्याओं से जूझते हुए भी पत्रकारिता के माध्यम से राष्ट्रवाद की मशाल को और तीव्र किया।<br /></p><p>1857 की विद्रोह की ख़बरें दबाने के लिए गैगिंग एक्ट लागू किया। उस समय स्वतंत्रता आंदोलन के नेता अजीमुल्ला खाँ ने दिल्ली से पयामे आजादी निकाला जिसने ब्रिटिश कुशासन की जमकर आलोचना की। ब्रिटिश सरकार ने इस पत्र को बंद करने का भरसक प्रयास किया और इस अखबार की प्रति किसी के पास पाए जाने पर उसे कठोर यातनाएँ दी जाती थी। इसके बाद इण्डियन घोष, द हिन्दू, पायनियर, अमृत बाजार पत्रिका, द ट्रिब्यून जैसे कई समाचार पत्र सामने आए।<br /></p><p>लोकमान्य तिलक ने पत्रकारिता के माध्यम से उग्र राष्ट्रवाद की स्थापना की। उनके समाचार पत्र मराठा और केसरी, उग्र प्रवृत्ति का जीता जागता उदाहरण हैं। गाँधीजी ने पत्रकारिता के माध्यम से पूरे समाज को एकजुट करने का कार्य किया और स्वाधीनता संग्राम की दिशा सुनिश्चित की। नवभारत, नवजीवन, हरिजन, हरिजन सेवक, हरिजन बंधु, यंग इंडिया, आदि समाचार पत्र गाँधीजी के विचारों के संवाहक थे।</p><p> गाँधीजी राजनीति के अलावा अन्य विषयों पर भी लिखते थे। उन्होंने अपनी लेखनी के माध्यम से सामाजिक कुरीतियों को भी उजागर कर उन्हें समाप्त करने पर बल दिया। गणेश शंकर विद्यार्थी ने कानपुर से प्रताप नामक पत्र निकाला जो अँग्रेजी सरकार का घोर विरोधी बन गया। अरविंद घोष ने वंदे मातरम, युगांतर, कर्मयोगी और धर्म आदि का सम्पादन किया। बाबू राव विष्णु पराड़कर ने वर्ष 1920 ई. में आज का संपादन किया जिसका उद्देश्य आजादी प्राप्त करना था।<br /></p>',8,'2024-10-26 17:49:51','2024-10-26 18:35:04','','Publish',0,'open',35,43),('सोवियत कम्युनिस्ट पार्टी का महत्व और विशेषताएँ।','importance-and-characteristics-of-soviet-communist-party',2,'<p>आधुनिक काल में शासन सत्ता के पीछे वास्तविक शक्ति राजनीतिक दल हैं। वे शासन रूपी गाड़ी को चलाने के लिए ईंधन (fuel) का कार्य करते हैं। वे समाज के राजनीतिक एवं आर्थिक पहलुओं पर इस प्रकार छा गये हैं कि उन्हें अदृश्य सरकार (Invisible Government) कहा जाता है। भारत तथा इंगलैण्ड की अपेक्षा सोवियत रूस में साम्यवादी दल का बहुत अधिक महत्त्व है। उन्हें ही देश का \"शासक\" (Governor) कहा गया है। दल ही सोवियत संघ के प्रशासन का पथप्रदर्शन एवं निर्देशन करता है। संविधान की धारा 120 में स्पष्ट रूप से कहा गया है कि- \"समाजवादी व्यवस्था को सुदृढ़ बनाने और उसे विकसित करने के लिए किये जाने वाले संघर्ष में श्रमजीवी जनता का मार्गदर्शन और श्रमजीवी जनता की सभी सार्वजनिक और राजकीय संस्थाओं का मूल केन्द्र है।</p><br /><h2>सोवियत साम्यवादी दल का महत्त्व </h2><p>साम्यवादी दल के महत्त्व को समझने के लिए उसके कार्यों पर विचार करना आवश्यक है। 1952 ई. के दल नियमों के संशोधित प्रारूप में कहा गया कि- \"वर्तमान काल में सोवियत संघ में साम्यवादी दल के मुख्य कर्तव्य है- साम्यवादी समाज का निर्माण, समाज के आजीविका तथा सांस्कृतिक स्तर को निरन्तर ऊँचा उठाना, रूसियों को अन्तर्राष्ट्रीय तथा सभी देशों के मजदूरों से भ्रातृ-सम्बन्ध स्थापना की शिक्षा देना और दुश्मन से सोवियत संघ की सुरक्षा करना।” <br>संक्षेप में सोवियत रूस के साम्यवादी दल के कार्यों का विस्तृत विवरण इस प्रकार है-<br /></p><h3>1. क्रांति का जनक एवं रक्षक </h3><p> 1917 ई. के बोल्शेविक क्रांति के पूर्व साम्यवादी दल का प्रमुख कार्य था जारशाही के विरुद्ध देश में क्रांति लाना। 1917 ई. की सफल क्रांति के पश्चात् साम्यवादी दल का प्रमुख कार्य हो गया-आन्तरिक एवं वाह्य शत्रुओं से क्रांति की रक्षा करना । देशद्रोहियों एवं विदेशी पूँजीवादी देशों के विरुद्ध रूस के साम्यवादी दल ने सजग “प्रहरी” के रूप में कार्य किया। अभी भी साम्यवादी दल का प्रमुख कार्य है-समाजवादी रूस की आन्तरिक एवं वाह्य शत्रुओं से रक्षा करना।<br /></p><h3>2. साम्यवादी दल प्रेरक, आदर्श एवं शिक्षक के रूप में </h3><p> साम्यवादी दल ने रूस को आगे बढ़ाने में तथा समाजवाद के निर्माण में जनता के समक्ष कठिन परिश्रम एवं अद्भुत त्याग का अपूर्व उदाहरण प्रस्तुत किया। इस अर्थ में वे जनता के आदर्श एवं प्रेरक हैं। इसके अतिरिक्त उन्होंने सोवियत जनता को मार्क्सवाद तथा लेनिनवाद की शिक्षा भी दी। मार्क्स के आदर्शों का प्रचार दल का प्रमुख कार्य है।<br /></p><h3>3. अग्रणी संगठन </h3><p> साम्यवादी दल ही सोवियत जनता का एकमात्र राजनीतिक संगठन है तथा अन्य संगठनों का संचालन एवं निर्देशन करता है। अर्थात् दल सभी राजकीय या सार्वजनिक संस्थाओं का मूल केन्द्र है।<br /></p><h3>4. सर्वहारा वर्ग का मार्ग-दर्शक </h3><p> रूसी साम्यवादी दल समाजवादी व्यवस्था को सुदृढ़ बनाने तथा उसे विकसित करने के लिए किये जाने वाले संघर्ष में श्रमजीवी जनता का मार्ग-दर्शक है। साम्यवादी सर्वहारा वर्ग के अधिनायकत्व की स्थापना चाहता है। <br /></p><h3>5. साम्यवाद का प्रचारक</h3><p> साम्यवादी दल का एक प्रमुख कार्य सोवियत जनता को लेनिन एवं मार्क्स के सिद्धान्तों की शिक्षा देना है। इसके लिए वह सभी उपलब्ध साधनों का प्रयोग करता है। इस उद्देश्य से संगीत, कला, साहित्य एवं विज्ञान को इस प्रकार नियमित किया जाता है कि जनता में मार्क्स के सिद्धान्तों के प्रति विश्वास हो तथा साम्यवादी प्रवृत्ति भावना का विकास हो ।<br /></p><h3>6. प्रेषण कड़ी के रूप में </h3><p>रूसी साम्यवादी दल जनता तथा नेता के बीच में एक कड़ी का कार्य करता है। दल के माध्यम से नेतागण अपने कार्यों का विवरण जनता के समक्ष प्रस्तुत करते हैं। दल सरकार की नीतियों तथा कार्यों के विषय में जनता को सूचना देता है तथा उसकी स्पष्ट व्याख्या जनता के सामने रखता है। इस उद्देश्य से दल समाचार पत्र, समाचार एजेंसियों, रेडियो, साहित्य आदि को दल अपने नियन्त्रण में रखता है। तथा इसके माध्यम से समाचारों एवं सूचनाओं का मनचाहा रूप जनता के सामने रखता है।<br /></p><h3>7. सूचना केन्द्र के रूप में</h3><p> साम्यवादी दल केवल सरकारी नीतियों एवं कार्यों की सूचना ही जनता को नहीं देता वरन् जनता की इच्छा तथा प्रतिक्रियाओं की सूचना भी सरकार और दल के नेताओं को देता है। सरकार को उसकी नीति तथा कार्यों के प्रति जनता का दृष्टिकोण एवं प्रतिक्रिया साम्यवादी दल के माध्यम से ही प्राप्त होता है।<br /></p><h3>8. अन्तर्राष्ट्रीय कार्य</h3><p> रूस के साम्यवादी दल को कुछ अन्तर्राष्ट्रीय कार्य भी पड़ते हैं। रूसी साम्यवादी दल का एक उद्देश्य दूसरे देशों से भी पूँजीवाद का विनाश एवं साम्यवाद की स्थापना है। इसलिए अन्तर्राष्ट्रीय संगठनों के माध्यम से रूसी साम्यवादी दल अन्य देशों के साम्यवादी दलों का पथ प्रदर्शन करता है तथा उन्हें नियंत्रित भी करता है।<br /></p><h3>10 वास्तविक शासक</h3><p> साम्यवादी दल के महत्ता का सबसे प्रमुख कारण यह है कि अपने स्थिति के कारण यह रूस का वास्तविक शासक बन गया है। अन्य देशों के दलों की भाँति यह सरकार का निर्माणकर्त्ता, पालनकर्त्ता तथा संचालक तो है ही, इसके अतिरिक्त शासन से वह इतना घुल-मिल गया है कि दल तथा सरकार को अलग-अलग करना मुश्किल है; </p><p>दल-शासन पर इस तरह छा गया है कि वह देश का वास्तविक शासक बन गया है। शासन के विभिन्न अंग दल की नीतियों के कार्यान्वयन के साधन मात्र हैं। सिद्धान्त रूप में सरकार कानून बनाती है, अध्यादेश जारी करती है, सेना का संगठन करती है तथा वैदेशिक नीति का संचालन आदि कार्य करती है किन्तु व्यावहारिक रूप में ये सभी कार्य दल द्वारा किये जाते हैं।</p><p> किसी भी विषय में दल का निर्णय ही अन्तिम होता है। सरकार के विभिन्न अंग केवल \"रबर स्टाम्प मात्र है। अर्थात् सरकार केवल दल के निर्णयों को लागू करती है। विधानपालिका, कार्यपालिक तथा न्यायपालिका दल के सहायक अंग हैं। वस्तुतः दल ही सरकार है और सर्वहारा अधिनायकत्व दल का (Dictatorship of the Party) है</p><p>दल का महासचिव ही देश का वास्तविक प्रधानमंत्री है और प्रधानमंत्री उसके हाथों में एक खिलौना मात्र है। इसलिए प्रायः रूस में जो व्यक्ति प्रधानमंत्री होता है वही दल का महासचिव भी होता है। जो प्रधानमंत्री दल का महासचिव नहीं हुआ उसे अन्त में पदत्याग करना पड़ा। इससे भी दल की महत्ता सिद्ध होती है।<br /></p><br /><h2>साम्यवादी दल की विशेषताएँ</h2><p>सोवियत साम्यवादी दल की निम्नलिखित प्रमुख विशेषताएँ हैं :<br /></p><h3>1. एकमात्र दल</h3><p>पूँजीवादी देशों के विपरीत सोवियत रूस में एक दल की परम्परा है। पूँजीवादी देश के विभिन्न द्रल समाज के विभिन्न वर्गों को दर्शाते हैं। किन्तु सोवियत रूस में एकमात्र वर्ग है-सर्वहारा वर्ग । अतः सोवियत रूस में सिर्फ एक दल है - साम्यवादी दल जो सर्वहारा वर्ग का प्रतिनिधित्व करता है। किसी अन्य दल या संगठन के लिए वहाँ के संविधान में कोई स्थान नहीं है।<br /></p><br /><h3>2. उद्देश्य </h3><p>रूसी साम्यवादी दल निश्चित सिद्धान्तों पर आधारित है तथा इसके निश्चित उद्देश्य भी हैं। यह दल लेनिन तथा मार्क्सवाद के सिद्धान्तों पर चलते हुए सर्वहारा वर्ग के अधिनायकत्व की स्थापना तथा उसको सुदृढ़ बनाने एवं समाजवादी व्यवस्था को स्थापित करने तथा सुदृढ़ बनाने के लिए कृतसंकल्प है।<br /><br /></p><h3>3. दलीय सर्वोच्चता का अद्भुत उदाहरण</h3><p> साम्यवादी दल अपनी स्थिति के कारण रूसी शासन में सर्वोच्च है। यह सोवियत समाज का अग्रणी एवं पथ प्रदर्शक है। देश का वास्तविक शासक है तथा प्रशासन के सभी अंगों पर इसका पूर्ण नियंत्रण है।<br /><br /></p><h3>4. मोनोलिथिक दल </h3><p>\"मोनोलिथ\" (Monolith) का अर्थ है, एक ही ठोस पत्थर का बना हुआ खम्भा। सोवियत साम्यवादी दल को \'मोनोलिथिक\' दल कहा जाता है। \'यह पूर्णतः केन्द्रित, संगठित एवं कठोरतम अनुशासित दल है।<br /><br /></p><h3>5. सीमित सदस्यता </h3><p> साम्यवादी दल एक सीमित सदस्यता वाला संगठन है। इस दल की सदस्यता प्राप्त करना एक कठिन कार्य है। इस दल के विधान के अनुसार दल के सदस्यों को कुछ निश्चित अधिकार प्रदान किये गये हैं। इसी सूची की परिधि में वे बँधे रहते हैं।<br /><br /></p><h3>6. जनतांत्रिक केन्द्रवाद </h3><p>रूसी साम्यवादी दल का गठन जनतांत्रिक केन्द्रवाद (Democratic Centralism) के सिद्धान्त के आधार पर किया गया है। इसके अनुसार प्रत्येक निम्न स्तर की दल-संस्था अपने से उच्च स्तर की दल-संस्था का निर्वाचन करती है, लेकिन प्रत्येक निम्न संगठन अपने से उच्च संगठन के अधीन होता है और उसके आदेशानुसार ही कोई कार्य करता है।<br /></p><h3>7. पूर्ण प्रतिनिधि नहीं </h3><p> सामाजिक संगठन की दृष्टि से रूसी दल को पूर्ण प्रतिनिधि नहीं कहा जा सकता है। पहले दल में श्रमिकों की संख्या ज्यादा थी। आज उनकी संख्या घट रही है और बुद्धिजीवियों की संख्या बढ़ती जा रही है। ग्रामीणों की अपेक्षा शहरी सोवियत साम्यवादी दल में अधिक संख्या में हैं। इस प्रकार सोवियत साम्यवादी दल को पूर्ण प्रतिनिधिक संस्था नहीं कहा जा सकता है।<br /></p><br /><br /><br /><br /><p>निष्कर्ष रूप में कहा जा सकता है कि रूस में साम्यवादी दल ही देश का “वास्तविक शासक\" (Real Governor) है। दल तथा सरकार में विभेद करना असम्भव है। फेनसाड (Fainsod) ने ठीक ही कहा है कि- \"दल सरकार के अन्दर एक सरकार है और सोवियत संघ में शक्ति का वास्तविक केन्द्र है।\" उसी प्रकार साम्यवादी दल \"स्पार्क प्लग\" (Spark Plug ) या शक्ति का स्रोत है। संक्षेप में सोवियत समाज के राजनीतिक, आर्थिक एवं सांस्कृतिक जीवन के प्रत्येक पहलू पर दल का एकच्छत्र आधिपत्य है। </p>',7,'2024-10-26 17:49:51','2024-10-26 18:37:40','','Publish',0,'open',0,44),('साम्राज्यवाद के उत्थान और विकास के कारण।','reasons-for-the-rise-and-growth-of-imperialism',2,'<p>ऐतिहासिक दृष्टि से \'साम्राज्यवाद\' कई अभिव्यक्तियों से संबद्ध माना जाता है- जैसे \'उपनिवेशवाद\', \'एकाधिकारवादी पूँजीवाद\', सैन्यवाद, \'फासीवाद\' और \'नव-उपनिवेशवाद\' आदि। इसके बावजूद, साम्राज्यवाद का वास्तविक अर्थ स्पष्ट नहीं होता। उपनिवेशवाद आर्थिक शोषण को इंगित करता है जबकि साम्राज्यवाद आर्थिक, राजनीतिक व सामाजिक-सांस्कृतिक शोषण से संबद्ध है।</p><p> पूँजीवाद के एक विकसित चरण के रूप में एकाधिकार द्वारा अधिकाधिक मुनाफा कमाना एकाधिकारवादी पूँजीवाद का उद्देश्य है जबकि साम्राज्यवाद पूँजीवादी एकाधिकारवाद का ऐसा कोई स्पष्ट आधार प्रायः नहीं दिखता। साम्राज्यवाद को सुदृढ़ बनाने की दिशा में सैन्यवाद एक रणं कौशल के रूप में अपनाया जाता है। अपनी राष्ट्रीय सीमाओं को पार कर लेने के बाद फासीवाद साम्राज्यवाद का रूप धारण कर लेता है तथा उसके बल पर फूलता - फलता है।<br /></p><h2>साम्राज्यवाद अर्थ</h2><p> साम्राज्यवाद का मूल तत्व एक राज्य द्वारा दूसरे राज्यों पर अपनी शक्ति का विस्तार है। आधुनिक काल में \'साम्राज्यवाद\' शब्द का प्रयोग दो अर्थों में किया जाता है: पहला, आर्थिक और दूसरा, राजनीतिक, आर्थिक साम्राज्यवाद का तात्पर्य एक देश द्वारा दूसरे देश के आर्थिक शोषण तथा स्वामित्व से है। राजनीतिक साम्राज्य से एक देश द्वारा दूसरे देश के राजनीतिक शोषण का बोध होता है।</p><p>राज्यों की यह सामान्य नीति रही है कि वे किसी न किसी रूप में अपना विस्तार करें। राज्यों का अपने प्रभाव और नियन्त्रण को इस प्रकार से फैलाना ही साम्राज्यवाद कहा जाएगा। इंसाइक्लोपीडिया ब्रिटेनिका के नवीनतम 15वें संस्करण में इनका लक्ष्य इस प्रकार किया गया है-नह राज्य की ऐसी नीति है जिसका उद्देश्य अपने राज्य की सीमाओं से बाहर रहने वाली ऐसी जनता पर अपना नियन्त्रण स्थापित करना होता है जो सामान्य रूप से ऐसे नियन्त्रण को स्वीकार करने के लिए अनिच्छुक है।<br /></p><p>साम्राज्यवाद के सिद्धांतों के बारे में दो व्यक्तियों की पुस्तकें सर्वाधिक प्रचलित हैं - • जे. ए. हाब्सन : हाब्सन का जन्म 1858 में इग्लैण्ड में हुआ था। मूलतः वे एक व्यापारी थे एवं तात्कालीन उत्पादन कला का उन्हें अच्छा ज्ञान था। वे एक अच्छे पत्रकार थे, गूढ़ अर्थ शास्त्री, पूँजीवादी, सुधारवाद और शांतिवाद के एक प्रचारक तथा साम्राज्यवाद के प्रशंसक थे।</p><p> हॉब्सन अपनी प्रसिद्ध कृतियों- \'नेशनल गिल्डस एण्ड दि स्टेट\' तथा \'साम्राज्यवाद\' के लिए विश्व प्रसिद्ध हैं। हॉब्सन ने \'साम्राज्यवाद\' में उपनिवेशवाद एवं साम्राज्यवाद की विस्तार से चर्चा की है। यह पुस्तक 1902 में लन्दन और न्यूयार्क से- प्रकाशित हुई थी। इस पुस्तक में, उपनिवेशवाद और साम्राज्यवाद की मुख्य आर्थिक और राजनैतिक विशेषताओं का बहुत अच्छा और विस्तृत वर्णन किया है।</p><p> दूसरा नाम जो साम्राज्यवाद के सिद्धांतों के लिए सर्वाधिक प्रचलित और वैज्ञानिक विश्लेषण के लिए प्रसिद्ध है वह है, रूस की 1917 की समाजवादी क्रांति के जनक ब्लादिमीर इलियच लेनिन ।</p><br /><h2>साम्राज्यवाद के उत्थान और विकास के कारण</h2><h3>आर्थिक कारण </h3><p>औद्योगिक क्रान्ति के बाद औद्योगिक उत्पादन यूरोप के बड़े राज्यों का इतना अधिक बढ़ गया था कि यूरोप के देश उसे अपने ही देश में खपा नहीं पा रहे थे। अतः ऐसे उत्पादित सामान को नये बाजारों में बेचने की जरूरत थी। इसके अतिरिक्त रबड़, टीन, कपास, वनस्पति तेल, मैंगनीज आदि कई प्रकार के कच्चे माल की भी माँग बढ़ती जा रही थी। </p><p>उद्योगप्रधान देश ऐसे उपनिवेशों पर अधिकार करना चाहते थे जहाँ सस्ते मूल्य पर पर्याप्त कच्चा माल मिल सके। खाद्यान्नों की माँग की पर्त्ति भी इन उपनिवेशों से होती थी। यातायात एवं संचार के साधनों में परिवर्तन होने से वस्तुओं को ले जाना, ले आना सरल हो गया। यूरोप के राज्यों में पूँजी की माँग कम थी। अतः उस पर ब्याज भी कम प्राप्त होता था। लेकिन उसी पूँजी को उपनिवेशों में लगाने से अधिक लाभ मिलने की संभावना थी। इसी कारण बड़े-बड़े बैंकर, व्यापारी, मिल मालिक चाहते थे कि उपनिवेश स्थापित किया जाय ताकि लाभ अधिक प्राप्त हो सके।<br /></p><h3>जनसंख्या में वृद्धि </h3><p><br /> यूरोपीय राज्यों की जनसंख्या में वृद्धि विशेष रूप से औद्योगिक क्रान्ति के बाद हुई। यह संभव नहीं था कि हर देश बढ़ी हुई जनसंख्या को रोजगार दे सके और उनके आवास की समस्या का समाधान कर सके। इस कार्य के लिए उपनिवेश उपयुक्त थे। यहाँ बढ़ती हुई जनसंख्या को बसाया जा सकता था और उन्हें रोजगार भी दिया जा सकता था। इस प्रकार आर्थिक उद्देश्यों के साथ-साथ राजनीतिक पिपासा ने साम्राज्यवाद को जन्म दिया।</p><p> 19वीं शताब्दी के उत्तरार्द्ध में कई राष्ट्रवादी राजनीतिज्ञ एवं लेखक, विचारक एवं अर्थशास्त्री आदि ने जन्म लिया जिन्होंने राष्ट्रीय गौरव को बढ़ाने के लिए आत्मनिर्भरता और राष्ट्रीय सुरक्षा के लिए औपनिवेशिक विस्तार का समर्थन किया। कई अन्वेषकों ने नये-नये मार्गों की खोज की। इससे एक-दूसरे देशों के बीच निकटता स्थापित हुई। हेनरी मार्टनर स्टेनली ने कांगो में और कार्लपिट्स ने पूर्वी अफ्रीका में कई उपयोगी वस्तुओं की जानकारी हासिल की। इनके अनुसंधानों के कारण साम्राज्य विस्तार को बल दिया।<br /></p><h3>यातायात के साधनों में सुधार </h3><p>यातायात के साधन यूरोपीय देशों की साम्राज्यवादी महत्त्वाकांक्षा को प्रदीप्त करने में निश्चय ही सहायक सिद्ध हुये। अफ्रीका और एशिया में यूरोपीय उद्योगों का माल यातायात के साधनों के कारण प्रचुर मात्रा में उपलब्ध होने लगा। रेलों के आविष्कार, मेकएडम प्रकार की सड़कें तथा भाप से चलने वाले जहाज आदि उत्पादित माल का अपेक्षित स्थान के लिये अपेक्षित समय पर निर्यात कर सकते थे। फलस्वरूप दूर-दूर के प्रदेशों पर अधिकार करना और उन पर शासन करना सरल हो गया था।<br /></p><h3>विजय की महत्त्वाकांक्षा </h3><p>उग्र राष्ट्रवाद- राष्ट्रवाद उन्नीसवीं शती के अन्त में उग्रता में बदलने लगा, अनेक राष्ट्र केवल अपने-अपने देश के स्वार्थी को महत्त्व देने लगे। प्रत्येक राष्ट्र अपने को महान और दूसरे को हीन समझने लगा। अनेक राष्ट्र शक्ति का आधार साम्राज्य विस्तार को समझने लगे। इस प्रकार शक्ति प्राप्ति और विजय प्राप्ति की लालसा के कारण ही आधुनिक साम्राज्यवाद का उदय हुआ। </p><p>इंग्लैण्ड, फ्रांस तथा जर्मनी ने सामरिक महत्त्व के अनेक प्रदेशों पर अधिकार स्थापित कर लिया। प्रथम विश्वयुद्ध के श्चात् फासिस्टवादियों के अनुसार साम्राज्यवाद का अर्थ देश का विस्तार और राष्ट्रीय ओज की अभिव्यक्ति बन गया। अनेक राजनीतिज्ञों में जैसे इंग्लैण्ड के चैम्बरलेन, रोजवरी, किचनर फ्रांस के फेरी और जर्मन सम्राट कैंसर विलियम द्वितीय ने साम्राज्यवाद को अपनी कूटनीति तथा लेखन द्वारा प्रोत्साहित किया था।<br /><br /></p><h3>साम्राज्यवादी देशों का प्रचार तंत्र </h3><p>यूरोपीय देशों का एक वर्ग साम्राज्यवाद को शोषण नहीं मानता था। उनके विचारानुसार पिछड़े हुये देशों को सभ्य बनाने के लिये ही इस व्यवस्था का उदय हुआ था परन्तु यह विचार मात्र ढोंग था। साम्राज्यवादी राष्ट्रों ने अपने साम्राज्यवादी प्रयास को न्यायोचित सिद्ध करने के लिये यह प्रचार कर रखा था कि उनका लक्ष्य पिछड़ों को सभ्य बनाना है।</p><p> साम्राज्यवाद के समर्थन में प्रस्तुत किये गये \'श्वेत लोगों के बोझ\' (The White Men\'s Burden) के विषय में यह कहा गया कि सभ्य व सुविकसित अंग्रेजों को पिछड़े हुये देशों के लोगों को प्रगतिशील, सभ्य व ज्ञानवान बनाना चाहिये। जूल्स फेरी ने कहा था कि सभ्य जातियों का परम कर्तव्य है कि वे पिछड़े हुये लोगों को सभ्य बनायें। ईसाई पादरियों के पक्ष में भी यह तर्क उपस्थित किया गया कि वे लोक सेवा से प्रेरित होकर विश्व के पिछड़े हुये प्रदेशों में जायें परन्तु यह सब दिखावा था । धर्म-प्रचारकों ने शासकों का साथ साम्राज्य विस्तार में दिया था। लन्दन की धर्म प्रचार समिति (Missionary Society) ने अफ्रीका में ब्रिटिश साम्राज्य के विस्तार के लिए निरन्तर प्रयत्न किये थे।<br /></p><h3>ईसाई धर्मप्रचारकों का योगदान :</h3><p>ईसाई धर्म का प्रचार और प्रसार के क्रम में पश्चिमी सभ्यता और संस्कृति का भी प्रचार करने के लिए साम्राज्यवाद को बढ़ावा दिया गया। इंगलैण्ड के डॉक्टर डेविड लिविंगस्टन (David Livingstone) ने लगभग 20 वर्ष तक अफ्रीका में कई क्षेत्रों को ढूँढ़ते रहे। उन्होंने दासप्रथा को समाप्त करने के लिए, ईसाई धर्म के प्रचार के लिए अफ्रीका में बहुत कुछ किया।</p><p> फ्रांस के कार्डिनल लेभीगेरी (Cardinal Lavigirie) ने अलजिरिया में और ट्यूनिस में विशेष धर्मप्रचार कार्य किया। अफ्रीका में कार्यरत मिशिनरियों की एक समिति भी उसने गठित की। उसके प्रभाव के कारण ही फ्रांस ट्यूनिस पर अधिकार कर सका।<br /></p>',54,'2024-10-26 17:49:51','2024-10-26 18:38:43','','Publish',0,'open',29,45),('प्रथम विश्वयुद्ध के कारण।','due-to-world-war-one',2,'<p>नेपोलियन के पतन के बाद से बाल्कन प्रायद्वीप में राजनीतिक सरगर्मियाँ बढ़ने लगी थीं और 20वीं सदी के शुरू होते-होते उसने इतना भीषण स्वरूप धारण कर लिया कि बाल्कन प्रायद्वीप यूरोप का ज्वालामुखी कहा जाने लगा। यूरोप के विभिन्न राज्यों की शक्ति-आजमाइश का यह क्षेत्र अखाड़ा बन गया था। इनकी महत्त्वाकांक्षाएँ अपनी स्वार्थपूर्ति के लिए टकराती रही थीं। इस बीच इन राज्यों की अनिश्चित गुटबाजी ने न केवल संदेहों को जन्म दिया अपितु विश्व को प्रथम युद्ध के कगार पर ला खड़ा किया।<br /></p><br /><h2>प्रथम विश्वयुद्ध के निम्नलिखित कारण थे -</h2><h3>1. गुप्त संधियाँ </h3><p>प्रथम विश्वयुद्ध के अन्य कारणों के अतिरिक्त उन गुप्त-सन्धियों की महत्त्वपूर्ण भूमिका रही है जो राजाओं या राज्यों के बीच हुई थीं किन्तु जिनका पता या अन्दाज राज्य की जनता अथवा अन्य वरिष्ठ कर्मचारियों को नहीं थी। 1879 ई. में जर्मनी ने ऑस्ट्रिया-हंगरी के साथ गुप्त संधि की थी जिसमें 1882 ई. में इटली भी शामिल हो गया। बिस्मार्क के पतन के पश्चात् फ्रांस-रूस आपस में चुपचाप 1894 ई. में सन्धि से मित्र बने। इंगलैण्ड ने जो अबतक अलग-थलग था</p><p> 1902 ई. में जापान, 1904 ई. में फ्रांस और 1907 ई. में रूस से संधि की। रूस के 1917 ई. की क्रान्ति के उपरान्त जारों की गुप्त संधियों का पर्दाफाश हुआ था। इन सन्धियों के कारण हर राज्य एक-दूसरे को संदेह की दृष्टि से देखता था। देश की जनता समय को ध्यान में रखकर शासन से कुछ अन्य अपेक्षाएँ रखती थीं जब कि शासन का बर्ताव अनिश्चित हुआ करता था। संधि में खुलापन न रहने के कारण यूरोपीय राज्य युद्ध के निकट खिंच आये।<br /></p><h3>2. उग्र राष्ट्रीयता </h3><p> राष्ट्रीयता या देशभक्ति जनता के स्वाभिमान को इतना अधिक उभार देती है कि वह अन्य देशवासियों की अपेक्षा अपने को श्रेष्ठ समझने लगता है। बलात् स्वयं को अन्य राज्य के नागरिकों से ऊँचा समझना उग्र राष्ट्रीयता होती है। उग्र राष्ट्रीयता के फलस्वरूप प्रायः एक देश के नागरिक दूसरे देश को नीचा दिखाने का प्रयास करने लगते हैं तथा अपने राजा या शासन पर अपरोक्ष दबाव डालते हैं कि वह उनके स्वाभिमान की रक्षा तथा दूसरे प्रभावी राज्य का मानमर्दन करे। </p><p>प्रथम विश्वयुद्ध के पूर्व जर्मनी, फ्रांस, ऑस्ट्रिया, इंगलैण्ड में ही उग्र राष्ट्रीयता के लक्षण नहीं दिखलाई पड़ते थे अपितु बाल्कन प्रायद्वीप के छोटे-छोटे राज्य यूनान, सर्विया आदि पर भी उग्र राष्ट्रीयता का नशा चढ़ चुका था। इनके अतिरिक्त पोल, स्लाव, चेक आदि जातियाँ भी घुटन की जिन्दगी जी रही थीं। इस प्रकार जब छोटे-बड़े राज्य अपनी संस्कृति, अपना धर्म, अपनी सभ्यता का पाठ दूसरे देश के नागरिकों को पढ़ाने तथा उन पर थोपने के लिए उतावले होने लगे थे तो अवरोध और युद्ध निश्चित हो गया था।<br /><br /></p><h3>3. समाचार-पत्रों का अनर्गल</h3><p> जनमत को युद्ध के कगार पर लाने में विभिन्न देशों के समाचार-पत्रों ने महत्त्वपूर्ण भूमिका निभायी। उन्होंने बेबुनियादी अनर्गल एवं उत्तेजक समाचारों द्वारा सस्ती लोकप्रियता अर्जित कर ली थी और ऐसा जनमत तैयार कर दिया था जो सरकार पर दबाव डालने लगा था कि अपने देश की प्रतिष्ठा के लिए दूसरे देशों को या दुश्मन देशों को पाठ पढ़ाना आवश्यक है।<br /></p><h3>4. उपनिवेश विस्तार </h3><p>व्यावसायिक क्रान्ति के फलस्वरूप कतिपय यूरोपीय देशों में मशीनीकरण बहुत तेजी से हुआ तथा फैक्टरी से अधिक मात्रा में माल का उत्पादन होने लगा। उत्पादित माल के बाजार की तलाश में उन देशों ने ऐसे देशों या छोटे-बड़े राज्यों या उसके हिस्सों पर आधिपत्य जमाना शुरू कर दिया जहाँ उनके माल की खपत हो सके। यूरोप का प्रायः हर देश संसार के प्रत्येक कोने में अपना बाजार स्थापित करना चाहता था। जर्मनी इंगलैण्ड इस हेतु प्रबल प्रतिद्वन्द्वी एवं दुश्मन बन गये थे। जर्मनी के सम्राट कैसर विलियम ने उपर्युक्त उद्देश्य से अपनी नौ-शक्ति एवं जहाजी बेड़ों को सशक्त एवं समृद्ध करना प्रारम्भ कर दिया। इंगलैण्ड किसी देश की नौ-शक्ति को बढ़ते नहीं देख सकता था। इंगलैण्ड एवं जर्मनी के सम्बन्ध इतने खराब हुए कि दोनों युद्ध की मानसिक स्थिति में आ गये थे।<br /></p><h3>5. सैनिकवाद </h3><p>19वीं शताब्दी के अन्त आते-आते तक यूरोप के अनेक देश युद्ध के उन्माद से विक्षिप्त दिखलायी पड़ने लगे थे। सभी इस आशंका में कि कभी भी युद्ध हो सकता था अपनी सैनिक तैयारियाँ तथा सैन्य सामग्रियाँ कड़ी मेहनत से दिन-रात जुटाने में लगे हुए थे। फ्रांस, जर्मनी जैसे प्रमुख यूरोपीय राज्य अपनी राष्ट्रीय आय का 85% सैनिक तैयारियों पर व्यय करने लगे थे। सभी देशों में सैनिक शिक्षा अनिवार्य कर दी गयी थी। 1898 ई. तथा 1907 ई. में हेग में दो बार इस उद्देश्य से सम्मेलन बुलाया गया कि संसार में युद्ध सामग्री के उत्पादन पर नियंत्रण रखा जाय किन्तु दोनों सम्मेलन निरर्थक रहे। रक्षा की ओट में सैनिक तैयारियाँ द्रुत गति से की जा रही थीं जो आसन्न विश्वयुद्ध का संकेत था ।<br /></p><h3>6. फ्रांस- जर्मनी संबंध</h3><p> प्रथम विश्वयुद्ध के गर्भ में फ्रांस का वह राष्ट्रीय अपमान भी था जब प्रशा ने उसे पराजित कर सन् 1871 ई. में उससे लॉरेन एवं अल्लास के प्रांत छीन लिये थे तथा उसे युद्ध का हर्जाना भी भरना पड़ा था। फ्रांस अपने प्रांत वापस लेना चाहता था तथा जर्मनी को पराजित करने की गोटियाँ सदा बैठाया करता था।<br /></p><p>फ्रांस-जर्मनी वैमनस्य ने विश्व को युद्ध के कगार पर ला खड़ा किया था। 7. पूर्वी समस्या : प्रथम विश्वयुद्ध का मुख्य कारण बाल्कन प्रायद्वीप की समस्या थी। तुर्की की दुर्बलता, मेसोडोनिया को लेकर यूनान, सर्विया, बुल्गेरिया में घृणाजनक फूट न केवल पश्चिमी यूरोप का ध्यान आकर्षित किये हुए था अपितु रूस भी पूर्वी समस्या की ओट में अपना सुरक्षा कवच बनाने की ताक में था। रूस ने 1908 ई. में, बोस्निया की समस्या को सुलझाने में, सर्विया का साथ दिया। वह पूर्व की ओर भी साम्राज्य विस्तार की योजना बना रहा था।<br /></p><h3>8. बोस्निया एवं हर्जेगोविना की समस्या </h3><p><br /> पूर्वी यूरोप के इन दोनों प्रान्तों का शासन प्रबंध ऑस्ट्रिया एवं हंगरी के हाथ में था किन्तु वै इनका विलय करार के अनुसार अपने राज्य में नहीं कर सकते थे किन्तु किसी की चिन्ता न कर उन दोनों ने इन प्रान्तों को अपने देश में मिला लिया। सर्विया ने विरोध किया तथा बोस्निया और हर्जेगोविना स्वतंत्र होने के लिए विद्रोह कर रहे थे। रूस परोक्ष रूप से उनकी मदद कर रहा था। इस प्रकार ऑस्ट्रिया-रूस तनाव में आ गये थे।<br /></p><h3>9. तात्कालिक कारण सराजेवो हत्याकाण्ड </h3><p>उपर्युक्त कारणों ने प्रथम विश्वयुद्ध की पृष्ठभूमि अवश्य तैयार कर रखी थी किन्तु इसमें आग लगने का काम सराजेवो हत्याकाण्ड (28 जून 1914 ई.) है जिसे इतिहासकार तात्कालिक कारण की संज्ञा देते हैं। 8 जून 1914 ई. को ऑस्ट्रिया के उत्तराधिकारी राजकुमार आर्च ड्यूक फ्रांसिस फरडिनैण्ड अपनी पत्नी के साथ बोस्निया की राजधानी सराजेवो का दौरा करने के लिए गये जहाँ एक सर्व नागरिक ने बम मारकर उसकी हत्या कर दी। यह एक विद्रोही कार्य था तथा ऑस्ट्रिया को पूरा विश्वास था कि इस हत्याकाण्ड को प्रोत्साहन सर्व सरकार ने दिया था।</p><p> इस घटना के लगभग 1 माह बाद जर्मनी को विश्वास में लेकर ऑस्ट्रिया ने सर्विया को 48 घण्टे की नोटिस दी और उसके सम्मुख 12 कठोर शर्तें भी रखीं। जिन पर इंगलैण्ड के विदेशमंत्री सर एडवर्ड ग्रे ने टिप्पणी की थी- \"मैंने आज तक किसी देश को एक दूसरे स्वतंत्र देश से ऐसी कड़ी शर्तें मनवाते हुए नहीं देखा है।” किन्तु विवश सर्विया ने 12 में से 9 शर्तें अक्षरशः मान ली तथा शेष तीन के लिए भी समय माँगा तथा आश्वासन दिया कि मान लिया जायेगा। यदि ऑस्ट्रिया सर्विया के उत्तरों से सन्तुष्ठ नहीं होता तो अन्तर्राष्ट्रीय न्यायालय हेग में महान शक्तियों का सम्मेलन बुलाकर फैसला कर लिया जाता। पर 28 जुलाई 1914 ई. को ऑस्ट्रिया ने जो युद्ध के लिए उतावला हो रहा था, सर्विया पर आक्रमण करने की घोषणा कर दी।<br /></p><p>इस घटना से 1914 ई. में प्रथम विश्वयुद्ध का कुप्रारम्भ हुआ। फ्रांस ने रूस के साथ संधि कर ऑस्ट्रिया के विरुद्ध रूस की सहायता का वचन दिया जबकि रूस ने अपने सैनिकों को ऑस्ट्रिया के विरुद्ध युद्ध करने के लिए भेज दिया। यह रूस की बाध्यता थी अन्यथा युद्ध उसकी सीमा के निकट छिड़ जाता। प्रारम्भ में इंगलैण्ड एवं ज़र्मनी इस युद्ध को सीमित रखने के पक्ष में थे किन्तु जर्मनी भी युद्ध में कूद पड़ा। विवश इंगलैण्ड फ्रांस एवं रूस के साथ मिल गया। इस प्रकार विश्व के बड़े राष्ट्र दो गुटों में विभाजित होकर महाविनाशक युद्ध में जुट गये।<br /></p>',120,'2024-10-26 17:49:51','2024-10-26 18:40:28','','Publish',0,'open',14,46),('प्रथम विश्वयुद्ध के परिणाम।','results-of-the-first-world-war',2,'<p>लगभग चार साल पंद्रह हफ्ता लगातार चलने वाला यह विश्वयुद्ध जर्मनी के आत्मसमर्पण के साथ 11 नवम्बर 1918 ई. को समाप्त हुआ। इस युद्ध में मित्रराष्ट्रों को अमेरिका द्वारा दी गयी सैनिक सहायता ने निर्णायक भूमिका निभायी थी। अमेरिका के राष्ट्रपति विल्सन ने यह नारा दिया था कि जर्मनी को हराकर संसार को लोकतंत्र के लिए सुरक्षित बचाना है। उसका यह भी कहना था कि अमेरिका जर्मनी की जनता से नहीं अपितु उसके अत्याचारी शासक से लड़ रहा है। विल्सन युद्ध के उपरान्त अपने चौदह सूत्री सिद्धान्त के आधार पर ऐसे सुन्दर संसार का निर्माण करना चाहता था जहाँ राष्ट्रसंघ की देख-रेख में शान्ति एवं न्याय की स्थापना हो । किन्तु प्रथम विश्वयुद्ध के परिणाम तथा बाद की घटनाएँ विल्सन के मनोनुकूल नहीं हुईं।</p><br /><h2>प्रथम विश्वयुद्ध के मुख्य परिणाम निम्नलिखित थे -</h2><br /><h3>1. जन-धन का विनाश </h3><p>A. प्रथम विश्वयुद्ध में इतिहासकारों ने अनुमान लगाया है कि कम-से-कम 80 लाख सैनिक असैनिक मारे गये तथा 60 लाख से अधिक लोग अपंग हुए। इस प्रकार भयंकर नरसंहार की घटना ने विश्व में आबादी तथा स्त्री-पुरुष के सन्तुलन को विकृत कर दिया था।<br /></p><p>B. नरसंहार के अतिरिक्त अर्थशास्त्रियों के अनुसार इस महायुद्ध में 58,500 करोड़ रुपये खर्च हुए। प्रतिदिन औसतन खर्च 40 करोड़ रुपये था। अन्तिम दिनों में यह राशि 80 करोड़ रुपये प्रतिदिन पहुँच गयी थी। वित्तीय असंतुलन के कारण जीवनोपयोगी चीजों की कीमतें आसमान छूने लगीं। पैदावार की 4 साल की कमी ने आवश्यक वस्तुओं का अभाव पैदा कर दिया था। मुद्रा का अवमूल्यन होने लगा जिससे व्यापार में अव्यवस्था फैल गयी।<br /></p><h3>2. उद्योग-धन्धों में ह्रास</h3><p> युद्ध के अवसर पर युद्ध सामग्री के अतिरिक्त अन्य उत्पादन नगण्य हो गये थे। युद्ध के विनाश ने अनेक फैक्टरी, मकानों एवं कारखानों को धवस्त कर दिया था। सबसे अधिक क्षति फ्रांस, इंगलैण्ड, सर्विया, रूमानिया और बेल्जियम को उठानी पड़ी थी। बाहर से कच्चा माल आने तथा तैयार माल जाने में बाधाएँ उत्पन्न हो गयी थीं। जर्मनी एवं ऑस्ट्रिया इस दृष्टि से सर्वाधिक प्रभावित थे।<br /></p><h3>3. गणराज्यों की स्थापना </h3><p>विश्वयुद्ध के पूर्व फ्रांस, स्विटजरलैण्ड और पुर्तगाल ऐसे युद्ध - संलग्न देश थे जहाँ गणतंत्र की स्थापना थी किन्तु इस युद्ध की समाप्ति के साथ लोकतंत्र की माँग तेजी से बढ़ी और अनेक देश क्रमशः लोकतंत्रीय प्रणाली अपनाने लगे। निरंकुश शासकों का अन्त हुआ। रूस से जारशाही का विनाश हुआ। ऑस्ट्रिया, हंगरी, बुल्गेरिया में राजवंश का अन्त हुआ। जर्मनी का भी गौरवशाली राजवंश सदा के लिए समाप्त हो गया। एक दशक के भीतर तुर्की से भी निरंकुश शासन का खात्मा हुआ। इस प्रकार रूस, जर्मनी, पोलैण्ड, ऑस्ट्रिया, लिथुआनिया, लौटाविया, फीनलैण्ड, यूक्रोनिया आदि देशों में गणतंत्रीय शासन व्यवस्था की स्थापना हुई।<br /></p><h3>4. अधिनायकवाद का विकास </h3><p> युद्ध के दुष्परिणाम स्वरूप अधिनायकवादी प्रवृत्ति विकसित हुई। राजवंशों के पतन के पश्चात् जब गणतंत्रीय व्यवस्था ने पैर जमाना शुरू किया तो प्रायः राजनेताओं की भूमिका अधिनायकवादी हो गयी। गणतंत्र में अपने विरोधी नेताओं को कुचलने तथा शक्ति संचय की प्रवृत्ति से प्रभावित इन राजनेताओं ने अपना वर्चस्व बनाये रखने के लिए हर हथकंडे अपनाये। देश के इन कर्णधारों ने भलाई सुरक्षा-उन्नति के नाम पर असीमित अधिकारों का प्रयोग करना शुरू कर दिया। इस तरह इटली, स्पेन, जर्मनी, रूस आदि देशों में राजनीतिक दलों का दृढ़ शासन स्थापित हो गया। इस प्रवृत्ति ने क्रमशः विकसित होकर फासीवाद का रूप ग्रहण कर लिया जिसने मुसोलिनी तथा हिटलर का मार्ग प्रशस्त कर दिया था।<br /></p><h3>5. राष्ट्रीयता के सिद्धान्त को बल </h3><p> इस महायुद्ध से विश्व में राष्ट्रीयता के सिद्धान्त को काफी शक्ति मिली और वर्साय की सन्धि के आधार पर यूरोप में 8 नये राज्यों का निर्माण हुआ। फिर भी कुछ ऐसे देश थे जिन्हें इन सिद्धान्तों का लाभ नहीं मिला; जैसे- इंगलैण्ड के अधीनस्थ देश, भारत, आयरलैण्ड और मिस्र तथा अफ्रीका में बड़े-बड़े देशों के अनेक उपनिवेश ।<br /></p><h3>6. नये देशों का शक्ति के रूप में उदय</h3><p><br /> विश्वयुद्ध ने तत्कालीन अनेक शक्तिशाली कहे जाने वाले देशों को धन एवं शक्ति से जर्जर कर दिया था तथा वे अपनी विभिन्न योजनाओं द्वारा पुनर्निर्माण में लगे हुए थे। अमेरिका की इस युद्ध में प्रत्यक्ष भागीदारी नहीं थीं। अतः वह युद्ध के दुष्प्रभावों से प्रभावित नहीं हुआ। उसके सभी साधन सुरक्षित रहे तथा वह प्रगति पथ पर क्रमशः बढ़ते हुए विश्व का सबसे अधिक शक्तिशाली देश बन गया। एशिया में इसी प्रकार जापान ने प्रगति की तथा अमेरिका के पश्चात् पूर्वी एशिया में जापान की आर्थिक एवं सैन्य शक्ति काफी सुदृढ़ हो गयी। इस प्रकार कुछ नये देश इस युद्ध के फलस्वरूप उभर कर सामने आये।<br /></p><h3>7. राजनीतिक एवं सामाजिक प्रभाव </h3><p>इस युद्ध के उपरान्त राजनीतिक में सर्वहारा वर्ग का महत्त्व बढ़ गया। युद्ध के समय मजदूरों ने जी-तोड़ मेहनत की थी तथा हर देश ने उनकी शक्ति का एहसास किया। रूस में जगह-जगह पर अन्तर्राष्ट्रीय मजदूर संगठन बनने लगे।<br /></p><p>महिलाएँ जो समाज में अब तक उपेक्षित थीं, महत्त्वपूर्ण हो गयीं। पुरुष-क्षय से उनका महत्त्व बढ़ गया। कल-कारखाने, कार्यालयों में महिलाएँ आगे बढ़ कर काम करने लगीं। महिलाओं ने विभिन्न संगठनों द्वारा अपने अधिकारों की माँग की। काले-गोरे का भेद भी बहुत सीमा तक मिट गया।<br /></p><h3>8. नवीन आविष्कार </h3><p> इस विश्वयुद्ध का एक उपयोगी पक्ष यह है कि चिकित्सकीय क्षेत्र में अनेक लाभकारी आविष्कार हुए। चूँकि इस युद्ध में तरह-तरह की जहरीली गैसों का प्रयोग हुआ था अतः इसे रासायनिकों का भी युद्ध कहा जाता है। रसायनशास्त्रियों ने अपने ज्ञान एवं अनुभव का लाभ नयी-नयी उपयोगी औषधियों की खोज में लगाया और सफल हुए। शल्य चिकित्सा के क्षेत्र में भी उल्लेखनीय सफलता प्राप्त की गयी।<br /><br /></p><h3>9. पराजित राष्ट्रों का शोषण</h3><p> विश्वयुद्ध का सारा दायित्व जर्मनी पर लादा गया तथा उसे दोषी ठहराया गया। वर्साय संधि के द्वारा इस नाम पर कि पुनः संसार में युद्ध न भड़क सके जर्मनी को बुरी तरह दबाया गया। उसके साम्राज्य के लगभग छठे भाग को मित्रराष्ट्रों ने आपस में बाँट लिया और 1500 करोड़ रुपये का जुर्माना लगाया गया। इसके अतिरिक्त यह भी निश्चित किया गया कि जर्मनी दस वर्षों तक 60 लाख टन कोयला प्रतिवर्ष इटली, बेल्जियम एवं फ्रांस को देता रहेगा। जर्मनी के युद्धपोतों, सुंरंगों, पनडुब्बियों पर मित्रराष्ट्रों का अधिकार हो गया और इस संधि द्वारा उसकी नौ-शक्ति को समाप्त कर दिया गया।<br /></p><h2>प्रथम विश्वयुद्ध प्रभाव</h2><p>इस विश्वयुद्ध का घातक प्रभाव संसार की आर्थिक, राजनीतिक एवं सामाजिक व्यवस्था पर भी पड़ा। यद्यपि राजतंत्र का तो अन्त हुआ किन्तु कतिपय यूरोपीय देशों के शक्तिशाली होने के कारण उपनिवेशों के शोषण का मार्ग भी प्रशस्त हुआ। वर्साय की संधि द्वारा जर्मनी इस प्रकार दबाया गया था जो स्वाभाविक और सहज ग्राह्य नहीं था। अतः जर्मन जिसकी झलक राष्ट्रीयता संधि के बोझ को उतार फेंकने के लिए व्यग्र थी विश्व के द्वितीय युद्ध में देखा साफ दिखायी पड़ता है।<br /></p><p>प्रथम विश्वयुद्ध 4 वर्ष 3 माह 11 दिन तक चला। ऐसा युद्ध इतिहास में पहले कभी नहीं हुआ था। इतनी अधिक सैनिक संख्या ने कभी भी किसी युद्ध में भाग नहीं लिया था । 30 राज्यों के 65,000,000 सैनिकों ने प्रत्यक्ष रूप से इसमें भाग लिया। इसमें 13,000,000 व्यक्ति युद्धभूमि में अपने प्राणों से हाथ धो बैठे। अर्थात् प्रत्येक 5 व्यक्ति में से एक व्यक्ति मारा गया। लगभग 22,000,000 सैनिक घायल हुए जिसमें 7,00,000 स्थायी रूप से अपाहिज या अपंग हो गये। दुनिया के इतिहास में यह अभूतपूर्व युद्ध था। 1790 ई. से 1813 ई. तक अर्थात् 123 वर्षों में विश्व के विभिन्न भागों में जो प्रमुख युद्ध हुए थे उसमें मरने वाले सैनिकों की दुगुनी संख्या से भी अधिक 1914 ई. से 1918 ई. तक के युद्धों में मरने वालों की संख्या थी।<br /></p><p>इस युद्ध में दोनों पक्षों को 186,000,000 डॉलर खर्च करने पड़े। इसके अतिरिक्त युद्ध में 39,000,000,000 डॉलर मूल्य की सम्पत्ति नष्ट हो गयी। इतनी बड़ी आर्थिक विनाश-लीला पहले कभी नहीं हुई थी। वर्षों तक यूरोपीय जनता एवं विश्व के प्राणी आर्थिक संकट के दौर से गुजरे।<br /></p><p>राजनीतिक दृष्टि से यूरोप के तीन प्राचीन राजवंश - ऑस्ट्रिया का हेप्सवर्ग, प्रशा या जर्मनी का होहेनत्सोलर्न और रूस का रोमेनाफ राजवंश समाप्त हो गये। इसके अलावे छोटे-छोटे जर्मन एवं बुल्गेरिया के कई राजवंशों का भी समापन हो गया।<br /></p><p>निरंकुश एकतंत्र पर प्रजातंत्र की विजय विश्वयुद्ध का परिणाम माना जा सकता है। राष्ट्रीय आत्मनिर्णय का सिद्धान्त विजयी हुआ। युद्ध के बाद समाजवादी विचारधारा को बल मिला। मार्क्सवादी समाजवाद का प्रभाव बढ़ने लगा।<br /></p><p>विनाशकारी शस्त्रों के प्रयोग के कारण हवाई जहाजों, पनडुब्बियों एवं विषैले गैसों ने सैनिक एवं असैनिक नागरिकों को जो क्षति पहुँचायी वह मानव जाति के इतिहास में एक दर्दनाक घटना के रूप में स्मरणीय रहेगा।<br /></p>',128,'2024-10-26 17:49:51','2024-10-26 18:42:02','','Publish',0,'open',14,47),('प्रथम विश्वयुद्ध के पश्चात् युद्ध की क्षतिपूर्ति समस्या?','war-compensation-problem-after-the-first-world-war',2,'<p>प्रथम विश्वयुद्ध में धन-जन की अपूरणीय क्षति हुई थी। इस क्षति का सर्वाधिक प्रभाव पराजित राज्यों पर पड़ा क्योंकि युद्ध में तो उनकी आर्थिक व्यवस्था डगमगा गई। साथ ही उसे मित्रराष्ट्रों को क्षति पूर्ति के रूप में भारी धनराशि की देनदारी भी घोप दी गई।<br /></p><p>इस महायुद्ध में मित्रराष्ट्रों को जो क्षति हुई। उसके लिए जर्मनी तथा उसके साथियों को मुख्य रूप से दोषी ठहराया गया। वे अपनी सभी क्षतिपूर्ति की वसूली जर्मनी एवं उसके साथी देशों से करना चाहते थे। इस युद्ध में अमेरिका शामिल नहीं हुआ था, उसने युद्ध में कर्ज के रूप में काफी धनराशि मित्र राष्ट्रों को दी थी। प्रारंभ में ब्रिटेन ने भी मित्रराष्ट्रों को युद्ध लड़ने के लिए कर्ज दिए थे, लेकिन जब युद्ध उग्र रूप धारण करने लगे तो ब्रिटेन के लिए भी कर्ज देना असंभव हो गया था।<br /></p><p>युद्ध समाप्त होने के पश्चात् यूरोप के बहुत से राज्य अमेरिका और ब्रिटेन के कर्जदार थे। साथ ही साथ ब्रिटेन स्वयं अमेरिका का ऋणी था। मित्रराष्ट्रों ने अपने कर्ज की मुक्ति ..के लिए जर्मनी एवं उसके साथियों से हर्जाना वसूलने की भारी रकम लाद दी थी। लेकिन, जर्मनी के सहयोगी राष्ट्रों- ऑस्ट्रिया, हंगरी और बुल्गेरिया लड़ाई में इतने निर्बल हो गए थे कि इनसे कोई हर्जाना वसूलना संभव नहीं था। इन देशों की आर्थिक व्यवस्था संभालने के लिए इन्हें ही कर्ज की आवश्यकता थी। इस स्थिति में मित्रराष्ट्रों के कर्ज का बोझ पूर्णतया जर्मनी पर ही पड़ गया।<br /></p><p>इसी बीच 1920, में स्पा में आयोजित एक कांफ्रेन्स में मित्रराष्ट्रों ने यह तय किया कि जर्मनी से जो भी धन की वसूली की जाएगी उसमें 52% हिस्सा फ्रांस, 22% ब्रिटेन, 8% बेल्जियम, 10% इटली और शेष 8% सभी अन्य मित्रराष्ट्रों द्वारा आपस में बाँट लिए जायेंगे। जर्मनी से वसूल की जानेवाली हरजाने की मात्रा और उसे वसूल करने के ढंग का निर्णय करने के लिए पेरिस की शांति परिषद ने एक \"हर्जाना कमीशन\" को नियुक्त किया, जिसमें अमेरिका, इटली, ब्रिटेन और फ्रांस का एक-एक प्रतिनिधि शामिल थे। इन चार प्रमुख राज्यों के प्रतिनिधियों के अलावे अन्य मित्रराष्ट्रों के भी अन्य प्रतिनिधियों को इसमें शामिल किया गया। प्रारम्भ में जर्मनी से 1500 करोड़ रुपये हर्जाने के रूप में तत्काल जमा करने को कहा गया था, जिसे बाद में कुल 10 हजार करोड़ रुपये नियत कर दिया गया।<br /></p><p>प्रारंभ में यह प्रयास किया गया था कि जर्मनी माल के रूप में हर्जाना अदा करें। वह अपने इंजन, कल-कारखानों की मशीनें, कोयला, लोहा और इसी प्रकार के अन्य व्यवसायिक माल देकर हर्जाने की अच्छी-खासी रकम अदा कर सकता था। जर्मनी ने इस तरह से बहुत सारा माल दिया भी परन्तु इसका परिणाम यह हुआ कि जर्मनी के माल से फ्रांस, ब्रिटेन व अन्य देशों के बाजार भर गए। जर्मनी से मुफ्त में आया हुआ यह माल बाजार में बहुत सस्ती कीमत पर बिकने लगा। इसके मुकाबले में अपने देश का माल बिकना मुश्किल हो गया।<br /></p><p>परिणाम यह हुआ कि पूँजीपतियों ने इस तरह माल की शक्ल में हर्जाना वसूल करने के खिलाफ आवाज उठाई और मित्रराष्ट्रों ने यह तय किया कि हर्जाना माल की शक्ल में न लेकर नगद लिया जाए। पर जर्मनी नकदी तभी दे सकता था, जब उसके निर्यात माल की मात्रा आयात माल के मुकाबले ज्यादा रहे। इसके बिना और कोई उपाय नहीं था, जिससे जर्मनी हर्जाने की इतनी भारी रकम अदा कर सके।<br /><br /></p><p>जर्मनी के साम्राज्य बिखर गए थे उसके उपनिवेश छिन्न गए थे। इस कारण उसके सभी बाजार उसके हाथों से निकल गए थे। इस दशा में अधिक मात्रा में अपने माल को विदेशों में बेचकर जर्मनी के लिए हर्जाना अदा कर सकना संभव नहीं था। अब उसके पास यही उपाय था कि टैक्स अधिक बढ़ाये, सरकारी खर्च में कभी करें और मुद्रा का प्रसार करें।<br /></p><p>इसी बीच 1920, में स्पा में आयोजित एक कांफ्रेन्स में मित्रराष्ट्रों ने यह तय किया कि जर्मनी से जो भी धन की वसूली की जाएगी उसमें 52% हिस्सा फ्रांस, 22% ब्रिटेन, 8% बेल्जियम, 10% इटली और शेष 8% सभी अन्य मित्रराष्ट्रों द्वारा आपस में बाँट लिए जायेंगे। जर्मनी से वसूल की जानेवाली हरजाने की मात्रा और उसे वसूल करने के ढंग का निर्णय करने के लिए पेरिस की शांति परिषद ने एक \"हर्जाना कमीशन\" को नियुक्त किया, जिसमें अमेरिका, इटली, ब्रिटेन और फ्रांस का एक-एक प्रतिनिधि शामिल थे। इन चार प्रमुख राज्यों के प्रतिनिधियों के अलावे अन्य मित्रराष्ट्रों के भी अन्य प्रतिनिधियों को इसमें शामिल किया गया। प्रारम्भ में जर्मनी से 1500 करोड़ रुपये हर्जाने के रूप में तत्काल जमा करने को कहा गया था, जिसे बाद में कुल 10 हजार करोड़ रुपये नियत कर दिया गया।<br /></p><p>हर्जाने की अदायगी में कठिनाई: प्रारंभ में यह प्रयास किया गया था कि जर्मनी माल के रूप में हर्जाना अदा करें। वह अपने इंजन, कल-कारखानों की मशीनें, कोयला, लोहा और इसी प्रकार के अन्य व्यवसायिक माल देकर हर्जाने की अच्छी-खासी रकम अदा कर सकता था। जर्मनी ने इस तरह से बहुत सारा माल दिया भी परन्तु इसका परिणाम यह हुआ कि जर्मनी के माल से फ्रांस, ब्रिटेन व अन्य देशों के बाजार भर गए। जर्मनी से मुफ्त में आया हुआ यह माल बाजार में बहुत सस्ती कीमत पर बिकने लगा। इसके मुकाबले में अपने देश का माल बिकना मुश्किल हो गया।<br /><br /></p><p>परिणाम यह हुआ कि पूँजीपतियों ने इस तरह माल की शक्ल में हर्जाना वसूल करने के खिलाफ आवाज उठाई और मित्रराष्ट्रों ने यह तय किया कि हर्जाना माल की शक्ल में न लेकर नगद लिया जाए। पर जर्मनी नकदी तभी दे सकता था, जब उसके निर्यात माल की मात्रा आयात माल के मुकाबले ज्यादा रहे। इसके बिना और कोई उपाय नहीं था, जिससे जर्मनी हर्जाने की इतनी भारी रकम अदा कर सके।<br /><br /></p><p>जर्मनी के साम्राज्य बिखर गए थे उसके उपनिवेश छिन्न गए थे। इस कारण उसके सभी बाजार उसके हाथों से निकल गए थे। इस दशा में अधिक मात्रा में अपने माल को विदेशों में बेचकर जर्मनी के लिए हर्जाना अदा कर सकना संभव नहीं था। अब उसके पास यही उपाय था कि टैक्स अधिक बढ़ाये, सरकारी खर्च में कभी करें और मुद्रा का प्रसार करें।<br /></p><p>मुद्रा के प्रसार से विदेशी विनिमय में जर्मनी के सिक्के की कीमत गिरेगी, सिक्के की कीमत गिरने से दूसरे देश में जर्मनी का माल सस्ता पड़ेगा और इस प्रकार जर्मनी के लिए यह संभव हो जाएगा, कि वह अपना माल अधिक से अधिक मात्रा में दूसरे देशों को बेच सके और उससे जो धन उसे प्राप्त हो, उसे हर्जाने की अदाएगी के लिए प्रस्तुत कर सके। जर्मनी ने इसी नीति का अनुसरण किया। जर्मन सिक्को मार्क की कीमत गिरने लगी और जर्मनो का माल अन्य देशों में सस्ते दाम पर बिकने लगा।<br /></p><p>इसी बीच ब्रिटेन, फ्रांस, अमेरिका में जर्मनी से आया माल अपने देश के मुकाबले सस्ते में बिकने लगा। कल-कारखानों के मालिकों को फिर शिकायत का मौका मिला और उन्होंने अपने देशों की सरकारों को इस बात के लिए विवश किया कि संरक्षण नीति का अनुसरण किया जाए और बाहर से आने वाले माल पर आयात कर लगाया जाए। इसके परिणामस्वरूप जर्मन माल विदेशी में बिकना बंद हो गया और पैदावार बढ़ाकर व माल को दूसरे देशों में बेचकर हर्जाने की अदाएगी की सब आशा नष्ट हो गई।<br /></p><p>अब जर्मनी के पास केवल एक उपाय शेष रहा, कि वह कर्ज ले और मुद्रा का और अधिक प्रसार करें। परिणाम यह हुआ कि मार्क की कीमत लगातार गिरती गई और जर्मनी का आर्थिक जीवन बिल्कुल अस्त-व्यस्त हो गया। सिक्के की कीमत गिरने का असर किसी भी देश की आर्थिक जीवन पर बहुत बुरा पड़ता है। लोग अपने धन को अपनी बचत को बैंकों में जमा करते है। बैंक उसी रकम का देनदार होता है, जो उसके पास जमा की गई हो। यदि उसके पास किसी के एक हजार मार्क जमा है तो वह एक हजार मार्को का ही देनदार है। बैंक को इस बात से कोई वास्ता नहीं कि जब उसके पास रकम जमा कराई गई थी तो उससे कितना माल खरीदा जा सकता था और जब वह रकम वापस दे रहा है तो उससे क्या कुछ माल खरीदा जा सकता है। यही हालत बीमा कम्पनियों द्वारा दी जाने वाली रकमों, सरकारी कर्ज की रकमों और अन्य देनदारियों के बारे में समझी जा सकती है।<br /></p><p>मुद्रा का इस प्रकार अवमूल्यन हो गया कि अब मार्क का कोई मूल्य ही नहीं रह गया। प्रारंभ में एक पौण्ड के 20 मार्क आते थे, 1920 में मार्क की कीमत गिरकर 250 मार्क पहुँच गई थी। 1922 में एक पौण्ड के बदले 34,000 मार्क खरीदे जा सकते थे। इसका परिणाम यह हुआ कि लोगों को जो कुछ रुपया पाना था, वह सब मिट्टी हो गया। कीमते बेहद बढ़ गई। आम मजदूरों को जो दैनिक मजदूरी मिलती थी, उसमें तो कीमतों के बढ़ने के साथ-साथ वृद्धि भी हो सकती थी पर मध्यम श्रेणी के लोगों को जो वेतन मिलता था वे प्रायः निश्चित होते थे।<br /></p><p>इस प्रकार मध्यम श्रेणी के नियत वेतन पाने वाले को गंभीर संकटों का सामना करना पड़ा। उनकी आमदनी तो अब आम गरीब, मजदूरों के बराबर रह गई थी, पर उनका रहन-सहन ऊंचा था। उनमें बहुत बैचेनी और असंतोष था । विदेशी लोगों के लिए जर्मनी अब स्वर्ग के समान था। कोई भी व्यक्ति पौण्ड, रुपया, फ्रांक या डॉलर जेब में डालकर जर्मनी में आनन्द से जीवन बिता सकता था। मात्र कुछ रुपयों में ही सम्पूर्ण जर्मनी की यात्रा की जा सकती थी। कुछ पैसों में प्रतिदिन अच्छे से अच्छे होटल में ठहरा जा सकता था। कुछ रुपयों में ही जर्मनी में अच्छी जायदाद भी खरीदी जा सकती थी।<br /></p><p><br />जर्मनी की इस दुर्दशा पर जर्मनी के लोग अधिक परेशान थे। उनके लिए यह असंभव था कि हर्जाने की अदायगी में कुछ भी दे सके। नगद कुछ भी दे सकना उनके लिए • नामुमकिन था। उनके सिक्कों की कीमत धूल में मिल गई थी, उससे किसी भी विदेशी सिक्के को खरीद सकना उसके लिए कठिन था। यही कारण था, जब हर्जाने की राशि नहीं दे सकने के कारण फ्रांस ने जर्मनी के रूर प्रदेश पर अधिकार कायम कर लिया था।<br /></p><h2>निष्कर्ष </h2><p> इस प्रकार उपरोक्त अध्ययनों से हम इस निष्कर्ष पर पहुँचते है कि प्रथम विश्वयुद्ध के पश्चात् मित्रराष्ट्रों द्वारा युद्ध के लिए जर्मनी एवं उसके सहयोगियों को उत्तरदायी ठहराया गया। इसके बदले में उन्होंने क्षतिपूर्ति की माँग की, लेकिन जर्मनी के सहयोगी राष्ट्र आर्थिक रूप से पूर्णतया पंगु हो गए थे अतः उनके स्थान पर पूर्ण रूपेण जर्मनी से क्षतिपूर्ति का लक्ष्य निर्धारित किया गया। इस कारण जर्मनी को कई कठिनाइयों का सामना करना पड़ा। उसकी अर्थव्यवस्था पूरी तरह से चौपट हो गई। इसी के परिणामस्वरूप जर्मनी में हिटलर जैसे तानाशाह का उदय हुआ। उसने इस क्षतिपूर्ति को गलत बताया तथा इसके अदायगी को समाप्त कर दिया जिसके परिणामस्वरूप आगे चलकर द्वितीय विश्वयुद्ध की समस्या खड़ी हो गई।<br /></p>',97,'2024-10-26 17:49:51','2024-10-26 18:44:05','','Publish',0,'open',14,48),('1929-32 की आर्थिक मंदी के कारण ','due-to-world-economic-recession',2,'<h2>आर्थिक मंदी</h2>\r\n<p>1929-32 इ दौरान दुनिया के अधिकतर हिस्सों में उत्पादन, आय, व्यापार और रोज़गार में भारी कमी आ गई थी, जिससे भारी संख्या\r\n    में लोग भुखमरी और गरीबी का शिकार हो गये थे। इतना ही नहीं, उद्योग बंद होने से बड़े-बड़े उद्योगपति भी क़र्ज़ में डूब\r\n    गए थे।</p>\r\n<h2>आर्थिक मंदी का अर्थ</h2>\r\n<p>महामंदी के कारणों और उसके प्रभावों पर चर्चा करने से पहले यह जानना ज़रूरी है कि, आर्थिक मंदी का अर्थ क्या होता है?\r\n    दरअसल, आर्थिक मंदी अर्थव्यवस्था का एक कुचक्र है जिसमें फंसकर आर्थिक वृद्धि रुक जाती है और देश के विकास कार्यों में\r\n    बाधा आ जाती है। इस दौरान बाज़ार में वस्तुओं की भरमार होती है लेकिन खरीदने वाला कोई नहीं होता है। उत्पादों की आपूर्ति\r\n    अधिक व मांग कम होने से अर्थव्यवस्था असंतुलित हो जाती है।</p>\r\n<h2>साल 1929 की वैश्विक महामंदी के कारण</h2>\r\n<h3 class=\"atech\">अति उत्पादन की समस्या</h3>\r\n<p> प्रथम विश्व युद्ध के दौरान अमेरिका और जापान में बड़े-बड़े कल कारखाने खोले गये थे। इन\r\n    कारखानों में बड़ी मात्रा में उत्पादन होता था। इनमें युद्ध के दौरान जितनी वस्तुओं का निर्माण किया जाता था, उतनी ही\r\n    वस्तुओं का निर्माण युद्ध के बाद भी जारी था। जिसका परिणाम यह हुआ कि, बाजा़र में वस्तुएं भरी पड़ी थीं लेकिन उन्हें\r\n    खरीदने वाला कोई नहीं था।</p>\r\n<p>यह समस्या कृषि के क्षेत्र में सबसे ज़्यादा थी। अंतर्राष्ट्रीय स्तर पर कृषि उपज के अति उत्पादन से अनाज की कीमतें बेहद\r\n    निचले स्तर पर पहुंच गईं थी और किसानों की आय घट गई थी। अपनी आय के स्तर को बनाये रखने के लिये किसानों ने और अधिक\r\n    उत्पादन करना शुरू कर दिया था। जिसके चलते ऐसी स्थिति आ गई थी कि बाज़ार में कृषि उपजों की आमद और बढ़ गई और कीमतें और\r\n    भी कम हो गईं; लेकिन खरीदारों के न आने से अनाज पड़ा-पड़ा सड़ने लगा था।</p>\r\n<h3 class=\"atech\">अमेरिकी शेयर बाज़ार में गिरावट</h3>\r\n<p> 23 अक्टूबर 1929 को न्यूयार्क-स्टॉक एक्सचेंज में शेयरों का मूल्य अचानक से 50\r\n    अरब डॉलर गिर गया था। अमेरिकी सरकार और पूँजीपतियों के प्रयास से स्थिति कुछ ठीक हुई लेकिन अगले महीने यानी नवंबर में\r\n    फिर से शेयरों की कीमत बहुत घट गई थी। शेयर बाज़ार के इस तरह से धड़ाम होने पर बड़े-बड़े निवेशकों का दिवाला निकल गया\r\n    था। इसके बाद अमेरिका में जो फैसले लिये गए उनका प्रभाव अन्य देशों पर भी बहुत गहरा पड़ा था।</p>\r\n<h3 class=\"atech\">क़र्ज़ की समस्या</h3>\r\n<p> महामंदी का दूसरा कारण युद्धकालीन क़र्ज़ था। प्रथम विश्व युद्ध के दौरान तत्कालीन यूरोपीय\r\n    राष्ट्रों ने अमेरिका से बहुत बड़ी राशि क़र्ज़ के रूप में ली थी। यहाँ तक कि, ब्रिटेन जैसे शक्तिशाली देश भी अमेरिकी\r\n    क़र्ज़ के बोझ तले दबे हुये थे। शुरुआत में अमेरिका युद्ध में शामिल नहीं हुआ था लेकिन वह अपने मित्रराष्ट्रों को लगातार\r\n    क़र्ज़ दे रहा था। पर जब अमेरिकी उद्यमियों को संकट के संकेत मिले तो उनके होश उड़ गए और अमेरिका ने साल 1929 की शरद ऋतु\r\n    में यह घोषणा कर दी कि अब वह किसी भी देश को क़र्ज़ नहीं देगा। इस घोषणा का मुख्य कारण स्वयं अमेरिका में मूल्यपात\r\n    (Slump) था।</p>\r\n<p>वर्ष 1928 के पहले छह माह तक विदेशों में अमेरिका का क़र्जा़ एक अरब डॉलर था, जो कि साल भर के भीतर घटकर केवल चौथाई रह\r\n    गया था। जो देश अमेरिकी क़र्जे़ पर अधिक निर्भर थे उन पर गहरा संकट मंडराने लगा था। साथ ही, पूरी दुनिया की क्रयशक्ति घट\r\n    गई थी।</p>\r\n<p>इतना ही नहीं, अमेरिका की इस घोषणा से यूरोप के बड़े-बड़े बैंक धराशायी हो गये थे; ब्रिटेन समेत कई देशों की मुद्राओं की\r\n    कीमतें बुरी तरह से गिर गईं थी; लैटिन अमेरिका एवं अन्य स्थानों पर कृषि उत्पादों और कच्चे मालों की कीमतों में भी कमी आ\r\n    गई थी।</p>\r\n<h3 class=\"atech\">उच्च कर</h3>\r\n<p>अमेरिकी सरकार ने अपनी अर्थव्यवस्था को इस महामंदी से बचाने के लिये आयातित उत्पादों पर सीमा शुल्क\r\n    बढ़ाकर दो गुना कर दिया था। इस फैसले ने वैश्विक व्यापार को बुरी तरह प्रभावित किया था।</p>\r\n<p>धन का असमान वितरण- उस दौरान अमेरिका में 3-4% लोगों के पास करीब 50 फीसदी धन था और वही अमीर लोग अर्थव्यवस्था को\r\n    नियंत्रित कर रहे थे। धन का समान वितरण न होने से अधिकांश लोग गरीब थे।</p>\r\n<h3>महामंदी का विश्व पर प्रभाव</h3>\r\n<p>दुनिया के अधिकांश देश इस महामंदी की चपेट में आ गये थे। बात करें औद्योगिक देशों की, तो अमेरिका को इस आर्थिक महामंदी की\r\n    सबसे ज़्यादा मार झेलनी पड़ी थी। अमेरिका की अर्थव्यवस्था जितनी तेजी से समृद्ध हो रही थी, उतनी ही तेजी से लुढ़क भी गई\r\n    थी।</p>\r\n<p>मंदी के चलते अमेरिकी बैंकों ने घरेलू क़र्जे़ देना बंद कर दिया था और जो क़र्जे़ पहले दिये जा चुके थे,उनकी वसूली शुरू\r\n    कर दी थी। लेकिन कीमतों में कमी के कारण किसान से लेकर उद्योगपति तक, सभी आर्थिक संकट का सामना कर रहे थे और कई परिवार\r\n    क़र्जे़ चुकाने में असमर्थ थे। ऐसे में उन परिवारों के मकानों और कारों समेत सभी ज़रूरी चीजें कुर्क कर ली गईं थी।</p>\r\n<p>हज़ारों बैंक क़र्जे़ वसूल न कर पाने, ग्राहकों की जमा पूंजी न लौटा पाने और निवेश की गई धनराशि में लाभ न मिलने पर\r\n    दिवालिया हो गये थे और उन्हें बंद कर दिया गया था। इस प्रकार अमेरिकी बैंकिंग प्रणाली भी ध्वस्त हो गई थी। आंकड़ों की\r\n    बात करें तो, साल 1933 तक 4000 से ज़्यादा बैंक बंद हो चुके थे और साल 1929 से 1932 के बीच करीब 1,10,000 कंपनियाँ नष्ट\r\n    हो गईं थी। इतनी बड़ी संख्या में बैंक और कंपनियाँ बंद होने से तेजी से बेरोज़गारी बढ़ी और लोग काम की तलाश में दूर-दूर\r\n    तक जाने लगे।</p>',67,'2024-10-26 17:49:51','2024-10-26 18:47:27','','Publish',0,'open',22,49),(' हिटलर की गृह एवं विदेश नीति की विवेचना कीजिये।','hitler-domestic-and-foreign-policy',2,'<h2>हिटलर की गृह नीति </h2>\r\n<p>एडोल्फ हिटलर ने जर्मनी को यूरोप का एक प्रतिष्ठित राज्य बनाने के लिए न केवल अपनी विदेशनीति का कुशलतापूर्वक संयोजन किया\r\n    अपितु गृहनीति को भी इस प्रकार अपनाया कि देश की आर्थिक स्थिति में उल्लेखनीय सुधार हुआ साथ ही साथ जर्मनीवासियों में\r\n    अभूतपूर्व \'राष्ट्रीयता\' का उदय हुआ ।<br> हिटलर की गृहनीति को निम्नलिखित तथ्यों में आबंटित कर समझा जा सकता है-\r\n</p>\r\n<h3>1. आर्थिक सुधार </h3>\r\n<p>हिटलर ने जर्मनी की आर्थिक सुदृढ़ता के लिए लगभग उन्हीं मार्गों का अनुसरण किया था जिन्हें इटली में मुसोलिनी ने अपनाया\r\n    था। आर्थिक सुधार के लिए निम्नलिखित कदम उठाये गये-</p>\r\n<h4>A. बेकारी उन्मूलन का प्रयास </h4>\r\n<p>प्रथम विश्वयुद्ध के पश्चात् जर्मनी में आर्थिक तंगी तथा महँगाई के साथ-साथ बेकारी की समस्या विकराल रूप से बढ़ी हुई थी।\r\n    हजारों सैनिक कार्यमुक्त कर दिया गये थे। हिटलर ने इन्हें नाजीपार्टी का स्वयंसेवक बनाकर इनकी समस्या को बहुत हद तक दूर\r\n    किया। स्वयंसेवकों को वर्दी तथा वेतन प्रदान किया जाता था।</p>\r\n<p> इनके अतिरिक्त जर्मनी में अत्यधिक बंजर भूमि थी जिन्हें कृषियोग्य बनाने के लिए हिटलर ने मजदूर स्वयंसेवक सेना का गठन\r\n    किया तथा इन भागों को सड़क मार्ग से शहरों से जोड़ दिया जिससे उत्पादित अनाज नगर की मंडियों तक पहुँच सके। इस प्रकार\r\n    उसने बेकारी की समस्या को लगभग समाप्त कर दिया था।</p>\r\n<h4>B. कोयला उत्पादन </h4>\r\n<p>हिटलर की दृष्टि कोयला के उत्पादन पर लगी हुई थी जहाँ क्षमता से कम उत्पादन होता था। अनेक कोयला खानें उपेक्षित पड़ी थीं।\r\n    हिटलर ने सुप्त कोयला खानों में उत्पादन प्रारम्भ करवाया तथा जहाँ काम हो रहा था अधिक श्रमिक लगाकार उत्पादन में वृद्धि\r\n    की। इस प्रकार एक ओर कोयले के उत्पादन में अत्यधिक वृद्धि हुई तथा दूसरी ओर बेकारी की समस्या भी हल हुई।</p>\r\n<h4>C. श्रमिकों की निश्चित कार्य अवधि </h4>\r\n<p>श्रमिकों की सहानुभूति पाने तथा कल-कारखानों को पूरी तरह नियंत्रित करने के लिए हिटलर ने सप्ताह में कुल 40 घण्टे काम\r\n    निर्धारित कर दिये।</p>\r\n<h4>D विवाहित स्त्रियों को काम से रोकना </h4>\r\n<p>हिटलर तथा नाजी दल के नेता इस विचारधारा के थे कि विवाहित स्त्रियों का काम गृहस्थी सम्हालना है अतः वे किसी कार्यालय,\r\n    कारखाने आदि में काम नहीं कर सकती थीं। ऐसी कार्यरत स्त्रियों को काम से हटाकर बेरोजगारों को काम दे दिया गया। बेकारी और\r\n    घटी।</p>\r\n<h4>E. लेबर - फ्रंट की स्थापना </h4>\r\n<p>आर्थिक स्थिति का सीधा संबंध उत्पादन से होता है। और उत्पादन में संतोषजनक प्रगति मिल-मालिक एवं श्रमिकों के सहयोग से\r\n    संभव है अतः हिटलर ने मजदूर संघों एवं पूँजीपतियों के संगठनों को समाप्त कर लेबर फ्रंट की स्थापना की जिसमें मजदूरों एवं\r\n    पूँजीपतियों के प्रतिनिधि होते थे। इनमें विवाद होने पर सरकारी कर्मचारी हस्तक्षेप करते तथा उचित मार्ग निकालते थे। इस\r\n    प्रकार असंतोष समाप्त कर उत्पादन में वृद्धि संभव किया गया था।</p>\r\n<h3>2. आर्थिक आत्मनिर्भरता </h3>\r\n<p> किसी भी राष्ट्र के लिए आर्थिक आत्मनिर्भरता लोगों का उपयोग बंजर भूमि को कृषियोग्य बनाने में, फैक्टरी में अधिक\r\n    श्रमिकों द्वारा उसकी सबसे बड़ी शक्ति होती है। जर्मनी की आर्थिक आत्मनिर्भरता के लिए बेकार\' अधिक उत्पादन, कोयले के नये\r\n    खानों में खनन कार्य आरम्भ करा कर अधिक कोयला उत्पादन आदि ऐसे विधियाँ थीं कि जर्मनी में माल बहुतायत से बनने लगा और\r\n    उसका निर्यात भी शुरू हो गया। इसके अतिरिक्त जो वस्तुएँ विदेशों से आती थीं उनका उत्पादन जर्मनी में होने लगा। घरेलू\r\n    उत्पादन बढ़ाने तथा खपत में मितव्यययितापूर्वक प्रयोग पर कड़ी निगरानी रखी गयी।</p>\r\n<p> साथ ही साथ जर्मन वैज्ञानिकों का आह्वान किया गया कि वे ऐसी तकनीक एवं रसायन उन्नत करें जिससे खाद्यान्न का अपार भण्डार\r\n    सुरक्षित कर लिया जाय तथा युद्धोपयोगी वस्तुएँ प्रचुर मात्रा में उत्पादित कर ली जायें वस्तुतः आर्थिक आत्मनिर्भरता के\r\n    पीछे हिटलर की दृष्टि उस भावी युद्ध पर लगी थी जिसके द्वारा वर्साय की संधि के अपमान का वह बदला ले सके।</p>\r\n<h3>3. धार्मिक विचार </h3>\r\n<p>पीप को स्पष्ट कर दिया गया कि पादरी लोग राजनीति में भाग नहीं ले सकते। वे अपने को अपने कार्यक्षेत्र तक ही सीमित रखें।\r\n    आवश्यकता पड़ने पर उन्हें सरकारी नौकरियाँ दी जा सकती हैं। धर्म सम्बन्धी हिटलर की अन्य कोई रुचि\r\n    नहींथी।</p>\r\n<h3>4. यहूदी निष्कासन </h3>\r\n<p>नाजीवादी गृहनीति का एक मुद्दा जर्मनी को यहूदियों से मुक्त करना था। प्रथमं विश्वयुद्ध के समय तक जर्मनी का समस्त\r\n    व्यापार एवं अर्थतंत्र लगभग यहूदियों के हाथ में था जिससे जर्मनीवासियों का शोषण होता था। चूँकि हिटलर को आर्य होने का\r\n    अभिमान था और यहूदी सेमेटिक प्रजाति के थे अतः यहूदियों की वृत्ति, स्वभाव एवं प्रजाति के कारण हिटलर जर्मनी को उनसे\r\n    मुक्त करना चाहता था। उसने ऐसे अनेक कदम उठाये जिससे यहूदियों ने जर्मनी से पलायन करना शुरू कर दिया।</p>\r\n<h3>5. शिक्षा नीति </h3>\r\n<p> गृहनीति में शिक्षा नीति का महत्त्व है। हिटलर ने शिक्षा में नाजीवाद दर्शन को पढ़ाये जाने की अनिवार्यता निश्चित कर दी।\r\n    शिक्षा का सीधा सम्बन्ध युवा पीढ़ी से होता है और युवा पीढ़ी यदि नाजीवादी विचारधारा से प्रभावित होगी तो आगे आने वाले\r\n    दिनों में नाजीवाद के प्रचार-प्रसार में सहायता होगी।</p>\r\n<h3>6. जनसंख्या शुद्धिकरण </h3>\r\n<p>नाजी सरकार जर्मन जाति को विशुद्ध आर्य जाति बनाना चाहती थी। युद्ध के परिणामस्वरूप वहाँ पर जनसंख्या की पर्याप्त कमी हो\r\n    गयी थी अतः जनसंख्या वृद्धि का प्रचार किया जाने लगा। इस उद्देश्य से कानूनन अवैध सन्तान को अब वैध मान लिया गया। सरकार\r\n    ने व्यवस्था दी कि केवल वे ही लोग सन्तान उत्पन्न करेंगे जो स्वस्थ तथा परिश्रमी हों। जो व्यक्ति किसी वंशानुगत रोग का\r\n    शिकार होता था या बहुत मदिरा पीकर दुर्बल हो जाता था उसे नपुंसक कर दिया जाता था या विवाह करने की अनुमति नहीं दी जाती\r\n    थी जिससे अस्वस्थ सन्तान न उत्पन्न होने पाये। स्वस्थ संतति के लिए नाजियों का यह विधान प्रजातीय राष्ट्रीयता से\r\n    उत्प्रेरित था।</p>\r\n<h2>हिटलर की गृह विदेश नीति</h2>\r\n<p>हिटलर की विदेश नीति के मुख्य तीन आधार थे- </p>\r\n<ul>\r\n    <li> वर्साय संधि को ठुकरा देना। </li>\r\n    <li> समस्त जर्मन समुदाय को एकसूत्र में बाँधना।</li>\r\n    <li> जर्मन साम्राज्य का विस्तार करना तथा इसकी पूर्ति के लिए चाहे जो भी साधन अपनाना पड़े अपनाना।</li>\r\n</ul>\r\n<p>इतिहासकार लिप्सन के अनुसार हिटलर ने अपनी विदेश नीति के सम्बन्ध में स्वयं एक बार कहा था - <i>\"इसकी प्राप्ति के\r\n        लिए समझौता और यदि यह न हो सका तो युद्धं का आश्रय लेना विदेश नीति की ओर हमारा कदम होगा।\"</i></p>\r\n<h3>1. वर्साय संधि </h3>\r\n<p>हिटलर का प्रथम लक्ष्य वर्साय संधि को ठुकरा देना था। इस हेतु उसने सर्वप्रथम राष्ट्रसंघ से जर्मनी की सदस्यता समाप्त कर\r\n    देना ज्यादा उचित समझा। उसने अक्टूबर 1933 ई. में जर्मन प्रतिनिधियों को राष्ट्रसंघ से वापस बुला लिया और सदस्यता\r\n    त्यागने की सूचना भी दे दी। वर्साय संधि के अनुसार 15 वर्ष पश्चात् अर्थात् जनवरी 1935 ई. में सार प्रान्त को जनमत\r\n    द्वारा निश्चित करना था कि क्या वे जर्मनी में शामिल होना चाहेंगे। 90% मतदाताओं ने सार का जर्मनी साम्राज्य में विलय के\r\n    पक्ष में मत दिया और हिटलर ने सार को जर्मनी का अंग बना लिया। </p>\r\n<p>वर्साय संधि द्वारा आरोपित क्षतिपूर्ति दण्ड को उसने यह कहकर अस्वीकार कर दिया कि जर्मनी आक्रमक नहीं था न उसके ऊपर युद्ध\r\n    का दायित्व लादा जा सकता है। वर्साय संधि की पाँचवीं धारा के अनुसार जर्मनी को 1 लाख तक सेना रखने का अधिकार था किन्तु\r\n    हिटलर ने तीव्र गति से अपनी सैन्य शक्ति बढ़ाने का प्रयास किया तथा जर्मनी में सैनिक सेवा अनिवार्य कर दी एवं सैन्य\r\n    शक्ति को तेजी से बढ़ाने लगा। इस प्रकार हिटलर ने वर्साय संधि की धज्जी-धज्जी उड़ा दी और अपनी विदेश नीति का एक पक्ष\r\n    पूरा किया।</p>\r\n<h3>2. पोलैण्ड से समझौता </h3>\r\n<p>पोलैण्ड जर्मनी का पड़ोसी देश है। हिटलर ने पोलैण्ड के साथ 10 वर्ष की संधि की जिसके अनुसार दोनों देश एक-दूसरे की सीमा\r\n    का सम्मान करेंगे। इस समझौते से जर्मनी पोलैण्ड से अपने वे प्रदेश प्राप्त कर लेता जिसे पेरिस की शान्ति परिषद् द्वारा\r\n    पोलैण्ड के अधीन कर दिया गया था। उसका दूसरा उद्देश्य उस वृहद् जर्मन साम्राज्य की स्थापना करना था जिसे पोलैण्ड एवं\r\n    ऑस्ट्रिया को सम्मिलित कर बनाया जा सकता था। यह एक अपराजेय बड़ी शक्ति की कल्पना थी।</p>\r\n<h3>3. ब्रिटेन - जर्मन संधि </h3>\r\n<p>हिटलर ने उचित समय पर ब्रिटेन से मित्रता का हाथ बढ़ाया। जर्मन की फ्रांस से जन्मजात शत्रुता थी। इस बीच फ्रांस एवं रूस\r\n    ने संधि कर ली • थी जिससे ब्रिटेन भीतर ही भीतर नाराज था । उचित अवसर देखकर हिटलर ने ब्रिटेन को अपने पक्ष में ले लिया\r\n    और जून 1935 ई. को निश्चित हुआ कि थल और नभ सेना में जर्मनी पूरी तरक्की करे किन्तु नौसेना या नाविक शक्ति उसे ब्रिटेन\r\n    से 35% कम रखनी होगी। यह संधि गुप्त रखी गयी थी।</p>\r\n<h3>4. राइनलैण्ड का सैनिकीकरण</h3>\r\n<p> हिटलर राइनलैण्ड का पुनर्सेनिकीकरण करने के लिए तत्पर था। चूँकि फ्रांस रूस ने समझौता कर लोकार्नो संधि की शर्तों की\r\n    अवहेलना की थी अतः हिटलर का अधिकार होता है कि वह राइनलैण्ड का सैनिकीकरण कर दे। हिटलर ने 35 हजार जर्मन सैनिकों को\r\n    भेजकर राइनलैण्ड पर अधिकार कर लिया।</p>\r\n<h3>5. इटली - जर्मनी सन्धि</h3>\r\n<p> सार वापस पा लेने के पश्चात् पश्चिमी यूरोपीय देशों में हिटलर की अब अभिरुचि नहीं रह गयी थी। वह पूर्व में बढ़ना चाहता\r\n    था। इसके लिए उसे ऑस्ट्रिया पर विजय पाना आवश्यक था जो बिना इटली की सहायता के दुष्कर कार्य था । इटली एवं जर्मनी में\r\n    वैचारिक मतभेद नहीं था, दोनों साम्यवाद के दुश्मन थे। इसके अतिरिक्त इटली भूमध्य सागर पर अपना प्रभुत्व स्थापित करना\r\n    चाहता था और फ्रांस इसका प्रबल विरोधी था। फ्रांस से जर्मन की शत्रुता सभी यूरोपीय देश जानते थे। अबीसीनिया युद्ध के समय\r\n    मात्र जर्मनी ने ही इटली की सहायता की थी, जबकि ब्रिटेन, फ्रांस आदि देशों ने इटली का आर्थिक बहिष्कार किया था। इन\r\n    परिस्थितियों में 25 अंक्टूबर 1936 ई. को जर्मनी-इटली में समझौता हुआ जिसके अन्तर्गत-</p> \r\n<ul>\r\n    <li>जर्मनी ने अबीसिनिया पर इटली के अधिकारों को मान्यता दे दी </li>\r\n    <li>स्पेन में फ्रांको के आन्दोलन को समर्थन देना तय हुआ </li>\r\n    <li>यह तय हुआ कि रूस का विरोध करने में दोनों एकजुट रहेंगे </li>\r\n</ul> \r\n<p>इस समझौते से दो अधिनायक मित्र हो गये और फ्रांको स्पेन का शासक मान लिया गया। इस प्रकार तीसरी शक्ति भी इनसे आ मिली।\r\n    इटली-जर्मनी सन्धि हिटलर की योजना की एक बड़ी सफलता थी।</p>\r\n<h3>6. रोम-बर्लिन टोकियो धुरी </h3>\r\n<p>हिटलर के प्रयास ने उस जापान को भी अपना मित्र बना लिया जिसकी सेना ने रूस की विशाल सेना को पराजित किया था। जापान भी\r\n    साम्यवाद विरोधी था तथा रूस का शत्रु था। अतः नवम्बर 1936 ई. में बर्लिन-टोकियो धुरी का निर्माण जर्मनी जापान संधि के\r\n    द्वारा हुआ। इसमें 1937 ई. में इटली भी आ मिला। यह नयी शक्ति रोम-बर्लिन-टोकियो धुरी के नाम से विख्यात हुई।</p>\r\n<h3>7. ऑस्ट्रिया विजय </h3>\r\n<p>हिटलर ऑस्ट्रिया पर नाजी शासन का अधिकार चाहता था। उस समय ऑस्ट्रिया में शुशनिग प्रधानमंत्री था। उसे बाध्य होकर\r\n    अपना पदत्याग करना पड़ा। जर्मन की सेनाओं के आक्रमण के भय से ऑस्ट्रिया का नया प्रधानमंत्री डॉ. सेइसइन्कावर्ट नियुक्त\r\n    किया गया जो कट्टर नाजीवादी एवं हिटलर का भक्त था। ऑस्ट्रिया में जब नाजी सरकार बन गयी तो हिटलर अपने गृहस्थान गया तथा\r\n    दिवंगत माँ-बाप को श्रद्धांजलि अर्पित की। ऑस्ट्रिया पर नाजीदल के विजय ने जर्मनी की शक्ति का उल्लेखनीय विस्तार किया।\r\n</p>\r\n<h3>8. चेकोस्लोवाकिया का अन्त</h3>\r\n<p>ऑस्ट्रिया के पश्चात् हिटलर का दूसरा शिकार चेकोस्लोवाकिया था। चेकोस्लोवाकिया एक नया स्वतंत्र राज्य था तथा यूरोप में\r\n    आदर्श प्रजातंत्रीय गणतंत्र के रूप में प्रतिष्ठित था। चेकोस्लोवाकिया का एक प्रदेश सुडटेन लैण्ड था जहाँ जर्मनों की\r\n    आबादी लगभग 35 लाख थी। हिटलर का उद्देश्य यूरोप भर में फैली जर्मन जाति को एकसूत्र में एकत्रित करना था । अतः काफी लम्बी\r\n    लड़ाई और राजनीतिक दाँव-पेंच के उपरान्त म्युनिख समझौते के अनुसार सुडटेन लैण्ड से 10 दिनों के भीतर चेक लोगों को खाली\r\n    करा दिया गया तथा इस पर जर्मनी का कब्जा बिना खून-खराबा मान लिया गया।</p>\r\n<h3>9. मेमेल पर कब्जा </h3>\r\n<p>मेमेल भी सुडटेन लैण्ड की तरह जर्मनबहुल प्रान्त था जो लिथुआनिया के अधिकार में था। हिटलर के दबाव पर इस छोटे देश ने\r\n    तुरन्त आत्मसमर्पण कर दिया तथा 21 मार्च 1939 ई. को हिटलर ने मेमेल पर अधिकार कर लिया।</p>\r\n<h3>10. जर्मन-रूस समझौता </h3>\r\n<p> हिटलर की विदेश नीति की दूरदर्शिता का यह समझौता चरम बिन्दु है। रूस जर्मनी का दुश्मन था आज मित्रवत मिल रहा था। वस्तुतः\r\n    जर्मनी पोलैण्ड पर आक्रमण करना चाहता था किन्तु पोलैण्ड को इंगलैण्ड एवं फ्रांस की गारंटी मिल गयी थी। यदि जर्मनी अभी\r\n    पोलैण्ड पर आक्रमण कर देता तो मौका देखकर रूस अवश्य जर्मनी पर आक्रमण कर देता। इस प्रकार जर्मनी को पोलैण्ड एवं रूस दो\r\n    मोचौं पर युद्ध करना पड़ता। यह जर्मनी के लिए घातक हो सकता था; अतः पोलैण्ड पर युद्ध करने के पहले हिटलर रूस से सन्धि कर\r\n    लेना चाहता था। 23 अगस्त 1939 ई. को जर्मनी - रूस में एक अनाक्रामक संधि हुई जिसके अनुसार तय हुआ कि वे एक-दूसरे पर\r\n    आक्रमण नहीं करेंगे। इस संधि के अन्तर्गत गुप्त रूप से पोलैण्ड को जर्मनी एवं रूस में आपस में बाँट लेने की\r\n    भी बात तय हुई थी।</p>\r\n<h3> 11. द्वितीय विश्वयुद्ध का बीजारोपण </h3>\r\n<p>यूरोपीय देशों के अनेक प्रयासों एवं ब्रिटेन के लाख समझाने पर भी जर्मनी पोलैण्ड पर अपने इरादे से विरत नहीं हुआ और 1\r\n    सितम्बर 1939 ई. को बिना विधिवत् घोषणा किये एकदम सुबह जर्मनी की सेना ने पोलैण्ड पर आक्रमण कर दिया। तीन दिनों बाद\r\n    ब्रिटेन एवं फ्रांस पोलैण्ड की सहायता के लिए पहुँच गये।</p>\r\n<p> इस प्रकार दूसरे विश्वयुद्ध का बीजारोपण पोलैण्ड पर जर्मनी के आक्रमण से हो गया। इस प्रकार, हिटलर की इस नीति से कि जहाँ\r\n    भी नाजी विचारधारा के और जर्मन प्रजाति के लोग हैं वह जर्मनी का एक अंग है, हिटलर के आक्रामक स्वरूप का ही परिचय मिलता\r\n    है।</p>\r\n<p>वस्तुतः हिटलर ने इतनी सैन्य एवं अन्य शक्तियाँ प्रस्तुत कर ली थीं कि उसके लिए युद्ध आवश्यक हो गया था</p>',128,'2024-10-26 17:49:51','2024-10-26 18:49:03','','Publish',0,'open',33,50),('आंतरिक आलोचना से आप क्या समझते हैं? व्याख्या करें।','what-do-you-understand-by-internal-criticism',2,'<p>अलोचना का अर्थ किसी व्यक्ति वस्तु विचार या कार्य की गुण-दोष के आधार पर करना, यह एक प्रक्रिया है जिसमें किसी विषय का विश्लेषण किया जाता है उसकी अच्छाई और बुराइयों का परखा जाता है। अर्थात शोध कार्य में ऐतिहासिक स्रोत की प्राप्ति के पश्चात प्रारंभिक तैयारी की जाती है जिसका प्रथम चरण आलोचना है इसके तहत स्रोतों को उपयोग में लाने से पूर्व उनकी प्रामाणिकता एवं विश्वसनीयता की पुष्टि की जाती है <strong>आलोचना के अंतर्गत त्रुटिपूर्ण कथनों को सामने लाया जाता है तथा उनके स्थान पर साक्ष्य सहित यथार्थ प्रस्तुत किया जाता हैं।</strong></p>\r\n<p>आलोचना में विभिन्न प्रकार होते हैं जिनमें मुख्य रूप से <strong>आंतरिक आलोचना</strong> एवं <strong>वाह्य आलोचना</strong> शामिल हैं-</p>\r\n<h2>आंतरिक आलोचना</h2>\r\n<p>आंतरिक आलोचना जिसे उच्च आलोचना भी कहा जाता है यह किसी दस्तावेज़ में पाई गई जानकारी की विश्वसनीयता का परीक्षण करने की विधि है इसका उद्देश्य दस्तावेज़ की सामग्री की विश्वसनीयता स्थापित करना होता हैं।</p>\r\n<p>आंतरिक आलोचना के अंतर्गत दस्तावेज की विश्वसनीयता को जांचा जाता है दस्तावेज में दी गई जानकारी विश्वसनीय है या नहीं। क्योंकि कई बार लेखक अपने व्यक्तिगत पूर्वाग्रह, आज्ञानता या सामाजिक दबाव के कारण वास्तविकता से भटक जाता है। उदाहरण के लिए- <i>आपातकाल के दौरान कई लोगों ने डर के कारण इंदिरा गाँधी की झूठी प्रशंसा की थी।</i> इसी तरह एक विदेशी लेखक भारत के संस्कृति को जाने बिना प्रशंसा की थी कि लोग इतने अमीर है कि वे खाने के बाद अपना खाना फेंक देते हैं।</p>\r\n<p>वास्तव में आज्ञानता, पूर्वाग्रह, कपट संस्कृति अंतर जैसे विभिन्न कारणों ने लेखन में त्रुटि का योगदान दिया इसलिए इतिहासकारों को उन अभिलेखों को सावधानीपूर्वक जांच करनी होती है कि जो प्रमाणित प्रतीक होती है।</p>\r\n<p>आंतरिक आलोचना दो तरह से होता है <strong>नकारात्मक आलोचना</strong> और <strong>सकारात्मक आलोचना</strong>। </p>\r\n<h3 class=\"atech\">नकारात्मक आलोचना</h3>\r\n<p>यह जांचने के लिए होती है कि लेखन या गवाह क्या सच बोलने की स्थिति में था या नहीं। उनमें यह परखा जाता है कि क्या लेखक ने परिस्थितियों के कारण सच्चाई को छिपाया या बदल दिया। <strong>प्रोo गोटचाक</strong> के अनुसार- \"<i>ऐतिहासिक साक्ष्य की विश्वसनीयता निम्न जांचों पर निर्भर करती है।</i>\"</p>\r\n<ul>\r\n    <li><p>क्या प्रधान गवाह सत्य बोलने का योग था।</p></li>\r\n    <li><p>क्या वह सत्य बोलने की इच्छा रखता था। </p></li>\r\n    <li><p>क्या घटना के बारे में सही ढंग से सूचित किया गया था।</p></li>\r\n    <li><p>क्या कोई स्वतंत्र साक्ष्य है जिससे प्रधान गवाह के बयान की जांच की जा सके?</p></li>\r\n    <li><p>इसके आधार पर ही ऐतिहासिक साक्ष्य की विश्वसनीयता की जांच की जा सकती हैं।</p></li>\r\n</ul>\r\n<h3 class=\"atech\">सकारात्मक आलोचना</h3>\r\n<p>सकारात्मक आलोचना यह पता लगाने के लिए किया जाता है कि जो लिखा गया है वह सच है या नहीं। यह क्या उसने सच कहा है कई बार सच बोलने से रोकने वाली परिस्थितियां सामने आती है जैसे- </p>\r\n<ul>\r\n    <li><p>संभवत: सभी लोग सच बोलने के आदी नहीं होते। </p></li>\r\n    <li><p>सत्य को पता लगाने में क्षमता का अभाव।</p></li>\r\n    <li><p>सत्य तक पहुंचने की क्षमता जो स्थान और समय पर निर्भर करती है। </p></li>\r\n    <li><p>पक्षों का गवाह लेखन के पक्ष में हो सकता हैं।</p></li>\r\n</ul>\r\n<p>एक इतिहासकार को यह देखना होता है कि लेखक या रिपोर्टर ने क्या घटना का विवरण तत्काल लिखा था या कुछ समय बाद। अगर वह विवरण तुरंत लिखा है तो, वह अधिक विश्वसनीय माना जा सकता है इसके अलावा यह भी परखा जाता है कि लेखक ने किसी तरह की डर, लालच, प्रेरणा या अन्य दवाव के तहत तो नहीं लिखा है <strong>प्रोफेसर हॉकेट</strong> का कथन है- \"<i>सभी चश्मदीद गवाह उत्तम पर्यवेक्षक नहीं होते</i>\" अतः विश्वासनीयता साक्ष्य कई कारकों पर निर्भर करता है जिसमें गवाह की योग्यता और इच्छा शामिल हैं।</p>\r\n<p>इसलिए आंतरिक आलोचना का मुख्य उद्देश्य दस्तावेज की विश्वसनीयता और सच्चाई को जांच करना है यह प्रक्रिया इतिहासकारों के लिए महत्वपूर्ण होती है ताकि वे प्रामाणिक तत्वों पर आधारित सटीक इतिहास प्रस्तुत कर सकें।</p>\r\n<h2>निष्कर्ष </h2>\r\n<p>इस प्रकार ऐतिहासिक स्रोतों को प्रयोग में लाने से पूर्व उपरोक्त आधारों पर उनकी प्रामाणिकता को सिद्ध किया जाना चाहिए। प्रायः देखा गया है कि यद्यपि सैद्वान्तिक रूप से आलोचना सिद्धांत का समर्थन किया जाता है किंतु व्यवहार में इनका पालन नहीं किया जाता है।</p><p>',72,'2024-10-31 06:47:55','2024-10-31 08:34:10','','Publish',0,'open',0,51),('ऐतिहासिक शोध में शोध विषय का चयन करने के लिए शोधार्थी को किन बातो को प्राथमिकता देनी चाहिए।','what-should-be-given-priority-while-selecting-a-research-topic',2,'\r\n    <p>ऐतिहासिक शोध में विषय का चयन अत्यंत महत्वपूर्ण और सावधानीपूर्वक किया जाने वाला कदम है, जो शोध की दिशा, गुणवत्ता और उनके प्रभाव को निर्धारित करता है शोधार्थी को ऐसे विषय का चयन करना चाहिए जो उसकी रुचि, ज्ञान और उपलब्धता संसाधनों के आधार पर उपयुक्त हो। शोध कार्य ज्ञान-क्षितिज के विस्तार के लिए किसी विशेष क्षेत्र में किया जाता है।</p>\r\n    <p>भारत में शोध कार्य प्रायः स्नाकोत्तर के बाद आरंभ किया जाता है अपितु कुछ विश्वविद्यालय में स्नातकों को M.A की उपाधि के लिए वैकल्पिक विषय के रूप में शोध प्रबंध लिखने की अनुमति दी जाती है शोधकार्य अनेक कारणों से किया जाता है इसके द्वारा PHD की उपाधि प्राप्त की जाती है। शोध महज उपाधि प्राप्त करने के लिए भी की जाती है जिससे व्यक्ति के प्रतिष्ठा में वृद्धि होती है या फिर स्नातकोट के बाद जब कोई विद्यार्थी किसी नौकरी में नहीं लग पाता है तो वह शोध कार्य में जुड़ जाता है इससे उसे कुछ आर्थिक सहायता मिल जाती है।</p>\r\n    <p>शोधार्थी को शोध विषय का चयन करने के लिए निम्नलिखित बातों को प्राथमिकता देनी चाहिए-</p>\r\n    <h2>रुचि और विशेषज्ञता</h2>\r\n    <p>शोधार्थी जब शोध कार्य का निश्चय कर लेता है तब पहला प्रश्न उसके सामने विषय चयन का उठना है, इस कार्य के लिए प्राय: शोधार्थी अपने मार्गदर्शन या प्रधानाध्यापक का दरवाजा खटखटाता है। यह बुरी नहीं है लेकिन पूर्णत: मार्गदर्शक पर आश्रित होना भी ठीक नहीं है शोधार्थी को स्वयं अपने शोध प्रबंध का विषय चुनना चाहिए।</p>\r\n    <p>शोधार्थी को जिस विषय में रुचि और लगन है वह विषय चयन करना चाहिए जिससे शोध की गुणवत्ता को बढ़ाया जा सके उदाहरण के लिए यदि किस शोधार्थी को प्राचीन भारतीय संस्कृति में रुचि है तो उसे इससे जुड़ी विषय का चयन करना चाहिए ताकि वह अपने ज्ञान और उत्साह का सही उपयोग कर सकें।</p>\r\n    <h2>प्राथमिक स्रोतों की उपलब्धता</h2>\r\n    <p>जब विषय का चयन कर लिया जाता है तब शोधार्थी के सामने प्रश्न विषय-सामग्री का उठता है उसे इसकी पूरी जानकारी होनी चाहिए की विषय-सामग्री जैसे पुरातात्विक साक्ष्य, पांडुलिपियाँ, शिलालेख एवं पुराने दस्तावेज आदि कहां-कहां मिलेगी। साथ ही इस बात को ध्यान रखना चाहिए यदि विषय के लिए आवश्यक स्रोत उपलब्ध नहीं होते है, तो शोधकार्य में कठिनाइयां आ सकती है और निष्कर्ष तक पहुंचना कठिन हो सकता है।</p>\r\n    <p>इस प्रकार शोधार्थी को विषय का चयन करते समय यह ध्यान रखना चाहिए कि उसके लिए पर्याप्त स्रोत और संदर्भ सामग्री मौजूद है, दूसरे शब्दों में विषय संतुलित होना चाहिए।</p>\r\n    <h2>शोध कार्य विषय भाषा का ज्ञान</h2>\r\n    <p>शोधार्थी को अपने शोध विषय की भाषा की ज्ञान या जानकारी आवश्यक होना चाहिए। कभी-कभी एक से अधिक भाषाओं की जानकारी भी आवश्यक हो जाती है उदाहरण के लिए अगर शोधार्थी उपनिवेशवाद पर शोध कर रहा है तो उसे अंग्रेजी के अतिरिक्त फ्रेंच, जर्मनी, स्पेन, पुर्तगाली आदि भाषाओं का भी जानकारी होनी चाहिए।</p>\r\n    <h2>विषय की आसाधारणता और नवीनता</h2>\r\n    <p>ऐतिहासिक शोध में असाधारणता और आद्वितीय विषय चुनना शोधार्थी को अन्य शोधकार्यो से अलग बनाता है। जिन विषय पर कम शोध हुआ है वह अनुसंधान में नए दृष्टिकोण और आयाम जोड़ जा सकते हैं उदाहरण स्वरूप प्राचीन भारत में व्यापार मार्गों पर कम शोध हुआ है तो इस विषय पर शोध करना, उसे समय की आर्थिक संरचना तथा अंतरराष्ट्रीय संसाधनों पर नए दृष्टिकोण प्रदान कर सकते हैं।</p>\r\n    <p>शोधार्थी अपने विषय चयन में विभिन्न ऐतिहासिक पत्रिकाओं में प्रकाशित पुस्तकों के पूर्ण परीक्षण और निबंधों की संदर्भ सूची से भी सहायता ले सकता है।</p>\r\n    <h2>निष्कर्ष</h2>\r\n    <p>इस प्रकार उपयुक्त अध्ययनों से हम पाते हैं की ऐतिहासिक शोध विषय चयन करते समय उपरोक्त सभी बिंदुओं पर ध्यान देना अत्यंत आवश्यक है। एक उपयुक्त विषय का चयन न केवल शोध को दिशा देता है बल्कि शोधार्थी को अतीत की घटनाओं का वस्तुनिष्ठ अध्ययन करने में मदद करता है सही विषय का चयन कर शोधार्थी न केवल अतीत के  तथ्यात्मक अध्ययन को बढ़ावा देता है, बल्कि वर्तमान समाज को भी इसके माध्यम से लाभान्वित कर सकता है।</p>\r\n',22,'2024-11-29 13:58:54','2024-11-29 14:05:56','','Publish',0,'open',0,52),('प्राथमिक ऐतिहासिक स्रोत क्या है?','primary-historical-sources',2,'<p>एक इतिहासकार ऐतिहासिक स्रोत की सहायता से अतीत को वर्तमान के सामने लाता है यानी इतिहासकार ऐतिहासिक स्रोत का उपयोग कर अतीत के घटनाओं, संस्कृतियों, समाजों को समझने और उनके बारे में जानकारी प्राप्त करने के लिए करते हैं। ऐतिहासिक स्रोत को मुख्यतः दो भागों में बांटा जा सकता है प्रधान (प्राथमिक) स्रोत या गौण (द्वितीय) स्त्रोत।</p>\r\n<p>प्रधान या प्राथमिक स्रोत में चश्मदीत गवाह के साक्ष्य, मौलिक दस्तावेज, साहित्य और ग्रंथ, पुरातात्विक स्रोत आदि आते हैं, इतिहासकार बिखरे हुए प्रधान स्रोतों को इकट्ठा कर उन्हें गौण स्रोत बना देते हैं जैसे इतिहास की किताब ,शोध पत्र और लेख जीवन और आत्मकथाएं। इस विषय में प्रोफेसर मार्विक ने लिखा है- <i>\"प्रधान स्रोत अप्रकाशित स्रोत है जो कुछ कुशल इतिहासकार के लिए अधिक महत्वपूर्ण है। जैसे- गौण साधन, प्रकाशित पुस्तक, निबंध आदि।\"</i></p>\r\n<p>प्रधान स्रोत के अंतर्गत प्रयाग पांडुलिपि या हस्तलिखित प्रति जो एक ही प्रति में उपलब्ध है प्रधान स्रोत माने जाते हैं। इसका मुख्य कारण यह है कि लिखने वाला या तो समय घटना से संबंधित होता है या घटना का दर्शक होता है। किंतु इस विषय में प्रोफेसर मार्मिक इस विचार को सहमत नहीं है उनका कहना है कि मुद्रित दस्तावेज, पांडुलिपियों से अधिक विश्वसनीय और महत्वपूर्ण है, यह संभव है की पांडुलिपि किसी लेखक के दिमागी उपज हो।</p>\r\n<p>प्रधान स्रोत में निम्नलिखित प्रमुख हैं। </p>\r\n<h2>समकालीन अभिलेख</h2>\r\n<p>इस विषय में प्रोफेसर गोटचाक कहते हैं कि <i>\"हमें समकालीन अभिलेख जो अत्यंत महत्वपूर्ण है जैसे- किसी राजदुत द्वारा भेजे हुए आदेश या ऐसे दस्ताज में छल कपट या भूल की कम संभावना रहती है।\"</i> फिर भी यह आवश्यक है कि उनके विषय वस्तु को मानने से पहले सत्यता की जांच कर ली जाए। व्यापार और विधि जगत संबंधित कागजात जैसे हुण्डी, विधेयक, पत्रिकाएँ, आदेश, रेहन, कर, अभिलेख आदि, भी प्राथमिक स्रोत के अंतर्गत आते हैं क्योंकि इनमें भी कोई भूल नहीं हो सकती इतिहासकार इसका उपयोग कर द्वितीयक स्रोत का निर्माण कर सकता है।</p>\r\n<p>प्राय ऐसे व्यापार या कानूनिक कागजात महत्वपूर्ण इसलिए है क्योंकि इसको तैयार करने वाली योग और विशेषज्ञ होते हैं इसी तरह प्रख्यात व्यक्ति अपने उपयोग के लिए नोटबुक, स्मरण-पत्र आदि रखते हैं इतिहास के लिए यह अत्यंत उपयोगी है।</p>\r\n<h2>पुरातात्विक अवशेष</h2>\r\n<p>पुरातात्विक अवशेष, मकान के खंडहर होने पर उसके अवशेष मिलते हैं जैसे मोहनजोदड़ो में स्नानागार, मर्तियां, चित्रकला। जो प्राथमिक श्रोत के अंतर्गत आते हैं इनकी परीक्षण करने से हमें उसे समय की आर्थिक राजनीतिक एवं सामाजिक घटनाओं के बारे में जानकारी मिलती है। यह प्राय प्राथमिक स्रोत के अंतर्गत आते हैं क्योंकि इनमें बदलाव नहीं हो सकता।</p>\r\n<h2>सार्वजनिक प्रतिवेदन या प्रकाशित सामग्री</h2>\r\n<p>यह कम विश्वसनीय होते हैं लेकिन इन्होंने भी प्राथमिक स्रोत के अंतर्गत रखा जाता है जैसे- पुस्तक व पत्रिका और जनरल लेख, समाचार पत्र आदि इस विषय में एक इतिहासकार लिखते हैं- <i>\"19वीं शताब्दी तक विशेष संवाददाताओं की नियुक्ति का प्रचलन नहीं था और समाचार पत्र एक दूसरे की नकल करते थे\"</i>, हालांकि आजकल तो समाचार पत्रों की सहायता समाचार पत्र एजेंसी, डेडीकेट और संवाददाता हैं।</p>\r\n<h2>सरकारी दस्तावेज</h2>\r\n<p>अनेक सरकारी दस्तावेज संकलित किए जाते हैं जो इतिहासकार के लिए महत्वपूर्ण होते हैं उदाहरण स्वरूप सरकारी रिपोर्ट, जनगणना आदि यह स्रोत से भी हमें जानकारी प्राप्त होती है यह प्राय प्राथमिक स्रोत के अंतर्गत आते हैं परंतु कुछ ऐसे भी सरकारी दस्तावेज होते हैं जिन्हें प्राथमिक स्रोत के अंतर्गत नहीं लिया जा सकता उदाहरण स्वरूप- <i>\"अमेरिकी कांग्रेस के संभाषण अभिलेख में उन भाषाओं को भी दर्ज किया जाता है जो सदस्य द्वारा बोले नहीं गए द्वितीय प्रकासन के पूर्व भाषणो को भि दर्ज किया जाता है।\"</i></p>\r\n<h2>साहित्य </h2>\r\n<p>साहित्य भी एक महत्वपूर्ण ऐतिहासिक स्रोत है साहित्य से इतिहासकार को स्थानीय दशाओं, सामाजिक रीति रिवाज आदि की जानकारी प्राप्त होता है क्योंकि साहित्य समाज का दर्पण होता है। चार्ल्स डिकेंस ने 19वीं शताब्दी के इंग्लैंड सामाजिक जीवन का चित्रण किया है। अधिकांश इतिहासकार उनके चरित्र को ऐतिहासिक साधन मानते हैं। फिर भी मार्विक का कहना है कि- <i>\"इतिहासकार को समकालीन साहित्य पर ही आश्रित नहीं होना चाहिए उसे सरकारी कागजात को भी सहायता लेनी चाहिए जिनमें रहन-सहन का स्तर, मजदूर की दरों, अनाज की कीमतें आदि उल्लेखनीय रहता हैं।\"</i></p>\r\n<h2>निष्कर्ष</h2>\r\n<p>प्राथमिक श्रोत इतिहास, संस्कृति, और समाज को समझने के लिए एक मजबूत आधार प्रदान करते हैं। ये अतीत की घटनाओं को सटीकता और प्रामाणिकता के साथ जानने में मदद करते हैं। हालांकि, इनका उपयोग करते समय आलोचनात्मक दृष्टिकोण अपनाना आवश्यक होता है ताकि किसी प्रकार की त्रुटि या अधूरी जानकारी के कारण गलत निष्कर्ष न निकले।</p>\r\n',8,'2024-11-30 06:06:25','2024-11-30 07:50:43','','Publish',0,'open',0,53),('ऐतिहासिक शोध में तथ्यों का समन्वीकरण कैसे किया जाता है इसके महत्व पर प्रकाश डालें।','coordination-of-facts-in-historical-research',2,'<p>ऐतिहासिक शोध में तथ्यों का समन्वीकरण एक महत्वपूर्ण प्रक्रिया है, दरअसल आंतरिक एवं बाह्य आलोचना के बाद तथ्यों का समन्वीकरण करना आवश्यक होता है। इसमें इतिहासकार विभिन्न स्रोतों तथ्यों का संग्रह और विश्लेषण करते हैं। जिसमें घटनाओं की स्पष्टता, निरंतरता और कालक्रम स्थापित होता है। इतिहासकार को समस्त उपलब्ध सामग्रियों का उपयोग इस ढंग से करने की जिम्मेदारी होती है की ऐतिहासिक तत्व प्रकाश में आ सके।</p>\r\n    <p>प्रसिद्ध इतिहासकार मार्विक ने समन्वीकरण के संबंध में लिखते हैं- <i>\"समाग्री इकट्ठा करने के बाद इतिहासकार का काम इतिहास लेखन का है यह काम ठीक उसी तरह है जिस तरह इंस्पेक्टर जनरल अपने दौर का रिपोर्ट लिखाने, राजदूत की तरह अपनी सरकार को सूचना भेजने।\"</i> एक इतिहासकार से यह आशा की जाती है कि अलग-अलग तथ्यों की वैधता का परीक्षण करें और तब उसे प्रस्तुत करें। इसलिए इतिहासकार किसी भी कठोर कानून का अनुसरण करने के लिए बांध हुआ नहीं होता है।</p>\r\n    <p>तथ्यों का समन्वीकरण निम्नलिखित चरणों में किया जा सकता हैं-</p>\r\n    <h2>सामग्री का चयन और मूल्यांकन</h2>\r\n    <p>ऐतिहासिक तथ्यों को समझने के लिए सबसे पहले प्राथमिक और द्वितीयक स्रोत का चयन किया जाता है एवं स्रोतों का मूल्यांकन करते समय यह देखा जाता है कि वह कितना प्रमाणित है जैसे कि यदि किसी दस्तावेज़ में कोई घटनाओं का विवरण है तो वह देखा जाता है कि समय और स्थिति क्या थी, लिखने वाला व्यक्ति का क्या उद्देश्य था और क्या उनमें कोई पूर्वाग्रह हो सकता हैं।</p>\r\n    <p>उदाहरण के लिए प्राचीन शासको ने अभिलेख और ताम्रपत्र अक्सर शासन के महनता को बढ़-चढ़कर लिखते थे। इसलिए इतिहासकार का कर्तव्य है इन स्रोतों के विश्वसनीयता पर विशेष ध्यान दें। प्रोफेसर लैगलोई और साइनोब ने लिखा हैं- <i>\"यदि इतिहास के तथ्यों के ढेर में खो नहीं जाना है तो अन्य विज्ञानों की तरह उसे प्रश्नोतर की प्रक्रिया में लिखना चाहिए।\"</i></p>\r\n    <h2>घटनाओं का कार्यक्रम और स्थान निर्धारण</h2>\r\n    <p>ऐतिहासिक तथ्यों को समझने के लिए घटनाओं को सही क्रम में रखना आवश्यक है कार्यक्रम मे घटनाओं को सही स्थान देने से उनके बीच के कारण और प्रभाव का संबंध समझा समझना आसान हो जाता है यह भी देखा जाता है कि कौन सी घटना कहां घाटी। गार्डिनर ने अपना \'17वी शताब्दी का इतिहास\' बिल्कुल इसी आधार पर लिखा है किंतु मौकाले, बार्जुन और ग्राफ ने इस पद्धति को पसंद नहीं करते हैं। अपितु उदाहरण के लिए विभिन्न युद्धों के कारणों को समझने के लिए घटनाओं का कार्यक्रम और स्थान एक बड़ी भूमिका निभाती है।</p>\r\n    <h2>तत्वों का तुलनात्मक अध्ययन</h2>\r\n    <p>विभिन्न स्रोतों से प्राप्त तत्वों की तुलना कर यह देखा जाता है कि वह एक दूसरे से पूरक है या विरोधाभाषी। यदि कोई तथ्य विरोधाभाषा मिलता है तो उसकी गहन विश्लेषण करना चाहिए तथा उसकी सटीकता को सामने लाना चाहिए यह एक इतिहासकार का कर्तव्य है। उदाहरण के लिए यदि दो दस्तावेज किसी राजा के विजय के बारे में विरोधाभाषी विवरण देते हैं तो अन्य स्रोतों के आधार पर निष्कर्ष निकाला जा सकता हैं।</p>\r\n    <h2>तर्क </h2>\r\n    <p>तर्क इतिहास के समन्वीकरण में काफी महत्व रखता है इतिहासकारों को इतिहास की रचना करते समय कुछ ऐसे भी समस्याओं का सामना करना पड़ता है जिसका समाधान जुटाई गई सामग्री से न हो पता है। अतः ऐसे जगह पर तर्क की सहायता लेनी पड़ती है। तर्क दो प्रकार के होते हैं स्वीकारात्मक और निषेधात्मक।</p>\r\n    <p>दस्तावेज में किसी तथ्य के अभाव में निषेधात्मक तर्क की सहायता ली जाती है दूसरे शब्दों में यदि किसी भी दस्तावेज में किसी विशेष तथ्य का अभाव है तो यह अनुमान लगाया जाता है कि ऐसा कोई तथ्य नहीं था यदि ऐसा कोई तथ्य होता तो किसी दस्तावेज़ में इसका उल्लेख किया जाता। किंतु इस तरह का निषेधात्मक तर्क उचित नहीं है। जब वर्तमान अतीत की व्याख्या अनुमान के तौर पर किया जाता है तो उसे स्वीकारात्मक तर्क कहते है।</p>\r\n    <h2>समन्वीकरण का महत्व</h2>\r\n    <p>समन्वीकरण इतिहास लेखन में सजीव की भूमिका निभाती है। तथ्यों के समन्वीकरण का महत्व ऐतिहासिक शोध और विश्लेषण में अत्यधिक महत्वपूर्ण है, क्योंकि यह घटनाओं के बीच संबंधों को स्पष्ट करने, कारण प्रभाव का अध्ययन करने और यथार्थत को उजागर करने में सहायक होता है। दरअसल तथ्यों का समूह बनाना अपने आप में एक कठिन कार्य होता है यह ऐतिहासिक तथ्य अनेक प्रकार के होते हैं।</p>\r\n    <p>प्राय: इतिहासकारों को अपने-अपने शैली में तथ्यों को लिखते हैं किंतु इतिहासकार जिस भी शैली अपनाए, एक सामान्य सिद्धांत यह है कि यह पढ़ने योग हो। किंतु कुछ इतिहासकार, विद्वानो के लिए लिखते हैं सामान्य पाठक ना तो उनकी भाषा समझ सकते हैं और यह भी नहीं समझ पाते की इतिहासकार क्या कहना चाहता है। प्रोफेसर इल्टन ने लिखा है- <i>\"इतिहासकार केवल कुछ ही लोगों के लिए न लिखें, घटिया लोकप्रिय इतिहास के स्थान पर उत्तम लोकप्रिय इतिहास की रचना करनी चाहिए।\"</i></p>\r\n    <h2>निष्कर्ष</h2>\r\n    <p>इस प्रकार उपरोक्त अध्ययनों से हम इस निष्कर्ष पर पहुंचते हैं कि इतिहासकारों द्वारा तथ्यों का समन्वीकरण काफी महत्वपूर्ण है। सबसे पहले तत्वों की प्रामाणिकता और विश्वसनीयता का आकलन किया जाता है इसके अंतर्गत तथ्यों का मूल्यांकन, उसकी आकस्मिक, आवश्यकता एवं तर्क के आधार पर उसका संश्लेषण किया जाता है ऐतिहासिक शोध में तथ्यों का समन्वीकरण न केवल इतिहास के तथ्यात्मक ज्ञान को संरक्षित करता है बल्कि समाज को अतीत के अनुभवो से सीखने और भविष्य में उन्हें सुधारने का अवसर भी प्रदान करता है।</p>\r\n',11,'2024-11-30 07:54:37','2024-11-30 09:13:21','','Publish',0,'open',0,54),('परिकल्पना के प्रकार और अनुसंधान','hypothesis',2,'<p>परिकल्पना का शाब्दिक अर्थ है पूर्व विचार या पूर्व सिद्धांत। यह एक ऐसा विचार है जिसके आधार पर शोधकर्ता अपने शोध के अध्धयन के लक्ष्य को तय करता है तथा उसकी जाँच करता है। शोध के निष्कर्ष में परिकल्पना को सत्य सिद्ध होने पर एक सिद्धांत के रूप में लागु करता है।</p>\r\n    <p>वास्तविक अध्ययन आरम्भ करने के पहले शोधकर्ता अनुमान लगाता है कि अध्ययन के बाद किस तरह का परिणाम मिलेगा। साधारण अर्थ में इसी अनुमान को परिकल्पना कहते हैं। जैसे-मान लें कि एक शोधकर्ता अपने अध्ययन में रूढ़िवाद पर शैक्षिक स्तर का प्रभाव देखना चाहता है। वास्तविक अध्ययन करने के पूर्व वह अनुमान लगा सकता है कि कम शिक्षित लोगों की अपेक्षा अधिक शिक्षित लोगों में रूढ़िवादिता कम पायी जायेगी। यही अनुमानित कथन परिकल्पना कहलायेगी।</p>\r\n    <p>कई विद्वानों ने परिकल्पना की अलग-अलग परिभाषाएँ दी हैं। करलिंगर के अनुसार- <i>\"परिकल्पना दो या दो से अधिक चरों के बीच सम्बन्ध का अनुमानात्मक कथन है।\"</i></p>\r\n    <p>कारणों की व्याख्या में परिकल्पना सहायक होती है, क्योंकि कल्पना के अभाव में कारणों की क्रमबद्धता कठिन है।\' इसी सत्य को ध्यान में \'रखकर क्रोचे तथा कालिंगवुड ने कहा है कि \"<i>कल्पना ऐतिहासिक ज्ञान का मूल स्रोत है। इसी को भारतीय दर्शन में अनुमान कहा गया है।</i>\" मोमसेन तथा माइकेल ने भी अनुमान के महत्त्व को स्वीकार किया है।</p>\r\n    <p>इतिहास में अनुमान भी लगाया जाता है। रीतिवादी इतिहासकार किसी रेखाङ्कन के आधार पर घटना का अनुमान कर लेते हैं। वे इस तथ्य को भूल जाते हैं कि इतिहास पूर्णरूप से काल्पनिक नहीं, अपितु साक्ष्यों पर आधृत है। जैसे कहीं खण्डहर देखकर अनुमान किया जाता है कि यहाँ कभी एक विशाल नगर रहा होगा। किन्तु अनुमान कभी काल्पनिक भी हो सकता है</p>\r\n    <h2>परिकल्पना के प्रकार</h2>\r\n    <h3 class=\"atech\">सार्वजनीन परिकल्पना</h3>\r\n    <p>सार्वजनीन परिकल्पना वह परिकल्पना है जिसमें ऐसे सम्बन्ध का उल्लेख किया जाता है जो सभी चरों के लिए, सभी स्थान तथा सभी समय पर लागू होता है। जैसे- न्यूटन द्वारा बनायी गयी गुरुत्व परिकल्पना वास्तव में सार्वजनीन परिकल्पना का उदाहरण है।</p>\r\n    <p>ऐसी परिकल्पना का महत्त्व भौतिक विज्ञानों में अधिक है। सामाजिक विज्ञानों या व्यवहारपरक विज्ञानों में इस परिकल्पना का महत्व अपेक्षाकृत कम है। कारण, इस परिकल्पना के लिए नियंत्रित परिस्थिति का होना आवश्यक है जो केवल भौतिक विज्ञानों में ही सम्भव है। फिर भी मनोविज्ञान में भी सीमित मात्रा में सार्वजनीन परिकल्पना का उल्लेख मिलता है। \"थकान से उत्पादन घटता है।\" यह परिकल्पना सभी समय तथा स्थान के लिए सत्य है। </p>\r\n    <p>सार्वजनीन परिकल्पना की तीन विशेषताएँ हैं- </p>\r\n    <ul>\r\n    <li><p>इसमें वैज्ञानिकता अधिक पायी जाती है। इसीलिए, इसे कभी-कभी वैज्ञानिक परिकल्पना भी कहते हैं। </p></li>\r\n    <li><p>इसमें भविष्यवाणी मूल्य अधिक होता है। </p></li>\r\n    <li><p>इस प्रकार की परिकल्पना अधिक व्यापक तथा विस्तृत होती है।</p></li>\r\n    </ul>\r\n    <h3 class=\"atech\">अस्तित्वपरक परिकल्पना </h3>\r\n    <p>अस्तित्वपरक परिकल्पना वह परिकल्पना है, जिसमें कम से कम एक चीज का उल्लेख किया जाता है, जिसकी एक निश्चित विशेषता होती है। इस परिकल्पना में किसी एक ही इकाई का गहन अध्ययन किया जाता है और कोई निश्चित परिणाम प्राप्त किया जाता है। मनोविज्ञान में इंस प्रकार की परिकल्पना का महत्व देखा जाता है। इस परिकल्पना पर आधारित अध्ययन स्थानीय तथा व्यक्तिगत होता है। जैसे एबिंगहाँस ने स्वयं अपने ऊपर प्रयोग किया और स्मरण तथा विस्मरण के स्वरूप के माबन्ध में कई निश्चित परिणाम प्राप्त किये। अतः उनके द्वारा बनायी गयी परिकल्पना को अस्तित्वपाक परिकल्पना कहेंगे।</p>\r\n    <p>अस्तित्वपरक परिकल्पना की कई विशेषताएँ हैं- </p>\r\n    <ul>\r\n    <li><p>इस तरह की परिकल्पना का क्षेत्र सीमित होता है। </p></li>\r\n    <li><p>यह परिकल्पना मभी कान्ना तथा सभी समयों पर लागू नहीं होती है। </p></li>\r\n    <li><p>इस परिकल्पना में पूर्ण वैज्ञानिकता नहीं पायी जानी है।</p></li>\r\n    </ul>\r\n    <h3 class=\"atech\">सीमित परिकल्पना</h3> \r\n    <p>सीमित परिकल्पना वह परिकल्पना है जो प्रत्यक्ष कथन के रूप में होती है और सदा प्रमाणीय होती है। यह परिकल्पना वास्तव में निगमन पर आधारित होती है। इस तरह की परिकल्पना का क्षेत्र सीमित होता है और यह अल्पव्यापी होती है। ऐसी परिकल्पना सामाजिक विज्ञानों में अधिक महत्त्व रखती है।</p>\r\n    <h2>निष्कर्ष</h2>\r\n    <p>इसप्रकार परिकल्पना अनुसंधान की दिशा निर्धारित करने का एक महत्वपूर्ण उपकरण है। यह समस्या के समाधान की ओर पहला कदम होता है और शोध प्रक्रिया को वैज्ञानिक, व्यवस्थित और तार्किक बनाता है। इसका निर्माण, परीक्षण, और सत्यापन अनुसंधान की सफलता सुनिश्चित करने में सहायक होते हैं। परिकल्पना सही साबित हो या गलत, दोनों ही स्थितियों में यह ज्ञान और समझ में वृद्धि करती है।</p>\r\n',43,'2024-11-30 07:54:37','2024-11-30 14:47:32','','Publish',0,'open',0,55),('इतिहास में वस्तुनिष्ठता','objectivity-in-history',2,'\r\n<p>इतिहास, मानव सभ्यता के अतीत की घटनाओं का व्यवस्थित अध्ययन है। यह न केवल घटनाओं को दस्तावेज़ के रूप में दर्ज करता है, बल्कि उनके कारणों, परिणामों, और प्रभावों को समझने का प्रयास भी करता है। इतिहास का लेखन केवल तथ्यों का संग्रह नहीं है, बल्कि यह उन तथ्यों की व्याख्या और विश्लेषण का कार्य है। इस व्याख्या और विश्लेषण में वस्तुनिष्ठता (Objectivity) और शोध संरचना (Research Framework) का विशेष महत्व है।</p>\r\n<h2>वस्तुनिष्ठता की परिभाषा और आवश्यकता</h2>\r\n<p>स्तुनिष्ठता का अर्थ है बिना किसी पक्षपात, व्यक्तिगत विचार, या पूर्वाग्रह के ऐतिहासिक तथ्यों का प्रस्तुतीकरण। जब इतिहासकार अतीत की घटनाओं का अध्ययन करते हैं, तो उनका उद्देश्य होता है कि वे उन घटनाओं को जितना संभव हो सके, सटीकता और तटस्थता के साथ प्रस्तुत करें। यह महत्वपूर्ण है क्योंकि इतिहास समाज को उसकी जड़ों से जोड़ता है और उसकी पहचान को परिभाषित करता है।</p>\r\n<p>वस्तुनिष्ठता के बिना, इतिहास केवल एक दृष्टिकोण या मत बन सकता है। उदाहरण के लिए, विजेताओं द्वारा लिखे गए इतिहास में पराजित समाजों के योगदान और दृष्टिकोण अक्सर अनदेखे रह जाते हैं। मध्यकालीन भारत के कई इतिहासकारों ने मुस्लिम शासकों के अधीन भारत के इतिहास को प्रमुखता दी, जबकि स्थानीय राजाओं और उनके योगदानों को दरकिनार कर दिया। <strong>बूततेरफील्ड</strong> ने लिखा है- <i>\"वस्तुनिष्ठता इतिहास की वाणी हैं।\"</i></p>\r\n<h2>वस्तुनिष्ठता के तत्व</h2>\r\n<h3 class=\"atech\">स्रोतों का चयन</h3>\r\n<p>वस्तुनिष्ठता को बनाए रखने के लिए विभिन्न स्रोतों का चयन करना आवश्यक है। इससे एक व्यापक दृष्टिकोण प्राप्त होता है। स्रोतों में प्राथमिक और द्वितीयक दोनों प्रकार के दस्तावेज़ शामिल होते हैं, जैसे सरकारी दस्तावेज़, पत्र, जीवित व्यक्तियों की गवाही, और ऐतिहासिक पुस्तकें।</p>\r\n<h3 class=\"atech\">तथ्यों का विश्लेषण</h3>\r\n<p>तथ्यों का विश्लेषण करते समय, इतिहासकारों को यह सुनिश्चित करना चाहिए कि वे अपने व्यक्तिगत विचारों को निष्क्रिय करें। तथ्यों को संदर्भित करते हुए, उन्हें उन स्थितियों, सामाजिक-आर्थिक परिस्थितियों, और राजनीतिक परिवर्तनों पर विचार करना चाहिए जो उन घटनाओं को प्रभावित कर सकते हैं।</p>\r\n<h3 class=\"atech\">पूर्वाग्रहों से बचना</h3>\r\n<p>इतिहासकारों को अपने व्यक्तिगत पूर्वाग्रहों को पहचानना और उन पर काबू पाना चाहिए। यह महत्वपूर्ण है कि वे अपने दृष्टिकोण को तथ्यों के अनुरूप रखकर निष्पक्षता बनाए रखें।</p>\r\n<h3 class=\"atech\">समय और संदर्भ</h3>\r\n<p>इतिहास में वस्तुनिष्ठता को बनाए रखने के लिए, समय और संदर्भ का ध्यान रखना आवश्यक है। ऐतिहासिक घटनाओं की व्याख्या करते समय, इतिहासकारों को यह समझना चाहिए कि घटनाएँ किस सामाजिक, राजनीतिक, और आर्थिक संदर्भ में घटित हुईं।</p>\r\n\r\n<h2>वस्तुनिष्ठता का महत्व</h2>\r\n<h3 class=\"atech\">सत्यता</h3>\r\n<p>वस्तुनिष्ठता सुनिश्चित करती है कि प्रस्तुत किए गए तथ्यों और आंकड़ों में सच्चाई हो। जब ऐतिहासिक घटनाओं या अनुसंधान परिणामों का विश्लेषण वस्तुनिष्ठता के आधार पर किया जाता है, तो वे अधिक विश्वसनीय होते हैं। यह पाठकों और शोधकर्ताओं को सही जानकारी प्राप्त करने में मदद करता है।</p>\r\n<h3 class=\"atech\">निष्पक्षता</h3>\r\n<p>वस्तुनिष्ठ दृष्टिकोण से लेखक की व्यक्तिगत राय या पूर्वाग्रह को हटा दिया जाता है। इससे पाठकों को तथ्यों के आधार पर स्वतंत्र रूप से विचार करने और निर्णय लेने का अवसर मिलता है। निष्पक्षता से एक स्वस्थ संवाद और बहस की संभावना बढ़ती है।</p>\r\n<h3 class=\"atech\">समाज में जागरूकता</h3>\r\n<p>वस्तुनिष्ठता के माध्यम से समाज को ऐतिहासिक तथ्यों और घटनाओं के बारे में सही जानकारी मिलती है। इससे समाज में जागरूकता बढ़ती है और गलतफहमियाँ कम होती हैं। जब लोग सही और निष्पक्ष जानकारी प्राप्त करते हैं, तो यह सामाजिक समरसता और एकता को बढ़ावा देता है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>इतिहास का उद्देश्य न केवल अतीत को समझना है, बल्कि वर्तमान और भविष्य के लिए सबक लेना भी है। वस्तुनिष्ठता और शोध संरचना, इतिहास को विश्वसनीय और प्रासंगिक बनाने के महत्वपूर्ण स्तंभ हैं। इनके बिना, इतिहास केवल मतों और धारणाओं का संग्रह बन जाएगा। एक इतिहासकार का मुख्य उद्देश्य तथ्यों को सटीकता और तटस्थता के साथ प्रस्तुत करना होना चाहिए। <br>इतिहास केवल अतीत की गाथा नहीं है, यह समाज को उसकी जड़ों से जोड़ने का एक माध्यम है। वस्तुनिष्ठता और शोध संरचना के साथ लिखा गया इतिहास ही हमें हमारे अतीत, वर्तमान, और भविष्य के बीच के संबंध को समझने में मदद कर सकता है।</p>\r\n\r\n\r\n\r\n\r\n',4,'2024-11-30 15:26:41','2024-12-01 08:37:58','','Publish',0,'open',0,56),('झारखंड के सिंह राजवंश का इतिहास','history-of-singh-dynasty',2,'<p>झारखंड के सिंह राजवंश का इतिहास और उसकी शासन व्यवस्था भारतीय उपमहाद्वीप के मध्यकालीन इतिहास का एक महत्वपूर्ण अध्याय है। इस राजवंश ने झारखंड के जंगलों, पहाड़ों, और पठारी इलाकों में अपना शासन स्थापित कर न केवल राजनीतिक स्थायित्व प्रदान किया बल्कि सामाजिक और सांस्कृतिक विकास में भी महत्वपूर्ण योगदान दिया। झारखंड, जो प्राचीन काल से ही आदिवासी बहुल क्षेत्र रहा है, सिंह राजवंश के शासन के तहत एक अद्वितीय प्रशासनिक संरचना और सांस्कृतिक एकता का उदाहरण प्रस्तुत करता है।</p>\r\n<h2>सिंह राजवंश का उद्भव</h2>\r\n<p>सिंह राजवंश का उद्भव झारखंड क्षेत्र में ऐसे समय हुआ, जब बाहरी आक्रमणकारियों और साम्राज्यों का प्रभाव बढ़ रहा था। झारखंड के दुर्गम भूभाग और प्राकृतिक संसाधनों ने इस क्षेत्र को न केवल आक्रमणकारियों के लिए आकर्षण का केंद्र बनाया बल्कि स्थानीय शासकों को भी अपनी शक्ति का विस्तार करने का अवसर दिया। सिंह राजवंश, जिनकी जड़ें स्थानीय जनजातीय परंपराओं और सामाजिक संरचनाओं में गहराई से जमी हुई थीं, ने धीरे-धीरे क्षेत्र पर अपना प्रभुत्व स्थापित किया।</p>\r\n<p>सिंह राजवंश का आरंभिक इतिहास मुख्यतः मौखिक परंपराओं और स्थानीय लोककथाओं में सुरक्षित है। यह राजवंश आदिवासी और गैर-आदिवासी समाज के बीच सामंजस्य स्थापित करने में सफल रहा। उनका शासन क्षेत्र मुख्यतः आज के झारखंड, ओडिशा और बंगाल के कुछ हिस्सों तक फैला हुआ था। सिंह राजवंश ने अपने शासन को स्थायित्व प्रदान करने के लिए राजनीतिक कुशलता और सैन्य ताकत का सहारा लिया।</p>\r\n<h2>शासन व्यवस्था</h2>\r\n<p>सिंह राजवंश की शासन व्यवस्था मुख्यतः सामंतवादी प्रणाली पर आधारित थी, जिसमें राजा सर्वोच्च शासक होता था। उनके अधीन सामंत या जमींदार होते थे, जो स्थानीय स्तर पर प्रशासनिक कार्यों को देखते थे। सामंतों की जिम्मेदारी कर संग्रहण, कानून व्यवस्था बनाए रखना और युद्ध के समय राजा को सैन्य सहायता प्रदान करना था।</p>\r\n<h3 class=\"atech\">न्याय प्रणाली</h3>\r\n<p>सिंह राजवंश की न्याय प्रणाली दो स्तरों पर कार्य करती थी। पहले स्तर पर स्थानीय पंचायतें थीं, जो छोटे विवादों और आपसी झगड़ों का निपटारा करती थीं। दूसरे स्तर पर राजा का दरबार था, जहां बड़े और गंभीर मामलों का निर्णय लिया जाता था।</p>\r\n<p>न्याय प्रणाली में जनजातीय परंपराओं और रीति-रिवाजों का विशेष ध्यान रखा जाता था। अपराधियों को कठोर दंड दिया जाता था, लेकिन यह सुनिश्चित किया जाता था कि न्याय प्रक्रिया निष्पक्ष हो।</p>\r\n<h3 class=\"atech\">सैन्य संगठन</h3>\r\n<p>सिंह राजवंश की सैन्य व्यवस्था उनकी शासन प्रणाली का एक मजबूत स्तंभ थी। दुर्गम पहाड़ी इलाकों और जंगलों का उपयोग उन्होंने अपने सैन्य अभियानों के लिए कुशलतापूर्वक किया। जनजातीय योद्धाओं को सेना में शामिल किया गया, जो क्षेत्र की भौगोलिक परिस्थितियों से भलीभांति परिचित थे। यह सेना बाहरी आक्रमणों के खिलाफ एक मजबूत रक्षक के रूप में कार्य करती थी।</p>\r\n<h2>सामाजिक संरचना और सांस्कृतिक योगदान</h2>\r\n<p>सिंह राजवंश ने झारखंड की सामाजिक और सांस्कृतिक संरचना को मजबूती प्रदान की। उन्होंने जनजातीय और गैर-जनजातीय समुदायों के बीच एकता स्थापित करने के लिए कई प्रयास किए।</p>\r\n<h3 class=\"atech\">धर्म और संस्कृति</h3>\r\n<p>सिंह राजवंश धार्मिक सहिष्णुता का प्रतीक था। वे मुख्यतः शिव और दुर्गा के उपासक थे, लेकिन उन्होंने स्थानीय देवी-देवताओं और जनजातीय धार्मिक परंपराओं का भी समर्थन किया। उनके शासनकाल में मंदिरों और धार्मिक स्थलों का निर्माण हुआ।</p>\r\n<p>इन धार्मिक स्थलों ने न केवल धार्मिक विश्वासों को मजबूत किया बल्कि सामाजिक एकता को भी बढ़ावा दिया। राजा स्वयं धार्मिक अनुष्ठानों में भाग लेते थे, जिससे प्रजा के बीच उनके प्रति आदर और निष्ठा का भाव उत्पन्न होता था।</p>\r\n<h3 class=\"atech\">कला और वास्तुकला</h3>\r\n<p>सिंह राजवंश के शासनकाल में कला और वास्तुकला का विकास हुआ। उनके द्वारा बनाए गए मंदिर, किले, और अन्य स्थापत्य संरचनाएं उस समय की वास्तुकला की उत्कृष्टता को दर्शाते हैं। झारखंड के कई ऐतिहासिक स्थलों पर उनके योगदान के प्रमाण मिलते हैं।</p>\r\n<h3 class=\"atech\">लोक परंपराएं और त्यौहार</h3>\r\n<p>सिंह राजवंश ने झारखंड की लोक परंपराओं और त्यौहारों को संरक्षण और प्रोत्साहन दिया। क्षेत्रीय संगीत, नृत्य और लोक कथाएं उनके शासनकाल में फली-फूलीं। हूल महोत्सव, करमा पर्व और सरहुल जैसे आदिवासी त्यौहार इस बात के प्रमाण हैं कि सिंह राजवंश ने सांस्कृतिक विविधता को स्वीकार किया और उसे प्रोत्साहित किया।</p>\r\n<h2>आर्थिक व्यवस्था</h2>\r\n<p>सिंह राजवंश की आर्थिक व्यवस्था मुख्यतः कृषि और वनोपज पर आधारित थी। झारखंड के उपजाऊ भूमि और घने जंगलों ने आर्थिक गतिविधियों को संचालित करने में महत्वपूर्ण भूमिका निभाई।</p>\r\n<h3 class=\"atech\">कृषि और वनोपज</h3>\r\n<p>धान, गेहूं, और दलहन जैसी फसलों की खेती मुख्य आर्थिक गतिविधि थी। वनों से प्राप्त शहद, लाख, और औषधीय पौधों का उपयोग न केवल स्थानीय व्यापार में होता था बल्कि यह बाहरी व्यापार का भी महत्वपूर्ण हिस्सा था।</p>\r\n<h3 class=\"atech\">खनिज संसाधन</h3>\r\n<p>झारखंड खनिज संपदा से भरपूर क्षेत्र है। सिंह राजवंश ने इन खनिजों का कुशलतापूर्वक उपयोग किया। लौह अयस्क, तांबा, और कोयला उनके राजस्व के मुख्य स्रोत थे। इन खनिजों का व्यापार राज्य की आर्थिक स्थिरता में सहायक था।</p>\r\n<h3 class=\"atech\">कर प्रणाली</h3>\r\n<p>राज्य में कर प्रणाली संतुलित थी। किसानों और व्यापारियों से कर लिया जाता था, लेकिन यह सुनिश्चित किया जाता था कि कर उनकी क्षमता के अनुरूप हो। कर से प्राप्त राजस्व का उपयोग सार्वजनिक कार्यों और सैन्य अभियानों में किया जाता था।</p>\r\n<h2>संघर्ष और पतन</h2>\r\n<p>सिंह राजवंश को बाहरी आक्रमणों और आंतरिक विवादों का सामना करना पड़ा। बाहरी शासक, विशेषकर मुगल और बंगाल के नवाब, झारखंड की खनिज संपदा पर कब्जा करना चाहते थे। सिंह राजवंश ने इन आक्रमणों का साहसपूर्वक मुकाबला किया।</p>\r\n<p>आंतरिक विवाद और प्रशासनिक कमजोरियां सिंह राजवंश के पतन का मुख्य कारण बनीं। समय के साथ उनका सैन्य बल कमजोर पड़ गया और प्रशासनिक ढांचा भी ढहने लगा। ब्रिटिश शासन के आगमन और उनकी \"फूट डालो और राज करो\" नीति ने इस प्रक्रिया को और तेज कर दिया।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>सिंह राजवंश का झारखंड के इतिहास में एक विशिष्ट स्थान है। उनका शासन न केवल राजनीतिक स्थिरता का प्रतीक था, बल्कि उन्होंने सामाजिक, सांस्कृतिक और आर्थिक विकास में भी अभूतपूर्व योगदान दिया।</p>\r\n<p>सिंह राजवंश ने झारखंड की परंपराओं, जनजातीय रीति-रिवाजों और सांस्कृतिक विविधता को संरक्षित रखा। उनका शासन आदिवासी और गैर-आदिवासी समाज के बीच संतुलन बनाए रखने का एक अद्भुत उदाहरण है।</p>\r\n<p>आज भी झारखंड के कई ऐतिहासिक और धार्मिक स्थलों पर सिंह राजवंश की छाप देखी जा सकती है। उनकी शासन व्यवस्था, सांस्कृतिक योगदान और संघर्ष की गाथाएं झारखंड के लोगों की स्मृतियों और लोक कथाओं में जीवित हैं। सिंह राजवंश का इतिहास न केवल झारखंड के लिए, बल्कि पूरे भारतीय उपमहाद्वीप के लिए प्रेरणा का स्रोत है।</p>\r\n\r\n\r\n',76,'2024-11-30 15:26:41','2024-12-01 12:58:35','','Publish',0,'open',0,57),('सिंह राजवंश की शासन व्यवस्था पर प्रकाश डाले?','rule-of-singh-synasty',2,'<p>झारखंड के सिंह राजवंश की शासन व्यवस्था एक अद्वितीय प्रणाली थी, जो स्थानीय जनजातीय परंपराओं, सामंतवादी संरचनाओं और मध्यकालीन भारतीय प्रशासनिक नीतियों का मिश्रण थी। इस व्यवस्था ने झारखंड की सामाजिक, आर्थिक, और सांस्कृतिक संरचना को न केवल स्थिरता प्रदान की, बल्कि उसे दीर्घकालिक प्रभाव भी दिया। यह शासन प्रणाली प्राचीन भारतीय परंपराओं की गहराई में जाकर जनजातीय समाज की आवश्यकताओं और उनकी परंपराओं को समझने की कोशिश करती थी। यहाँ केवल सिंह राजवंश की शासन प्रणाली पर विस्तार से चर्चा की जाएगी, जिसमें उनके प्रशासन, न्याय, कर, और सैन्य संगठन का विश्लेषण किया गया है।</p>\r\n<h2>राजा का स्थान और उनकी भूमिका</h2>\r\n<p>सिंह राजवंश की शासन व्यवस्था में राजा का स्थान सर्वोपरि था। उन्हें न केवल प्रशासनिक व्यवस्था का प्रमुख माना जाता था, बल्कि वे सांस्कृतिक और धार्मिक संरक्षक भी थे। राजा को \"धर्म के पालक\" के रूप में देखा जाता था और उनकी भूमिका न्यायप्रिय, संरक्षक और कुशल प्रशासक के रूप में होती थी। उनके आदेश अंतिम और सर्वमान्य होते थे। शासन प्रणाली में राजा की छवि एक न्यायप्रिय और करुणामय शासक के रूप में बनाई गई थी, ताकि प्रजा में उनके प्रति विश्वास और निष्ठा बनी रहे।</p>\r\n<p>राजा का दरबार शासन का केंद्र था, जहाँ पर प्रशासनिक निर्णय लिए जाते थे। यह दरबार स्थानीय सामंतों, प्रधानों और अन्य प्रमुख व्यक्तियों का एक बैठक स्थल होता था, जहाँ से राज्य के संचालन से जुड़े निर्णय लिए जाते थे। दरबार में सैन्य प्रमुख, कर संग्रहकर्ता और धार्मिक मामलों के विशेषज्ञ भी शामिल होते थे। राजा की उपस्थिति में ही महत्वपूर्ण प्रशासनिक और न्यायिक मामलों का निपटारा किया जाता था।</p>\r\n<h2>सामंतवादी संरचना</h2>\r\n<p>सिंह राजवंश की शासन प्रणाली सामंतवादी ढांचे पर आधारित थी। राजा के अधीनस्थ सामंत और जमींदार होते थे, जो अपने-अपने क्षेत्रों में प्रशासनिक और न्यायिक कार्यों को देखते थे। सामंतों को राजा की ओर से भूमि का अधिकार दिया जाता था, जिसके बदले वे राज्य को कर और सैन्य सहायता प्रदान करते थे। सामंत अपनी भूमि में रहने वाले किसानों और कारीगरों से कर एकत्र करते थे। ये कर अनाज, पशु, और अन्य वस्त्रों के रूप में दिए जाते थे, जो राज्य की अर्थव्यवस्था को बनाए रखने में सहायक थे।</p>\r\n<p>सामंतों की जिम्मेदारी केवल कर संग्रह तक सीमित नहीं थी। वे स्थानीय कानून-व्यवस्था बनाए रखने और छोटे विवादों का समाधान करने में भी प्रमुख भूमिका निभाते थे। उनका मुख्य उद्देश्य राजा के प्रति निष्ठा बनाए रखना और उनकी आज्ञाओं का पालन करना था। सामंती व्यवस्था ने सिंह राजवंश को न केवल प्रशासनिक स्थिरता प्रदान की, बल्कि स्थानीय स्तर पर शासन चलाने में भी मदद की।</p>\r\n<h2>न्याय प्रणाली</h2>\r\n<p>न्याय व्यवस्था सिंह राजवंश की शासन प्रणाली का एक महत्वपूर्ण हिस्सा थी। यह दो स्तरों पर कार्य करती थी। पहला स्तर स्थानीय था, जहाँ ग्राम पंचायतें छोटे विवादों और अपराधों का निपटारा करती थीं। पंचायतें जनजातीय परंपराओं और स्थानीय रीति-रिवाजों के आधार पर निर्णय लेती थीं। इन पंचायतों में बुजुर्ग और अनुभवी व्यक्तियों को शामिल किया जाता था, जो अपनी निष्पक्षता और ज्ञान के लिए प्रसिद्ध होते थे।</p>\r\n<p>दूसरा स्तर राजा का दरबार था, जहाँ गंभीर अपराधों और महत्वपूर्ण विवादों का निपटारा किया जाता था। राजा स्वयं या उनके द्वारा नियुक्त न्यायाधीश इन मामलों का समाधान करते थे। न्याय प्रणाली में निष्पक्षता और पारदर्शिता बनाए रखने का प्रयास किया जाता था। राजा को \"धर्म और न्याय का संरक्षक\" माना जाता था, और उनकी न्यायप्रियता को लेकर कहानियाँ प्रचलित थीं।</p>\r\n<h2>कर प्रणाली</h2>\r\n<p>सिंह राजवंश की कर प्रणाली को व्यवस्थित और कुशलता से लागू किया गया था। राज्य की आय मुख्यतः कृषि, खनिज, और वनोपज से होती थी। किसानों से उनकी फसलों पर कर लिया जाता था, जिसे \"भाग\" कहा जाता था। यह कर अनाज या अन्य उत्पादों के रूप में दिया जाता था। इसके अतिरिक्त, व्यापारियों और कारीगरों से भी कर वसूला जाता था।</p>\r\n<p>खनिज संपदा, जो झारखंड के पहाड़ी और जंगलों में प्रचुर मात्रा में उपलब्ध थी, कर संग्रह का एक महत्वपूर्ण स्रोत थी। लौह अयस्क, कोयला, और अन्य खनिज पदार्थों पर कर लगाया जाता था। वनोपज, जैसे शहद, लाख, और लकड़ी, पर भी कर लागू होता था। इन करों का उपयोग राज्य के प्रशासन, सैन्य विस्तार, और सार्वजनिक कार्यों में किया जाता था।</p>\r\n<h2>सैन्य संगठन</h2>\r\n<p>सिंह राजवंश का सैन्य संगठन उनकी शक्ति और सामर्थ्य का प्रमुख आधार था। सेना में जनजातीय योद्धाओं को विशेष स्थान दिया जाता था, क्योंकि वे दुर्गम पहाड़ी और जंगलों में युद्ध करने में निपुण होते थे। यह सेना राजा के प्रत्यक्ष नियंत्रण में होती थी और उनका मुख्य उद्देश्य राज्य की सीमाओं की रक्षा और आंतरिक विद्रोहों का दमन करना था।</p>\r\n<p>सैनिकों को उनके कौशल और अनुभव के आधार पर अलग-अलग जिम्मेदारियाँ सौंपी जाती थीं। इनमें घुड़सवार, धनुर्धर, और पैदल सैनिक शामिल होते थे। सेना का संचालन और प्रशिक्षण राजा द्वारा नियुक्त सैन्य प्रमुख के अधीन होता था। सिंह राजवंश ने सैन्य अभियानों के लिए जंगलों और पहाड़ी इलाकों का कुशलतापूर्वक उपयोग किया, जिससे उन्हें आक्रमणकारियों के खिलाफ रणनीतिक लाभ मिला।</p>\r\n<h2>सामाजिक और धार्मिक प्रशासन</h2>\r\n<p>सिंह राजवंश की शासन व्यवस्था में सामाजिक और धार्मिक प्रशासन का महत्वपूर्ण स्थान था। यह व्यवस्था जनजातीय समाज की परंपराओं और रीति-रिवाजों का सम्मान करती थी। समाज के विभिन्न वर्गों के बीच सामंजस्य बनाए रखने का प्रयास किया जाता था। राजा धार्मिक सहिष्णुता के प्रतीक थे और उन्होंने सभी धर्मों और परंपराओं का समान रूप से सम्मान किया।</p>\r\n<p>राजा मुख्यतः शिव और दुर्गा के उपासक थे, लेकिन उन्होंने क्षेत्रीय देवी-देवताओं और जनजातीय परंपराओं का भी समर्थन किया। धार्मिक अनुष्ठानों और मंदिरों के निर्माण में राजा की सक्रिय भूमिका होती थी। यह धार्मिक सहिष्णुता न केवल प्रजा के बीच एकता को बढ़ावा देती थी, बल्कि राज्य की सांस्कृतिक धरोहर को भी समृद्ध करती थी।</p>\r\n<h2>आर्थिक प्रशासन</h2>\r\n<p>सिंह राजवंश की अर्थव्यवस्था मुख्यतः कृषि और वनोपज पर आधारित थी। राज्य की कृषि प्रणाली संगठित थी और किसानों को बेहतर उत्पादन के लिए प्रोत्साहित किया जाता था। कृषि उत्पादों के व्यापार को बढ़ावा देने के लिए बाजार और मेलों का आयोजन किया जाता था।</p>\r\n<p>खनिज और वनोपज राज्य की आय का एक अन्य महत्वपूर्ण स्रोत थे। सिंह राजवंश ने इन संसाधनों का कुशल प्रबंधन किया और उनके व्यापार के माध्यम से राज्य की अर्थव्यवस्था को सुदृढ़ किया।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>झारखंड के सिंह राजवंश की शासन व्यवस्था जनजातीय परंपराओं, सामंती संरचनाओं, और मध्यकालीन प्रशासनिक नीतियों का एक अनूठा मिश्रण थी। यह प्रणाली न केवल राज्य की राजनीतिक स्थिरता सुनिश्चित करती थी, बल्कि समाज के विभिन्न वर्गों के कल्याण को भी प्राथमिकता देती थी। उनकी न्यायप्रियता, सैन्य संगठन, और धार्मिक सहिष्णुता ने उन्हें झारखंड के इतिहास में एक विशिष्ट स्थान प्रदान किया। यह शासन व्यवस्था क्षेत्रीय सांस्कृतिक और ऐतिहासिक धरोहर का महत्वपूर्ण हिस्सा है, जो आज भी अध्ययन और प्रशंसा के योग्य है।</p>\r\n',54,'2024-12-01 13:17:25','2024-12-01 13:35:33','','Publish',0,'open',9,58),('झारखंड में सदानों की भूमिका का वर्णन करे?','role-of-sadans-in-jharkhand',2,'<h2>झारखंड में सदानों की भूमिका</h2>\r\n<p>झारखंड के सामाजिक, सांस्कृतिक, आर्थिक और राजनीतिक परिदृश्य में सदानों का योगदान अत्यधिक महत्वपूर्ण है। सदान झारखंड के गैर-आदिवासी मूल निवासी हैं, जो इस क्षेत्र में आदिकाल से बसे हुए हैं। झारखंड का विकास और इसकी विविधता का स्वरूप सदानों और आदिवासियों के सामूहिक योगदान का परिणाम है।</p>\r\n<p>सदान शब्द का अर्थ है \"मूल निवासी\" या \"स्थानीय निवासी।\" झारखंड के सदान समुदाय गैर-आदिवासी होने के बावजूद आदिवासी समाज के साथ गहरी सांस्कृतिक समानता साझा करते हैं। समें कुर्मी, भूमिहार, ब्राह्मण, कायस्थ, राजपूत और अन्य जातियाँ शामिल हैं।झारखंड की संस्कृति में सदानों ने अपनी भाषा, संगीत और परंपराओं से गहरा योगदान दिया है। सदानी भाषा, जिसमें नागपुरी, कुरमाली और खोरठा प्रमुख हैं, झारखंड की पहचान का हिस्सा है। ये भाषाएँ न केवल संचार का माध्यम हैं, बल्कि क्षेत्र की सांस्कृतिक धरोहर को भी संरक्षित करती हैं। सदान समुदाय के लोग अपने लोकगीतों और नृत्यों के माध्यम से झारखंड की सांस्कृतिक विरासत को जीवंत रखते हैं। झारखंड की क्षेत्रीय भाषाओं में  प्रमुख स्थान रखती है।सदान समुदाय हिन्दू धर्म को मानता है, लेकिन आदिवासी धर्म और परंपराओं से उनका घनिष्ठ संबंध है।</p>\r\n<h2>झारखंड में सदानों की आर्थिक भूमिका</h2>\r\n<p>इतिहास में झारखंड का क्षेत्र लंबे समय तक कृषि और स्थानीय व्यापार का केंद्र रहा है। सदानों ने कृषि और पशुपालन के माध्यम से इस क्षेत्र की आर्थिक व्यवस्था को मजबूत किया। कुर्मी और भूमिहार जातियाँ झारखंड की कृषि अर्थव्यवस्था के आधारस्तंभ रही हैं। पारंपरिक फसल उत्पादन के अलावा, वे जल प्रबंधन और भूमि संरक्षण में भी अपनी विशेषज्ञता का प्रदर्शन करते हैं। सदान समाज का आर्थिक योगदान केवल खेती तक सीमित नहीं है; वे खनन और उद्योगों में भी सक्रिय रहे हैं। झारखंड के खनिज संसाधनों के दोहन और औद्योगिक विकास में सदानों की भागीदारी उल्लेखनीय रही है।</p>\r\n<h2>झारखंड में सदानों की राजनीतिक भूमिका</h2>\r\n<p>राजनीतिक दृष्टि से सदानों की भूमिका झारखंड के इतिहास के हर दौर में देखी जा सकती है। स्वतंत्रता संग्राम के दौरान, सदान नेताओं ने अंग्रेजों के खिलाफ संघर्ष में सक्रिय भाग लिया। इसके अलावा, झारखंड को अलग राज्य के रूप में मान्यता दिलाने के आंदोलन में भी सदानों ने अपनी भूमिका निभाई। सदानों ने झारखंड के आदिवासियों के साथ मिलकर क्षेत्र की सांस्कृतिक और राजनीतिक अस्मिता को बनाए रखने का प्रयास किया।</p>\r\n<h2>झारखंड में सदानों की सामाजिक भूमिका </h2>\r\n<p>समाज सुधार के क्षेत्र में सदानों ने शिक्षा और स्वास्थ्य सेवाओं के विकास में योगदान दिया है। कई सदान नेताओं ने ग्रामीण क्षेत्रों में शिक्षा का प्रसार किया और स्थानीय स्तर पर सामाजिक कुरीतियों के खिलाफ आवाज उठाई। उनका मानना था कि शिक्षा और जागरूकता के माध्यम से ही समाज का विकास संभव है।</p>\r\n<p>वर्तमान में, झारखंड में सदान समुदाय तेजी से आधुनिकता की ओर अग्रसर है। वे शिक्षा, उद्योग, और अन्य पेशों में अपनी उपस्थिति दर्ज करा रहे हैं। युवा पीढ़ी अपने पारंपरिक पेशों के साथ-साथ आईटी, चिकित्सा, और इंजीनियरिंग जैसे क्षेत्रों में भी कदम रख रही है। इस बदलाव के बावजूद, सदानों ने अपनी पारंपरिक संस्कृति और मूल्यों को संरक्षित रखा है।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार हम देखते है झारखंड के विकास और इतिहास में सदानों की भूमिका अत्यंत महत्वपूर्ण रही है। उनका सामाजिक, सांस्कृतिक, आर्थिक और राजनीतिक योगदान झारखंड की विविधता और समृद्धि को दर्शाता है। सदानों और आदिवासियों के सामूहिक प्रयासों ने झारखंड को एक विशिष्ट पहचान दी है। वर्तमान समय में सदानों की भूमिका शिक्षा, आधुनिक रोजगार, और सामाजिक सुधार में बढ़ रही है, जो झारखंड के उज्जवल भविष्य का प्रतीक है। सदानों का योगदान झारखंड की संस्कृति, परंपराओं और आधुनिक विकास के बीच एक सेतु का कार्य करता है।</p>',45,'2024-12-02 09:00:28','2024-12-02 12:40:40','','Publish',0,'open',9,59),('झारखंड में 1857 का विद्रोह।','revolt-of-1857-in-jharkhand',2,'<p>1857 का विद्रोह, जिसे \"सिपाही विद्रोह\" भी कहा जाता है, झारखंड के विभिन्न हिस्सों में फैल चुका था। क्षेत्रीय आदिवासी और किसान पहले से ही ब्रिटिश नीतियों, ज़मींदार प्रथा और सांस्कृतिक दमन से असंतुष्ट थे। झारखंड का यह संघर्ष मुख्य रूप से चोटानागपुर, संताल परगना और पलामू जैसे क्षेत्रों में केंद्रित था।</p>\r\n<p>शशिभूषण चौधरी ने अपनी पुस्तक सिविल रेविलियन इन द इण्डियन म्यूटनिज 1957 ई. में लिखा है कि <i>\"झारखंड में 1857 ई. के गदर का स्वरूप सरकारी विरोध था साथ ही यहाँ इस क्रांति के कुछ कतिपय स्थानीय कारण भी थे जो इसे विशिष्ट निजी स्वरूप प्रदान करते हैं। झारखंड में जैसे-जैसे अंग्रेजी सरकार का शिकंजा मजबूत होते गई वैसे-वैसे पलामू के चेरों, छोटानागपुर के नागवंशियों, छोटानागपुर के सिंह राजाओं, रामगढ़ के शासकों तथा अन्य छोटे-मोटे शासकों, जमींदारों और जागीरदारों की राजनीति तथा आर्थिक स्थिति दयनी होती गई।</i></p>\r\n<h2>झारखंड में 1857 का विद्रोह के कारण</h2>\r\n<h3 class=\"atech\">आर्थिक शोषण</h3>\r\n<p>ब्रिटिश शासन ने ज़मींदारी प्रथा लागू करके आदिवासियों और किसानों से उनकी भूमि छीन ली। उनसे भारी कर वसूले गए, जिससे उनकी आजीविका पर संकट गहराने लगा। जंगलों पर ब्रिटिश अधिकार ने आदिवासियों को उनके परंपरागत संसाधनों और रोजगार से वंचित कर दिया। आदिवासी किसानों को साहूकारों से कर्ज लेना पड़ा, और जब वे अपना कर्ज चुकाने में असमर्थ हुए, तो उनकी संपत्ति छीन ली गई। साहूकारों और ज़मींदारों के अत्याचारों ने आदिवासियों को कर्ज और बंधुआ मजदूरी के चक्र में फंसा दिया।  इस आर्थिक शोषण ने आदिवासी समाज में व्यापक असंतोष और विद्रोह की भावना को जन्म दिया।</p>\r\n<h3 class=\"atech\">राजनीतिक कारण</h3>\r\n<p>झारखंड में ब्रिटिश शासन की नीतियों ने स्थानीय लोगों में गहरा असंतोष पैदा किया। आदिवासी समाज के नेताओं को राजनीतिक अधिकारों से वंचित कर दिया गया था, और स्थानीय प्रशासन में भ्रष्टाचार ने उनकी नाराजगी को बढ़ाया। ब्रिटिश प्रशासन ने आदिवासी समाज की पारंपरिक सामाजिक व्यवस्था, जैसे मानकी-मुंडा प्रथा और आदिवासी पंचायती व्यवस्था को कमजोर किया। इसके स्थान पर विदेशी कानून और ज़मींदारी व्यवस्था लागू की गई, जिसने आदिवासियों को उनके प्राकृतिक संसाधनों और जमीन से वंचित कर दिया। इसने उनके पारंपरिक रोजगार, जैसे खेती, शिकार, और जंगल पर आधारित आजीविका को बाधित किया।</p>\r\n<h3 class=\"atech\">सामाजिक कारण</h3>\r\n<p>आदिवासियों की पारंपरिक जीवनशैली और रीति-रिवाजों में ब्रिटिश हस्तक्षेप मुख्य था। ईसाई मिशनरियों द्वारा धर्म परिवर्तन का दबाव और आदिवासी धार्मिक परंपराओं का अपमान सामाजिक असंतोष का बड़ा कारण बना। सामाजिक दमन और ब्रिटिश अधिकारियों द्वारा आदिवासियों के प्रति भेदभावपूर्ण व्यवहार ने उनके आत्मसम्मान को ठेस पहुंचाई। इन कारणों से आदिवासी समाज में असंतोष गहराया और उन्होंने अपनी सांस्कृतिक पहचान और अधिकारों की रक्षा के लिए विद्रोह किया।</p>\r\n<h3 class=\"atech\">सैनिक असंतोष</h3>\r\n<p>झारखंड के कई सैनिक ब्रिटिश सेना में शामिल थे। उन्हें भेदभावपूर्ण व्यवहार और धार्मिक भावनाओं के अपमान का सामना करना पड़ा। \"चर्बी वाले कारतूस\" विवाद, जिसमें गाय और सूअर की चर्बी का उपयोग किया गया था, ने धार्मिक भावनाओं को ठेस पहुंचाई। झारखंड के सैनिकों ने विद्रोह में सक्रिय भूमिका निभाई और अपने क्षेत्रों में इसे फैलाने में मदद की।</p>\r\n\r\n<h2>झारखंड में 1857 का विद्रोह का स्वरूप</h2>\r\n<p>झारखंड में 1857 का विद्रोह एक व्यापक और संगठित संघर्ष के रूप में उभरा, जिसमें विभिन्न सामाजिक, आर्थिक और सांस्कृतिक कारकों का समावेश था। शशिभूषण चौधरी के मत में <i>\"छोटानागपुर का विद्रोह जना था जिसमें सभी प्रकार के लोगों, जमींदारों से लेकर मुखिया तक, आदिवासियों मुसलमानों, सभी ने भाग लिया और सभी का एक ही मकसद था अंग्रेजों द्वारा शोषण को समाप्त किया जाना और अंग्रेजी शासन के प्रतीक चिन्हों को समाप्त कर देना इसलिए यह न केवल सैनिक विद्रोह था और न किसी छोटे और असंतुष्ट जनजातीय समुह का उपद्रव मात्र।\"</i></p>\r\n<p>छोटानागपुर के लोगों ने अभूतपूर्व उत्साह और बहादूरी के साथ इस गदर में भाग लिया। डाल्टन ने लिखा है कि <i>\"किसी भी व्यक्ति पर इनाम की घोषणा का प्रभाव नहीं पड़ा।\"</i> बड़े पैमाने पर लूट-मार, आगजनी और विद्रोहियों द्वारा कई सफल हमले इस तथ्य को सिद्ध करता है कि लोग विद्रोहियों के पक्ष में थे। विद्रोहियों ने कई जमींदारों पर हमले किए। जिसका कारण उनसे उनकी पुरानी दुश्मनी थी यह असत्य है वस्तुतः ये जमीदार सरकार के समर्थक थे इसलिए उनपर हमले हुए। किसी अंग्रेज अधिकारी के चंगुल में न जाने पर वे अपने देश में विदेशी शासन के सभी चिन्हों को नष्ट करने में लग गए।</p>\r\n<p>कुछ सरकारी अधिकारी यह भी सिद्ध करने का प्रयास किया है कि छोटानागपुर विशेष की जनजातियाँ इस विद्रोह में तटस्थ बनी रही। लेकिन सच्चाई यह है कि वीर, मेहनती और स्वतंत्रता प्रेमी, मुंडा तथा उरांव जाति के लोग बुण्डू तमाड़ क्षेत्र में अत्याधिक सक्रिय थे। विद्रोह के दौरान नागवंशी राजा जगन्नाथ शाहदेव से मुंडाओं ने सहायता मांगी थी। वे नागवंशी राजा को उनके वचनों की याद दिला रहे थे और उससे अपने प्राणों की रक्षा के लिए याचना कर रहे थे। स्थिति इतनी विस्फोटक हो गई थी कि उन्होंने सुरक्षा की आशा छोड़ अपने जीवन की परवाह किए बिना अंग्रेजों पर टूट पड़े।</p>\r\n\r\n<h2>झारखंड में 1857 का विद्रोह का परिणाम</h2> \r\n<p>हालांकि 1857 ई. का विद्रोह अपने तात्कालिक लक्ष्य को पाने में विफल रहा, लेकिन इसका दूरगामी प्रभाव पड़ा। यह राष्ट्रभक्तों के लिए प्रेरणास्रोत बना और इसने राष्ट्रीय चेतना के उदय एवं विकास में महत्वपूर्ण भूमिका निभाई।</p>\r\n<p>यद्यपि 1857 ई. का विद्रोह ब्रिटिश सरकार के द्वारा सफलतापूर्वक कुचल दिया गया। ब्रिटिश संसद के द्वारा एक अधिनियम पारित किया गया, जिसके अनुसार भारत में इस्ट इण्डिया कम्पनी का शासन समाप्त हुआ और भारत में ब्रिटिश क्राउन (ताज) का प्रत्यक्ष शासन आरंभ हुआ।</p>\r\n<p>विद्रोही नेताओं की संपत्ति जब्त कर ली गई और उनके बीच बाँट दी गई, जिन्होंने अंग्रेजों का साथ दिया था। विद्रोह की समाप्ति के बाद छोटानागपुर को लड़ाकू (युद्धप्रिय) जनजातियों जैसे कोलों, संथालों आदि में से कुछ को सेना में भर्ती किया जाने लगा।</p>\r\n<p>झारखण्ड में ब्रिटिश ताज के सीधे शासन के कारण प्रशासन में सुधारों की प्रक्रिया आरंभ हुई। फिर भी आर्थिक रूप से यहाँ की जनता का शोषण हुआ। अतएव झारखण्ड में धीरे-धीरे राजनीतिक चेतना का उदय हुआ।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>झारखंड में 1857 का विद्रोह केवल ब्रिटिश शासन के खिलाफ एक संगठित आंदोलन नहीं था, बल्कि यह आदिवासी संस्कृति, अधिकार और आजादी की रक्षा के लिए एक महत्वपूर्ण संघर्ष था। यह विद्रोह उस साहस और दृढ़ता का प्रतीक है, जो झारखंड के आदिवासियों और किसानों ने ब्रिटिश दमन के खिलाफ दिखाया। इसने भारत के स्वतंत्रता संग्राम को एक नई दिशा दी और झारखंड को इतिहास में एक विशेष स्थान प्रदान किया।</p>',154,'2024-12-02 09:00:28','2024-12-03 05:39:09','','Publish',0,'open',9,60),('भारतीय सिनेमा, कला और साहित्य में महिलाओं का योगदान','contribution-of-women-in-indian-cinema-art-and-literature',2,'<p>भारतीय सिनेमा, कला और साहित्य में महिलाओं का योगदान अद्वितीय और महत्वपूर्ण रहा है। महिलाओं ने इन क्षेत्रों में न\r\n        केवल अपनी प्रतिभा का प्रदर्शन किया है, बल्कि समाज की धारणाओं को चुनौती भी दी है।</p>\r\n    <h2>भारतीय सिनेमा में महिलाओं का योगदान</h2>\r\n<p>भारतीय सिनेमा का इतिहास 1913 से शुरू होता है जब दादा साहेब फाल्के ने \'राजा हरिशचंद्र\' फिल्म बनाई। इस दौर में महिलाओं की भूमिका काफी सीमित थी, और उन्हें परदे पर देखना असामान्य था। लेकिन धीरे-धीरे, कुछ महिलाएं इस क्षेत्र में आईं, जैसे देविका रानी, जिन्होंने न केवल अभिनय किया, बल्कि फिल्म निर्माण में भी महत्वपूर्ण भूमिका निभाई। देविका रानी भारतीय सिनेमा की पहली महिला प्रोड्यूसर थीं, और उन्होंने \'नया संसार\' जैसी फिल्मों में अपनी कलात्मकता का परिचय दिया।</p>\r\n    <h3 class=\"atech\">1950 और 1960 का दशक</h3>\r\n    <p>इस दशक में कई अभिनेत्रियां जैसे निम्मी, वहीदा रहमान, और मीना कुमारी ने अपने अभिनय से सिनेमा को समृद्ध किया। मीना\r\n        कुमारी ने अपने करियर के दौरान कई सामाजिक मुद्दों को उठाया और अपनी फिल्मों के माध्यम से महिलाओं की आवाज उठाई। इस\r\n        समय के दौरान, फिल्मों में महिलाओं की भूमिकाओं को विकसित किया गया, और उन्हें मुख्यधारा की कहानियों का हिस्सा\r\n        बनाया गया।</p>\r\n    <h3 class=\"atech\">1970 और 1980 का दशक</h3>\r\n    <p>इस समय में, भारतीय सिनेमा ने महिला केंद्रित फिल्मों की ओर कदम बढ़ाया। शबाना आज़मी, स्मिता पाटिल और रीमा लागू जैसी\r\n        अभिनेत्रियों ने अपनी एक्टिंग से सिनेमा को नया रूप दिया। शबाना आज़मी ने कई फिल्मों में सामाजिक मुद्दों को उठाया,\r\n        जबकि स्मिता पाटिल ने महिलाओं के अधिकारों और उनकी स्थिति पर ध्यान केंद्रित किया।</p>\r\n    <h3 class=\"atech\">1990 के दशक से वर्तमान</h3>\r\n    <p>1990 के दशक में, सिनेमा में महिलाओं की भूमिकाएं और अधिक विविध हो गईं। इस दौर में, फिल्म निर्माता और निर्देशक जैसे\r\n        मीरा नायर और दीपा मेहता ने महिलाओं के मुद्दों पर आधारित फिल्में बनाई। \'फ्राइडन\' और \'हवा हॉई\' जैसी फिल्मों ने\r\n        महिलाओं के अधिकारों और उनके संघर्षों को उजागर किया।</p>\r\n    <p>आधुनिक समय में, विद्या बालन, कंगना रनौत, और दीपिका पादुकोण जैसी अभिनेत्रियों ने विभिन्न प्रकार की भूमिकाएं निभाईं\r\n        हैं। विद्या बालन की \'कहानी\' और \'बदला\' जैसी फिल्मों ने महिला नायिकाओं को केंद्र में रखा और उनके दृष्टिकोण को\r\n        महत्वपूर्णता दी।</p>\r\n\r\n    <h2>भारतीय कला में महिलाओं का योगदान</h2>\r\n    <h3 class=\"atech\">1. पारंपरिक कला</h3>\r\n    <p>भारतीय पारंपरिक कला में महिलाओं की भूमिका महत्वपूर्ण रही है। मधुबनी पेंटिंग, वारली आर्ट, और कांची काड़ी जैसे\r\n        विभिन्न कलात्मक रूपों में महिलाओं ने अपनी पहचान बनाई है। उदाहरण के लिए, मिथिलावासी महिलाएं मधुबनी पेंटिंग्स में\r\n        अपना योगदान देती हैं, जो न केवल एक कला है, बल्कि एक सांस्कृतिक धरोहर भी है।</p>\r\n    <h3 class=\"atech\">2. आधुनिक कला</h3>\r\n    <p>आधुनिक कला में, अमृता शेरगिल, नंदिता दास और अंजलि मेनन जैसी कलाकारों ने भारतीय कला को नया दिशा दी है। अमृता\r\n        शेरगिल ने भारतीय कला को पश्चिमी प्रभावों के साथ मिलाकर अपनी अनोखी शैली विकसित की। उनकी पेंटिंग्स में भारतीय\r\n        संस्कृति और जीवन के विविध पहलुओं को दर्शाया गया है।</p>\r\n    <h3 class=\"atech\">3. संगीत और नृत्य</h3>\r\n    <p>भारतीय संगीत और नृत्य में भी महिलाओं का योगदान अद्वितीय है। लता मंगेशकर और आशा भोसले जैसी गायिकाओं ने भारतीय\r\n        संगीत को नई ऊंचाइयों पर पहुंचाया। उनके गाने न केवल भारतीय फिल्म उद्योग में, बल्कि अंतरराष्ट्रीय स्तर पर भी\r\n        लोकप्रिय हुए हैं।</p>\r\n    <p>नृत्य में, रुक्मिणी देवी अरुंडेल और सोनल मानसिंह जैसी कलाकारों ने नृत्य को एक उच्च कला रूप में स्थापित किया।\r\n        उन्होंने नृत्य के माध्यम से भारतीय संस्कृति को विश्व स्तर पर प्रस्तुत किया।</p>\r\n    <h2>भारतीय साहित्य में महिलाओं का योगदान</h2>\r\n    <h3 class=\"atech\">1. प्राचीन काल</h3>\r\n    <p>भारतीय साहित्य में महिलाओं की भूमिका प्राचीन काल से ही महत्वपूर्ण रही है। मीरा बाई ने भक्ति साहित्य में अपनी आवाज\r\n        दी, जबकि सावित्री बाई फुले ने समाज सुधारक के रूप में महत्वपूर्ण योगदान दिया।</p>\r\n    <h3 class=\"atech\">2. आधुनिक साहित्य</h3>\r\n    <p>19वीं और 20वीं सदी में, महिलाओं ने साहित्य में अपने विचारों और अनुभवों को अभिव्यक्त करने के लिए लेखन को अपनाया।\r\n        महादेवी वर्मा, इस्मत चुगताई, और कमला दास जैसी लेखिकाओं ने अपने साहित्य में महिलाओं की समस्याओं और उनके जीवन की\r\n        कठिनाइयों को व्यक्त किया।</p>\r\n    <p>महादेवी वर्मा की कविताएं और इस्मत चुगताई की कहानियां भारतीय समाज में महिलाओं की स्थिति को उजागर करती हैं।\r\n        उन्होंने न केवल साहित्य में योगदान दिया, बल्कि समाज में महिलाओं के अधिकारों के लिए भी आवाज उठाई।</p>\r\n    <h3 class=\"atech\">3. समकालीन साहित्य</h3>\r\n    <p>आधुनिक समय में, लेखिकाएं जैसे अनुराधा कोलंबकर, तस्लीमा नसरीन, और शहनाज़ हुसैन ने अपने लेखन के माध्यम से समाज में\r\n        महिलाओं की समस्याओं और संघर्षों को उजागर किया। इन लेखिकाओं ने अपने अनुभवों को साहित्य में ढाला और समाज को सोचने\r\n        पर मजबूर किया।</p>\r\n    <h2>महिलाओं का योगदान: प्रभाव और बदलाव</h2>\r\n    <p>भारतीय सिनेमा, कला और साहित्य में महिलाओं के योगदान ने समाज के अनेक पहलुओं को प्रभावित किया है। उनके कार्यों ने न\r\n        केवल सांस्कृतिक पहचान को मजबूत किया है, बल्कि उन्होंने महिलाओं के अधिकारों और उनके स्थान को भी उजागर किया है।\r\n    </p>\r\n    <p>महिलाओं ने अपने संघर्ष और कठिनाइयों के माध्यम से यह साबित किया है कि वे केवल दर्शक नहीं हैं, बल्कि समाज में\r\n        महत्वपूर्ण परिवर्तन लाने की क्षमता रखती हैं। उनके योगदान ने उन्हें सशक्त बनाया है और उन्होंने नए रास्ते खोले\r\n        हैं।</p>\r\n    <h2>निष्कर्ष</h2>\r\n    <p>भारतीय सिनेमा, कला और साहित्य में महिलाओं का योगदान अद्वितीय और प्रेरणादायक है। उन्होंने अपने कार्यों के माध्यम\r\n        से समाज की धारणाओं को चुनौती दी है और अपने अनुभवों को साझा किया है। भारतीय सिनेमा में महिलाओं ने न केवल अभिनय\r\n        किया, बल्कि निर्देशन और लेखन में भी महत्वपूर्ण योगदान दिया है।</p>\r\n    <p>कला में, महिलाओं ने पारंपरिक और आधुनिक दोनों क्षेत्रों में अपनी प्रतिभा का प्रदर्शन किया है। साहित्य में,\r\n        उन्होंने अपने विचारों को लिखकर समाज के मुद्दों को उजागर किया है।</p>\r\n    <p>महिलाओं का योगदान न केवल उन्हें सशक्त बनाता है, बल्कि पूरे समाज को आगे बढ़ने की प्रेरणा देता है। यह महत्वपूर्ण है\r\n        कि हम महिलाओं के योगदान को पहचानें और उन्हें सम्मान दें, ताकि आने वाली पीढ़ियाँ भी इस प्रेरणा से प्रेरित हो\r\n        सकें।</p>',100,'2024-12-05 03:09:12','2024-12-05 03:10:56','','Publish',0,'open',19,61),('मध्यकालीन भारत में महिलाओं की राजनीतिक स्थिति','political-status-of-women-in-medieval-india',2,'<p>मध्यकालीन भारत में महिलाओं की राजनीतिक स्थिति एक जटिल और विविधतापूर्ण विषय है, जो विभिन्न राजवंशों, क्षेत्रों और सामाजिक संरचनाओं के आधार पर भिन्नता दिखाती है। लगभग 6ठी से 18वीं शताब्दी में, महिलाओं की भूमिका और स्थिति कई कारकों से प्रभावित थी, जिसमें समाज का ढाँचा, धर्म, शिक्षा, और आर्थिक स्थिति शामिल थे। इस समय में भारतीय समाज में सामंती ढाँचा, धर्म, और सामाजिक मान्यताएँ महिलाओं की भूमिका को निर्धारित करने में महत्वपूर्ण भूमिका निभाती थीं।</p>\r\n<p>रानी दुर्गावती और झाँसी की रानी लक्ष्मीबाई जैसी वीर महिलाओं ने अपने राज्यों की स्वतंत्रता और सुरक्षा के लिए युद्ध लड़े। इसी तरह, रानी कर्णावती और रुद्रमा देवी जैसी रानियों ने शासन की बागडोर संभालते हुए अपनी क्षमता का प्रदर्शन किया। इन महिलाओं ने यह साबित किया कि वे केवल पारिवारिक जिम्मेदारियों तक सीमित नहीं थीं, बल्कि राजनीतिक निर्णय लेने में भी सक्षम थीं।</p>\r\n<p>मध्यकालीन भारत में कुछ महिलाओं ने अपनी राजनीतिक स्थिति को प्रभावी रूप से इस्तेमाल किया। उदाहरण के लिए, रानी दुर्गावती, जो गोंडवाना की रानी थीं, ने 16वीं शताब्दी में मुग़ल साम्राज्य के खिलाफ संघर्ष किया। उन्होंने अपने राज्य की स्वतंत्रता के लिए अद्वितीय साहस और नेतृत्व दिखाया। इसी तरह, झाँसी की रानी लक्ष्मीबाई ने 1857 के स्वतंत्रता संग्राम के दौरान महत्वपूर्ण भूमिका निभाई। उनकी बहादुरी और रणनीतिक कौशल ने उन्हें भारतीय इतिहास में एक प्रमुख व्यक्तित्व बना दिया।</p>\r\n<p>राजपूत रानियाँ भी राजनीतिक मामलों में महत्वपूर्ण भूमिका निभाती थीं। रानी पद्मावती, जो चित्तौड़ की रानी थीं, ने अपने राज्य की रक्षा के लिए साहसिक कदम उठाए। इन महिलाओं की राजनीतिक गतिविधियाँ केवल युद्ध में भाग लेने तक सीमित नहीं थीं, बल्कि वे अपने पति के राजकीय निर्णयों में भी सक्रिय रूप से शामिल थीं।</p>\r\n<p>कई मामलों में, रानियाँ अपने पति की अनुपस्थिति में शासन की बागडोर संभालती थीं। जब राजा युद्ध में जाते थे या अस्वस्थ होते थे, तब उनकी पत्नियाँ शासन करती थीं। रानी कर्णावती ने मेवाड़ के खिलाफ युद्ध किया और रानी रुद्रमा देवी ने अपनी शक्ति का इस्तेमाल करते हुए अपने राज्य का सफलतापूर्वक संचालन किया। ये उदाहरण दर्शाते हैं कि रानियाँ न केवल अपने परिवारों के लिए, बल्कि समाज के लिए भी महत्वपूर्ण राजनीतिक भूमिकाएँ निभाती थीं।</p>\r\n<p>महिलाओं की राजनीतिक स्थिति उनके शिक्षा स्तर और सामाजिक स्थिति पर निर्भर करती थी। उच्च जातियों की महिलाएँ, विशेष रूप से राजघरानों से संबंधित, आमतौर पर अधिक स्वतंत्रता और शिक्षा प्राप्त करती थीं। कुछ रानियाँ और सामंतियों की पत्नियाँ शिक्षा प्राप्त करती थीं और साहित्य, कला और विज्ञान में योगदान देती थीं। रानी कीर्तिदेवी जैसी विदुषियों ने कविताएँ लिखीं और समाज में जागरूकता फैलाने का कार्य किया।</p>\r\n<p>हालांकि, निम्न जातियों की महिलाओं की स्थिति अधिक कठिन होती थी। उन्हें अक्सर शिक्षा का अवसर नहीं मिलता था, और वे सामाजिक और आर्थिक रूप से वंचित रहती थीं। उनकी राजनीतिक भागीदारी भी सीमित थी।</p>\r\n<p>महिलाओं ने कई धार्मिक और सामाजिक आंदोलनों में भी सक्रिय भाग लिया। भक्ति आंदोलन में कई महिला संत उभरीं, जिन्होंने न केवल धार्मिक स्वतंत्रता की मांग की, बल्कि सामाजिक न्याय के लिए भी संघर्ष किया। मीरा बाई, राधा, और तुकाराम जैसी महिलाएँ भक्ति के प्रतीक बन गईं। उनका योगदान धार्मिक और सामाजिक बदलाव में महत्वपूर्ण था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>कुछ महिलाओं सीधे तौर पर राजनीतिक में भाग लिया कुछ महिलाओं ने अपनी महत्वपूर्ण एवं उपयोगी सुझावों के द्वारा राजनीतिक में महत्वपूर्ण भूमिका निभाई, महिलाओं ने राजनीतिक निर्णयों में सक्रिय भागीदारी की, जबकि अधिकांश पारंपरिक भूमिकाओं में बंधी रहीं।</p>\r\n',170,'2024-12-05 03:09:12','2024-12-05 04:59:19','','Publish',0,'open',19,62),('कोल विद्रोह के कारण और परिणाम ','causes-and-consequences-of-kol-revolt',2,'<p>कोल विद्रोह आदिवासी जनजातीय आंदोलनों में से एक महत्वपूर्ण विद्रोह था जो वर्तमान झारखंड के छोटा नागपुर क्षेत्र में 1831 और 1832 के बीच हुआ था। यह विद्रोह झारखंड के कोल आदिवासियों द्वारा अंग्रेजों और उनके समर्थक ज़मींदारों के खिलाफ किया गया था। इसका मुख्य उद्देश्य बाहरी हस्तक्षेप से अपने पारंपरिक अधिकारों और संस्कृति की रक्षा करना था।</p>\r\n<p>ब्रिटिश शासन के आगमन के साथ, इन जनजातियों की पारंपरिक सामाजिक-आर्थिक संरचना बाधित हो गई। अंग्रेजों ने इस क्षेत्र में गैर-आदिवासी साहूकारों, ज़मींदारों (ज़मींदारों) और व्यापारियों को लाया। इसके कारण कोल मुखियाओं से लेकर इन बाहरी लोगों तक बड़े पैमाने पर ज़मीन का हस्तांतरण हुआ, जिसमें अत्याचारी सिख और मुस्लिम किसान और साहूकार शामिल थे, जो अत्यधिक कर मांगते थे।</p>\r\n<p>कोल ने इन बाहरी लोगों के हाथों अपनी ज़मीनें खो दीं और उन्हें भारी मात्रा में पैसे देने पड़े, जिसके कारण कई लोग बंधुआ मज़दूर बन गए। ब्रिटिश न्यायिक नीतियों ने भी कोल के बीच नाराज़गी पैदा की। नए कानूनी और राजनीतिक ढांचे के तहत कोल द्वारा सामना किए जाने वाले आर्थिक शोषण और सामाजिक उत्पीड़न ने व्यापक असंतोष और गुस्से को जन्म दिया, जिसने विद्रोह के लिए मंच तैयार किया।</p>\r\n<h2>कोल विद्रोह के कारण</h2>\r\n<h3>आर्थिक शोषण</h3>\r\n<p>अंग्रेजों द्वारा जमींदारी प्रथा लागू करने से जनजातीय मुखियाओं से भूमि गैर-जनजातीय जमींदारों को हस्तांतरित हो गई, जिनमें अत्याचारी हिंदू, सिख और मुस्लिम किसान और साहूकार शामिल थे। इन नये जमींदारों ने ऊंचे लगान और अवैध कर लगाये, जिसके परिणामस्वरूप अक्सर कोलों से मवेशी जब्त कर लिये जाते थे और उनसे जबरन श्रम कराया जाता था। भूमि स्वामित्व और प्रशासन की ब्रिटिश प्रणालियाँ जनजातीय जीवन शैली के लिए अनुपयुक्त थीं और इससे व्यापक आर्थिक संकट पैदा हुआ।</p>\r\n<h3>सामाजिक कारण</h3>\r\n<p>कोल और अन्य जनजातियों की पारंपरिक सामाजिक संरचना गैर-आदिवासी लोगों के आगमन से बाधित हुई, जो जनजातीय रीति-रिवाजों का सम्मान नहीं करते थे और अक्सर मूल निवासियों के साथ दुर्व्यवहार करते थे। कोल लोगों को उनकी बुनियादी गरिमा और अधिकारों से वंचित कर दिया गया, जिससे उनकी स्वायत्तता समाप्त हो गई और सांस्कृतिक क्षरण हुआ।</p>\r\n<h3>राजनीतिक कारण</h3>\r\n<p>ब्रिटिश कानून और न्यायिक नीतियों के लागू होने से वंशानुगत जनजातीय प्रमुखों की शक्ति को खतरा पैदा हो गया तथा जनजातियों के पारंपरिक शासन को नुकसान पहुंचा। ब्रिटिश औपनिवेशिक प्रशासन को आदिवासी लोगों की आवश्यकताओं और रीति-रिवाजों के प्रति विदेशी और असंवेदनशील माना जाता था।</p>\r\n<h3>सांस्कृतिक कारण</h3>\r\n<p>अन्य जनजातियों की तरह कोल में भी सामुदायिकता और स्वतंत्रता की प्रबल भावना थी, जो ब्रिटिश नीतियों के कारण खतरे में पड़ गयी। जनजातियों के बीच सांस्कृतिक एकजुटता ने उन बाहरी ताकतों के खिलाफ सामूहिक प्रतिरोध को बढ़ावा देने में मदद की, जो उनकी जीवन शैली को बदलना चाहती थीं।</p>\r\n<h2>विद्रोह का परिणाम</h2>\r\n<p>कोल विद्रोह के बाद कई घटनाएं घटीं, जिनका विद्रोह में शामिल जनजातीय समुदायों पर महत्वपूर्ण प्रभाव पड़ा।</p>\r\n<p>ब्रिटिश प्रशासन ने कोल विद्रोह को बर्बर तरीके से दबा दिया। हजारों आदिवासियों को मार डाला गया और उनके गांवों को नष्ट कर दिया गया। विद्रोह के नेता मारे गए या गिरफ्तार कर लिए गए, और उनकी संपत्ति को जब्त कर लिया गया।</p>\r\n<p>इस विद्रोह ने ब्रिटिश प्रशासन को आदिवासियों की समस्याओं की ओर ध्यान देने पर मजबूर किया। भूमि और कर व्यवस्था में कुछ सुधार किए गए, लेकिन ये सुधार बहुत छोटे और अस्थायी थे</p>\r\n<p>कोल विद्रोह ने आदिवासी समुदायों में अपनी स्वतंत्रता और अधिकारों के प्रति जागरूकता बढ़ाई। इसने उन्हें संगठित होकर अपने अधिकारों की रक्षा करने की प्रेरणा दी।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>कोल विद्रोह आदिवासी समाज के साहस और संघर्ष का प्रतीक था। यह ब्रिटिश शासन, ज़मींदारी प्रथा, और बाहरी हस्तक्षेप के खिलाफ अपनी स्वतंत्रता, संस्कृति और अधिकारों की रक्षा के लिए किया गया ऐतिहासिक आंदोलन था। इसने न केवल आदिवासी चेतना को जागृत किया बल्कि भविष्य के आंदोलनों के लिए प्रेरणा भी प्रदान की। हालांकि विद्रोह को दबा दिया गया, लेकिन इसने अंग्रेजों को आदिवासियों की समस्याओं पर ध्यान देने और प्रशासनिक सुधार करने के लिए मजबूर किया। कोल विद्रोह भारतीय इतिहास में अन्याय के खिलाफ एक संगठित प्रतिरोध की मिसाल है।</p>\r\n',5,'2025-01-29 06:24:06','2025-01-29 06:42:20','','Publish',0,'open',35,63),('चेरो राज की राजनीतिक उपलब्धियाँ और प्रशासनिक व्यवस्था पर प्रकाश डाले।','political-achievements-and-administrative-system-of-chero-raj',2,'<p>चेरो झारखंड की एक प्रमुख जनजाति चेरो है। चेरो चेरू और चेरवास के रूप में भी जाने जाते हैं। पलामू जिले में रहने वाले चेरों वाराहजार कहलाते हैं। वर्तमान समय में चेरो पलामू, लातेहार राँची, संथाल परगना में पाए जाते हैं। चेरो प्रमुख रूप से पुराने पलामू जिले में पाए जाते हैं। चेरो जनजाति को स्वयं को क्षत्रिय और चौहानवंशी राजपूत से संबंधित मानते हैं। वे स्वयं को चन्द्रवंशी भी कहते हैं।</p>\r\n<p>चेरो राज का उदय 16वीं शताब्दी के आसपास हुआ,चेरो शासकों ने अपने साम्राज्य को स्थापित करने के लिए जनजातीय समुदायों के साथ राजनीतिक गठजोड़ बनाए और बाहरी आक्रमणकारियों के खिलाफ अपनी सीमाओं की रक्षा के लिए एक संगठित सैन्य प्रणाली विकसित की। चेरो शासकों ने बाहरी आक्रमणों के खिलाफ अपने राज्य की सुरक्षा को सुनिश्चित करने के लिए एक मजबूत सैन्य ढाँचा स्थापित किया। उन्होंने अपने क्षेत्र में कई महत्वपूर्ण किलों का निर्माण किया, जैसे कि रोहतासगढ़, जो उनकी सैन्य शक्ति का प्रतीक था।</p>\r\n<p>बृजनाथ झा ने चेरो राज के बारे मे लिखते है- स्थानीय पंचायतों और सामुदायिक संगठनों की महत्वपूर्ण भूमिका थी। उनकी दृष्टि में, न्याय व्यवस्था को सुदृढ़ करने के लिए स्थानीय लोगों की भागीदारी सुनिश्चित की गई, जिससे न्याय और समानता का सिद्धांत लागू हो सका।</p>\r\n<h2>राजनीतिक उपलब्धियाँ</h2>\r\n<h3>साम्राज्य का विस्तार</h3>\r\n<p>चेरो राज के राजाओं ने समय-समय पर अपने साम्राज्य का विस्तार किया। यह न केवल सैनिक विजय के माध्यम से किया गया, बल्कि चतुर राजनीतिक गठबंधनों और विवाह संबंधों के माध्यम से भी। इन विस्तारों ने चेरो राज को न केवल भौगोलिक रूप से सशक्त बनाया, बल्कि इसे व्यापार और सांस्कृतिक आदान-प्रदान का केंद्र भी बना दिया।</p>\r\n<h3>संस्कृति और कला का संरक्षण</h3>\r\n<p>चेरो राज ने स्थानीय संस्कृति और कला को संरक्षित करने में महत्वपूर्ण भूमिका निभाई। इस दौरान, विभिन्न प्रकार के लोक संगीत, नृत्य और कला शैलियों का विकास हुआ। चेरो क्षेत्र की स्थापत्य कला और मंदिर निर्माण ने भी इस राज्य की सांस्कृतिक धरोहर को समृद्ध किया। चेरो राज के शासनकाल में स्थानीय त्योहारों और धार्मिक अनुष्ठानों का आयोजन किया जाता था, जो समाज के विभिन्न वर्गों के बीच एकता और समरसता को बढ़ावा देते थे।</p>\r\n<h3>आर्थिक विकास</h3>\r\n<p>चेरो राज ने कृषि और वाणिज्य में उल्लेखनीय प्रगति की। कृषि को बढ़ावा देने के लिए विभिन्न योजनाएँ बनाई गईं, जिससे उत्पादन में वृद्धि हुई। इसके अलावा, चेरो क्षेत्र के पास खनिज संसाधनों का भी लाभ उठाया गया। व्यापारिक संबंधों को बढ़ावा देने के लिए स्थानीय बाजारों का विकास किया गया, जो आर्थिक समृद्धि का आधार बने।</p>\r\n<h3>सामाजिक विकास</h3>\r\n<p>चेरो राज में विभिन्न जातियों और समुदायों के बीच सामाजिक विकास को बढ़ावा दिया गया। स्थानीय लोगों के बीच आपसी सहिष्णुता और सहयोग को प्रोत्साहित किया गया। चेरो राज ने विभिन्न धार्मिक समुदायों के बीच आपसी समझ और सद्भाव को बढ़ावा दिया, जिससे समाज में एकता और सामुदायिक भावना विकसित हुई।</p>\r\n\r\n<h2>प्रशासनिक व्यवस्था</h2>\r\n<p>चेरो राज की प्रशासनिक व्यवस्था प्रभावी और सुव्यवस्थित थी। यह प्रणाली स्थानीय लोगों की भागीदारी और सहयोग पर आधारित थी।</p>\r\n<p>चेरो राज का शासक राजा होता था, जो राज्य का सर्वोच्च मुखिया होता था। राजा के अधीन उपराजा और अन्य उच्चाधिकारी होते थे, जो विभिन्न क्षेत्रों का प्रशासन संभालते थे। राजा की सत्ता को जनता का समर्थन प्राप्त था, और वह अपने लोगों के कल्याण के प्रति जिम्मेदार था। यह व्यवस्था राज्य के प्रशासन को प्रभावी बनाने में महत्वपूर्ण थी।</p>\r\n<p>चेरो राज में कृषि से प्राप्त राजस्व का संग्रहण एक व्यवस्थित तरीके से किया जाता था। किसानों से उपज का एक हिस्सा टैक्स के रूप में लिया जाता था, जो राज्य के विकास और प्रशासन में उपयोग होता था। यह प्रणाली कृषि क्षेत्र को सुदृढ़ करने में मदद करती थी, जिससे किसानों को अपने उत्पादन को बढ़ाने के लिए प्रोत्साहन मिलता था।</p>\r\n<p>चेरो राज की सुरक्षा के लिए एक मजबूत सैन्य ढांचा था। राजा ने अपनी सेना का गठन किया, जिसमें स्थानीय युवाओं को भर्ती किया जाता था। यह सेना बाहरी आक्रमणों से राज्य की रक्षा करती थी और स्थानीय सुरक्षा सुनिश्चित करती थी। सैन्य व्यवस्था ने चेरो राज को राजनीतिक स्थिरता बनाए रखने में सहायता की।</p>\r\n<p>चेरो राज में अपने स्वयं के कानून और नियम होते थे, जो स्थानीय रीति-रिवाजों और परंपराओं के अनुसार बनाए जाते थे। ये कानून न केवल प्रशासनिक कार्यों को संचालित करते थे, बल्कि समाज में न्याय और समानता को भी सुनिश्चित करते थे। स्थानीय स्तर पर न्याय प्रदान करने के लिए विभिन्न न्यायालयों का गठन किया गया था।</p>\r\n<p>चेरो राज ने धार्मिक स्थलों और सांस्कृतिक समारोहों के संरक्षण और प्रबंधन में भी महत्वपूर्ण भूमिका निभाई। स्थानीय त्योहारों और धार्मिक अनुष्ठानों को बढ़ावा देने के लिए राजकीय समर्थन प्रदान किया गया, जिससे समाज में एकजुटता और सामुदायिक भावना को बढ़ावा मिला।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>चेरो राज की राजनीतिक उपलब्धियाँ और प्रशासनिक व्यवस्था ने इसे झारखंड के इतिहास में एक महत्वपूर्ण स्थान प्रदान किया। इस राज्य ने अपनी स्वायत्तता, सांस्कृतिक धरोहर, और सामाजिक समरसता के माध्यम से स्थानीय लोगों के जीवन को समृद्ध किया। चेरो राज की उपलब्धियाँ आज भी स्थानीय लोगों के लिए प्रेरणा का स्रोत हैं और यह दर्शाती हैं कि एक संगठित और प्रभावी प्रशासनिक व्यवस्था कैसे सामाजिक और आर्थिक विकास को प्रोत्साहित कर सकती है।</p>\r\n',10,'2025-01-29 08:49:12','2025-01-29 08:55:20','','Publish',0,'open',9,64),('टाना भगत के जीवन परिचय और आंदोलन पर प्रकाश डाले।','biography-and-movement-of-tana-bhagat',2,'<p>टाना भगत झारखंड के इतिहास में एक महत्वपूर्ण व्यक्तित्व हैं, जिन्होंने आदिवासी समाज के उत्थान, उनके अधिकारों और शोषण के खिलाफ आवाज उठाने के लिए एक अद्वितीय आंदोलन का नेतृत्व किया। उनका जन्म 19वीं शताब्दी के उत्तरार्ध में चोटनागपुर क्षेत्र के एक छोटे से गांव में एक ओरांव आदिवासी परिवार में हुआ था। टाना भगत का जीवन सरलता, सत्य और अहिंसा के प्रति समर्पित था। उन्होंने अपने समुदाय को विदेशी शोषण और स्थानीय जमींदारों की अन्यायपूर्ण नीतियों के खिलाफ संगठित किया।</p>\r\n<h2>टाना भगत के जीवन परिचय</h2>\r\n<p>टाना भगत का जन्म एक गरीब और पारंपरिक आदिवासी परिवार में हुआ था। उनका मूल नाम क्या था, यह पूरी तरह से स्पष्ट नहीं है, लेकिन उन्हें \"टाना\" नाम उनके अनुयायियों और उनके द्वारा चलाए गए आंदोलन की पहचान के कारण मिला। टाना भगत बचपन से ही धार्मिक प्रवृत्ति के थे और अपनी संस्कृति और परंपराओं के प्रति गहरी निष्ठा रखते थे।</p>\r\n<p>उनका मुख्य उद्देश्य सामाजिक असमानता और आदिवासियों के शोषण के खिलाफ खड़ा होना था। उन्होंने देखा कि अंग्रेजों की नीतियां और स्थानीय सामंतों का अत्याचार आदिवासी जीवन को दूभर बना रहा था।</p>\r\n<p>19वीं शताब्दी के अंत और 20वीं शताब्दी की शुरुआत में, भारत में ब्रिटिश औपनिवेशिक शासन का प्रभाव अपने चरम पर था। इस दौरान, झारखंड क्षेत्र के आदिवासियों को कई समस्याओं का सामना करना पड़ा रहा था।</p>\r\n<ul>\r\n    <li><p>स्थानीय जमींदारों द्वारा आदिवासी किसानों पर भारी कर लगाए जाते थे। भूमि को छीन लिया जाता था और शोषण किया जाता था।</p></li>\r\n    <li><p>ब्रिटिश सरकार ने आदिवासियों की भूमि पर अधिकार करने और उनकी स्वतंत्रता को सीमित करने की नीति अपनाई।</p></li>\r\n    <li><p>आदिवासी समाज की परंपराओं और धार्मिक रीति-रिवाजों पतन किया जा रहा था।</p></li>\r\n</ul>\r\n<p>उनका बचपन कठोर परिस्थितियों में गुजरा, जहां उन्होंने अपने समाज की समस्याओं को निकट से देखा। आदिवासियों की भूमि उनसे छीन ली जाती थी, और उन्हें अत्यधिक कर चुकाने के लिए मजबूर किया जाता था। अंग्रेजी शासन की कठोर नीतियों और स्थानीय जमींदारों की लूट ने आदिवासियों के जीवन को दयनीय बना दिया था।</p>\r\n<p>टाना भगत के जीवन पर गहरी धार्मिक और सामाजिक विचारधाराओं का प्रभाव पड़ा। वह सादगी, ईमानदारी और सत्य में विश्वास रखते थे। उन्होंने महसूस किया कि आदिवासी समाज को संगठित और जागरूक किए बिना इन समस्याओं का समाधान संभव नहीं है। उनके इसी दृष्टिकोण ने उन्हें एक महान नेता और समाज सुधारक के रूप में उभारा।</p>\r\n\r\n<h2>टाना भगत आंदोलन</h2>\r\n<p>ऐसी मान्यता है कि गुरू ग्राम हेसराग के तुरिया भगत से उन्हें तंत्र-मंत्र विद्या सीखने के क्रम में 1914 ई. में आत्मबोध हुआ। ब्रिटिश राज्य के अत्याचार, बेगारी, अंधविश्वास आदि से पीड़ित आदिवासी समुदाय को राह दिखाने का संकल्प ले कर जतरा उरांव अब जतरा भगत बन गया। इस तरह टाना भगत आदोलन का प्रारंभ अप्रैल 1914 ई. में हुआ। \"टाना भगत आंदोलन\" के नाम से जाना जाता है। यह आंदोलन न केवल अंग्रेजों के अत्याचारों के खिलाफ था, बल्कि आदिवासी समाज के भीतर व्याप्त सामाजिक बुराइयों को समाप्त करने का भी एक प्रयास था। इस आंदोलन का उद्देश्य आदिवासियों को उनकी पारंपरिक जमीन और अधिकार वापस दिलाना था।</p>\r\n<p>टाना भगत ने महसूस किया कि आदिवासी समाज शराब और अन्य सामाजिक बुराइयों के कारण कमजोर हो रहा है। उन्होंने अपने अनुयायियों को इन बुराइयों को त्यागने और सत्य, अहिंसा और ईमानदारी के मार्ग पर चलने के लिए प्रेरित किया। उनके विचार महात्मा गांधी के सत्य और अहिंसा के सिद्धांतों से प्रभावित थे। उन्होंने अपने अनुयायियों को खादी पहनने और विदेशी वस्त्रों का बहिष्कार करने का संदेश दिया।</p>\r\n<ul>\r\n    <li><p>टाना भगत ने आदिवासी समाज को शराब और अन्य बुराइयों से मुक्त करने का प्रयास किया। उन्होंने सादा जीवन जीने और अपनी परंपराओं का पालन करने का संदेश दिया।</p></li>\r\n    <li><p>टाना भगत ने आदिवासियों को संगठित किया और उन्हें उनके अधिकारों के प्रति जागरूक किया। उन्होंने अंग्रेजी शासन के खिलाफ शांतिपूर्ण विरोध का नेतृत्व किया।</p></li>\r\n    <li><p>उन्होंने आदिवासी समाज को उनकी परंपराओं और संस्कृति के प्रति गर्व करने के लिए प्रेरित किया।</p></li>\r\n</ul>\r\n\r\n<p>टाना भगत का जीवन और उनका आंदोलन आज भी झारखंड और अन्य आदिवासी क्षेत्रों के लिए प्रेरणा का स्रोत है। उनका सत्य, अहिंसा और आत्म-सम्मान पर आधारित जीवन आज के समाज में भी प्रासंगिक है। उन्होंने दिखाया कि बिना हिंसा के भी बड़े बदलाव लाए जा सकते हैं।</p>\r\n<p>उनका आंदोलन झारखंड के इतिहास में एक महत्वपूर्ण स्थान रखता है। यह आंदोलन न केवल एक सामाजिक और सांस्कृतिक पुनरुत्थान का प्रतीक है, बल्कि यह आदिवासी समाज के संघर्ष और उनकी जीत की कहानी भी कहता है। उनका जीवन और उनका संघर्ष आदिवासी समाज के लिए एक प्रेरणादायक उदाहरण है।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>टाना भगत का जीवन और उनका आंदोलन आदिवासी समाज के संघर्ष और उनकी अस्मिता की रक्षा का प्रतीक है। उन्होंने दिखाया कि सादगी, सत्य और अहिंसा के माध्यम से शोषण और अन्याय का मुकाबला किया जा सकता है। उनका योगदान झारखंड के इतिहास में अमूल्य है और उनकी विरासत आने वाली पीढ़ियों को प्रेरणा देती रहेगी।</p>\r\n',7,'2025-01-29 08:49:12','2025-01-29 09:02:05','','Publish',0,'open',35,65),('इतिहास में स्त्री अध्ययन के लिये उदारवादी विचारधारा पर प्रकाश डालें','liberal-ideology-for-women-studies-in-history',2,'<p>उदारवादी विचारधारा का उदय 17वीं-18वीं शताब्दी के यूरोप में पुनर्जागरण और प्रबोधन काल में हुआ। यह विचारधारा स्वतंत्रता, समानता और व्यक्तिगत अधिकारों पर आधारित है। जॉन लॉक, जॉन स्टुअर्ट मिल, और मेरी वोल्स्टोनक्राफ्ट जैसे विचारकों ने इस विचारधारा को बढ़ावा दिया। स्त्री अध्ययन में उदारवाद महिलाओं के अधिकारों की मांग करता है और समाज में महिलाओं के लिए समान अवसर प्रदान करने की वकालत करता है।</p>\r\n<p>18वीं शताब्दी के दौरान मेरी वोल्स्टोनक्राफ्ट की पुस्तक \"<strong>A Vindication of the Rights of Woman</strong>\" ने स्त्री अधिकारों की चर्चा को व्यापक रूप से शुरू किया।</p>\r\n<p>उदारवाद के मुख्य सिद्धांत</p>\r\n<ul>\r\n    <li><p>हर व्यक्ति को अपनी इच्छा और क्षमता के अनुसार जीवन जीने का अधिकार है।</p></li>\r\n    <li><p>सभी नागरिकों को कानून के समक्ष समान माना जाना चाहिए।</p></li>\r\n    <li><p>शिक्षा को स्वतंत्रता और सशक्तिकरण का आधार माना गया है।</p></li>\r\n    <li><p>उदारवाद आर्थिक क्षेत्र में भी महिलाओं के अधिकारों की वकालत करता है।</p></li>\r\n</ul>\r\n\r\n\r\n<h2>शिक्षा और स्त्री सशक्तिकरण</h2>\r\n<p>शिक्षा को उदारवादी विचारधारा ने महिलाओं के सशक्तिकरण का सबसे बड़ा साधन माना। औपनिवेशिक भारत और आधुनिक युग में, महिलाओं के लिए शिक्षा की वकालत करने वाले सुधारक उदारवादी दृष्टिकोण से प्रेरित थे। शिक्षा महिलाओं को अपनी परिस्थितियों को समझने और अपने अधिकारों के लिए लड़ने का ज्ञान प्रदान करती है।\r\n</p><p>इतिहास में महिलाएं लंबे समय तक शिक्षा से वंचित रही थीं, जिससे उन्हें समाज में समान भागीदारी का अवसर नहीं मिला। परंतु 19वीं और 20वीं शताब्दी में शिक्षा के प्रसार ने महिलाओं के लिए नए द्वार खोले। महिलाओं ने शिक्षित होकर विभिन्न क्षेत्रों में अपनी पहचान बनाई और पारंपरिक सीमाओं को चुनौती दी।</p>\r\n\r\n<h2>कानूनी और सामाजिक सुधार</h2>\r\n<p>उदारवादी विचारधारा ने महिलाओं के अधिकारों को कानूनी रूप से सुरक्षित करने के लिए सुधारों की वकालत की। प्राचीन और मध्यकालीन समाजों में महिलाओं को संपत्ति, विवाह, और तलाक के मामलों में सीमित अधिकार प्राप्त थे। परंतु उदारवाद ने यह सिद्धांत प्रस्तुत किया कि महिलाएं भी समाज के समान नागरिक हैं और उन्हें समान कानूनी अधिकार मिलने चाहिए।</p>\r\n<p>इस दृष्टिकोण के आधार पर, कई देशों में महिलाओं को संपत्ति अधिकार, तलाक का अधिकार, और वैवाहिक जीवन में समानता की गारंटी दी गई। इसके अतिरिक्त, बाल विवाह, सती प्रथा, और दहेज प्रथा जैसी कुप्रथाओं को समाप्त करने के लिए भी उदारवादी दृष्टिकोण ने महत्वपूर्ण भूमिका निभाई।</p>\r\n\r\n<h2>राजनीतिक भागीदारी और महिलाओं का आंदोलन</h2>\r\n<p>राजनीतिक क्षेत्र में महिलाओं की भागीदारी उदारवादी विचारधारा का एक और महत्वपूर्ण पहलू है। 19वीं और 20वीं शताब्दी के दौरान, महिलाओं ने मताधिकार के अधिकार के लिए संघर्ष किया। यूरोप और अमेरिका में चलने वाले महिला आंदोलन, जैसे सफरेज मूवमेंट, उदारवादी विचारों से प्रेरित थे।\r\n</p><p>राजनीतिक भागीदारी से महिलाओं को अपने मुद्दों को उठाने और निर्णय लेने की प्रक्रिया में शामिल होने का अवसर मिला। यह आंदोलन भारत जैसे देशों में भी प्रेरणा बना, जहां महिलाओं ने स्वतंत्रता संग्राम और सामाजिक सुधार आंदोलनों में सक्रिय भूमिका निभाई।</p>\r\n\r\n<h2>आर्थिक स्वतंत्रता और आत्मनिर्भरता</h2>\r\n<p>उदारवादी विचारधारा ने महिलाओं की आर्थिक स्वतंत्रता पर भी बल दिया। यह विचारधारा मानती है कि महिलाएं आर्थिक रूप से स्वतंत्र होकर अपने जीवन में बेहतर निर्णय ले सकती हैं। औद्योगिक क्रांति के बाद, महिलाओं को रोजगार के अधिक अवसर मिलने लगे।</p>\r\n<p>महिलाओं के लिए आर्थिक स्वतंत्रता उनके सामाजिक और पारिवारिक जीवन में भी बदलाव लेकर आई। उन्होंने केवल गृहिणी की पारंपरिक भूमिका को छोड़कर विभिन्न व्यवसायों और उद्योगों में अपना स्थान बनाया।</p>\r\n\r\n<h2>आलोचनात्मक विश्लेषण</h2>\r\n<p>हालांकि उदारवादी विचारधारा ने स्त्री अध्ययन में कई सकारात्मक परिवर्तन किए, फिर भी इसके कुछ सीमित पहलू भी हैं। यह विचारधारा मुख्य रूप से मध्यम और उच्च वर्ग की महिलाओं पर केंद्रित रही है, जिससे निम्न वर्ग और ग्रामीण महिलाओं की समस्याएं अक्सर उपेक्षित रह जाती हैं।</p>\r\n<p>इसके अलावा, उदारवादी दृष्टिकोण पितृसत्तात्मक संरचनाओं को पूरी तरह से चुनौती देने में असमर्थ रहा है। यह महिलाओं के अधिकारों के लिए कानूनी और सामाजिक सुधारों की वकालत करता है, लेकिन जमीनी स्तर पर गहरे बदलाव लाने के लिए पर्याप्त प्रयास नहीं कर पाता।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>स्त्री अध्ययन में उदारवादी विचारधारा का योगदान अमूल्य है। इसने महिलाओं के अधिकारों, शिक्षा, और समानता की दिशा में समाज को एक नई सोच दी। हालांकि इसमें कुछ सीमाएं हैं, फिर भी यह विचारधारा इतिहास में महिलाओं के सशक्तिकरण और सामाजिक बदलाव में महत्वपूर्ण भूमिका निभाती है। उदारवाद के माध्यम से महिलाएं अपने अधिकारों के प्रति जागरूक हुईं और उन्होंने समाज में अपनी स्थिति को मजबूत करने के लिए संघर्ष किया।\r\n</p><p>यह विचारधारा आज भी महिलाओं के अधिकारों और समानता के लिए एक प्रेरणा स्रोत बनी हुई है।</p>',35,'2025-01-29 08:49:12','2025-01-29 09:06:03','','Publish',0,'open',0,66),('प्राचीन भारत में महिलाओं की स्थिति पर प्रकाश डालें।','status-of-women-in-ancient-india',2,'<p>प्राचीन भारतीय समाज में महिलाओं की स्थिति के बारे में ज्यादा जानकारी नहीं मिलती है क्योंकि प्राचीन भारत में नारी की सामाजिक आर्थिक और राजनीतिक स्थिति पर कम शोध हुआ है इसके विषय में विद्वानों में भी मतभेद है परंतु नारियों की स्थिति के बारे में साहित्य में कुछ जानकारी उपलब्ध है जिसके द्वारा हमें उनकी स्थिति के बारे में पता चलता है</p>\r\n<p>प्राचीन समय में महिलाओं को समाज के हर क्षेत्र में उच्च स्थान प्राप्त था और उन्हें बराबरी का दर्जा प्राप्त था । वैदिक ग्रन्थों से स्पष्ट होता है कि नारियों को शिक्षा, यज्ञ, ज्ञान प्राप्ति आध्यात्म आदि विभिन्न क्षेत्रों में स्वतंत्रता व समानता प्राप्त थी । डाo लता सिंघल ने अपनी पुस्तक \"भारतीय संस्कृति में नारी\" में नारी की स्थिति का सटीक चित्रण किया है।</p>\r\n<p>हालांकि परोक्ष रूप से तो नारी को बराबर के अधिकार दिये गए, देवी का दर्जा दिया गया लेकिन वास्तविक रूप में तो सारे अधिकार गौण रूप में ही प्राप्त हैं। यदि प्राचीन समय से पूर्व मध्य युग तक देखें तो भारतीय समाज में नारी को बहुत उच्च दर्जा प्राप्त था। पूर्ण सामाजिक, राजनैतिक, धार्मिक, आर्थिक अधिकार प्राप्त थे। लेकिन मुगलों के आगमन के साथ ही नारी की स्थिति में गिरावट आती चली गई, नारी घर में कैद होती गई, नारी के अधिकार व स्वतंत्रता छिनती चली गई।</p>\r\n<h2>सामाजिक स्थिति</h2>\r\n<p>अति प्राचीन काल में भारतीय समाज में स्त्रियों को आदर व सम्मान प्राप्त था। स्त्री-पुरूष में कोई भेद नहीं था। दोनों की सामाजिक परिस्थितियाँ समान थी तथा प्रत्येक सामाजिक धार्मिक कार्यों में उनकी उपस्थिति अनिवार्य थी। लड़कियाँ ब्रह्मचर्य का पालन करती थी। आश्रम में शिक्षा प्राप्त करती थी। सह शिक्षा का अधिकार था। अध्ययन के पश्चात कुछ स्त्रियाँ अध्यापन कार्य करती थीं। उपनिषदों में स्त्री शिक्षिकाओं का वर्णन है। शिक्षिकाओं को \"उपाध्याया\" कहा जाता था। परन्तु शिक्षिकाओं की संख्या अधिक नहीं थी।</p>\r\n<p>वैदिक काल में स्त्रियां बुद्धि व शिक्षा में अग्रणी थी। यजुर्वेद के अनुसार इस काल में कन्या का उपनयन संस्कार होता था। उसे सन्ध्या करने का अधिकार था। रामायण में विवरण है कि सीता नियमित रूप से संध्या पाठ करती थी। वे तर्क शास्त्र व वाद-विवादों में पारंगत थी। इस काल में सुलभा, गार्गी, मैत्री आदि के नाम अविस्मरणीय हैं।</p>\r\n<p>प्राचीन युग में भारत की स्त्रियों को शिक्षा व यज्ञ करने का अधिकार प्राप्त था। प्रत्येक सामाजिक व धार्मिक कार्यों में स्त्रियों की उपस्थिति अनिवार्य थी। उस समय नियोग प्रथा बहु प्रचलित थी। वैदिक युग में विधवा को पुनर्विवाह प्रचलित था, दूसरा समाज में नियोग प्रथा भी प्रचलित थी। जिसके द्वारा विधवा पुत्र की प्राप्ति कर सकती थी। पर्दा प्रथा का नामोनिशान नहीं था।  समाज में एक विवाह प्रथा प्रचलित थी। इस काल में स्त्रियों को सामाजिक धार्मिक व राजनीति आदि के क्षेत्रों में पुरुषों के समान अधिकार प्राप्त थे।</p>\r\n<p>उत्तर वैदिक व महाकाव्य काल में स्त्रियों के साथ भेदभाव की स्थिति में परिवर्तन आने लगा। उनकी धार्मिक, सामाजिक, राजनैतिक, आर्थिक स्थितियों पर प्रतिबंध लगने लगा। उन्हें वेद पढने व मंत्रोचारण के उपयुक्त नहीं समझा गया।</p>\r\n<h2>आर्थिक स्थिति</h2>\r\n<p>उस समय की अर्थव्यवस्था में भी नारी की महत्वपूर्ण भूमिका थी। गृहकार्यों से लेकर कृषि, प्रशासन एवं यज्ञ कर्म से लेकर आध्यात्म साधना तक के क्षेत्र उनके विशिष्ट व्यक्तित्व प्रतिभा एवं कौशल की छाप से अछूते नहीं थे। अर्थव्यवस्था में भी नारी की महत्वपूर्ण भूमिका थी।</p>\r\n<p>प्राचीन काल में आर्थिक जीवन का मुख्य आधार कृषि था। नारी कृषि व श्रम के कार्यों में पर्याप्त रूचि लेती थी। नारियां अपने गृह कार्य खाना बनाना, बर्तन साफ करना, घर की सफाई करना आदि के साथ-साथ, कृषि व बाजार के कार्यों में पति की सहायता करती थी। दूध-दही के विक्रय करने से उसकी आर्थिक व सामाजिक स्थिति सुदृढ़ होती थी। गणिकायें व देवदासियां भी समाज का एक अंग थी। ये संगीत, नृत्य, श्रंगार, गायन आदि में कुशल होती थी। नृत्य-संगीत इनकी स्वतन्त्र जीविका के साधन थे।</p>\r\n<p>मध्यकाल में महिलाओं की स्थिति और भी दयनीय हो गई। सती प्रथा, बाल विवाह और पर्दा प्रथा जैसी प्रथाएँ अधिक प्रचलित हुईं। हालांकि, इस दौरान मीराबाई और रजिया सुल्तान जैसी महिलाओं ने अपनी अद्भुत क्षमता और प्रभाव से समाज में अपनी जगह बनाई।</p>\r\n<p>प्राचीन भारत में महिलाओं की स्थिति को समय और समाज के अनुसार ढालते हुए देखा गया। वैदिक काल में उनकी स्थिति गौरवपूर्ण थी, लेकिन बाद के समय में पितृसत्ता के कारण उनके अधिकार और स्वतंत्रता सीमित हो गए।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>प्राचीन भारत में महिलाओं की स्थिति काल और परिस्थिति के अनुसार बदलती रही। वैदिक काल में महिलाओं का दर्जा ऊँचा था, लेकिन बाद के समय में उनके अधिकार सीमित होते गए। इसके बावजूद, भारत के इतिहास में कई महिलाएँ प्रेरणा स्रोत बनीं।</p>\r\n',53,'2025-01-29 08:49:12','2025-01-29 09:27:59','','Publish',0,'open',19,67),('मध्यकालीन भारत में महिलाओं की शिक्षा की स्थिति','status-of-womens-education-in-medieval-india',2,'<p>मध्यकालीन भारत में शिक्षा मुख्यत विदेशी आक्रमणों से प्रभावित थी। मध्यकाल में कई व्यापारी और शासक भारत आए और अपनी संस्कृति और परंपरा के साथ-साथ शिक्षा की प्रक्रिया भी लेकर आए। भारतीय समाज ने उस ज्ञान को आत्मसात किया और देश के लोगों में उसका प्रसार किया। हालाँकि, इन विदेशी आक्रमणों के परिणामस्वरूप मध्यकाल में महिलाओं की स्थिति में गिरावट आई। भारत में महिला साक्षरता दर पुरुष साक्षरता दर से कम थी। मध्यकालीन भारत में महिला शिक्षा को बहुत नुकसान उठाना पड़ा।</p>\r\n<p>प्राचीन भारतीय ग्रंथों में महिलाओं को समाज के कमजोर वर्ग के रूप में वर्णित किया गया है। उन्हें शारीरिक और सामाजिक रूप से कमज़ोर माना जाता था। इस प्रकार, हालाँकि वैदिक काल में महिलाओं को समान अधिकार दिए गए थे, लेकिन समय के साथ उनकी स्थिति खराब होती गई। मध्यकालीन समाज असमानताओं के अधीन थे और उन पर अत्याचार भी किया जाता था। ऐतिहासिक रूप से, मध्यकाल को भारत में महिलाओं के लिए \'अंधकार युग\' के रूप में जाना जाता है। मध्यकालीन भारत में, महिलाओं को \'पर्दा\' (एक घूंघट) प्रणाली से परिचित कराया गया था। इसके अलावा, समाज में कई बुराइयाँ शुरू हुईं। मध्यकालीन भारत में बाल विवाह, सती, जौहर जैसी सामाजिक कुप्रथाएं महिला शिक्षा पर प्रतिबंध थीं।</p>\r\n\r\n<h2>प्रारंभिक मध्यकालीन</h2>\r\n<p>प्रारंभिक मध्यकालीन भारत में महिलाओं की शिक्षा का मुख्य उद्देश्य धार्मिक और पारिवारिक कर्तव्यों की पूर्ति करना था। महिलाओं को घर पर ही धार्मिक ग्रंथों जैसे रामायण, महाभारत और पुराणों का अध्ययन कराया जाता था। उच्च वर्ग की महिलाओं को संगीत, कला, और साहित्य का प्रशिक्षण दिया जाता था।</p>\r\n<p>इस युग में राजघरानों की महिलाएं शिक्षित थीं। वे राज्य प्रशासन, युद्ध कला, और कूटनीति में भी रुचि रखती थीं। \"प्रथ्वीराज चौहान की पत्नी संयोगिता\" इसका एक उदाहरण हैं। बौद्ध और जैन परंपराओं में महिलाओं की शिक्षा को प्रोत्साहन मिला। बौद्ध विहारों में महिलाओं को दर्शन, तर्कशास्त्र, और व्याकरण की शिक्षा दी जाती थी।</p>\r\n\r\n<h2>उत्तर मध्यकालीन</h2>\r\n<p>उत्तर मध्यकालीन भारत में मुस्लिम शासन के प्रभाव के कारण महिलाओं की शिक्षा पर और अधिक प्रतिबंध लगाए गए। पर्दा प्रथा का प्रचलन बढ़ा, जिसने महिलाओं को सार्वजनिक जीवन और शिक्षा से दूर कर दिया। उच्च वर्ग की मुस्लिम महिलाओं को मदरसों में कुरान और अरबी भाषा की शिक्षा दी जाती थी। उन्हें धार्मिक अध्ययन के साथ-साथ काव्य और संगीत का भी ज्ञान दिया जाता था। रजिया सुल्तान जैसी शिक्षित महिलाओं ने इस धारणा को चुनौती दी। वह न केवल शिक्षित थीं, बल्कि कुशल प्रशासक भी थीं।</p>\r\n<p>भक्ति आंदोलन ने महिलाओं को शिक्षा के क्षेत्र में प्रेरित किया। इस आंदोलन ने महिलाओं को साहित्य और काव्य में योगदान देने का अवसर प्रदान किया। मीराबाई, ललद्यद, और संत सहजोबाई जैसी महिलाएं इस काल की प्रमुख कवयित्रियां थीं।</p>\r\n<p>मध्यकालीन भारत में महिला शिक्षा बाधित थी क्योंकि मुस्लिम पुरुष भी सामान्य रूप से कम शैक्षिक योग्यता के अधीन थे। दूसरी ओर, मध्यकालीन काल में कई महिलाओं ने कला, साहित्य, संगीत में उत्कृष्टता हासिल की। ​​मध्यकालीन काल में महिलाओं ने शासक के रूप में भी काम किया। रजिया सुल्तान मध्य युग में दिल्ली की गद्दी पर राज करने वाली एकमात्र महिला शासक थीं। गोंड रानी दुर्गावती ने मुगल सम्राट अकबर के सेनापति आसफ अली से युद्ध हारने से पहले पंद्रह वर्षों तक शासन किया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>मध्यकालीन भारत में महिलाओं की शिक्षा की स्थिति में गिरावट और सुधार दोनों देखने को मिले। जहां सामाजिक रूढ़ियों और धार्मिक परंपराओं ने उन्हें शिक्षा से दूर रखा, वहीं भक्ति आंदोलन और कुछ प्रगतिशील परंपराओं ने महिलाओं को प्रेरित किया। हालांकि, औपचारिक शिक्षा का व्यापक प्रसार औपनिवेशिक काल और आधुनिक युग में ही संभव हुआ।</p>\r\n<p>यह स्पष्ट है कि मध्यकालीन भारत में महिलाओं की शिक्षा की स्थिति समाज, धर्म, और राजनीति के गहरे प्रभावों के कारण सीमित थी। फिर भी, इस समय की कुछ शिक्षित महिलाओं ने अपनी प्रतिभा और शक्ति से इतिहास में अपनी जगह बनाई।</p>\r\n',16,'2025-01-29 08:49:12','2025-01-29 16:26:55','','Publish',0,'open',19,68),('भारतीय राजनीति में महिला आंदोलन पर प्रकाश डालिए।','political-participation-of-women-in-the-national-movement',2,'<p>राष्ट्रीय आंदोलन में महिलाओं की राजनीतिक भागीदारी भारतीय स्वतंत्रता संग्राम का एक महत्वपूर्ण पहलू थी। महिलाओं ने अपने साहस, संकल्प और सक्रियता से इस आंदोलन को गति दी। उनकी भूमिका कई स्तरों पर रही, जैसे कि सत्याग्रह, असहयोग आंदोलन, सविनय अवज्ञा आंदोलन, और विभाजन-विरोधी गतिविधियाँ। उनके योगदान ने इस आंदोलन को आकार देने और भारत के लिये स्वतंत्रता हासिल करने में महत्त्वपूर्ण भूमिका निभाई थी।</p>\r\n\r\n<p>ब्रिटिश औपनिवेशिक शासन से स्वतंत्रता हासिल करने के उद्देश्य से शुरू किया गया भारतीय राष्ट्रीय आंदोलन एक राजनीतिक और सामाजिक संघर्ष था। यह आंदोलन एक लंबा और जटिल संघर्ष था जो 19वीं शताब्दी के अंत से लेकर 1947 तक जारी रहा था। भारतीय महिलाओं ने नमक सत्याग्रह और भारत छोड़ो आंदोलन जैसे अहिंसक प्रतिरोध आंदोलनों में सक्रिय रूप से भाग लिया था।</p>\r\n<p>उदाहरण के लिये अरुणा आसफ अली और सुचेता कृपलानी जैसी महिलाएँ भारत छोड़ो आंदोलन की प्रमुख नेता थीं और उन्होंने बड़े पैमाने पर प्रदर्शनों और हड़तालों में महत्त्वपूर्ण भूमिका निभाई थी।</p>\r\n\r\n<p>भारतीय महिलाएँ बड़े पैमाने पर प्रदर्शनों और हड़तालों में शामिल हुई थीं और इन्होंने औपनिवेशिक शासन के खिलाफ विरोध के रूप में ब्रिटिश वस्तुओं का बहिष्कार किया था। उदाहरण के लिये महात्मा गांधी की पत्नी कस्तूरबा गांधी ने नमक सत्याग्रह में भाग लिया था जिसके कारण उन्हें कैद कर लिया गया था।</p>\r\n<p>भारतीय महिलाएँ विभिन्न भूमिगत गतिविधियों में शामिल हुई थीं। इसमें उपनिवेश विरोधी लेखन और इसका प्रसार शामिल है जिसने स्वतंत्रता आंदोलन के बारे में जागरूकता फैलाने में महत्त्वपूर्ण भूमिका निभाई थी। उदाहरण के लिये आजाद हिंद फौज का हिस्सा रही कैप्टन लक्ष्मी सहगल जैसी महिलाओं ने भूमिगत आंदोलन में महत्त्वपूर्ण भूमिका निभाई थी।</p>\r\n<p>भारतीय महिलाओं ने राजनीतिक कैदियों को सहायता प्रदान करने के साथ स्वतंत्रता आंदोलन हेतु धन संग्रह करने वाली गतिविधियों में भाग लिया था। उदाहरण के लिये कमलादेवी चट्टोपाध्याय जैसी महिलाओं ने राजनीतिक कैदियों और उनके परिवारों के लिये राहत प्रयासों की दिशा में महत्त्वपूर्ण भूमिका निभाई थी।</p>\r\n\r\n<p>स्वतंत्रता संग्राम के दौरान भारतीय महिलाओं ने सामाजिक सुधार आंदोलनों में शामिल होने के साथ महिलाओं के अधिकार, शिक्षा और गरीबी उन्मूलन जैसे मुद्दों के समाधान की दिशा में काम किया था।</p>\r\n<p>उदाहरण के लिये सरोजिनी नायडू और एनी बेसेंट जैसी महिलाएँ महिला अधिकार आंदोलन की प्रमुख नेता थीं और उन्होंने महिला सशक्तिकरण में महत्त्वपूर्ण भूमिका निभाई थी।</p>\r\n\r\n<p>भारत के स्वतंत्रता संग्राम में महिलाओं की भूमिका अतुलनीय और महत्त्वपूर्ण थी लेकिन उनके समक्ष कुछ चुनौतियाँ भी थीं जैसे-</p>\r\n\r\n<ul>\r\n    <li><p>महिलाओं को अक्सर दोयम दर्जे के नागरिक के रूप में देखा जाता था।</p></li>\r\n    <li><p>सांस्कृतिक और सामाजिक बाधाओं ने महिलाओं की गतिशीलता और सार्वजनिक जीवन में इनकी भागीदारी को सीमित कर दिया था।</p></li>\r\n    <li><p>शिक्षा और राजनीतिक स्तर पर इनकी कम भागीदारी थी।</p></li>\r\n    <li><p>आर्थिक और सामाजिक बाधाओं जैसे- गरीबी, सामाजिक कलंक और भेदभाव एवं शारीरिक हिंसा तथा दुर्व्यवहार से राष्ट्रीय आंदोलन में महिलाओं की भागीदारी सीमित हुई थी।</p></li>\r\n</ul>\r\n<p>कई चुनौतियों का सामना करने के बावजूद, भारतीय महिलाओं ने भारतीय राष्ट्रीय आंदोलन में महत्त्वपूर्ण योगदान दिया था। उनके प्रयासों और बलिदानों ने भारत के लिये स्वतंत्रता हासिल करने और आंदोलन को आकार देने में महत्त्वपूर्ण भूमिका निभाई थी। राष्ट्रीय आंदोलन में भारतीय महिलाओं की भूमिका, विपरीत परिस्थितियों में महिलाओं की क्षमता और साहस के रूप में प्रेरणा का परिचायक है</p>।\r\n',11,'2025-01-29 08:49:12','2025-01-29 16:29:20','','Publish',0,'open',35,69),('स्वतंत्र भारत में महिलाओं की संवैधानिक स्थिति का वर्णन।','constitutional-status-of-women-in-independent-india',2,'<p>स्वतंत्र भारत में महिलाओं की संवैधानिक स्थिति एक व्यापक और महत्वपूर्ण विषय है। भारतीय संविधान ने महिलाओं के अधिकारों को सुनिश्चित करने और उन्हें समाज में समान अवसर और सम्मान प्रदान करने के लिए अनेक प्रावधान किए हैं। इन प्रावधानों का उद्देश्य महिलाओं को सामाजिक, आर्थिक, राजनीतिक और सांस्कृतिक दृष्टि से समानता दिलाना है।</p>\r\n<p>भारतीय संविधान, जिसे 26 जनवरी 1950 को लागू किया गया, ने महिलाओं को उनके अधिकारों को सुनिश्चित करने के लिए अनेक विशेष प्रावधान किए हैं। संविधान के अनुसार महिलाओं को पुरुषों के समान अधिकार प्राप्त हैं। यह एक महत्वपूर्ण कदम था क्योंकि भारतीय समाज में लंबे समय तक महिलाओं को भेदभाव और असमानता का सामना करना पड़ा था।</p>\r\n<p>संविधान के अनुच्छेद 14 में सभी नागरिकों को कानून के समक्ष समानता और कानून का समान संरक्षण प्राप्त करने का अधिकार दिया गया है। यह प्रावधान महिलाओं को पुरुषों के समान स्थान और सम्मान सुनिश्चित करता है। इसके साथ ही अनुच्छेद 15 में लिंग, धर्म, जाति, या जन्म स्थान के आधार पर भेदभाव को निषिद्ध किया गया है।</p>\r\n<p>स्वतंत्रता के बाद, भारतीय सरकार ने महिलाओं के अधिकारों और उनकी सुरक्षा के लिए कई कानूनी सुधार किए। ये सुधार महिलाओं की सामाजिक स्थिति को सुधारने और उन्हें न्याय दिलाने के लिए आवश्यक थे।</p>\r\n<p>दहेज निषेध अधिनियम (1961), इस अधिनियम का उद्देश्य दहेज प्रथा को समाप्त करना था, जो महिलाओं के लिए एक प्रमुख सामाजिक समस्या थी। दहेज के कारण होने वाली हिंसा और उत्पीड़न को रोकने के लिए इस कानून का निर्माण किया गया।</p>\r\n<p>घरेलू हिंसा से संरक्षण अधिनियम (2005), इस कानून के तहत महिलाओं को घरेलू हिंसा से बचाने के लिए कानूनी सुरक्षा प्रदान की गई। यह कानून महिलाओं को उनके जीवन, स्वास्थ्य और गरिमा की रक्षा सुनिश्चित करता है।</p>\r\n<p>कार्यस्थल पर यौन उत्पीड़न की रोकथाम (2013), विशाखा गाइडलाइंस के आधार पर यह कानून महिलाओं को कार्यस्थल पर यौन उत्पीड़न से बचाने के लिए बनाया गया। यह कानून महिलाओं को उनके अधिकारों और सुरक्षा का एहसास कराता है।</p>\r\n<p>भारतीय समाज में महिलाओं की स्थिति में समय के साथ बदलाव आया है। प्राचीन काल में महिलाओं को समाज में उच्च स्थान प्राप्त था, लेकिन मध्यकाल में उनके अधिकार और स्वतंत्रता सीमित हो गए। स्वतंत्रता के बाद, महिलाओं को संविधान के माध्यम से समान अधिकार दिए गए, लेकिन सामाजिक रूढ़ियों और परंपराओं के कारण उनका प्रभाव सीमित रहा।</p>\r\n<p>स्वतंत्र भारत में शिक्षा और रोजगार के क्षेत्र में महिलाओं की भागीदारी बढ़ी है। सरकारी योजनाओं और नीतियों के कारण लड़कियों की शिक्षा को बढ़ावा मिला है। महिलाओं ने विभिन्न क्षेत्रों में अपनी उपस्थिति दर्ज कराई है, जैसे कि राजनीति, प्रशासन, विज्ञान, और व्यवसाय।</p>\r\n<p>भारतीय राजनीति में महिलाओं की भागीदारी बढ़ रही है। पंचायती राज संस्थाओं और शहरी निकायों में महिलाओं को आरक्षण दिया गया है, जिससे वे स्थानीय स्तर पर निर्णय लेने में सक्रिय भूमिका निभा रही हैं।</p>\r\n<p>महिलाओं को सशक्त बनाने के लिए सरकार और समाज ने अनेक प्रयास किए हैं। सरकारी योजनाओं, गैर-सरकारी संगठनों और सामाजिक आंदोलनों ने महिलाओं को जागरूक करने और उनके अधिकारों को सुनिश्चित करने में महत्वपूर्ण भूमिका निभाई है।</p>\r\n<p>महिला सशक्तिकरण के लिए कई योजनाएं लागू की गई हैं, जैसे बेटी बचाओ बेटी पढ़ाओ, महिला हेल्पलाइन योजना, और उज्ज्वला योजना। इन योजनाओं का उद्देश्य महिलाओं को शिक्षित करना, उन्हें आर्थिक रूप से स्वतंत्र बनाना और उनके स्वास्थ्य का ख्याल रखना है।</p>\r\n<p>महिलाओं के अधिकारों और उनकी स्थिति को सुधारने के लिए सामाजिक जागरूकता अभियान चलाए गए हैं। बाल विवाह, दहेज प्रथा, और घरेलू हिंसा जैसी सामाजिक बुराइयों के खिलाफ आवाज उठाई गई है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>स्वतंत्र भारत में महिलाओं की संवैधानिक स्थिति मजबूत और प्रभावी है। संविधान ने उन्हें समान अधिकार और अवसर प्रदान किए हैं। सरकार और समाज के प्रयासों से महिलाओं की स्थिति में सुधार हो रहा है। हालांकि, सामाजिक और सांस्कृतिक चुनौतियों के कारण उनके अधिकारों का पूर्ण उपयोग करना अभी भी एक बड़ी चुनौती है।</p>\r\n<p>महिलाओं को उनके अधिकारों के प्रति जागरूक करना और समाज में लैंगिक समानता सुनिश्चित करना सभी की जिम्मेदारी है। शिक्षा, आर्थिक सशक्तिकरण, और सामाजिक जागरूकता के माध्यम से एक ऐसा समाज बनाया जा सकता है, जहां महिलाएं अपने अधिकारों का पूर्ण उपयोग कर सकें और समाज के विकास में समान योगदान दे सकें</p>।\r\n',6,'2025-01-29 08:49:12','2025-01-29 16:31:52','','Publish',0,'open',19,70),('जल प्रबंधन क्या है? जल प्रबंधन का अर्थ और संसाध पर प्रकाश डाले।','what-is-water-management',2,'<p>जल प्रबंधन का अर्थ है जल संसाधनों का प्रभावी और स्थायी ढंग से उपयोग और संरक्षण करना। यह एक प्रक्रिया है जो जल की उपलब्धता, गुणवत्ता, वितरण और उपयोग के विभिन्न पहलुओं को संभालती है। जल प्रबंधन का उद्देश्य जल संसाधनों का संरक्षण करना, जल संकट को रोकना, जल प्रदूषण को कम करना और जल के उचित वितरण को सुनिश्चित करना है।</p>\r\n<p>भारत में बहने वाली मुख्य नदियों के अलावा हमें औसतन सालाना 1170 ml बारिश का पानी मिल जाता है</p>\r\n<p>जल प्रबंधन के तहत पानी से संबंधित जोखिमों जैसे- बाढ़, सूखा और संदूषण आदि के प्रबंधन को भी शामिल किया जाता है। यह प्रबंधन स्थानीय प्रशासन द्वारा भी किया जा सकता है और किसी व्यक्तिगत इकाई द्वारा भी। उचित जल प्रबंधन में जल का इस प्रकार प्रबंधन शामिल होता है कि सभी लोगों तक वह पर्याप्त मात्रा में पहुँच सके।</p>\r\n<p>जल, मानव जीवन के लिए एक अनिवार्य प्राकृतिक संसाधन है, जिसका उपयोग न केवल पीने के लिए, बल्कि कृषि और औद्योगिक प्रक्रियाओं में भी किया जाता है। विशेषज्ञों का मानना है कि जल प्रबंधन भविष्य की सबसे बड़ी चुनौतियों में से एक होगा। भारत जल संकट की गंभीर स्थिति का सामना कर रहा है, जहाँ नदियाँ प्रदूषित हो रही हैं, जल संचयन के तंत्र बिगड़ रहे हैं और भूजल स्तर लगातार घट रहा है।</p>\r\n<h2>जल प्रबंधन के प्रमुख तरीके</h2>\r\n<h3 class=\"atech\">अपशिष्ट जल प्रबंधन प्रणाली</h3>\r\n<p>उपयुक्त सीवेज सिस्टम साफ और सुरक्षित तरीके से अपशिष्ट जल के निपटान में मदद करते हैं। इसमें गंदे पानी को रिसाइकिल किया जाता है और उसे प्रयोग करने योग्य बनाया जाता है ताकि उसे वापस लोगों के घरों में पीने और घरेलू कार्यों में इस्तेमाल हेतु भेजा जा सके।</p>\r\n<h3 class=\"atech\">सिंचाई प्रणालियाँ</h3>\r\n<p>सूखा प्रभावित क्षेत्रों में फसलों के पोषण के लिये अच्छी गुणवत्ता वाली सिंचाई प्रणाली सुनिश्चित की जा सकती है। इन प्रणालियों को प्रबंधित किया जा सकता है ताकि पानी बर्बाद न हो और अनावश्यक रूप से पानी की आपूर्ति को कम करने से बचने के लिये इसके पुनर्नवीनीकरण या वर्षा जल का भी उपयोग कर सकते हैं।</p>\r\n<h3 class=\"atech\">प्राकृतिक जल निकायों की देखभाल करना</h3>\r\n<p>झीलों, नदियों और समुद्रों जैसे प्राकृतिक जल स्रोत काफी महत्त्वपूर्ण हैं। ताज़े पानी के पारिस्थितिकी तंत्र और समुद्री पारिस्थितिक तंत्र दोनों ही विभिन्न जीवों की विविधता का घर हैं और इन पारिस्थितिक तंत्रों के समर्थन के बिना ये जीव विलुप्त हो जाएंगे।</p>\r\n<h3 class=\"atech\">जल संरक्षण</h3>\r\n<p>देश में जल संरक्षण पर बल देना आवश्यक है और कोई भी इकाई (चाहे वह व्यक्ति हो या कोई कंपनी) अनावश्यक रूप से उपकरणों के प्रयोग को कम कर रोज़ाना कई गैलन पानी बचा सकता है।</p>\r\n<h3 class=\"atech\">अन्य तरीके</h3>\r\n<p>रेनवाटर हार्वेस्टिंग द्वारा जल का संचयन। और वर्षा जल को सतह पर संग्रहीत करने के लिये टैंकों, तालाबों और चेक-डैम आदि की व्यवस्था।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>जल पृथ्वी का सर्वाधिक मूल्यवान संसाधन है और हमें न केवल अपने लिये इसकी रक्षा करनी है बल्कि भविष्य की पीढ़ियों के लिये भी इसे बचा कर रखना है। वर्तमान समय में जब भारत के साथ-साथ संपूर्ण विश्व जल संकट का सामना कर रहा है तो आवश्यक है कि इस ओर गंभीरता से ध्यान दिया जाए। भारत में जल प्रबंधन अथवा संरक्षण संबंधी नीतियाँ मौज़ूद हैं, परंतु समस्या उन नीतियों के कार्यान्वयन के स्तर पर है। अतः नीतियों के कार्यान्वयन में मौजूद शिथिलता को दूर कर उनके बेहतर क्रियान्वयन को सुनिश्चित किया जाना चाहिये जिससे देश में जल के कुप्रबंधन की सबसे बड़ी समस्या को संबोधित किया जा सके।</p>\r\n',5,'2025-01-31 06:28:07','2025-01-31 06:45:20','','Publish',0,'open',42,71),('झारखण्ड में वन्य जीवन प्रबंधन।','wildlife-management-in-jharkhand',2,'<p>झारखंड, जिसे \"वनों का प्रदेश\" भी कहा जाता है, अपनी प्राकृतिक संपदा, घने जंगलों, और अद्वितीय जैव-विविधता के लिए प्रसिद्ध है। राज्य की लगभग 29% भूमि वनों से आच्छादित है, जो देश के जैविक विविधता के संरक्षण में महत्वपूर्ण भूमिका निभाती है। इन वनों में विभिन्न प्रकार के वन्य जीव-जंतु और पौधों की प्रजातियाँ पाई जाती हैं। इन प्राकृतिक संसाधनों को संरक्षित करने के लिए वन्य जीवन प्रबंधन एक महत्वपूर्ण विषय बन जाता है।</p>\r\n<p>झारखंड के जंगलों में बाघ, हाथी, तेंदुआ, हिरण, चीतल, भालू, और नीलगाय जैसे जंतु पाए जाते हैं। साथ ही, यहाँ सर्प, मगरमच्छ और अन्य सरीसृपों की भी प्रजातियाँ हैं। पक्षियों की दृष्टि से भी राज्य बेहद समृद्ध है। मोर, तोता, कठफोड़वा, और गिद्ध जैसी प्रजातियाँ यहाँ सामान्यतः देखी जाती हैं।</p>\r\n<p>वन्य जीवन की यह समृद्धता न केवल पर्यावरणीय दृष्टि से महत्वपूर्ण है, बल्कि यह पर्यटन, पारिस्थितिकी, और स्थानीय जनजातियों की आजीविका के लिए भी अत्यधिक महत्त्वपूर्ण है।</p>\r\n<p>झारखंड में वन्य जीवन की समृद्धता के बावजूद, इसके संरक्षण की आवश्यकता निरंतर बढ़ रही है। कई कारक, जैसे शहरीकरण, औद्योगिकीकरण, और खनन गतिविधियाँ, वनों और वन्य जीवों पर नकारात्मक प्रभाव डाल रही हैं।</p>\r\n<p>वतेजी से हो रहे शहरीकरण और कृषि विस्तार के कारण झारखंड के वनों की अंधाधुंध कटाई हो रही है। यह वन्य जीवों के प्राकृतिक आवास को नष्ट कर रहा है, जिससे उनकी संख्या में कमी आ रही है।</p>\r\n<p>जैसे-जैसे वन क्षेत्र सिकुड़ते जा रहे हैं, वन्य जीव भोजन और आश्रय की तलाश में मानव बस्तियों की ओर आने लगे हैं। इससे मानव-वन्यजीव संघर्ष की घटनाएँ बढ़ रही हैं, जिसमें कभी-कभी जानमाल की हानि भी होती है।</p>\r\n<p>झारखंड में दुर्लभ प्रजातियों के अवैध शिकार और तस्करी की घटनाएँ बढ़ रही हैं। बाघों, हाथियों, और अन्य वन्य जीवों की तस्करी न केवल उनकी संख्या को घटाती है, बल्कि जैव विविधता के लिए भी गंभीर खतरा है।</p>\r\n<p>जंगलों में आग, सूखा, और जलवायु परिवर्तन जैसे कारक भी वन्य जीवन के लिए गंभीर खतरा बनते जा रहे हैं। इन सभी कारकों के चलते, झारखंड में वन्य जीवन के संरक्षण के लिए ठोस कदम उठाने की आवश्यकता है।</p>\r\n<p>झारखंड में वन्यजीव प्रबंधन के लिए कई योजनाएं और कदम उठाए गए-</p>\r\n<ul>   \r\n    <li><p>पलामू टाइगर रिजर्व की स्थापना 1973 में की गई थी। यह भारत के पहले टाइगर प्रोजेक्ट में से एक है और बाघों की सुरक्षा के लिए महत्वपूर्ण स्थान है।</p></li>\r\n    <li><p>बेतला राष्ट्रीय उद्यान की स्थापना 1986 में की गई थी। यह पलामू टाइगर रिजर्व का एक हिस्सा है और यहाँ विविध वन्य जीवों का संरक्षण किया जाता है।</p></li>\r\n    <li><p>हजारीबाग अभयारण्य की स्थापना 1954 में की गई थी। यह अभयारण्य विविध प्रकार के वन्य जीवों का घर है और पर्यटकों के लिए भी आकर्षण का केंद्र है।</p></li>\r\n    <li><p>पारसनाथ अभयारण्य की स्थापना 1989 में की गई थी। यह अभयारण्य पारसनाथ पर्वत क्षेत्र में स्थित है और यहाँ कई प्रकार के वन्य जीव और पक्षियों का संरक्षण किया जाता है।</p></li>\r\n    <li><p>कोडरमा अभयारण्य की स्थापना 1985 में की गई थी। यह क्षेत्र मुख्य रूप से बाघों और अन्य वन्य जीवों के लिए जाना जाता है और यहाँ जैव विविधता का संरक्षण किया जाता है।</p></li>\r\n</ul>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>झारखंड में वन्यजीव प्रबंधन की योजनाएँ और संरक्षित क्षेत्र जैसे पलामू टाइगर रिजर्व, बेतला राष्ट्रीय उद्यान, हजारीबाग अभयारण्य, पारसनाथ अभयारण्य, और कोडरमा अभयारण्य, वन्य जीवन और जैव विविधता के संरक्षण में महत्वपूर्ण भूमिका निभाते हैं। इन अभयारण्यों की स्थापना ने न केवल बाघों और अन्य वन्य जीवों की सुरक्षा को सुनिश्चित किया है, बल्कि स्थानीय समुदायों को भी संरक्षण में शामिल किया है, जिससे उन्हें आर्थिक लाभ मिल रहा है।</p>\r\n<p>हालांकि, अवैध शिकार, वनों की कटाई, और मानव-वन्यजीव संघर्ष जैसी चुनौतियाँ अभी भी मौजूद हैं। इनसे निपटने के लिए स्थायी प्रबंधन रणनीतियों और स्थानीय समुदायों की जागरूकता बढ़ाने की आवश्यकता है।</p>\r\n<p>अंततः, झारखंड के वन्यजीवों और उनके आवासों का संरक्षण न केवल जैव विविधता के लिए आवश्यक है, बल्कि यह पारिस्थितिकी संतुलन, जलवायु परिवर्तन से निपटने, और भविष्य की पीढ़ियों के लिए एक स्वस्थ वातावरण बनाए रखने में भी महत्वपूर्ण है।</p>',3,'2025-01-31 06:56:54','2025-01-31 07:31:10','','Publish',0,'open',43,72),('पर्यावरण को प्रदुषित करने वाले घटकों का वर्णन करे।','elements-that-pollute-the-environment',2,'<P>पर्यावरण पृथ्वी पर जीवन के लिए आवश्यक सभी प्राकृतिक तत्वों का संयोजन है। यह हमें स्वच्छ हवा, शुद्ध पानी, उपजाऊ भूमि और स्थिर जलवायु प्रदान करता है। लेकिन औद्योगिकीकरण, शहरीकरण और मानवीय गतिविधियों के कारण, यह प्राकृतिक संतुलन आज बुरी तरह प्रभावित हो रहा है। प्रदूषण पर्यावरण को नुकसान पहुंचाने वाले प्रमुख कारकों में से एक है। यह एक ऐसी स्थिति है जिसमें वायु, जल, मिट्टी, ध्वनि, और प्रकाश के तत्व दूषित हो जाते हैं और यह मानव जीवन, वनस्पति, और जीव-जंतुओं पर गंभीर प्रभाव डालता है।</P>\r\n<P>पर्यावरण वह है जो हमें चारों ओर से घेरता है—प्राकृतिक और कृत्रिम दोनों रूपों में। इसमें वायु, जल, भूमि, वनस्पति, और जीव-जंतु शामिल हैं। जब इन तत्वों में अवांछनीय और हानिकारक परिवर्तन होते हैं, तो इसे प्रदूषण कहते हैं। प्रदूषण पर्यावरण के संतुलन को बाधित करता है और जीवों के अस्तित्व के लिए खतरा उत्पन्न करता है।</P>\r\n<P>सबसे पहले उन प्रदूषकों का अध्ययन किया गया जिनमें भौतिक तत्व मौजूद थे: वायु प्रदूषण, जल प्रदूषण और भूमि प्रदूषण। </P>\r\n<P>बाद में, सादृश्य द्वारा, ध्वनि प्रदूषण, प्रकाश प्रदूषण, तापीय प्रदूषण और विद्युत चुम्बकीय प्रदूषण के लिए परिभाषाएं प्रदान की गईं</P>\r\n<P>पर्यावरण को प्रदुषित करने वाले निम्नलिखित  घटक है-</P>\r\n<H2>वायु प्रदूषण</H2>\r\n<P>वायु प्रदूषण का मुख्य कारण औद्योगिक उत्सर्जन, वाहनों से निकलने वाला धुआं, और जीवाश्म ईंधनों का जलना है। इनसे वायुमंडल में कार्बन डाइऑक्साइड, कार्बन मोनोऑक्साइड, सल्फर डाइऑक्साइड, और नाइट्रोजन ऑक्साइड जैसी जहरीली गैसें बढ़ जाती हैं। इसके अलावा, धूल और अन्य ठोस कण (पार्टिकुलेट मैटर) भी हवा की गुणवत्ता को प्रभावित करते हैं। वायु प्रदूषण से श्वसन तंत्र संबंधी रोग, ग्लोबल वार्मिंग, और ओजोन परत का क्षरण होता है।</P>\r\n<H2>जल प्रदूषण</H2>\r\n<P>जल प्रदूषण तब होता है जब जल स्रोतों में हानिकारक पदार्थ घुल जाते हैं। यह मुख्यतः औद्योगिक अपशिष्ट, घरेलू कचरे, और कृषि में उपयोग किए जाने वाले रसायनों के कारण होता है। प्लास्टिक कचरा, तेल रिसाव, और अनियमित शहरीकरण ने जल प्रदूषण की समस्या को और बढ़ा दिया है। इसके परिणामस्वरूप जल स्रोतों की जैव विविधता प्रभावित होती है, और कई जीव-जन्तु विलुप्त होने की कगार पर हैं।</P>\r\n<H2>भूमि प्रदूषण</H2>\r\n<P>भूमि प्रदूषण का मुख्य कारण कृषि में रासायनिक उर्वरकों और कीटनाशकों का अत्यधिक उपयोग है। इसके अलावा, ठोस कचरे, प्लास्टिक, और औद्योगिक रसायनों के अनुचित निपटान से भूमि की उर्वरता घटती है। यह न केवल खेती को प्रभावित करता है, बल्कि मानव स्वास्थ्य पर भी बुरा प्रभाव डालता है, जैसे कि भोजन में जहरीले पदार्थों का प्रवेश।</P>\r\n<H2>ध्वनि प्रदूषण</H2>\r\n<P>ध्वनि प्रदूषण वाहनों के शोर, औद्योगिक गतिविधियों, और निर्माण कार्यों से उत्पन्न होता है। यह समस्या शहरी क्षेत्रों में अधिक गंभीर है। अत्यधिक शोर तनाव, अनिद्रा, और श्रवण हानि का कारण बनता है। पशु भी इससे प्रभावित होते हैं, जिससे उनके प्राकृतिक व्यवहार में परिवर्तन आता है।</P>\r\n<H2>ई-कचरा या प्लास्टिक प्रदूषण</H2>\r\n<P>प्लास्टिक प्रदूषण आधुनिक समय की एक गंभीर समस्या है। प्लास्टिक के अपशिष्ट को नष्ट करना बेहद कठिन है। यह न केवल भूमि को दूषित करता है, बल्कि समुद्री जीवन को भी खतरे में डालता है। प्लास्टिक के छोटे कण (माइक्रोप्लास्टिक्स) खाद्य श्रृंखला में प्रवेश कर रहे हैं, जिससे मानव स्वास्थ्य भी प्रभावित हो रहा है।</P>\r\n<P>पुरानी इलेक्ट्रॉनिक वस्तुओं को फेंकना और उनका अनियंत्रित निपटान ई-कचरे का प्रमुख कारण है। कंप्यूटर, मोबाइल, और अन्य उपकरणों से निकलने वाले जहरीले रसायन भूमि और जल को प्रदूषित करते हैं।</P>\r\n<H2>निष्कर्ष</H2>\r\n<P>पर्यावरण प्रदूषण एक गंभीर समस्या है, जिसका समाधान सामूहिक प्रयासों से ही संभव है। हमें अपने पर्यावरण की रक्षा के लिए अपनी आदतों में सुधार लाना होगा। प्रदूषण को नियंत्रित करना न केवल वर्तमान पीढ़ी के लिए बल्कि भविष्य की पीढ़ियों के लिए भी आवश्यक है।</P>\r\n<P>यदि हम अभी कदम नहीं उठाते, तो यह समस्या और विकराल हो जाएगी, जिससे पृथ्वी पर जीवन का अस्तित्व खतरे में पड़ जाएगा।</P>\r\n',16,'2025-01-31 06:56:54','2025-01-31 07:37:12','','Publish',0,'open',44,73),('बांध परियोजना से आप क्या समझते हैं?','what-do-you-understand-by-dam-project',2,'<p>बांध परियोजनाएँ मानव सभ्यता की सबसे महत्वपूर्ण उपलब्धियों में से एक हैं। यह जल संसाधनों को नियंत्रित और प्रबंधित करने का एक ऐसा उपाय है जो समाज, पर्यावरण और अर्थव्यवस्था को सशक्त करता है। पानी, जो जीवन का मूल तत्व है, को सही तरीके से उपयोग करने और संरक्षित करने के लिए बांध परियोजनाएँ आवश्यक हैं। नदियों के जल प्रवाह को नियंत्रित करते हुए इन परियोजनाओं ने खेती, बिजली उत्पादन, जल आपूर्ति, और बाढ़ नियंत्रण में महत्वपूर्ण योगदान दिया है।</p>\r\n<p>प्राचीन बाँध निर्माताओं ने प्राकृतिक सामग्री जैसे- चट्टानों या मिट्टी का इस्तेमाल किया, जबकि आज अधिकांश बाँध कंक्रीट का उपयोग करके बनाए गए हैं।</p>\r\n<p>भारत जैसे कृषि प्रधान देश में, जहाँ अधिकतर कृषि वर्षा पर निर्भर करती है, बांध परियोजनाएँ न केवल सिंचाई के लिए जल की आपूर्ति करती हैं, बल्कि जलविद्युत उत्पादन, बाढ़ नियंत्रण, और पेयजल उपलब्ध कराने में भी महत्वपूर्ण भूमिका निभाती हैं। ये परियोजनाएँ समाज को आत्मनिर्भर बनाने और देश के आर्थिक विकास में योगदान करने के लिए बनाई जाती हैं।</p>\r\n<h2>बांध परियोजनाओं का ऐतिहासिक परिप्रेक्ष्य</h2>\r\n<h3 class=\"atech\">प्राचीन काल</h3>\r\n<p>भारत में जल प्रबंधन की परंपरा बहुत प्राचीन है। सिंधु घाटी सभ्यता में जल संचय और प्रबंधन के उन्नत प्रमाण मिलते हैं। इस सभ्यता में विकसित नगरों में जल निकासी और संग्रहण की अद्वितीय प्रणाली मौजूद थी। दक्षिण भारत में, कल्लनई बांध को लगभग 2000 वर्ष पहले चोल साम्राज्य के राजा करिकाल चोल ने बनवाया था। यह बांध आज भी उपयोग में है और इस बात का प्रमाण है कि भारत में जल प्रबंधन की परंपरा कितनी पुरानी और समृद्ध रही है।</p>\r\n<h3 class=\"atech\">मध्यकालीन भारत</h3>\r\n<p>मध्यकाल में भी कई जल संरचनाएँ बनाई गईं। इनमें तालाब, झीलें और नहरें शामिल थीं, जो स्थानीय लोगों की पानी की जरूरतों को पूरा करती थीं। राजस्थान के किलों और गुजरात के बावड़ियों में जल संचय के उत्कृष्ट उदाहरण मिलते हैं।</p>\r\n<h3 class=\"atech\">आधुनिक काल</h3>\r\n<p>आधुनिक समय में बांध परियोजनाओं की शुरुआत औपनिवेशिक शासन के दौरान हुई। ब्रिटिश शासन ने जल आपूर्ति और सिंचाई के लिए कई छोटी-छोटी परियोजनाएँ शुरू कीं। स्वतंत्रता के बाद, इन परियोजनाओं को बड़े पैमाने पर विकसित किया गया। पंडित जवाहरलाल नेहरू ने इन्हें \"आधुनिक भारत के मंदिर\" कहा। भाखड़ा-नांगल, हीराकुंड और दामोदर घाटी निगम जैसी परियोजनाएँ इस दिशा में मील का पत्थर साबित हुईं।</p>\r\n<h3 class=\"atech\">बांध परियोजनाओं के उद्देश्य और उपयोग</h3>\r\n<p>ये परियोजनाएँ कई उद्देश्यों की पूर्ति करती हैं, जैसे- सिंचाई,बिजली उत्पादन,बाढ़ नियंत्रण,जल आपूर्ति, और पर्यटन और मनोरंजन।</p>\r\n<h3 class=\"atech\">सिंचाई</h3>\r\n<p>भारत में खेती ज्यादातर मानसून पर निर्भर करती है। कई बार अनियमित बारिश या सूखे की स्थिति में फसलों को नुकसान पहुंचता है। बाँध परियोजनाएँ इस समस्या का समाधान प्रदान करती हैं। पानी को संग्रहित कर, इसे नहरों के माध्यम से खेतों तक पहुँचाया जाता है। उदाहरण के लिए भाखड़ा-नांगल बांध ने हरियाणा, पंजाब और राजस्थान में कृषि क्षेत्र में क्रांति लाई।</p>\r\n<h3 class=\"atech\">जलविद्युत उत्पादन</h3>\r\n<p>जल को ऊँचाई से गिराकर उत्पन्न ऊर्जा से बिजली बनाई जाती है। जलविद्युत संयंत्र स्वच्छ और अक्षय ऊर्जा का एक प्रमुख स्रोत हैं। उदाहरण के लिए टिहरी बांध (उत्तराखंड) से बड़े पैमाने पर बिजली का उत्पादन होता है।</p>\r\n<h3 class=\"atech\">बाढ़ नियंत्रण</h3>\r\n<p>बाढ़ भारत में एक आम समस्या है, जो हर साल हजारों लोगों के जीवन और संपत्ति को प्रभावित करती है। बाँध जल को नियंत्रित कर बाढ़ की तीव्रता को कम करने में सहायक होते हैं। उदाहरण के लिए हीराकुंड बांध (ओडिशा) महानदी के प्रवाह को नियंत्रित करता है और बाढ़ से बचाव करता है।</p>\r\n<h3 class=\"atech\">पेयजल आपूर्ति</h3>\r\n<p>बांध परियोजनाएँ बड़े शहरों और कस्बों में पीने के पानी की आपूर्ति का एक महत्वपूर्ण स्रोत हैं। उदाहरण के लिए इंदिरा सागर परियोजना मध्य प्रदेश के कई हिस्सों में जल आपूर्ति करती है।</p>\r\n<h3 class=\"atech\">पर्यटन और रोजगार</h3>\r\n<p>बांध क्षेत्र अक्सर पर्यटन स्थलों के रूप में विकसित होते हैं। इससे स्थानीय लोगों को रोजगार के अवसर भी मिलते हैं। उदाहरण के लिए नागार्जुनसागर बांध (तेलंगाना) के आसपास का क्षेत्र एक प्रमुख पर्यटन स्थल है।</p>\r\n<h2>बांध परियोजनाओं के नुकसान</h2>\r\n<p>हालाँकि बाँधों के परिणामस्वरूप समाज को कई तरह के लाभ प्राप्त होते हैं, लेकिन उन्हें नदी पारिस्थितिकी, वन्यजीव, मछलियों के आवास और अंततः मनुष्यों के लिये सबसे बड़े खतरे के रूप में देखा जाता है।</p>\r\n<h3 class=\"atech\">पर्यावरणीय नुकसान</h3>\r\n<p>बाँधों के निर्माण से पर्यावरण को गंभीर नुकसान पहुंचता है। इसके अंतर्गत वनों और वन्यजीवों का नाश, प्राकृतिक पारिस्थितिकी तंत्र में बदलाव, और जलवायु पर दीर्घकालिक प्रभाव शामिल हैं। बाँध बनने से बड़ी मात्रा में जंगल डूब जाते हैं, जिससे जैव विविधता को नुकसान पहुंचता है। नदी के प्राकृतिक प्रवाह में बाधा उत्पन्न होने से मछलियों और अन्य जलजीवों पर प्रतिकूल प्रभाव पड़ता है।</p>\r\n<h3 class=\"atech\">विस्थापन और पुनर्वास</h3>\r\n<p>बाँध परियोजनाओं के कारण हजारों या लाखों लोगों को अपने घर और जमीन छोड़नी पड़ती है। यह विस्थापन न केवल भौतिक स्थानांतरण है, बल्कि सामाजिक और सांस्कृतिक संकट भी उत्पन्न करता है। विस्थापित समुदायों को रोजगार, शिक्षा और स्वास्थ्य सुविधाओं में कमी का सामना करना पड़ता है।</p>\r\n<h3 class=\"atech\">भूस्खलन और भूकंप का खतरा</h3>\r\n<p>बाँधों के पीछे जल के भारी भंडार बनने से भौगोलिक अस्थिरता बढ़ जाती है। इससे भूस्खलन और कभी-कभी भूकंप जैसी प्राकृतिक आपदाओं का खतरा उत्पन्न होता है।</p>\r\n<h3 class=\"atech\">जलवायु परिवर्तन पर प्रभाव</h3>\r\n<p>बाँध के पीछे इकट्ठा पानी एक अप्राकृतिक, स्थिर झील का निर्माण करता है जो अक्सर वहाँ के पारिस्थितिक तंत्र को नुकसान पहुँचाता है। पानी में मौजूद बैक्टीरिया इन पौधों को विघटित करते हैं और कार्बन डाइऑक्साइड एवं मीथेन (शक्तिशाली ग्रीनहाउस गैस) उत्पन्न करते हैं, जो जलवायु परिवर्तन में योगदान करती हैं।</p>\r\n<h3 class=\"atech\">जल संसाधनों का असमान वितरण</h3>\r\n<p>बड़े बाँधों से पानी का उपयोग मुख्यतः औद्योगिक और शहरी क्षेत्रों में किया जाता है, जिससे ग्रामीण और गरीब समुदायों को जल संकट का सामना करना पड़ता है।</p>\r\n<h3 class=\"atech\">कृषि और मत्स्य पालन पर प्रभाव</h3>\r\n<p>बाँधों के निर्माण से नदियों का प्रवाह नियंत्रित होता है, जिससे सिंचाई की समस्याएँ और मत्स्य पालन पर नकारात्मक प्रभाव पड़ता है। मछलियों के प्रवास में बाधा आने से स्थानीय मछली उद्योग पर संकट उत्पन्न होता है।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>बाँध परियोजनाएँ जल प्रबंधन और ऊर्जा उत्पादन के लिए महत्वपूर्ण हैं, लेकिन उनके कई नुकसान हैं, जैसे विस्थापन, पर्यावरणीय प्रभाव, और स्थानीय समुदायों पर नकारात्मक प्रभाव। इसके अलावा, आर्थिक बोझ और जलवायु परिवर्तन में योगदान भी चिंताजनक हैं।</p>\r\n<p>इसलिए, सतत विकास के लिए वैकल्पिक ऊर्जा स्रोतों और जल प्रबंधन के अन्य तरीकों का उपयोग करना आवश्यक है, ताकि पर्यावरण और समाज दोनों का संतुलन बना रहे।</p>\r\n\r\n\r\n',18,'2025-01-31 06:56:54','2025-01-31 07:41:11','','Publish',0,'open',42,74),('मध्यकाल में प्राकृतिक संसाधनों पर आधारित उद्योगों।','industries-based-on-natural-resources-in-the-medieval-period',2,'<p>मध्यकालीन युग, जो लगभग 5वीं शताब्दी से 15वीं शताब्दी तक फैला, एक ऐसा समय था जब प्राकृतिक संसाधनों की खोज और उनका उपयोग समाज के विकास में महत्वपूर्ण भूमिका निभाते थे। इस अवधि में विभिन्न क्षेत्रों में प्राकृतिक संसाधनों के दोहन और उपयोग ने आर्थिक, सामाजिक और सांस्कृतिक पहलुओं को प्रभावित किया।</p>\r\n<p>मध्यकाल को मुस्लिम कल के नाम से भी जाना जाता है क्योंकि इस दौरान भारत में केंद्रीय सत्ता मुस्लिम शासको के अधीन रही। अध्ययन की सुविधा के लिए पूरे मध्यकाल को दो भागों में विभाजित किया जा सकता है संतरण कल एवं मुगल काल।</p>\r\n<h2>सल्तनत काल के दौरान प्राकृतिक संसाधनों पर आधारित उद्योग</h2>\r\n<p>भारत हमेशा सही कृषि प्रधान देश रहा है और यहां की अधिकांश जनता कृषक रही है इसलिए दिल्ली सल्तनत के सुल्तान भी हमेशा से ही कृषक को पर आश्रित रहे हैं क्योंकि कृषि पर आधारित उद्योग ही उनकी आय का प्रमुख स्रोत हुआ करते थे कृषक से प्राय: उत्पादन के 1/3 हिस्सा भूमि कर के रूप में लिया जाता था।</p>\r\n<p>इस काल के दौरान भारत में कई प्रकार के प्राकृतिक संसाधनों पर आधारित उद्योग विकसित हुए। इस काल में भारतीय उपमहाद्वीप की अर्थव्यवस्था में कृषि, हस्तशिल्प और व्यापार का महत्वपूर्ण स्थान था</p>\r\n<p>वैसे तो भारत में सिंचाई की सुविधा प्राचीन काल से ही विद्यमान थे परंतु अनेक सुल्ताने जैसे- गियासुद्दीन तुगलक, मोहम्मद-बिन-तुगलक, और फिरोज शाह तुगलक इत्यादि ने कृषि पैदावार बढ़ाने के लिए अनेक प्रयास किया गियासुद्दीन तुगलक ने कृषि पैदावार को बढ़ाने के लिए नहरे का निर्माण करवाया, मोहम्मद-बिन-तुगलक ने एक नया विभाग \"दीवान-ए-अमीरकोह\" की स्थापना की तथा फिरोज शाह तुगलक ने सिचाई व्यवस्था को सुदृढ़ एवं व्यवस्थित करवाया।</p>\r\n<p>कृषि के साथ-साथ मछली पालन, धातु कर्म नमक उत्पादन, अफीम, शराब उत्पादन आदि प्रमुख उद्योग थे जो ग्रामीण एवं शहरी दोनों ही क्षेत्र में विद्यमान थे, यह उद्योग प्राय: प्राकृतिक संसाधनों पर आधारित होते थे और इनका राज्य की अर्थव्यवस्था पर व्यापक प्रभाव पड़ता था। खनिजों में सोना चांदी लोहा और तम प्रमुख थे जिनका उपयोग इन उद्योगों में किया जाता था और इनसे विभिन्न प्रकार की वस्तुओं जैसे आभूषण, सिक्के, हथियार, बर्तन इत्यादि निर्यात की जाती थी। </p>\r\n<p>देश में दो प्रकार के उद्योग विद्यमान थे एक तो वह जिन्हें संरक्षण प्राप्त था, दूसरा वह जो पूर्ण रूपेण निजी स्वामित्व में थे इनके अतिरिक्त दिल्ली के सुल्तानों ने अपने निजी कारखाने हुआ करते थे जिसमे  शाही ज़रूरतें की वस्तुएं का निर्माण किया जाता था।</p>\r\n<p>सुलतानों के निजी कारखाने में सिल्क एवं रेशम से निर्मित वस्त्र का उत्पादन बड़े पैमाने पर किया था कीमती आभूषण एवं सजावटी सामान बनाने के लिए भी पृथक सही कारखाने थे व्यापारियों के नीचे उद्योग में प्रसिद्ध थे सूती वस्त्र उद्योग, ऊनी और रेशमी वस्त्र उद्योग, धातु कर्म, कागजात उद्योग आदि।</p>\r\n<h2>मुगल काल के दौरान प्राकृतिक संसाधनों पर आधारित उद्योग</h2>\r\n<p>मुगलकालीन अर्थव्यवस्था में व्यापारिक गतिविधियों का महत्वपूर्ण भूमिका रही है मुगल काल में भारत का सर्वाधिक प्रमुख उद्योग कपड़ा उद्योग था कपास उत्पादन और कपास से सूती वस्त्र का निर्माण बड़े पैमाने पर किया जाता था इस कल के दौरान जौनपुर बनारस पटना बरहानपुर लखनऊ इत्यादि स्थान सूती वस्त्र उद्योग के प्रमुख केंद्र थे। </p>\r\n<p>इस कल के दौरान भारतीय उद्योग में निर्मित वस्त्र की मांग ना केवल भारत में थी बल्कि विश्व के अन्य देशों की बाजारों में थी भारतीय वस्त्र विश्व में दूर-दूर तक व्याख्यात थे जहां रेशम भी बड़ी मात्रा में होता था और इतने महीन कपड़े यहां बनते थे जिनका कल्पना नहीं की जा सकती।</p>\r\n<p>कपड़ा उद्योग के साथ-साथ कपड़ों की रंगाई करने का उद्योग भी पनप रहा था कपड़ों की रंगाई खूबसूरत पुष्प कृतियां द्वारा किए जाते थे इस काल में शिल्प कपड़ा उद्योग उन्नत व्यवस्था था सम्राट अकबर ने सिल्क उद्योग को पूर्ण संरक्षण प्रदान किया था जिसके कारण इसका विकास तीव्र गति से हुआ आगरा, फतेहपुर सिकरी, लाहौर इत्यादि स्थान इस काल में शिल्प उद्योग के प्रमुख केंद्र बन चुके थे। </p>\r\n<p>नील की खेती विशेष रूप से बंगाल और बिहार में होती थी। इससे वस्त्र रंगने के लिए प्राकृतिक रंग तैयार किए जाते थे।</p>\r\n<p>लकड़ी और सागौन का उपयोग जहाज निर्माण और फर्नीचर निर्माण के लिए किया जाता था। दक्षिण भारत और पश्चिमी घाट के जंगल लकड़ी के प्रमुख स्रोत थे। समुद्री व्यापार के लिए बड़े जहाजों का निर्माण होता था। इनमें सागौन और शीशम की लकड़ी का उपयोग किया जाता था। लकड़ी से बने फर्नीचर, जैसे पलंग, अलमारियाँ और दरवाजे, मुगलों की शाही शैली को दर्शाते थे।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>मध्यकाल में प्राकृतिक संसाधनों पर आधारित उद्योग स्थानीय अर्थव्यवस्था और रोजगार का आधार थे। इन उद्योगों में कपड़ा, धातु, कागज, काष्ठ, खाद्य प्रसंस्करण, इत्र, और मिट्टी के बर्तन शामिल थे। स्थानीय संसाधनों का उपयोग कर उत्पादन बढ़ा, जिससे व्यापार और सांस्कृतिक आदान-प्रदान को बढ़ावा मिला। यह उद्योग उस समय की स्वावलंबी अर्थव्यवस्था का मुख्य स्तंभ थे।</p>\r\n\r\n\r\n',64,'2025-01-31 06:56:54','2025-01-31 07:48:56','','Publish',0,'open',46,75),('वनोन्मूलन क्या है? वनोन्मूलन के कारण और उनके प्रभाव पर चर्चा करे।','what-is-deforestation-and-write-the-causes-and-effects-of-deforestation',2,'<p>वनोन्मूलन का अर्थ है वनों के क्षेत्रों में बहुत से पेड़ों को जलाया या काटा जाता है ऐसा करने के लिए कई कारण हैं जैसे- घरेलू उपयोग  चारकोल, फर्नीचर आदि में एवं कृषि विस्तार, शहरीकरण,पशुपालन आदि। यह न केवल जैव विविधता को खतरे में डालता है, बल्कि जलवायु परिवर्तन और पारिस्थितिकी तंत्र के संतुलन को भी प्रभावित करता है।</p>\r\n<h2>वनोन्मूलन के कारण</h2>\r\n<p>वनोन्मूलन, या वनों की कटाई, एक गंभीर पर्यावरणीय समस्या है जो कई कारणों से होती है।</p>\r\n<h3 class=\"atech\">कृषि विस्तार</h3>\r\n<p>बढ़ती जनसंख्या और खाद्य मांग के कारण कृषि भूमि की आवश्यकता में वृद्धि हुई है। इसके चलते किसानों द्वारा वनों की कटाई की जाती है ताकि खेती के लिए अधिक भूमि प्राप्त हो सके। विशेष रूप से वाणिज्यिक फसलों की खेती के लिए वनों का नष्ट होना आम है।</p>\r\n<h3 class=\"atech\">शहरीकरण</h3>\r\n<p>शहरीकरण के कारण शहरों और बस्तियों का विस्तार होता है। इसके लिए आवास, सड़कें, और अन्य बुनियादी ढाँचे की आवश्यकता होती है, जिससे वनों का सफाया होता है। यह प्रक्रिया विशेष रूप से विकासशील देशों में अधिक प्रचलित है।</p>\r\n<h3 class=\"atech\">अवैध लकड़ी कटाई</h3>\r\n<p>लकड़ी की मांग में वृद्धि के साथ, अवैध लकड़ी कटाई एक महत्वपूर्ण कारण बन गई है। मानव जनसंख्या का बढ़ना जिससे भवन निर्माण, रेलवे लाइन, सड़कों, इमारतों, शैक्षिक संस्थाओं, उद्योगों आदि को स्थापित करने के लिए भूमि की माँग बढ़ी है</p>\r\n<h3 class=\"atech\">खनन गतिविधियाँ</h3>\r\n<p>खनिजों की खोज और खनन के लिए वनों की सफाई की जाती है। खनन कंपनियाँ अक्सर जंगलों को नष्ट करके अपनी गतिविधियाँ चलाती हैं, जिससे वन्य जीवों का निवास स्थान खत्म होता है और जल, वायु और मिट्टी प्रदूषण बढ़ता है।</p>\r\n<h3 class=\"atech\">जलवायु परिवर्तन</h3>\r\n<p>जलवायु परिवर्तन से इन वनों पर अधिक प्रभाव पड़ते हैं उच्च तापमान जिससे कभी-कभी जंगलों में आग लग जाते हैं जिससे लाखों की संख्या में पेड़ जल जाते हैं और सामान्य वर्षा जिसमें बहुत सारे पेड़ बर्बाद हो जाते हैं जिसके कारण वनों का नष्ट होना और भी तेजी हो जाता है।</p>\r\n<p>इन कारणों के परिणामस्वरूप, वनोन्मूलन एक जटिल समस्या बन गई है, जो न केवल पर्यावरण बल्कि मानव जीवन के लिए भी गंभीर खतरे का कारण है। इसे नियंत्रित करने के लिए ठोस कदम उठाने की आवश्यकता है।</p>\r\n<h2>वनोन्मूलन के प्रभाव</h2>\r\n<p>वनोन्मूलन का प्रभाव व्यापक और गहरा होता है, जो न केवल पर्यावरण बल्कि मानव जीवन और पारिस्थितिकी तंत्र को भी प्रभावित करता है।</p>\r\n<h3 class=\"atech\">जैव विविधता की हानि</h3>\r\n<p>वनों के नष्ट होने से अनेक जीव-जंतु और पौधे अपने प्राकृतिक आवास खो देते हैं। यह जैव विविधता को गंभीर रूप से प्रभावित करता है, जिससे अनेक प्रजातियों का अस्तित्व संकट में पड़ सकता है। कई प्रजातियाँ तो विलुप्त हो जाती हैं, जिससे पारिस्थितिकी तंत्र का संतुलन बिगड़ता है।</p>\r\n<h3 class=\"atech\">जलवायु परिवर्तन</h3>\r\n<p>पेड़ कार्बन डाइऑक्साइड को अवशोषित करके जलवायु परिवर्तन में महत्वपूर्ण भूमिका निभाते हैं। वनों के कटने से CO2 का स्तर बढ़ता है, जो ग्लोबल वार्मिंग का कारण बनता है। यह जलवायु में परिवर्तन लाता है, जैसे कि असामान्य मौसम, सूखा, और बाढ़।</p>\r\n<h3 class=\"atech\">मिट्टी का कटाव</h3>\r\n<p>पेड़ और वनस्पतियाँ मिट्टी को स्थिर रखने में मदद करती हैं। वनों के नष्ट होने से मिट्टी का कटाव बढ़ता है, जिससे उपजाऊ मिट्टी की परत धीरे-धीरे खत्म हो जाती है। यह कृषि उत्पादन को प्रभावित करता है और भूमि की उपजाऊ क्षमता को कम करता है।</p>\r\n<h3 class=\"atech\">जल संसाधनों की कमी</h3>\r\n<p>वनों का नष्ट होना जल चक्र को प्रभावित करता है। पेड़ जलवाष्प के माध्यम से बारिश में योगदान करते हैं। जब वनों की मात्रा कम होती है, तो वर्षा की मात्रा भी कम हो जाती है, जिससे जल संकट पैदा होता है। इससे जल की उपलब्धता कम होती है, जो कृषि और पीने के पानी के लिए आवश्यक है।</p>\r\n<p>वनोन्मूलन के प्रभाव न केवल पर्यावरणीय बल्कि सामाजिक और आर्थिक भी होते हैं। इसके कारण जैव विविधता की हानि, जलवायु परिवर्तन, मिट्टी का कटाव, और जल संसाधनों की कमी होती है। इसके साथ ही, यह स्वास्थ्य, आर्थिक विकास, और सांस्कृतिक पहचान को भी प्रभावित करता है।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>वनोन्मूलन एक गंभीर समस्या है जो मानव जीवन, पर्यावरण और जैव विविधता को प्रभावित करती है। इसके प्रमुख कारणों में कृषि विस्तार, शहरीकरण, अवैध लकड़ी कटाई, खनन गतिविधियाँ और जलवायु परिवर्तन शामिल हैं। वनों के नष्ट होने से जैव विविधता की हानि, जलवायु परिवर्तन, मिट्टी का कटाव, और जल संसाधनों की कमी जैसी गंभीर समस्याएँ उत्पन्न होती हैं।</p>\r\n<p>इससे निपटने के लिए स्थायी वन प्रबंधन, सामुदायिक भागीदारी, और शिक्षा की आवश्यकता है। वनों का संरक्षण न केवल पर्यावरण की रक्षा के लिए आवश्यक है, बल्कि यह आने वाली पीढ़ियों के लिए एक सुरक्षित भविष्य सुनिश्चित करता है। हमें सामूहिक रूप से वनों के संरक्षण के लिए प्रयास करने चाहिए ताकि हम एक संतुलित और हरित भविष्य की दिशा में आगे बढ़ सकें।</p>\r\n',125,'2025-01-31 06:56:54','2025-01-31 07:53:34','','Publish',0,'open',45,76),('वैदिक काल में पर्यावरणीय जागरूकता पर चर्चा करें।','environmental-awareness-in-the-vedic-period',2,'<p>वैदिक काल भारतीय इतिहास का एक अत्यंत महत्वपूर्ण और समृद्ध चरण है, जो लगभग 1500 ईसा पूर्व से 500 ईसा पूर्व तक फैला हुआ माना जाता है। इस काल में जीवन शैली, संस्कृति और दर्शन में प्रकृति का विशेष महत्व था। वैदिक ग्रंथों में पर्यावरणीय संतुलन और प्रकृति के संरक्षण के अनेक प्रमाण मिलते हैं, जो इस बात का संकेत देते हैं कि वैदिक लोग पर्यावरण के प्रति अत्यंत जागरूक थे।</p>\r\n<p>वैदिक काल भारतीय इतिहास का एक ऐसा युग था, जिसमें धर्म, दर्शन और विज्ञान का अद्भुत समन्वय दिखाई देता है। इस युग के ग्रंथ जैसे वेद, उपनिषद, और पुराण न केवल आध्यात्मिक दृष्टि से महत्वपूर्ण हैं, बल्कि इनमें प्रकृति और पर्यावरण के प्रति अद्वितीय जागरूकता भी दृष्टिगोचर होती है। वैदिक काल में मानव जीवन और प्रकृति के बीच गहरा संबंध था। प्रकृति को ईश्वर का स्वरूप माना जाता था और इसका संरक्षण सामाजिक और धार्मिक कर्तव्य समझा जाता था।</p>\r\n<p>रोमिला थापर लिखते है- \"<i>वैदिक ग्रंथों में मानव और प्रकृति के बीच सामंजस्यपूर्ण संबंध पर जोर दिया गया है, जहां पर्यावरण के तत्वों को पवित्र और जीवन को बनाए रखने के लिए आवश्यक माना गया है।</i>\"</p>\r\n<p>वैदिक ग्रंथों में प्रकृति के विभिन्न तत्वों को देवी-देवता के रूप में पूजा जाता था। पृथ्वी, जल, अग्नि, वायु, और आकाश – इन पंचतत्वों को जीवन का आधार माना गया है। इन तत्वों को शुद्ध, संतुलित और संरक्षित रखना वैदिक कालीन जीवन का अभिन्न हिस्सा था।</p>\r\n<h3  class=\"atech\">पृथ्वी (भूमि)</h3>\r\n<p>पृथ्वी को \"भूमि माता\" और \"धरा देवी\" के रूप में सम्मान दिया गया। अथर्ववेद में भूमि को धैर्य और पालन-पोषण का प्रतीक माना गया है। यह उल्लेख मिलता है कि भूमि को अतिक्रमण, कटाई, और अंधाधुंध उपयोग से बचाना चाहिए।</p>\r\n<h3  class=\"atech\">जल (अप)</h3>\r\n<p>जल को जीवन का स्रोत माना गया। ऋग्वेद में \"आपः\" नामक एक पूरा सूक्त जल की महिमा और उसकी शुद्धता को समर्पित है। नदियों को देवियों के रूप में पूजा जाता था, जैसे गंगा, यमुना, सरस्वती।</p>\r\n<h3  class=\"atech\">वायु (पवन)</h3>\r\n<p>वायु को प्राण का वाहक कहा गया। यजुर्वेद में वायु को शुद्ध और संतुलित रखने के लिए नियम बताए गए हैं। वायु प्रदूषण को रोकने के लिए धूम्र और विषैली गैसों से बचाव का उल्लेख मिलता है।</p>\r\n<h3  class=\"atech\">अग्नि (तेज)</h3>\r\n<p>अग्नि यज्ञ और धार्मिक अनुष्ठानों का प्रमुख तत्व थी। अग्नि को शुद्धता और ऊर्जा का प्रतीक माना गया। यज्ञ के माध्यम से पर्यावरणीय शुद्धता बनाए रखने की परंपरा थी।</p>\r\n<h3  class=\"atech\">आकाश (अंतरिक्ष)</h3>\r\n<p>आकाश को अनंत और दिव्य तत्व माना गया। इसके शुद्धता और संतुलन के लिए ध्यान और साधना को प्राथमिकता दी गई।</p>\r\n<p>आर.सी. मजूमदार  लिखते है-\"<i>वैदिक लोग नदियाँ, वृक्षों और समुद्र की दैवीय सत्ता के रूप में पूजा करते थे, जो पर्यावरण संरक्षण की आवश्यकता के प्रति उनकी गहन जागरूकता का विवरण है।</i>\"</p>\r\n\r\n<ul>\r\n    <li><p>यज्ञ वैदिक काल का प्रमुख धार्मिक कृत्य था। यह न केवल आध्यात्मिक उद्देश्य के लिए किया जाता था, बल्कि पर्यावरण को शुद्ध करने का भी माध्यम था। यज्ञ से वायु और जल की शुद्धता बनी रहती थी, और यह पर्यावरणीय संतुलन बनाए रखने में सहायक था।</p></li>\r\n    <li><p>वृक्षों को वैदिक काल में जीवनदायी माना गया। वृक्षों की पूजा और संरक्षण को धर्म का हिस्सा बनाया गया। अथर्ववेद में पीपल, बरगद, और तुलसी जैसे वृक्षों को पूजनीय बताया गया है। वृक्षों की कटाई पर प्रतिबंध था, और वन को \"देवता का निवास\" माना जाता था।</p></li>\r\n    <li><p>नदियों की स्वच्छता और संरक्षण को धर्म का कर्तव्य समझा जाता था। गंगा, यमुना, और सरस्वती जैसी नदियों को पवित्र मानकर उनकी पूजा की जाती थी।</p></li>\r\n    <li><p>पशुओं को वैदिक काल में परिवार का हिस्सा माना जाता था। गाय को विशेष रूप से पूजनीय और पोषण का स्रोत माना गया। पशुओं के प्रति हिंसा को पाप समझा जाता था।</p></li>\r\n    <li><p>वेदों में प्रकृति की जैव विविधता का सम्मान किया गया है। यह माना गया कि हर प्राणी और पौधा प्रकृति के संतुलन के लिए आवश्यक है।</p></li>\r\n    <li><p>वैदिक काल में पर्यावरणीय संतुलन को आध्यात्मिकता से जोड़ा गया। यह धारणा थी कि प्रकृति के हर तत्व में ईश्वर का वास है। अतः किसी भी प्राकृतिक तत्व को हानि पहुंचाना पाप माना गया। \"वसुधैव कुटुम्बकम्\" का सिद्धांत भी इसी विचारधारा पर आधारित है, जिसमें संपूर्ण पृथ्वी को एक परिवार माना गया।</p></li>\r\n</ul>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>वैदिक काल में पर्यावरणीय जागरूकता का स्तर अत्यंत ऊंचा था। यह काल हमें सिखाता है कि प्रकृति के साथ सामंजस्य बनाकर कैसे जीवन जिया जा सकता है। इस बात को रोमिला थापर,आर.सी. मजूमदार,डॉ. राधाकुमुद मुखर्जी,विनीता दामोदरन,डी.एन. झा यदि इतिहासकारो ने समर्थन दिया है। आज के समय में, जब पर्यावरण संकट गहराता जा रहा है, वैदिक काल की इस पर्यावरणीय चेतना से प्रेरणा लेना आवश्यक है। यदि हम प्रकृति के साथ वैदिक काल की तरह सामंजस्यपूर्ण संबंध स्थापित कर सकें, तो मानवता का भविष्य सुरक्षित हो सकता है।</p>\r\n',145,'2025-01-31 06:56:54','2025-01-31 07:57:50','','Publish',0,'open',45,77),('अर्थशास्त्र के साथ इतिहास का संबंध।','relation-of-history-with-economics',2,'<p>अर्थशास्त्र और इतिहास दोनों ही महत्वपूर्ण शाखाएं हैं जो मानव समाज के विकास और उसके संगठन को समझने में मदद करती हैं।अर्थशास्त्र के साथ इतिहास का गहरा संबंध है। समाज में मानव के क्रियाकलापों का आर्थिक घटनाओं से घनिष्ठ रूप से जुड़ा हुआ है अतः एक इतिहासकार के लिए यह अत्यंत आवश्यक है कि वह अपने युग के आर्थिक युग के दशाओं के भली-भाँति कई प्रकार से जानकारी रखें ताकि वह अपने समाज की आर्थिक दशाओं से अध्ययन कर सकें।</p>\r\n<p>प्रसिद्ध इतिहासकार बी शेख अली ने लिखा है कि \"डार्विन ने अस्तित्व के संघर्ष के संबंध में संकेत किया। वही कालमार्क्स ने आर्थिक इतिहास पर प्रकाश डाला, विशेष रूप से 1917 के रूसी क्रांति के समय आर्थिक इतिहास में अत्यधिक महत्त्व प्राप्त किया और मानव जीवन के आर्थिक इतिहास (घटनो) महत्त्व को प्रतिविधित किया।\"</p>\r\n<p>पिछले कुछ वर्षों में अर्थशास्त्र का अत्यन्त कठिन व जटिल बन गया है सामान्यतः इतिहासकार को गणित का ठोस ज्ञान प्राप्त नहीं होता इसलिए अर्थशास्त्र का समुचित ज्ञान प्राप्त करने के लिए उसे पर्याप्त समय तक इसका अध्ययन करना पड़ता हैं। जिसके कारण इतिहास अध्ययन के लिए समय कम पड़ जाता है, जिसके परिणामस्वरूप एक नवीन प्रकार के इतिहासकारों का उदय हुआ। जिन्हे आर्थिक इतिहासकार के नाम से जाना जाता है, जो मूल रूप से अर्थशास्त्र अध्ययन में परांगत होते और जिन्होने देश की आर्थिक दशाओं के कार्मिक प्रकाश डाला है। अन्य इतिहासकार केवल उनके पद चिन्हों का अनुपालन (अनुसरण) करते हैं और उनके द्वारा निकाले गए परिणामों को ही मान्य प्रदान करते हैं। आधुनिक समय में इतिहास का अध्ययन बहुत कुछ आर्थिक समस्याओं के विश्लेषण से संबंध हैं एक इतिहासकार के लिए लगभग असंभव है कि वह बिना अर्थशास्त्र के ज्ञान के इतिहास लेखन का कार्य को पूर्ण कर सकें।</p>\r\n<p>आधुनिक वर्तमान युग के इतिहासकारों को अपने समय के आर्थिक संकटों का पूर्ण ज्ञान होना चाहिए तभी वह इतिहास के महत्वपूर्ण पहलु आर्थिक इतिहास का विश्लेषण व विवेचना कर सकेंगे। विश्व की आर्थिक घटनाओं (नई आर्थिक नीती, विश्व आर्थिक मंदी, वैश्वीकरण आर्थिक एवं व्यापारिक ढांचे आदि) की जानकारी के अभाव में 20 वीं शताब्दी के इतिहास उचित लेखन प्रस्तुत कर पाना मुश्किल है।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>उपयुक्त वर्णनों के आधार पर यह स्पष्ट है कि वर्तमान युग में अर्थशास्त्र यवं इतिहास के बीच परस्पर संबंध है और एक के बिना दूसरों का अस्तित्व अधूरा है। आर्थिक गतिविधियों इतिहास के लिए अत्यंत महत्वपूर्ण है, क्योंकि इन्हीं गतिविधियों के आधार पर एक इतिहासकार आर्थिक दशाओं को वर्णन कर पाता है। इस तरह एक अर्थशास्त्री आर्थिक घटनाओं का क्रमिक अध्ययन के पश्चात्य ही अर्थशास्त्र के विषय वस्तु को समझ सकता है अर्थशास्त्र इतिहास से अत्यंत संबंधित हैं।</p>\r\n',101,'2025-01-31 12:13:02','2025-01-31 17:56:27','','Publish',0,'open',0,78);
INSERT INTO `article` VALUES ('इतिहास का प्राच्चवादी उपागम।','orientalist-approach-to-history',2,'<p>प्राच्चवादी प्राय: उन यूरोपीय विद्वानों को कहा जाता था जिन्हें प्राचीन इतिहास और संस्कृत के अध्ययन में रुचि ली। 18 वीं सदी से भारतीय इतिहास और संस्कृत के प्रति यूरोपीय विद्वानों ने रुचि लेना प्रारंभ किया। <strong>15वीं शताब्दी में यूरोप के साथ भारत का व्यापारिक संबंध स्थापित हुआ।</strong> जिसके परिणाम स्वरूप विभिन्न <strong>यूरोपीय विद्वानों और यूरोपीय मिशनरीयो</strong> एशिया के इतिहास के प्रति आकर्षित हुए। प्रारंभिक दौर में यूरोपीय विद्वानों का ध्यान भारत के विशेष संदर्भ में विशेषत: संस्कृत और फारसी भाषा के अध्ययन के ओर आकर्षित हुआ। 18वीं शताब्दी के अंत में <i>\"रॉयल एशियाटिक सोसाइटी\"</i> की स्थापना के साथ ही व्यवस्थित तौर पर प्राचीन भारतीय संस्कृत ग्रंथ का विशेषकर वैदिक ग्रंथ के अध्ययन और अनुवाद पर जोर दिया।</p>\r\n<p><strong>1765 ई (इलाहाबाद की संधि) में बंगाल, बिहार, उड़ीसा पर जब ईस्ट इंडिया कंपनी का शासन स्थापित हुआ।</strong> तो शासको को हिंदुओं की उत्तराधिकार एवं न्याय व्यवस्था स्थापित करने में कुछ कठिनाइयां सामने आई। परिणामत: <strong>1776 ईस्वी में मनुस्मृति का अंग्रेज़ी अनुवाद The Code of Jento Lowes के नाम से प्रकाशित किया गया।</strong> इसे देखकर यूरोप की विद्वानों में खलबली मच गई अर्थात द्विवेदी के अनुसार- <i>\"जिस जाति के ज्ञान भंडार में ऐसी ऐसी पुस्तके विद्वमान है उनका भूतकाल बडा ही उज्जवल रहा होगा उसमें ऐसी न जाने कितने ग्रंथ और होंगे यथायोग इस जाति के पूर्व इतिहास से परिचय प्राप्त करने से अनेक लाभ होने की संभावना है।\"</i></p>\r\n<p>इस प्रकार के संभावना से प्रेरित होकर <strong>सर विलयम जॉन्स ने तत्कालीक गवर्नर जनरल वॉरेन हेस्टिन की सहायता से कोलकाता में 1784 ईस्वी में एशियाटिक सोसाइटी बंगाल नामक संस्था की स्थापना की</strong> इस संस्था ने एशिया के इतिहास, साहित्य, स्थापत्य, धर्म, समाज और विज्ञान आदि विषयों के संबंध में खोज करना अपना उद्देश्य निश्चित किया।</p>\r\n<p>प्राच्चवेदो में सर जॉन्स का प्रमुखता से लिया जाता है। वे 1783 में फोर्ड विलियम के प्रधान न्यायाधीश के पद पर नियुक्त हुए थे। न्यायाधीश के रूप में उन्होंने अनुभव किया की प्राचीन भारतीय सामाजिक परंपराओं और रीति-रिवाज के जाने बिना भारतीय न्याय व्यवस्था का सुचारू संचालन संभव नहीं है। उन्होंने प्राचीन संस्कृत ग्रंथों के अध्ययन के साथ-साथ उनके अनुवाद की आवश्यकता महसूस की।<strong> सर विलियम जॉन्स ने 1789 में कालिदास के <i>\"अभिज्ञानशाकुन्तल्म\"</i> का अंग्रेज़ी अनुवाद किया।</strong> जर्मन कवि जेटे ने इस अनुवाद की काफी प्रशंसा की है। इससे प्राचीन भारतीय <i>\"वाङ्गमय\"</i> के अध्ययन और अनुशीलन को काफी बढ़ावा मिला।</p>\r\n<p>प्राच्चवादी इतिहासों में विलियन जॉन्स के बाद <strong>चार्ल्स विलिकन्स</strong> अत्यंत महत्वपूर्ण है।उन्होंने भी संस्कृत का ज्ञान प्राप्त किया था। इन्हीं के प्रत्यनो से <strong>देवनागरी और बंगाल</strong> के टाइप तैयार किए गए। <strong>1785 में इन्होंने भागवत गीता का अंग्रेज़ी अनुवाद किया था।</strong> येसियाटिक सोसाइटी में 1778 ईस्वी में <strong>Asiatic Researches</strong> नामक पत्रिका निकाली। सर विलियम जॉन्स के मृत्यु के बाद उनका स्थान उनके सहयोगी हेनरी लोलबुक ने लिया था। उन्होंने भारत के संबंध में अनेक लेख लिखे। उनके द्वारा <strong>On The Vedas</strong> नामक पुस्तक एवं हिंदुओं के धार्मिक रीति-रिवाज, भारतीय वर्ण व्यवस्था की उत्पत्ति संस्कृत एवं प्राकृतिक भाषा इत्यादि महत्वपूर्ण लेख लिखे गए हैं। इसके अलावा भी वेद, संख्या निमांसा, न्याय, वैशोषिक, वेदांत, भारतीय कृषि, समाज, कानून, धर्म, गणित इत्यादि विषयों पर भी विध्वतापूर्ण लेख लिखे गए।</p>\r\n<p><strong>1804 ईस्वी में मुंबई में एशियाटिक सोसाइटी की स्थापना हुई।</strong> 1823 ईस्वी में ग्रेट ब्रिटेन के लंदन में स्थापना हुई सर्वप्रथम विलियम जॉन्स ने यह अवधारना प्रस्तुत की थी की मूलतः यूरोपिए भाषाऐ संस्कृत और ईरानी भाषाऐ से मिलती-जुलती हैं। इस तथ्य से प्रभावित होकर जर्मनी, फ्रांस, रूस, यूरोपीय इत्यादि देशों में भारतीय विद्या के अध्ययन में अधिक रुचि जागृत हुई। 19वीं शताब्दी के पूर्वार्ध में इंग्लैंड साहित्य अन्य यूरोपीय देशों में संस्कृत के आचार्य पद स्थापित हुए। 1818 ईस्वी में जर्मन के विश्वविद्यालय में संस्कृत के विभाअध्यक्ष के पद पर वॉन इलेगल की नियुक्ति हुई। इनके भाई फ्राइड्रीश इलेगल थे। संस्कृत के विद्वान थे।  हर्न विल्हेम नमक एक जर्मन विद्वान ने इन्हि इलेगल बंधुओ के प्रेरणा से गीता का अध्ययन किया और उसे एक उच्च कोटि की साहित्य की संज्ञा दी। उपनिषदों का भी जर्मन भाषा में अनुवाद हुआ। प्रसिद्ध जर्मन दार्शनिक शापेनहावर ने उपनिषद को मानव वृद्धि की सर्वोच्य उपज करार देते हुए यह कहा है कि इसका अध्ययन मेरे जीवन के लिए तो आश्वासन है ही मेरी मृत्यु के लिए भी आश्वासन सिद्ध होगा। <strong>जर्मन के महान विद्वान F मैक्समूलर ने भारतीय विद्या के अध्ययन को सर्वाधिक बढ़ावा दिया।</strong> उनेक संपादन में <strong>Secred Books Of The East</strong> शीर्षक के तहत लगभग 50 खंडों में पुस्तक का अनुवाद किया गया। यद्यपि इस श्रेणी में कुछ चीनी और ईरानी ग्रंथो का अनुवाद भी शामिल था। परंतु मुख्यत: प्राचीन भारतीय धर्म ग्रंथ शामिल थे।</p>\r\n<p>जर्मनी के प्रमुख पुराविद् विन्टरनिट्ज ने भारतीय प्राचीनतम ग्रंथो के अनुवेशन और अनुवाद पर प्रतिक्रिया व्यक्त करते हुए मत दिया है कि जब भारतीय वाङ्गमय पश्चिम में प्रथम बार प्रकाश में आया तब अधिकांश विद्वानों की रुचि प्रत्येक भारतीय ग्रंथ को प्राचीनतम मानने में थी। प्राचीनतम भारतीय वाङ्गमय के प्रति बढ़ती रुचि यूरोपीय देशों के कोसो ओर संदर्भ ग्रंथो की रचना को भी प्रोत्साहित किया। राय और बोथलिंग के अथक प्रयासों से 7 खण्डों में सस्कृत जर्मन शब्दकोश का निर्माण हुआ। इसी परंपरा में मोनियर विलियम्स ने संस्कृत अंग्रेजी शब्दकोश का प्रकाशन किया। <strong>संदर्भ ग्रंथों के रूप में ब्लूमफील्ड का A Vadic Confardace तथा मैकडोनाल्ड  एवं कीय का Vedic Index का एक सहनीय प्रयास था।</strong></p>\r\n<p><strong>रोमिला थापर</strong> ने इतिहास के प्राच्चवादी उपागम को स्पष्ट करते हुए लिखा है कि- <i>\"जीवन प्राच्चवादीयों ने संस्कृत का अध्ययन किया है वह आर्य भाषा-भाषी संस्कृत के उत्साहि प्रतिपादक बन गए उन लोगों ने भारत यूरोप मूल स्थान और संस्कृत और यूनानियों संस्कृतयों की समान पूर्वज परंपरा का सिद्धांत विकसित किया आर्यों को संबंध भाषा बोलने वाले लोगों के समूह के स्थान पर एक जातिय इकाई के रूप में देखा गया और भारत की आर्य संस्कृति और यूरोप की यूनानी संस्कृति के गति विज्ञान को संबंध करने के कोशिश की गई। वैदिक युग को बड़ा चढ़ाकर आका गया और प्राच्चवेदो ने प्राचीन भारतीयों को खुशहाल ग्राम समाज के लोगों के रूप में देश तनाव भरे बातों की नजर अंदाज कर किया गया और गौरव पक्षपर जोर दिया गया।\"</i></p>\r\n<p>उपरोक्त विवेचनाओं से स्पष्ट है कि प्राच्चवादीयों ने भारत के अतीत का महिमामंडन किया। परंतु ऐसे लेखन के पीछे उनका क्या उद्देश्य था यह भी जाना आवश्यक है। रोमिला थापर के अनुसार बहुत से प्राच्चवेदो ऐसे थे जो अपने समाज से बेगानी हो गए थे। <strong>औद्योगीकरण के फलस्वरुप यूरोप भौतिकवादी परिवर्तनों के प्रति उनके मन में संदेह व्याप्त था। वह एक आदर्श लोगों के तलाश में थे उन्होंने अपने आदर्श लोगों की तलाश प्रच्चजगत की संस्कृतियों में पूर्ण होती दिखाई दी।</strong> अतः प्राच्चवेदो ने भारतीय संस्कृति को आदर्श के साचे में ढ़ालकर उनके साथ तादात्य (सामंजस्य) स्थापित करने का दूसरा कारण यह भी था कि उसे समय ब्रिटेन में उपयोगिता वादी दर्शन का विकास हो रहा था जिससे प्राच्चवेदो की पुर्ण अहशमती थी। उपयोगिता वादीयो का मानना था कि भारत में अंग्रेजों का शासन एक दैविय संयोग सहयोग और भारत जैसे पिछड़े हुए देश का पिछड़ापन ब्रिटिश प्रशासन एवं कानून के द्वारा दूर किया जा सकता है।</p>\r\n<p><strong>रामशरण शर्मा</strong> ने भी प्राच्चवेदो द्वारा बेहद मात्रा में प्राचीन भारतीय ग्रंथ के अनुवाद कार्य के पीछे उनकी निहित उद्देश्यों पर प्रकाश डाला है। <strong>उनके अनुसार मनुस्मृति के अंग्रेजी अनुवाद का प्रमुख कारण ईस्ट इंडिया कंपनी द्वारा हिंदू उत्तराधिकार संबंधी न्याय व्यवस्था में आ रही कठिनाइयों को दूर करने की इच्छा थी।</strong> कुछ प्रच्चवेद ईसाई धर्म के प्रचार प्रसार की भावना से प्रेरित थी। मास्कमूल्य के बारे में आम धारणा या है कि वह प्राचीन भारतीय धर्म ग्रंथो में सनातन धर्म की खामियां ढूंढता चाहता था। आर एस शर्मा के अनुसार 1857 के विद्रोह में ब्रिटिश शासन की आंखें खोल दी उन्हें महसूस हो गया कि जिन विदेशियों पर उन्हें शासन करना है उनके रीति-रिवाज और सामाजिक व्यवस्थाओं का उन्हें गहन ज्ञान प्राप्त करना हो। इसाई धर्म प्रचारकों ने हिंदुओं धर्म के दुर्बलताओं को जानना आवश्यक समझा ताकि वह धर्म परिवर्तन कर सके। <strong>मोनियर विलियंस</strong> ने अपने संस्कृत अंग्रेजी शब्दकोश की भूमिका मैं स्पष्ट लिखा है कि- <i>\"वोडेन द्वारा स्थापित ट्रस्ट के माध्यम से संस्कृत ग्रंथो के अंग्रेजी अनुवाद का जो कार्य हो रहा है वह भारतीयों को ईसाई बनाने में प्रकारांतर से सहायक सिद्ध होगा।\"</i></p>\r\n<p>प्राच्चवेदो द्वारा अपनाई जानने वाला उप्त दृष्टिकोण के बावजूद उनके प्रयास भारतीयों के लिए लाभदायक सिद्ध हुए। प्रच्चवेदी लेखन का भारतीय समाज और चेतना पर गहरा प्रभाव पड़ा। सकरात्मक दृष्टि से देखे तो <strong>19वीं सदी में उनके धार्मिक सामाजिक सुधार आंदोलन पर प्रच्चवेदी इतिहासकारों का प्रभाव था।</strong> आर्य समाज द्वारा वैदिक परंपरा पर जोर देकर ब्रह्म समाज द्वारा चलाए गए सुधार आंदोलन में एशियाटिक सोसाइटी, रामकृष्ण मिशन आदि के सिद्धांत प्राच्चवादी लेखन से प्रभावित थे प्राच्चवेदो ने संस्कृत और यूनानी भाषा तथा आर्य व यूनानी संस्कृति को संबंध करने का प्रयास किया। इसने ब्रिटिश शासन वर्ग और शासित भारतीय वर्ग के बीच संबंध को विकसित किया जिसका राजनीतिक करणो से स्वागत भी हुआ।</p>\r\n<p>इस प्रकार हम देखते हैं कि प्राच्चवादी इतिहास उपागम भले ही ईसाई धर्म के प्रचार की भावना व अन्य भावनओ से प्रभावित रहा। परंतु उन्होंने प्राचीन भारतीय वाङ्गमय की ओर न केवल यूरोपीय विद्वान के जगत अपितु पक्षात्म शिक्षा प्राप्त भारतीयों का भी ध्यान आकर्षित करने का प्रयास किया। <strong>सर विलियम जॉन्स, मैक्समूलर, पोलगुरुप, H.H विल्सन, बौथलीगं, मोनियर विलियनस जैसे प्राच्चवादीयों ने निसंदे प्राचीन भारतीय वाङ्गमय का अनुवेशन एवं अनुवाद कार्य संपन्न कर आगामी भारतीय इतिहास लेखन एक अनुसंधान हेतु प्रचुर मात्रा में आधार सामग्री उपलब्ध करने का सारनिया कार्य संपन्न किया।</strong></p>\r\n',92,'2025-01-31 12:13:02','2025-01-31 17:59:18','','Publish',0,'open',0,79),('इतिहास का राष्ट्रवादी उपागम','nationalist-approach-to-history',2,'<p>वाद का तात्पर्य भावनाओं के संगठित अभिव्यक्ति है। वाद एक विचारात्मक शक्ति है जो किसी विचार को संगठित रूप देता है। राष्ट्रवाद राष्ट्रीयता के भावना पर निर्भर करती है। यह राष्ट्रीयता की भावना को संगठित कर उसे भावनात्मक शक्ति का रूप देता है। यह शक्ति राष्ट्रीयता को राष्ट्र के रूप में होने में मदद करती है। सभ्यता और बुद्धि के नियंत्रण विकास में मानव को कुटुम ग्राम और छोटे-छोटे राज्यों के सीमा के बाद देश के विस्तृत भूखंड के मोह-पास्य में बांध दिया था। राष्ट्रीय के भावना से युक्त देश को ही एक राष्ट्र की संज्ञा से अभिव्यक्त किया जाता है। राष्ट्र के प्रति तीव्र एवं गहन का घनत्व और महत्व की भावना से राष्ट्रीयता का जन्म हुआ है।</p>\r\n<p><strong>19वीं शताब्दी में भारतीयों में एक नवीन चेतना का प्रदूभाव हुआ। इस नवीन चेतना के परिणाम स्वरुप भारतीयों ने अपने संकटग्रस्त वर्तमान को अनुभव किया। जबकि देश का अतीत अत्यंत गौरवशाली था।</strong><span> भारतीय सामाजिक चरित्र का विशेषता यह है कि उसे अपने शक्ति का अनुमान तब होता है जब कोई दूसरा उसे अभास्य करता है</span> ठीक यही बात भारतीय चेतना के जागृति में हुई थी। A.B कीय निट्रज इत्यादि के बताने पर भारतीय के अपने उच्च ज्ञान का अनुमान हुआ। बुद्धिजीवी भारतीयों ने देखा कि ब्रिटिश विद्वान भारतीय इतिहास का उपयोग अपने साम्राज्यवादी पक्ष को मजबूत बनाने के लिए कर रहे हैं। <strong>19वीं शताब्दी में कई भारतीय विद्वान ने अपने गौरवमय अतीत का महिमामण्डन कर देशवासियों के खोए आत्मविश्वास को जगाने का प्रयास किया।</strong> बंकिग चन्द्र ने बंगाल भाषा में <span>आनंद मठ</span> नामक उपन्यास की रचना की जिसका एक गीत वन्दे मातरम भारतीय मुक्ति संग्राम का प्रेरणा स्रोत बन गया। उनके उपन्यासों को भारतीय राष्ट्रवाद के कड़ी के रूप में स्वीकार किया गया।</p>\r\n<p>स्वामी दयानन्द सरस्वती ने ब्रिटिश इतिहासकारों द्वारा वेदों की त्रुटि पूर्ण व्याख्या को<span> सत्यार्थ प्रकाश</span> नामक ग्रंथ द्वारा परिक्रित करने का प्रयास किया और साथ ही साथ आर्य समाज की स्थापना कर हिंदू धर्म की कुरितियो और रूढ़ियों का दमन कर जनमानस में आत्मविश्वास और आत्मसम्मान लाने का कार्य किया। इस परिवेश में उनकी रचनाओं को राष्ट्रवादी इतिहास लेखन की पूर्ण पिठिका स्वीकार किया जा सकता है। </strong>स्वामी विवेकानंद(1863-1902) ने अपने नव वेदांत द्वारा पुरातन पद्धति भारतीय समाज पर अठाराघाट (चोट) किया।</strong> उन्होंने भारतीयों को कहा- <i>\"उठो जागो और अपने लक्ष्य को प्राप्त करो\"</i> इसप्रकार विवेकानंद वास्तव में Prophel Of Indian Nationalish थे।</p>\r\n<p>राजाराम मोहन राय (1774-1833) ने भारतीय साहित्य के गौरवमय अतीत के परंपरा को आगे बढ़ाया और राजेंद्र लाल मित्र वगरह (इत्यादि) ने उनका अनुसरण किया। जिस समय राजेंद्र लाल मित्र भारतीय साहित्य के दुर्लभ ग्रंथो का प्रकाशन कर रहे थे। उन दिनों इतिहास लेखन की विवित विद्या से प्रभावित भी नहीं हुई थी परंतु वे राष्ट्रीयता के भावना से उब गए थे। भारतीय इतिहास को आधुनिक विधि से लिखने वाले वे प्रथम भारतीय इतिहासकार थे। उनके लेखो का संकलन <span>The Indo Argans</span> के नाम से प्रकाशित हुआ। रमेश चंद्र दत्त उनके सामकालीन थे। र्स्वेदत ने ऋग्वेद का बंगाल अनुवाद करने के साथ-साथ चार ऐतिहासिक उपन्यासों के भी रचना की। सन् 1889 ईस्वी में उन्होंने तीन करो में <span>A History of Civitization in Aacient India</span> की रचना की। 1857 में आर सी दत्त ने इंग्लैंड एवं इंडिया लिखीं। जिनमें उन्होंने भारत के अकाल और निर्धन प्रज्ञा के प्रति ब्रिटिश शासन के दृष्टिकोण को स्पष्ट किया। उनकी र्स्वेधिक महत्वपूर्ण क्रिति इक्नौकम हिस्ट्री ऑफ इंडिया है। जिसकी रचना श्रीदत्त ने मूल पत्रों, दस्तावेजों एवं अभिलेखों के आधार पर किया था। इससे इन्होंने 1757 से 1900 ई तक भारत के आर्थिक शोषण का जीवन चित्रण प्रस्तुत किया है।</p>\r\n<p>19वीं शताब्दी के पूर्वार्ध में लॉर्ड विलियन मैन्टिक की कार्यकारी परिषद में विद्यी सदस्य लॉर्ड मैकॉले ने भारतीय शिक्षा एवं ज्ञान को भिन्न बताया तथा उसके रिपोर्ट के अनुसार अंग्रेजी भाषा को शिक्षा का माध्यम स्वीकार कर लिया गया। भारतीयों ने राजाराम मोहन राय के प्रयास शिक्षा के क्षेत्र में सहारणीय है। <strong>नई शिक्षा नीति के कारण यूरोप यह विचार को थॉमस हॉब्स, जॉन लॉग, रूसो, फ्रेंच एवं अमेरिकी क्रांति आदि का अध्ययन करने का शुभ अवसर भारतीय विद्वानों को मिला। परिणाम स्वरुप मध्यम वर्ग में विद्वानों का एक समूह उत्पन्न हुआ।</strong> यह समूह समाज की रूढ़िवादी और कुर्तियां से छूट (दुखी) थी ।अतः इन्होंने जीवन दर्शन का नया आधार प्रस्तुत किया। भारत का नवजागरण हुआ इसके प्रवर्तकों में प्रमुख थे- श्री रामकृष्ण परमहंस, अक्षय कुमार दत्,  ईश्वर चंद्रगुप्त, काली प्रसंग सिंहा, राजा राधाकांत देव, हेनरी विलियन, डेविड हेयर, ईश्वर चंद्रविद्यासागर, कालनारायण बोस, बिपिनचंद्र पाल, देवेंद्र नाथ टैगोर इत्यादि इन सबों ने अपनी-अपनी ढंग से भारतीय नवजागरण में महत्वपूर्ण भूमिका निभाई। परिणाम स्वरुप <strong>भारतीय राष्ट्रवाद का उदय</strong> हुआ। पुनर्जागरण कालीन नेताओं ने एक और ब्रिटिश शासन के शोषण के रेखांकित किया तो दूसरी ओर भारत के गौरव को विश्व में स्थापित किया। राष्ट्र निर्माण में इतिहास की भूमिका को अस्वीकार नहीं किया जा सकता इन विभूतियों ने राष्ट्रीय चेतना के निर्माण में योगदान कर राष्ट्रवादी इतिहास लेखन की प्रक्रिया के आधारशिला रखी।</p>\r\n<p>महादेव गोविंद रानाडे सन (1876-78) ईस्वी में भारत के पड़े आकाल में ब्रिटिश सरकार की नीति की कटु आलोचना की एवं सरकार के विरुद्ध होने में आंदोलन का भी श्री गणेश से किया। <strong>सन 1878 ई के वर्नाकुलर प्रेस एक्ट और 1861 के भारतीय परिषद अधिनियम तथा 1883 ई के इलबट बिल के विरोध के विरुध वह मुखर हो गए और आंदोलन का नेतृत्व किया।</strong> इसी समय उन्होंने <span>The rise of matatha power</span> की रचना कर छत्रपति शिवाजी के बारे में ब्रिटिश इतिहासकारों द्वारा फैलाई गई भ्रांतियां का निराकरण किया।</p>\r\n<p>सुरेंद्रनाथ बनर्जी एवं दादा भाई नौरोजी ने ब्रिटिश सरकार द्वारा भारतीय संप्रदाय के शोषण और दोहन की आलोचना की R.C मजूमदार, A.C दत्, V.D सार्वकर इन लेखकों के रचनाओं ने भी राष्ट्रीय चेतना का निर्माण कर राष्ट्रवादी इतिहास लेखन की अवधारण का संचार किया। गंगाधर तिलक ने ब्रिटिश इतिहासकारों की इस अवधारणा का खण्डन किया कि आर्यों की मूलभूमि भारत नहीं है। उन्होंने <span>Archi Home of Aryans</span> नामक ग्रंथ के माध्यम से अपने पक्ष को स्पष्ट करने का प्रयास किया। <strong>प्रथम विश्व युद्ध के दौरान ब्रिटिश शासन भारतीय के सहयोग का आकांक्षी था परंतु युद्ध समाप्त होते ही इसका रूप बदल गया। उसने भारत को स्वशासन देना अस्विष्कार कर दिया।</strong> इसी पृष्ठभूमि में 1919 ईस्वी में V.A स्मिथ ने <span>Oxford History of India</span> प्रकाशित की Smith ने प्रमाणित करने का प्रयास किया कि भारत में कभी भी स्वशासी संस्थाएं थी ही नहीं स्मिथ की इस पक्षपातपूर्ण मत का खंडन करते हुए फासी प्रसाद जैस्वाल ने<span> \"हिंदू पालिटी\"</span> नामक प्रसिद्ध ग्रंथ की रचना की। उन्होंने यह सिद्ध किया कि जिस लोकतांत्रिक प्रणाली पर पश्चात राजनीतिक संस्थाओं का गर्व है वह भारत में ईसापुर 6ठी शताब्दी में प्रचलित था। जब यूरोप नगन्ता के दौर में से गुजर रहा था।</p>\r\n<p>हरिश्चंद्र मुखर्जी, सुशील कुमार गोस, रामगोपाल गोस इत्यादि ने नील की खेती करने वाले किसानों की दरदशा की संबंध में पुस्तक लिखी। K.A नीलकंठ शास्त्री ने अपनी पुस्तक History of Sowth India में दक्षिण प्रांतो में आए स्थिति के प्रचार प्रसार का उल्लेख कर उत्तर-दक्षिण विवाद को समाप्त करके संपूर्ण भारत को एक संस्कृतिक खंड के रूप में प्रस्तुत किया। राखा कुमुद मुखर्जी एवं H.C राय चौधरी ने ब्रिटिश शासन की इस दृष्टिकोण से की गई व्याख्या कि उनके शासन में संपूर्ण बोस एक राष्ट्र के रूप में संगठित हो सका। चुनौती देते हुए प्रमाणित किया की ऊपरी तौर पर भारत की सांस्कृतिक विभिन्नता मूल्य रूप से उसकी एकता को प्रदर्शित करती है। इन लेखकों के रचनाओं ने राष्ट्रीय चेतना का निर्माण कर इतिहास चेतना में राष्ट्रवादी अवधारणा का संचार किया ऐतिहासिक संस्थाएं- भारतीय इतिहास संशोधन पुणे, आजी भण्डाकर ओरिएंटल रिसर्च इंस्टीट्यूट पुणे न केवल भारतीय इतिहास का पुनर्निर्माण किया बल्कि प्राचीन भारत के गौरवमय इतिहास को स्पष्ट भी किया। राष्ट्र के निर्माण में इतिहास का विशेष महत्व होता है। नवजागरण ने भारतीय इतिहास को जीवित करके राष्ट्र निर्माण अमूल्य योगदान दिया। अरविंद गोस ने इंद्रप्रकाश एवं वंदे मातरम, लाल गंगाधर तिलक राय ने पंजाब केसरी और बाल गंगाधर तिलक ने केसरी और मराठ के माध्यम से जनमानस के मन में यह प्रश्न जागृत करने का प्रयास किया कि आर्य वीर हम अंग्रेज के गुलाम क्यों हैं। इस प्रकार राष्ट्रप्रेम की भावना ने इस राष्ट्र को स्वतंत्र करने की भावना पैदा की। इसने भारतीयों के सास्कृत एकता और गौरव का निर्माण किया। इसी ने उसे आधारशिला का निर्माण किया जिस पर आधुनिक भारत की नीव है।</p>\r\n<p><strong>राष्ट्रवादी इतिहास लेखन का धारा का उद्भव एक कारण तत्कालीन भारत की विसिष्ट परिस्थितियों भी थी।</strong> ब्रिटिश इतिहासकारों ने प्राचीन और मध्यकालीन भारत के इतिहास का उदाहरण देकर हमारे अतीत को बहुत आलोचना की। राष्ट्रवादी इतिहासकार ने इस चुनौती को स्वीकार किया और अतीत का प्रशिक्षण प्रारंभ किया। उनके अनुसंधानों के फल स्वरुप इतिहास लेखन में प्राथमिक स्रोतों का चलन बढ़ गया। अतीत का विश्लेषण कर इतिहासकारों ने यह साबित किया कि समकालीन यूरोप की तुलना में भारत की कूटनीतिक एवं राजनीतिक संरचनाएं श्रेष्ठ थी। <strong>उन्होंने कौटिल्य के अर्थशास्त्र की प्रशंसा करते हुए कहा कि इससे साबित होता है कि भारतीय प्रशासन कूटनीति और राज्य के आर्थिक प्रबंध में अत्यंत दक्षय थे।</strong> कई इतिहासकारों ने राज्य पर धर्म के प्रभाव की आवहेलना करते हुए इस बात पर जोर दिया कि भारतीय राज्य पूरी तरह से धर्मनिरपेक्ष हुआ करते थे। उन्होंने भारतीय शासको की निरुकशता के मत का भी खंडन किया उन्होंने जन्म कल्याण और न्याय प्रयता के कई उदाहरण प्रस्तुत किया और उन्होंने साबित किया कि सरकार गैर जिम्मेदार नहीं थी। राजा की शक्ति और निरूकुस्ता पर कई प्रकार के प्रतिबंध लगे हुए थे। कुछ इतिहासकार ने तो यह तक साबित किया कि राजतंत्र संभवतः राजनीतिक राजतंत्र था। ग्राम पंचायत वह स्थानीय प्रशासन का गठन लोकतांत्रिक तरीके से होता था। कर व्यवस्था की आधुनिक कर व्यवस्था के समान थी।</p>\r\n<p>राष्ट्रवादी दृष्टिकोण ने इस बात पर भी बल दिया कि पश्चिम में जिस राजनीतिक रूप से सकारात्मक माना गया था। वह सभी तत्व पहले से ही प्राचीन भारत में विद्यमान थे। श्रेष्ठ पश्चिमी संस्थाओं को प्राचीन भारत में ढूंढकर यह साबित करने का प्रयास किया गया कि हम किसी भी तरह से अपने पिछड़े हुए नहीं है। उपनिवेशवादी इतिहासकारों ने भारत को धर्म, आशा, क्षेत्र इत्यादि बाटकर यह साबित करने का प्रयास किया कि भारत की राजनीतिक एकता अंग्रेजी शासन की दिन थी और भारत इससे पूर्व कभी भी एक राजनीतिक सत्ता के अंतर्गत नहीं रहा। <strong>राष्ट्रवादी इतिहासकारों ने चंद्रगुप्त मौर्य, अशोक, समुद्रगुप्त, चंद्रगुप्त विक्रम आदित्य, अकबर आदि के उदाहरण द्वारा इस भ्रांति का निवारण किया।</strong> यहां यह ध्यान देनी होती है कि राष्ट्रवादी इतिहासकारों ने अपनी ऊर्जा का बड़ा अंश प्राचीन और मध्यकालीन इतिहास लेखन पर ही व्यय किया और यह से अधिक सफल भी रहे इन लेखकों ने आधुनिक इतिहास लेखन पर ध्यान नहीं दिया। इसका प्रधान कारण यह भी था कि ज्यादातर इतिहासकार सरकारी नौकर थे। उन्हें डर था कि सरकारी नीतियों की आलोचना करने पर उन्हें दण्डित किया जा सकता है। आजादी के बाद राष्ट्रवादी इतिहासकारों ने आधुनिक भारत के इतिहास पर अधिक ध्यान देना प्रारंभ किया।</p>\r\n<p>इतिहास लेखन की राष्ट्रवादी धारा ने कई दृष्टिकोण से देशवासियों के आत्म सम्मान को बढ़ाने में महत्वपूर्ण भूमिका निर्वहन किया। प्राचीन और मध्यकालीन इतिहास लेखन की कई श्रेष्ठ परंपराएं इन लेखकों के अनुसंधान के कारण ही प्रकाश में आई। निशांडे भारतीय इतिहास लेखन में राष्ट्रवादी इतिहास लेखन का महत्वपूर्ण स्थान है। राष्ट्रवादी इतिहासकारों का महत्व इसलिए भी अधिक बढ़ जाता है क्योंकि उनके पास संसाधनों की अत्यंत कमी थी पुरातत्व अभी शुरू ही हुआ था समाजशास्त्र और मानव शास्त्र का उपयोग न के बराबर हो रहा था। सरदारो मदार (सारा दायित्व) लिखित स्रोतों पर ही था। अल्प संसाधनों के साथ राष्ट्रीय गौरव को आयत में महती भूमिका निर्वहन के कारण इतिहास लेखन की यह धारा अत्यंत महत्वपूर्ण है।</p>\r\n ',155,'2025-01-31 12:13:02','2025-01-31 18:01:17','','Publish',0,'open',0,80),('इतिहास के कार्य-करण के सिद्धांत।','theories-of-the-working-of-history',2,'<p>कार्य-कारण का शाब्दिक अर्थ होता है कार्य और करण। मानव कोई भी कार्य किसी न किसी कारण से परेरित या  प्रोत्साहित होकर करता है। अत: कार्य-करण का अध्ययन इतिहास की प्रमुख विषय-वस्तु है। कॉलिंगवुड महोदय के अनुसार  <i>\"कारण वह प्रमुख तत्व है जो मनुष्य को कार्य करने के लिए प्रेरित या प्रोत्साहित एवं बाध्य करता है।\"</i> 18 वीं शताब्दी में जब आधुनिक इतिहास लेखन की नींव पड़ रही थी तब मॉन्टेस्क्यू ने अपने प्रसिद्ध पुस्तक <strong>Considerations on the Causes of the Greatness of the Romans and their Decline</strong> के आरंभ में यह सिद्धांत स्वीकार किया था कि<i> \"प्रत्योक राजवंश के उत्थान राजत्वकाल और पतन के पीछे कुछ नैतिक या भौतिक अर्थात सामान्य कारण होते हैं।\"</i> और यही भी की जो कुछ भी घटित होता है इन्हीं कारणों के तहत होते हैं। E.H कार ने भी कार्य-करण संबंध को इतिहास की कुंजी कहा है।</p>\r\n<p>इतिहास में कोई घटना बिना कारण नहीं होती है। प्रारंभिक समय में इतिहासकार और विद्वान घटनाओं के कारण को महत्त्व नहीं देते थे। क्योंकि वे इन्हें ईश्वर की इच्छा में हस्तक्षेप मानते थे परंतु कारणों की अनिवार्यत को समझा गया। क्योंकि वे भविष्य के कार्यों के एक महत्वपूर्ण मार्गदर्शन स्वीकार किया गया। <strong>प्रारंभ में इतिहासकार केवल घटनाओं पर अपना ध्यान केंद्रित रखते थे। जैसे युद्ध कहाँ और कब हुआ और इनमें कितने लोग मारे गए थे और सेनाएं की योजना किस प्रकार थी।</strong> लेकिन कलांतर में इतिहासकार का दृष्टिकोण मूल्य आंकलन पर आधारित हो गया। अतः घटनाओं के कारणों की ओर विद्वानों का ध्यान आकर्षित होने लगा। कार्य-करण के अनेक सिद्धांत है और प्रत्योक सिद्धांत एक तर्कसंगत प्रतीक होते हैं।</p>\r\n<h2 class=\"atech\">दैविक योजना</h2>\r\n<p>इस सिद्धांत के समर्थकों का विश्वास है कि इतिहास में भाग्य की महत्वपूर्ण भूमिका होती है। समस्त प्राचीन सभ्यता जैसे इस इज्यिशियन, बेबीलोनियम और ग्रीक का इस सिद्धांत में विश्वास है। प्रत्योक धर्म चाहे वे हिंदू, इस्लाम इत्यादि और चीनी सभी ने इस सिद्धांत का समर्थन किया है। इन सभी धर्मों का मानने वाले का विश्वास है कि राजा, नायक, पादरी और समाज के बुद्धिजीवी कई घटनाओं में महत्वपूर्ण भूमिका निभाते हैं लेकिन ऐसे बहुत सी घटनाएं होती हैं जो ईश्वरीय या ईश्वर की इच्छा से घटित होती है। इस प्रकार वे भगवान को कार्यों में प्रत्यक्ष हस्तक्षेप स्वीकार करते है। ऐसे इतिहासकार यह मानते हैं कि प्रत्योक घटना का कोई कारण होता है और वे अपने ढंग से उस घटना से संबंधित कोई कारण नहीं ढूंढ पाते हैं वे उसे ईश्वरीय घटना मान लेते हैं। </p>\r\n<p><span>प्रारंभिक समय में अधिकांश विद्वान ने इस सिद्धांत को स्वीकार कर लिया था। क्योंकि समाज पुरोहित वर्ग के द्वारा शासित होता था और पूर्व और पश्चिम में यह सिद्धांत अधिक व लोकप्रिय था।</span> क्योंकि उस समय लोग धर्म पर अधिक विश्वास रखते थे उस समय के विद्वान ईश्वरीय शक्ति में अंधविश्वास रखते थे और चर्च का उनका सामाजिक जीवन पर नियंत्रण रहता था। इस के साथ ही शिक्षा और ज्ञान का अभाव था इस कारण इस सिद्धांत को अधिक महत्त्व प्राप्त हुआ। परंतु वर्तमान समय में यह विश्वास किया जाता है कि प्रत्योक घटना का कोई न कोई कारण होता है और इसे गठित होने में व्यक्ति की महत्वपूर्ण भूमिका होती हैं।</p>\r\n<h2 class=\"atech\">बुद्धिवादी सिद्धांत</h2>\r\n<p>17 वीं - 18 वीं शताब्दी के लोगों में जागृति आने लगी थी। और इस काल में समाज के लोग में बुद्धि का प्रसार होने लगा और लोगों में चेतना का विकास हुआ। अनेक इतिहासकार विद्वान और ज्ञानियों ने घटनाओं के घटित होने में दैविक योजना का बहिष्कार किया। उन्होंने ने मानव के विकास में ईश्वर का संलगन होने में असहमति प्रकट की। <span>उन्होंने मानव की और अपना ध्यान आकर्षित किया तथा उसकी भूमिका पर विशेष बल दिया।</span> इतिहासकारों ने घटनाओं को नए तरीके से अपनाना प्रारंभ किया। लॉग का मत है कि-<i> \"व्यक्ति में परस्पर प्रेम राष्ट्रीय समाज की प्रभावोत्मक विशेषता भी और उनकी नागरिकता, संस्था, तर्क एवं उनकी स्वतंत्र अधिकारों और विशेषाधिकारों को सुरक्षित रखने के इच्छा से प्रेरित थी।\"</i>  फ्रांसीसी दार्शनिक ओका का मान्यता थी कि इतिहास का स्थिर ज्ञान की प्राप्ति और तर्क कि विजय के मध्य से मानव मात्र संपूर्णता की ओर बढ़ रहा हैं</p>\r\n<h2 class=\"atech\">मानवीय संयोग( मनोभाव )</h2>\r\n<p>इस सिद्धांत के अनुसार मानवीय व्यवहारों के कारण अथवा घटनाओं के पीछे का कारण केवल मानवीय सहयोग के कारण हुआ करते हैं।  <span>हिगल, काम्टे और सायमन विद्वानों के विचारों के अनुसार इतिहास के निर्माण में मानवीय मनोभाव का हाथ है।</span> वे लोग सांस्कृतिक के उत्तमअधिकार में विश्वास करते हैं। उनका विचार है कि प्राचीन सभ्यता-संस्कृतियों का जब विनाश होता है और उनके स्थान पर जब नई सभ्यता संस्कृति का जन्म लेती है तो वह नई संस्कृतियाँ मनोभाव का प्रतिनिधित्व करता हैं।</p>\r\n<h2 class=\"atech\">मार्क्सवादी सिद्धांत</h2>\r\n<p>यह सिद्धांत कार्ल मार्क्स के नाम से प्रसिद्ध है। क्योंकि इनमें मार्क्स के आर्थिक कारणों को इतिहास की आधारशिला माना गया है। <strong>मार्क्स ने इतिहास की भौतिकवादी व्याख्या करते हुए वर्ग-संघर्ष को स्वीकार किया।</strong> क्योंकि उससे उत्पादन का मूल्य कारण के रूप में स्वीकार किया गया है। उनके अनुसार दो राष्ट्रों के बीच संघर्ष तथा राष्ट्रों के संगठन का आधार आर्थिक होता है। आज जो विश्व के सारे देश दो गुटों में बंटे हैं उनका कारण भी हुआ आर्थिक ही मानते है। <span>मार्क्स का मानना है कि उत्पादन के साधनों के नियत्रंक पूँजीपति सत्ता को प्रभावित करते हैं और शोषक वर्ग के होते हैं। ये ही मज़दूरों का शोषण करते हैं जिससे कि वर्ग-संघर्ष होता है।</span> इस सिद्धांत का खंडन करते बर्ट्रेण्ड रसेल ने कहा की- इतिहास के प्रत्येक घटना को अर्थ से जोड़ता अथवा प्रत्येक घटना के पीछे आर्थिक कारणों को ढूंढने तात्मर्य इतिहास को अनैतिहासिक स्वरूप प्रदान करना होगा। परन्तु मार्क्सवादियों ने रसेल के इस कथन की परवाह किए बिना इस बात को बार-बार दुहराया है कि इतिहास की घटना के पीछे आर्थिक कारण होते हैं।</p>\r\n<h2 class=\"atech\">राष्ट्रीय सिद्धांत</h2>\r\n<p>19 वीं शताब्दी के प्रारंभ के साथ साथ इस कारण से संबंधित एक अन्य समस्या को स्वीकार किया वह राष्ट्रवाद की भावना थी। जिसने 19 वीं शताब्दी में ठोस आधार ग्रहण कर लिया। <span>राष्ट्रवाद की भावना के कारण अनेक लड़ाई एवं युद्ध हुए जो शक्तिशाली राष्ट्र अपने राष्ट्र के विस्तार के उद्देश्य से अपने से छोटे राष्ट्रो पर आक्रमण करते थे।</span> इनमें कोई संदेह नहीं है कि अतीतकाल में भी राष्ट्रो में राष्ट्रवाद की भावना विद्यमान नहीं रही होगी। ये हमेशा से अपने राष्ट्र की रही होगी। ये अपने राष्ट्र को विस्तार करने में अवश्य लगे रहते होंगे। इसके साथ-साथ राष्ट्रीय चरित्र एवं संरचनाओ  ने भी ऐतिहासिक घटनाओं के घटित होने में महत्वपूर्ण भूमिका अदा की। वस्तुत: ऐतिहासिक रूप से स्थापित सामाजिक, आर्थिक और राजनीतिक संस्थाओं के द्वारा राष्ट्रीय चरित्र का निर्माण व विनाश हुआ।</p>\r\n<h2 class=\"atech\">स्थितियों का सिद्धांत</h2>\r\n<p>प्रसिद्ध इतिहासकार ओकशॉट की मान्यता है कि परिस्थितियां की समुचित व्यवस्था में कार्य-करण के स्पष्ट प्रभाव को ढूंढा जा सकता है। अतः कार्य-करण के संबंधों का उचित वर्णन जब प्ररिस्तितियां के संदर्भ में किया जाता है। तब घटना के कारण स्वरूप परिस्थितियां महत्त्व प्राप्त करती है। <span>ओकशॉट के अनुसार यह सच है कि परिस्थितियां की व्याख्या में ही कारण के स्पष्ट प्रभाव को ढूंढा जा सकता है।</span> उदाहरणस्वरूप यदि हम यह कह सकते हैं कि वृहदथ को उसके ही सेनापति पुष्यमित्र शुंग ने क्यों मारा डाला। हम यह कह सकेंगे की उस समय की राजकीय और सैनिक परिस्थितियां ने बृहदथ को इतना निर्बल बना दिया था कि वे उसके कारण उसकी हत्या करना अधिक सरल हो गया था।</p>\r\n<h2 class=\"atech\">वैज्ञानिक सिद्धांत</h2>\r\n<p>19 वीं शताब्दी में एक ऐसे सम्प्रदाय का जन्म हुआ जिसने इतिहास के कारणों पर अपना ध्यान आग्रशीत किया। <span>रांके ने नेतृत्व में इतिहास के कारणों की व्याख्या अत्यंत वैज्ञानिक तरीकों से किया गया था।</span> रांके ने बताया कि इतिहास में बिना कारणत्व दर्शन के भी बताया जा सकता हैं। इस सिद्धांत के अनुसार इतिहास कि व्याख्या कारणत: दर्शन के बिना भी किया जा सकता है और इतिहास का सवोर्तम दर्शन कारणत: के सिद्धांत से नितान्तत आसम्बद्ध हैं</p>\r\n<p>इस तरह ऐतिहासिक कारणत्व के जीतने भी सिद्धांत हैं वे सभी पर्याप्त नहीं है किंतु जो भी हैं उनमें कुछ छोड़ने और कुछ अपनाने योग्य नहीं है अपितु उसके विषयों में योग जानकारी भी रखते हुए घटनाओं के कारणों को ढूंढने की आवश्यकता है। गोटचाक भी यह कहते हैं- <i>\"इतिहासकार को कारण यह कारणों शब्द का प्रयोग करना चाहिए उन्हें निश्चित शब्दों जैसे- उदेश्य, अवसर, पूर्ववर्ती साधन व मूलभाव का प्रयोग करना चाहिए और उन्हें प्रत्योक दशा में ऐतिहासिक घटनाओं के कारण पर प्रकाश डालना चाहिए।\"</i></p>\r\n<p>इस तरह स्पष्ट है कि कार्य-करण के अनेक कारणों के वर्णन के बाद भी अभी समस्या का हल संभव नहीं हुआ। इतिहासकार को अत्यंत सावधानीपूर्वक कारण के स्थान पर कारणों का प्रयोग करना चाहिए। और इस मान्य सिद्धांत को तोड़ते हुए कुछ विशिष्ट शब्दो- उद्देश्य, अवसर, घटना, साधन और तात्पर्य का जहाँ संभव हो प्रयोग करना चाहिए। हर प्रकार से इस समस्या के प्रति निरन्तर जागृति वांछनीय है और यथार्थत पर विशेष ध्यान दिया जाना चाहिए।</p>\r\n',149,'2025-01-31 12:13:02','2025-01-31 18:03:31','','Publish',0,'open',0,81),('इतिहास क्या है?','what-is-history',2,'<p>इतिहास क्या है यह प्रश्न जितना सरल है इसका उत्तर उतना ही जटिल है। विभिन्न कालों में विद्वानों ने इसकी विभिन्न उत्तर दिए हैं <strong>इति+ह+आस</strong> (ऐसा ही था)। समाज के संदर्भ में इतिहास की वही भूमिका है जो मनुष्य के संदर्भ से उसकी स्मृति का है इस तरह इतिहास समष्ट में अपनी अतीत की स्मृति है अतः अतीत को प्रस्तुत करने, जानने, समझने उससे प्रेरणा लेकर वर्तमान को सवार ने और भविष्य का मार्गदर्शन करने का साधन इतिहास है।</p>\r\n<p>समान्यत: अतीत की घटनाओं को क्रमबद्ध अध्ययन को इतिहास माना जाता है इस संदर्भ में दो प्रश्न विचारणीय है- <strong>क्या घटनाएं स्वय इतिहास है अथवा घटनाओं को लेखा-जोखा।</strong> जेम्स शॉटवेल ने स्पष्ट किया है कि वस्तुत घटनाएं इतिहास नहीं होती बल्कि इसकी लेखा-जोखा इतिहास होता है। वर्तमान समय में इतिहास का मायने बदल चुके हैं अब सिर्फ घटनाओं का क्रमबद्ध अध्ययन ही नहीं अपितु घटनाओं के घटित होने का कारण और परिस्थितियों का अध्ययन ही इतिहास की तहत किया जाता है।</p>\r\n<p><strong>इतिहास शब्द की उत्पत्ति इति+ह+आस इन तीन शब्दों से हुई है।</strong> जिसका अर्थ है- निश्चित रूप से ऐसा हुआ। इतिहास शब्द का प्राचीनतम उल्लेख अर्थवेद में मिलता है जहां प्रसंग वश कहा गया है कि ध्यान लक्ष्य की ओर आग्रसर राष्ट्र का अनुसरण इतिहास, पुराण, गाथा और नाराशंसी कहते हैं।</p>\r\n<p>प्राचीन भारत में ज्ञान की शाखों के रूप में इतिहास का अध्ययन होते हैं <strong>छांदोग्य के उपनिषद में इतिहास को पांचवा वेद काहा गया है।</strong> <strong>आचार्य दुर्गा</strong> ने अपनी निरुक्ति <strong>भाष्यवृस्ति</strong> में इतिहास की व्याख्या करते हुए लिखा है- <i>\"इतिहैवमासीदती यत् कध्यते तत् इतिहास\"</i> अर्थात यह निश्चित रूप से ऐसा ही हुआ। यह जो कहा जाता है वही इतिहास है।</p>\r\n<h2>इतिहास क्या है?</h2>\r\n<p><strong>History</strong> शब्द का इतिहास के लिए सर्वप्रथम प्रयोग <strong>यूनान के हीरोडोट्स</strong> के द्वारा किया गया था। History शब्द <strong>हिस्टोरिया (Historia)</strong> से बना है जिसका अर्थ ज्ञात करना होता है। ग्रीक भाषा में हिस्टोर (Histor) शब्द इतिहासकार के लिए प्रयोग किया गया है। हिस्टोर उस व्यक्ति को कहा जाता था जिसे विषयों का अच्छा ज्ञान हो और जो न्याय-निर्णय करने में सक्षम हो। अर्थात इतिहासकार से आस्य से उसे व्यक्ति से था जो झगड़ों का निपटारण करने में सक्षम होता था। शाब्दिक अर्थ की दृष्टि से इतिहास और हिस्ट्री दो बिन संस्कृतियों के शब्द हैं हिस्ट्री का असंगत अर्थ है-</p>\r\n<h2>इतिहास के परिभाषा।</h2>\r\n<p>इतिहास के अर्थ के तरह ही विद्वानों ने इसकी विभिन्न परिभाषाएं भी दी है इतिहास अपने आप में इतना वृहद विषय है कि इसकी सर्वमाण परिभाषा स्वीकृत नहीं की जा सकती। इतिहास के परिभाषा को लेकर विभिन्न विद्वानों मे मतय का अभाव को देखते हुए <strong>चार्ल्स फर्थ</strong> का यह कथन काफी उचित प्रतीक होता है कि <i>\"इतिहास को परिभाषित करना आसान नहीं है\"</i> विभिन्न विद्वानों ने इतिहास को विभिन्न प्रकारों से परिभाषित किया है।</p>\r\n<h3 class=\"atech\">इतिहास एक कहानी है</h3>\r\n<p>ऐनियर महोदय ने History शब्द में से Hi को अलग करके उसे एक कहानी के रूप में परिभाषित किया है। ऐनियर की तरह ही ट्रेविलियन, हेनरी पिरेन, ओलिवर आदि ने भी इतिहास को कहानी की तरह ही परिभाषित किया है। ट्रेविलियन ने इतिहास को अ परिवर्तन अंश में एक कहानी की संज्ञा दी है। <strong>हेनरी पिरेन</strong> के अनुसार- <i>\"इतिहास समाज में रहने वाले मनुष्य के कार्यों और उपलब्धियां की कहानी है।\"</i> परंतु इतिहास को कहानी मान लेने से इतिहास का मूल्य स्वरूप समाप्त हो सकता है। इतिहास वस्तुतः तथ्यों से निर्मित होता है और तथ्य ही अपने आप में निर्जीव होती है। यह इतिहासकार के कौशल पर निर्भर करता है कि वह तत्वों कला के आवरण में रोचक ढंग से प्रस्तुत करता है अथवा वास्तविक अतीत को वैज्ञानिक प्रवृत्ति से वर्तमान के सक्षम रखता है। कहानी में कल्पना के भी तत्व भी होते हैं जिनका इतिहास से कोई संपर्क नहीं होता। प्राचीन काल में राजाओं रानियों और दरबारीयों के राजनीतिक इतिहास पर जोर दिया जाता था क्योंकि कहानी नायक प्रधान होती है। अतः इसे इतिहास के साथ संबंध कर दिया जाता था परंतु आज व्यक्ति विशेष पर केंद्रित राजनीतिक इतिहास कलाअतीत हो चुके हैं तथा सामाजिक और सांस्कृतिक इतिहास पर जोर दिया जा रहा है। ऐसे में इतिहास को कहानी कतई स्वीकार नहीं किया जा सकता। यह सत्य है कि इतिहास की कुछ घटनाएं अत्यंत रोचक होती है और वह एक कहानी सामान प्रतीक होती है परंतु फिर भी हम इतिहास को कहानी कहकर उसके महत्व को कम नहीं कर सकते।</p>\r\n<h3 class=\"atech\">इतिहास ज्ञान है</h3>\r\n<p>इतिहास को कहानी के स्थान पर ज्ञान अथवा ज्ञान का स्रोत मानना अधिक व अर्थ पूर्ण प्रतीक होता है। इतिहास का प्रमुख उद्देश्य है अतीत के घटनाओं द्वारा भविष्य का मार्गदर्शन करना। <strong>चार्ल्स</strong> के अनुसार-  <i>\"इतिहास ज्ञान की मात्रा एक शाखा ही नहीं अपितु विशेष प्रकार का ज्ञान है जो मनुष्य के दैनिक जीवन में उपयोगी है।\"</i> इतिहास समाज की मूलभूत जिज्ञासाओ का समाधान बनाकर ज्ञान की हर विधा में समाया हुआ है। <strong>ऐतिहासिक ज्ञान के स्वरूप को परिभाषित करने का प्रयास डिल्थे, क्रोचे और कॉलिंगवूर्ड ने किया। क्रोचे ने इतिहास ज्ञान को मानव ज्ञान का स्रर्वथ रूप एवं प्रेरक शक्ति माना है।</strong> क्रोचे की तरह कॉलिंगवूर्ड ने ऐतिहासिक ज्ञान को मानव का संपूर्ण ज्ञान का स्रोत मानते हैं।</p>\r\n<p>यहां उल्लेखनीय तथ्य यह भी है कि मानव और समाज इतिहास से बहुत कम सीख लेता है। <strong>हीगल</strong> ने लिखा है- <i>\"इतिहास की सबसे बड़ी सीख यह है कि इतिहास से कोई सीख नहीं लेता।\"</i> प्रथम विश्व युद्ध के विनाशकारी परिणाम से यदि विश्व सीख लेता तो उसे <strong>द्वितीय विश्व युद्ध की विभिसका नहीं झेलनी पड़ती।</strong> ऐसे अनेको-अनेक उदाहरण विश्व इतिहास में भरे पड़े हैं जो प्रमाणित करते हैं कि मनुष्य ने इतिहास से कोई सीख नहीं लेकर पुरानी गलतियों को दोहराया है। परंतु इतिहास में अनेक ऐसे भी उदाहरण मिलते हैं जिससे साबित होता है कि <strong>इतिहास से सिख लेकर मानव ने भविष्य को सावरा है।</strong> उदाहरणत:  राष्ट्र संघ की असफलता के बाद उसकी कमियों को दूर करते हुए संयुक्त राष्ट्र संघ का निर्माण किया गया, अलाउद्दीन खिलजी ने सिकंदर-ए-सानी उपाधि धारण की थी परंतु सिकंदर की गलती से सीख लेकर उसने विश्व विजय का विचार त्याग दिया।</p>\r\n<p>उपरोक्त उदाहरण से स्पष्ट है कि <strong>जब-जब इतिहास का ज्ञान के स्रोत के रूप में उपयोग किया गया है तब तब न केवल व्यक्ति अपितु समस्त समाज एवं राष्ट्र लाभान्वित हुआ। और जब-जब उसकी अपेक्षा की गई तब तब मानव समाज को त्रासदियों से गुजरना पड़ा।</strong> अत: निश्चित रूप से इतिहास ज्ञान भी है और ज्ञान का प्रमुख स्रोत भी। अतः हमें हर कदम पर इससे मार्गदर्शन लेकर सुखद भविष्य का निर्माण करना चाहिए।</p>\r\n<h3 class=\"atech\">इतिहास सामाजिक विज्ञान है</h3>\r\n<p>19वीं शताब्दी के उत्तरार्ध में यूरोप में विभिन्न सामाजिक विज्ञान अस्तित्व में आए। <strong>मार्क्स ने सर्वप्रथम मानवीय अध्ययन में वैज्ञानिक पद्धति का प्रयोग कर इतिहास को सामाजिक विज्ञान से संबद्ध किया।</strong> डिल्थे प्रथम व्यक्ति थे जिसने इतिहास को सामाजिक विज्ञान बताने की चेष्टा की उसने कहा कि यदि इतिहास को भली भांति अध्ययन किया जाए तो इतिहास द्वारा ही मनुष्य को समझने का सूत्र प्राप्त किया जा सकता हैं।</p>\r\n<p><strong>चार्ल्स पर्थ</strong>  के अनुसार- <i>\"इतिहास मानव समाज का लेखा-जोखा है यह पूर्ण परिवर्तनों को बदलता है इससे समाज गुजर चुका है यह उन विचारों को बदलता है जिसका समाज के क्रियाकलापों और भौतिक दशाओं को प्रभावित किया है।\"</i> <strong>प्रोफेसर ए-एल-राउज</strong> के अनुसार- <i>\"इतिहास प्रधानत: समाज में मानव का उसके भौगोलिक व भौतिक पर्यावरणो का लेखा-जोखा है उसकी सामाजिक और सांस्कृतिक परिस्थितियों एक दूसरे की अंतर क्रिया से शुरू हुई है।\"</i> राउज का यह कथन इसलिए भी काफी उचित प्रतीक होता है क्योंकि भौगोलिक परिस्थितियों मनुष्य की क्षमता को काफी प्रभावित करती है। हुनो के घूमंत मंगोल के लड़ाकू और मराठों को छापामार युद्ध में सिद्धहस्त बनाने में भौगोलिक परिस्थितियों की निर्णायक भूमिका थी। अतः इतिहास व सामाजिक विज्ञान है जिसमें समय का प्रवाह पर्यावरण और भौगोलिक परिस्थितियों के अनुरूप मनुष्य की सामाजिक अंतर संबंधों का अध्ययन किया जाता है। चुकि इतिहास सामाजिक ज्ञानो का उद्गम स्थल है। अतः इतिहास में सामाजिक, राजनीतिक और आर्थिक विकास का उल्लेख भी होता है। इतिहासकार का प्रमुख कर्तव्य अतीत की घटनाओं को प्रकाश में लाना घटनाओं के परस्पर संबंधों को दिखलाना और उनकी व्याख्या करना है। अतः सामाजिक विज्ञान के तहत आने वाली विषयों में सर्वप्रमुख विषय इतिहास ही है।</p>\r\n<h3 class=\"atech\">संपूर्ण इतिहास विचारों का इतिहास है</h3>\r\n<p><strong>कॉलिंग वूर्ड</strong> के अनुसार- <i>\"संपूर्ण इतिहास विचारों का इतिहास होता है।\"</i> उनके अनुसार जब हम इतिहास का अध्ययन करते हैं तो हमें यह नहीं सोचना चाहिए कि मनुष्य ने क्या किया अपितु उसके विचारों के बारे में सोचना चाहिए। इतिहासकार प्रधान नहीं अपितु उसके विचार प्रधान है। इतिहास प्राचीन विचारों का पुन: प्रदर्शन करता है। मानव मस्तिष्क में विचार पहले उत्पन्न होता है और वह कार्य के रूप में लेता है जिसका प्रेरणा स्रोत विचार ही होता है। अतः मानव के कार्यो  का मूल्य स्रोत विचार ही होता है। अतः ऐतिहासिक स्रोत की महन स्थिति का अध्ययन कर लेने पर उनके कार्यों को भली-भांति समझा जा सकता है। उदाहरणत: बलबन ने इल्तुतमिश से नसीरुद्दीन मोहम्मद तक के सुल्तान के मध्यत: अनेक पद धारण किए थे और सुल्तान की पद के प्रतिष्ठा को क्रमशः गिरते हुए देखा था परिणाम स्वरुप सुल्तान बनने के उपरांत उसने दरबार में सिजदा और पैबोस को लागू किया तथा सुल्तान के पद की प्रतिष्ठा को पुन स्थापित करने का प्रत्यन भी किया।</p>\r\n<p>कई विद्वानों ने इतिहास को विचारधारा का इतिहास स्वीकार नहीं किया है। प्रोफेसर बाल्श के अनुसार- <i>\"इतिहास विचार प्रधान नहीं होता प्राय: दैविक प्रकोप बाढ़, भूकंप, अतिदृष्टि, अनावृष्टि आदि मानवीय विचार के विपरीत परिणाम देते हैं।\"</i>  प्रोफेसर बटरफील्ड ने भी बाल्श के विचारों का समर्थन किया है। उपर्युक्त दोनों विद्वानों का विचार मोहम्मद-बिन-तुगलक के संबंध में सही भी प्रतीक होता है। कागज पर मोहम्मद-बिन-तुगलक की सभी योजनाएं ठोस एवं विचारों की दृष्टि से उत्तम थी परंतु विचारों को प्रियंकित करने पर योजनाएं असफल सिद्ध हो गई। अर्थात <strong>विचारों का प्रियंकित करने तो मनुष्य के हाथों में है परंतु उसकी सफलता या असफलता परिस्थितियों पर निर्भर करती है।</strong> अर्थात संपूर्ण इतिहास को विचारों का इतिहास नहीं कहा जा सकता इतिहास में ऐतिहासिक चरित्रो के साथ-साथ इतिहासकार भी अपनी भूमिका निभाते हैं। अतः <strong>E.H Car</strong>  ने कहा है- <i>\"इतिहास अध्ययन करने से पहले इतिहासकार का अध्ययन करो और इतिहासकार का अध्ययन करने से पहले उसके ऐतिहासिक सामाजिक और उसकी संस्कृति प्रवेश का अध्ययन करो।\"</i>  देश काल और परिस्थितियों ऐतिहासिक चरित्र एवं इतिहासकार दोनों के ही विचारों को प्रभावित करते हैं अतः संपूर्ण इतिहास को केवल विचारों या विचारधारा का इतिहास मानना अत्यंत कठिन है।</p>\r\n<h3 class=\"atech\">संपूर्ण इतिहास समसामित इतिहास होता है</h3>\r\n<p>इटली के प्रसिद्ध इतिहासकार <strong>क्रोचे</strong> ने संपूर्ण इतिहास को समसामित इतिहास की संज्ञा दी है। उनके अनुसार लिखी जाने वाली घटनाएं वर्तमान से चाहे जितने दूर पर हो वास्तव में इतिहास वर्तमान अवश्कताओ एवं स्थितियों से ही संदर्भित होता है। उन्ही में पहले वह घटनाएं प्रतिद्वनित होती है अर्थात इतिहास लेखन मूलतः वर्तमान की आंखों से आधुनिक समस्याओं पृष्ठभूमि में अतीत को प्रस्तुत करता है और <strong>इतिहासकार का प्रमुख दायित्व घटनाओं का अभीलेखन करने की अपेक्षा उनका मूल्यांकन करना है।</strong> प्रत्योग वर्तमान अतीत को अपनी दृष्टि से देखा है और अतीत को उसे रूप में नहीं देखाता जिस रूप में हुआ था। अतीत का निर्माण इतिहासकार के मस्तिष्क में होता है वर्तमान जीवन से संबंध होने के कारण इतिहास सदैव समसामित होता है। <strong>क्रोचे</strong> यह भी बताते हैं कि निकट से देखने पर वह इतिहास भी जिसे हम समसामयित कहते हैं यदि वस्तुतः शुद्ध अर्थ में इतिहास है समसामित होता है। </p>\r\n<p>संपूर्ण इतिहास को समसामित इतिहास मानने के पीछे क्रोचे का उपयोगिता वादी दृष्टिकोण प्रखरता के साथ तेजी से प्रलक्षित होती है। यह दृष्टिकोण डेवी के इस कथन से भी स्पष्ट होता है कि- <i>\"अतीत के प्रति इष्ठा अतीत के लिए नहीं अपितु सुरक्षित और शुसंपन्न वर्तमान और भविष्य के लिए भी की जाती है।\"</i> ओकशाट, गॅालव्रेथ एवं मैडंलबाम आदि ने भी डेवी के उपरोक्त बातों का समर्थन किया है। इतिहास के उपरोक्त परिभाषा <strong>E.H Car</strong> पूर्णत: सहमत नहीं है कार कहते हैं कि इस परिकल्पना के अनुसार <strong>इतिहास के तथ्य कुछ नहीं है केवल व्याख्या ही सब कुछ है चुकि तथ्यों की व्याख्या से ही इतिहास का निर्माण होता है।</strong> अत: तथ्य अधिक महत्वपूर्ण है ऐसे में प्रत्येक इतिहासकार को इस बात का ध्यान रखना चाहिए कि वह इतिहास को उपयोगिता बनाने के चक्कर में तत्वों को तोड़-मोड कर प्रस्तुत न करें।</p>\r\n<h3 class=\"atech\">इतिहास अतीत व वर्तमान के बीच अनवरत संवाद है</h3>\r\n<p>एक इतिहासकार अतीत को तत्वों के आधार पर लिखता है तथ्य मृत प्राय: होते हैं इतिहासकार उन्हें जीवन प्रदान करता है। जिस प्रकार तथ्य को अर्थ पाने के लिए इतिहासकार के अवश्यता पड़ती है उसी प्रकार इतिहासकार भी तथ्यों के बिना जड़ और व्यर्थ हैं। तथ्य अतीत का प्रतिनिधित्व करते हैं और इतिहासकार वर्तमान का। यही कारण है कि इतिहासकार एवं पारस्परिक क्रिया में वर्तमान और अतीत की पारस्परिक भी निहित होती है। इस कालक्रम में <strong>E.H Car</strong> ने इतिहास को परिभाषित करते हुए उचित ही लिखा है कि- <i>\"इतिहास इतिहासकार और उनके तत्वों की क्रिया प्रतिक्रिया की एक अविच्छीन प्रक्रिया है तथा अतीत व वर्तमान के बीच अनवरत परिसंवाद है।\"</i></p>\r\n<p>वस्तुत: वर्तमान और अतीत के बीच एक मजबूत सूत्र होता है जो वर्तमान वह अतीत को जोड़ने का कार्य करता है। इसी सूत्रा को जब वर्तमान और अतीत को एक साथ देखने के साधन के रूप में प्रयुक्त किया जाता है तब इसे इतिहास दृष्टि कहा जाता है। अपनी इसी इतिहास दृष्टि का उपयोग कर इतिहासकार समसामिक समाज को अतीत के उन तथ्यों का अवलोकन करता है जो वर्तमान के लिए रुचिकर व उपयोगी हो। अतः <strong>इतिहास वर्तमान और अतीत के बीच अनवरत परिसंवाद के साथ-साथ उनके बीच एक सेतु भी है जिसके माध्यम से ही वर्तमान के परिपेक्ष में अतीत का अवलोकन कर सुखद भविष्य के लिए मार्गदर्शन प्राप्त कर सकते हैं।</strong> इतिहास की यही परिभाषा अपने आप में लगभग पूर्ण एवं एक उपयोगितावादी परिभाषा है। इतिहास की यह परिभाषा इतिहास के साथ-साथ तथ्य इतिहासकार एवं उसकी इतिहास दृष्टि को भी परिभाषित करती है।</p>\r\n',100,'2025-01-31 12:13:02','2025-01-31 18:06:18','','Publish',0,'open',0,82),('इतिहास लेखन में इसके महत्त्व पर प्रकाश डाले।','importance-in-history-writing',2,'<p>इतिहास मनुष्य के अनुभवों की कहानी है। अनुभव को सक्रिय और निष्क्रिय दो प्रकार के होते हैं। जीवन में एक मनुष्य के साथ जो कुछ जटिल होता है और परिस्थिति आने पर वह स्वयं उसका सामना करता है तो उसकी समझ और ज्ञान में वृद्धि होती है। इतिहास का संबंध समाज में रहने वाले व्यक्ति से ही नहीं है बल्कि उसे समाज से भी है जिसमें व्यक्ति अपना जीवन व्यतीत करता है। व्यक्ति का प्रत्येक कार्य समाज के अन्य लोगों से भी संबंध रखता है। </p>\r\n            <h2>इतिहास लेखन के महत्त्व</h2>\r\n            <h3>मानवीय अध्ययन</h3>\r\n            <p>इतिहास लेखन स्वयं के बारे में जानने की मनुष्य जाति के आंतरिक इच्छा की प्रतिक्रिया है। इस कारण यह मौलिक रूप से एक मानवीय अध्ययन है जो लोगों के महत्व, उनकी व्यक्तिगत पसंद, उनके मूल्य तथा स्वयं के साथ-साथ विश्व को देखने के उनके दृष्टिकोण पर जोर देता है।</p>\r\n            <h3>व्यक्ति और समाज का अध्ययन</h3>\r\n            <p>इतिहास लेखन का संबंध व्यक्ति और समाज दोनों से रहता है। अन्य समाज विज्ञानों की भांति इतिहासकारों की रुचि इस बात से रहती है कि स्त्री और पुरुष सामाजिक प्राणी के रूप में साथ-साथ क्यों तथा कैसे कार्य करते हैं? समाज विज्ञान के साथ अपने संपर्क सूत्रों के कारण इतिहास लेखन समान परिकल्पना और निष्कर्षों का प्रयोग करते हुए यह जानकारी प्राप्त करता है कि लोगों ने अपनी संस्थाओं का विकास किस प्रकार किया है? इन संस्थाओं का प्रयोग किस प्रकार किया गया तथा राजनीतिक सामाजिक एवं सांस्कृतिक संरचना में इन्होंने कैसे कार्य किया? इतिहासकार का उद्देश्य उपन्यासकार की भांति उस वास्तविकता की पुनः खोज करना, ग्रहण करना तथा हमारे समक्ष प्रस्तुत करना है जो समय के कारण हमसे दूर हो चुकी हैं।</p>\r\n            <h3>अतीत का अध्ययन</h3>\r\n            <p>इतिहास लेखन अन्य शास्त्रों का कार्य अनुभवों की रक्षा, संचरण एवं व्याख्या करना है लेकिन इतिहास लेखन का विशेष दायित्व अतीत का स्मरण कराना, पुनः मूल्यांकन करना एवं पूर्ण व्याख्या करना है। यह अतीत को वर्तमान की समझ के योग्य बनाता है तथा उसकी इस प्रकार व्याख्या करता है कि प्रत्येक पीढ़ी उसका प्रयोग कर सकें।</p>\r\n            <h3>इतिहास लेखन मार्गदर्शक होता है</h3>\r\n            <p>इतिहास लेखन की रूचि कारणों में निहित होती है अथवा सामाजिक प्रक्रिया के हमारे विचारों को आगे बढ़ाता है और स्पष्ट करता है। जो हमारे समूह को सामाजिक समस्याओं के बारे में अधिक अनुशासित दृष्टिकोण प्रस्तुत करता है। सन्तयाना के अनुसार — “जो लोग इतिहास को नहीं जानते वह निश्चित रूप से इसे दोहराते हैं।” जब हम यह जान लेते हैं कि अतीत काल में समाज का संचरण किस प्रकार हुआ था तो हम वर्तमान में अंतर्निहित संभावनाओं तथा विकल्पों को भी जान लेते हैं। इस प्रकार इतिहास लेखन हमारा मार्गदर्शन करता है।</p>\r\n            <h3>घटनाओं की व्याख्या</h3>\r\n            <p>इतिहासकार अभिलेखों के चयन और संगठन में पर्याप्त संक्षिप्तीकरण और सावधानी का प्रयोग करते हैं। वह इसी उद्देश्य को दृष्टिगत रखते हैं जिसके लिए जांच की जा रही है। वे तद अनुसार घटनाओं की व्याख्या करते हैं। अतीत निश्चय ही वर्तमान का रूप निर्धारित करता है। जैसे — इतिहासकार इस बात पर सहमत हैं कि वर्साय की संधि की सर तो ने ऐसा वातावरण बनाया था जिसके फलस्वरूप नाजी जर्मनी का विकास हो सका। इसके अतिरिक्त वर्तमान अतीत की अपनी व्याख्या के माध्यम से आती है इसका रूप निर्धारित करता है ताकि वर्तमान अतीत को समझ सके।</p>\r\n            <h3>भविष्य की योजना बनाना</h3>\r\n            <p>इतिहास लेखन से हम अपने भविष्य की योजना बना सकते हैं। पिछले गतिविधियों के परिणाम से हमें यहां तक की जानकारी मिलती है कि विभिन्न कारणों और नीतियों का कैसे परिणाम हुआ है, जिससे हम बेहतर निर्णय लेने के लिए साजग हो सकते हैं।</p>\r\n            <h2>निष्कर्ष</h2>\r\n            <p>इस प्रकार, इतिहास लेखन का महत्व उच्च होता है क्योंकि यह हमें अपने गुजरे हुए काल की समझ, सीख, और समृद्धि प्रदान करने में मदद करता है और हमें एक समृद्ध और समृद्धिशील भविष्य की दिशा में मार्गदर्शन करता है।</p>\r\n         ',228,'2025-01-31 12:13:02','2025-01-31 18:11:01','','Publish',0,'open',0,83),('वानभट्ट का इतिहास','history-of-vanbhatta',2,'<p>प्राचीन भारतीय इतिहास लेखन में की परंपरा में वानभट्ट का काफी सामान्य स्थान है। वह राजा हर्षवर्धन के \"आस्थान कवि\" थे। उनके दो प्रमुख ग्रंथ हैं। <strong>हर्षचरितम् तथा कादम्बरी</strong>। हर्षचरितम्, राजा हर्षवर्धन का जीवन-चरित्र है और कादम्बरी विश्व का पहला उपन्यास। परंतु इससे हर्ष के काल की कई महत्वपूर्ण जानकारियां प्राप्त होती हैं।</p>\r\n<p>बाणभट्ट एक सामान्य भार्गव ब्राह्मण व्यक्ति के पुत्र थे, जिनका जन्म आधुनिक युग के बिहार में हुआ था। बाणभट्ट ने संस्कृत गद्य और कविता लेखन के कई कार्यों के माध्यम से पहचान और प्रमुखता प्राप्त की। बाण भट्ट की कुछ रचनाओं को हर्षवर्द्धन जैसे प्रसिद्ध राजाओं से प्रशंसा मिली। इतिहास लेखन परंपरा उन्हें वंश परंपरा से उत्तराधिकार के रूप में प्राप्त हुई थी। वे पुष्यभूति वंश के राजा हर्षवर्धन के राजकीय लेखक थे।</p>\r\n<p>वानभट्ट ने हर्षचरितम् में सम्राट हर्ष के महत्वपूर्ण जीवन वृत्ति का वर्णन नहीं किया है। तथा ना हीं उन्होंने उसका क्रमबद्ध वर्णन ही किया है। इसके बावजूद इस ग्रंथ में वाणभट्ट ने तथ्यों और कल्पना का सुंदर समन्वय प्रस्तुत किया है। उसका मूल उद्देश्य अपने संरक्षक सम्राट हर्ष के व्यक्तित्व को उजागर करना था और इसमें वह सफल रहा। वाणभट्ट की विशेष रुचि हर्षकालीन घटनाओं के यथारूप एवं क्रमबद्ध लेखन में नहीं थी। वाणभट्ट वस्तुतः अपने नायक हर्षवर्धन द्वारा एक विशिष्ट लक्ष्य स्वतंत्र राजवंश की स्थापना की प्राप्ति को पहले से सुनिश्चित मानकर इस लक्ष्य की प्राप्ति तक की सभी घटनाओं का होना सुनिश्चित मानता है। वाणभट्ट के अनुसार हर्ष के पूर्वज पुष्पभूति को स्वयं लक्ष्मी से यह वरदान दिया गया था वह ऐसे राजकुल की स्थापना करेगा, जिसमें हर्ष एक प्रतापी और स्वतंत्र सम्राट बनेगा और वह स्वयं उसकी परिचारिका बनेगी।</p>\r\n<p>वाणभट्ट ने इसे स्पष्ट करते हुए बताया है कि राजश्री के रूप में भाग्य की देवी लक्ष्मी अपने वचनानुसार हर्ष की बहन बनी और उसी की मदद से हर्ष को विशिष्ट लक्ष्य की प्राप्त हुई। इस लक्ष्य की प्राप्ति तक जो घटनाएं घटी वे वाणभट्ट के अनुसार नियति द्वारा पूर्व में ही निर्धारित की जा चुकी थी।</p>\r\n<p>वाणभट्ट हर्षचरित्र में बताते हैं कि हर्ष की बहन राजश्री के पति गृहवर्मा को गौड़ शासक शशांक एवं मालवा नरेश देवगुप्त द्वारा हत्या कर दिया जाती है। इसके बाद राजश्री के बड़े भाई राज्यवर्धन द्वारा बहनोई की मौत का बदला लेने जाना परंतु शशांक द्वारा राज्यवर्धन की भी धोखे से हत्या कर दी जाती है। इस कारण हर्ष अनिच्छा से बनता है और बहनोई तथा भाई की हत्या का शत्रुओं से बदला लेने की शपथ लेता है। इसके लिए वह एक सेना के साथ प्रस्तान करता है, परंतु इसी बीच उसे पता चलता है की राजश्री कारावास से मुक्त होकर विंध्यांचल के जंगलों में चली गयी है। हर्ष सेना का संचालन सेनापतियों को सौंपकर जंगल की ओर प्रस्थान करता है। बौद्ध भिक्षु दिवाकर मित्र की सहायता से हर्ष ठीक उस समय राजश्री को ढूंढ निकालता है। जब वह सती होने जा रही थी।</p>\r\n<p>इस प्रकार हर्षवर्धन का अपनी बहन राष्ट्रीय अथवा लक्ष्मी से मिलन होता है और यही वाणभट्ट अपने हर्षचरित का विवरण समाप्त कर देते हैं। वान द्वारा निर्धारित अभीष्ट लक्ष्य को इस प्रकार हर्ष अपनी बहन के माध्यम से प्राप्त करता है। चीनी ग्रंथ फेंन्ची से पता चलता है कि वास्तव में हर्ष अपनी बहन राजश्री के साथ कन्नौज शासन करता था। हर्ष ने अपनी राजधानी कन्नौज हस्तान्तरित कर ली थी। ताकि वह प्रशासनिक कार्यों में राजश्री की मदद कर सके।</p>\r\n<p>वाणभट्ट ने युद्ध आदि के विवरण में कोई रुचि नहीं दिखाई तथा हर्ष द्वारा राजश्री के रूप में लक्ष्मी की प्राप्ति एवं उसके बाद उसके द्वारा अपने अभीष्ट लक्ष्य की प्राप्ति पर ही ध्यान केंद्रित किया। वाणभट्ट साथ ही यह स्पष्ट कर देता है इसका नायक उचित तरीके से उत्तराधिकारी बना जो की उसका मूल्य ध्येय था।</p>\r\n<p>वानभट्ट की हर्षचरितम् की सबसे प्रमुख विशेषता यह है कि यह साहित्यिक दृष्टि से जितनी श्रेष्ठ है ऐतिहासिक दृष्टि से उतनी प्रमाणिक भी है। वाणभट्ट वस्तु: इतिहास लेखन की उस परंपरा के प्रतीक हैं जो राजनीति के साथ-साथ तत्-युगीन सांस्कृतिक प्रवेश का भी प्रमाणिक विवरण प्रस्तुत करती है। साथ ही भौगोलिक वितरणों को भी उसने अपने लेखन में स्थान दिया हैं।</p>\r\n<p>वाणभट्ट हर्ष की विजय यात्रा के बारे में बताता है कि वह प्रतिदिन आठ को उसकी दूरी तय करता था। वह हर्ष की सैन्य अभ्यास की प्रतिबद्धता के बारे में लिखता है कि- \"<i>दिन प्रतिदिन अस्त्र-शास्त्रों के प्रयोग से उसके हाथ काले पड़ गए थे।मानो वे समस्त राजाओं के प्रताप की अग्नि को शांत करने के लिए मालिन पड़ गए थे।</i>\" राजनीतिक स्तिथि के बारे में हर्ष की सिंध विजय का उल्लेख करते हुए वाणभट्ट ने लिखा है कि- \"<i>सिंधुराज को युद्ध क्षेत्र में मरदिप्त करके उसकी राजलक्ष्मी को छीन लिया।</i>\" हर्षचरित में हर्ष को \'सकल-उत्तरापथनाथ\' कहा गया है जो यह स्पष्ट करता है कि उसने उत्तर भारत पर विजय प्राप्त कर लिया था।</p>\r\n<p>अन्वेषण, सतीप्रथा, राज्यविस्तार, ऐतिहासिक चरित्र आदि सभी तथ्यों का संकलन किया है, किंतु इन तथ्यों एवं घटनाओं को कोई क्रम नहीं दिया। इसका प्रमुख कारण यह है की उसने अपने नायक हर्ष द्वारा एक विशिष्ट लक्ष्य की उपलब्धि पर ही सारा ध्यान केंद्रित किया। जिसमें घटनाएं अनिवार्यत्: परिणत होती है। </p>\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार हम देखते हैं कि वाहन भट्ट को जहाँ कुछ इतिहासविध्, एक इतिहासकार की श्रेणी में रखते हैं वहीं अधिकांश विद्वान उसे काव्यकार रूप में ही प्रतिष्ठित रखने पर सहमति देते है। हमारे विचार से भी हर चरित्र कोई ऐतिहासिक ग्रंथ हो नहीं है, किंतु की प्रवृत्ति हर्ष का राजनीतिक इतिहास लिखने की ही दिखाई देती हैं। उनकी शैली क्योंकि महाकाव्यों की है इसलिए उसको इतिहासोन्मुख तो कहा ही जा सकता है। इसी विचार को ध्यान में रखकर हमने वाणभट्ट को प्राचीन भारतीय इतिहासकार गणना हेतु मान्य किया है। उनके इतिहास लेखन को तत्कालीन भारतीय परंपरागत ही देखना होगा। आधुनिक अथवा पाश्चात्य पद्धति से नहीं।</p>\r\n',79,'2025-01-31 12:13:02','2025-01-31 18:13:25','','Publish',0,'open',0,84),('समाजशास्त्र और इतिहास का संबंध','the-relationship-of-sociology-and-history',2,'<p>अन्य विषयों के अनुरूप ही इतिहास एवं समाजशास्त्र के बीच परस्पर घनिष्ठ संबंध है। दोनों को अध्ययन का विषय समाज में निवास करने वाला मानव जाति हैं, परंतु दोनों के बीच मानव के प्रति पहुँच में अंतर है। सामाजिक इतिहास के अंतर्गत हम मनुष्य और समाज की विभिन्न संस्थाओं और समस्याओं का अध्ययन करते हैं, जो मानव जाति का अत्यन्त महत्वपूर्ण हिस्सा है। सामाजिक व्यावहारिक पद्धति का वर्णन करने के लिए समाजशास्त्र को इतिहास की और इतिहास का समाजशास्त्र की आवश्यकता है। ताकि समाज की वास्तविक स्थिति को लोगों के सम्मुख लाया जा सके। इसी संदर्भ में प्रसिद्ध इतिहासकार टॉयनबी ने लिखा है कि \"<i>समाज कंण है जिसके आधार पर इतिहास लिखा जाता है। इतिहास के अंतर्गत हम केवल व्यक्ति अथवा राष्ट्रों का ही अध्ययन नहीं करते बल्कि समाज का जो इतिहास के अभिन्न अंग है का भी अध्ययन करते हैं।</i>\"</p>\r\n<p>समय के हिसाब से दोनों विषय अलग-अलग रहने के पश्चात वर्तमान दौर में एक दूसरे समीप आ रहे हैं। दोनों विषयो के नजदीकी का प्रमुख कारण \"<strong>इमाईल दुर्खीम</strong>\" (आत्महत्या के बारे में लिखा और लोगों तक पहुंचाया) जिसने ऐतिहासिक तथ्य के संदर्भ में प्रयोगात्मक, तुलनात्मक पद्धति को अपनाया। वर्तमान समय में पद्धति समाजशास्त्री मैक्सबेबर ने ऐतिहासिक अध्ययन पर अत्यधिक बल दिया। इसी तरह प्रोफेसर EH Car ने लिखा है कि- \"<i>समाजशास्त्र को यदि इतिहास के सामान्य अध्ययन का एक महत्वपूर्ण क्षेत्र बनाना है तब उसे निश्चित ही स्वयं अदुतीय और समान्य के मध्य संबंधित रहना चाहिए, परंतु साथ ही उसे सक्रिय बनाना चाहिए। सामाजिक परिवर्तन और उथान का भी अध्ययन प्रस्तुत करना चाहिए।\"</i></p>\r\n<p>दुर्खीम और बेबर जैसे समाजशास्त्री ने आंक्षिक रूप से समाजशास्त्र इतिहास पर निर्भर कर दिया है। इस समय से इतिहास को ज्यादा लाभ पहुंचा है, इतिहासकार के लिए समाजशास्त्र से अध्ययन पर बल देते हुए EH Car ने बताया है कि <span>चूँकि सामाजिक जीवन में कारणों परिणामों का उल्लेख किया गया है और ये एक मूलभूत सामाजिक विज्ञान है जो एकमात्र विषय है जो सामाजिक प्रक्रिया सामान्य दृष्टिकोण व कारणों को प्रस्तुत करने की आस्था करता है।</span></p>\r\n<p>सामाजिक विज्ञान विषय के अंतर्गत इतिहास और समाजशास्त्र एक दूसरे से घनिष्ठ रूप से जुड़े हुए हैं इसी घनिष्ठा के महत्त्व पर बल देते हुए विभिन्न इतिहासकारों ने समाजशास्त्र के अध्ययन पर ज़ोर दिया है। वहीं समाज शास्त्रियों ने भी ऐतिहासिक अध्ययन पर बल दिया है, चुकि इतिहास के अंतर्गत सामाजिक इतिहास का विश्लेषण अनिवार्य है। इतिहास कोई तुच्छ भाग नहीं है जिसके द्वारा एक समूह की आर्थिक, राजनीतिक, सैनिक एवं धार्मिक परिस्थितियों का वर्णन करने के लिए बाध्य है। अतः स्पष्ट हैं कि इतिहासकार की गहन दृष्टि एवं सही वर्णन की क्षमता भौतिक रूप से उसके समाजशास्त्र के प्रारंभिक सिद्धंतो के कारण बढ़ जाती है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार समाजशास्त्र समाज के अध्ययन में इतिहास की अत्यधिक सहायता कर रहा है। जो केवल सामाजिक अध्ययन तक सीमित नहीं है, अपितु निरंतर सामाजिक परिवर्तन एवं विकास को भी प्रस्तुत करता है। सामाजिक प्रक्रिया एवं समाजिक कारक इतिहास को नवीन दृष्टि देखकर परंपरागत इतिहास या वंशागत इतिहास से अलग दृष्टिकोण रखने का अवसर देता है। वर्तमान भारतवर्ष में इतिहासकार सामाजिक इतिहास लेखन की ओर अपनी ध्यान केंद्रित कर रहे हैं।</p>\r\n',367,'2025-01-31 12:13:02','2025-01-31 18:15:26','','Publish',0,'open',0,85),('आर्य समाज - एक सामाजिक और धार्मिक क्रांति','arya-samaj-social-and-religious-revolution',2,'<p>भारत के धार्मिक, सामाजिक और सांस्कृतिक इतिहास में उन्नीसवीं सदी का कालखंड अत्यंत महत्वपूर्ण रहा है। इसी युग में कई धार्मिक और सामाजिक सुधार आंदोलनों का जन्म हुआ, जिन्होंने भारतीय समाज को रूढ़ियों, अंधविश्वासों और पाखंडों से मुक्त करने का प्रयास किया। आर्य समाज भी ऐसा ही एक महान आंदोलन था, जिसकी स्थापना <strong>महर्षि स्वामी दयानंद सरस्वती</strong> ने की थी। आर्य समाज न केवल धार्मिक सुधार की दिशा में अग्रसर हुआ, बल्कि सामाजिक चेतना और राष्ट्रवाद को भी बल दिया। इसने भारतीय समाज में व्याप्त कुरीतियों के विरुद्ध संघर्ष छेड़ा और एक वैदिक आदर्श समाज की स्थापना का लक्ष्य रखा।</p>\r\n<p>आर्य समाज की स्थापना 10 अप्रैल 1875 को बॉम्बे (वर्तमान मुंबई) में <strong>स्वामी दयानंद सरस्वती</strong> द्वारा की गई थी। <strong>स्वामी दयानंद</strong> का मूल उद्देश्य <i>वैदिक धर्म की पुन: स्थापना करना और समाज को अंधविश्वासों, मूर्तिपूजा, जातिवाद, बाल-विवाह, <strong>सती प्रथा</strong> जैसी कुरीतियों से मुक्त कराना था।</i> उन्होंने अपने आंदोलन के माध्यम से ‘<strong>वेदों की ओर लौटो</strong>’ (Back to the Vedas) का नारा दिया।</p>\r\n<p>स्वामी दयानंद का मानना था कि वेद ही सत्य ज्ञान का मूल स्रोत हैं और उनमें ही धर्म, विज्ञान, राजनीति, समाज, नैतिकता आदि के लिए आवश्यक सभी सिद्धांत निहित हैं। उन्होंने आर्य समाज को एक ऐसा मंच बनाया, जिसके माध्यम से भारतीय समाज में सुधार की दिशा में क्रांतिकारी परिवर्तन लाया जा सके।</p>\r\n<h2>स्वामी दयानंद सरस्वती का जीवन</h2>\r\n<p>स्वामी दयानंद सरस्वती का जन्म <strong>12 फरवरी 1824</strong> को काठियावाड़ (गुजरात) के मोरबी नामक स्थान पर हुआ था। उनका मूल नाम मूलशंकर था। वे एक ब्राह्मण परिवार में जन्मे थे और बचपन से ही धार्मिक प्रवृत्ति के थे। एक बार उन्होंने महाशिवरात्रि के दिन मंदिर में देखा कि एक चूहा शिवलिंग पर चढ़ा है, तब उनके मन में यह विचार आया कि अगर यह ईश्वर है तो फिर यह चूहा इसका अपमान कैसे कर सकता है?</p>\r\n<p>इस घटना ने उनके मन में अनेक प्रश्न खड़े किए और वे सत्य की खोज में निकल पड़े। वर्षों तक उन्होंने विभिन्न गुरुओं से अध्ययन किया और अंततः उन्हें वेदों में वह ज्ञान मिला जिसकी वे तलाश कर रहे थे। इसके बाद उन्होंने संन्यास ग्रहण किया और \"स्वामी दयानंद सरस्वती\" के नाम से प्रसिद्ध हुए।</p>\r\n\r\n<h2>धार्मिक क्षेत्र में आर्य समाज की भूमिका</h2>\r\n<p>धार्मिक क्षेत्र में आर्य समाज की भूमिका को निम्नलिखित बिंदुओं में समझा जा सकता है</p>\r\n<h3 class=\"atech\">वेदों की ओर लौटने का आह्वान</h3>\r\n<p>आर्य समाज ने ‘वेदों की ओर लौटो’ (Back to the Vedas) का नारा दिया। स्वामी दयानंद का मानना था कि भारतीय संस्कृति और धर्म की शुद्धता केवल वेदों में है। उन्होंने कहा कि वेद अपौरुषेय हैं, अर्थात् ईश्वर द्वारा रचित हैं और उनमें ही मानवता का कल्याण निहित है। अतः आर्य समाज ने वेदों को जीवन के प्रत्येक क्षेत्र में मार्गदर्शक मानते हुए उनके प्रचार-प्रसार को अपने आंदोलन का मूल लक्ष्य बनाया।</p>\r\n<h3 class=\"atech\">मूर्ति-पूजा और पाखंड का विरोध</h3>\r\n<p>स्वामी दयानंद ने स्पष्ट कहा – \"<i>ईश्वर निराकार है, अतः उसकी पूजा किसी मूर्ति या प्रतीक से नहीं की जा सकती।</i>\" उन्होंने मंदिरों में होने वाली अंधश्रद्धा, मूर्ति पूजा, तीर्थ यात्रा के नाम पर ढोंग, चमत्कारों की कहानियों आदि को धार्मिक विकृति बताया। आर्य समाज ने धर्म को तर्क और वैज्ञानिक दृष्टिकोण से समझने पर बल दिया।</p>\r\n<h3 class=\"atech\">धार्मिक ग्रंथों की युक्तिसंगत व्याख्या</h3>\r\n<p>दयानंद ने धार्मिक ग्रंथों की समीक्षात्मक आलोचना की। उन्होंने सत्यार्थ प्रकाश ग्रंथ में पुराणों में वर्णित अनैतिक और अवैज्ञानिक बातों की निंदा की तथा वेदों को ही धर्म का सच्चा मार्गदर्शक बताया। इससे परंपरागत पुरोहित वर्ग की आलोचना हुई, लेकिन बुद्धिजीवियों और शिक्षित युवाओं ने आर्य समाज की विचारधारा को अपनाया।</p>\r\n\r\n<h2>सामाजिक क्षेत्र में आर्य समाज की भूमिका</h2>\r\n<h3 class=\"atech\">जातिप्रथा और छुआछूत का विरोध</h3>\r\n<p>आर्य समाज ने जाति के आधार पर भेदभाव का विरोध किया। दयानंद सरस्वती के अनुसार, जाति जन्म से नहीं बल्कि कर्म, गुण और स्वभाव से निर्धारित होती है। उन्होंने जातिगत ऊँच-नीच को समाज का सबसे बड़ा दोष बताया और सभी मनुष्यों को समान बताया। आर्य समाज ने ‘समवेत समाज’ की स्थापना पर बल दिया, जिसमें सभी जातियाँ समान अधिकारों से युक्त हों।</p>\r\n<h3 class=\"atech\">शुद्धि आंदोलन</h3>\r\n<p>19वीं सदी के उत्तरार्द्ध और 20वीं सदी के आरंभ में अनेक हिन्दू धर्मावलंबी ईसाई या इस्लाम धर्म अपना रहे थे। आर्य समाज ने शुद्धि आंदोलन चलाया, जिसका उद्देश्य था – इन लोगों को पुनः हिंदू धर्म में वापस लाना। यह आंदोलन विशेष रूप से उत्तर प्रदेश, राजस्थान, पंजाब और हरियाणा में सक्रिय रहा। शुद्धि आंदोलन के माध्यम से आर्य समाज ने ‘धार्मिक आत्मरक्षा’ का मार्ग अपनाया और हिंदू समाज को संगठित किया।</p>\r\n<h3 class=\"atech\">नारी सशक्तिकरण और स्त्री शिक्षा</h3>\r\n<p>आर्य समाज ने महिलाओं की दशा सुधारने हेतु अनेक प्रयास किए- स्त्री शिक्षा को बढ़ावा दिया। कई कन्या पाठशालाएँ खोली गईं। <strong>बाल विवाह</strong> का विरोध किया और <strong>विधवा विवाह</strong> को प्रोत्साहित किया। पर्दा प्रथा, बहुपति प्रथा और स्त्री दमन के अन्य रूपों के विरुद्ध जागरूकता अभियान चलाए गए।</p>\r\n<h3 class=\"atech\"> शराब और व्यसन के विरोध में आंदोलन</h3>\r\n<p>आर्य समाज ने नशा, विशेषकर शराब के सेवन को सामाजिक और नैतिक पतन का कारण बताया और इसके खिलाफ जनजागरण चलाया। उन्होंने सामाजिक आयोजनों और प्रचार के माध्यम से नशा-मुक्ति की संस्कृति को बढ़ावा दिया।</p>\r\n\r\n<h2>शिक्षा के क्षेत्र में आर्य समाज का योगदान</h2>\r\n<h3 class=\"atech\">गुरुकुल प्रणाली की पुनर्स्थापना</h3>\r\n<p>आर्य समाज ने वेद आधारित शिक्षा के प्रसार के लिए <strong>गुरुकुल कांगड़ी विश्वविद्यालय</strong> (हरिद्वार) की स्थापना की, जहाँ आधुनिक विषयों के साथ वैदिक साहित्य, संस्कृत, योग आदि की शिक्षा दी जाती थी। इसके अलावा अनेक अन्य शिक्षण संस्थानों की स्थापना की गई, जहाँ जाति, धर्म या लिंग के आधार पर भेदभाव नहीं किया जाता था।</p>\r\n<h3 class=\"atech\">छात्रावास, आश्रम और पुस्तकालय</h3>\r\n<p>शिक्षा के प्रचार-प्रसार हेतु आर्य समाज ने कई आश्रम, छात्रावास और पुस्तकालयों की स्थापना की। इन संस्थाओं ने समाज के गरीब और पिछड़े वर्गों को शिक्षा के माध्यम से सशक्त किया।</p>\r\n<h3 class=\"atech\">तर्क और विज्ञान आधारित शिक्षा</h3>\r\n<p>आर्य समाज ने धार्मिक अंधविश्वासों के विरुद्ध तर्क और वैज्ञानिक सोच को बढ़ावा दिया। स्कूलों में छात्रों को धर्म के नाम पर डराने की जगह तर्क करने, प्रश्न पूछने और मानवता को प्राथमिकता देने की शिक्षा दी गई।</p>\r\n\r\n<h2>आर्य समाज के सिद्धांत</h2>\r\n<p>आर्य समाज ने 10 प्रमुख सिद्धांतों की स्थापना की, जिन्हें “दस नियाम” कहा जाता है। ये निम्नलिखित हैं</p>\r\n<ul>\r\n    <li><p>सत्य का ग्रहण करो और असत्य को त्यागो।</p></li>\r\n    <li><p>ईश्वर एक है, सर्वशक्तिमान है, निराकार है।</p></li>\r\n    <li><p>वेद सब सत्य ज्ञान के पुस्तक हैं।</p></li>\r\n    <li><p>सत्यार्थप्रकाश जैसे ग्रंथों का अध्ययन करो।</p></li>\r\n    <li><p>सत्य के प्रचार हेतु यज्ञ और सत्कर्म करो।</p></li>\r\n    <li><p>दूसरों के कल्याण के लिए काम करो।</p></li>\r\n    <li><p>अज्ञान और अन्याय का विरोध करो।</p></li>\r\n    <li><p>विद्या प्राप्त करो और दूसरों को सिखाओ।</p></li>\r\n    <li><p>सभी के साथ प्रेम और न्याय का व्यवहार करो।</p></li>\r\n    <li><p>धर्म के प्रचार हेतु संगठित रहो।</p></li>\r\n</ul>\r\n<h2>आर्य समाज के प्रमुख उद्देश्य</h2>\r\n<p></p>\r\n<ul>\r\n    <li><p>वैदिक धर्म की पुन: स्थापना।</p></li>\r\n    <li><p>समाज में व्याप्त रूढ़ियों, अंधविश्वासों और पाखंडों का खंडन।</p></li>\r\n    <li><p>शिक्षा का प्रचार, विशेषकर स्त्रियों और शूद्रों के लिए।</p></li>\r\n    <li><p>जातिप्रथा, सतीप्रथा, बालविवाह, पर्दा प्रथा आदि का विरोध।</p></li>\r\n    <li><p>विधवा पुनर्विवाह को बढ़ावा देना।</p></li>\r\n    <li><p>स्वदेशी और स्वराज की भावना का विकास।</p></li>\r\n    <li><p>शुद्धि आंदोलन के माध्यम से हिंदू धर्म में पुनः वापसी।</p></li>\r\n    <li><p>राष्ट्रवाद और स्वतंत्रता संग्राम को नैतिक आधार प्रदान करना।</p></li>\r\n</ul>\r\n<h2>आर्य समाज की विशेषताएं</h2>\r\n<p>आर्य समाज वेदों को सर्वोच्च मानता है और एक निराकार, सर्वशक्तिमान ईश्वर में विश्वास करता है। यह मूर्तिपूजा, अंधविश्वास, पाखंड और जातिवाद का विरोध करता है। समाज में फैली कुरीतियाँ जैसे <strong>सती प्रथा</strong>, <strong>बाल विवाह</strong>, <strong>छुआछूत</strong> और बहुविवाह के विरुद्ध आर्य समाज ने आवाज उठाई। महिलाओं की शिक्षा, <strong>विधवा विवाह</strong> और समान अधिकारों को समर्थन देकर यह समाज में समानता की भावना फैलाने का कार्य करता है।</p>\r\n<p>आर्य समाज ने शिक्षा के क्षेत्र में विशेष योगदान दिया, जैसे DAV स्कूल और गुरुकुलों की स्थापना। शुद्धि आंदोलन के माध्यम से जो लोग धर्म छोड़ चुके थे, उन्हें पुनः वैदिक धर्म में लाने का प्रयास किया गया। यह संगठन सत्य, परोपकार, ईमानदारी और समाज सेवा को धर्म का हिस्सा मानता है और राष्ट्र सेवा को भी प्राथमिकता देता है।</p>\r\n<h2>आर्य समाज की उपलब्धियां</h2>\r\n<p>आर्य समाज की सबसे बड़ी उपलब्धि यह रही कि इसने भारतीय समाज को अंधविश्वास, मूर्तिपूजा और जातिवाद जैसी कुरीतियों के विरुद्ध जागरूक किया। इसने <strong>सती प्रथा</strong>, <strong>बाल विवाह</strong>, <strong>छुआछूत</strong> और नारी अत्याचार का विरोध कर सामाजिक सुधार को गति दी। महिलाओं की शिक्षा, <strong>विधवा विवाह</strong> और समान अधिकारों को बढ़ावा देना इसकी बड़ी उपलब्धियों में से एक है।</p>\r\n<p>शिक्षा के क्षेत्र में आर्य समाज ने DAV स्कूल और कॉलेजों की स्थापना की, जिससे लाखों लोगों को आधुनिक और वैदिक शिक्षा मिली। शुद्धि आंदोलन के माध्यम से कई लोगों को पुनः हिंदू धर्म में लाया गया। इसके साथ ही आर्य समाज ने स्वराज और स्वदेशी आंदोलनों को नैतिक समर्थन देकर राष्ट्रवाद की भावना को भी प्रबल किया।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>आर्य समाज ने आधुनिक भारत में सामाजिक और धार्मिक सुधारों की दिशा में एक क्रांतिकारी भूमिका निभाई। आर्य समाज एक सामाजिक, धार्मिक और सांस्कृतिक क्रांति थी जिसने भारतीय समाज को नए विचार, नई चेतना और नई दिशा दी। स्वामी दयानंद सरस्वती का जीवन और उनके विचार आज भी प्रेरणादायक हैं। आर्य समाज ने केवल धर्म और समाज की शुद्धि ही नहीं की, बल्कि स्वतंत्रता संग्राम को भी नैतिक बल प्रदान किया। वर्तमान समय में जब समाज पुनः अनेक प्रकार की रूढ़ियों और पाखंडों में उलझ रहा है, तब आर्य समाज के सिद्धांतों और दयानंद सरस्वती के विचारों को अपनाने की आवश्यकता पहले से कहीं अधिक है।</p>',17,'2025-05-29 17:34:06','2025-05-29 17:41:04','','Publish',0,'open',27,94),('दीन-ए-इलाही','deen-e-ilahi',2,'<p>अकबर द्वारा <strong>सुलह-ए-कुल</strong> के सिद्धांत पर <strong>दीन-ए-इलाही</strong> की नींव रखी गई। वह बड़ा धार्मिक एवं जिज्ञासु प्रवृत्ति का शासक था। उसे धर्म के विषय में विशेष <strong>रुचि</strong> थी। धार्मिक जिज्ञासा को शांत करने के लिए अकबर ने फतेहपुर सीकरी में 1575 में <strong>इबादतखाने</strong> का निर्माण करवाया। इसमें मुस्लिम धर्मवालों को आमंत्रित करवाया गया, जो इस्लाम धर्म पर वाद-विवाद करते थे। अकबर यह वाद-विवाद ध्यान से सुनता था और उसने पाया कि इस्लाम के सिद्धांतों पर सभी विद्वान एकमत नहीं हैं। विवादों के अवसर पर विद्वानों के विचार से <strong>संकरण मनोवर्धी</strong> और असहिष्णुता का परिचय मिला। अकबर को इससे बड़ा दुख हुआ और इस्लाम की श्रेष्ठता से उसका विश्वास उठ गया।</p>\r\n    <p>इस कारण हिंदू, जैन, फारसी, ईसाई आदि सभी धर्मों के विद्वानों को <strong>इबादतखाने</strong> में आने की अनुमति थी। सभी धर्मों में सत्य है, इस विश्वास को लेकर अकबर ने धार्मिक <strong>सहिष्णुता</strong> की नीति पालन करते हुए निम्नलिखित कार्य किए—</p>\r\n    <ul>\r\n    <li><p>सभी धर्मों के लोगों को अपने धर्म को मानने एवं पालन करने की स्वतंत्रता दी गई।</p></li>\r\n    <li><p>जो लोग बलपूर्वक मुसलमान बनाए गए थे, उन्हें पुनः अपने धर्म को स्वीकार करने की अनुमति प्रदान की गई।</p></li>\r\n    <li><p>इस तरह धार्मिक भेदभाव <strong>पूर्णतः</strong> समाप्त हो गया एवं सभी धर्मों को समान अधिकार दिया गया।</p></li>\r\n    <li><p>हिंदुओं में <strong>सती प्रथा</strong> बंद कर दी गई।</p></li>\r\n    <li><p><strong>विधवा पुनर्विवाह</strong> को मान्यता दी गई।</p></li>\r\n    <li><p><strong>दास प्रथा समाप्त</strong> की गई।</p></li>\r\n    <li><p>हिंदुओं से <strong>तीर्थयात्रा कर एवं जजिया कर</strong> हटा दिया गया।</p></li>\r\n    <li><p>16 वर्ष से कम उम्र के लड़के तथा 14 वर्ष से कम उम्र की लड़की के विवाह पर रोक लगा दी गई।</p></li>\r\n    <li><p>वेश्याओं को अलग नगरों में बसाया गया।</p></li>\r\n    </ul>\r\n    <p>उपरोक्त सभी कार्य धार्मिक हस्तक्षेप हेतु नहीं बल्कि <strong>कुप्रथाओं</strong> को समाप्त करने के लिए किए गए थे। <strong>1582</strong> में अकबर ने <strong>दीन-ए-इलाही</strong> की स्थापना की। अबुल फजल को इसका प्रधान स्वरूप बनाया गया। जो भी व्यक्ति इस संप्रदाय का सदस्य बनना चाहता था, वह किसी भी रविवार के दिन बादशाह अकबर के पास जाता और उसके <strong>कदमों</strong> में पगड़ी रख देता। इसके बाद बादशाह उसे <strong>सील</strong> प्रदान करता।</p>\r\n    <p>सील- का आशय किसी प्रतीकात्मक स्वीकृति या मान्यता से है,\"स्वीकृति प्रदान करता\" या \"संप्रदाय में शामिल करता\"</p>\r\n    <h3><strong>दीन-ए-इलाही के कुछ नियम</strong></h3>\r\n    <ul>\r\n    <li><p>यह संप्रदाय के सदस्य अभिवादन के लिए <strong>\"अल्लाह-हू-अकबर\"</strong> और उत्तर में <strong>\"जलाल-हू\"</strong> शब्द का प्रयोग करते थे।</p></li>\r\n    <li><p>मृत्यु के समय दान देने के स्थान पर <strong>जीवनकाल में ही दान</strong> देने पर बल दिया जाता था।</p></li>\r\n    <li><p><strong>वृद्धों को दान देना</strong> अनिवार्य था।</p></li>\r\n    <li><p><strong>मांस का सेवन वर्जित</strong> था।</p></li>\r\n    <li><p><strong>कम उम्र की लड़कियों एवं वृद्ध महिलाओं से विवाह पर रोक थी।</strong></p></li>\r\n    </ul>\r\n    <h3><strong>दीन-ए-इलाही की सीमाएँ और प्रभाव</strong></h3>\r\n    <p>दीन-ए-इलाही के सदस्यों की संख्या सीमित रही। वास्तव में, <strong>दीन-ए-इलाही</strong> एक धार्मिक संप्रदाय नहीं था, क्योंकि इसमें <strong>कोई पैगंबर, पूजा-पद्धति या धार्मिक ग्रंथ</strong> नहीं था, जो किसी भी धर्म के लिए आवश्यक होते हैं। इसके सदस्यों की संख्या बढ़ाने के लिए अकबर ने कभी दबाव नहीं डाला तथा सदैव <strong>उदारता की नीति</strong> अपनाई।</p>\r\n    <p>यदि <strong>दीन-ए-इलाही असफल</strong> हुआ, तो इसमें अकबर का <strong>दोष</strong> नहीं था, बल्कि उस दौर की <strong>रूढ़िवादी सोच</strong> इसका कारण थी। यह नीति काफी हद तक सफल रही। कुछ कट्टर मुसलमानों को छोड़कर अधिकांश भारतीयों ने इसे सहर्ष स्वीकार किया।</p>\r\n    <p>हमें यह भी याद रखना चाहिए कि <strong>उस दौर में</strong>, जब यूरोप परस्पर विरोधी संप्रदायों के संघर्षों से त्रस्त था, अकबर ने न केवल उन्हें एकजुट रखा बल्कि <strong>उन्हें शांति भी प्रदान की</strong>।</p>    \r\n    <h2>निष्कर्ष</h2>\r\n    <p>इस प्रकार हम पाते है कि अकबर द्वारा स्थापित दीन-ए-इलाही कोई पूर्ण धार्मिक संप्रदाय नहीं था, बल्कि यह विभिन्न धर्मों के अच्छे सिद्धांतों को अपनाने और धार्मिक सहिष्णुता को बढ़ावा देने का प्रयास था। इसका मूल उद्देश्य सामाजिक कुरीतियों को समाप्त करना और एक समरस समाज की स्थापना करना था। हालाँकि, यह संप्रदाय व्यापक रूप से लोकप्रिय नहीं हो सका, क्योंकि उस समय के समाज में पारंपरिक धार्मिक मान्यताएँ बहुत गहरी जड़ें जमा चुकी थीं। फिर भी, अकबर की इस पहल ने धार्मिक सहिष्णुता और सामाजिक सुधारों को एक नई दिशा दी। दीन-ए-इलाही भले ही अल्पकालिक रहा हो, लेकिन इसका प्रभाव अकबर की नीतियों और उनके शासन की उदारता में स्पष्ट रूप से दिखाई देता है। इसने मध्यकालीन भारतीय समाज में धर्मनिरपेक्षता और सह-अस्तित्व की भावना को बढ़ावा देने में महत्वपूर्ण भूमिका निभाई।</p>\r\n',6,'2025-05-29 17:34:06','2025-05-29 17:53:50','','Publish',0,'open',5,95),('बौद्ध धर्म','buddhism',2,'<p>छठी शताब्दी ईसा पूर्व में जब वैदिक धर्म में कर्मकांडों और आडंबरों की अधिकता हो गई थी, तब जनता को इनसे मुक्ति दिलाने के उद्देश्य से कई धार्मिक संप्रदायों का उदय हुआ। इन्हीं में से एक प्रमुख संप्रदाय था — <strong>बौद्ध धर्म</strong>, जिसकी स्थापना <strong>महात्मा बुद्ध</strong> ने की।</p>\r\n<h2>महात्मा बुद्ध</h2>\r\n<p>महात्मा बुद्ध का वास्तविक नाम <strong>सिद्धार्थ</strong> था। उनका जन्म 563 ईसा पूर्व में लुंबिनी वन (वर्तमान नेपाल) में हुआ था। उनके पिता का नाम <strong>शुद्धोधन</strong> था, जो कपिलवस्तु (शाक्य गणराज्य की राजधानी) के प्रधान थे। उनकी माता का नाम <strong>महामाया</strong> (माया देवी) था। जब सिद्धार्थ गौतम का जन्म हुआ, तो कई भविष्यवक्ताओं ने भविष्यवाणी की कि वह एक महान व्यक्ति बनेंगे। उनके पिता ने उन्हें एक शानदार महल में रखा और उन्हें दुनिया की दुखों से दूर रखा। हालांकि, सिद्धार्थ ने एक दिन महल से बाहर निकलकर संसार की वास्तविकता देखी, जिसमें बुढ़ापे, बीमारी और मृत्यु की समस्याएँ थीं।</p>\r\n<p> 16 वर्ष की आयु में सिद्धार्थ का विवाह यशोधरा से हुआ, जिनसे उन्हें एक पुत्र राहुल हुआ। लेकिन सांसारिक जीवन से उन्हें कभी संतोष नहीं मिला। संसार में व्याप्त दुखों को देखकर उन्होंने <strong>29 वर्ष</strong> की आयु में घर छोड़ दिया। इस घटना को <strong>महाभिनिष्क्रमण</strong> कहा जाता है।</p>\r\n<h2>ज्ञान की प्राप्ति और धर्म का प्रचार</h2>\r\n<p>ज्ञान की खोज में उन्होंने अनेक आचार्यों से शिक्षा प्राप्त की, पर उन्हें संतोष नहीं हुआ। बाद में उन्होंने उरुवेला (बोधगया) में कठोर तप किया, लेकिन जब इससे भी समाधान नहीं मिला, तो उन्होंने तप का मार्ग छोड़कर ध्यान और समाधि के मार्ग को अपनाया।</p>\r\n<p>35 वर्ष की आयु में <i>बोधगया में पीपल वृक्ष के नीचे उन्हें ज्ञान की प्राप्ति हुई।</i> इस घटना को <strong>संबोधि</strong> कहते हैं, और वे सिद्धार्थ से गौतम बुद्ध बन गए। ज्ञान प्राप्ति के बाद बुद्ध ने पहला उपदेश सारनाथ में अपने पाँच साथियों को दिया, जिसे धर्मचक्र प्रवर्तन कहा जाता है।</p>\r\n<p>इसके बाद उन्होंने 45 वर्षों तक लगातार धर्म प्रचार किया। वे मगध, कोशल, वैशाली, लिच्छवी, काशी आदि राज्यों में घूम-घूमकर उपदेश देते रहे। उनका देहावसान 483 ईसा पूर्व में कुशीनगर (वर्तमान उत्तर प्रदेश के देवरिया ज़िले में) हुआ। इस घटना को महापरिनिर्वाण कहा जाता है।</p>\r\n<h2>महात्मा बुद्ध के उपदेश और दर्शन</h2>\r\n<p>महात्मा बुद्ध ने चार आर्य सत्य और अष्टांगिक मार्ग पर बल दिया।</p>\r\n<h3>चार आर्य सत्य</h3>\r\n<ul>\r\n    <li><p><strong>दुख (Dukkha)</strong>: जीवन में दुख और असंतोष मौजूद हैं, चाहे वह जन्म हो, वृद्धावस्था हो, बीमारी हो या मृत्यु। हर व्यक्ति को जीवन के विभिन्न रूपों में दुख का सामना करना पड़ता है।</p></li>\r\n    <li><p><strong>दुख का कारण (Samudaya)</strong> दुख का कारण मनुष्य की तृष्णा और लालसा है। यह इच्छाएँ हमें बंधन में डालती हैं।</p></li>\r\n    <li><p><strong>दुख का निवारण (Nirodha)</strong> अगर तृष्णा और लालसा को समाप्त किया जाए, तो दुख से मुक्ति मिल सकती है।</p></li>\r\n    <li><p><strong>दुख का अंत करने का मार्ग (Magga)</strong> दुख से मुक्ति पाने का मार्ग अष्टांगिक मार्ग है।</p></li>\r\n</ul>\r\n<h3>अष्टांगिक मार्ग</h3>\r\n<ul>\r\n    <li><p><strong>सम्यक दृष्टि (Right View)</strong> जीवन और संसार की सही समझ।</p></li>\r\n    <li><p><strong>सम्यक संकल्प (Right Intention)</strong> मन के सही इरादे और उद्देश्य।</p></li>\r\n    <li><p><strong>सम्यक वचन (Right Speech)</strong> सत्य बोलना, दूसरों को दुख न पहुँचाना।</p></li>\r\n    <li><p><strong>सम्यक कर्म (Right Action)</strong> अच्छे कार्य करना, अहिंसा का पालन करना।</p></li>\r\n    <li><p><strong>सम्यक आजीविका (Right Livelihood)</strong> सही पेशे का चयन करना जो किसी को नुकसान न पहुँचाए।</p></li>\r\n    <li><p><strong>सम्यक प्रयास (Right Effort)</strong> अच्छे कार्यों और विचारों को बढ़ावा देना।</p></li>\r\n    <li><p><strong>सम्यक स्मृति  (Right Mindfulness)</strong> अपने विचारों, भावनाओं और क्रियाओं के प्रति जागरूक रहना।</p></li>\r\n    <li><p><strong>सम्यक समाधि (Right Concentration)</strong> ध्यान और मानसिक एकाग्रता को प्राप्त करना।</p></li>\r\n</ul>\r\n<h2>बौद्ध धर्म का विस्तार</h2>\r\n<p>बौद्ध धर्म का विस्तार प्रारंभ में भारत में हुआ, लेकिन समय के साथ यह अन्य देशों में भी फैल गया। बौद्ध धर्म की दो प्रमुख शाखाएँ हैं: <strong>हिनायान</strong> (Theravada) और <strong>महायान</strong> (Mahayana)।</p>\r\n<h3 class=\"atech\">हिनायान बौद्ध धर्म</h3>\r\n<p>यह शाखा बौद्ध धर्म के मूल सिद्धांतों को मानती है और इसे \'<strong>पारंपरिक</strong>\' बौद्ध धर्म माना जाता है। हिनायान बौद्ध धर्म का मुख्य उद्देश्य आत्मज्ञान प्राप्त करना है। यह शाखा मुख्य रूप से श्रीलंका, थाईलैंड, बर्मा, कंबोडिया, और लाओस में प्रचलित है।</p>\r\n<h3 class=\"atech\">महायान बौद्ध धर्म</h3>\r\n<p>महायान बौद्ध धर्म ने बौद्ध धर्म को एक व्यापक दृष्टिकोण से देखा और इसमें अन्य प्राणियों की सहायता करने पर बल दिया। महायान बौद्ध धर्म में बोधिसत्त्व की अवधारणा प्रमुख है, जो दूसरों की मुक्ति के लिए जीवन बिताता है। यह शाखा मुख्य रूप से चीन, जापान, कोरिया और तिब्बत में प्रचलित है।</p>\r\n\r\n<h2>बौद्ध धर्म का समाज पर प्रभाव</h2>\r\n<p>बौद्ध धर्म ने भारतीय समाज को गहरे रूप से प्रभावित किया। इसके सिद्धांतों ने जातिवाद, अंधविश्वास और सामाजिक भेदभाव को चुनौती दी। बुद्ध ने सभी मनुष्यों को समान माना और उनके धर्म में कोई जाति या वर्ग का भेद नहीं था। इसने भारतीय समाज में एक नए दृष्टिकोण को जन्म दिया, जिसमें व्यक्ति की आंतरिक जागरूकता और सत्य की खोज को प्राथमिकता दी गई।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>बौद्ध धर्म ने न केवल धार्मिक क्षेत्र में बल्कि समाज, राजनीति, और संस्कृति में भी गहरी छाप छोड़ी है। इसके सिद्धांतों ने मानवता के भले के लिए काम करने, दुखों से मुक्ति पाने और मानसिक शांति प्राप्त करने के रास्ते खोले हैं। बौद्ध धर्म ने विश्वभर में शांति, सहिष्णुता और बंधुत्व के विचारों को फैलाया है और यह आज भी लोगों के जीवन को प्रभावित करता है।</p>\r\n<p>बौद्ध धर्म का संदेश आज भी अत्यंत प्रासंगिक है। वह हमें अपने अंदर के दुखों को समझने, दूसरों की मदद करने और सत्य के मार्ग पर चलने की प्रेरणा देता है। जब तक मानवता अपने अस्तित्व को समझने और शांतिपूर्ण जीवन जीने का प्रयास करती रहेगी, तब तक बौद्ध धर्म का संदेश अनंतकाल तक जीवित रहेगा।</p>',22,'2025-05-29 17:34:06','2025-05-29 18:03:43','','Publish',0,'open',19,96),('ब्रह्म समाज एक सामाजिक और धार्मिक पुनर्जागरण आंदोलन।','brahma-samaj-is-a-social-and-religious-renaissance-movement',2,'<p>19वीं शताब्दी का भारत सामाजिक, धार्मिक और राजनीतिक दृष्टि से बड़े बदलावों के दौर से गुजर रहा था। एक ओर ब्रिटिश शासन\r\n    भारतीय परंपराओं को चुनौती दे रहा था, वहीं दूसरी ओर भारतीय समाज के भीतर अनेक कुरीतियाँ, अंधविश्वास और सामाजिक\r\n    असमानताएं व्याप्त थीं। ऐसे समय में एक चेतना का उदय हुआ जिसने भारतीय समाज को तर्क, विवेक, समानता और नैतिकता की ओर\r\n    उन्मुख किया। इस चेतना का नाम था – ब्रह्म समाज। इसकी स्थापना राजा राममोहन राय द्वारा 1828 में की गई थी, जो भारतीय\r\n    नवजागरण के अग्रदूत माने जाते हैं। इसका एक उद्देश्य भिन्न भिन्न धार्मिक आस्थाओं में बँटी हुई जनता को एक जुट करना तथा\r\n    समाज में फैली कुरीतियों को दूर करना था।</p>\r\n<p>ब्रिटिश शासन के आगमन के बाद भारतीय समाज में कई पश्चिमी विचारधाराओं का प्रवेश हुआ, जैसे मानवाधिकार, स्वतंत्रता,\r\n    समानता, वैज्ञानिक दृष्टिकोण आदि। इसके परिणामस्वरूप समाज के कुछ प्रबुद्ध वर्गों में आत्मचिंतन और आत्ममंथन की\r\n    प्रक्रिया शुरू हुई। लोगों ने परंपराओं, धर्म, जाति और लिंग के आधार पर हो रहे भेदभाव पर प्रश्न उठाना शुरू किया।</p>\r\n<h2>ब्रह्म समाज की स्थापना और उद्देश्य</h2>\r\n<p>राजा राममोहन राय का जन्म 22 मई 1772 को पश्चिम बंगाल के राधानगर गाँव में हुआ था। एक ब्राह्मण परिवार से थे। उन्होंने\r\n    अरबी, फारसी, संस्कृत और अंग्रेज़ी में गहरी शिक्षा प्राप्त की थी। वे वेदों, उपनिषदों और इस्लाम तथा ईसाई धर्मग्रंथों\r\n    का भी अध्ययन कर चुके थे। उन्होंने सभी धर्मों में उपस्थित नैतिक मूल्यों को मानते हुए मूर्ति पूजा, पाखंड और रूढ़ियों\r\n    का विरोध किया।</p>\r\n<p>राममोहन राय ने सबसे पहले 1828 में \"आत्मीय सभा\" की स्थापना की जो आगे चलकर ब्रह्म समाज के रूप में परिणत हुई। इस संस्था\r\n    का उद्देश्य था—एकेश्वरवाद को बढ़ावा देना, तर्क और नैतिकता के आधार पर धर्म का पुनर्मूल्यांकन करना, और समाज में सुधार\r\n    लाना।</p>\r\n<h2>ब्रह्म समाज के सिद्धांत</h2>\r\n<p>ब्रह्म समाज ने धर्म और समाज दोनों में सुधार की कोशिश की। इसके प्रमुख सिद्धांत थे</p>\r\n<h3>ब्रह्म समाज के धार्मिक सिद्धांत</h3>\r\n<ul>\r\n    <li><p>ईश्वर एक है। वह संसार का स्रष्टा पालक और रक्षक है; उसकी शक्ति, प्रेम, न्याय और पवित्रता असिमित है। </p></li>\r\n    <li><p>जीवात्मा अमर है; उसमें उन्नति करने की असीज़ क्षमता है और वह अपने कार्यों के लिए भगवान के सामने उत्तरदायी है। आध्यात्मिक उन्नति के लिए प्रार्थना, भगवान का आश्रय और उसके अस्तित्व की अनुभूति आवश्यक है।</p></li>\r\n    <li><p>किसी भी बनाई हुई वस्तु को ईश्वर समझकर नहीं पूजना चाहिए और न की किसी पुस्तक या पुरुष को निर्वाह अथवा मोक्ष का एकमात्र साधन मानना चाहिए।</p></li>\r\n</ul>\r\n<h3>ब्रह्म समाज के सामाजिक सिद्धांत</h3>\r\n<ul>\r\n    <li><p>अस्पृश्यता का विनाश होना आवश्यक है।</p></li>\r\n    <li><p>बाल विवाह पर रोक लगाना परम आवश्यक है।</p></li>\r\n    <li><p>विधवा - विवाह का प्रचार 4. बाल - हत्या अपराध है।</p></li>\r\n</ul>\r\n<h2>ब्रह्म समाज के विकास के चरण</h2>\r\n<p>राममोहन राय की मृत्यु के बाद देबेंद्रनाथ टैगोर (1817–1905) ने ब्रह्म समाज को नया जीवन दिया। उन्होंने 1843 में तत्त्वबोधिनी सभा के माध्यम से इसे संगठित किया। उन्होंने \'ब्रह्म धर्म\' नामक ग्रंथ लिखा और इसे वेदों और उपनिषदों की व्याख्या के माध्यम से एक वैचारिक दिशा दी।</p>\r\n<p>केशव चंद्र सेन (1838–1884) एक युवा, प्रखर और करिश्माई नेता थे। उन्होंने ब्रह्म समाज को बंगाल से बाहर पूरे भारत में फैलाया। उन्होंने समाज में सुधार लाने के लिए अनेक आंदोलनों की शुरुआत की, जैसे अंतरजातीय विवाह, स्त्री अधिकारों की रक्षा, शिक्षा सुधार आदि। हालाँकि बाद में केशव चंद्र सेन और देबेंद्रनाथ टैगोर के बीच वैचारिक मतभेद हुए, जिससे ब्रह्म समाज दो भागों में बँट गया</p>\r\n<p>आदि ब्रह्म समाज (देबेंद्रनाथ टैगोर के नेतृत्व में) और नव ब्रह्म समाज ( केशव चंद्र सेन के नेतृत्व में)</p>\r\n<h2>ब्रह्म समाज का योगदान/ देन</h2>\r\n<h3 class=\"atech\">सामाजिक सुधार</h3>\r\n<p>ब्रहन समाज ने बाल विवाह, कन्या व वर का क्रय विक्रय, कन्या वध, सती प्रथा आदि का विरोध किया, विधवा विवाह का समर्थन किया। छुआ-छूत, अस्पृश्यता, जाति पाँति आदि के विरुद्ध बीड़ा उठाया।</p>\r\n<h3 class=\"atech\">धार्मिक सुधार</h3>\r\n<p>पाखण्ड, आडम्बर, पुरोदिववाद, कर्मकांड का विरोधा मूर्ति-पूजा, अनेकेश्वरवाद के विरुद्ध आवाज उठाई, मानव धर्म ची थी की दुहाई दी। इस विश्वास का प्रसार किया कि आत्मा एक है।</p>\r\n<h3 class=\"atech\">शिक्षा में सुधार</h3>\r\n<p>हिन्दू कॉलेज, रुइंगलिश स्कूल आदि शिक्षा की संस्थाओं दुवारा भारतीय को पाश्चात्य विज्ञान का अध्ययन करवाया। और स्त्रियों के लिए भी \"बैथून कॉलेज\" तथा अन्य शिक्षणालयों की स्थापना की। आज भी अनेक स्थानों पर ब्रह्म समाज के स्कूल आदि चल रहे हैं</p>\r\n<h2 class=\"atech\">निसकर्ष</h2>\r\n<p>इस तरह हम देखते है की राजा राममोहन राय द्वारा स्थापित ब्रह्म समाज भारतीय इतिहास में एक क्रांतिकारी आंदोलन था जिसने धर्म और समाज दोनों को विवेक, नैतिकता और मानवता के आधार पर पुनर्संगठित करने का प्रयास किया। यह केवल धार्मिक सुधार का आंदोलन नहीं था, बल्कि सामाजिक चेतना और जागरूकता का वाहक भी था। इसकी विचारधारा ने न केवल 19वीं शताब्दी के भारत को बदला बल्कि आधुनिक भारत की नींव रखने में भी महत्वपूर्ण भूमिका निभाई।</p>',5,'2025-05-30 02:48:04','2025-05-30 03:19:03','','Publish',0,'open',60,97),('भक्ति आंदोलन - एक धार्मिक-सामाजिक क्रांति','bhakti-movement-religious-social-revolution',2,'<p>भारतीय इतिहास में <strong>मध्यकाल</strong> को अक्सर सामाजिक, धार्मिक, राजनीतिक अस्थिरता और विदेशी आक्रमणों का काल माना जाता है। इस समय समाज में गहरी धार्मिक रूढ़ियाँ, सामाजिक भेदभाव, और कर्मकांडों का बोलबाला था। इन्हीं परिस्थितियों में भारतीय उपमहाद्वीप में एक अद्भुत धार्मिक और सामाजिक जागरण का उदय हुआ जिसे <strong>भक्ति आंदोलन</strong> कहा गया। यह आंदोलन भारतीय जनता के दिलों में <i>ईश्वर की प्राप्ति</i> के एक सरल और मानवीय मार्ग का संदेश लेकर आया और समाज को आडंबर व जातीय भेदभाव से मुक्त कराने का प्रयास किया।</p>\r\n<p>7वीं से 17वीं शताब्दी तक फैले इस आंदोलन की जड़ें दक्षिण भारत में पाई जाती हैं। यहाँ नायनार (शैव) और आलवार (वैष्णव) संतों ने भक्ति की भावना को समाज में जीवंत किया। इस परंपरा ने धीरे-धीरे उत्तर भारत में प्रवेश किया और वहाँ इसे कबीर, तुलसीदास, मीराबाई, गुरु नानक, सूरदास आदि जैसे संतों ने लोकप्रिय बनाया। यह आंदोलन संप्रदायवाद, मूर्ति पूजा की कठोरता, जाति-पाति और धार्मिक पाखंड के विरुद्ध एक <strong>क्रांति</strong> बन गया।</p>\r\n\r\n<h2>भारत में भक्ति आंदोलन के उदय के कारण</h2>\r\n<p>मुस्लिम शासकों के बर्बर शासन से कुंठित एवं उनके अत्याचारों से त्रस्त हिन्दू जनता ने ईश्वर की शरण में अपने को अधिक सुरक्षित महसूस कर <strong>भक्ति मार्ग</strong> का सहारा लिया।</p>\r\n<p>हिन्दू एवं मुस्लिम जनता के आपस में सामाजिक एवं सांस्कृतिक संपर्क से दोनों के मध्य सद्भाव, सहानुभूति एवं सहयोग की भावना का विकास हुआ। इस कारण से भी भक्ति आंदोलन के विकास में सहयोग मिला।</p>\r\n<p>सूफी संतों की उदार एवं सहिष्णुता की भावना तथा एकेश्वरवाद में उनकी प्रबल निष्ठा ने हिन्दुओं को प्रभावित किया। हिन्दुओं ने सूफियों की तरह एकेश्वरवाद में विश्वास करते हुए ऊँच-नीच एवं जात-पात का विरोध किया। शंकराचार्य का ज्ञान मार्ग व अद्वैतवाद अब साधारण जनता के लिये बोधगम्य नहीं रह गया था।</p>\r\n<p>मुस्लिम शासकों द्वारा मूर्तियों को नष्ट एवं अपवित्र कर देने के कारण, बिना मूर्ति एवं मंदिर के ईश्वर की आराधना के प्रति लोगों का झुकाव बढ़ा, जिसके लिये उन्हें <strong>भक्ति मार्ग</strong> का सहारा लेना पड़ा।</p>\r\n\r\n<h2>भक्ति आंदोलन का महत्त्व</h2>\r\n<p>भक्ति आंदोलन के संतों ने लोगों के सामने कर्मकांडों से मुक्त जीवन का ऐसा लक्ष्य रखा, जिसमें ब्राह्मणों द्वारा लोगों के शोषण का कोई स्थान नहीं था।</p>\r\n<p>भक्ति आंदोलन के कई संतों ने <strong>हिन्दू-मुस्लिम एकता</strong> पर बल दिया, जिससे इन समुदायों के मध्य सहिष्णुता और सद्भाव की स्थापना हुई।</p>\r\n<p>भक्तिकालीन संतों ने क्षेत्रीय भाषाओं की उन्नति में महत्त्वपूर्ण योगदान दिया। हिंदी, पंजाबी, तेलुगू, कन्नड़, बंगला आदि भाषाओं में इन्होंने अपनी भक्तिपरक रचनाएँ कीं।</p>\r\n<p>भक्ति आंदोलन के प्रभाव से जाति-बंधन की जटिलता कुछ हद तक समाप्त हुई। फलस्वरूप दलित व निम्न वर्ग के लोगों में भी आत्मसम्मान की भावना जागी।</p>\r\n<p>भक्तिकालीन आंदोलन ने कर्मकांड रहित समतामूलक समाज की स्थापना के लिये आधार तैयार किया।</p>\r\n\r\n<h2>भक्ति आंदोलन में प्रमुख संतों का योगदान और विचार</h2>\r\n<p>संत कबीर ने <strong>ईश्वर को निराकार और सर्वव्यापी</strong> मानते हुए जातिवाद और कर्मकांड के खिलाफ आवाज उठाई। उनका कहना था कि सच्ची भक्ति प्रेम से होती है, न कि किसी बाहरी पूजा से। संत रविदास ने भी समानता की बात की और यह बताया कि हर व्यक्ति को भक्ति का अधिकार है, चाहे वह किसी भी जाति या धर्म से हो।</p>\r\n<p>मीराबाई ने कृष्ण भक्ति को अपना जीवन मानते हुए प्रेम और भक्ति के माध्यम से समाज में समानता का संदेश दिया। वे एक महिला संत थीं, जिन्होंने अपने भजनों के जरिए कृष्ण के प्रति प्रेम को सबसे ऊँचा बताया। गुरु नानक देव ने सिख धर्म की नींव रखी और <i>\"एक ओंकार\"</i> का संदेश दिया, जो यह बताता है कि ईश्वर एक है और उसका भौतिक रूप नहीं है। उनका मुख्य उद्देश्य था समाज में भेदभाव को समाप्त करना।</p>\r\n<p>तुलसीदास ने <i>\"रामचरितमानस\"</i> की रचना की, जिससे राम की भक्ति को जन-जन में प्रसारित किया। उनके अनुसार राम का जीवन आदर्श है। सूरदास ने कृष्ण की बाल लीलाओं और प्रेम भक्ति को सरल भाषा में व्यक्त किया, जो आज भी लोकप्रिय है।</p>\r\n<p>चैतन्य महाप्रभु ने संकीर्तन के माध्यम से कृष्ण प्रेम को फैलाया और वैष्णव धर्म को समृद्ध किया। वहीं, तुकाराम ने मराठी भाषा में अभंगों के द्वारा विट्ठल भक्ति को प्रमुख किया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>भक्ति आंदोलन ने भारतीय समाज में धर्म, समानता और सामाजिक सुधार की दिशा में महत्वपूर्ण परिवर्तन किए। इस आंदोलन के संतों ने जातिवाद, पाखंड और कर्मकांड का विरोध करते हुए ईश्वर के प्रति सच्ची भक्ति और प्रेम को सर्वोच्च माना। उन्होंने भक्ति को व्यक्तिगत अनुभव और समाज में भाईचारे का माध्यम बनाया। भक्ति आंदोलन ने विशेष रूप से दलितों और स्त्रियों को धार्मिक अधिकार दिए और समाज में समानता का संदेश दिया। इसके माध्यम से, भारतीय समाज में <strong>एकता, प्रेम और आत्मनिर्भरता</strong> का एक नया दृष्टिकोण स्थापित हुआ।</p>',6,'2025-05-30 02:48:04','2025-05-30 04:08:47','','Publish',0,'open',60,98),('मुगल कालीन सामाजिक जीवन','mughal-carpet-social-life',2,'<p>भारत का इतिहास बहुत लंबा और रोचक है। इसमें कई राजवंशों ने शासन किया, लेकिन मुगल काल (1526 ई. से 1857 ई. तक) एक ऐसा समय था, जब भारत में बहुत से बदलाव आए। इन बदलावों का असर सिर्फ राजनीति तक सीमित नहीं था, बल्कि समाज, धर्म, रहन-सहन, शिक्षा और लोगों की सोच पर भी पड़ा।</p>\r\n<p>मुगल काल ने भारत के सांस्कृतिक और सामाजिक ताने-बाने को गहराई से प्रभावित किया। इस दौर में अनेक सांस्कृतिक आदान-प्रदान और नवाचार हुए, जो आज भी भारतीय समाज के विभिन्न पहलुओं में देखे जा सकते हैं। भाषा, कला, स्थापत्य और रीत-रिवाज़ों में भी मुगलकालीन प्रभाव स्पष्ट रूप से दिखाई देता है, जिससे यह युग भारतीय इतिहास में एक उल्लेखनीय अध्याय बन गया।</p>\r\n\r\n<p>मुगल शासक खुद तो मुस्लिम थे, लेकिन उनके राज्य में ज़्यादातर लोग हिंदू थे। इसलिए उस समय का समाज बहुत विविध था – <i>कई धर्मों, जातियों और परंपराओं से मिलकर बना था।</i> मुगल काल का सामाजिक जीवन हमें यह बताता है कि लोग कैसे रहते थे, क्या सोचते थे, कौन-सी प्रथाएँ थीं, और समाज में कौन-से बदलाव हो रहे थे।</p>\r\n<p>मुगल काल की सामाजिक संरचना में धार्मिक सहिष्णुता की भावना भी देखने को मिली, जिससे अलग-अलग समुदायों के बीच तालमेल बना रहा। यह सहिष्णुता ही थी जिसने भारत को एक समृद्ध और बहु-धार्मिक सभ्यता बनाए रखा, जहाँ विविधता में एकता की भावना गहराई से स्थापित थी।</p>\r\n\r\n<h2>धार्मिक जीवन</h2>\r\n<p>मुगल काल में भारत का समाज मुख्य रूप से दो धर्मों में बँटा हुआ था</p>\r\n<h3 class=\"atech\">हिंदू धर्म</h3>\r\n<p>हिंदू समाज उस समय बहुत बड़ी संख्या में था। वह कई जातियों और वर्गों में बँटा हुआ था। ब्राह्मण, क्षत्रिय, वैश्य, शूद्र और दलित जैसी जातियाँ समाज में मौजूद थीं। ब्राह्मणों को सबसे ऊपर माना जाता था और दलितों को सबसे नीचे। हिंदू समाज में मंदिर, पूजा-पाठ और त्यौहारों का बहुत महत्व था।</p>\r\n<p>हिंदू धर्म की धार्मिक प्रथाएँ और सामाजिक संगठन उस समय अत्यंत जटिल थे। विभिन्न त्योहार, धार्मिक अनुष्ठान और सामाजिक नियम लोगों के जीवन का अभिन्न हिस्सा थे। जाति व्यवस्था ने समाज को वर्गीकृत किया, जिससे सामाजिक पदानुक्रम स्पष्ट था। इस समय की धार्मिक गतिविधियाँ सामाजिक जीवन को मजबूती प्रदान करती थीं और सामुदायिक मेल-जोल को प्रोत्साहित करती थीं।</p>\r\n<h3 class=\"atech\">मुस्लिम धर्म</h3>\r\n<p>मुसलमान शासक वर्ग में थे और उनकी संख्या शहरों में ज़्यादा थी। मुस्लिम समाज में भी ऊँच-नीच मौजूद थी। वहाँ \"<strong>अशराफ</strong>\" (विदेशी मूल के मुस्लिम) को ऊँचा और \"अजलाफ\" (स्थानीय मुसलमान) को नीचा माना जाता था। मुसलमानों का धार्मिक जीवन मस्जिदों, रोज़ा, नमाज़ और हज जैसे धार्मिक कार्यों से जुड़ा था।</p>\r\n<p>मुस्लिम धर्म में सामाजिक स्तरों का प्रभाव धार्मिक क्रियाकलापों और व्यवहारों पर भी पड़ता था। धार्मिक और सामाजिक कर्तव्यों का पालन अत्यंत महत्वपूर्ण माना जाता था। इसके अलावा, सूफी संप्रदाय ने धार्मिक सहिष्णुता और प्रेम के संदेश को फैलाने में अहम भूमिका निभाई, जिससे विभिन्न समुदायों के बीच सांस्कृतिक संवाद बढ़ा।</p>\r\n<p>अकबर जैसे मुगल बादशाह ने \"<strong>सुलह-ए-कुल</strong>\" की नीति अपनाई, जिसका मतलब था – सभी धर्मों के साथ शांति और समान व्यवहार। उन्होंने हिंदू राजा-रानियों से रिश्ते बनाए, मंदिरों को दान दिया और \"दीन-ए-इलाही\" नामक एक नया धर्म शुरू करने की कोशिश भी की, जिसमें सभी धर्मों की अच्छी बातें शामिल थीं।</p>\r\n<p>अकबर की यह नीति भारतीय उपमहाद्वीप में धार्मिक सहिष्णुता की एक मिसाल थी, जिसने समाज में एकता और समरसता को बढ़ावा दिया। उनकी यह पहल साम्प्रदायिक तनावों को कम करने और विभिन्न समुदायों के बीच भाईचारे को बढ़ावा देने की दिशा में महत्वपूर्ण कदम साबित हुई।</p>\r\n\r\n<p>अधिकांश जनसंख्या गाँवों में रहती थी। कृषि मुख्य जीविका थी। समाज पंचायत व्यवस्था पर आधारित था। जाति व्यवस्था गाँवों में अधिक कठोर थी। दिल्ली, आगरा, लाहौर, फतेहपुर सीकरी जैसे शहर प्रमुख शहरी केंद्र थे। इनमें व्यापार, दस्तकारी, शिक्षा और प्रशासनिक गतिविधियाँ केंद्रित थीं।शहरों में बाजार, कारखाने, सराय और बाग-बगीचे आम थे।</p>\r\n<p>शहरी और ग्रामीण जीवन के बीच स्पष्ट भेद था। ग्रामीण क्षेत्रों में परंपरागत जीवनशैली और कृषि आधारित अर्थव्यवस्था प्रमुख थी, जबकि शहरों में व्यापार, कला, संस्कृति और प्रशासनिक कार्यों का विकास हुआ। इस भेद ने समाज के विभिन्न वर्गों की जीवनशैली और सामाजिक संरचना को प्रभावित किया।</p>\r\n\r\n<h2>परिवार एवं शिक्षा</h2>\r\n<p>मुगल काल में संतान को विशेष महत्व दिया जाता था। <i>बेटे को कुल का वारिस और भविष्य का सहारा माना जाता था, जबकि बेटियों को पारिवारिक जिम्मेदारी समझा जाता था।</i> मुगल काल में परिवार <strong>संयुक्त</strong> होता था, जिसमें दादा-दादी, माता-पिता, और बच्चों का एक साथ रहना आम था। पुरुष परिवार का मुखिया होते थे, जबकि महिलाएँ घरेलू कार्यों तक सीमित थीं। पारिवारिक संबंधों में अनुशासन और परंपराओं का पालन किया जाता था, और मुगल काल में संतान को ईश्वर का वरदान माना जाता था।, कई पीढ़ियाँ एक साथ रहती थीं। शिक्षा केवल उच्च वर्ग तक सीमित थी। मुस्लिम समाज में मदरसे और मकतब प्रमुख शैक्षणिक संस्थान थे जहाँ कुरान, फारसी, गणित और धार्मिक शिक्षा दी जाती थी। हिंदू समाज में शिक्षा गुरुकुल और पाठशालाओं में दी जाती थी, जहाँ संस्कृत, गणित, धर्मशास्त्र और ज्योतिष सिखाया जाता था। लड़कियों की शिक्षा की ओर समाज का झुकाव बहुत कम था और उन्हें घरेलू कार्यों की शिक्षा देना ही पर्याप्त माना जाता था। कुल मिलाकर शिक्षा का उद्देश्य धार्मिक और नैतिक ज्ञान प्रदान करना था, जिसमें सामाजिक वर्ग और लिंग के आधार पर भेदभाव स्पष्ट रूप से देखा जा सकता है।</p>\r\n<p>परिवार की संरचना और शिक्षा के क्षेत्र में सामाजिक भेद स्पष्ट थे। उच्च वर्ग के बच्चे अधिक शिक्षित होते थे और उनमें प्रशासन, धर्म, कला आदि की शिक्षा दी जाती थी, जबकि निम्न वर्ग में यह सीमित थी। <i>महिलाओं की शिक्षा को प्राथमिकता नहीं दी जाती थी</i>, जिससे उनके सामाजिक विकास पर प्रभाव पड़ता था। परिवार में अनुशासन और कड़ी सामाजिक नियमावली ने व्यक्तिगत स्वतंत्रता को सीमित किया।</p>\r\n\r\n<h2>विवाह प्रथा</h2>\r\n<p>मुगल काल में विवाह सामाजिक और धार्मिक दायित्व माना जाता था। हिंदू समाज में विवाह एक संस्कार था, जबकि मुस्लिम समाज में यह एक सामाजिक अनुबंध माना जाता था। दोनों समुदायों में बाल विवाह प्रचलित थे और विवाह अधिकतर माता-पिता द्वारा तय किए जाते थे। स्त्रियों की भूमिका केवल गृहस्थ जीवन तक सीमित थी और वे पति तथा परिवार की इच्छाओं के अधीन मानी जाती थीं। <i>पर्दा प्रथा विशेषकर मुस्लिम महिलाओं में अत्यंत कठोर रूप से पालन की जाती थी</i>, वहीं हिंदू महिलाओं में भी इसका प्रभाव बढ़ रहा था। दहेज प्रथा आम थी और स्त्रियों को अपने अधिकारों से वंचित रखा जाता था। उच्च वर्ग में बहुविवाह का चलन था, जबकि निम्न वर्ग में एक पत्नी के साथ जीवन व्यतीत करने की परंपरा अधिक सामान्य थी। विधवाओं की स्थिति अत्यंत दुखद थी और सती प्रथा जैसी अमानवीय परंपराएँ भी मौजूद थीं।</p>\r\n<p>विवाह प्रणाली में महिलाओं की स्थिति कमजोर थी और उन्हें सामाजिक नियमों और परिवार की इच्छाओं के अधीन रखा जाता था। विवाह के माध्यम से परिवारों के बीच रिश्ते बनते थे, परंतु महिलाओं के अधिकारों की अनदेखी आम थी। सती प्रथा और विधवाओं की दुर्दशा जैसी कुप्रथाओं ने महिलाओं के जीवन को अत्यंत कठिन बना दिया था। सामाजिक सुधार की आवश्यकताएँ इस दौर में भी स्पष्ट थीं।</p>\r\n\r\n<h2>मनोरंजन</h2>\r\n<p>मुगल काल में मनोरंजन के विविध साधन थे जो वर्ग और आर्थिक स्थिति के अनुसार भिन्न होते थे। शासक वर्ग संगीत, नृत्य, शिकार, मुशायरे और कव्वाली जैसे शाही मनोरंजन में लिप्त रहते थे। दरबारों में कलाकारों और नर्तकियों को आमंत्रित किया जाता था और त्योहारों के अवसर पर भव्य आयोजन होते थे। आम जनता के लिए मेले, तमाशे, कहानी सुनना, लोकगीत, लोकनाट्य, झूला, पतंगबाजी, कुश्ती, और रामलीला जैसे मनोरंजन लोकप्रिय थे। धार्मिक पर्वों और मेलों का आयोजन सामाजिक जीवन का महत्वपूर्ण हिस्सा था जहाँ लोग न केवल मनोरंजन करते थे, बल्कि सामाजिक मेल-जोल और सामूहिकता की भावना का अनुभव भी करते थे। इस प्रकार मुगल काल का सामाजिक जीवन सांस्कृतिक रूप से समृद्ध और विविधता से परिपूर्ण था।</p>\r\n<p>मनोरंजन न केवल शाही वर्ग का मनोरंजन था, बल्कि आम जनता के बीच भी यह सामाजिक समरसता और सांस्कृतिक अभिव्यक्ति का माध्यम था। मेलों और त्योहारों में सामूहिक भागीदारी से लोगों के बीच भाईचारा बढ़ा और सांस्कृतिक विरासत के संरक्षण में मदद मिली। कला, संगीत और नाटक की प्रथाएँ समाज के हर वर्ग में लोकप्रिय थीं।</p>\r\n\r\n<h2>वस्त्र एवं आभूषण</h2>\r\n<p>मुगल काल के लोगों के वस्त्र और आभूषण उनके सामाजिक और आर्थिक स्थिति के प्रतीक होते थे। ऊँचे वर्ग के पुरुष रेशमी कुर्ता, पायजामा, अंगरखा और रंग-बिरंगी पगड़ियाँ पहनते थे, जबकि महिलाएँ भारी कढ़ाई वाले घाघरे, चोली और चुनरी या बुरका धारण करती थीं। निम्न वर्ग के लोग साधारण कपड़े पहनते थे जो अधिकतर सूती होते थे। आभूषणों का प्रचलन स्त्रियों में विशेष रूप से अधिक था। स्त्रियाँ सोने, चाँदी और कीमती पत्थरों के गहने पहनती थीं जैसे कि हार, झुमके, कंगन, पायल, बिचुए, मांगटीका, नथ इत्यादि। पुरुष भी अंगूठी, ताबीज और कभी-कभी कानों में बाली पहनते थे। आभूषण केवल सौंदर्य के लिए ही नहीं बल्कि सामाजिक प्रतिष्ठा और पारिवारिक संपत्ति के रूप में भी माने जाते थे। वस्त्रों और आभूषणों में क्षेत्रीय विविधता भी देखी जाती थी जो भारत की सांस्कृतिक बहुलता को दर्शाती है।</p>\r\n<p>वस्त्र और आभूषण न केवल पहचान का प्रतीक थे, बल्कि सामाजिक वर्ग और आर्थिक स्थिति को भी प्रतिबिंबित करते थे। उच्च वर्ग के लोग भव्य पोशाकों और गहनों से अपनी स्थिति दर्शाते थे, जबकि निम्न वर्ग की पोशाकें सरल और कार्यात्मक थीं। क्षेत्रीय प्रभावों और सांस्कृतिक विविधता के कारण वस्त्रों और आभूषणों में रंग-रूप और शैली की कई भिन्नताएँ देखने को मिलीं।</p>\r\n\r\n<h2>खान-पान</h2>\r\n<p>मुगल काल में खान-पान का तरीका व्यक्ति की जाति, धर्म और वर्ग पर निर्भर करता था। मुस्लिम शासक वर्ग की रसोई में बिरयानी, कबाब, कोरमा, नान, फिरनी और शीरमाल जैसे स्वादिष्ट और मसालेदार व्यंजन तैयार होते थे। हिंदू समाज में चावल, दाल, सब्ज़ी, रोटी, दूध, दही और घी का प्रयोग अधिक होता था। ग्रामीण क्षेत्रों में सादा भोजन प्रचलित था जबकि नगरों में मिठाई, मावा, लड्डू और अन्य व्यंजन उत्सवों के अवसर पर बनाए जाते थे। शाही दरबारों में विदेशी व्यंजनों का भी प्रयोग होता था, जैसे तुर्की और ईरानी प्रभाव वाले भोजन। त्योहारों पर विशेष पकवान बनते थे और धार्मिक मान्यताओं के अनुसार मांसाहारी और शाकाहारी भोजन का पालन किया जाता था। भोजन के साथ-साथ लोग ताज़गी के लिए गुलाब जल, ताज़ा फलों का रस और कभी-कभी नशीले पेय भी पीते थे। खान-पान की यह विविधता उस समय की समृद्ध सांस्कृतिक और सामाजिक जीवनशैली को दर्शाती है।</p>\r\n<p>खान-पान न केवल पोषण का साधन था बल्कि सामाजिक और धार्मिक पहचान का भी प्रतीक था। विभिन्न समुदायों की खान-पान की आदतें उनके धर्म और सांस्कृतिक परंपराओं से गहराई से जुड़ी थीं। भोजनों में उपयोग होने वाले मसाले, पकवानों की विविधता और त्यौहारों के अवसर पर खास व्यंजन सामाजिक मेल-जोल और सांस्कृतिक धरोहर को जीवित रखते थे।</p>\r\n\r\n<h2>नैतिक जीवन</h2>\r\n<p>मुगल काल में नैतिक जीवन पर धर्म, रीति-रिवाज़ और सामाजिक परंपराओं का गहरा प्रभाव था। लोगों का जीवन धार्मिक मान्यताओं से जुड़ा होता था और नैतिकता को धार्मिक कर्तव्यों के रूप में समझा जाता था। ईमानदारी, दया, सेवा, बड़ों का सम्मान और समाज के प्रति कर्तव्य को नैतिक गुणों में गिना जाता था। भक्ति और सूफी आंदोलनों ने लोगों को प्रेम, सहिष्णुता और समानता का संदेश दिया जिससे समाज में नैतिक जागरूकता आई। हालांकि ऊँच-नीच, जात-पात, पर्दा प्रथा और स्त्रियों की दुर्दशा जैसी सामाजिक बुराइयाँ भी व्याप्त थीं। आम जनता अधिकतर धार्मिक प्रवृत्ति की थी और अपने नैतिक कर्तव्यों का पालन करती थी। साथ ही मुगल शासकों ने भी अपने धार्मिक विचारों के अनुसार समाज में न्याय, करुणा और दया की भावना को बढ़ावा देने का प्रयास किया।</p>\r\n<p>नैतिकता की समझ धार्मिक और सामाजिक दोनों स्तरों पर स्थापित थी, जिससे सामाजिक व्यवस्था बनी रहती थी। भले ही समाज में कई कुरीतियाँ थीं, लेकिन धार्मिक आस्थाएँ और सूफी विचारधारा ने लोगों के जीवन में एक प्रकार की नैतिकता और सहिष्णुता विकसित की। शासकों के प्रयासों से न्याय और करुणा की भावना को बढ़ावा मिला, जिससे सामाजिक समरसता बनी।</p>\r\n\r\n<h2>कला और संस्कृति</h2>\r\n<p>मुगल काल में सामाजिक जीवन अत्यंत सांस्कृतिक रूप से समृद्ध था। तानसेन जैसे संगीतज्ञों ने हिंदुस्तानी शास्त्रीय संगीत को ऊँचाई दी। नृत्य और नाटक कथक जैसी परंपराएं दरबारों और समाज में प्रचलित हुईं। मुगल चित्रकला फारसी और भारतीय परंपराओं का मिश्रण थी। वस्त्राभूषण ऊंचे वर्ग के लोग रेशमी वस्त्र, ज़री की कढ़ाई और कीमती गहने पहनते थे। साधारण जनता सूती वस्त्रों का प्रयोग करती थी।</p>\r\n<p>कला और संस्कृति में मुगल काल ने भारतीय सभ्यता को समृद्ध बनाया। स्थापत्य कला, संगीत, नृत्य, चित्रकला और शिल्प कला में नवाचार हुए, जिससे भारतीय कला को वैश्विक पहचान मिली। मुगल कला में फारसी और स्थानीय तत्वों का सुंदर मेल था, जो सांस्कृतिक समरसता का प्रतीक था। यह काल भारतीय सांस्कृतिक इतिहास में स्वर्णिम युग माना जाता है।</p>\r\n\r\n<h2>त्योहार और उत्सव</h2>\r\n<p>मुस्लिम त्योहार - ईद, बकरीद, मुहर्रम, शब-ए-बरात आदि। हिंदू त्योहार - होली, दिवाली, रक्षाबंधन, दशहरा, जन्माष्टमी आदि। मुगल शासक अकबर होली और दिवाली जैसे त्योहारों में भी हिस्सा लेते थे। उत्सवों के समय मेलों, झांकियों और कव्वाली जैसी परंपराएँ समाज को सांस्कृतिक रूप से जोड़ती थीं।</p>\r\n<p>त्योहारों और उत्सवों ने समाज को एकजुट करने और सांस्कृतिक पहचान मजबूत करने में महत्वपूर्ण भूमिका निभाई। धार्मिक सीमाओं के बावजूद, विभिन्न समुदायों के त्योहारों में भागीदारी ने सहिष्णुता और भाईचारे की भावना को बढ़ावा दिया। यह सामाजिक समरसता का एक महत्वपूर्ण पहलू था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>मुगल काल का सामाजिक जीवन विविधताओं से भरा हुआ था। समाज में धर्म, जाति और वर्ग के अनुसार जीवनशैली में अंतर देखने को मिलता था। ऊँचे वर्ग का जीवन भव्य और विलासी था जबकि आम जनता सादा जीवन व्यतीत करती थी। स्त्रियों की स्थिति सीमित और परंपराओं में जकड़ी हुई थी, परंतु समाज में कला, संस्कृति और धार्मिक सहिष्णुता का विकास भी इसी काल में हुआ। शिक्षा, विवाह, खान-पान, वस्त्र, मनोरंजन और नैतिक मूल्यों के क्षेत्र में समाज ने जो विविधता और समृद्धि दिखाई, वह मुगल काल की एक महत्वपूर्ण पहचान बनी रही। यह काल भारतीय समाज के इतिहास में एक महत्वपूर्ण सामाजिक, सांस्कृतिक और नैतिक परिवर्तन का युग था।</p>\r\n<p>अतः मुगल काल को केवल एक राजनैतिक काल के रूप में नहीं, बल्कि सामाजिक और सांस्कृतिक परिवर्तन के एक युग के रूप में देखा जाना चाहिए। इस काल की विरासत ने आधुनिक भारतीय समाज की नींव रखी और उसकी बहुलता, सहिष्णुता और सांस्कृतिक समृद्धि को आकार दिया। मुगल काल की सामाजिक संरचना और सांस्कृतिक विविधता आज भी भारतीय जीवन की प्रमुख विशेषताएँ हैं।</p>\r\n',11,'2025-05-30 02:48:04','2025-05-30 04:31:30','','Publish',0,'open',5,99),('वैदिक कालीन समाज का सामाजिक जीवन','social-life-of-vedic-carpet-society',2,'<p><strong>वैदिक कालीन समाज</strong> का <strong>सामाजिक जीवन</strong> <i>स्वस्थ एवं विकसित</i> था। इस जीवन की आधारशिला <strong>परिवार</strong> होते थे। उस समय <i>संयुक्त परिवार</i> की परंपरा अत्यंत लोकप्रिय थी, जिसमें पति-पत्नी के अतिरिक्त माता-पिता, भाई-बहन, पुत्र-पुत्रियाँ सभी एक साथ रहते थे। नवविवाहिता जब ससुराल आती थी, तो वह सास-ससुर से प्रेम और आदर का भाव रखते हुए <strong>घर की स्वामिनी</strong> बन जाती थी।</p>\r\n\r\n<p>एक ही घर में <i>एकल या संयुक्त परिवार</i> की परंपरा प्रचलित थी। परिवार का <strong>मुखिया प्रायः पिता</strong> होता था, जिसके नेतृत्व में पारिवारिक कार्यों का संचालन होता था। उसके आदेशों का उल्लंघन साधारणतः कोई सदस्य नहीं करता था। <strong>परिवार का अध्यक्ष</strong> सभी सदस्यों की आवश्यकताओं का ध्यान रखता था और उनके प्रति समान भाव से व्यवहार करता था। पत्नियाँ न केवल <i>गृहकार्य</i> में सहभागी होती थीं, बल्कि <strong>धार्मिक कृत्यों</strong> का भी संपादन करती थीं। उन्हें <strong>गृहस्वामिनी</strong> तथा <strong>सधर्मिणी</strong> का <i>सम्मानजनक स्थान</i> प्राप्त था। वास्तव में वे पति के साथ <strong>गृह की शासिका</strong> होती थीं।</p>\r\n\r\n<h2>संतान एवं शिक्षा</h2>\r\n<p>वैदिक काल में <strong>संतान उत्पत्ति</strong> को <i>आध्यात्मिक, धार्मिक तथा आर्थिक</i> दृष्टि से आवश्यक माना जाता था। <strong>पुत्र जन्म</strong> पर विशेष हर्ष मनाया जाता था, परंतु <i>पुत्री जन्म</i> पर उतना उल्लास नहीं होता था। फिर भी, <strong>पुत्र और पुत्री दोनों</strong> को <i>समान रूप से</i> देखा जाता था, तथा उनके <strong>पालन-पोषण और शिक्षा</strong> का समान रूप से प्रबंध किया जाता था।</p>\r\n\r\n<p><strong>कन्याओं</strong> को भी <strong>अध्ययन काल</strong> में <i>ब्रह्मचर्य</i> का पालन करना पड़ता था। विवाह के समय उन्हें <strong>पिता की संपत्ति</strong> का एक भाग प्राप्त होता था। <i>आजीवन कुंवारी कन्याएँ</i> पिता के घर में रहती थीं और उनका भरण-पोषण वहीं होता था।</p>\r\n\r\n<p><strong>ऋग्वेद</strong> से यह प्रमाणित होता है कि <strong>स्त्रियों को उच्च शिक्षा</strong> प्राप्त होती थी। कई <strong>विदुषी नारियाँ</strong> ऋग्वेद के मंत्रों की रचयिता थीं, जैसे - <i>विश्ववारा, घोषा, अपाला, लोपामुद्रा, सिकता, इंद्राणी</i> आदि। कुछ स्त्रियाँ <strong>युद्धकला</strong> में भी निपुण थीं। उस समय <strong>पर्दा प्रथा</strong> या <strong>सती प्रथा</strong> जैसी <i>कुरीतियाँ</i> नहीं थीं, जिससे <strong>स्त्री जाति का विकास</strong> कुंठित नहीं होता था। उन्हें समाज में <strong>सम्मान</strong> प्राप्त था और वे <i>स्वतंत्रता पूर्वक</i> अपने विचार रख सकती थीं।</p>\r\n\r\n<h2>विवाह प्रथा</h2>\r\n<p>वैदिक काल में <strong>विवाह एक धार्मिक संस्कार</strong> था। कन्या का विवाह उसकी <i>परिपक्वता</i> के बाद, उपयुक्त वर से होता था। वर और कन्या <i>एक-दूसरे को पसंद</i> करते थे और अभिभावकों की सहमति ली जाती थी। <strong>विवाह संस्कार</strong> कन्या के माता-पिता के घर होते थे। <strong>कन्या का मूल्य</strong> नहीं लिया जाता था, परंतु वर को <i>उपहार</i> दिए जाते थे।</p>\r\n\r\n<p>साधारण जन <strong>एक पत्नी से विवाह</strong> करते थे, जबकि धनी और राजपरिवारों में <i>बहुपत्नी प्रथा</i> प्रचलित थी। बहुपत्नी जीवन को <i>सुखद नहीं</i> माना जाता था। <strong>विधवा विवाह</strong> और <strong>अंतरजातीय विवाह</strong> निषिद्ध थे। भाई-बहन जैसे <i>निकट संबंधियों</i> में विवाह नहीं होते थे। <strong>अनैतिक यौन संबंधों</strong> के उदाहरण नहीं मिलते हैं।</p>\r\n\r\n<h2>मनोरंजन</h2>\r\n<p><strong>आर्यों का सामाजिक जीवन</strong> <i>शुष्क नहीं</i> था, बल्कि वे <strong>जीवन को आनंदपूर्वक</strong> जीने में विश्वास रखते थे। <strong>मनोरंजन</strong> के लिए <i>घुड़दौड़, संगीत, नृत्य, द्युतक्रीड़ा, शिकार</i>, तथा अन्य खेलों का आयोजन होता था। युवक-युवतियाँ <strong>त्योहारों</strong> पर खुलकर भाग लेते थे।</p>\r\n\r\n<p><strong>द्युतक्रीड़ा</strong> का <i>वेदों में वर्णन</i> मिलता है, साथ ही इसकी <strong>निंदा</strong> भी की गई है। जुए में कभी-कभी व्यक्ति अपनी पत्नी तक को <i>दाँव</i> पर लगा देते थे। <strong>संगीत एवं नृत्य</strong> का उन्हें विशेष प्रेम था। वे <i>वीणा, करताल</i>, और अन्य वाद्ययंत्रों का प्रयोग करते थे। स्त्री और पुरुष दोनों ही <strong>गान एवं नृत्य</strong> में भाग लेते थे।</p>\r\n\r\n<h2>वस्त्र एवं आभूषण</h2>\r\n<p><strong>आर्य लोग</strong> <i>सूती, ऊनी तथा रेशमी वस्त्र</i> पहनते थे। पुरुष प्रायः <strong>अधोवस्त्र (धोती), उत्तरीय (ओढ़नी), अत्रेयी (शॉल)</strong> धारण करते थे। स्त्रियाँ <i>चोली एवं साड़ी</i> पहनती थीं। <strong>वस्त्रों</strong> पर <i>सोने-चाँदी की कढ़ाई</i> की जाती थी।</p>\r\n\r\n<p>स्त्रियाँ और पुरुष दोनों <strong>आभूषण</strong> पहनते थे। आभूषणों में <i>कर्णफूल, कंगन, कड़े, हार, गजरे</i> आदि लोकप्रिय थे। स्त्रियाँ <i>बालों में तेल लगाकर</i> उन्हें सजाती थीं और विभिन्न <strong>अलंकरणों</strong> से सुसज्जित रहती थीं। पुरुष <strong>दाढ़ी-मूँछ</strong> रखते थे और उन्हें सँवारते थे।</p>\r\n\r\n<h2>खान-पान</h2>\r\n<p>आर्यों की <strong>आजीविका</strong> का मुख्य साधन <i>पशुपालन और कृषि</i> था। भोजन में <strong>शाकाहारी पदार्थ</strong> जैसे <i>अन्न, सब्जियाँ, दूध, दही, घी, फल</i> आदि सम्मिलित थे। कभी-कभी <i>विशेष अवसरों</i> पर <strong>मांसाहार</strong> भी किया जाता था।</p>\r\n\r\n<p><strong>गाय</strong> को वेदों में \"<i>अघन्या</i>\" (ना मारने योग्य) कहा गया है, परंतु <strong>यज्ञों और अतिथि सत्कार</strong> के अवसर पर मांस परोसने की परंपरा थी। <strong>सोमरस</strong> और <strong>सुरा</strong> जैसे पेय भी प्रचलित थे। सोमरस को <i>धार्मिक अवसरों</i> पर पिया जाता था और <strong>देवताओं को अर्पित</strong> किया जाता था। सुरा का सेवन <i>विलासी व्यक्तियों</i> द्वारा किया जाता था और इसकी <strong>निंदा</strong> भी की गई है।</p>\r\n\r\n<h2>नैतिक जीवन</h2>\r\n<p>वैदिक काल में <strong>नैतिक जीवन</strong> <i>उच्च स्तर</i> का था। <strong>सत्य भाषण, अतिथि सत्कार, संयमित जीवन, और धर्माचरण</strong> को <i>सर्वोत्तम गुण</i> माना जाता था। <strong>चोरी, डकैती</strong>, और <strong>यौन अपराध</strong> लगभग <i>नगण्य</i> थे। <strong>क्रोध, जुआ और सुरापान</strong> को <i>पाप की श्रेणी</i> में रखा गया था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार <strong>वैदिक कालीन समाज</strong> एक <i>स्वस्थ, संतुलित, और सुसंस्कृत समाज</i> था। उसमें <strong>स्त्रियों को सम्मान</strong> प्राप्त था, <strong>परिवार संयुक्त</strong> थे और समाज में <strong>नैतिकता</strong> का उच्च स्थान था। लोग <i>मनोरंजन, धर्म, शिक्षा, आभूषण, वस्त्र, खान-पान</i>, सब में संतुलन रखते थे। उनका जीवन <strong>संयमित, अनुशासित और उच्च आदर्शों</strong> पर आधारित था।</p>\r\n',5,'2025-05-30 02:48:04','2025-05-30 05:23:05','','Publish',0,'open',27,100),('शैव धर्म की उत्पत्ति और विकास पर निबंध','shaivism',2,'<p><strong>शैव धर्म</strong> भगवान शिव और उनके अवतारों की पूजा करने वालों का धर्म है। इस धर्म के अनुयायी <i>शैव</i> कहलाते हैं। शैव धर्म भारतीय संस्कृति और धार्मिक परंपरा का एक महत्वपूर्ण हिस्सा है, जो बहुत प्राचीन और विविधतापूर्ण है। शैव धर्म में भगवान शिव की पूजा के विभिन्न तरीके और उपास्य विधियाँ हैं। शैव धर्म में कई उपसंप्रदाय जैसे <i>शाक्त, नाथ, दशनामी, नाग</i> आदि होते हैं, जिनमें प्रत्येक का अपना एक विशिष्ट तरीका होता है भगवान शिव की पूजा का। शैव धर्म की पूजा विधियों में <i>तंत्र, मंत्र, ध्यान, योग</i>, और अन्य विधियाँ शामिल हैं, लेकिन सबसे प्रमुख यह माना जाता है कि शिव की पूजा <strong>सरल और सात्विक विधियों</strong> से की जानी चाहिए।</p>\r\n\r\n<h2>शैव धर्म के प्रमुख सिद्धांत</h2>\r\n\r\n<h3 class=\"atech\">भगवान शिव की उपासना</h3>\r\n<p>शैव धर्म में भगवान शिव की पूजा मुख्य आधार है। शिव को अनेक नामों से पुकारा जाता है, जैसे <i>महादेव, भोलेनाथ, शंकर, रुद्र</i>, आदि। भगवान शिव का मुख्य मंत्र \"<strong>ॐ नमः शिवाय</strong>\" है, जो उनकी महिमा का बखान करता है। शैव धर्म के अनुयायी भगवान शिव की पूजा <i>ध्यान, मंत्र जाप, योग, और षोडशोपचार पूजन</i> जैसे सात्विक विधियों से करते हैं।</p>\r\n\r\n<h3 class=\"atech\">पाशुपत संप्रदाय</h3>\r\n<p><i>पाशुपत संप्रदाय</i>, जो शैव धर्म का एक प्रमुख संप्रदाय है, तंत्र विद्या और साधना पर आधारित है। पाशुपत संप्रदाय के अनुयायी भगवान शिव के 18 अवतारों में से एक अवतार <strong>लकुलीश</strong> को मानते हैं। यह संप्रदाय अपने अनुयायियों से सात्विक विधियों को अपनाने का आग्रह करता है और तामसिक क्रियाओं जैसे <i>शराब पीने और मांस खाने</i> से दूर रहने की सलाह देता है।</p>\r\n\r\n<h3 class=\"atech\">शिवलिंग पूजा का इतिहास</h3>\r\n<p><strong>शिवलिंग</strong> की पूजा का उल्लेख सबसे पहले <i>हड़प्पा संस्कृति</i> में मिलता है, और इसे बाद में भारत के विभिन्न हिस्सों में प्रचलित किया गया। शिवलिंग की पूजा का विस्तार विशेष रूप से <i>मत्स्यपुराण</i> और <i>महाभारत</i> के अनुशासन पर्व में किया गया है।</p>\r\n\r\n<h3 class=\"atech\">शैव धर्म के सिद्धांत और पूजा विधि</h3>\r\n<p>शैव धर्म का मुख्य सिद्धांत <strong>एकेश्वरवाद</strong> है, जिसका अर्थ है कि भगवान शिव सर्वोच्च ब्रह्म हैं। इसके अनुसार, शिव ही <i>सृष्टि के सृजनकर्ता, पालनकर्ता और संहारक</i> हैं। शैव धर्म में <strong>ध्यान और योग</strong> का विशेष महत्व है। साधक <i>ध्यान और साधना</i> के माध्यम से भगवान शिव के साथ एकात्मता का अनुभव करने का प्रयास करते हैं। पूजा विधियों में <i>मंत्र जाप, रुद्राक्ष माला का प्रयोग, शिवलिंग की पूजा</i>, और <strong>भभूति का तिलक</strong> लगाना शामिल है।</p>\r\n\r\n<h2>शैव धर्म की पूजा विधि और संस्कार</h2>\r\n<p>शैव धर्म के अनुयायी अपनी पूजा में कई महत्वपूर्ण <i>संस्कार और विधियाँ</i> अपनाते हैं।</p>\r\n\r\n<h3 class=\"atech\">शिवलिंग पूजा</h3>\r\n<p><strong>शिवलिंग की पूजा</strong> शैव धर्म में अत्यधिक महत्वपूर्ण मानी जाती है। इसे स्नान कराके, <i>शुद्ध जल, दूध, और बेल पत्र</i> अर्पित करके पूजा जाता है।</p>\r\n\r\n<h3 class=\"atech\">ध्यान और योग</h3>\r\n<p>शैव धर्म के अनुयायी <strong>ध्यान और योग</strong> के माध्यम से आत्मा की शुद्धि और भगवान शिव से मिलन की कोशिश करते हैं। ध्यान के माध्यम से साधक अपने मन को शांति प्रदान करता है और <i>ईश्वर के निकटता</i> का अनुभव करता है।</p>\r\n\r\n<h3 class=\"atech\">सांस्कृतिक परंपराएँ</h3>\r\n<p>शैव धर्म में <strong>संन्यासियों</strong> को <i>जटा रखने</i> और <i>चोटी न रखने</i> की परंपरा है। वे <i>भगवा या सफेद वस्त्र</i> पहनते हैं और शिवलिंग के साथ-साथ अन्य देवी-देवताओं की पूजा करते हैं। शैव संप्रदाय के अनुयायी <strong>रुद्राक्ष माला</strong> का प्रयोग करते हैं और <strong>भभूति का तिलक</strong> लगाते हैं।</p>\r\n\r\n<h3 class=\"atech\">साधू और साधक</h3>\r\n<p>शैव धर्म में <i>साधू, योगी, अवधूत, सिद्ध, नाथ</i> आदि विशेष रूप से <i>पूजा और ध्यान</i> के माध्यम से आत्मज्ञान प्राप्त करने के प्रयास करते हैं। वे परंपरागत रूप से अपनी साधना को पूरा करने के लिए <i>दूरदर्शन और भव्य समारोहों</i> से बचते हैं।</p>\r\n\r\n<h2>शैव धर्म के प्रमुख तीर्थ</h2>\r\n<p>शैव धर्म में कई पवित्र <strong>तीर्थ स्थल</strong> हैं, जो भगवान शिव के अनुयायियों के लिए अत्यधिक महत्वपूर्ण माने जाते हैं। कुछ प्रमुख शैव तीर्थ स्थलों में शामिल हैं - <strong>बनारस (काशी)</strong> - यह तीर्थ स्थल भगवान शिव का प्रमुख निवास स्थल माना जाता है। <strong>केदारनाथ</strong> - यह तीर्थ स्थल उत्तराखंड में स्थित है और यहां भगवान शिव के <i>विश्व प्रसिद्ध मंदिर</i> का निर्माण किया गया है। <strong>सोमनाथ</strong> - यह गुजरात में स्थित है और यह भगवान शिव के प्रमुख <i>ज्योतिर्लिंगों</i> में से एक है। <strong>रामेश्वरम</strong> - यह स्थान तमिलनाडु में स्थित है और यहां भगवान शिव के प्रमुख मंदिर हैं। <strong>अमरनाथ</strong> - जम्मू कश्मीर में स्थित यह <i>गुफा मंदिर</i> भगवान शिव के एक महत्वपूर्ण तीर्थ स्थल के रूप में जाना जाता है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>शैव धर्म</strong> भारतीय संस्कृति का एक अति महत्वपूर्ण अंग है, और इसके अनुयायी भगवान शिव की पूजा के माध्यम से <i>आत्मज्ञान</i> प्राप्त करने की कोशिश करते हैं। इसमें विभिन्न <i>संप्रदायों, पूजा विधियों, और परंपराओं</i> का समावेश है, लेकिन इसका मूल उद्देश्य <strong>शिव की भक्ति और आत्मा की मुक्ति</strong> है। शैव धर्म ने भारतीय समाज और संस्कृति में महत्वपूर्ण योगदान दिया है, और इसकी पूजा विधियाँ आज भी <strong>लाखों लोगों</strong> द्वारा पालन की जाती हैं।</p>\r\n',3,'2025-05-30 07:23:45','2025-05-30 07:33:59','','Publish',0,'open',19,101),('सूफीवाद और इसके सिद्धांत क्या है','sufism-and-its-principles',2,'<p><strong>\"सूफीवाद\"</strong> <i>इस्लाम धर्म के एक धार्मिक और रहनुमा आंदोलन</i> को कहा जाता है, जो विशेष रूप से <strong>आत्मा की शुद्धि</strong>, <strong>भगवान के साथ व्यक्तिगत संबंध</strong>, और <strong>साधना के माध्यम से आत्मज्ञान प्राप्त</strong> करने पर केंद्रित है। सूफीवाद, इस्लाम के भीतर एक आध्यात्मिक धारा के रूप में विकसित हुआ, जिसमें इस्लाम के धार्मिक सिद्धांतों के साथ एक <i>गहरी व्यक्तिगत अनुभव और भक्ति</i> की ओर अग्रसर होने का प्रयास किया जाता है।</p>\r\n\r\n<p><strong>\'सूफी\'</strong> शब्द संभवतः अरबी के <i>\'सूफ\'</i> शब्द से लिया गया है जिसका अर्थ है <i>\'वह जो ऊन से बने कपड़े पहनता है\'</i>। इसका एक कारण यह है कि ऊनी कपड़ों को आमतौर पर फकीरों से जोड़कर देखा जाता था। इस शब्द का एक अन्य संभावित मूल <i>\'सफा\'</i> है जिसका अरबी में अर्थ <strong>\'शुद्धता\'</strong> है।</p>\r\n\r\n<p>सूफीवाद की उत्पत्ति <strong>8वीं और 9वीं सदी</strong> में मानी जाती है। यह आंदोलन इस्लाम के <strong>पैगंबर मुहम्मद (सल्ल.)</strong> के समय से ही अस्तित्व में था, लेकिन यह <strong>10वीं सदी में एक व्यवस्थित रूप</strong> में सामने आया। सूफीवाद का मुख्य उद्देश्य था <strong>\"आत्मिक शांति\"</strong> प्राप्त करना और <strong>ईश्वर के निकट जाने</strong> के लिए एक साधना पद्धति को अपनाना। यह आंदोलन प्रायः इस्लाम के शारीरिक और बाहरी धार्मिक कर्तव्यों से अलग होकर <i>आत्मा की शुद्धि और आंतरिक रूप से ईश्वर से मिलन</i> के लिए समर्पित था।</p>\r\n\r\n<p>भारत में सूफीवाद का आगमन <strong>12वीं सदी</strong> में हुआ। सूफी संतों ने भारतीय समाज में अपनी भक्ति और साधना के माध्यम से <strong>एकता और भाईचारे का संदेश</strong> दिया। भारत में सूफी संतों का योगदान बहुत महत्वपूर्ण था, और उनका प्रभाव आज भी <i>भारतीय संस्कृति</i> में महसूस किया जाता है। भारत में प्रमुख सूफी केंद्र <strong>अजमेर, दिल्ली, लखनऊ, और हैदराबाद</strong> में स्थित हैं, जहां हजारों भक्त सूफी संतों की <i>दरगाहों पर जाकर पूजा अर्चना</i> करते हैं।</p>\r\n\r\n<p>सूफीवाद में <strong>संगीत और काव्य</strong> का अत्यधिक महत्व है। सूफी संतों ने अपनी भक्ति का इज़हार <strong>संगीत के माध्यम से</strong> किया, और यह एक <i>आध्यात्मिक साधना</i> के रूप में उभरा। <strong>\"कव्वाली\"</strong> सूफी संगीत का एक महत्वपूर्ण रूप है, जो आज भी व्यापक रूप से प्रचलित है। सूफी संतों का यह मानना था कि <strong>संगीत के माध्यम से आत्मा को शांति</strong> मिलती है और वह <strong>ईश्वर के निकट</strong> पहुँचती है।</p>\r\n\r\n<h2>सूफीवाद के मुख्य सिद्धांत</h2>\r\n<p>सूफीवाद में यह मान्यता है कि हर व्यक्ति का <strong>ईश्वर के साथ एक व्यक्तिगत संबंध</strong> होता है। यह संबंध किसी धार्मिक या सामाजिक नियमों से नहीं, बल्कि <strong>आत्मिक साधना और भक्ति</strong> से उत्पन्न होता है। <strong>ईश्वर के साथ प्रेम और एकता</strong> की भावना सूफी भक्ति का केंद्रीय तत्व है।</p>\r\n\r\n<p>सूफीवाद में <strong>ध्यान, काव्य, संगीत</strong>, और <strong>मौन साधना</strong> जैसी विधियाँ शामिल हैं। सूफी संतों ने अक्सर अपनी भक्ति के जरिए <strong>ईश्वर के साथ आत्मीयता</strong> महसूस करने का प्रयास किया। यह साधना <i>ईश्वर की उपासना में गहरी डूबने</i> और <strong>अंतर्दृष्टि प्राप्त</strong> करने का तरीका है।</p>\r\n\r\n<p><strong>तसल्ली</strong> का अर्थ है <i>\"ईश्वर का साक्षात्कार\"</i> और <strong>तुहिद</strong> का अर्थ है <i>\"ईश्वर की एकता का अनुभव\"</i>। सूफी यह मानते हैं कि आत्मा को ईश्वर से मिलन के लिए <strong>तसल्ली की अवस्था</strong> तक पहुँचने की आवश्यकता है।</p>\r\n\r\n<p>सूफीवाद में <strong>प्रेम</strong> एक केंद्रीय सिद्धांत है, जिसे <i>\"इश्क\"</i> कहा जाता है। सूफी संतों के लिए, <strong>ईश्वर के प्रति प्रेम</strong> एक ऐसी भावना है, जो आत्मा को शुद्ध करती है और <strong>ईश्वर के साथ एकता</strong> की ओर अग्रसर करती है। सूफी कवि जैसे <strong>रूमी</strong> और <strong>हाफिज़</strong> ने अपनी कविताओं में <i>प्रेम और ईश्वर के प्रति समर्पण</i> की गहरी भावनाओं को व्यक्त किया।</p>\r\n\r\n<p>सूफीवाद का एक अन्य महत्वपूर्ण पहलू <strong>समाधि और शांति की खोज</strong> है। सूफी संतों का यह मानना था कि जब एक व्यक्ति <strong>अपनी आत्मा को शुद्ध</strong> करता है, तो उसे <strong>ईश्वर के साथ साक्षात्कार</strong> होता है, जो उसे <strong>शांति और संतोष</strong> की अवस्था में ले जाता है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>सूफीवाद एक <strong>आध्यात्मिक और भक्ति पर आधारित आंदोलन</strong> है, जिसका उद्देश्य <strong>आत्मा की शुद्धि</strong> और <strong>ईश्वर के साथ एकता प्राप्त</strong> करना है। यह आंदोलन अपनी <strong>साधना विधियों, भक्ति गीतों</strong>, और <strong>ध्यान</strong> के माध्यम से मानवता को <strong>शांति, प्रेम और एकता</strong> का संदेश देता है। सूफीवाद न केवल <i>इस्लाम धर्म के भीतर</i>, बल्कि पूरी दुनिया में एक <strong>गहरी आध्यात्मिक धारा</strong> के रूप में माना जाता है, जो समाज में <strong>सामंजस्य और सहिष्णुता</strong> को बढ़ावा देता है।</p>\r\n',4,'2025-05-30 07:23:45','2025-05-30 07:40:00','','Publish',0,'open',11,102),('हड़प्पा सभ्यता का सामाजिक जीवन पर प्रकाश डालें।','social-life-of-harappan-civilization',2,'<p><i>हड़प्पा सभ्यता की सामाजिक व्यवस्था</i> के विषय में हमें <strong>लिखित सामग्री की अनुपस्थिति</strong> के कारण स्पष्ट जानकारी नहीं मिल पाती, लेकिन <strong>पुरातात्विक खुदाई</strong> से प्राप्त अवशेषों और वस्तुओं के आधार पर उनके <i>सामाजिक जीवन की झलक</i> अवश्य मिलती है।</p>\r\n<p>संभवत: हड़प्पा समाज में <strong>उच्च, मध्यम और निम्न</strong> तीनों वर्गों के लोग रहते थे। नगरों में मुख्यतः <i>मध्यम वर्ग</i> के लोग बसते थे। परिवार उस समय की <strong>सामाजिक इकाई</strong> का केंद्र था, और ऐसा प्रतीत होता है कि समाज <i>मातृसत्तात्मक</i> था। खुदाई में मिले नगर निर्माण और सामाजिक संस्थाओं से यह संकेत मिलता है कि समाज में <strong>विभिन्न व्यवसायों</strong> से जुड़े लोग रहते थे — जैसे <i>पुरोहित, शासकीय कर्मचारी, व्यापारी, रंगरेज़, बढ़ई, सुनार, लोहार, कुम्हार, कृषक, बुनकर</i> आदि।</p>\r\n\r\n<h2>शासन प्रणाली</h2>\r\n<p>हड़प्पा की शासन प्रणाली के विषय में <i>निश्चित रूप से</i> कुछ कह पाना कठिन है। कुछ विद्वानों का मानना है कि <strong>प्रतिनिधियों की एक सभा</strong> शासन चलाती थी, जबकि कुछ इसे <i>लोकतांत्रिक प्रणाली</i> मानते हैं। अन्य विद्वान इसे <strong>पुरोहित प्रधान</strong> या <i>विकेंद्रीकृत शासन प्रणाली</i> मानते हैं। <strong>मोहनजोदड़ो</strong> और <strong>हड़प्पा</strong> जैसे नगरों में प्रशासन संभवतः एक <i>संगठित नगर पालिका प्रणाली</i> के अंतर्गत चलता था, जिसे नगर शासन का पूर्ण अधिकार प्राप्त था। यह शासन व्यवस्था <strong>विकेंद्रीकरण</strong> पर आधारित थी और संभवतः सत्ता किसी एक राजा के हाथ में केंद्रित नहीं थी।</p>\r\n\r\n<h2>भोजन एवं खान-पान</h2>\r\n<p>खुदाई में मिले अवशेषों के आधार पर यह अनुमान लगाया गया है कि लोग <strong>अनाज, फल, मांस, अंडे, मछली, दूध</strong> आदि का सेवन करते थे। वे <i>गाय, सूअर, बकरी, मुर्गा, कछुए</i> आदि के मांस का प्रयोग करते थे। <strong>मछली</strong> भोजन का एक प्रमुख हिस्सा थी। <i>खजूर और नारियल</i> जैसे फल भी खाए जाते थे। मिट्टी और धातु के बर्तनों की विविधता से यह स्पष्ट होता है कि हड़प्पावासी <strong>पेय-पदार्थों और पकवानों की विविधता</strong> से परिचित थे।</p>\r\n\r\n<h2>वस्त्र एवं आभूषण</h2>\r\n<p>हड़प्पा सभ्यता के लोगों के <strong>वस्त्र साधारण</strong> होते थे। पुरुष और स्त्रियों के वस्त्रों में अधिक अंतर नहीं था। आमतौर पर वे <i>अधोवस्त्र</i> (जैसे धोती या साड़ी) और <i>उत्तरीय</i> (जैसे चादर या ओढ़नी) पहनते थे, जिससे <strong>उनका दाहिना हाथ स्वतंत्र</strong> रहता था। सिर पर एक विशेष प्रकार का परिधान भी पहना जाता था, जो <i>पंखे के आकार</i> का पीछे की ओर मुड़ा होता था। पुरुष <strong>दाढ़ी और मूंछ</strong> रखते थे जबकि स्त्रियां <i>विभिन्न प्रकार की केश-सज्जा</i> करती थीं।</p>\r\n<p><strong>श्रृंगार</strong> में स्त्री और पुरुष दोनों ही रुचि रखते थे। वे <i>काजल, इत्र, दर्पण</i> आदि का प्रयोग करते थे। खुदाई में <strong>हाथीदांत की कंघी, दर्पण, श्रृंगार पात्र</strong> मिले हैं। <strong>आभूषणों</strong> का भी प्रचलन व्यापक था। स्त्री और पुरुष दोनों <i>हार, कंगन, बाजूबंद, कर्णफूल, नथ, पायल</i> आदि पहनते थे। आभूषण <strong>सोने, चांदी, तांबे, हाथीदांत</strong> और विभिन्न पत्थरों जैसे <i>पन्ना, मूंगा</i> आदि से बनाए जाते थे। साधारण वर्ग के लोग <strong>मिट्टी और हड्डी</strong> के आभूषण पहनते थे।</p>\r\n\r\n<h2>मनोरंजन एवं खेल</h2>\r\n<p>हड़प्पा सभ्यता में <strong>मनोरंजन के लिए अनेक साधन</strong> थे। लोग <i>शिकार, जुआ, पासा, नृत्य और संगीत</i> का आनंद लेते थे। कुछ मुद्राओं पर <strong>धनुषधारी शिकारी</strong> और <i>पशु-पक्षियों की लड़ाई</i> के दृश्य अंकित हैं। मिट्टी, पत्थर और हाथीदांत से बने <i>पासा और खिलौने</i> मिले हैं। बच्चों के मनोरंजन के लिए मिट्टी की <strong>बैलगाड़ियाँ, कुर्सियाँ, पशु-पक्षियों की मूर्तियाँ, सीटी</strong> आदि मिलती हैं। धातु से बने खिलौने भी पाए गए हैं, जिनसे <i>बच्चों के मनोरंजन में उनकी रुचि</i> का पता चलता है।</p>\r\n<p>खुदाई में प्राप्त <strong>नृत्य करती मूर्तियाँ</strong> इस बात का प्रमाण हैं कि <i>संगीत और नृत्य</i> समाज में लोकप्रिय थे। विभिन्न <i>उत्सवों और धार्मिक अनुष्ठानों</i> में लोग <strong>उल्लास से भाग</strong> लेते थे।</p>\r\n\r\n<h2>सामाजिक विशेषताएँ</h2>\r\n<p>सामाजिक दृष्टि से हड़प्पा सभ्यता एक <strong>शांतिपूर्ण, समृद्ध और संगठित समाज</strong> प्रतीत होता है। <i>युद्ध और हिंसा</i> के प्रमाण बहुत कम हैं — <strong>हथियारों के अवशेष</strong> नहीं मिलते, जिससे अनुमान होता है कि यह समाज <i>युद्धप्रिय नहीं</i> था। उनकी सामाजिक संस्थाएं <strong>सुव्यवस्थित</strong> थीं और समाज का मुख्य उद्देश्य <strong>सुख और शांति</strong> की स्थिति बनाए रखना था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>हड़प्पा सभ्यता का <strong>सामाजिक जीवन</strong> काफी <i>उन्नत, शांतिपूर्ण और समृद्ध</i> था। <strong>रीति-रिवाज, खान-पान, वस्त्र-आभूषण, प्रशासन</strong>, और <strong>मनोरंजन</strong> के साधनों में एक <i>परिष्कृत और संतुलित जीवनशैली</i> दिखाई देती है। हालाँकि <strong>लिखित सामग्री के अभाव</strong> में हमें सम्पूर्ण जानकारी नहीं मिल पाती, लेकिन <strong>पुरातात्विक अवशेषों</strong> के आधार पर हम इस सभ्यता की <i>सामाजिक संरचना</i> का एक स्पष्ट चित्र अवश्य खींच सकते हैं।</p>\r\n',7,'2025-05-30 07:23:45','2025-05-30 07:48:43','','Publish',0,'open',19,103),('आपातकाल (1975-1977) - एक ऐतिहासिक समीक्षा','emergency',2,'<p><strong>भारत के स्वतंत्रता के पश्चात लोकतंत्र को सबसे बड़ी चुनौती</strong> <i>26 जून 1975</i> को मिली, जब तत्कालीन प्रधानमंत्री <strong>श्रीमती इंदिरा गांधी</strong> ने राष्ट्रपति <strong>फखरुद्दीन अली अहमद</strong> से <strong>संविधान की धारा 352</strong> के अंतर्गत देश में <strong>आंतरिक आपातकाल</strong> की घोषणा करवाई। यह आपातकाल <strong>21 मार्च 1977</strong> तक लागू रहा और भारतीय लोकतंत्र के इतिहास का एक <strong>अत्यंत विवादास्पद</strong> तथा <strong>अंधकारमय काल</strong> रहा।</p>\r\n\r\n<p><strong>1971</strong> में इंदिरा गांधी की सरकार भारी बहुमत से सत्ता में आई थी। इस काल में उन्होंने कई <i>प्रगतिशील नीतियाँ</i> लागू कीं, परंतु उनका शासकीय दृष्टिकोण धीरे-धीरे <strong>अधिनायकवादी</strong> बनता गया। इसी क्रम में 1971 में \'<strong>मेंटेनेंस ऑफ इंटरनल सिक्योरिटी एक्ट</strong>\' (<i>MISA</i>) पारित किया गया, जिसके अंतर्गत पुलिस और प्रशासन को <strong>मनमाने अधिकार</strong> दिए गए। इस कानून का <strong>दुरुपयोग</strong> कर विपक्षी नेताओं और असंतुष्टों को बिना कारण <strong>बंदी</strong> बनाया जाने लगा।</p>\r\n\r\n<h2>इलाहाबाद हाईकोर्ट का फैसला और संकट की शुरुआत</h2>\r\n<p><strong>1975</strong> में इलाहाबाद हाईकोर्ट ने एक <i>ऐतिहासिक फैसले</i> में इंदिरा गांधी को चुनाव में <strong>सरकारी संसाधनों के दुरुपयोग</strong> और <strong>भ्रष्ट तरीकों</strong> से मतदाताओं को प्रभावित करने का दोषी ठहराया। इसके तहत <strong>उनकी लोकसभा सदस्यता रद्द</strong> कर दी गई और <strong>छह वर्षों तक कोई भी सरकारी पद ग्रहण करने पर रोक</strong> लगा दी गई।<br>हालांकि इंदिरा गांधी ने इस फैसले को मानने से इनकार करते हुए <i>सर्वोच्च न्यायालय</i> में अपील की। इस निर्णय के बाद देश की राजनीति में <strong>असंतोष</strong> और <strong>उथल-पुथल</strong> की स्थिति बन गई।</p>\r\n\r\n<p><strong>जेपी (जयप्रकाश नारायण)</strong> ने इंदिरा गांधी के <strong>इस्तीफे</strong> की मांग की और लोकतांत्रिक मूल्यों की पुनः स्थापना हेतु <strong>आंदोलन शुरू</strong> किया। <i>5 जून 1975</i> को पटना के गांधी मैदान में उन्होंने <strong>संपूर्ण क्रांति</strong> का आह्वान किया। इस क्रांति में <i>भ्रष्टाचार मिटाने, बेरोजगारी दूर करने, शिक्षा सुधार</i>, सामाजिक और राजनीतिक व्यवस्था के <strong>पुनर्गठन</strong> की बात कही गई। जेपी ने कहा – \"<strong>यह संपूर्ण व्यवस्था बदलनी चाहिए। केवल सरकार नहीं, बल्कि सोच, प्रणाली, संस्कृति – सबकुछ बदलना होगा।</strong>\"</p>\r\n\r\n<h2>आपातकाल की घोषणा और दमनचक्र</h2>\r\n<p><i>25 जून 1975</i> की रात, इंदिरा गांधी ने राष्ट्रपति को <strong>आंतरिक संकट</strong> का हवाला देते हुए आपातकाल लागू करने की सिफारिश की, जिसे <strong>तात्कालिक रूप से स्वीकार</strong> कर लिया गया। <i>26 जून</i> को आकाशवाणी पर अपने संदेश में इंदिरा गांधी ने कहा कि <strong>उनके खिलाफ साजिशें</strong> रची जा रही हैं, और देश को स्थिरता के लिए आपातकाल आवश्यक है।</p>\r\n\r\n<p><strong>26 जून 1975</strong> को इंदिरा गांधी ने आपातकाल की घोषणा की। इसके तुरंत बाद <strong>जयप्रकाश नारायण, अटल बिहारी वाजपेयी, जॉर्ज फर्नांडिस</strong> समेत <strong>हजारों विपक्षी नेताओं</strong> को <strong>जेल में डाल</strong> दिया गया। <strong>प्रेस पर सेंसरशिप</strong> लगा दी गई, <strong>न्यायपालिका</strong> को नियंत्रित किया गया, <strong>नागरिक अधिकारों</strong> को निलंबित कर दिया गया और <strong>चुनाव स्थगित</strong> कर दिए गए।</p>\r\n\r\n<h2>आपातकाल के दौरान उठाए गए कदम</h2>\r\n<h3 class=\"atech\">विरोधियों की गिरफ्तारी</h3>\r\n<p><i>जयप्रकाश नारायण, अटल बिहारी वाजपेयी, जॉर्ज फर्नांडिस</i> समेत हजारों विपक्षी नेता गिरफ्तार हुए।</p>\r\n\r\n<h3 class=\"atech\">प्रेस पर सेंसरशिप</h3>\r\n<p>सभी <strong>अखबारों पर कड़ी निगरानी</strong> रखी गई। सरकार की अनुमति के बिना <i>कुछ भी प्रकाशित नहीं</i> किया जा सकता था।</p>\r\n\r\n<h3 class=\"atech\">नागरिक अधिकारों का निलंबन</h3>\r\n<p>संविधान के <strong>अनुच्छेद 14, 19 और 21</strong> को स्थगित कर दिया गया। <i>Habeas Corpus</i> जैसे <strong>अधिकार समाप्त</strong> हो गए।</p>\r\n\r\n<h3 class=\"atech\">नसबंदी अभियान</h3>\r\n<p><strong>संजय गांधी</strong> के नेतृत्व में <strong>जबरन नसबंदी</strong> कराई गई। इसका <i>व्यापक विरोध</i> हुआ।</p>\r\n\r\n<h3 class=\"atech\">न्यायपालिका पर दबाव</h3>\r\n<p><strong>सुप्रीम कोर्ट</strong> ने <i>ADM जबलपुर केस</i> में कहा कि <strong>आपातकाल</strong> के दौरान <strong>नागरिकों के पास कोई मौलिक अधिकार</strong> नहीं हैं।</p>\r\n\r\n<h2>आपातकाल का विरोध और जन-असंतोष</h2>\r\n<p>देश भर में <strong>आपातकाल का विरोध</strong> जारी रहा। भले ही उसे <i>कुचलने के प्रयास</i> हुए, लेकिन <strong>जन-असंतोष</strong> दबाया नहीं जा सका। <i>भूमिगत आंदोलन</i> चले, <i>साहित्यकारों और बुद्धिजीवियों</i> ने इसका विरोध किया। <strong>1977</strong> आते-आते यह विरोध <strong>तीव्र</strong> हो गया, और इंदिरा गांधी ने <strong>चुनाव कराने की घोषणा</strong> की।</p>\r\n\r\n<h2>1977 का आम चुनाव और परिणाम</h2>\r\n<p><strong>मार्च 1977</strong> में हुए आम चुनाव में <strong>कांग्रेस की ऐतिहासिक हार</strong> हुई</p>\r\n<ul>\r\n    <li><p><strong>इंदिरा गांधी रायबरेली से चुनाव हार गईं।</strong></p></li>\r\n    <li><p>कांग्रेस की सीटें <strong>350 से घटकर मात्र 153</strong> रह गईं।</p></li>\r\n    <li><p><strong>जनता पार्टी ने भारी बहुमत</strong> से सरकार बनाई और <strong>मोरारजी देसाई</strong> प्रधानमंत्री बने।</p></li>\r\n    <li><p>यह पहली बार था जब <strong>केंद्र में गैर-कांग्रेसी सरकार</strong> बनी।</p></li>\r\n</ul>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>भारत में 1975 से 1977 तक लगा आपातकाल</strong> स्वतंत्र भारत के इतिहास का एक <strong>काला अध्याय</strong> था। यह घटना बताती है कि लोकतंत्र को केवल <strong>संविधान</strong> से नहीं, बल्कि <strong>जनता की सजगता, संस्थाओं की स्वतंत्रता</strong> और <strong>नेताओं की नैतिकता</strong> से सुरक्षित रखा जा सकता है।</p>\r\n<p>आपातकाल ने यह भी दिखा दिया कि यदि <strong>लोकतंत्र खतरे</strong> में पड़ता है, तो <strong>भारत की जनता</strong> उस पर <strong>प्रतिक्रिया देने में देर नहीं करती</strong>। <strong>1977 के आम चुनाव</strong> ने यह प्रमाणित कर दिया कि <strong>भारतीय लोकतंत्र की जड़ें</strong> कितनी गहरी हैं।</p>\r\n<p>यह अनुभव आज भी <strong>भारतीय लोकतंत्र को मजबूत बनाए रखने</strong> के लिए एक <strong>चेतावनी</strong> और <strong>प्रेरणा का स्रोत</strong> बना हुआ है।</p>\r\n',2,'2025-05-31 04:26:23','2025-05-31 04:32:42','','Publish',0,'open',19,104),('आर्थिक सुधार आंदोलन - भारत में 1990 के दशक की दिशा और प्रभाव','economic-reform-movement',2,'<p><strong>भारत ने 15 अगस्त 1947 को स्वतंत्रता प्राप्त की</strong>, लेकिन उसके बाद की आर्थिक संरचना <i>समाजवादी सोच</i> से प्रेरित रही। सरकारी नियंत्रण, योजना आधारित विकास और सार्वजनिक क्षेत्र पर आधारित अर्थव्यवस्था ने कुछ क्षेत्रों में सफलता पाई, लेकिन 1980 के दशक के अंत तक यह ढांचा थकने लगा था। <strong>1991 में भारत को गहरे आर्थिक संकट का सामना करना पड़ा</strong> और यहीं से शुरू हुआ <strong>भारत में आर्थिक सुधार आंदोलन</strong>, जिसने न केवल भारत की अर्थव्यवस्था को नया जीवन दिया बल्कि उसे <i>वैश्विक अर्थव्यवस्था</i> से जोड़ भी दिया।</p>\r\n\r\n<p>इस आंदोलन के तहत <strong>उदारीकरण</strong>, <strong>निजीकरण</strong> और <strong>भूमंडलीकरण</strong> को भारतीय अर्थव्यवस्था का <i>अभिन्न अंग</i> स्वीकार किया गया। इसके मुख्य उद्देश्य थे – <i>अर्थव्यवस्था की गतिविधियों से अनावश्यक प्रतिबंधों और नियमन को हटाना</i>, <i>व्यापार की स्वतंत्रता को बढ़ावा देना</i> और <i>वैश्विक अर्थव्यवस्था के साथ भारतीय अर्थव्यवस्था का एकीकरण</i>।</p>\r\n\r\n<h2>पारंपरिक आर्थिक नीतियाँ और समस्याएँ</h2>\r\n<p>1990 के दशक से पहले, भारत की आर्थिक नीति में <strong>सार्वजनिक क्षेत्र का बोलबाला</strong> था। सरकार सुनिश्चित करती थी कि सभी आर्थिक क्षेत्र <i>पंचवर्षीय योजनाओं</i> के लक्ष्यों के अनुसार कार्य करें, जिसके लिए निजी उद्योगों और विदेश व्यापार पर कड़े नियंत्रण लागू किए गए थे। <strong>सरकारी उपक्रमों को बढ़ावा</strong> दिया गया, जबकि <i>निजी क्षेत्र को सीमित</i> रखा गया। इन नीतियों के परिणामस्वरूप <strong>न तो तेज़ आर्थिक विकास हुआ</strong> और <strong>न ही रोजगार सृजन में कोई उल्लेखनीय वृद्धि</strong> हो सकी।</p>\r\n\r\n<p><strong>1980 के दशक</strong> में भारत का <i>राजकोषीय घाटा</i> लगातार बढ़ रहा था। <strong>आयात अधिक और निर्यात कम</strong> था, जिससे <i>विदेशी मुद्रा भंडार</i> तेजी से घट रहा था। <strong>1990-91 में यह संकट इतना गहरा</strong> हो गया कि भारत के पास केवल <strong>दो सप्ताह का आयात करने लायक विदेशी मुद्रा</strong> बची थी। देश के सामने तीन प्रमुख समस्याएं थीं–</p>\r\n<ul>\r\n    <li><p><strong>भुगतान संतुलन का संकट</strong></p></li>\r\n    <li><p><strong>राजकोषीय घाटा</strong></p></li>\r\n    <li><p><strong>महँगाई और मंदी</strong></p></li>\r\n</ul>\r\n<p>इसी समय, <strong>खाड़ी युद्ध (1990-91)</strong> ने <i>तेल की कीमतों को बढ़ा दिया</i>, जिससे संकट और गहरा गया। <strong>IMF</strong> और <strong>World Bank</strong> से मदद लेने के लिए भारत को <i>आर्थिक सुधारों को अपनाना</i> पड़ा।</p>\r\n\r\n<h2>सुधारों की शुरुआत और उद्देश्य</h2>\r\n<p><strong>1991 में, डॉ. मनमोहन सिंह</strong> को वित्त मंत्री नियुक्त किया गया और प्रधानमंत्री <strong>पी.वी. नरसिंह राव</strong> के नेतृत्व में <i>नई आर्थिक नीति (New Economic Policy)</i> लागू की गई। इस नीति के <strong>तीन मुख्य स्तंभ</strong> थे–</p>\r\n\r\n<h3 class=\"atech\">उदारीकरण</h3>\r\n<p>इस नीति के तहत <strong>सरकारी नियंत्रण को घटाते हुए</strong> उद्योगों को अधिक स्वतंत्रता दी गई। <i>व्यापारिक गतिविधियों पर से प्रतिबंध हटाए गए</i>, <i>लाइसेंस व्यवस्था समाप्त</i> की गई और <strong>निजी निवेश को बढ़ावा</strong> दिया गया।</p>\r\n\r\n<h3 class=\"atech\">निजीकरण</h3>\r\n<p><strong>सार्वजनिक क्षेत्र के उपक्रमों को निजी हाथों में सौंपने</strong> या उनमें निजी निवेश को अनुमति देने की प्रक्रिया शुरू की गई। इसका उद्देश्य था <i>सरकारी कंपनियों की कार्यकुशलता में सुधार</i> और <i>घाटे में चल रहे उपक्रमों का पुनर्गठन</i>।</p>\r\n\r\n<h3 class=\"atech\">वैश्वीकरण</h3>\r\n<p>इस नीति के तहत <strong>भारत की अर्थव्यवस्था को वैश्विक अर्थव्यवस्था के साथ जोड़ा</strong> गया। <i>विदेश व्यापार और निवेश के रास्ते खोल दिए गए</i>, जिससे <strong>भारतीय कंपनियों को वैश्विक प्रतिस्पर्धा</strong> का सामना करना पड़ा।</p>\r\n\r\n<p>इनका संक्षिप्त रूप <strong>‘एल.पी.जी. (LPG)’</strong> है। इन नीतियों का मुख्य उद्देश्य था–</p>\r\n<ul>\r\n    <li><p><strong>सरकारी नियंत्रण को कम करना</strong></p></li>\r\n    <li><p><strong>निजी क्षेत्र को बढ़ावा देना</strong></p></li>\r\n    <li><p><strong>भारत को विश्व अर्थव्यवस्था से जोड़ना</strong></p></li>\r\n</ul>\r\n\r\n<h2>आर्थिक सुधारों के प्रभाव</h2>\r\n<p>आर्थिक सुधारों से भारतीय अर्थव्यवस्था पर कई <strong>सकारात्मक और नकारात्मक प्रभाव</strong> पड़े हैं। इन सुधारों ने <i>विकास दर में वृद्धि</i>, <i>विदेशी निवेश को आकर्षित</i> किया, और <i>रोजगार सृजन</i> में योगदान दिया। हालांकि, <i>असमानता, शहरी-ग्रामीण विभाजन</i>, और <i>क्षेत्रीय विकास</i> की समस्याएँ भी उभरीं।</p>\r\n\r\n<h3>सकारात्मक प्रभाव</h3>\r\n<p>आर्थिक सुधारों ने भारत की <strong>आर्थिक विकास दर में उल्लेखनीय वृद्धि</strong> की है। <strong>1991 के बाद से</strong>, <i>जीडीपी में लगातार वृद्धि</i> हुई है, और भारत अब दुनिया की <strong>सबसे तेजी से बढ़ती अर्थव्यवस्थाओं</strong> में से एक है।</p>\r\n\r\n<h4 class=\"atech\">विदेशी निवेश</h4>\r\n<p><i>उदारीकरण के कारण</i> प्रत्यक्ष विदेशी निवेश (एफडीआई) बढ़ा, जिससे <strong>नए क्षेत्रों का विकास</strong> हुआ और <strong>बुनियादी ढांचे में सुधार</strong> हुआ।</p>\r\n\r\n<h4 class=\"atech\">रोजगार सृजन</h4>\r\n<p><strong>निजीकरण और बाजार में वृद्धि</strong> से <i>रोजगार के नए अवसर</i> पैदा हुए, खासकर <i>आईटी, दूरसंचार और ऑटोमोबाइल उद्योगों</i> में।</p>\r\n\r\n<h4 class=\"atech\">तकनीकी उन्नति</h4>\r\n<p><strong>वैश्वीकरण ने उन्नत तकनीक लाई</strong>, जिससे <i>विनिर्माण और दूरसंचार</i> जैसे विभिन्न क्षेत्रों में <strong>उत्पादकता और नवाचार</strong> में वृद्धि हुई।</p>\r\n\r\n<h4 class=\"atech\">कृषि क्षेत्र में</h4>\r\n<p>आर्थिक सुधारों से <i>कृषि क्षेत्र में निवेश</i>, <i>आधुनिकीकरण</i> और <i>फसलों के विविधीकरण</i> में वृद्धि हुई है, जिससे <strong>किसानों और उपभोक्ताओं दोनों को लाभ</strong> हुआ है।</p>\r\n\r\n<h3>नकारात्मक प्रभाव</h3>\r\n\r\n<h4 class=\"atech\">बढ़ती असमानता</h4>\r\n<p>आर्थिक सुधारों ने <i>आय और संसाधनों के वितरण में असमानता</i> बढ़ाई है, जिससे <strong>शहरी और ग्रामीण क्षेत्रों के बीच का अंतर</strong> बढ़ा है।</p>\r\n\r\n<h4 class=\"atech\">शहरी-ग्रामीण विभाजन</h4>\r\n<p>आर्थिक सुधारों के कारण <strong>शहरी क्षेत्रों में विकास तेजी से हुआ</strong> है, जबकि <i>ग्रामीण क्षेत्र अभी भी पीछे हैं</i>, जिससे <strong>शहरी-ग्रामीण विभाजन</strong> बढ़ा है।</p>\r\n\r\n<h4 class=\"atech\">क्षेत्रीय विकास</h4>\r\n<p>आर्थिक सुधारों से <i>कुछ क्षेत्रों में विकास तेजी</i> से हुआ है, जबकि <strong>अन्य क्षेत्र विकास में पीछे</strong> रह गए हैं, जिससे <strong>क्षेत्रीय विकास की समस्या</strong> बढ़ी है।</p>\r\n\r\n<h4 class=\"atech\">सार्वजनिक क्षेत्र में गिरावट</h4>\r\n<p>आर्थिक सुधारों के तहत, <i>सार्वजनिक क्षेत्र के बुनियादी ढांचे में निवेश कम</i> हुआ है, जिससे <strong>शिक्षा, स्वास्थ्य सेवा और अन्य आवश्यक सेवाओं की गुणवत्ता</strong> में गिरावट आई है।</p>\r\n\r\n<h4 class=\"atech\">रोजगार की गुणवत्ता में गिरावट</h4>\r\n<p>आर्थिक सुधारों के बाद <strong>संगठित क्षेत्र में रोजगार की वृद्धि धीमी</strong> रही है, जिससे <i>अनौपचारिक क्षेत्र में रोजगार</i> में वृद्धि हुई है, जो कि <strong>कम वेतन और खराब कार्य स्थितियों</strong> के साथ जुड़ा हुआ है।</p>\r\n\r\n<h4 class=\"atech\">राजकोषीय घाटा</h4>\r\n<p>आर्थिक सुधारों के बाद भी <i>राजकोषीय घाटे को कम करने</i> में सरकार सफल नहीं हुई है, जिससे <strong>देश का वित्तीय स्वास्थ्य प्रभावित</strong> हुआ है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>1991 के आर्थिक सुधार आंदोलन</strong> ने <strong>भारतीय अर्थव्यवस्था को नई गति दी</strong>। इससे <i>देश की जीडीपी बढ़ी</i>, <i>वैश्विक मंच पर प्रतिष्ठा मिली</i> और <i>जीवन स्तर में सुधार</i> आया। लेकिन इसके कुछ दुष्प्रभाव भी रहे जैसे <strong>कृषि की उपेक्षा, असमान विकास, उपभोक्तावाद</strong> और <i>सांस्कृतिक बदलाव</i>। इस प्रकार यह आंदोलन <strong>मिश्रित फलदायक</strong> रहा—जिसने एक ओर <strong>भारत को वैश्विक अर्थव्यवस्था से जोड़ा</strong>, वहीं दूसरी ओर <strong>सामाजिक संरचना एवं समावेशी विकास पर प्रश्नचिह्न</strong> भी खड़े किए।</p>\r\n',5,'2025-05-31 04:26:23','2025-05-31 04:40:50','','Publish',0,'open',35,105),('इंदिरा गांधी और भारत-पाकिस्तान युद्ध कारण और परिणाम','indira-gandhi-and-india-pakistan-war-reasons-and-results',2,'<p><strong>भारत-पाकिस्तान युद्ध</strong>, विशेषकर <strong>1971 का युद्ध</strong>, भारतीय उपमहाद्वीप के इतिहास में एक <i>निर्णायक घटना</i> है। यह केवल दो देशों के बीच एक पारंपरिक युद्ध नहीं था, बल्कि इसमें <strong>मानवाधिकार</strong>, <strong>क्षेत्रीय राजनीति</strong>, <strong>राष्ट्रीय सुरक्षा</strong> और <strong>शरणार्थी संकट</strong> जैसे अनेक पहलुओं का समावेश था। इस युद्ध में भारत की तत्कालीन प्रधानमंत्री <strong>इंदिरा गांधी</strong> की भूमिका अत्यंत निर्णायक रही। उन्होंने <i>दूरदृष्टि, कूटनीति और नेतृत्व क्षमता</i> का अद्वितीय उदाहरण प्रस्तुत किया, जिसने न केवल युद्ध को भारत की विजय में बदला, बल्कि एक नए राष्ट्र—<strong>बांग्लादेश</strong>—का उदय भी सुनिश्चित किया।</p>\r\n\r\n<h2>भारत-पाकिस्तान युद्ध के कारण</h2>\r\n<h3 class=\"atech\">ऑपरेशन सर्चलाइट</h3>\r\n<p>25 मार्च 1971 को पाकिस्तानी सेना ने ऑपरेशन सर्चलाइट चलाया, जिसमें पूर्वी पाकिस्तान में बंगाली जनता, बुद्धिजीवियों, छात्रों और महिलाओं पर <strong>भीषण दमन</strong> हुआ। लाखों लोग मारे गए और बलात्कार, हत्या व उत्पीड़न की घटनाएँ हुईं।</p>\r\n\r\n<h3 class=\"atech\">भारत में शरणार्थियों की बाढ़</h3>\r\n<p>इस दमन के चलते लगभग <strong>1 करोड़ बंगाली शरणार्थी</strong> भारत के सीमावर्ती राज्यों – पश्चिम बंगाल, त्रिपुरा, असम और बिहार – में आ गए। इससे भारत पर <strong>आर्थिक, सामाजिक और प्रशासनिक दबाव</strong> पड़ा। शरणार्थियों की देखभाल के लिए संसाधनों की कमी और स्थानीय असंतोष ने <strong>इंदिरा गांधी सरकार</strong> को कार्रवाई के लिए विवश कर दिया।</p>\r\n\r\n<h3 class=\"atech\">राजनीतिक और कूटनीतिक प्रयासों की विफलता</h3>\r\n<p><strong>इंदिरा गांधी</strong> ने अंतरराष्ट्रीय समुदाय, विशेषकर अमेरिका, ब्रिटेन और संयुक्त राष्ट्र से अपील की कि वे पाकिस्तान पर दबाव डालें ताकि वह पूर्वी पाकिस्तान में दमन बंद करे। लेकिन अमेरिका की <i>निक्सन सरकार</i> पाकिस्तान के तानाशाह याह्या खान की पक्षधर थी और चीन भी पाकिस्तान के साथ खड़ा था। जब अंतरराष्ट्रीय स्तर पर न्याय नहीं मिला, तो भारत को <strong>सैन्य विकल्प</strong> अपनाना पड़ा।</p>\r\n\r\n<h3 class=\"atech\">पाकिस्तान द्वारा भारत पर हमला</h3>\r\n<p>3 दिसंबर 1971 को पाकिस्तान ने पश्चिमी सीमा पर भारत के 11 एयरबेस पर <strong>हवाई हमला</strong> कर दिया। यह भारत के लिए <i>सीधा युद्ध घोषित करने</i> जैसा था। इसके जवाब में भारत ने पाकिस्तान के खिलाफ युद्ध की औपचारिक घोषणा की, जिससे <strong>13 दिन का निर्णायक युद्ध</strong> शुरू हुआ।</p>\r\n\r\n<h2>इंदिरा गांधी की भूमिका</h2>\r\n<p><strong>इंदिरा गांधी</strong> ने पहले से ही वैश्विक स्तर पर इस संकट की ओर ध्यान आकर्षित करने की कोशिश की थी। उन्होंने अमेरिका, ब्रिटेन, फ्रांस और रूस जैसे प्रमुख देशों की यात्रा की और पूर्वी पाकिस्तान में हो रहे अत्याचारों की जानकारी दी।</p>\r\n<p>1971 में भारत ने सोवियत संघ के साथ <strong>20-वर्षीय मैत्री संधि</strong> पर हस्ताक्षर किए, जिससे भारत को एक महाशक्ति का रणनीतिक समर्थन मिला। इससे अमेरिका और चीन जैसे राष्ट्र पाकिस्तान के खुले समर्थन से पीछे हटे।</p>\r\n<p><strong>इंदिरा गांधी</strong> के नेतृत्व में भारत सरकार ने शरणार्थियों के पुनर्वास, भोजन और सुरक्षा की जिम्मेदारी ली, जबकि अंतरराष्ट्रीय मंचों पर पाकिस्तान के खिलाफ सशक्त मामला भी प्रस्तुत किया।</p>\r\n<p>प्रधानमंत्री ने सेना प्रमुख <strong>जनरल मानेकशॉ</strong> को युद्ध की रणनीति और समय निर्धारण की स्वतंत्रता दी। इससे सैन्य संचालन कुशल और प्रभावी तरीके से हुआ।</p>\r\n\r\n<h2>युद्ध के परिणाम</h2>\r\n<p><strong>1971 का भारत-पाकिस्तान युद्ध</strong> दक्षिण एशिया के इतिहास का एक निर्णायक मोड़ साबित हुआ। यह युद्ध केवल सैन्य विजय नहीं था, बल्कि इसके दूरगामी राजनीतिक, सामाजिक, कूटनीतिक और भूगोलिक परिणाम हुए। इस युद्ध ने न केवल दक्षिण एशिया की राजनीतिक संरचना को बदल दिया, बल्कि भारत की वैश्विक छवि को भी नई ऊंचाइयों तक पहुंचाया।</p>\r\n\r\n<h3 class=\"atech\">बांग्लादेश का निर्माण</h3>\r\n<p>इस युद्ध का सबसे महत्वपूर्ण और ऐतिहासिक परिणाम <strong>बांग्लादेश का निर्माण</strong> था। 16 दिसंबर 1971 को पूर्वी पाकिस्तान की राजधानी ढाका में पाकिस्तानी सेना ने आत्मसमर्पण कर दिया, जिससे बांग्लादेश एक स्वतंत्र राष्ट्र बना। <i>यह पहली बार था जब किसी युद्ध के फलस्वरूप एक नया राष्ट्र अस्तित्व में आया।</i> बांग्लादेश के लोगों को अपनी भाषा, संस्कृति और पहचान के अनुसार जीने का अधिकार मिला।</p>\r\n\r\n<h3 class=\"atech\">पाकिस्तानी सेना का ऐतिहासिक आत्मसमर्पण</h3>\r\n<p>इस युद्ध में पाकिस्तान के <strong>93,000 से अधिक सैनिकों</strong> ने भारतीय सेना के सामने आत्मसमर्पण किया, जो विश्व इतिहास में सबसे बड़ा सैन्य आत्मसमर्पणों में से एक माना जाता है। 16 दिसंबर 1971 को भारतीय लेफ्टिनेंट जनरल <strong>जगजीत सिंह अरोड़ा</strong> के समक्ष पाकिस्तानी लेफ्टिनेंट जनरल <strong>आमिर अब्दुल्ला खान नियाज़ी</strong> ने आत्मसमर्पण किया। इसे <i>\"विजय दिवस\"</i> के रूप में हर वर्ष भारत और बांग्लादेश में मनाया जाता है।</p>\r\n\r\n<h3 class=\"atech\">भारत की वैश्विक छवि में उभार</h3>\r\n<p>इस युद्ध के बाद भारत की छवि एक मजबूत और निर्णायक राष्ट्र के रूप में उभरी। अमेरिका, चीन जैसे शक्तिशाली देशों के दबाव के बावजूद भारत ने अपने निर्णय पर दृढ़ता दिखाई। भारत ने बांग्लादेश को न केवल सैन्य सहायता दी, बल्कि युद्ध के बाद पुनर्निर्माण में भी सहयोग किया। संयुक्त राष्ट्र और अन्य वैश्विक मंचों पर भारत की भूमिका को गंभीरता से लिया जाने लगा।</p>\r\n\r\n<h3 class=\"atech\">शिमला समझौता</h3>\r\n<p>युद्ध के बाद जुलाई 1972 में भारत और पाकिस्तान के बीच <strong>शिमला समझौता</strong> हुआ। इस समझौते में तय हुआ कि दोनों देश आपसी विवादों को शांतिपूर्ण तरीकों से सुलझाएंगे। <strong>कश्मीर मुद्दे</strong> को द्विपक्षीय बातचीत से सुलझाने की बात पर सहमति बनी। भारत ने युद्ध में पकड़े गए <strong>93,000 पाकिस्तानी सैनिकों</strong> को पाकिस्तान को लौटा दिया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>1971 का भारत-पाकिस्तान युद्ध</strong> केवल सैन्य संघर्ष नहीं था, बल्कि यह भारतीय नेतृत्व, कूटनीति, मानवीय मूल्यों और क्षेत्रीय स्थिरता का एक उत्कृष्ट उदाहरण बन गया। <strong>इंदिरा गांधी</strong> की भूमिका इस पूरे युद्ध में अत्यंत निर्णायक और ऐतिहासिक रही। उन्होंने राष्ट्रीय हितों की रक्षा करते हुए अंतरराष्ट्रीय मंचों पर भारत की प्रतिष्ठा को नई ऊँचाई तक पहुँचाया। इस युद्ध ने यह भी सिद्ध कर दिया कि <i>लोकतंत्र, मानवाधिकार और आत्मनिर्णय के सिद्धांत</i> केवल भाषणों तक सीमित नहीं रहते, बल्कि आवश्यकता पड़ने पर उनके लिए निर्णायक कदम भी उठाए जा सकते हैं।</p>\r\n',4,'2025-05-31 04:26:23','2025-05-31 04:52:49','','Publish',0,'open',35,106),('इंदिरा गांधी और भारत-पाकिस्तान युद्ध, 1971 - एक विश्लेषण','indira-gandhi-and-india-pakistan-war-1971',2,'<p><strong>इंदिरा गांधी</strong> का प्रधानमंत्रित्व काल भारतीय आधुनिक इतिहास में अत्यंत महत्वपूर्ण माना जाता है। जब इंदिरा गांधी भारत की प्रधानमंत्री बनीं, तब विश्व राजनीति <i>शीत युद्ध</i> के प्रभाव में थी, और अमेरिका तथा सोवियत संघ अपनी-अपनी महत्त्वाकांक्षाओं के कारण दुनिया को विभाजित कर रहे थे। ऐसे तनावपूर्ण वैश्विक वातावरण में इंदिरा गांधी ने भारत की बागडोर संभाली।</p> \r\n\r\n<p>यद्यपि इंदिरा गांधी <strong>गुटनिरपेक्ष आंदोलन</strong> की समर्थक थीं, किंतु उनका समय ऐसा नहीं था, जिसमें केवल आदर्शवाद से काम लिया जा सके। 1962 के भारत-चीन युद्ध में भारत की पराजय से उसकी अंतरराष्ट्रीय प्रतिष्ठा को गहरा आघात पहुँचा था। 1965 में पाकिस्तान पर विजय ने स्थिति कुछ सुधारी, लेकिन ताशकंद समझौते के बाद सब कुछ यथास्थिति में लौट गया। इस कारण भारत को कोई दीर्घकालिक लाभ नहीं हुआ।</p>\r\n\r\n<h2>अंतरराष्ट्रीय राजनीति में इंदिरा गांधी की यथार्थवादी नीति</h2>\r\n\r\n<p>अमेरिका और सोवियत संघ दोनों ही पाकिस्तान के पक्ष में झुके हुए थे। ऐसे में इंदिरा गांधी ने व्यवहारिक विदेश नीति अपनाई। भारत की पूंजी निवेश और खाद्यान्न आवश्यकताओं के मद्देनज़र उन्होंने मार्च 1966 में अमेरिका का दौरा किया। हालाँकि अमेरिका का रवैया अपेक्षा के अनुरूप नहीं था, फिर भी इंदिरा गांधी वहां से नई कृषि तकनीक तथा <strong>HYV बीज</strong> (<i>उच्च उत्पादक बीज</i>) लाने में सफल रहीं।</p>\r\n\r\n<p>भारत पर अमेरिका गुट में शामिल होने का दबाव था, लेकिन इंदिरा गांधी ने इसे अस्वीकार कर दिया और इसके विपरीत <strong>वियतनाम युद्ध</strong> में अमेरिका की नीति की खुली आलोचना की। इसके बाद उन्होंने सोवियत संघ से संबंध सुधारने की दिशा में कदम बढ़ाए।</p>\r\n\r\n<p>1968 में सोवियत संघ ने पाकिस्तान को सैन्य सहायता देने का वचन दे दिया। इंदिरा गांधी ने सार्वजनिक रूप से कुछ नहीं कहा, लेकिन 1969 में जब रूस और चीन के बीच सीमा पर तनाव बढ़ा, तब भारत ने तटस्थ रुख अपनाया। भारत के इस रुख का प्रभाव यह हुआ कि सोवियत संघ ने भारत को किसी भी विदेशी आक्रमण की स्थिति में सहायता का आश्वासन दे दिया। इसके परिणामस्वरूप अगस्त 1971 में <strong>भारत-सोवियत मैत्री संधि</strong> अस्तित्व में आई।</p>\r\n\r\n<p>इस संधि के विरोध में अमेरिका, पाकिस्तान और चीन आपस में और अधिक निकट हो गए।</p>\r\n\r\n<h2>1971 का भारत-पाकिस्तान युद्ध और इंदिरा गांधी की भूमिका</h2>\r\n\r\n<p>1971 में पूर्वी पाकिस्तान में उत्पन्न राजनीतिक-सैन्य संकट के कारण भारत-पाक युद्ध छिड़ गया। पाकिस्तान के गृहयुद्ध से भारत में शरणार्थियों की बाढ़ आ गई थी। भारत सरकार ने मानवीय आधार पर इन शरणार्थियों की सहायता की। साथ ही भारत ने पूर्वी पाकिस्तान की मुक्ति वाहिनी को अस्त्र, धन और प्रशिक्षण भी देना शुरू किया।</p>\r\n\r\n<p>3 दिसंबर 1971 को पाकिस्तान की वायुसेना ने भारत के पश्चिमी सीमावर्ती ठिकानों पर अचानक हमला किया। इसके बाद भारत के पास सैन्य हस्तक्षेप के अतिरिक्त कोई विकल्प नहीं बचा।</p>\r\n\r\n<p>यद्यपि इंदिरा गांधी ने कभी स्पष्ट रूप से पाकिस्तान के विभाजन की मंशा नहीं जताई, लेकिन परिस्थितियों के अनुसार उन्होंने आवश्यक निर्णय लिए। अमेरिका भारत के हस्तक्षेप की आलोचना कर रहा था और उसने बंगाल की खाड़ी में अपना युद्धपोत भेज दिया। लेकिन इसी दौरान सोवियत संघ ने भी भारत की सहायता के लिए अपनी पनडुब्बियाँ भेज दीं।</p>\r\n\r\n<p>सभी आर्थिक और मानवीय दबावों के बावजूद पाकिस्तान युद्ध करता रहा, लेकिन मात्र 13 दिनों के युद्ध के पश्चात 16 दिसंबर 1971 को पाकिस्तान की सेना ने आत्मसमर्पण कर दिया। इसके परिणामस्वरूप <strong>बांग्लादेश का जन्म</strong> हुआ।</p>\r\n\r\n<h2>बांग्लादेश का निर्माण और भारत की भूमिका</h2>\r\n\r\n<p>भारत ने युद्ध के बाद भी बांग्लादेश को मानवीय सहायता देना जारी रखा। 1974 में भारत ने बांग्लादेश के साथ \'<strong>बेरूबारी मुद्दे</strong>\' को सुलझाकर द्विपक्षीय संबंधों को मज़बूती प्रदान की। इस पूरे घटनाक्रम में भारत के रुख ने उसे दक्षिण एशिया में एक प्रमुख शक्ति के रूप में स्थापित कर दिया।</p>\r\n\r\n<p>हालाँकि, इस युद्ध के बाद अमेरिका के साथ भारत के संबंध बिगड़ गए, लेकिन इंदिरा गांधी ने स्वतंत्र विदेश नीति की राह नहीं छोड़ी।</p>\r\n\r\n<h2>विदेश नीति में स्वतंत्रता और आत्मनिर्भरता की झलक</h2>\r\n\r\n<p>1974 में इंदिरा गांधी ने भारत का पहला परमाणु परीक्षण करवाया, जिसे \'<i>स्माइलिंग बुद्धा</i>\' के नाम से जाना जाता है। इससे अमेरिका और उसके सहयोगी देशों ने भारत का बहिष्कार किया, लेकिन इंदिरा गांधी ने <strong>गुटनिरपेक्षता</strong> के सिद्धांत से विचलन नहीं किया।</p>\r\n\r\n<p>उनके कार्यकाल की विदेश नीति के अन्य उल्लेखनीय पहलू निम्नलिखित हैं:</p>\r\n\r\n<ul>\r\n    <li><p><strong>इंडोनेशिया</strong> और अन्य एशियाई देशों से संबंध सुधारना</p></li>\r\n    <li><p>चीन के साथ संबंधों को पुनः सामान्य करने का प्रयास</p></li>\r\n    <li><p>तीसरी दुनिया के देशों के साथ एकजुटता बनाए रखना</p></li>\r\n</ul>\r\n\r\n<h2>निष्कर्ष</h2>\r\n\r\n<p><strong>इंदिरा गांधी</strong> का कार्यकाल भारत की विदेश नीति के इतिहास में एक मील का पत्थर सिद्ध हुआ। उन्होंने भारत को दक्षिण एशिया की प्रमुख शक्ति के रूप में स्थापित किया। यद्यपि उनकी विदेश नीति पर यह आरोप लगाया जाता है कि वह गुटनिरपेक्षता से हटती दिखी, लेकिन सूक्ष्म अवलोकन करने पर स्पष्ट होता है कि उन्होंने गुटनिरपेक्षता के सिद्धांतों का व्यवहारिक रूप में पालन किया।</p>\r\n\r\n<ul>\r\n    <li><p>उन्होंने स्वतंत्रता का समर्थन किया – जैसे बांग्लादेश और वियतनाम के मामलों में।</p></li>\r\n    <li><p>उन्होंने किसी भी महाशक्ति के दबाव में आए बिना स्वतंत्र निर्णय लिए।</p></li>\r\n    <li><p>सोवियत संघ से मैत्री की, लेकिन देश के सम्मान और आत्मनिर्भरता से कभी समझौता नहीं किया।</p></li>\r\n</ul>\r\n\r\n<p>इस प्रकार यह कहा जा सकता है कि <strong>इंदिरा गांधी</strong> ने गुटनिरपेक्षता की नीति का व्यवहारिक और यथार्थपरक रूप में भारत के हितों के अनुसार प्रयोग किया।</p>',2,'2025-05-31 04:26:23','2025-05-31 05:01:10','','Publish',0,'open',19,107),('जनता पार्टी शासन (1977-1980) एक ऐतिहासिक राजनीतिक परिवर्तन','janata-party-rule-1977-1980-a-historical-political-change',2,'<p><strong>भारत के राजनीतिक इतिहास</strong> में जनता पार्टी का शासन (1977-1980) एक विशेष महत्व रखता है, क्योंकि यह पहला अवसर था जब केंद्र में कांग्रेस पार्टी की हार हुई और एक गठबंधन सरकार सत्ता में आई। यह शासन काल भारत के लोकतांत्रिक इतिहास में एक महत्वपूर्ण मोड़ साबित हुआ।</p> \r\n\r\n<p>जनता पार्टी की स्थापना 1977 में हुई थी। यह पार्टी उन सभी दलों और नेताओं को मिलाकर बनी थी जो <strong>इंदिरा गांधी</strong> द्वारा लगाए गए आपातकाल का विरोध कर रहे थे। 1975 में जब इंदिरा गांधी ने देश में आपातकाल लगाया, तब कई विपक्षी नेताओं को जेल में डाल दिया गया और आम लोगों के अधिकारों को छीन लिया गया।</p>\r\n\r\n<p>इस दौरान <strong>जयप्रकाश नारायण</strong> ने देश में भ्रष्टाचार और अन्य समस्याओं के खिलाफ \"<i>संपूर्ण क्रांति</i>\" आंदोलन शुरू किया। उन्होंने युवाओं और छात्रों से देश को बदलने की अपील की। 18 जनवरी 1977 को इंदिरा गांधी ने आपातकाल समाप्त कर मार्च 1977 में आम चुनाव कराने की घोषणा की, तब सभी विरोधी दल एक होकर जनता पार्टी नाम से एक नई पार्टी बना लिए।</p>\r\n\r\n<p>जनता पार्टी ने इंदिरा गांधी की कांग्रेस पार्टी के खिलाफ चुनाव लड़ा और बड़ी जीत हासिल की। पहली बार देश में कोई गैर-कांग्रेसी सरकार बनी और <strong>मोरारजी देसाई</strong> प्रधानमंत्री बने।</p>\r\n\r\n<p>1977 का आम चुनाव ऐतिहासिक बहुमत से जीत के बाद लोकतांत्रिक संस्थाओं को पुनः स्थापित किया गया। प्रेस की स्वतंत्रता बहाल की गई। भ्रष्टाचार विरोधी अभियान शुरू किया गया।</p>\r\n\r\n<p>परंतु यह सरकार अधिक समय तक नहीं टिक सकी। पार्टी के भीतर जनसंघ और अन्य घटकों के बीच वैचारिक मतभेद, <strong>राष्ट्रीय स्वयंसेवक संघ (RSS)</strong> की सदस्यता को लेकर विवाद, और नेताओं के बीच गुटबाजी ने पार्टी को कमजोर कर दिया। <strong>चौधरी चरण सिंह</strong> और मोरारजी देसाई के बीच मतभेद गहराए। <strong>नानाजी देशमुख</strong> और अन्य नेताओं ने RSS से संबंध रखने वालों पर आपत्ति जताई। अंततः 1979 में मोरारजी देसाई को इस्तीफा देना पड़ा और सरकार गिर गई। लोकसभा भंग कर दी गई और 1980 में पुनः चुनाव हुए।</p>\r\n\r\n<p>कांग्रेस ने भारी बहुमत से वापसी की। जनता पार्टी विभिन्न घटकों में टूट गई जैसे- <strong>भारतीय जनता पार्टी (BJP)</strong>, लोकदल, समाजवादी पार्टी। राजनीतिक अस्थिरता के कारण जनता का विश्वास समाप्त हो गया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n\r\n<p>जनता पार्टी ने पहली बार कांग्रेस की एकछत्र सत्ता को तोड़ा और देश में लोकतंत्र को मजबूत किया। लेकिन आपसी झगड़ों और विचारों की भिन्नता के कारण यह सरकार ज्यादा दिन नहीं चल सकी। इसके बावजूद यह एक ऐतिहासिक घटना थी, जिसने देश की राजनीति को नया रास्ता दिखाया।</p>\r\n',2,'2025-05-31 04:26:23','2025-05-31 05:09:35','','Publish',0,'open',19,108),('नेहरू की विदेश नीति पर प्रकाश डालें','nehrus-foreign-policy',2,'<p><strong>पंडित जवाहरलाल नेहरू</strong> भारत के पहले प्रधानमंत्री थे। आज़ादी के बाद जब भारत ने एक स्वतंत्र राष्ट्र के रूप में नई दिशा में कदम बढ़ाया, तब दुनिया के देश दो हिस्सों में बँट गए थे – एक तरफ <strong>अमेरिका</strong> का गुट और दूसरी तरफ <strong>रूस (सोवियत संघ)</strong> का गुट। उस समय नेहरू जी ने फैसला लिया कि भारत किसी भी गुट में शामिल नहीं होगा और अपनी स्वतंत्र विदेश नीति बनाएगा।</p>\r\n\r\n<h2>गुटनिरपेक्ष नीति</h2>\r\n<p>नेहरू जी चाहते थे कि भारत किसी भी बड़े देश का पिछलग्गू न बने। इसलिए उन्होंने कहा – \"<i>हम न अमेरिका के साथ हैं, न रूस के साथ, हम खुद अपनी सोच से काम करेंगे।</i>\" इस नीति को <strong>गुटनिरपेक्षता</strong> कहा गया। इसका मतलब – कोई गुट न चुनना। नेहरू जी ने कहा कि भारत उन देशों के साथ रहेगा जो <strong>शांति, विकास और एक-दूसरे के सम्मान</strong> में विश्वास रखते हैं।</p>\r\n\r\n<h2>पंचशील सिद्धांत</h2>\r\n<p><strong>पंचशील सिद्धांत</strong> पंडित जवाहरलाल नेहरू और चीन के प्रधानमंत्री चाऊ एन लाई के बीच 1954 में तय किए गए ऐसे पाँच मूलभूत सिद्धांत थे, जिनका उद्देश्य दो देशों के बीच <strong>शांतिपूर्ण सह-अस्तित्व</strong> को बढ़ावा देना था। इन सिद्धांतों को भारत-चीन समझौते में शामिल किया गया था, लेकिन बाद में इन्हें भारत की विदेश नीति का आधार बना दिया गया। ये पाँच सिद्धांत इस प्रकार हैं:</p>\r\n<ul>\r\n    <li><p><strong>एक-दूसरे की सीमा और आज़ादी का सम्मान करना।</strong></p></li>\r\n    <li><p><strong>एक-दूसरे पर आक्रमण न करना।</strong></p></li>\r\n    <li><p><strong>एक-दूसरे के आंतरिक मामलों में दखल न देना।</strong></p></li>\r\n    <li><p><strong>समानता और आपसी फायदा देख कर काम करना।</strong></p></li>\r\n    <li><p><strong>शांति से साथ रहना।</strong></p></li>\r\n</ul>\r\n\r\n<h2>उपनिवेशवाद और रंगभेद</h2>\r\n<p>नेहरू जी ने उन देशों की मदद की जो अंग्रेजों या दूसरे विदेशियों के राज में थे। उन्होंने कहा कि हर देश को आज़ाद होना चाहिए। इसके साथ ही, उन्होंने अफ्रीका में काले लोगों के साथ हो रहे भेदभाव (<i>रंगभेद</i>) का भी विरोध किया। उनका मानना था कि सभी लोगों को <strong>समान अधिकार</strong> मिलने चाहिए और किसी के साथ रंग, जाति या धर्म के आधार पर भेदभाव नहीं होना चाहिए।</p>\r\n\r\n<h2>पड़ोसी देशों से अच्छे रिश्ते</h2>\r\n<p><strong>पंडित नेहरू</strong> ने हमेशा पड़ोसी देशों के साथ अच्छे रिश्ते बनाने की कोशिश की। उनका मानना था कि <strong>शांतिपूर्ण सहयोग</strong> से ही क्षेत्रीय स्थिरता और विकास संभव है। उन्होंने <strong>पाकिस्तान, चीन, श्रीलंका, नेपाल और बांगलादेश</strong> के साथ अच्छे संबंध स्थापित करने का प्रयास किया। नेहरू जी ने क्षेत्रीय सहयोग बढ़ाने के लिए पहल की, जैसे सार्क का समर्थन, और हमेशा शांति और बातचीत के रास्ते पर चलने की कोशिश की।</p>\r\n\r\n<h2>भारत-चीन रिश्ते और 1962 का युद्ध</h2>\r\n<p>नेहरू जी ने शुरू में चीन से दोस्ती की और नारा दिया – \"<i>हिंदी चीनी भाई-भाई</i>\"। पर चीन ने अचानक भारत पर हमला कर दिया, जिससे नेहरू की नीति को गंभीर झटका लगा। लोगों ने कहा कि उन्होंने चीन पर बहुत भरोसा किया और भारत की सेना को मजबूत नहीं किया।</p>\r\n\r\n<h2>नेहरू की विदेश नीति की आलोचना</h2>\r\n<p>नेहरू की विदेश नीति की कुछ कमियाँ थीं - उन्होंने चीन पर बहुत भरोसा किया, जो गलत साबित हुआ। उन्होंने भारत की सेना को मजबूत नहीं किया, जिससे युद्ध में भारत को नुकसान हुआ। उनकी नीति को कई लोग <i>आदर्शवादी (Idealistic)</i> मानते हैं – यानी ज़्यादा अच्छे ख्यालों पर आधारित, पर असली दुनिया से थोड़ी दूर।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>नेहरू जी की विदेश नीति</strong> ने भारत को एक स्वतंत्र और शांतिप्रिय देश के रूप में दुनिया के सामने खड़ा किया। उन्होंने दिखाया कि भारत बिना किसी के दबाव में आए भी अपनी बात रख सकता है। हालांकि कुछ गलतियाँ हुईं, जैसे – चीन पर भरोसा करना और सेना को न मजबूत करना, लेकिन फिर भी उन्होंने एक मजबूत नींव रखी, जिस पर आगे चलकर भारत की विदेश नीति और मज़बूत हुई।</p>\r\n',3,'2025-05-31 04:26:23','2025-05-31 05:13:11','','Publish',0,'open',19,109),('भारत-पाकिस्तान संबंध - इतिहास और विवाद','india-pakistan-relations-history-and-disputes',2,'<p><strong>भारत और पाकिस्तान</strong>, जो एक ही सांस्कृतिक और ऐतिहासिक विरासत से जन्मे दो देश हैं, उनके संबंध विभाजन के समय से ही <strong>संघर्ष, तनाव और अविश्वास</strong> से भरे रहे हैं। 1947 में जब ब्रिटिश भारत का विभाजन हुआ, तब से लेकर आज तक दोनों देशों के बीच चार बड़े युद्ध हो चुके हैं, अनेक सीमावर्ती झड़पें, कूटनीतिक संकट, आतंकवादी घटनाएं और संवाद की कोशिशें होती रही हैं। यह संबंध एशिया ही नहीं, बल्कि वैश्विक राजनीति के लिए भी अत्यंत महत्वपूर्ण हैं।</p>\r\n\r\n<p>1947 का भारत-विभाजन, उपमहाद्वीप के इतिहास की सबसे दर्दनाक घटनाओं में से एक था। इस विभाजन के फलस्वरूप लाखों लोग विस्थापित हुए और अनुमानतः 10 लाख से अधिक लोगों की मृत्यु हो गई। विभाजन <i>धार्मिक आधार</i> पर हुआ, और इससे दोनों देशों के संबंधों की नींव ही <strong>दुश्मनी और अविश्वास</strong> पर पड़ गई। पाकिस्तान ने खुद को एक <strong>इस्लामिक गणराज्य</strong> के रूप में स्थापित किया जबकि भारत ने <i>धर्मनिरपेक्ष लोकतंत्र</i> को अपनाया।</p>\r\n\r\n<h2>विवाद और संघर्ष</h2>\r\n<p><strong>भारत-पाकिस्तान संबंधों</strong> में कश्मीर सबसे बड़ा और पुराना विवाद है। 1947 में जम्मू-कश्मीर के राजा हरि सिंह ने भारत के साथ विलय पत्र पर हस्ताक्षर किए, जिसके बाद यह राज्य भारत का हिस्सा बन गया। पाकिस्तान ने इसे मान्यता नहीं दी और इसी को लेकर पहला युद्ध (1947-48) हुआ। यह मुद्दा आज भी संयुक्त राष्ट्र समेत वैश्विक मंचों पर उठा रहा है। कश्मीर भारत के लिए एक अभिन्न हिस्सा है, जबकि पाकिस्तान उसे \"<i>अधिकार-छीन लिया गया मुस्लिम बहुल राज्य</i>\" मानता है।</p>\r\n<ul>\r\n    <li><p><strong>1947-48 युद्ध</strong> कश्मीर के मुद्दे पर हुआ, जो संयुक्त राष्ट्र की मध्यस्थता से संघर्षविराम में बदला।</p></li>\r\n    <li><p><strong>1965 युद्ध</strong> एक बार फिर कश्मीर को लेकर हुआ, जो ताशकंद समझौते (1966) में समाप्त हुआ।</p></li>\r\n    <li><p><strong>1971 युद्ध</strong> यह युद्ध बांग्लादेश की स्वतंत्रता को लेकर हुआ, जिसमें पाकिस्तान की हार हुई और भारत ने 90,000 से अधिक पाकिस्तानी सैनिकों को बंदी बना लिया।</p></li>\r\n    <li><p><strong>1999 करगिल युद्ध</strong> पाकिस्तान की सेना और घुसपैठियों ने करगिल की पहाड़ियों पर कब्ज़ा किया, जिसे भारत ने ऑपरेशन विजय के तहत वापस लिया।</p></li>\r\n</ul>\r\n\r\n<p>1980 के दशक से पाकिस्तान प्रायोजित आतंकवाद भारत के लिए सबसे बड़ा सुरक्षा संकट बन गया है। कश्मीर में आतंकी गतिविधियों से लेकर मुंबई हमलों (2008), संसद हमला (2001), पठानकोट (2016) और पुलवामा हमला (2019) तक कई बड़ी घटनाएं पाकिस्तान समर्थित आतंकी संगठनों जैसे <strong>लश्कर-ए-तैयबा, जैश-ए-मोहम्मद</strong> से जुड़ी रही हैं।</p>\r\n\r\n<h2>सिंधु जल संधि</h2>\r\n<p>ब्रिटिश शासनकाल में पंजाब में नहरों का निर्माण किया गया था। विभाजन के बाद पंजाब की तीन नदियाँ हैं- <strong>सतलुज, रावी, ब्यास</strong>। 1960 में भारत और पाकिस्तान के बीच विश्व बैंक की मध्यस्थता में सिंधु जल संधि हुई, जिसके अनुसार भारत तीन पूर्वी नदियों (सतलुज, रावी, ब्यास) का उपयोग कर सकता है जबकि पाकिस्तान को तीन पश्चिमी नदियां (सिंधु, झेलम, चिनाब) दी गईं। यह संधि अब तक कायम है, लेकिन हाल के वर्षों में इस पर भी सवाल उठने लगे हैं, खासकर जब भारत ने आतंकवाद के जवाब में \"<i>पानी और खून एक साथ नहीं बह सकते</i>\" जैसे बयान दिए।</p>\r\n\r\n<h2>समकालीन स्थिति और बदलाव</h2>\r\n<p>2019 में भारत सरकार ने जम्मू-कश्मीर को विशेष दर्जा देने वाला <strong>अनुच्छेद 370</strong> हटा दिया और उसे दो केंद्र शासित प्रदेशों में विभाजित कर दिया। पाकिस्तान ने इस कदम को अवैध बताया और भारत के साथ अपने राजनयिक संबंधों को न्यूनतम कर दिया। इसके बाद से दोनों देशों के बीच कोई औपचारिक वार्ता नहीं हुई है।</p>\r\n\r\n<h2>आतंकवाद और घुसपैठ</h2>\r\n<p>1990 के दशक में कश्मीर में आतंकवाद को पाकिस्तान द्वारा समर्थन मिलने के ठोस प्रमाण सामने आए। करगिल युद्ध (1999) और संसद पर हमला (2001) जैसी घटनाओं ने दोनों देशों के संबंधों को और बिगाड़ा।</p>\r\n<p>आतंकवाद को लेकर वैश्विक संस्था <strong>FATF</strong> ने पाकिस्तान को ‘ग्रे लिस्ट’ में रखा था, जिसके कारण उसकी आर्थिक स्थिति और अंतरराष्ट्रीय छवि पर बुरा असर पड़ा। भारत लगातार यह प्रयास करता रहा है कि पाकिस्तान को आतंकवाद के प्रति अपनी नीति बदलनी पड़े।</p>\r\n<p>भारत की पाकिस्तान के प्रति नीति में समय-समय पर बदलाव आया है। कभी \"<i>शांति और संवाद</i>\", तो कभी \"<strong>कड़ा सैन्य और कूटनीतिक उत्तर</strong>\"। मोदी सरकार के तहत भारत ने \"<strong>सर्जिकल स्ट्राइक</strong>\" (2016) और \"<strong>एयर स्ट्राइक</strong>\" (2019) जैसे जवाब दिए, जिससे स्पष्ट हुआ कि भारत अब आतंकवाद के प्रति \"<i>सहनशीलता</i>\" नहीं रखेगा।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>भारत और पाकिस्तान</strong> के बीच संबंधों का इतिहास <strong>संघर्ष, युद्ध और अविश्वास</strong> से भरा रहा है। लेकिन इसके साथ ही संवाद, समझौते और शांति की कोशिशें भी होती रही हैं। दोनों देशों के भविष्य का निर्धारण इस बात पर निर्भर करेगा कि वे अपने इतिहास से सीखकर एक नए और शांतिपूर्ण भविष्य की ओर बढ़ते हैं या नहीं। द्विपक्षीय समस्याओं का समाधान बातचीत और विश्वास से ही संभव है, न कि युद्ध और आतंक से। यदि दोनों देश समझदारी से काम लें, तो आने वाली पीढ़ियों के लिए <strong>शांति और विकास</strong> का मार्ग प्रशस्त किया जा सकता है।</p>\r\n',58,'2025-05-31 04:26:23','2025-05-31 05:18:07','','Publish',0,'open',35,110),(' मंडल कमीशन 1990 के दशक- राजनीतिक गतिविधियों एवं वी.पी. सिंह की भूमिका','mandal-commission-1990s-political-activities-and-vprole-of-lion',2,'<p><strong>1990 का दशक</strong> भारतीय राजनीति में सामाजिक न्याय की अवधारणा को लेकर महत्वपूर्ण मोड़ साबित हुआ। इसी दौर में <strong>मंडल कमीशन</strong> की रिपोर्ट को लागू करने की घोषणा हुई, जिसने पिछड़े वर्गों को सरकारी नौकरियों में <strong>27% आरक्षण</strong> देने की सिफारिश की थी। इस निर्णय ने देश की राजनीति, समाज और प्रशासन में गहरा प्रभाव डाला। इस घटनाक्रम में तत्कालीन प्रधानमंत्री <strong><i>विश्वनाथ प्रताप सिंह (वी.पी. सिंह)</i></strong> की भूमिका निर्णायक रही। मंडल आयोग की सिफारिशों के लागू होते ही भारतीय राजनीति में जबरदस्त उथल-पुथल मच गई, जो लंबे समय तक देश की राजनीति की दिशा तय करती रही।</p> <h2><strong>मंडल कमीशन क्या था?</strong></h2> <p>1979 में जनता पार्टी की सरकार ने एक आयोग बनाया जिसे \"<strong>मंडल आयोग</strong>\" कहा गया। इसके प्रधानमंत्री <strong><i>मोरारजी देसाई</i></strong> थे। आयोग के अध्यक्ष <strong><i>बिंदेश्वरी प्रसाद मंडल</i></strong> थे। इसका काम था यह पता लगाना कि भारत में कौन-कौन सी जातियाँ सामाजिक और शैक्षणिक रूप से पिछड़ी हैं।</p> <p><strong><i>बिंदेश्वरी प्रसाद मंडल</i></strong>, जो एक अनुभवी राजनेता और पूर्व केंद्रीय मंत्री रह चुके थे। आयोग का प्रमुख उद्देश्य था:</p> <ul> <li><p><strong>भारत में सामाजिक और शैक्षिक रूप से पिछड़े वर्गों (OBC)</strong> की पहचान करना।</p></li> <li><p><strong>उनके सामाजिक और आर्थिक उत्थान के लिए उपयुक्त उपाय सुझाना।</strong></p></li> </ul> <p>आयोग ने दो वर्षों की गहन पड़ताल के बाद 1980 में अपनी रिपोर्ट सरकार को सौंप दी। इस रिपोर्ट में यह बताया गया कि देश की कुल जनसंख्या में लगभग <strong>52%</strong> लोग सामाजिक और शैक्षणिक रूप से पिछड़े वर्गों से आते हैं, जिन्हें “<strong>अन्य पिछड़ा वर्ग (OBC)</strong>” कहा गया।</p> <h2><strong>वी.पी. सिंह की भूमिका</strong></h2> <p><strong><i>वी.पी. सिंह</i></strong> 1980 के दशक में एक ईमानदार और भ्रष्टाचार-विरोधी नेता के रूप में उभरे। उन्होंने बोफोर्स घोटाले के खिलाफ आवाज उठाई, जिससे उन्हें जनता का अपार समर्थन मिला। 1989 में जनता दल के नेतृत्व में विपक्षी दलों ने उन्हें प्रधानमंत्री बनाया। उनके प्रधानमंत्री बनने के बाद उन्होंने <strong>सामाजिक न्याय</strong> को अपनी प्राथमिकता बनाई।</p> <p>7 अगस्त 1990 को संसद में <strong><i>वी.पी. सिंह</i></strong> ने घोषणा की कि <strong>मंडल आयोग की रिपोर्ट लागू की जाएगी</strong>, और केंद्र सरकार की नौकरियों में अन्य पिछड़ा वर्ग (OBC) को <strong>27% आरक्षण</strong> दिया जाएगा।</p> <h2><strong>फैसले का देशभर में व्यापक असर</strong></h2> <p>मंडल आयोग की सिफारिशों के लागू होने के बाद पूरे देश में प्रतिक्रिया शुरू हो गई। जहां एक ओर पिछड़े वर्ग के लोगों में खुशी और उत्साह था, वहीं सवर्ण वर्ग में असंतोष और गुस्सा फैल गया। इस निर्णय ने देश को दो वर्गों में बाँट दिया – एक ओर वे लोग जो <strong>सामाजिक न्याय</strong> की बात कर रहे थे और दूसरी ओर वे लोग जो इसे योग्यता के खिलाफ मान रहे थे। खासकर, शहरी मध्यवर्गीय युवाओं में इस फैसले के प्रति विरोध की भावना देखी गई।</p> <h3><strong>छात्रों का व्यापक आंदोलन</strong></h3> <p>आरक्षण लागू होने के बाद छात्रों ने सड़कों पर उतरकर भारी विरोध प्रदर्शन किया। दिल्ली, लखनऊ, पटना, भोपाल, जयपुर आदि शहरों में हज़ारों छात्र विरोध रैलियों में शामिल हुए। इनमें से कई प्रदर्शन हिंसक भी हो गए। सबसे दर्दनाक घटना थी जब दिल्ली विश्वविद्यालय के छात्र <strong><i>राजीव गोस्वामी</i></strong> ने आत्मदाह करने की कोशिश की। यह घटना राष्ट्रीय स्तर पर प्रतीक बन गई और मीडिया ने इसे प्रमुखता से दिखाया। इसके बाद देश भर में कई छात्रों ने आत्मदाह की कोशिशें कीं, जिससे माहौल और तनावपूर्ण हो गया।</p> <h2><strong>राजनीतिक असंतुलन और वी.पी. सिंह की सरकार</strong></h2> <p><strong><i>वी.पी. सिंह</i></strong> की सरकार बाहरी समर्थन पर चल रही थी, जिसमें भारतीय जनता पार्टी (भाजपा) का भी समर्थन शामिल था। मंडल आयोग के फैसले से भाजपा असहज हो गई क्योंकि उसका मुख्य आधार वर्ग सवर्ण था जो इस निर्णय से नाराज़ था। इसी बीच भाजपा ने अयोध्या में राम मंदिर आंदोलन शुरू किया। <strong><i>लालकृष्ण आडवाणी</i></strong> ने रथ यात्रा की शुरुआत की और जब उन्हें बिहार में गिरफ्तार किया गया, तो भाजपा ने <strong><i>वी.पी. सिंह</i></strong> सरकार से समर्थन वापस ले लिया। इससे <strong><i>वी.पी. सिंह</i></strong> की सरकार गिर गई। उन्होंने सत्ता तो खो दी, लेकिन इतिहास में एक साहसी और सामाजिक न्याय समर्थक नेता के रूप में दर्ज हो गए।</p> <h2><strong>इंदिरा साहनी बनाम भारत सरकार मामला</strong></h2> <p>मंडल आयोग के फैसले को चुनौती देने के लिए सुप्रीम कोर्ट में याचिका दायर की गई, जिसे <strong>इंदिरा साहनी केस</strong> के नाम से जाना जाता है। इस केस में सर्वोच्च न्यायालय ने 1992 में फैसला दिया कि पिछड़े वर्गों को आरक्षण देना संविधान के अनुरूप है, लेकिन आरक्षण की सीमा <strong>50%</strong> से अधिक नहीं हो सकती। साथ ही अदालत ने यह भी स्पष्ट किया कि आरक्षण केवल जाति के आधार पर नहीं, बल्कि सामाजिक और शैक्षणिक पिछड़ेपन के आधार पर दिया जाना चाहिए। इस फैसले ने मंडल आयोग की सिफारिशों को कानूनी वैधता दे दी।</p> <h2><strong>निष्कर्ष</strong></h2> <p><strong>मंडल कमीशन और वी.पी. सिंह का फैसला</strong> भारत के इतिहास में एक बहुत बड़ा मोड़ था। इसने यह साबित किया कि लोकतंत्र का असली मतलब है – समाज के हर वर्ग को बराबरी का हक देना। भले ही इस फैसले से विवाद हुआ, विरोध हुआ, लेकिन यह एक जरूरी कदम था।</p> <p><strong><i>वी.पी. सिंह</i></strong> ने अपने प्रधानमंत्री पद की परवाह न करते हुए पिछड़ों को हक दिलाया। उन्होंने दिखाया कि सच्चा नेता वही होता है जो जनता की भलाई के लिए अपने पद की भी कुर्बानी दे सके।</p> <p>आज भी जब हम सामाजिक न्याय, आरक्षण, और बराबरी की बात करते हैं, तो मंडल आयोग और <strong><i>वी.पी. सिंह</i></strong> का नाम सबसे पहले आता है।</p>',4,'2025-05-31 04:26:23','2025-05-31 05:28:54','','Publish',0,'open',19,111),('मंडल आयोग क्या था?','divisional-commission',2,'<p><strong>मण्डल आयोग</strong> <i>पिछड़ा वर्ग आरक्षण का लाभ देने के उद्देश्य से</i> निर्मित की गई थी। दरअसल, दक्षिण भारतीय राज्यों में लगभग 1960 के दशक से <strong>पिछड़े वर्ग के आरक्षण</strong> हेतु प्रावधान चले आ रहे थे, लेकिन आरक्षण की यह नीति <strong>उत्तर भारतीय राज्यों</strong> में नहीं थी। 1977 से 1979 में जब <strong>जनता पार्टी</strong> की सरकार सत्ता में आई, तब उत्तर भारत में पिछड़े वर्गों के आरक्षण के लिए राष्ट्रीय स्तर पर मजबूती से आवाज उठाई गई।</p>\r\n\r\n<p><strong>बिहार में तत्कालीन मुख्यमंत्री कर्पूरी ठाकुर</strong> इस दिशा में अग्रणी थे। उनकी सरकार ने बिहार में <strong>OBC (Other Backward Classes)</strong> को आरक्षण देने के लिए एक <strong>नई नीति</strong> लागू की। इसके बाद केंद्र सरकार ने 1978 में एक आयोग बनाया, जिसका कार्य <i>पिछड़े वर्ग की स्थिति सुधारने</i> का काम सौंपा गया।</p>\r\n\r\n<p>आजादी के बाद यह <strong>दूसरा अवसर</strong> था जब सरकार ने ऐसा आयोग नियुक्त किया। इसी कारण आधिकारिक रूप से इस आयोग को \"<strong>दूसरा पिछड़ा वर्ग आयोग</strong>\" कहा गया। आमतौर पर इस आयोग के अध्यक्ष <strong>बिंदेश्वरी प्रसाद मण्डल</strong> के नाम पर इसे <strong>मण्डल आयोग</strong> या <strong>मण्डल कमिसन</strong> कहा गया।</p>\r\n\r\n<p><strong>मण्डल आयोग</strong> का गठन <i>भारतीय समाज में विभिन्न तत्वों के शैक्षणिक और सामाजिक पिछड़ेपन की व्यापकता का पता लगाने</i> और <i>इन पिछड़े वर्गों की पहचान के तरीके बताने</i> के लिए किया गया था। आयोग से यह भी अपेक्षा की गई थी कि वह <i>इन वर्गों के पिछड़ेपन को दूर करने के उपाय</i> सुझाएगा। <strong>आयोग ने 1980 में अपनी सिफारिशें पेश कीं</strong>। इस वक्त तक <strong>जनता पार्टी की सरकार गिर चुकी</strong> थी। आयोग की सिफारिश थी कि <strong>पिछड़ा वर्ग</strong> को <i>पिछड़ी जाति के वर्ग</i> में स्वीकार किया जाए, क्योंकि अनुसूचित जातियों से इतर अनेक ऐसी जातियां हैं जिन्हें वर्ग वर्ण-व्यवस्था में नीचे समझा जाता है।</p>\r\n\r\n<p><strong>आयोग ने सर्वेक्षण किया</strong> और पाया कि इन पिछड़ी जातियों की <strong>शिक्षा संस्थानों तथा सरकारी नौकरियों</strong> में भागीदारी (मौजूदगी) बहुत कम है। इस वजह से आयोग ने इस समूह के लिए <strong>शिक्षण संस्थानों तथा सरकारी नौकरियों में 27% सीटें आरक्षित</strong> करने की सिफारिश दी। <strong>मण्डल आयोग</strong> ने <i>पिछड़ा वर्ग की स्थिति सुधारने</i> के लिए कई और समाधान सुझाए, जिनमें <strong>भूमि सुधार</strong> भी एक था।</p>\r\n\r\n<p><strong>1990 के अगस्त</strong> में <i>राष्ट्रीय मोर्चा सरकार ने मण्डल आयोग की सिफारिशों में से एक को लागू करने का फैसला लिया</i>। यह सिफारिश <strong>केंद्रीय सरकार और उसके उपक्रमों की नौकरियों में अन्य पिछड़ा वर्ग को आरक्षण देने</strong> के संबंध में थी। सरकार के इस फैसले से <strong>उत्तर भारत में कई शहरों में हिंसक विरोध प्रदर्शन</strong> हुए। इस फैसले को <strong>सर्वोच्च न्यायालय</strong> में भी चुनौती दी गई और यह प्रकरण \"<strong>इंदिरा साहनी</strong>\" के नाम से प्रसिद्ध हुआ। सरकार के फैसले के खिलाफ जिन लोगों ने अर्जी दायर की थी, उनमें एक नाम <strong>इंदिरा साहनी</strong> का भी था।</p>\r\n\r\n<p><strong>1992 के नवंबर</strong> में <strong>सर्वोच्च न्यायालय</strong> ने सरकार के निर्णय को <strong>सही ठहराते हुए</strong> अपना फैसला सुनाया। <i>राजनीतिक दलों</i> में इस फैसले को लागू करने के तरीकों को लेकर कुछ मतभेद थे, <strong>बहरहाल अन्य पिछड़ा वर्ग को आरक्षण देने</strong> के मामले पर देश के सभी बड़े राजनीतिक दलों में <strong>सहमति</strong> थी।</p>\r\n\r\n<p><strong>राजनीतिक प्रभाव</strong> के रूप में, <strong>1980 के दशक</strong> में <strong>दलित-जनजातीय राजनीतिक संगठनों</strong> का उभार हुआ। <strong>1978 में \"बामसेफ\"</strong> (Bamsafe) का गठन हुआ। यह <i>सरकारी कर्मचारियों</i> का कोई साधारण ट्रेड यूनियन नहीं था, बल्कि इस संगठन ने <strong>बहुजन</strong> अर्थात <strong>अनुसूचित जनजाति, अनुसूचित जाति, पिछड़ा वर्ग और अल्पसंख्यकों</strong> को संगठित कर उन्हें <i>राजनीतिक सत्ता में भागीदारी</i> दिलाने की दिशा में कार्य किया। इसी का परवर्ती विकास \"<strong>दलित शोषित समाज संघर्ष समिति</strong>\" के रूप में हुआ, जिसे बाद में \"<strong>बहुजन समाज पार्टी</strong>\" (बसपा) के रूप में जाना गया।</p>\r\n\r\n<p>इस पार्टी की अगुवाई <strong>कांशीराम</strong> ने की। <strong>बहुजन समाज पार्टी</strong> अपने शुरुआती दौर में एक छोटी पार्टी थी, जिसे <strong>पंजाब, हरियाणा और उत्तर प्रदेश</strong> में <strong>दलित मतदाताओं का समर्थन</strong> प्राप्त था। लेकिन <strong>1989, 1991</strong> के चुनावों में इस पार्टी को उत्तर प्रदेश में <strong>उल्लेखनीय सफलता</strong> मिली। <i>आजाद भारत में यह पहला अवसर</i> था जब कोई राजनीतिक दल <strong>स्वतंत्र रूप से दलित मतदाताओं के समर्थन के आधार</strong> पर इतनी बड़ी राजनीतिक सफलता हासिल कर सका।</p>\r\n\r\n<p>दरअसल, <strong>कांशीराम के नेतृत्व में</strong> बसपा ने अपनी संगठनात्मक नींव <i>व्यवहार-केंद्रित नीतियों</i> पर रखी। <strong>बहुजन समाज</strong> देश की आबादी में <strong>सबसे अधिक</strong> है और <strong>संख्या के लिहाज से</strong> एक मजबूत राजनीतिक रूप ले सकते हैं। <strong>बसपा के आत्मविश्वास</strong> को इस तथ्य से बड़ा बल मिला। इसके बाद बसपा <strong>राज्य की एक बड़ी राजनीतिक ताकत</strong> के रूप में उभरी। बसपा को <strong>सबसे अधिक समर्थन दलित मतदाताओं</strong> से मिला, लेकिन इसने <i>समाज के अन्य वर्गों के बीच भी</i> अपना जनाधार बनाना शुरू किया।</p>\r\n\r\n<p><strong>भारत के कई हिस्सों</strong> में <strong>दलित राजनीति</strong> और <strong>अन्य पिछड़ा वर्ग की राजनीति</strong> <i>स्वतंत्र रूप धारण</i> किया और इन दोनों के बीच अक्सर <strong>प्रतिस्पर्धा</strong> भी देखी गई।</p>\r\n\r\n<h2><strong>निष्कर्ष</strong></h2>\r\n<p>इस प्रकार, उपरोक्त तथ्यों से यह स्पष्ट होता है कि <strong>मण्डल आयोग</strong> का गठन <strong>बिंदेश्वरी प्रसाद मण्डल</strong> द्वारा <i>पिछड़ा वर्ग की दशा सुधारने एवं आरक्षण सुनिश्चित</i> करने हेतु किया गया था। उनकी सिफारिशों के आधार पर <strong>ओबीसी को 27% आरक्षण</strong> प्रदान किया गया। इसके लागू होने से इस वर्ग के लोगों को <strong>लाभ</strong> मिला और साथ ही <strong>राजनीतिक परिदृश्य</strong> पर भी इसका प्रभाव पड़ा। <strong>बहुजन समाज</strong> को संगठित कर <strong>बसपा जैसी पार्टियां</strong> अस्तित्व में आईं, जिनका नेतृत्व <strong>स्वर्गीय कांशीराम</strong> ने किया। इस प्रकार, <strong>निम्न वर्ग की राजनीतिक गतिविधियां सक्रिय</strong> हुईं और <strong>भारतीय राजनीति</strong> में उनका प्रभाव बढ़ा।</p>\r\n',4,'2025-05-31 04:26:23','2025-05-31 05:33:30','','Publish',0,'open',19,112),('राजीव गांधी और नई आर्थिक नीति','rajiv-gandhi-and-new-economic-policy',2,'<p><strong>राजीव गांधी का प्रधानमंत्रित्व काल (1984-1989)</strong> भारत के आर्थिक इतिहास में एक <strong>महत्त्वपूर्ण संक्रमणकाल</strong> के रूप में देखा जाता है। यह वह दौर था जब भारत एक ओर जहां <i>पारंपरिक समाजवादी आर्थिक ढांचे</i> के अंतर्गत काम कर रहा था, वहीं वैश्विक स्तर पर <strong>तकनीकी और बाजार आधारित अर्थव्यवस्थाएं</strong> तेज़ी से उभर रही थीं। ऐसे में <strong>राजीव गांधी ने देश की आर्थिक दिशा को बदलने</strong> की पहल की और \"<strong>नई आर्थिक सोच</strong>\" को जन्म दिया, जो बाद में <strong>1991 की नई आर्थिक नीति</strong> की पृष्ठभूमि बनी। राजीव गांधी भले ही उस व्यापक <i>उदारीकरण, निजीकरण और वैश्वीकरण</i> के दौर तक नहीं पहुँच पाए, परंतु उन्होंने उसकी <strong>नींव अवश्य रख दी</strong>।</p> <p><strong>1991</strong> में भारत ने <strong>नई आर्थिक नीति (NEP)</strong> लागू की, जिसका मकसद देश की <i>आर्थिक हालत को सुधारना</i> और <strong>विकास को तेज़</strong> करना था। इस नीति के बाद <strong>1991 से 1994</strong> के बीच भारत की अर्थव्यवस्था हर साल औसतन <strong>7%</strong> की दर से बढ़ी। इसके बाद <strong>1995 से 2000</strong> के बीच यह बढ़त और तेज हो गई और <strong>GDP</strong> (सकल घरेलू उत्पाद) औसतन <strong>9%</strong> तक पहुँच गई।</p> <h2><strong>परिवर्तन की आवश्यकता</strong></h2> <p><strong>राजीव गांधी</strong> ने प्रधानमंत्री बनने के बाद यह महसूस किया कि भारत की अर्थव्यवस्था <i>जड़ होती जा रही है</i>। <strong>सरकारी नियंत्रण, लाइसेंस राज, भ्रष्टाचार</strong> और <i>धीमी निर्णय प्रक्रिया</i> के कारण <strong>निजी क्षेत्र का विकास</strong> बाधित था। राजीव गांधी की <strong>नई आर्थिक सोच</strong> इस बात पर केंद्रित थी कि अगर भारत को <i>21वीं सदी में एक समृद्ध राष्ट्र</i> बनाना है, तो उसे <strong>वैज्ञानिक, तकनीकी और उद्यमशील</strong> बनना होगा। उन्होंने <strong>प्रशासनिक सुधारों</strong> के साथ-साथ <strong>आर्थिक ढांचे</strong> में भी <strong>बदलाव लाने की शुरुआत</strong> की, जिससे <i>आर्थिक नीतियों में गति, पारदर्शिता और प्रतिस्पर्धा</i> आ सके।</p> <h2><strong>औद्योगिक नीति में सुधार</strong></h2> <p>राजीव गांधी ने <i>औद्योगिक क्षेत्र</i> में कार्य करने के लिए <strong>अनावश्यक सरकारी हस्तक्षेप</strong> को कम करने की शुरुआत की। उन्होंने अनेक क्षेत्रों को <strong>लाइसेंस की बाध्यता से मुक्त</strong> किया और <strong>उद्योगों को अधिक स्वतंत्रता</strong> प्रदान की। उन्होंने यह सुनिश्चित करने का प्रयास किया कि <i>निजी उद्यमियों</i> को <strong>व्यवसाय करने के लिए अनुकूल वातावरण</strong> मिले। इसके अलावा, उन्होंने <strong>बड़े उद्योगों</strong> के साथ-साथ <strong>लघु और मझोले उद्योगों</strong> को भी बढ़ावा देने की दिशा में योजनाएं बनाई ताकि <strong>आर्थिक विकास समावेशी</strong> हो।</p> <h2><strong>प्रौद्योगिकी और नवाचार</strong></h2> <p><strong>राजीव गांधी की नई आर्थिक नीति</strong> की विशेषता यह थी कि वह <i>परंपरागत संसाधनों</i> पर आधारित विकास की जगह <strong>नवाचार और प्रौद्योगिकी पर आधारित विकास</strong> को प्राथमिकता देती थी। उन्होंने <strong>कंप्यूटर, टेलीकॉम, सूचना तकनीक और अंतरिक्ष अनुसंधान</strong> के क्षेत्र में <strong>बड़े सुधार</strong> किए। <strong>कंप्यूटराइजेशन</strong> और <strong>दूरसंचार के विस्तार</strong> ने देश को <i>एक नई दिशा</i> दी। राजीव गांधी का यह दृष्टिकोण उस समय <strong>क्रांतिकारी</strong> माना गया, क्योंकि तब तक भारत की अर्थव्यवस्था <i>मुख्यतः कृषि और भारी उद्योगों</i> पर आधारित थी।</p> <h2><strong>वैश्वीकरण की ओर बढ़ते कदम</strong></h2> <p>हालाँकि <strong>राजीव गांधी</strong> ने <i>पूर्ण रूप से वैश्वीकरण</i> की नीति लागू नहीं की, परंतु उनके कार्यों में <strong>उसके बीज</strong> अवश्य दिखते हैं। उन्होंने <strong>आयात-निर्यात नीति</strong> में <i>लचीलापन</i> लाया और <strong>विदेशी निवेश</strong> को लेकर कुछ <strong>प्रारंभिक प्रयास</strong> किए। उन्होंने यह समझा कि भारत को यदि <strong>वैश्विक प्रतिस्पर्धा</strong> में टिके रहना है, तो उसे <strong>अंतरराष्ट्रीय बाजार से जुड़ना</strong> ही होगा। उनके समय में <i>व्यापार प्रक्रिया को सरल बनाने</i> और <i>व्यापार घाटे को कम करने</i> की दिशा में कार्य हुआ।</p> <h2><strong>पंचायती राज और विकेंद्रीकरण</strong></h2> <p><strong>राजीव गांधी</strong> का ध्यान केवल औद्योगिक क्षेत्रों तक सीमित नहीं था। उन्होंने <strong>ग्रामीण भारत को सशक्त</strong> बनाने के लिए <strong>पंचायती राज संस्थाओं</strong> को <strong>अधिक अधिकार</strong> देने की पहल की। उन्होंने यह महसूस किया कि <i>विकास की प्रक्रिया को जमीनी स्तर</i> तक पहुँचाना है, तो योजनाओं को नीचे तक लागू करने वाली संस्थाओं को <strong>आर्थिक रूप से सक्षम</strong> बनाना होगा। इससे <strong>स्थानीय भागीदारी</strong> बढ़ी और <strong>विकास की प्रक्रिया</strong> अधिक प्रभावी बनी।</p> <p><strong>राजीव गांधी की नई आर्थिक सोच</strong> का एक प्रमुख स्तंभ <strong>मानव संसाधन में निवेश</strong> था। उन्होंने <strong>शिक्षा, स्वास्थ्य, विज्ञान और तकनीकी</strong> क्षेत्र में <strong>सुधारों को प्राथमिकता</strong> दी। उन्होंने <strong>तकनीकी संस्थानों</strong> की स्थापना, <strong>व्यावसायिक शिक्षा को बढ़ावा</strong> और <strong>युवाओं के लिए स्वरोजगार</strong> की योजनाएं लागू कीं। यह समझदारी थी कि यदि भारत को <strong>तकनीकी और आर्थिक रूप से आगे बढ़ना</strong> है, तो उसकी जनसंख्या को <strong>कुशल और शिक्षित</strong> बनाना ही पड़ेगा।</p> <h2><strong>निष्कर्ष</strong></h2> <p><strong>राजीव गांधी की आर्थिक नीति</strong> को \'<strong>नई आर्थिक नीति</strong>\' की <strong>पूर्वपीठिका</strong> कहा जा सकता है। वे भले ही <strong>1991</strong> की तरह कोई औपचारिक <i>नई आर्थिक नीति</i> लागू नहीं कर पाए, लेकिन उनके समय में जो <strong>सुधारात्मक प्रयास</strong> हुए, उन्होंने <strong>भारतीय अर्थव्यवस्था</strong> को <strong>उदारीकरण, तकनीकी नवाचार और वैश्विक प्रतिस्पर्धा</strong> के लिए <strong>तैयार करने का आधार</strong> तैयार कर दिया। उनका यह दृष्टिकोण था कि भारत को <strong>आत्मनिर्भर, आधुनिक और विज्ञान आधारित राष्ट्र</strong> बनाना है, और इसके लिए <strong>अर्थव्यवस्था में नई सोच और लचीलापन</strong> लाना आवश्यक है। इस तरह <strong>राजीव गांधी</strong> केवल एक <i>राजनेता</i> ही नहीं, बल्कि एक <strong>दूरदर्शी आर्थिक सुधारक</strong> भी थे, जिनकी <strong>सोच ने भारत के भविष्य की आर्थिक दिशा को आकार</strong> दिया।</p>',2,'2025-05-31 04:26:23','2025-05-31 05:39:15','','Publish',0,'open',19,113),('लाल बहादुर शास्त्री और भारत-पाकिस्तान संबंध','lal-bahadur-shastri-and-india-pakistan-relations',2,'<p><strong>भारत और पाकिस्तान</strong>, जो एक ही सांस्कृतिक और ऐतिहासिक विरासत से जन्मे दो देश हैं, उनके संबंध विभाजन के समय से ही <strong>संघर्ष, तनाव और अविश्वास</strong> से भरे रहे हैं। <strong>1947</strong> में जब ब्रिटिश भारत का विभाजन हुआ, तब से लेकर आज तक दोनों देशों के बीच चार बड़े युद्ध हो चुके हैं, अनेक सीमावर्ती झड़पें, कूटनीतिक संकट, आतंकवादी घटनाएं और संवाद की कोशिशें होती रही हैं।</p>\r\n\r\n<p><strong>1947 का भारत-विभाजन</strong>, उपमहाद्वीप के इतिहास की <i>सबसे दर्दनाक घटनाओं</i> में से एक था। इस विभाजन के फलस्वरूप <strong>लाखों लोग विस्थापित</strong> हुए और अनुमानतः <strong>10 लाख से अधिक लोगों</strong> की मृत्यु हो गई। विभाजन <i>धार्मिक आधार</i> पर हुआ, और इससे दोनों देशों के संबंधों की नींव ही <strong>दुश्मनी और अविश्वास</strong> पर पड़ गई। पाकिस्तान ने खुद को एक <i>इस्लामिक गणराज्य</i> के रूप में स्थापित किया जबकि भारत ने <strong>धर्मनिरपेक्ष लोकतंत्र</strong> को अपनाया।</p>\r\n\r\n<p><strong>लाल बहादुर शास्त्री</strong> ने <strong>9 जून 1964</strong> को भारत के प्रधानमंत्री का पद संभाला। यह समय भारत के लिए <i>बहुत ही नाजुक</i> था, क्योंकि देश को आंतरिक राजनीतिक अस्थिरता, आर्थिक संकट और बाहरी खतरों का सामना करना पड़ रहा था। पाकिस्तान के साथ <strong>लंबे समय से कश्मीर</strong> को लेकर विवाद चल रहा था, जो धीरे-धीरे युद्ध की ओर बढ़ रहा था। <strong>शास्त्री जी का नेतृत्व</strong> एक ऐसे समय में सामने आया, जब देश को <strong>मजबूती और निर्णायक सोच</strong> की ज़रूरत थी।</p>\r\n\r\n<h2><strong>ऑपरेशन जिब्राल्टर और भारत की जवाबी कार्रवाई</strong></h2>\r\n<p><strong>1965</strong> में पाकिस्तान ने <i>‘ऑपरेशन जिब्राल्टर’</i> नाम की एक सैन्य योजना बनाई, जिसके तहत उसके सैनिकों ने <strong>कश्मीर में घुसपैठ</strong> की। उद्देश्य यह था कि <i>स्थानीय कश्मीरी जनता भारत के खिलाफ विद्रोह</i> कर देगी और पाकिस्तान की सहायता से <strong>कश्मीर को भारत से अलग</strong> कर दिया जाएगा। लेकिन यह योजना असफल रही क्योंकि <strong>कश्मीरी जनता ने पाकिस्तान का साथ नहीं दिया</strong>। भारत ने तुरंत सेना भेजकर <strong>पाकिस्तान की इस घुसपैठ को रोकने</strong> के लिए कड़ी सैन्य कार्रवाई की।</p>\r\n\r\n<h2><strong>1965 का युद्ध</strong></h2>\r\n<p>घुसपैठ के जवाब में <strong>भारत और पाकिस्तान</strong> के बीच <strong>सितंबर 1965</strong> में युद्ध छिड़ गया। यह युद्ध <strong>पंजाब, कश्मीर और राजस्थान</strong> के विभिन्न मोर्चों पर लड़ा गया। <strong>भारतीय सेना</strong> ने <i>साहस और रणनीति</i> के साथ युद्ध लड़ा और <strong>लाहौर तक पहुँचने</strong> की स्थिति में आ गई। इस युद्ध में <strong>भारतीय वायुसेना और थलसेना</strong> दोनों ने शानदार प्रदर्शन किया। इस समय <strong>शास्त्री जी ने सैन्य बलों को पूरा समर्थन</strong> दिया और उन्होंने देश को एकजुट करते हुए <i>“जय जवान, जय किसान”</i> का नारा दिया, जो आज भी <strong>राष्ट्रीय भावना</strong> का प्रतीक है।</p>\r\n\r\n<h2><strong>युद्ध के बाद ताशकंद समझौता</strong></h2>\r\n<p>युद्ध के बाद <strong>अंतर्राष्ट्रीय दबाव</strong> और <strong>सोवियत संघ की पहल</strong> पर भारत और पाकिस्तान के बीच <strong>जनवरी 1966</strong> में <strong>ताशकंद (उज्बेकिस्तान)</strong> में शांति वार्ता आयोजित की गई। <strong>शास्त्री जी और पाकिस्तान के राष्ट्रपति अयूब खान</strong> के बीच हुई बातचीत में दोनों देश <strong>युद्ध विराम पर सहमत</strong> हुए और युद्ध से पूर्व की सीमाओं पर लौटने का फैसला हुआ। इस समझौते को <i>“ताशकंद समझौता”</i> कहा जाता है।</p>\r\n\r\n<p><strong>11 जनवरी 1966</strong> को <i>ताशकंद समझौते के ठीक बाद</i> <strong>लाल बहादुर शास्त्री जी का आकस्मिक निधन</strong> हो गया। यह खबर <i>देशभर में शोक</i> का कारण बनी। उनकी मृत्यु को लेकर कई सवाल उठे और आज भी कुछ लोग इसे <i>रहस्यमयी</i> मानते हैं। लेकिन इसमें कोई संदेह नहीं कि उन्होंने देश को <strong>एकजुटता, साहस और संयम</strong> के साथ नेतृत्व दिया।</p>\r\n\r\n<h2><strong>निष्कर्ष</strong></h2>\r\n<p><strong>लाल बहादुर शास्त्री</strong> का कार्यकाल भले ही छोटा रहा, लेकिन उनका योगदान <strong>अत्यंत महत्वपूर्ण और प्रेरणादायक</strong> रहा। उन्होंने <strong>भारत-पाकिस्तान</strong> के तनावपूर्ण संबंधों को <strong>दृढ़ता और विवेक</strong> से संभाला। <strong>1965 का युद्ध</strong> उनके <strong>नेतृत्व कौशल</strong> का प्रमाण है, जबकि <strong>ताशकंद समझौता</strong> उनकी <strong>शांति-प्रिय सोच</strong> को दर्शाता है। वे एक ऐसे नेता थे जिन्होंने <i>न सिर्फ युद्ध जीतने</i> का साहस दिखाया, बल्कि <i>शांति स्थापित करने</i> की भी अद्भुत क्षमता रखी। उनका <strong>जीवन और योगदान</strong> <i>भारत के इतिहास में स्वर्ण अक्षरों में लिखा गया</i> है।</p>\r\n',4,'2025-05-31 04:26:23','2025-05-31 05:42:28','','Publish',0,'open',19,114),('हरित क्रांति - कारण और प्रभाव','green-revolution-causes-and-effects',2,'<p><strong>हरित क्रांति</strong> से तात्पर्य <i>कृषि के क्षेत्र में आए उत्पादन के स्वरूप में परिवर्तन</i> से होता है। दरअसल <strong>भारत में कृषि की स्थिति और आर्थिक पिछड़ेपन</strong> की स्थिति में थी, जिसका प्रमुख कारण <i>औपनिवेशिक शासन द्वारा भारतीय संसाधनों का शोषण</i> तथा <i>स्वतंत्रता के पश्चात भारत के विभाजन के आर्थिक दुष्परिणाम</i>ों के प्रभाव स्वरूप कृषि के क्षेत्र में असंतुलन उत्पन्न हो गया था। इस दौरान पाकिस्तान के अंदर भारत के सर्वाधिक खाद्यान्न एवं उद्योगों हेतु कच्चे माल के उत्पादक क्षेत्र चले गए थे। पाकिस्तान से आने वाले <strong>विस्थापितों</strong> की भारी संख्या को <strong>भारतीय कृषि क्षेत्र में आबाद</strong> किया गया, जिससे कुल मिलाकर <i>पिछड़ी खेती और जनसंख्या के भार</i> के कारण कृषि क्षेत्र में <strong>भारी विसंगतियाँ</strong> उत्पन्न हो गई थीं।</p>\r\n\r\n<p>सामान्यतः माना जाता है कि <strong>हरित क्रांति ने कृषि क्षेत्र को ऊँचाइयों पर पहुँचाने</strong> का महत्वपूर्ण कार्य किया। सबसे बड़ी परेशानी <strong>खाद्यान्नों</strong> को लेकर थी। भारत को <i>खाद्यान्न विदेशों से आयात</i> करना पड़ता था। अतः हरित क्रांति ने <strong>भारत को खाद्यान्न के मामले में आत्मनिर्भर और आत्मसंतुष्ट</strong> बनाया तथा <i>गोदाम अति-शेष खाद्यान्नों से भरने</i> लगे।</p>\r\n\r\n<h2>हरित क्रांति के कारण</h2>\r\n<p>भारत में हरित क्रांति एक <strong>वैज्ञानिक व तकनीकी क्रांति</strong> थी, जिसमें <i>भारतीय कृषि के विकास और समृद्धि</i> का रास्ता आगे बढ़ाया गया। इसके कारक निम्नलिखित हैं-</p>\r\n\r\n<h3 class=\"atech\">भूमि सुधार</h3>\r\n<p>हरित क्रांति का प्रमुख प्रेरक तत्व <strong>भूमि सुधार</strong> था। <i>स्वतंत्रता पूर्व भारतीय कृषि में ठहराव</i> की स्थिति थी। इस दौर में कृषि क्षेत्र में <strong>गतिहीनता</strong> व्याप्त हो गई थी। लेकिन 1955-60 के दौरान भूमि सुधारों ने <i>भू-संरचना के सामंती ढाँचे को संस्थागत रूप में समाप्त</i> कर दिया। भूमि सुधारों के अंतर्गत अधिसंख्य किसानों को भूमि अधिकार प्राप्त हुए, तो वे <strong>निजी स्तर पर उत्पादन को बढ़ाने के लिए प्रयास</strong> करने लगे। अब वे अपने खेतों पर कुएँ, तालाब, रहट, नलकूप इत्यादि का निर्माण करवाने लगे। इस तरह <strong>1955-60 के दौरान कृषि क्षेत्र में पंद्रह प्रतिशत</strong> की वृद्धि हुई। <i>सिंचाई, उर्वरक, उन्नत बीजों</i> का प्रयोग होने लगा।</p>\r\n\r\n<h3 class=\"atech\">तकनीकी विकास</h3>\r\n<p>भूमि सुधारों ने कृषि क्षेत्र के <i>संस्थागत सुधार में भारी परिवर्तन</i> किया। स्वतंत्र भारत की आवश्यकताओं के अनुकूल कृषि में <strong>तकनीक का उपयोग</strong> प्रारंभ हुआ। <strong>प्रथम पंचवर्षीय योजना</strong> के दौरान कृषि और सिंचाई पर <strong>21 प्रतिशत धनराशि खर्च</strong> की गई। इस प्रकार <strong>संस्थागत सुधारों</strong> के साथ <i>आधुनिक कृषि का वैज्ञानिक तकनीकी आधार</i> भी निर्मित होने लगा। अनेक सिंचाई परियोजनाएँ, कृषि विश्वविद्यालय, शोध प्रयोगशालाएँ, <strong>भारतीय कृषि अनुसंधान परिषद</strong>, रासायनिक खाद के कारखाने आदि ने <i>कृषि के विकास में तकनीकी सहायता</i> पहुँचाई।</p>\r\n\r\n<h3 class=\"atech\">खाद्यान्नों का अभाव</h3>\r\n<p><strong>आज़ादी के समय भारत में खाद्यान्नों का अभाव</strong> था। 1950 के बाद <strong>खाद्यान्नों के दामों में भारी वृद्धि</strong> हुई। भोजन की अपनी माँग को पूरा करने के लिए <i>अनाजों का आयात</i> करना पड़ा। भारत ने अमेरिका के साथ <strong>PL-480</strong> के समझौते किए और <strong>1956 में लगभग 30 लाख टन अनाज</strong> का आयात किया गया। <strong>1963 में यह 65 में 45,000 टन</strong> पहुँच गया। इस कारण भारत ने <i>आत्मनिर्भर बनने के लिए कृषि उत्पादन में वृद्धि</i> के लिए प्रेरणा ली।</p>\r\n\r\n<h3 class=\"atech\">अंतरराष्ट्रीय दबाव</h3>\r\n<p>भारत को <strong>1962 में चीन</strong> और <strong>1965 में पाकिस्तान</strong> से युद्ध लड़ने पड़े। इससे यह साबित हो गया कि <i>भारत अंतरराष्ट्रीय क्षेत्र में अपनी अस्मिता की रक्षा</i> तभी कर सकता है जब वह <strong>आर्थिक रूप से सक्षम</strong> हो। ऐसी स्थिति में <strong>अमेरिका, चीन</strong> आदि देश भारत पर दबाव बनाने लगे। <i>खाद्यान्नों के मामले में अमेरिका पर निर्भरता</i> भारत की <strong>स्वतंत्र विदेश नीति</strong> में बाधक बन रही थी। इसलिए <i>आर्थिक आत्मनिर्भरता भारत के लिए आवश्यक</i> थी।</p>\r\n\r\n<h3 class=\"atech\">अकाल की स्थिति</h3>\r\n<p><strong>1964 से 1968 के दौरान भारत को भयानक अकाल</strong> का सामना करना पड़ा। इससे <i>खाद्यान्नों का अभाव और अनाजों की कीमतें</i> बढ़ीं। <strong>1966 में भारत को एक करोड़ टन से अधिक</strong> खाद्यान्न का आयात करना पड़ा। इससे <strong>उत्तर प्रदेश एवं बिहार</strong> भी अकाल की चपेट में आ गए। इस दौरान <i>संपूर्ण राष्ट्र तथा भविष्य</i> को ध्यान में रखकर इससे निपटने के लिए कृषि पर विशेष ध्यान दिया गया।</p>\r\n\r\n<h3 class=\"atech\">कृषि ऋण व्यवस्था</h3>\r\n<p>भारत में <strong>परंपरागत कृषि के लिए ऋणों की व्यवस्था महाजन</strong> किया करते थे, जो <i>अनियंत्रित ब्याज</i> वसूलते थे। <strong>किसान ऋण चुकाने की स्थिति में न रहने पर</strong> उनकी ज़मीन हल्ला-बोलकर नीलाम करवा दी जाती थी। जिस तरह से सामंत कृषकों पर भार बनाए रखते थे, उसी प्रकार किसान <i>सूदखोरों के भार से प्रताड़ित</i> थे। स्वतंत्रता के पश्चात सरकार ने <strong>कृषि वित्त की आपूर्ति के लिए संस्थागत साधनों के विकास</strong> पर ध्यान दिया। <i>सहकारी समितियों</i> के माध्यम से <strong>कृषि ऋण उपलब्ध</strong> कराए जाने लगे। <strong>1969 में बैंकों के राष्ट्रीयकरण</strong> के साथ ही कृषि वित्त का प्रावधान उपयोगी सिद्ध हुआ। <strong>सरकारी निवेश, संस्थागत वित्त, उत्पादन मूल्य</strong> आदि <i>हरित क्रांति में सहायक</i> सिद्ध हुए।</p>\r\n\r\n<h2>हरित क्रांति के प्रभाव</h2>\r\n<p>हरित क्रांति के प्रभाव <strong>भारतीय कृषि, समाज और अर्थव्यवस्था</strong> पर <i>गहरे और व्यापक</i> रूप से पड़े।</p>\r\n\r\n<h3 class=\"atech\">उत्पादन में वृद्धि</h3>\r\n<p>हरित क्रांति का सर्वाधिक प्रभाव <strong>कृषि उत्पादन में वृद्धि</strong> के रूप में सामने आया। <i>उत्पादन में वृद्धि</i> के माध्यम से देश ने <strong>खाद्यान्न के क्षेत्र में आत्मनिर्भरता</strong> प्राप्त की। कृषि क्षेत्र <i>समृद्धि की ओर अग्रसर</i> हुआ। इसने <strong>राष्ट्रीय अर्थव्यवस्था में कृषि के योगदान</strong> को बढ़ाया। खाद्यान्नों के अतिरिक्त <strong>तिलहनों के उत्पादन</strong> में भी बढ़ोतरी नजर आने लगी। तिलहनों के क्षेत्र में <i>आत्मनिर्भरता प्राप्त करने</i> का प्रयास <strong>1980 के बाद</strong> आरंभ हुआ।</p>\r\n\r\n<h3 class=\"atech\">कृषि क्षेत्र में वृद्धि</h3>\r\n<p>हरित क्रांति के परिणामस्वरूप <strong>कृषि प्रसार अधिक क्षेत्र</strong> में हुआ। जो भूमि <i>कृषि जोत से बाहर</i> थी, उन्हें जोत में सम्मिलित करने में हरित क्रांति ने <strong>महत्वपूर्ण भूमिका</strong> निभाई। <strong>सिंचाई साधनों में वृद्धि</strong> के कारण <i>अधिक भूमि पर खेती संभव</i> हो सकी। <strong>कृषि उत्पादन में वृद्धि</strong> होने के कारण किसानों ने <strong>भूमि पर भरोसा</strong> करना आरंभ किया।</p>\r\n\r\n<h3 class=\"atech\">किसानों के दृष्टिकोण में परिवर्तन</h3>\r\n<p>हरित क्रांति ने <i>तकनीकी के प्रति किसानों के दृष्टिकोण में भारी परिवर्तन</i> किया। उन्हें <strong>परंपरागत खेती की सीमाओं</strong> का पता चल गया। प्रारंभ में किसानों ने नई तकनीक को अपनाने में <i>संकोच और दकियानूसी रवैया</i> दिखाया, किंतु नई तकनीकी से <strong>कृषि उत्पादन में वृद्धि</strong> के प्रभाव को उन्होंने <strong>एकमत होकर स्वीकार</strong> किया। अब किसान <i>ट्रैक्टर, नलकूप, पंपसेट, संकरित बीज, रासायनिक खाद, कीटनाशक दवाओं</i> आदि का प्रयोग करने लगे हैं।</p>\r\n\r\n<h3 class=\"atech\">जीवन स्तर में परिवर्तन</h3>\r\n<p>हरित क्रांति से उपजी <strong>समृद्धि ने ग्रामीण जीवन स्तर को उन्नत</strong> बनाया। <i>कच्चे मकानों के स्थान पर पक्के मकानों</i> का निर्माण तेजी से हुआ। <strong>भौतिक सुख-साधनों में वृद्धि</strong> हुई। <i>ट्रांजिस्टर, रेडियो, घड़ी, साइकिल, पंखा, टेलीविजन, वॉशिंग मशीन, सिलाई मशीन, कूलर, कार, एयर कंडीशनर</i> जैसे उपकरणों का उपयोग होने लगा।</p>\r\n\r\n<h3 class=\"atech\">रोजगारों का सृजन</h3>\r\n<p>इससे <strong>नए रोजगारों का सृजन</strong> हुआ। <i>बिजली, पंपसेट, ट्रैक्टर, ट्रक, कार, मोटरसाइकिल</i> आदि के कारण <strong>मरम्मत, संचालन एवं चालकों की माँग</strong> बढ़ी। इससे <i>अन्य रोजगारों को भी बढ़ावा</i> मिला। लोग <strong>मिस्त्री, बढ़ई, दर्जी, बुनकर</strong> इत्यादि के रूप में कार्य करने लगे।</p>\r\n\r\n<h3 class=\"atech\">उद्योगों को लाभ</h3>\r\n<p>हरित क्रांति ने <strong>नगरों को भी लाभान्वित</strong> किया। <i>कृषि उत्पादों का विपणन शहरों</i> में होता था, जिससे <strong>व्यापारी वर्ग को भारी लाभ</strong> हुआ। <strong>रासायनिक खाद, कीटनाशक दवाओं का उत्पादन एवं विपणन</strong> भी शहरों में हुआ। इस प्रकार <i>उद्योगों द्वारा उत्पादित वस्तुओं का सबसे बड़ा उपभोक्ता ग्रामीण क्षेत्र</i> बन गया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार उपर्युक्त अध्ययन से निष्कर्ष निकलता है कि <strong>स्वतंत्रता प्राप्ति के पश्चात भारत में 1960 के दशक</strong> में जो <strong>भूमि सुधार कार्यक्रम</strong> प्रारंभ हुए, उसी क्रम में <strong>हरित क्रांति का सूत्रपात</strong> हुआ। इसके परिणामस्वरूप <i>भारत की खाद्यान्नों पर विदेशी निर्भरता समाप्त</i> हुई और भारत <strong>आत्मनिर्भर</strong> बना। इसने जहाँ एक ओर <strong>अकाल जैसे संकटों को रोका</strong>, वहीं दूसरी ओर <strong>उत्पादन वृद्धि</strong> के कारण <i>ग्रामीण जीवन स्तर में भी सुधार</i> लाया। <strong>भारत की अर्थव्यवस्था में कृषि का योगदान</strong> भी बढ़ गया।</p>\r\n',3,'2025-05-31 04:26:23','2025-05-31 05:49:09','','Publish',0,'open',19,115),('अरस्तू के राज्य संबंधी सिद्धांत का वर्णन कीजिए','aristocratic-principle',2,'<p><strong>अरस्तू</strong> प्राचीन यूनानी राजनीतिक दर्शन का एक अत्यंत महत्वपूर्ण स्तंभ है। <i>अरस्तू (384–322 ई.पू.)</i> प्लेटो का शिष्य और सिकंदर महान का गुरु था। वह पहला व्यक्ति था जिसने राज्य और राजनीति का वैज्ञानिक अध्ययन किया और <strong>राजनीति को एक \"प्राकृतिक संस्था\"</strong> बताया।</p>\r\n\r\n<p><strong>अरस्तू राज्य को स्वाभाविक मानते हैं।</strong> उनके अनुसार, राज्य सभी मनुष्यों के लिए एक आवश्यक शर्त है। <i>प्लेटो की तरह</i>, वे राज्य या समाज के बीच अंतर नहीं करते हैं और इसी तरह, इसे <strong>अच्छे जीवन के लिए आवश्यक</strong> मानते हैं। इस प्रकार, उनके विचार में, राज्य एक अच्छे जीवन की एक आवश्यक शर्त है।</p>\r\n\r\n<h2>राज्य का प्राकृतिक स्वरूप</h2>\r\n<p>अरस्तू ने कहा है कि \"<strong>मनुष्य स्वभाव से ही एक सामाजिक एवं राजनीतिक प्राणी है।</strong>\" उसके अनुसार- कोई भी मनुष्य अकेले नहीं रह सकता, इसलिए एक पुरुष और एक महिला मिलकर एक परिवार बनाते हैं। जब एक परिवार अपना विस्तार करता है तो एक गांव बनता है और जब ऐसे कई गांव बनते हैं तो एक राज्य अस्तित्व में आता है। जब एक राज्य बनता है और समाज संगठित होता है, तो मनुष्य अपनी <i>ज़रूरतों को पूरा</i> कर सकता है।</p>\r\n\r\n<h2>राज्य का उद्देश्य</h2>\r\n<p><strong>अरस्तू के अनुसार, राज्य का मुख्य उद्देश्य \"नागरिकों को सद्गुणपूर्ण और पूर्ण जीवन प्रदान करना\" है।</strong> वह राज्य को केवल सुरक्षा या आर्थिक व्यवस्था के लिए नहीं, बल्कि <strong>नैतिक और बौद्धिक विकास</strong> के लिए आवश्यक मानते हैं। उनका मानना था कि राज्य एक नैतिक संस्था है जो व्यक्ति को \"<i>श्रेष्ठ जीवन</i>\" जीने का अवसर देती है। उन्होंने स्पष्ट रूप से कहा- \"<strong>राज्य का उद्देश्य केवल जीना नहीं, बल्कि अच्छा जीना है।</strong>\"</p>\r\n\r\n<h2>राज्य और नागरिक</h2>\r\n<p>अरस्तू के अनुसार राज्य और नागरिक एक-दूसरे के पूरक हैं। <strong>राज्य नागरिकों के नैतिक जीवन को दिशा देता है</strong> और नागरिक राज्य की स्थिरता व विकास में योगदान करते हैं। अरस्तू के अनुसार राज्य एक स्वाभाविक संस्था है, जो परिवार और ग्राम की क्रमिक विकास प्रक्रिया का परिणाम है। इसका उद्देश्य केवल जीवित रहना नहीं, बल्कि \"<strong>उत्तम जीवन</strong>\" जीना है। <i>राज्य व्यक्ति से बड़ा है</i> क्योंकि वह व्यक्ति के नैतिक और सामाजिक विकास को संभव बनाता है।</p>\r\n<p>अरस्तू ने नागरिक की परिभाषा दी कि \"<strong>वह व्यक्ति जो राज्य के कार्यों में भाग लेता है, जैसे कानून बनाना और न्याय करना, वही नागरिक कहलाता है।</strong>\" <i>नागरिकता केवल जन्म या निवास पर आधारित नहीं</i> होती, बल्कि <strong>राज्य की राजनीतिक गतिविधियों में भागीदारी</strong> आवश्यक होती है।</p>\r\n\r\n<h2>राज्य और शिक्षा</h2>\r\n<p>अरस्तू के अनुसार <strong>राज्य और शिक्षा का गहरा संबंध</strong> है। उसका मानना था कि राज्य का प्रमुख उद्देश्य <strong>नागरिकों के नैतिक और बौद्धिक विकास</strong> को सुनिश्चित करना है, और यह कार्य <i>शिक्षा के बिना संभव नहीं</i> है। इसलिए <strong>शिक्षा को वह एक सार्वजनिक और अनिवार्य व्यवस्था</strong> मानता था, जिसे राज्य द्वारा नियंत्रित किया जाना चाहिए।</p>\r\n<p>उसके अनुसार बच्चों को प्रारंभ से ही ऐसी शिक्षा दी जानी चाहिए जो उन्हें न केवल <strong>अच्छे नागरिक</strong> बनाए, बल्कि राज्य के प्रति उनकी <strong>निष्ठा, अनुशासन और नैतिकता</strong> को भी मजबूत करे। <i>शिक्षा का उद्देश्य केवल ज्ञान देना नहीं है</i>, बल्कि <strong>चरित्र निर्माण</strong> करना और व्यक्ति को <i>समाज के अनुरूप ढालना</i> भी है।</p>\r\n\r\n<h2>राज्य और न्याय</h2>\r\n<p><strong>अरस्तू के अनुसार न्याय राज्य की आत्मा है।</strong> अरस्तू के अनुसार राज्य का मुख्य उद्देश्य <strong>न्याय की स्थापना</strong> है। उनके विचार में \"<strong>न्याय ही राज्य का आधार है</strong>\" और <i>बिना न्याय के राज्य का अस्तित्व संभव नहीं</i>। <strong>न्याय वह तत्त्व है जो लोगों को एकजुट करता है</strong> और राज्य को स्थिर बनाता है।</p>\r\n\r\n<h2>राज्य और कानून</h2>\r\n<p>अरस्तू के अनुसार, राज्य तभी सफल और स्थिर हो सकता है जब उसमें <strong>कानून सर्वोच्च हो</strong> और <i>सभी नागरिकों के लिए एक समान और न्यायपूर्ण नियम</i> लागू हों। <strong>कानून ही राज्य को नैतिक, न्यायपूर्ण और संगठित</strong> बनाता है।</p>\r\n<p>अरस्तू यह मानता था कि <strong>कानून सभी पर समान रूप से लागू होना चाहिए</strong>, चाहे वह सामान्य नागरिक हो या शासक स्वयं। उसके अनुसार सबसे अच्छा शासन वह है जहाँ \"<strong>कानून का शासन</strong>\" होता है, न कि किसी एक व्यक्ति का <i>निरंकुश शासन</i>। <strong>कानून बुद्धि और तर्क का परिणाम</strong> होता है, जबकि व्यक्ति का निर्णय <i>भावनाओं से प्रभावित</i> हो सकता है। इसलिए <strong>कानून पर आधारित राज्य ही न्यायपूर्ण और स्थायी</strong> होता है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>अरस्तू का राज्य संबंधी सिद्धांत यथार्थवाद, तर्क और व्यावहारिकता पर आधारित</strong> है। वह न तो प्लेटो की तरह <i>आदर्शवादी</i> था और न ही केवल <i>शक्ति की राजनीति</i> में विश्वास करता था। उसने राज्य को एक <strong>नैतिक और प्राकृतिक संस्था</strong> बताया जो नागरिकों को <strong>सुखी, नैतिक और पूर्ण जीवन</strong> प्रदान करने के लिए बनी है। <i>अरस्तू के विचार आज भी आधुनिक लोकतंत्र, नागरिकता, और न्याय</i> की अवधारणाओं को समझने में अत्यंत उपयोगी हैं।</p>\r\n',3,'2025-06-02 14:35:35','2025-06-02 15:53:41','','Publish',0,'open',63,116),('कौटिल्य का मंडल सिद्धांत','kautilya-of-kautilya',2,'<p><strong>कौटिल्य</strong>, जिन्हें <i>चाणक्य</i> और <i>विष्णुगुप्त</i> के नाम से भी जाना जाता है, <strong>मौर्य साम्राज्य</strong> के संस्थापक <i>चंद्रगुप्त मौर्य</i> के प्रधान मंत्री और मार्गदर्शक थे। उन्होंने <i>‘अर्थशास्त्र’</i> नामक ग्रंथ में <strong>राजनीति, अर्थव्यवस्था, विदेश नीति</strong> और <strong>युद्धनीति</strong> के विभिन्न सिद्धांत प्रस्तुत किए। इन्हीं में से एक महत्वपूर्ण सिद्धांत है – <strong>मंडल सिद्धांत</strong>। यह सिद्धांत <i>विदेशी संबंधों और कूटनीति</i> से संबंधित है, और बताता है कि किसी भी राजा को <strong>अपने शत्रु और मित्र की पहचान कैसे करनी चाहिए</strong>।</p>\r\n\r\n<p><strong>कौटिल्य ने अर्थशास्त्र के छठे अधिकरण में मंडल सिद्धांत</strong> का वर्णन किया है। <i>‘मंडल’</i> का शाब्दिक अर्थ है <i>घेरा या परिधि</i>। कौटिल्य के अनुसार, <strong>हर राज्य के चारों ओर अन्य राज्य होते हैं</strong>, जो <i>मित्र या शत्रु</i> हो सकते हैं। उन्होंने <strong>मंडल में 12 प्रकार के देशों</strong> का जिक्र किया है — <i>‘विजिगीषु’, ‘अरि’, ‘मित्र’, ‘अरि-मित्र’, ‘मित्र-मित्र’, ‘अरि-मित्र-मित्र’, ‘पार्ष्णिग्राह’, ‘आक्रंद’, ‘पार्ष्णिग्राहसार’, ‘आक्रन्दसार’, ‘मध्यमा’</i> तथा <i>‘उदासीन’</i> देश। उन्होंने मंडल के इन सभी देशों के <strong>एक-दूसरे के साथ संबंधों</strong> को ही <strong>मंडल सिद्धांत</strong> का नाम दिया है।</p>\r\n\r\n<h2>मंडल सिद्धांत की संरचना</h2>\r\n<p><strong>कौटिल्य ने मंडल सिद्धांत</strong> के अंतर्गत <strong>राज्य व्यवस्था को बारह प्रकार के राज्यों</strong> में विभाजित किया, जिनकी <i>भूमिका और संबंध विजिगीषु राज्य से भिन्न</i> होती है। ये बारह प्रकार <strong>निम्नलिखित</strong> हैं-</p>\r\n\r\n<table>\r\n  <thead>\r\n    <tr>\r\n      <th>पद</th>\r\n      <th>संबंध</th>\r\n      <th>भूमिका</th>\r\n    </tr>\r\n  </thead>\r\n  <tbody>\r\n    <tr>\r\n      <td>अरि</td>\r\n      <td>शत्रु</td>\r\n      <td>विजिगीषु का पड़ोसी और प्रत्यक्ष शत्रु</td>\r\n    </tr>\r\n    <tr>\r\n      <td>मित्र</td>\r\n      <td>सहयोगी</td>\r\n      <td>अरि का शत्रु, विजिगीषु का स्वाभाविक मित्र</td>\r\n    </tr>\r\n    <tr>\r\n      <td>अरि-मित्र</td>\r\n      <td>अप्रत्यक्ष शत्रु</td>\r\n      <td>अरि का मित्र, विजिगीषु के लिए संभावित खतरा</td>\r\n    </tr>\r\n    <tr>\r\n      <td>मित्र-मित्र</td>\r\n      <td>मित्र का मित्र</td>\r\n      <td>विजिगीषु का परोक्ष सहयोगी</td>\r\n    </tr>\r\n    <tr>\r\n      <td>अरि-मित्र-मित्र</td>\r\n      <td>दूरस्थ शत्रु</td>\r\n      <td>अरि-मित्र का मित्र, अप्रत्यक्ष विरोधी</td>\r\n    </tr>\r\n    <tr>\r\n      <td>पार्ष्णिग्राह</td>\r\n      <td>गुप्त शत्रु</td>\r\n      <td>पीछे से आक्रमण की योजना बनाने वाला</td>\r\n    </tr>\r\n    <tr>\r\n      <td>आक्रंद</td>\r\n      <td>सहयोगी</td>\r\n      <td>पार्ष्णिग्राह का शत्रु, विजिगीषु का परोक्ष मित्र</td>\r\n    </tr>\r\n    <tr>\r\n      <td>पार्ष्णिग्राहसार</td>\r\n      <td>पार्ष्णिग्राह का मित्र</td>\r\n      <td>अप्रत्यक्ष शत्रु</td>\r\n    </tr>\r\n    <tr>\r\n      <td>आक्रन्दसार</td>\r\n      <td>आक्रंद का मित्र</td>\r\n      <td>विजिगीषु का सहयोगी</td>\r\n    </tr>\r\n    <tr>\r\n      <td>मध्यमा</td>\r\n      <td>संतुलक</td>\r\n      <td>विजिगीषु और अरि के बीच शक्ति संतुलन बनाए रखने वाला</td>\r\n    </tr>\r\n    <tr>\r\n      <td>उदासीन</td>\r\n      <td>तटस्थ</td>\r\n      <td>किसी भी पक्ष में नहीं, पर रणनीतिक दृष्टि से महत्वपूर्ण</td>\r\n    </tr>\r\n  </tbody>\r\n</table>\r\n<h3 class=\"atech\">अरि (शत्रु)</h3>\r\n<p><strong>कौटिल्य के मंडल सिद्धांत</strong> में ‘अरि’ वह राजा होता है जो <i>विजिगीषु</i> (विजय की इच्छा रखने वाला राजा) का सीधा पड़ोसी होता है। चूंकि दोनों की सीमाएं मिलती हैं और दोनों का विस्तार एक-दूसरे के लिए खतरा बन सकता है, इसलिए उन्हें स्वाभाविक रूप से एक-दूसरे का शत्रु माना जाता है। कौटिल्य के अनुसार, पड़ोसी राज्य से सबसे अधिक खतरा होता है, इसलिए उसे <strong>प्राथमिक शत्रु</strong> मानकर रणनीति बनानी चाहिए। ‘अरि’ को कमजोर करने के लिए विजिगीषु को उसके पड़ोसियों से मित्रता करनी चाहिए।</p>\r\n\r\n<h3 class=\"atech\">मित्र</h3>\r\n<p>‘मित्र’ वह राजा होता है जो विजिगीषु के शत्रु (अरि) का पड़ोसी होता है। इस कारण से वह अरि के प्रभाव से भी खतरे में रहता है और इसलिए वह स्वाभाविक रूप से विजिगीषु का सहयोगी होता है। कौटिल्य के अनुसार, मित्रता का आधार <strong>साझा शत्रु</strong> होता है। मित्र को सदैव <strong>सशक्त</strong> बनाए रखना चाहिए ताकि वह समय पर सहायता कर सके। मित्रता का संबंध राजनीतिक लाभ, सैन्य सहयोग, और आर्थिक लेन-देन पर आधारित होता है, न कि भावनात्मक संबंधों पर।</p>\r\n\r\n<h3 class=\"atech\">अरि-मित्र</h3>\r\n<p>अरि-मित्र वह राजा होता है जो विजिगीषु के शत्रु का मित्र होता है। यह राज्य प्रत्यक्ष रूप से विजिगीषु से नहीं जुड़ा होता, परंतु अरि का सहयोगी होने के कारण वह विजिगीषु के लिए खतरा बन सकता है। यह अप्रत्यक्ष शत्रु होता है और अक्सर अरि की मदद से विजिगीषु को हानि पहुँचाने का प्रयास करता है। कौटिल्य के अनुसार, ऐसे राज्यों पर विशेष निगरानी रखनी चाहिए और भेद या साम के माध्यम से इनसे निपटना चाहिए।</p>\r\n\r\n<h3 class=\"atech\">मित्र-मित्र</h3>\r\n<p>मित्र-मित्र वह राजा होता है जो विजिगीषु के मित्र का मित्र होता है। यह विजिगीषु के हित में कार्य करने वाला परोक्ष सहयोगी होता है। चूंकि वह उसके मित्र के पक्ष में होता है, इसलिए वह भी विजिगीषु का समर्थक बन जाता है। कौटिल्य के अनुसार, ऐसे राज्यों को भी अपनी रणनीति में शामिल करना चाहिए ताकि मित्रता की श्रृंखला और अधिक मजबूत हो और शत्रु पक्ष की घेराबंदी की जा सके।</p>\r\n\r\n<h3 class=\"atech\">अरि-मित्र-मित्र</h3>\r\n<p>यह वह राजा होता है जो अरि-मित्र का मित्र होता है। यह राज्य विजिगीषु से भले ही दूर हो, लेकिन शत्रु के सहयोगी की सहायता करने के कारण इसका दृष्टिकोण विरोधी हो सकता है। यह मंडल में तृतीय स्तर का अप्रत्यक्ष शत्रु होता है। कौटिल्य इसे भी संभावित खतरे के रूप में देखते हैं और सुझाते हैं कि यदि आवश्यक हो, तो ऐसे राज्यों को भेद या दंड से काबू में रखना चाहिए।</p>\r\n\r\n<h3 class=\"atech\">पार्ष्णिग्राह</h3>\r\n<p><strong>पार्ष्णिग्राह</strong> वह राजा होता है जो विजिगीषु के पीछे की ओर स्थित होता है और गुप्त रूप से उस पर आक्रमण करने की योजना बनाता है। यह राजा अवसर की तलाश में रहता है कि कब विजिगीषु कमजोर पड़े और वह उस पर वार करे। इसे <i>छिपा हुआ शत्रु</i> भी कहा जाता है। कौटिल्य ने इसे गंभीर खतरा माना है और कहा है कि ऐसे राजा पर विशेष दृष्टि रखनी चाहिए और कूटनीतिक उपायों से उसे नियंत्रित करना चाहिए।</p>\r\n\r\n<h3 class=\"atech\">आक्रंद</h3>\r\n<p>आक्रंद वह राजा होता है जो पार्ष्णिग्राह का शत्रु होता है। चूंकि पार्ष्णिग्राह विजिगीषु के लिए खतरा है, इसलिए उसका शत्रु आक्रंद, विजिगीषु के लिए सहयोगी हो सकता है। कौटिल्य के अनुसार, आक्रंद को विजिगीषु अपने पक्ष में लेकर पार्ष्णिग्राह के खतरे को संतुलित कर सकता है। यह रणनीतिक दृष्टिकोण से महत्वपूर्ण होता है क्योंकि इससे पीछे के हमले से सुरक्षा मिलती है।</p>\r\n\r\n<h3 class=\"atech\">पार्ष्णिग्राहसार</h3>\r\n<p>यह वह राजा होता है जो पार्ष्णिग्राह का मित्र होता है। यह विजिगीषु के लिए एक और अप्रत्यक्ष खतरा बनता है क्योंकि यह पार्ष्णिग्राह को शक्ति और सहायता प्रदान करता है। पार्ष्णिग्राहसार को शत्रु के पक्ष में सक्रिय मानकर उससे सतर्क रहना चाहिए। कौटिल्य ने कहा है कि ऐसे राज्यों के खिलाफ मित्र समूह को सुदृढ़ करके मोर्चा तैयार करना चाहिए।</p>\r\n\r\n<h3 class=\"atech\">आक्रन्दसार</h3>\r\n<p>आक्रन्दसार वह राजा होता है जो आक्रंद का मित्र होता है। यह राज्य विजिगीषु के लिए सहयोगी हो सकता है क्योंकि यह पार्ष्णिग्राह के विरोध में होता है। चूंकि यह आक्रंद की मदद करता है, इसलिए इसका समर्थन भी विजिगीषु को पार्ष्णिग्राह के खतरे से निपटने में मदद करता है। कौटिल्य इसे लाभकारी सहयोगी मानते हैं।</p>\r\n\r\n<h3 class=\"atech\">मध्यमा</h3>\r\n<p>मध्यमा वह राजा होता है जो विजिगीषु और अरि – दोनों से भौगोलिक दूरी पर होता है, परंतु दोनों से शक्ति में तुलनीय होता है। यह अक्सर दोनों पक्षों को नियंत्रित करने या संतुलन बनाए रखने की कोशिश करता है। मध्यमा अपनी शक्ति और स्थिति का उपयोग करके गठबंधनों और संधियों के माध्यम से प्रभाव स्थापित करता है। कौटिल्य ने इसे संभावित सहयोगी या प्रतिस्पर्धी दोनों रूपों में देखा है।</p>\r\n\r\n<h3 class=\"atech\">उदासीन</h3>\r\n<p>उदासीन वह राजा होता है जो विजिगीषु और अरि दोनों से दूरी बनाए रखता है और किसी पक्ष में हस्तक्षेप नहीं करता। वह तटस्थ होता है और सामान्यतः अपने ही राज्य की सुरक्षा और विकास में रुचि रखता है। परंतु परिस्थितियों के अनुसार वह किसी एक पक्ष की ओर झुक सकता है। कौटिल्य ने सुझाया है कि ऐसे राज्यों को प्रभावित करके उन्हें अपने पक्ष में लाना विदेश नीति का भाग होना चाहिए।</p>\r\n\r\n<p><strong>कौटिल्य का यह सिद्धांत</strong> यह सुझाव देता है कि एक राज्य को अपने संबंधों की राजनीति को समझने और उसकी स्थिति के आधार पर अपनी रणनीति बनानी चाहिए। इस सिद्धांत के अनुसार, राज्यों के बीच दोस्ती और शत्रुता की स्थिति के आधार पर कूटनीतिक कदम उठाए जाते हैं।</p>\r\n<p><strong>कौटिल्य ने यह भी कहा</strong> कि राज्य को सदैव अपने शत्रु से निपटने के लिए तैयार रहना चाहिए, साथ ही मित्रों से सहयोग और शत्रु के खिलाफ ताकतवर रणनीति अपनानी चाहिए। वह मानते थे कि समय के साथ इस मंडल की स्थिति बदलती रहती है, और राज्य को अपनी कूटनीति में लचीलापन बनाए रखना चाहिए ताकि वह अपने राजनीतिक उद्देश्यों को प्राप्त कर सके।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>कौटिल्य का मंडल सिद्धांत एक अत्यंत व्यावहारिक और रणनीतिक दृष्टिकोण है जो यह बताता है कि किसी भी राष्ट्र की विदेश नीति कैसे भूगोल, शक्ति संतुलन और अपने हितों पर आधारित होनी चाहिए। यह सिद्धांत आज भी भारत सहित अनेक देशों की विदेश नीति में प्रत्यक्ष या अप्रत्यक्ष रूप से परिलक्षित होता है। कौटिल्य का यह विचार आधुनिक राजनीति विज्ञान में एक अमूल्य योगदान है।</p>\r\n',15,'2025-06-02 14:35:35','2025-06-02 16:04:57','','Publish',0,'open',64,117),('कौटिल्य का सप्तांग सिद्धांत क्या है','kautilyas-seventh-state-theory',2,'<p><strong>प्राचीन भारत में राज्य की अवधारणा</strong> अत्यंत वैज्ञानिक और गूढ़ मानी जाती थी। <i>हिंदू राज्यशास्त्र</i> के आचार्यों ने राज्य के स्वरूप और तत्वों का गहन विश्लेषण किया है। इन्हीं विचारों का समन्वय <strong>कौटिल्य के अर्थशास्त्र</strong> में \"<strong>सप्तांग राज्य</strong>\" के रूप में किया गया है। सप्तांग राज्य की कल्पना में राज्य को <i>एक शरीर की संज्ञा</i> दी गई है, जिसके सात अवयव शरीर के अंगों की तरह कार्य करते हैं।</p>\r\n\r\n<p><i>महाभारत के शांतिपर्व</i> और <i>शुक्रनीतिसार</i> में भी इस अवधारणा का उल्लेख मिलता है। <strong>शुक्रनीति</strong> में <strong>राजा को मस्तिष्क, अमात्य को आंखें, जनपद को शरीर, दुर्ग को हाथ, कोश को मुख, बल को मन और मित्र को हृदय</strong> के समान बताया गया है। इसी प्रकार <strong>कौटिल्य</strong> ने भी इन सात अंगों को राज्य की \"<strong>सप्त प्रकृतियां</strong>\" कहा है।</p>\r\n\r\n<h2>राज्य के सात अंग</h2>\r\n<p><strong>कौटिल्य</strong> ने सप्तांग राज्य के जिन सात तत्वों की व्याख्या की है, वे निम्नलिखित हैं-</p>\r\n\r\n<h3 class=\"atech\">स्वामी (राजा)</h3>\r\n<p>‘<strong>सप्तांग सिद्धांत</strong>’ से संबंधित सभी स्रोत ग्रंथों में, राज्य के प्रधान के लिए <strong>‘स्वामी’</strong> शब्द का उल्लेख हुआ है। जिसका अर्थ है, <i>अधिपति</i>। कौटिल्य के अनुसार <strong>‘स्वामी’</strong> को <i>अभिजात्य, प्रज्ञावान, शिक्षित, उत्साही, युद्ध कला में चतुर</i> तथा <i>अन्य उत्तम चारित्रिक गुणों</i> से संपन्न होना चाहिए तथा <i>काम, क्रोध, लोभ, मोह</i> आदि दुर्गुणों से दूर रहना चाहिए। कौटिल्य के अनुसार <strong>स्वामी</strong> के दो मुख्य कर्तव्य होते हैं – प्रथम, <i>उसे अपने प्रजाजनों के सुख और हित पर पूर्ण ध्यान देना चाहिए</i> तथा द्वितीय, <i>अन्य राज्यों के क्रियाकलापों पर तीक्ष्ण दृष्टि रखनी चाहिए</i> ताकि उसके राज्य पर खतरा उत्पन्न ना हो।</p>\r\n\r\n<h3 class=\"atech\">अमात्य (मंत्री)</h3>\r\n<p><strong>अमात्य</strong> वह व्यक्ति होता है जो शासन संचालन में राजा की सहायता करता है। राजा की नीति का कार्यान्वयन अमात्य करता है। कौटिल्य ने कहा है – \"<i>एक अकेला आदमी कोई निर्णय नहीं ले सकता।</i>\" <strong>‘अर्थशास्त्र’</strong> के अनुसार, <strong>‘अमात्य’</strong> एक अस्थाई <i>‘सेवा-संवर्ग’</i> के सदस्य थे तथा इसी संवर्ग से <i>प्रधान पुरोहित, मंत्री, समाहर्ता, कोषपाल</i> आदि उच्च पदाधिकारियों की नियुक्ति की व्यवस्था की गई थी।</p>\r\n\r\n<h3 class=\"atech\">जनपद</h3>\r\n<p>राज्य का तीसरा अंग <strong>‘जनपद’</strong> है। इसका शाब्दिक अर्थ <i>‘जनजातीय बस्ती’</i> होता है। मौर्योत्तर ग्रंथों <i>‘मनुस्मृति’</i> एवं <i>‘विष्णु स्मृति’</i> में <strong>‘जनपद’</strong> का उल्लेख <i>‘राष्ट्र’</i> के रूप में हुआ है। <strong>‘अर्थशास्त्र’</strong> की परिभाषा के अनुसार, <strong>‘जनपद’</strong> में <i>भू-भाग और जनसंख्या</i> दोनों का समावेश होता है। भू- भाग में <i>अच्छी जलवायु, चारागाह, उपजाऊ भूमि, जंगल, विकसित जल एवं स्थल मार्ग, देवालय, विश्राम-गृह, नदियां एवं खनिज</i> पदार्थ होने चाहिए। इसमें <i>परिश्रमी कृषकों</i> का निवास होना चाहिए, जो <strong>‘कर’ और ‘दंड’</strong> का बोझ वहन कर सकें।</p>\r\n\r\n<h3 class=\"atech\">दुर्ग</h3>\r\n<p><strong>‘कौटिल्य’</strong> के अनुसार राज्य की सुरक्षा के लिए <strong>सुदृढ़ दुर्ग</strong> आवश्यक है। ये दुर्ग हैं – <i>‘औदक दुर्ग’</i> (जल या गहरी खाई से घिरा), <i>‘पर्वत दुर्ग’</i> (पर्वत श्रेणियों से घिरा), <i>‘धान्यवन दुर्ग’</i> (मरुस्थलीय प्रदेश में बना), <i>‘वन दुर्ग’</i> (बीहड़ जंगलों से घिरा)। ‘दुर्ग’ <i>मगरमच्छ और कमल</i> से भरी तीन खाईयों से घिरा होना चाहिए। <i>गुप्त द्वार, पत्थर की चारदीवारी</i> और <i>सुरक्षा के विशेष प्रबंध</i> आवश्यक माने गए हैं।</p>\r\n\r\n<h3 class=\"atech\">कोष (राजकोष)</h3>\r\n<p><strong>‘कोष’</strong>, ‘अर्थशास्त्र’ और अन्य स्रोतों में <strong>पांचवें अंग</strong> के रूप में उद्धृत है। <strong>राज्य के प्रत्येक कार्य के लिए धन अत्यावश्यक</strong> है। <strong>कौटिल्य</strong> ने <i>कृषि, पशुपालन और व्यापार</i> को आजीविका का मुख्य साधन तथा <strong>भूमि को राजस्व</strong> का प्रमुख स्रोत माना है। <i>अन्न के षष्ठ भाग</i> और <i>व्यापारिक वस्तुओं के दशमांश</i> को लेकर कोष संग्रह की बात कही गई है। <i>प्रचुर सोना, चांदी, बहुमूल्य रत्न और मुद्राएं</i> इसमें रहनी चाहिए।</p>\r\n\r\n<h3 class=\"atech\">दंड (सेना)</h3>\r\n<p><strong>‘दंड’</strong> सप्तांग राज्य का <strong>छठा अंग</strong> है, जिसका अर्थ है <strong>सेना</strong> या <i>बल प्रयोग की शक्ति</i>। कौटिल्य के अनुसार इसमें <i>पुश्तैनी, भाड़े के, वन और निगम सैनिक</i> होते हैं। <i>शांतिपर्व</i> में इसे <strong>अष्टांगबल</strong> कहा गया है। <i>मनुस्मृति</i> में दंड को <strong>शासन, सुरक्षा और धर्म का रक्षक</strong> बताया गया है। <strong>कौटिल्य</strong> ने <strong>क्षत्रियों</strong> को श्रेष्ठ सैनिक माना, पर <i>वैश्यों-शूद्रों</i> को भी संख्या बल हेतु शामिल करने की बात कही। <strong>सेना अनुशासित और संतुष्ट</strong> होनी चाहिए।</p>\r\n\r\n<h3 class=\"atech\">मित्र</h3>\r\n<p>राज्य के <strong>सप्तांग सिद्धांत</strong> में <strong>‘मित्र’</strong> सातवां और अंतिम अंग है। इसे कुछ ग्रंथों में <strong>‘सुहृद’</strong> भी कहा गया है। <strong>कौटिल्य</strong> के अनुसार, <strong>मित्र</strong> ऐसा होना चाहिए जो <i>कुलीन, भरोसेमंद, नेक और पीढ़ियों से संबंध रखने वाला</i> हो। ऐसा मित्र जिस पर <strong>पूरा विश्वास</strong> किया जा सके और जो <i>ज़रूरत पड़ने पर तुरंत मदद</i> के लिए तैयार हो। जो राजा <strong>विजय चाहता है</strong> (विजीगिषु राजा), उसे ऐसा मित्र चाहिए जिससे <i>झगड़े या मतभेद की कोई गुंजाइश न हो</i>।</p>\r\n\r\n<h2>सप्तांग राज्य सिद्धांत का महत्व</h2>\r\n<p><strong>कौटिल्य का सप्तांग राज्य सिद्धांत</strong> <i>भारतीय राज्यशास्त्र</i> में अत्यंत महत्वपूर्ण और प्रासंगिक सिद्धांत है। यह सिद्धांत न केवल <strong>प्राचीन भारत</strong> के प्रशासन और शासन की संरचना को स्पष्ट करता है, बल्कि इसके माध्यम से राज्य के <i>विभिन्न अंगों के बीच परस्पर संबंध</i> और उनकी कार्यप्रणाली को भी समझा जा सकता है।</p>\r\n\r\n<h3 class=\"atech\">समग्र राज्य संरचना का ज्ञान</h3>\r\n<p><strong>कौटिल्य का सप्तांग राज्य सिद्धांत</strong> राज्य की सभी तत्वों का <i>समग्र और वैज्ञानिक रूप से विश्लेषण</i> करता है। <strong>राजा, मंत्री, जनपद, दुर्ग, कोष, सेना और मित्र</strong> – ये सभी तत्व एक दूसरे के साथ <i>सहयोग करते हुए</i> राज्य की संरचना को बनाए रखते हैं। राज्य के प्रत्येक अंग की अपनी <i>विशेष भूमिका और जिम्मेदारी</i> होती है, जो राज्य के <strong>सुचारु संचालन</strong> के लिए अनिवार्य है।</p>\r\n\r\n<h3 class=\"atech\">प्रशासनिक दक्षता और संतुलन</h3>\r\n<p>यह सिद्धांत राज्य के <strong>विभिन्न अंगों में संतुलन और समन्वय</strong> स्थापित करने की आवश्यकता को बताता है। कौटिल्य ने यह स्पष्ट किया है कि प्रत्येक तत्व (<i>राजा, मंत्री, सेना, कोष</i> आदि) <strong>अपनी भूमिका में सक्षम</strong> होना चाहिए और उनके कार्य <i>एक दूसरे के साथ मेल खाते हुए</i> होने चाहिए। इससे <strong>प्रशासनिक दक्षता</strong> बढ़ती है और राज्य की सत्ता <i>मजबूत</i> होती है।</p>\r\n\r\n<h3 class=\"atech\">राज्य की सुरक्षा और रक्षा</h3>\r\n<p><strong>सप्तांग राज्य सिद्धांत</strong> में <strong>दुर्ग और सेना</strong> को विशेष महत्व दिया गया है। राज्य की <i>सुरक्षा और बाहरी आक्रमण से रक्षा</i> के लिए यह आवश्यक है कि राज्य के पास <strong>एक सक्षम सेना</strong> और <strong>मजबूत दुर्ग</strong> हो। यह सिद्धांत <i>आज भी राज्य सुरक्षा के संदर्भ में प्रासंगिक</i> है, क्योंकि कोई भी राज्य <strong>अपनी रक्षा के बिना</strong> स्थायित्व प्राप्त नहीं कर सकता।</p>\r\n\r\n<h3 class=\"atech\">धन और संसाधन का महत्व</h3>\r\n<p><strong>कोष का सिद्धांत</strong> यह बताता है कि किसी भी राज्य की सफलता के लिए <strong>वित्तीय संसाधन</strong> का होना आवश्यक है। एक <i>समृद्ध राज्य कोष</i> से ही अपने <i>प्रशासनिक खर्चे, सेना और जनकल्याण</i> कार्यों का संचालन कर सकता है। इससे यह सिद्धांत <strong>आर्थिक प्रबंधन</strong> की आवश्यकता और महत्व को भी उजागर करता है।</p>\r\n\r\n<h3 class=\"atech\">राज्य के अंदर और बाहर रिश्तों का प्रबंधन</h3>\r\n<p><strong>सप्तांग राज्य सिद्धांत</strong> में <strong>मित्र की अवधारणा</strong> राज्य के <i>बाहरी रिश्तों</i> को लेकर एक <i>सहयोगी दृष्टिकोण</i> प्रस्तुत करती है। यह सिद्धांत यह बताता है कि किसी भी राज्य का अस्तित्व केवल <i>अपनी शक्ति पर निर्भर</i> नहीं होता, बल्कि उसे <strong>मित्र राज्यों</strong> के साथ <i>अच्छे संबंध</i> स्थापित करने होते हैं ताकि <strong>आपसी सहयोग</strong> और सहायता की स्थिति में <strong>युद्ध की स्थिति से बचा</strong> जा सके।</p>\r\n\r\n<h3 class=\"atech\">वैज्ञानिक दृष्टिकोण</h3>\r\n<p><strong>कौटिल्य का सप्तांग राज्य सिद्धांत</strong> <i>एक विज्ञान की तरह</i> प्रस्तुत किया गया था। राज्य की <strong>स्थिरता और प्रगति</strong> के लिए <strong>सभी अंगों का सामंजस्यपूर्ण कार्यान्वयन</strong> आवश्यक था। इसे <i>वैज्ञानिक दृष्टिकोण</i> से देखा जाए तो यह सिद्धांत <strong>आज भी प्रासंगिक</strong> है, क्योंकि यह <i>राज्य के प्रशासन और उसकी स्थिरता</i> को <strong>महत्वपूर्ण अंगों के समुचित संतुलन</strong> से जोड़ता है।</p>\r\n\r\n<h3 class=\"atech\">राजनीतिक और सामाजिक दृष्टिकोण से महत्व</h3>\r\n<p>राज्य के <strong>सभी अंगों</strong> को ध्यान में रखते हुए <strong>कौटिल्य</strong> ने एक <i>सामाजिक और राजनीतिक समन्वय</i> की आवश्यकता को रेखांकित किया। यह सिद्धांत <strong>राजनीति और समाज</strong> के बीच एक <i>गहरे संबंध</i> को दर्शाता है, जिसमें राज्य के <strong>सभी अंग</strong> अपने <i>कर्तव्यों का पालन</i> करते हुए <strong>समाज की भलाई</strong> के लिए काम करते हैं।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>सप्तांग राज्य की अवधारणा</strong> न केवल <strong>प्राचीन भारतीय राजनीतिक चिंतन</strong> की गहराई को दर्शाती है, बल्कि यह <i>आज भी प्रशासनिक संगठन और संचालन</i> के दृष्टिकोण से प्रासंगिक है। यह सिद्धांत <strong>राज्य के समग्र विकास, सुरक्षा और स्थायित्व</strong> को <i>संतुलित ढंग</i> से प्रस्तुत करता है। अतः यह कहना गलत नहीं होगा कि <strong>कौटिल्य का सप्तांग सिद्धांत</strong> <i>पाश्चात्य राज्य-सिद्धांतों</i> की तुलना में कहीं अधिक <strong>व्यापक, वैज्ञानिक और सुव्यवस्थित</strong> है।</p>\r\n',9,'2025-06-02 14:35:35','2025-06-02 16:43:32','','Publish',0,'open',65,118),('डॉ भीमराव अंबेडकर और उनके विचार','dr-bhimrao-ambedkar-and-his-views',2,'<p><strong>डॉ भीमराव अंबेडकर</strong> भारतीय इतिहास के उन महान विचारकों में से एक हैं जिन्होंने <strong>सामाजिक न्याय</strong>, <strong>समानता</strong>, <strong>धर्मनिरपेक्षता</strong> और <strong>मानवाधिकार</strong> के लिए अपना संपूर्ण जीवन समर्पित कर दिया। वे केवल एक राजनीतिक या संविधान निर्माता नहीं थे अपितु वे एक <strong>महान दार्शनिक</strong>, <strong>समाजशास्त्री</strong> और <strong>सामाजिक क्रांतिकारी</strong> भी थे। उनके विचार एक ऐसे समाज निर्माण करना था जहाँ सभी को समान अधिकार मिले।</p>\r\n<p>डॉ भीमराव अंबेडकर का जन्म <strong>14 अप्रैल 1891</strong> <strong>मध्यप्रदेश के महू</strong> में हुआ। वे <strong>दलित परिवार</strong> में पैदा हुए थे। उन्होंने अपनी शिक्षा की शुरुआत अत्यंत कठिन परिस्थितियों में की। उन्हें बचपन से ही <strong>जातिवाद</strong> का सामना करना पड़ा। इनके पिता <strong>रामजी मालोजी सकपाल</strong> <strong>ब्रिटिश भारतीय सेना</strong> में <strong>सूबेदार</strong> के पद पर कार्यरत थे। उनकी नौकरी के कारण उनको कुछ हद तक सामाजिक सुरक्षा प्राप्त था।</p>\r\n<p>जब अंबेडकर लगभग 6 वर्ष के थे तब उनकी माता <strong>भीमाबाई</strong> का निधन हो गया। इसके बाद उनकी मौसी ने उनकी देखभाल की। <strong>सतारा</strong> में प्रारंभिक शिक्षा प्राप्त करने के बाद ही आगे की पढ़ाई के लिए <strong>बंबई (मुंबई)</strong> चले गए। <strong>मुंबई के एल्फिंस्टन हाई स्कूल</strong> में वे दलित समुदाय के पहले छात्र थे। अपनी स्कूल शिक्षा के दौरान उन्हें लगातार <strong>जातिगत भेदभाव</strong> का सामना करना पड़ा।</p>\r\n<p><strong>1906</strong> में लगभग 15 वर्ष की उम्र में इनका विवाह <strong>नौ वर्षीया रमाबाई</strong> से हुआ। उन्होंने <strong>1907</strong> में 10वीं पास की। इसके बाद आगे की पढ़ाई के लिए वे <strong>इंग्लैंड</strong> गए। उन्होंने <strong>लंदन स्कूल ऑफ इकोनॉमिक्स</strong> से <strong>अर्थशास्त्र में डॉक्टरेट</strong> की डिग्री प्राप्त की। अंबेडकर की शिक्षा ने उन्हें न केवल <strong>भारतीय समाज के सांस्कृतिक और सामाजिक मुद्दों</strong> को समझने की गहरी दृष्टि दी बल्कि उन्होंने एक ऐसे समाज के निर्माण का सपना देखा जहाँ सभी नागरिकों को समान अधिकार और सम्मान मिले।</p>\r\n<h2>अंबेडकर का जातिवाद को लेकर विचार</h2>\r\n<p>अंबेडकर का जीवन मुख्य रूप से भारतीय समाज में व्याप्त <strong>जातिवाद के खिलाफ संघर्ष</strong> से जुड़ा है। उन्होंने बचपन से ही जातिवाद का सामना किया था। इनका मानना था कि भारतीय समाज में सबसे बड़ी बुराई <strong>जाति प्रथा</strong> है जिसने समाज में <strong>असमानता, भेदभाव और अत्याचार</strong> को जन्म दिया। उनका मानना था कि जब तक समाज में जाति व्यवस्था रहेगी तब तक समानता की कोई संभावना नहीं हो सकती।</p>\r\n<p>उन्होंने जातिवाद के खिलाफ आंदोलन चलाया। उन्होंने <i>\"जाति का उन्मूलन (Annihilation of Caste)\"</i> के विचार का समर्थन किया। इसका मूल केंद्र <strong>सामाजिक न्याय</strong> था। वे मानते थे जब तक समाज में सभी वर्गों को समान अधिकार और सम्मान नहीं मिलेगा तब तक किसी भी प्रकार का <strong>लोकतंत्र</strong> विकसित नहीं हो सकता। उनका मानना था कि <strong>राजनीति स्वतंत्रता</strong> तब तक अधूरी है जब तक समाज के वंचितों को <strong>सामाजिक और आर्थिक स्वतंत्रता</strong> न मिले। उन्होंने स्पष्ट रूप से कहा है - <i>\"एक समाज जिसमें एक वर्ग विशेष को जन्म के आधार पर ऊँचा और दूसरे को नीचा माना जाता है, वह कभी भी समरस नहीं हो सकता।\"</i></p>\r\n<h2>अंबेडकर का शिक्षा को लेकर विचार</h2>\r\n<p>अंबेडकर का मानना था कि <strong>शिक्षा</strong> ही एक ऐसा साधन है जो व्यक्ति को जागरूक करता है और समाज में परिवर्तन लाने की क्षमता देता है। उनका प्रसिद्ध नारा है - <i>\"शिक्षित बनो, संगठित रहो और संघर्ष करो।\"</i> उनका यह नारा केवल नारा ही नहीं अपितु एक <strong>व्यापक क्रांति</strong> का आह्वान था।</p>\r\n<p>वे इस बात को अच्छी तरह से जानते थे कि बिना शिक्षा के व्यक्ति न तो अपने अधिकारों को समझ सकता है और न ही उनके लिए संघर्ष कर सकता है। इसलिए उन्होंने कई शैक्षणिक संस्थानों की स्थापना की - <strong>People\'s Education Society (1945)</strong>, <strong>Siddharth College Mumbai (1946)</strong>, <strong>Milind College Aurangabad (1950)</strong> आदि। इसके अलावा अन्य स्कूल तथा कॉलेज की स्थापना या शुरू करने के प्रयासों से योगदान दिया।</p>\r\n<h2>अंबेडकर के महिलाओं को लेकर विचार</h2>\r\n<p>अंबेडकर <strong>महिलाओं के अधिकार और सशक्तिकरण</strong> के प्रबल समर्थक थे। उनके विचार महिलाओं के संबंध में अत्यंत <strong>प्रगतिशील</strong> और <strong>न्यायसंगत</strong> थे। अंबेडकर का मानना था कि पुरुषों के बराबर ही महिलाओं की <strong>शिक्षा, रोजगार, संपत्ति और राजनीति</strong> सहित सभी क्षेत्रों में <strong>समान अधिकार</strong> होना चाहिए।</p>\r\n<p>उन्होंने भारतीय समाज में व्याप्त <strong>लैंगिक भेदभाव</strong> तथा <strong>असमानता</strong> की कड़ी आलोचना की। उनका प्रसिद्ध कथन था - <i>\"मैं किसी समुदाय की प्रगति को महिलाओं द्वारा हासिल की गई प्रगति की डिग्री से मापता हूं।\"</i> उन्होंने महिलाओं के खिलाफ प्रचलित सामाजिक बुराइयों जैसे- <strong>बाल विवाह</strong>, <strong>सती प्रथा</strong>, <strong>विधवा पुनर्विवाह पर रोक</strong> तथा <strong>देवदासी प्रथा</strong> का कड़ा विरोध किया।</p>\r\n<h2>अंबेडकर का आर्थिक विचार</h2>\r\n<p>अंबेडकर का <strong>आर्थिक विचार</strong> अत्यंत प्रभावशाली था। वे एक कुशल अर्थशास्त्री थे और <strong>भारतीय रिजर्व बैंक</strong> की स्थापना में अहम भूमिका निभाई। उनका ध्यान विशेष रूप से <strong>श्रमिकों, किसानों और शोषित वर्ग</strong> की आर्थिक स्थिति पर था। उन्होंने <strong>कृषि सुधारों, भूमि के पुनर्वितरण, सिंचाई प्रणाली</strong> और <strong>औद्योगीकरण</strong> को आवश्यक बताया।</p>\r\n<p>उन्होंने <strong>राज्य नियंत्रित समाजवाद</strong> का समर्थन किया जिसमें प्रमुख उद्योगों और कृषि का स्वामित्व और संचालन <strong>राज्य</strong> के पास हो। उनका मानना था कि <strong>निजी स्वामित्व</strong> से <strong>धन का असमान वितरण</strong> होता है और <strong>शोषण</strong> बढ़ता है। राज्य के नियंत्रण से यह सुनिश्चित किया जा सकेगा कि <strong>संसाधनों का उपयोग सभी के कल्याण</strong> के लिए हो।</p>\r\n<p>उन्होंने औद्योगिक श्रमिकों के लिए <i>\"समान काम के लिए समान वेतन\"</i> के सिद्धांत का समर्थन किया चाहे उनका लिंग कुछ भी हो। संक्षेप में, डॉ. अंबेडकर का <strong>आर्थिक दृष्टिकोण</strong> एक ऐसे <strong>राज्य-नियंत्रित अर्थव्यवस्था</strong> पर आधारित था जो <strong>सामाजिक न्याय, समानता और सभी के कल्याण</strong> को सुनिश्चित करे।</p>\r\n<h2>भारतीय संविधान</h2>\r\n<p><strong>डॉ. अंबेडकर</strong> <strong>भारतीय संविधान</strong> के निर्माता के रूप में जाने जाते हैं। यह उनके विचारों का <strong>सजीव प्रतीक</strong> है। भारतीय संविधान में उन्होंने <strong>समाज के सभी वर्गों को समान अधिकार</strong> देने का प्रयास किया। उनका मानना था कि एक मजबूत और <strong>लोकतांत्रिक देश</strong> के लिए एक <strong>समान और न्यायपूर्ण नियम</strong> या <strong>संविधान</strong> होना चाहिए।</p>\r\n<p>अंबेडकर ने संविधान में विशेष रूप से <strong>दलितों, पिछड़े वर्गों, महिलाओं और अल्पसंख्यकों</strong> के अधिकारों को सुरक्षा प्रदान करने के लिए कई प्रावधान जोड़े। उन्होंने संविधान में यह सुनिश्चित किया कि कोई भी व्यक्ति <strong>जाति, धर्म या लिंग</strong> के आधार पर <strong>भेदभाव</strong> का शिकार न हो।</p>\r\n<p>भारतीय संविधान में अंबेडकर के योगदान को भुलाया नहीं जा सकता क्योंकि यह संविधान आज भी <strong>भारतीय लोकतंत्र</strong> का मूल स्तंभ है। उन्होंने संविधान के माध्यम से भारतीय समाज को <strong>समानता और न्याय</strong> का मार्ग दिखाया।</p>\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार उपरोक्त अध्ययन से हम पाते हैं कि <strong>डॉ. भीमराव अंबेडकर</strong> के विचार <strong>भारतीय समाज</strong> के लिए एक <strong>प्रेरणा स्रोत</strong> हैं। उन्होंने <strong>जातिवाद, भेदभाव और असमानता</strong> के खिलाफ संघर्ष किया और एक ऐसे समाज की कामना की जिसमें सभी को <strong>समान अधिकार</strong> मिले। अंततः यह कहा जा सकता है कि <strong>डॉ. भीमराव अंबेडकर</strong> के विचार केवल कुछ वर्षों के लिए नहीं बल्कि <strong>समस्त मानवता</strong> के लिए हैं।</p>\r\n',11,'2025-06-03 05:35:53','2025-06-03 05:47:25','','Publish',0,'open',60,119),('प्लेटो का योगदान और विचार क्या है','platos-contribution-and-idea',2,'<p><strong>प्लेटो (Plato)</strong> प्राचीन यूनान के एक महान दार्शनिक थे। उनका जन्म <i>लगभग 427 ईसा पूर्व</i> एथेंस में हुआ था। वे <strong>सुकरात के शिष्य</strong> और <strong>अरस्तू के गुरु</strong> थे। प्लेटो का दार्शनिक विचार पूरी <i>पश्चिमी विचारधारा की नींव</i> माना जाता है। उन्होंने <strong>राजनीति, दर्शन, शिक्षा, न्याय और आत्मा</strong> जैसे विषयों पर गहराई से विचार किया।</p>\r\n\r\n<p>प्लेटो का सबसे प्रसिद्ध और मौलिक सिद्धांत <strong>\"रूपवाद\" या \"आदर्श रूप का सिद्धांत\" (Theory of Forms)</strong> है। इसके अनुसार, इस संसार की हर वस्तु केवल एक अपूर्ण छाया है किसी <strong>शाश्वत, पूर्ण और अमर \"रूप\"</strong> की, जो एक <i>दैविक या आध्यात्मिक जगत</i> में स्थित है। वे कहते हैं कि - <i>\"जो कुछ भी हमें इस संसार में दिखाई देता है, वह सत्य नहीं है, बल्कि सत्य उसकी परछाई है।\"</i></p>\r\n\r\n<p><i>उदाहरण स्वरूप –</i> हम जो एक सुंदर फूल देखते हैं, वह \"<strong>सौंदर्य के आदर्श रूप</strong>\" का केवल एक <i>क्षणिक और अधूरा प्रतिबिंब</i> है। यही बात हर वस्तु – जैसे <i>कुर्सी, न्याय, सच्चाई, प्रेम</i> – पर लागू होती है।</p>\r\n\r\n<h2><strong>जीवन और परिचय</strong></h2>\r\n<p>प्लेटो का वास्तविक नाम \"<i>अरिस्टोक्लीज़</i>\" था, लेकिन वे अपने चौड़े शरीर (<i>platos = broad</i>) के कारण प्लेटो नाम से प्रसिद्ध हुए। वे एथेंस के एक कुलीन परिवार से थे और प्रारंभिक जीवन में <i>कविता तथा संगीत</i> की ओर रुचि रखते थे। <strong>सुकरात के संपर्क में आने</strong> के बाद उन्होंने <strong>दर्शन को ही अपने जीवन का लक्ष्य</strong> बना लिया। <i>सुकरात की मृत्यु</i> ने उन्हें गहरा प्रभावित किया, जिसके बाद वे <i>कई देशों की यात्रा</i> पर निकले, जिनमें मिस्र और इटली शामिल हैं। बाद में उन्होंने एथेंस में <strong>Academy</strong> नामक शिक्षण संस्था की स्थापना की, जिसे <strong>यूरोप की पहली विश्वविद्यालयीय संस्था</strong> माना जाता है।</p>\r\n\r\n<h2><strong>आत्मा का सिद्धांत</strong></h2>\r\n<p>प्लेटो ने आत्मा को <strong>अमर और शाश्वत</strong> माना। उनका मानना था कि <i>आत्मा शरीर से पहले और बाद में भी अस्तित्व में रहती है</i>। शरीर केवल आत्मा का एक <i>अस्थायी वास</i> है। आत्मा के तीन भाग होते हैं</p>\r\n<ul>\r\n    <li><p><strong>बुद्धि (Reason)</strong> – जो सोचती है और निर्णय लेती है।</p></li>\r\n    <li><p><strong>उत्साह/साहस (Spirit)</strong> – जो <i>क्रोध, गर्व, और सम्मान</i> से जुड़ा है।</p></li>\r\n    <li><p><strong>इच्छा (Appetite)</strong> – जो <i>भूख, प्यास, यौन-इच्छा</i> जैसी भौतिक इच्छाओं से संबंधित है।</p></li>\r\n</ul>\r\n<p>जब आत्मा का प्रत्येक भाग अपने कार्य को निभाता है और नियंत्रण में रहता है, तभी व्यक्ति <strong>न्यायप्रिय और संतुलित</strong> होता है।</p>\r\n\r\n<h2><strong>न्याय का सिद्धांत</strong></h2>\r\n<p>प्लेटो के अनुसार न्याय केवल <i>कानून का पालन</i> नहीं है, बल्कि यह <strong>आत्मा और समाज दोनों में संतुलन</strong> की स्थिति है। उन्होंने अपनी पुस्तक <strong>The Republic</strong> में न्याय को इस रूप में परिभाषित किया - <i>\"न्याय तब होता है जब प्रत्येक व्यक्ति या वर्ग अपने कार्य को करता है और दूसरे के कार्य में हस्तक्षेप नहीं करता।\"</i> उनके अनुसार व्यक्ति के भीतर भी न्याय तभी होता है जब आत्मा के तीनों भाग – <strong>बुद्धि, साहस और इच्छा</strong> – संतुलन में रहते हैं।</p>\r\n\r\n<h2><strong>आदर्श राज्य</strong></h2>\r\n<p>प्लेटो ने \"<strong>आदर्श राज्य</strong>\" (Ideal State) की संकल्पना प्रस्तुत की, जिसमें समाज को तीन वर्गों में बाँटा गया-</p>\r\n<ul>\r\n    <li><p><strong>शासक (Rulers/Philosophers)</strong> – जिनके पास <i>ज्ञान</i> होता है और जो <i>राज्य का संचालन</i> करते हैं।</p></li>\r\n    <li><p><strong>रक्षक (Auxiliaries/Soldiers)</strong> – जो <i>राज्य की रक्षा</i> करते हैं।</p></li>\r\n    <li><p><strong>उत्पादक (Producers/Farmers, Artisans)</strong> – जो <i>कृषि, व्यापार, उत्पादन</i> आदि का कार्य करते हैं।</p></li>\r\n</ul>\r\n<p>प्लेटो का मानना था कि यह वर्गीकरण <i>जन्म या वंश</i> पर आधारित नहीं होना चाहिए, बल्कि <strong>योग्यता और प्रकृति</strong> पर आधारित होना चाहिए। उनका प्रसिद्ध कथन था- <i>\"राज्य तभी न्यायपूर्ण होगा जब शासक बुद्धिमान होंगे, रक्षक साहसी होंगे और उत्पादक संयमी होंगे।\"</i></p>\r\n\r\n<h2><strong>शिक्षा का सिद्धांत</strong></h2>\r\n<p>प्लेटो ने <strong>शिक्षा को आत्मा की शुद्धि</strong> और <strong>सत्य की ओर ले जाने वाली प्रक्रिया</strong> माना। उनका मानना था कि सही शिक्षा व्यक्ति के स्वभाव को प्रकट करती है और उसे अपने कर्तव्य के प्रति सजग बनाती है। उन्होंने शिक्षा की निम्नलिखित विशेषताएँ बताई-</p>\r\n<ul>\r\n    <li><p>शिक्षा <i>जन्म के बाद से प्रारंभ</i> हो जाती है और <i>जीवनभर चलती</i> है।</p></li>\r\n    <li><p>प्रारंभिक शिक्षा में <strong>जिम्नास्टिक</strong> (शारीरिक विकास) और <strong>संगीत</strong> (भावनात्मक विकास) अनिवार्य है।</p></li>\r\n    <li><p><strong>20 वर्ष</strong> के बाद <strong>गणित, तर्क और दर्शन</strong> की शिक्षा दी जानी चाहिए।</p></li>\r\n    <li><p><strong>30 वर्ष</strong> की आयु के बाद <i>राज्य संचालन का प्रशिक्षण</i> और <strong>50 वर्ष</strong> के बाद ही व्यक्ति <strong>शासन के योग्य</strong> होता है।</p></li>\r\n</ul>\r\n\r\n<h2><strong>स्त्रियों और संपत्ति पर विचार</strong></h2>\r\n<p>प्लेटो अपने समय से <strong>आगे सोचने वाले दार्शनिक</strong> थे। उन्होंने <strong>स्त्रियों को भी पुरुषों के समान</strong> शिक्षा और अधिकार देने की बात कही। उनके अनुसार <strong>स्त्रियाँ भी राज्य की रक्षक और शासक</strong> बन सकती हैं, बशर्ते उनमें <i>योग्यता</i> हो। उन्होंने यह भी कहा कि <strong>शासक और रक्षक वर्गों</strong> को <i>निजी संपत्ति नहीं रखनी</i> चाहिए, ताकि वे <i>लालच और पक्षपात</i> से दूर रहें।</p>\r\n\r\n<h2><strong>निष्कर्ष</strong></h2>\r\n<p>प्लेटो न केवल एक <strong>महान विचारक</strong> थे, बल्कि <strong>मानव समाज को एक आदर्श दिशा देने वाले मार्गदर्शक</strong> भी थे। उनके विचारों ने यह सिखाया कि केवल <i>भौतिक दुनिया ही सत्य नहीं है</i>, बल्कि <strong>वास्तविकता आत्मा, ज्ञान और न्याय</strong> के स्तर पर होती है। उनके दर्शन ने यह दिखाया कि एक <strong>समुचित और न्यायपूर्ण समाज</strong> के निर्माण के लिए <strong>दार्शनिक दृष्टिकोण और नैतिक शिक्षा</strong> अत्यंत आवश्यक है। <strong>प्लेटो की सोच, उनकी कल्पनाशीलता और आदर्शवाद</strong> आज भी <i>मानवता को नैतिक मूल्यों और ज्ञान की ओर</i> ले जाता है।</p>\r\n',4,'2025-06-03 05:35:53','2025-06-03 05:57:03','','Publish',0,'open',63,120),('बेंथम का उपयोगितावाद सिद्धांत क्या है','jeremy-benthams-theory-of-utilitarianism',2,'<p><strong>उपयोगितावाद</strong> <i>जेरेमी बेंथम</i> की समूची विचारधारा तथा चिंतन का मूलमंत्र और आधारशिला है। बेंथम ने तत्कालीन समय में <strong>नैतिकता</strong> की सभी पारंपरिक धारणाओं का खंडन किया और <strong>उपयोगिता</strong> को नैतिकता तथा मानवीय जीवन का आधार बनाया। प्रायः लोग <strong>ईश्वर की इच्छा</strong> को नैतिकता का आधार मानते थे और उनका कहना था कि जो कुछ ईश्वर की इच्छा है (अर्थात धर्मशास्त्रों के अनुसार) वही नैतिक है, और जो कुछ उसके विपरीत है, वह अनैतिक और अमान्य है। इसके अतिरिक्त, नैतिकता के संबंध में <strong>प्राकृतिक विधि</strong> की धारणा भी प्रचलित थी, और कुछ धार्मिक विचारक <strong>मनुष्य के अंतःकरण</strong> को नैतिकता का स्रोत मानते थे।</p>\r\n\r\n<p><i>बेंथम की विचारधारा</i> अन्य सभी राजनीतिक विचारधाराओं से भिन्न थी, क्योंकि यह <strong>मानव जीवन के नैतिक, तर्कसंगत और यथार्थवादी पक्ष</strong> पर आधारित थी। यही कारण है कि यह विचारधारा अधिक सैद्धांतिक नहीं, बल्कि <strong>व्यवहारिक</strong> है। उपयोगितावाद एक ऐसी विशाल विचारधारा है जो <strong>यथार्थवाद</strong> पर आधारित है। इस विचारधारा के अनुसार, <strong>सुख और दुख</strong> दो ऐसी प्रमुख अवस्थाएँ हैं जिन पर समस्त सामाजिक व्यवस्था आधारित होती है।</p>\r\n\r\n<h2>उपयोगिता का सिद्धांत</h2>\r\n<p><strong>बेंथम</strong> के उपयोगितावाद के मुख्य सिद्धांत</p>\r\n\r\n<h3 class=\"atech\">उपयोगिता का सिद्धांत</h3>\r\n<p>उपयोगितावाद का पहला प्रमुख सिद्धांत <strong>उपयोगिता के सिद्धांत</strong> पर आधारित है। इसके अनुसार, <strong>मानव की स्वाभाविक प्रवृत्ति</strong> होती है कि वह सुख प्राप्त करे और पीड़ा से बचे। मनुष्य की अन्य कई प्रवृत्तियों के बीच यह प्रवृत्ति सबसे प्रमुख है। इसी प्रवृत्ति के अनुसार, मनुष्य निरंतर <strong>प्रसन्नता</strong> प्राप्त करने और <strong>दुःख को दूर</strong> करने का प्रयास करता है।</p>\r\n\r\n<p>मानव के सभी कार्यों की अच्छाई-बुराई की कसौटी \'<strong>उपयोगिता</strong>\' होती है। जैसे <i>देशभक्ति</i>, <i>सत्यवादिता</i> आदि को उपयोगी मानकर अच्छा कहा जाता है। प्रसिद्ध उपयोगितावादी <strong>बेंथम</strong> ने कहा था कि <i>प्रकृति ने मानव जाति को दो स्वामी सौंपे हैं—सुख और दुःख।</i></p>\r\n\r\n<h3 class=\"atech\">अधिकतम सुख का सिद्धांत</h3>\r\n<p>दूसरी महत्वपूर्ण बात यह है कि <strong>राज्य का काम होना चाहिए अधिकतम व्यक्तियों को अधिकतम सुख देना</strong>। इसी आधार पर राज्य को न्यायसंगत माना जाता है, यानी <strong>राज्य का अस्तित्व</strong> तभी सही है जब वह <strong>समाज के अधिकांश लोगों की खुशी</strong> सुनिश्चित करता है।</p>\r\n\r\n<h3 class=\"atech\">राज्य और समाज का अंतर</h3>\r\n<p>उपयोगितावादियों के अनुसार, <strong>राज्य समाज से अलग</strong> है। राज्य का काम <strong>समाज में कानून व्यवस्था बनाए रखना</strong> है, लेकिन वह <strong>व्यक्तिगत जीवन में ज्यादा हस्तक्षेप नहीं करेगा</strong>। यह विचारधारा कहती है कि <strong>राज्य सिर्फ एक साधन</strong> है, उसका उद्देश्य <strong>समाज के कल्याण को बढ़ावा देना</strong> है।</p>\r\n\r\n<h3 class=\"atech\">यथार्थवादी दृष्टिकोण</h3>\r\n<p>उपयोगितावाद एक <strong>यथार्थवादी विचारधारा</strong> है, जिसका उद्देश्य केवल <i>कल्पना</i> नहीं, बल्कि <strong>वास्तविक जीवन की समस्याओं का समाधान</strong> करना है। इस विचारधारा ने <strong>समाज में सुधार</strong> के लिए कई नीतियां प्रस्तुत की, जिनका उद्देश्य <strong>लोगों के जीवन को बेहतर बनाना</strong> था।</p>\r\n\r\n<h3 class=\"atech\">संवैधानिकता और प्रजातंत्र</h3>\r\n<p>यह विचारधारा <strong>प्रजातंत्र</strong> में विश्वास करती है और यह मानती है कि <strong>सरकार को जनमत के आधार पर</strong> काम करना चाहिए, ताकि <strong>अधिकतम लोगों को अधिकतम सुख</strong> मिल सके।</p>\r\n\r\n<h2>उपयोगितावाद की आलोचना</h2>\r\n<p>उपयोगितावाद एक ऐसी विचारधारा है जो कहती है कि <strong>नैतिकता का आधार अधिकतम लोगों को अधिकतम सुख देना</strong> होना चाहिए। लेकिन इस सिद्धांत की कई आलोचनाएँ की गई हैं।</p>\r\n\r\n<h3 class=\"atech\">मनुष्य को केवल सुख का भूखा मानना गलत है</h3>\r\n<p>उपयोगितावाद मानता है कि <strong>मनुष्य का हर कार्य केवल सुख पाने और दुख से बचने</strong> के लिए होता है। लेकिन आलोचक कहते हैं कि <strong>मनुष्य में दया, प्रेम, त्याग, कर्तव्य</strong> जैसी भावनाएं भी होती हैं, जो सिर्फ सुख के लिए नहीं होतीं।</p>\r\n\r\n<h3 class=\"atech\">त्याग, बलिदान और नैतिकता की अनदेखी</h3>\r\n<p>यह विचारधारा <strong>त्याग और परोपकार</strong> जैसे नैतिक मूल्यों को कम महत्व देती है। जो काम <strong>दूसरों के लिए बिना किसी स्वार्थ के</strong> किए जाते हैं, उन्हें उपयोगितावाद में महत्व नहीं मिलता।</p>\r\n\r\n<h3 class=\"atech\">सुख को मापना असंभव है</h3>\r\n<p>उपयोगितावाद कहता है कि हम हर काम का मूल्य इस आधार पर तय करें कि उससे <strong>कितना सुख मिला</strong>। लेकिन सवाल यह है कि <strong>सुख को कैसे मापा जाए?</strong> हर व्यक्ति की खुशी अलग होती है। जिसे एक व्यक्ति अच्छा मानता है, वह <i>दूसरे के लिए दुखद</i> हो सकता है।</p>\r\n\r\n<h3 class=\"atech\">संख्यात्मक सोच का खतरा</h3>\r\n<p>उपयोगितावाद में यह कहा जाता है कि <i>“ज्यादा लोगों को अगर खुशी मिलती है, तो वह काम अच्छा है।”</i> लेकिन इससे <strong>अल्पसंख्यकों के अधिकारों की अनदेखी</strong> हो सकती है। जैसे – अगर <strong>90 लोग खुश हों लेकिन 10 लोग बहुत ज्यादा दुखी</strong> हों, तो क्या वह काम सही होगा?</p>\r\n\r\n<h3 class=\"atech\">व्यक्तिगत अधिकारों की उपेक्षा</h3>\r\n<p>यह विचारधारा <strong>व्यक्ति की स्वतंत्रता और समानता</strong> को प्राथमिकता नहीं देती। यह कहती है कि अगर <strong>किसी की स्वतंत्रता छीनकर भी बहुसंख्यक को सुख मिल सकता है</strong>, तो वह सही है – जो कि <i>लोकतंत्र और मानवाधिकारों</i> के खिलाफ है।</p>\r\n\r\n<p><strong>सिद्धांत रूप में</strong> यह विचार अच्छा लग सकता है, लेकिन वास्तविक जीवन में हर बार यह देखना कि <strong>किस कार्य से कितनों को सुख मिलेगा</strong> – बहुत जटिल और असंभव है।</p>\r\n\r\n<h2>उपयोगितावाद का महत्व</h2>\r\n<p>हालांकि उपयोगितावाद की आलोचनाएँ भी हैं, लेकिन इसके <strong>महत्व को नकारा नहीं</strong> जा सकता। इस विचारधारा ने <strong>समाज कल्याण और सार्वजनिक नीति</strong> में कई महत्वपूर्ण बदलाव लाए। इसने <strong>इंग्लैंड में कई सामाजिक और राजनीतिक सुधारों</strong> को प्रभावित किया। उपयोगितावाद का मूल उद्देश्य है <i>\"अधिकतम व्यक्तियों का अधिकतम सुख।\"</i></p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><i>जेरेमी बेंथम</i> का <strong>उपयोगितावाद</strong> एक <strong>क्रांतिकारी नैतिक सिद्धांत</strong> था जिसने <strong>नैतिकता को व्यावहारिक और वैज्ञानिक आधार</strong> देने की कोशिश की। यद्यपि इस पर कई आलोचनाएँ हुईं, फिर भी यह <strong>आधुनिक नैतिक दर्शन और सार्वजनिक नीति</strong> के विकास में अत्यंत प्रभावशाली रहा है। <i>जॉन स्टुअर्ट मिल</i> जैसे विचारकों ने इस सिद्धांत को और परिष्कृत किया और इसकी आलोचनाओं के उत्तर देने की कोशिश की।</p>\r\n',7,'2025-06-03 05:35:53','2025-06-03 06:06:17','','Publish',0,'open',63,121),('महात्मा गांधी का सत्याग्रह','satyagraha-of-mahatma-gandhi',2,'<p><strong>महात्मा गांधी द्वारा प्रतिपादित ‘सत्याग्रह’</strong> एक मौलिक एवं अनुपम विचार है। यह दो शब्दों <i>\"सत्य\"</i> (सच) और <i>\"आग्रह\"</i> (आशय या आग्रह) — से मिलकर बना है, जिसका अर्थ है: <strong>सत्य के लिए आग्रह</strong> या <strong>सत्य की शक्ति</strong>। गांधीजी ने इसे <i>आत्मबल</i> या <i>नैतिक बल</i> की संज्ञा दी है। गांधीजी का यह दृढ़ विश्वास था कि असत्य और अन्याय के विरुद्ध संघर्ष के लिए <strong>नैतिक बल</strong> की आवश्यकता होती है। अतः उन्होंने राजनीति में नैतिक मूल्यों के संरक्षण हेतु <strong>सत्याग्रह को एक प्रभावशाली अस्त्र</strong> के रूप में प्रयोग किया।</p>\r\n\r\n<p>गांधीजी के अनुसार जब व्यक्ति यह अनुभव करता है कि वह <strong>सत्य के पक्ष में</strong> है, तब वह अपने <i>आत्मबल</i> के द्वारा अन्याय का विरोध करता है। अतः स्पष्ट है कि <strong>सत्याग्रह केवल विरोध करने की एक विधि न होकर एक नैतिक शक्ति</strong> है, जिसमें विरोधी को <i>सच्चाई का बोध कराने</i> का प्रयत्न किया जाता है।</p>\r\n\r\n<h2>सत्याग्रही के गुण</h2>\r\n<p>गांधीजी के अनुसार <strong>प्रत्येक व्यक्ति सत्याग्रही नहीं बन सकता</strong>। उसके लिए <i>सत्य एवं अहिंसा में अटूट आस्था</i>, <i>आत्मानुशासन</i>, <i>सदाचार</i>, <i>आत्मबल</i> एवं <i>आत्मशुद्धि की भावना</i> आवश्यक है। गांधीजी ने <strong>11 व्रतों</strong> को भी सत्याग्रही के लिए आवश्यक बताया — जैसे <i>अहिंसा</i>, <i>सत्य</i>, <i>ब्रह्मचर्य</i>, <i>अस्तेय</i>, <i>अपरिग्रह</i>, <i>शारीरिक श्रम</i>, <i>अस्पृश्यता निवारण</i>, <i>सभी धर्मों का सम्मान</i> आदि।</p>\r\n\r\n<h2>सत्याग्रह की शुरुआत</h2>\r\n<p>गांधी जी ने इन <i>भेदभावपूर्ण नीतियों</i> के खिलाफ <strong>विरोध प्रदर्शन</strong> करने का निर्णय लिया। उनका मानना था कि <strong>अहिंसा और सत्य के मार्ग</strong> पर चलकर ही ये समस्याएं हल हो सकती हैं। <strong>1906 में उन्होंने \"सत्याग्रह\"</strong> शब्द का पहली बार उपयोग किया। उन्होंने भारतीयों से अपील की कि वे इन कानूनों का विरोध करें, लेकिन <i>हिंसा से बचें</i> और <i>शांतिपूर्ण तरीके से</i> विरोध करें।</p>\r\n\r\n<p>इस आंदोलन के दौरान गांधी जी और उनके अनुयायियों ने <i>हड़तालें</i>, <i>प्रदर्शन</i>, और <i>जेल भरो आंदोलन</i> जैसे तरीके अपनाए। यह आंदोलन <strong>सफल</strong> रहा और <i>दक्षिण अफ्रीका सरकार</i> ने भेदभावपूर्ण कानूनों को <strong>कुछ हद तक संशोधित</strong> किया।</p>\r\n\r\n<h2>भारत में सत्याग्रह की शुरुआत</h2>\r\n<p>महात्मा गांधी ने <strong>1915 में भारत लौटने के बाद</strong> सत्याग्रह को स्वतंत्रता संग्राम में लागू किया। उन्होंने देखा कि <i>ब्रिटिश साम्राज्य</i> भारत में <strong>किसानों और मजदूरों पर शोषण</strong> कर रहा था। गांधी जी ने सत्याग्रह को <strong>अधिकारों की रक्षा और संघर्ष</strong> के रूप में लागू किया।</p>\r\n\r\n<h3 class=\"atech\">चंपारण सत्याग्रह (1917)</h3>\r\n<p><strong>गांधी जी का भारत में पहला सत्याग्रह</strong> चंपारण (बिहार) में 1917 में शुरू हुआ। किसानों पर अंग्रेजों द्वारा <i>नील की खेती</i> करने का दबाव था। गांधी जी ने <strong>किसानों की समस्याओं को सुना</strong> और <strong>शांतिपूर्ण आंदोलन</strong> शुरू किया। यह <strong>सत्याग्रह सफल रहा</strong> और <strong>किसानों को राहत</strong> मिली।</p>\r\n\r\n<h3 class=\"atech\">खेड़ा सत्याग्रह (1918)</h3>\r\n<p>गुजरात के खेड़ा जिले में <strong>सूखा और अकाल</strong> के बावजूद किसानों से कर वसूले जा रहे थे। गांधी जी ने <i>किसानों को एकजुट</i> किया और <strong>शासन से राहत</strong> की मांग की। यह <strong>सत्याग्रह भी सफल</strong> रहा और करों में छूट मिली।</p>\r\n\r\n<h3 class=\"atech\">असहयोग आंदोलन (1920–22)</h3>\r\n<p><strong>जलियाँवाला बाग हत्याकांड</strong> और <i>रॉलेट एक्ट</i> के खिलाफ गांधी जी ने <strong>असहयोग आंदोलन</strong> शुरू किया। <i>सरकारी संस्थाओं का बहिष्कार</i> किया गया। यह <strong>एक व्यापक सत्याग्रह</strong> था। <i>चौरी-चौरा की हिंसा</i> के बाद गांधी जी ने आंदोलन वापस लिया, जिससे <strong>उनकी अहिंसा में आस्था</strong> स्पष्ट होती है।</p>\r\n\r\n<h3 class=\"atech\">नमक सत्याग्रह (1930)</h3>\r\n<p><strong>गांधी जी का सबसे प्रसिद्ध सत्याग्रह</strong> <i>नमक सत्याग्रह</i> था, जिसे <i>दांडी मार्च</i> भी कहा जाता है। 1930 में <strong>ब्रिटिश कर के विरोध में</strong> गांधी जी ने <strong>240 मील की पदयात्रा</strong> की। उन्होंने <i>समुद्र के किनारे</i> <strong>नमक बनाकर कर कानून का उल्लंघन</strong> किया। इसने <strong>भारत की जनता को एकजुट</strong> किया और गांधी जी को <strong>अंतरराष्ट्रीय पहचान</strong> दिलाई।</p>\r\n\r\n<h3 class=\"atech\">भारत छोड़ो आंदोलन (1942)</h3>\r\n<p><strong>द्वितीय विश्व युद्ध</strong> के दौरान गांधी जी ने <strong>\"अंग्रेजों भारत छोड़ो\"</strong> का नारा दिया। यह आंदोलन <i>सत्याग्रह पर आधारित</i> था, लेकिन <i>पूर्णतः अहिंसक नहीं</i> रहा। फिर भी गांधी जी <strong>अपने सिद्धांतों पर अडिग</strong> रहे।</p>\r\n\r\n<h2>सत्याग्रह का प्रभाव</h2>\r\n<p><strong>सत्याग्रह का स्वतंत्रता संग्राम पर गहरा प्रभाव</strong> पड़ा। इसने <i>आम जनता को आंदोलन से जोड़ा</i> और <strong>एक नैतिक मार्ग</strong> प्रदान किया। विभिन्न सत्याग्रहों ने <i>ब्रिटिश शासन की नींव</i> हिला दी। इससे <strong>भारत की आज़ादी की लड़ाई नैतिक</strong> बन गई, जिसने <i>दुनियाभर में आंदोलनों को प्रेरित</i> किया, जैसे <strong>मार्टिन लूथर किंग जूनियर</strong> का आंदोलन।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>महात्मा गांधी का सत्याग्रह</strong> केवल एक <i>राजनीतिक रणनीति</i> नहीं, बल्कि एक <strong>जीवन दर्शन</strong> था। यह एक ऐसी राह थी जो <strong>शांति, आत्मबल और नैतिकता</strong> के सहारे <strong>अन्यायपूर्ण सत्ता को झुकाने</strong> का सामर्थ्य रखती थी। सत्याग्रह ने <strong>भारत की आत्मा को जाग्रत</strong> किया और स्वतंत्रता आंदोलन को <strong>नैतिक व सांस्कृतिक आधार</strong> दिया। आज भी, <strong>सत्याग्रह का मार्ग</strong> <i>दुनिया को अहिंसा और न्याय</i> के पथ पर चलने की प्रेरणा देता है।</p>\r\n',15,'2025-06-03 05:35:53','2025-06-03 06:12:33','','Publish',0,'open',35,122),('रूसो के सामाजिक समझौते का वर्णन','description-of-russos-social-agreement',2,'<p><strong>ज्यां जैक रूसो</strong> अठारहवीं शताब्दी के एक महान फ्रांसीसी दार्शनिक थे, जिनका राजनीतिक चिंतन आधुनिक <strong>लोकतांत्रिक विचारधारा</strong> की नींव बन गया। उनकी सबसे प्रमुख रचना <i>\"The Social Contract\" (1762)</i> है, जिसमें उन्होंने यह तर्क दिया कि <strong>समाज और राज्य की स्थापना व्यक्तियों के आपसी समझौते</strong> के माध्यम से होनी चाहिए। <strong>रूसो</strong> ने <strong>सामाजिक अन्याय, असमानता</strong> और <strong>दमन</strong> की आलोचना करते हुए एक ऐसी व्यवस्था का सुझाव दिया जिसमें <strong>व्यक्ति की स्वतंत्रता और समानता</strong> की रक्षा हो सके।</p> <h2>प्राकृतिक अवस्था</h2> <p><strong>रूसो</strong> के अनुसार मानव का मूल स्वरूप <strong>स्वतंत्र, सरल और नैतिक</strong> था। <strong>प्राकृतिक अवस्था</strong> में मनुष्य <i>शुद्ध भावनाओं</i> से युक्त था और <strong>सामाजिक बंधनों से मुक्त</strong> था। परंतु जैसे-जैसे <strong>सभ्यता का विकास</strong> हुआ, <strong>निजी संपत्ति</strong> का उदय हुआ और <strong>सामाजिक असमानताएँ</strong> जन्म लेने लगीं। इसी कारण <strong>संघर्ष, स्वार्थ और दमन</strong> का वातावरण तैयार हुआ। <strong>रूसो</strong> मानते थे कि सभ्यता की प्रगति ने मनुष्य को जंजीरों में जकड़ दिया है। उन्होंने प्रसिद्ध पंक्ति में कहा, <i>\"मनुष्य स्वतंत्र पैदा होता है, परंतु हर जगह वह जंजीरों में जकड़ा हुआ है।\"</i></p> <h2>सामाजिक समझौते</h2> <p><strong>रूसो</strong> ने <strong>सामाजिक समझौते</strong> को उस प्रक्रिया के रूप में देखा जिसके माध्यम से लोग मिलकर एक नया <strong>समाज और राज्य</strong> बनाते हैं। इस समझौते में प्रत्येक व्यक्ति अपनी <strong>प्राकृतिक स्वतंत्रता</strong> का त्याग करता है और सभी लोग मिलकर एक सामूहिक इकाई का निर्माण करते हैं जिसे <strong><i>सामान्य इच्छा (General Will)</i></strong> कहा जाता है। इस इकाई के अंतर्गत रहने से व्यक्ति को <strong>राजनीतिक और नैतिक स्वतंत्रता</strong> प्राप्त होती है। इस प्रक्रिया में व्यक्ति अपनी इच्छा को <strong>सामूहिक इच्छा</strong> में विलीन करता है और <strong>सबका हित ही व्यक्तिगत हित</strong> बन जाता है।</p> <h2>सामान्य इच्छा का सिद्धांत</h2> <p><strong>रूसो</strong> का सबसे क्रांतिकारी विचार <strong><i>\"सामान्य इच्छा\"</i></strong> का सिद्धांत है। उनका विश्वास था कि जब समाज के सभी सदस्य एक साथ मिलकर निर्णय लेते हैं, तो उस निर्णय में <strong>व्यक्तिगत स्वार्थ</strong> नहीं बल्कि <strong>सामूहिक भलाई</strong> निहित होती है। <strong>सामान्य इच्छा</strong> किसी व्यक्ति या वर्ग की नहीं होती, बल्कि यह समाज की <strong>समष्टिगत चेतना</strong> का प्रतिनिधित्व करती है। <strong>रूसो</strong> का मानना था कि राज्य को केवल उसी समय <strong>वैध</strong> माना जा सकता है जब वह <strong>सामान्य इच्छा</strong> के अनुसार कार्य करे।</p> <h2>संप्रभुता की अवधारणा</h2> <p><strong>रूसो</strong> के <strong>सामाजिक समझौते</strong> में <strong>संप्रभुता</strong> का केंद्र <strong>जनता</strong> होती है। उन्होंने यह स्पष्ट किया कि <strong>संप्रभुता</strong> को किसी <strong>राजा, कुलीन वर्ग</strong>, या <strong>धार्मिक संस्था</strong> को सौंपा नहीं जा सकता। राज्य का अस्तित्व तभी वैध होता है जब वह <strong>जनता की सामान्य इच्छा</strong> को अभिव्यक्त करता हो। इस <strong>संप्रभुता</strong> को <strong>हस्तांतरित नहीं किया जा सकता</strong>, क्योंकि यह प्रत्येक नागरिक का <strong>नैतिक अधिकार</strong> है।</p> <h2>स्वतंत्रता की पुनः प्राप्ति</h2> <p><strong>रूसो</strong> के अनुसार <strong>सामाजिक समझौते</strong> के माध्यम से व्यक्ति न केवल <strong>सामाजिक व्यवस्था</strong> में प्रवेश करता है बल्कि वह एक नई प्रकार की <strong>स्वतंत्रता</strong> प्राप्त करता है। अब वह स्वतंत्रता <strong>स्वेच्छाचारिता</strong> नहीं होती, बल्कि <strong>नैतिक और विधिसम्मत स्वतंत्रता</strong> होती है। जब कोई व्यक्ति उस <strong>कानून</strong> का पालन करता है जिसे उसने स्वयं अपने प्रतिनिधियों के माध्यम से बनाया है, तब वह <strong>सच्चे अर्थों में स्वतंत्र</strong> होता है।</p> <h2>राज्य और कानून का स्वरूप</h2> <p><strong>रूसो</strong> के अनुसार <strong>राज्य</strong> का कार्य केवल <strong>सत्ता का प्रयोग</strong> करना नहीं है, बल्कि <strong>सामान्य इच्छा</strong> के अनुसार कार्य करना है। राज्य को चाहिए कि वह ऐसे <strong>कानून</strong> बनाए जो <strong>समाज के सभी लोगों के लिए समान</strong> हों और जो <strong>न्याय व समानता</strong> को बढ़ावा दें। <strong>राज्य और कानून</strong> का उद्देश्य <strong>व्यक्ति के अधिकारों</strong> की रक्षा करना और समाज में <strong>नैतिक मूल्यों</strong> को स्थायित्व प्रदान करना है।</p> <h2>निष्कर्ष</h2> <p><strong>रूसो</strong> का <strong>सामाजिक समझौता</strong> एक ऐसी <strong>वैचारिक संकल्पना</strong> है जिसने <strong>राज्य, स्वतंत्रता और समानता</strong> की परिभाषा को नया रूप दिया। उनके अनुसार <strong>व्यक्ति की वास्तविक स्वतंत्रता</strong> तब ही सुरक्षित हो सकती है जब वह <strong>समाज के हित</strong> में कार्य करे और ऐसा समाज केवल तभी संभव है जब वह <strong>सामान्य इच्छा</strong> पर आधारित हो। <strong>रूसो</strong> ने न केवल एक <strong>न्यायपूर्ण समाज</strong> की कल्पना की, बल्कि यह भी दिखाया कि वह समाज <strong>कैसे गठित</strong> किया जा सकता है। उनका विचार आज भी <strong>सामाजिक न्याय और लोकतंत्र</strong> के <strong>मूल स्तंभों</strong> को दिशा देने वाला बना हुआ है।</p>',19,'2025-06-03 05:35:53','2025-06-03 06:18:07','','Publish',0,'open',60,123),('संत थॉमस एक्विनास के विचार','ideas-of-saint-thomas-aquinas',2,'<p><strong>संत थॉमस एक्विनास (1225–1274)</strong> मध्यकालीन यूरोप के सबसे <i>प्रभावशाली धर्मशास्त्री</i> और <i>दार्शनिक</i> माने जाते हैं। उन्होंने <strong>ईसाई धर्म</strong> को <i>अरस्तू के तर्कशास्त्र और दर्शन</i> के साथ जोड़ने का प्रयास किया। उन्होंने <strong>विश्वास और तर्क के बीच समन्वय</strong> स्थापित किया और <i>ईश्वर, आत्मा, राज्य, न्याय, कानून तथा मानव स्वभाव</i> जैसे विषयों पर व्यापक चिंतन प्रस्तुत किया। उनके विचार आज भी <strong>ईसाई धर्मशास्त्र</strong> और <strong>पश्चिमी राजनीतिक दर्शन</strong> की नींव माने जाते हैं।</p>\r\n<h2>राज्य संबंधी विचार</h2>\r\n<p><strong>संत थॉमस एक्विनास</strong> के अनुसार, <i>राज्य एक प्राकृतिक संस्था</i> है, जिसकी उत्पत्ति मानव समाज की आवश्यकताओं की पूर्ति के लिए हुई है। उनका मानना था कि <strong>मनुष्य एक सामाजिक प्राणी</strong> है, और वह अकेले जीवन नहीं जी सकता। इसलिए <i>राज्य जैसी संस्था</i> की आवश्यकता होती है जो सामाजिक व्यवस्था और जनकल्याण को सुनिश्चित कर सके।</p>\r\n<p>उन्होंने कहा कि <strong>राज्य का अंतिम उद्देश्य सामूहिक भलाई (Common Good)</strong> है – यानी राज्य का कार्य यह सुनिश्चित करना है कि समाज के प्रत्येक सदस्य को <i>न्याय, सुरक्षा, शिक्षा और नैतिक उन्नति</i> प्राप्त हो। एक्विनास के अनुसार, एक शासक का दायित्व केवल शासन करना नहीं है, बल्कि जनता के <strong>नैतिक और आध्यात्मिक जीवन को भी ऊंचा उठाना</strong> है।</p>\r\n<p>यदि कोई शासक <strong>अन्यायपूर्ण शासन</strong> करता है या <i>ईश्वर के सिद्धांतों के विरुद्ध कार्य</i> करता है, तो प्रजा को उस शासन को हटाने का <strong>नैतिक अधिकार</strong> है। उन्होंने राज्य को <i>धर्म के अधीन</i> माना, अर्थात धर्म की सार्वभौमिक नैतिकता राज्य की सत्ता से ऊपर है।</p>\r\n\r\n<h2>दासता संबंधी विचार</h2>\r\n<p><strong>एक्विनास</strong> ने दासता को <i>नैतिक रूप से स्वीकार</i> तो किया, लेकिन यह स्पष्ट किया कि यह एक <strong>आदर्श स्थिति नहीं</strong> है। उनके अनुसार, दासता मूलतः <i>पाप का परिणाम</i> है और यह ईश्वर की सृष्टि की योजना का आवश्यक अंग नहीं है।</p>\r\n<p>उन्होंने अरस्तू के विचारों से प्रभावित होकर यह माना कि कुछ लोग <strong>स्वभावतः अधीन रहने के लिए होते हैं</strong> और दासता उनके लिए एक प्रकार की <i>नैतिक अनुशासन व्यवस्था</i> है। परंतु उन्होंने यह भी जोड़ा कि सभी मनुष्य <strong>आत्मा की दृष्टि से समान</strong> हैं और ईश्वर की संतान हैं, इसलिए दास के साथ भी <i>न्याय, दया और नैतिकता</i> का व्यवहार करना चाहिए।</p>\r\n<p>इस दृष्टिकोण से, उन्होंने दासता की <strong>अमानवीय और शोषणकारी प्रवृत्तियों</strong> को सही नहीं ठहराया, बल्कि इसे एक ऐसी व्यवस्था माना जिसे तत्कालीन समाज में <i>नियंत्रित और नैतिक रूप से संचालित</i> करना आवश्यक था।</p>\r\n\r\n<h2>कानून संबंधी विचार</h2>\r\n<p><strong>संत थॉमस एक्विनास</strong> ने कानून को चार श्रेणियों में बाँटा</p>\r\n<ul>\r\n    <li><p><strong>शाश्वत कानून</strong> - यह ईश्वर की बुद्धि में स्थित वह नियम है जिससे सृष्टि का संचालन होता है।</p></li>\r\n    <li><p><strong>प्राकृतिक कानून</strong> - यह वह नैतिक विवेक है जो प्रत्येक मनुष्य में जन्मजात होता है और जो उसे <i>सही-गलत का बोध</i> कराता है।</p></li>\r\n    <li><p><strong>मानव-निर्मित कानून</strong> - यह राज्य और समाज द्वारा बनाए गए वे नियम हैं जो <i>न्याय और व्यवस्था बनाए रखने</i> के लिए होते हैं।</p></li>\r\n    <li><p><strong>दिव्य कानून</strong> - यह बाइबल जैसे धर्मग्रंथों में पाया जाने वाला <i>ईश्वरीय विधान</i> है, जो मनुष्य को मोक्ष की ओर ले जाता है।</p></li>\r\n</ul>\r\n<p><strong>एक्विनास</strong> के अनुसार, किसी भी <i>मानव-निर्मित कानून</i> की वैधता इस पर निर्भर करती है कि वह <strong>प्राकृतिक और शाश्वत कानून के अनुरूप</strong> है या नहीं। यदि कोई कानून <i>नैतिक रूप से अन्यायपूर्ण</i> है, तो वह कानून कहलाने योग्य नहीं है और उसका पालन <strong>अनैतिक</strong> है।</p>\r\n<p>उनके अनुसार, कानून का उद्देश्य केवल व्यवस्था बनाए रखना नहीं, बल्कि <strong>नैतिकता को बढ़ावा देना</strong> है। उन्होंने <i>न्याय को कानून का सार</i> बताया और कहा कि कानून को केवल बल या दंड से लागू नहीं करना चाहिए, बल्कि लोगों की <strong>आत्मा और विवेक</strong> को भी संबोधित करना चाहिए।</p>\r\n\r\n<h2>धार्मिक विश्वास और तर्क का समन्वय</h2>\r\n<p><strong>संत थॉमस एक्विनास</strong> का दर्शन इस सिद्धांत पर आधारित था कि <i>तर्क और विश्वास एक-दूसरे के पूरक</i> हैं। उनका मानना था कि ईश्वर को केवल आस्था से नहीं, बल्कि <strong>तर्क के माध्यम से</strong> भी जाना जा सकता है। उन्होंने ईश्वर के अस्तित्व को सिद्ध करने के लिए प्रसिद्ध पाँच तर्क दिए।</p>\r\n<ul>\r\n    <li><p><strong>गति का तर्क</strong> - हर गति के पीछे एक प्रेरक शक्ति होती है, जो <i>ईश्वर</i> है।</p></li>\r\n    <li><p><strong>कारण का तर्क</strong> - हर प्रभाव का एक कारण होता है, और यह कारण <i>ईश्वर</i> है।</p></li>\r\n    <li><p><strong>संभाव्यता और अनिवार्यता का तर्क</strong> - सभी प्राणी संभाव्य हैं, लेकिन एक अनिवार्य सत्ता (<i>ईश्वर</i>) है।</p></li>\r\n    <li><p><strong>श्रेष्ठता का तर्क</strong> - हर वस्तु में श्रेष्ठता का स्तर होता है, और सर्वोच्च श्रेष्ठता <i>ईश्वर</i> में है।</p></li>\r\n    <li><p><strong>गंतव्य का तर्क</strong> - ब्रह्मांड की व्यवस्था एक उद्देश्यपूर्ण दृष्टिकोण से है, जो एक बुद्धिमान निर्माता (<i>ईश्वर</i>) की ओर इशारा करती है।</p></li>\r\n</ul>\r\n<p>इन सभी गुणों को ध्यान में रखते हुए, उनका मानना था कि <strong>नैतिक जीवन</strong> वही है जिसमें इन गुणों का पालन करते हुए व्यक्ति <i>ईश्वर की इच्छा के अनुसार जीवन</i> जीता है।</p>\r\n<p><strong>संत थॉमस एक्विनास</strong> का यह विश्वास था कि <i>धर्म और विज्ञान दोनों सत्य की खोज के अलग-अलग मार्ग</i> हैं। उनका कहना था कि दोनों का अंतिम उद्देश्य एक ही है - <strong>ईश्वर की पहचान</strong>। उन्होंने यह स्पष्ट किया कि यदि धर्म और विज्ञान के बीच कोई विरोध दिखाई देता है, तो वह मनुष्य की समझ की सीमाओं के कारण है, न कि दोनों के बीच वास्तविक विरोध।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>संत थॉमस एक्विनास</strong> ने मध्यकालीन समाज में <i>तर्क, नैतिकता, धर्म और राजनीति के बीच संतुलन</i> स्थापित करने का प्रयास किया। उन्होंने <strong>राज्य की भूमिका को जनकल्याण और नैतिक उत्थान</strong> से जोड़ा, दासता को सहनशील परंतु आदर्शविहीन व्यवस्था के रूप में स्वीकार किया, और कानून को केवल विधिक संरचना नहीं, बल्कि <i>नैतिक व्यवस्था का भी अंग</i> माना।</p>\r\n<p>उनकी दृष्टि में धर्म केवल आस्था नहीं था, बल्कि <strong>तर्क, विवेक और नैतिकता का मार्गदर्शक</strong> था। आज भी उनके विचार <i>न्याय, धर्मनिष्ठा और मानवाधिकार</i> के प्रश्नों में महत्वपूर्ण मार्गदर्शन प्रदान करते हैं।</p>\r\n',16,'2025-06-03 05:35:53','2025-06-03 06:23:19','','Publish',0,'open',63,124),('दिल्ली सल्तनत के केंद्रीय प्रशासन के वर्णन','central-administration-of-delhi-sultanate',2,'<p>दिल्ली सल्तनत का प्रमुख \"<strong>सुल्तान</strong>\" कहलाता था। ऐसी मान्यता थी कि प्रभुत्व संपूर्ण सुन्नी जनता में निवास करती है एवं उसे <strong>मिल्लत</strong> कहते थे, इसलिए मिल्लत को सुल्तान का चुनाव करने का अधिकार था। किंतु व्यावहारिक दृष्टि से देश की संपूर्ण मुस्लिम जनता को शामिल (एकत्र) करना असंभव था, इसलिए मताधिकार पहले प्रमुख व्यक्तियों और अंत में एक ही व्यक्ति तक सीमित रह गया। मृत्यु से पूर्व सुल्तान को अपना उत्तराधिकारी \"मनोनीत\" करने का अधिकार था। इस प्रकार, दिल्ली के सुल्तानों के चुनाव में दोनों प्रणालियों से काम लिया जाता था। वंशानुगत उत्तराधिकार का सिद्धांत नहीं था और कम से कम सैद्धांतिक दृष्टि से प्रत्येक सच्चे मुसलमान के लिए सुल्तान के पद का द्वार खुला था, किंतु व्यवहार में वह विदेशी तुर्कों तक ही सीमित था। बाद में, अमीरों के एक छोटे से दल और अंत में राजवंश तक ही सीमित रह गया। 15वीं से 16वीं शताब्दी में इस क्षेत्र में कुछ विस्तार हुआ तथा अरब और अफगान नस्ल के सुल्तान भी हुए।</p>\r\n    <p>शुद्ध इस्लामी सिद्धांत के अनुसार, ईश्वर ही मुस्लिमों का शासक माना जाता था और सुल्तान उसका प्रतिनिधि होता था। सुल्तान का कार्य नियमों को क्रियान्वित करना ही नहीं, अपितु उनकी व्याख्या करना भी था। इस कार्य में उसे \"<strong>हदीस</strong>\" और विख्यात विधि-वेत्ताओं (व्याख्या करने वाले) के निर्णय के अनुसार चलना पड़ता था तथा विवाद की स्थिति में \"<strong>उलेमाओं</strong>\" की राय स्वीकार करनी पड़ती थी। इसके अतिरिक्त, सुल्तान सर्वोच्च न्यायाधीकारी तथा सर्वोच्च सेनापति भी था। वह पूर्ण रूप से निरंकुश था और उसकी शक्ति पर किसी प्रकार का नियंत्रण नहीं था। संक्षेप में, उसमें कैसर और पोप, दोनों की शक्तियाँ नहीं थी। सुल्तान को शासन में सहायता और सलाह देने के लिए केंद्रीय प्रशासन में कई मंत्री होते थे। इसका वर्णन निमन्वत है-</p>\r\n    <h2>केंद्रीय प्रशासन की संरचना</h2>\r\n    <h3 class=\"atech\">मंत्रीगण</h3>\r\n    <p>शासन में सुल्तान को सहयोग देने के लिए मंत्री होते थे, जिनकी संख्या समय-समय पर घटती-बढ़ती रहती थी। गुलाम युग में मुख्यतः 4 श्रेणियां थीं — <strong>वजीर</strong>, <strong>आरिज़-ए-मुमालिक</strong>, <strong>दीवान-ए-इंशा</strong>, <strong>दीवान-ए-रसालत</strong>। कभी-कभी <strong>नायब-ए-मुमालिक</strong> भी हुआ करता था, जिसका पद सुल्तान से नीचे और वजीर से ऊँचा होता था। जब सुल्तान दुर्बल होता था, तब वह नायब के हाथ में अधिक शक्ति आ जाती थी। आगे चलकर <strong>सद्र-उस-सुदूर</strong> एवं <strong>दीवान-ए-क़ज़ा</strong> को भी मंत्रियों के समकक्ष कर दिया गया। इस प्रकार, सल्तनत के उत्कर्ष काल में 6 मंत्री काम करते थे। इसके अतिरिक्त, एक सांत्वना (7) पद भी था, जिसे धारण करने वाला मंत्रियों के समकक्ष न होते हुए भी अक्सर अत्यधिक शक्तिशाली होता था। यह पद सुल्तान के महलों के प्रबंधक का था।</p>\r\n    <h3 class=\"atech\">वजीर</h3>\r\n    <p>प्रधानमंत्री <strong>वजीर</strong> कहलाता था। उसकी स्थिति <strong>सुल्तान और प्रजा</strong> के बीच की थी। वह सुल्तान के नाम से महत्वपूर्ण पदाधिकारियों की नियुक्ति करता था और सभी अधिकारियों के विरुद्ध शिकायतें सुनता था। सुल्तान की <strong>ऋणावस्था (बीमारी)</strong>, <strong>अनुपस्थिति</strong> अथवा उसकी <strong>अल्प अवस्था</strong> में वजीर सुल्तान के स्थान पर कार्य करता था। सुल्तान को <strong>प्रजा की स्थिति और अवस्कताओ एवं भावनाओं</strong> से अवगत कराना तथा <strong>सामाजिक विषयों पर सलाह देना</strong> वजीर का कर्तव्य था।</p>\r\n    <p>सामान्य शासन व्यवस्था का अध्यक्ष होने के साथ-साथ वह विशेष रूप से <strong>वित्त विभाग का प्रधान</strong> था। इस हैसियत से <strong>लगान के बंदोबस्त के लिए नियम बनाना</strong>, <strong>अन्य करों की दरें निर्धारित करना</strong>, तथा <strong>राज्य के व्यय पर नियंत्रण रखना</strong> उसका मुख्य दायित्व था। इसके अतिरिक्त, <strong>सैन्य पदाधिकारिओ के कार्यों का निरीक्षण</strong> वह करता था सैन्य प्रशासन पर भी उसका नियत्रण था, क्योंकि सेना की सभी आवश्यकताओं की पूर्ति उसी के द्वारा होती थी।</p>\r\n    <p>विद्वानों और गरीबों को प्रदान की जाने वाली <strong>छात्रवृत्तियों</strong> का प्रबंध भी वजीर के हाथों में था। इस प्रकार, शासन की सभी शाखाओं पर उसका नियंत्रण था। <strong>सूबेदार से लेकर चपरासी तक</strong> सभी कर्मचारियों को प्रत्यक्ष या अप्रत्यक्ष रूप से उससे कार्य लेना पड़ता था। इतनी वृहद शक्तियों के कारण राज्य में वजीर की <strong>महत्वपूर्ण प्रतिष्ठा</strong> थी।</p>\r\n    <p>वजीर का कार्यालय <strong>दीवान-ए-विजारत</strong> कहलाता था। उसकी सहायता के लिए एक <strong>नायब वजीर</strong> होता था, जिसका कार्य दफ्तर का <strong>लेखा-जोखा रखना</strong> था। <strong>नायब वजीर</strong> के अधीन (नीचे)-<strong>मुशरिफ़-ए-मुमालिक (महालेखाकार)</strong>,<strong>मुस्तौफी-ए-मुमालिक (महालेखा परीक्षक)</strong> काम करते थे। मुशरिफ़-ए-मुमालिक प्रांतों और अन्य विभागों से होने वाला आय का लेखा-जोखा रखता था और मुस्तौफी-ए-मुमालिक उसकी जांच करता था।</p>\r\n    <p>फिरोज शाह तुगलक के शासनकाल में इस व्यवस्था में कुछ परिवर्तन हुआ। <strong>महालेखाकार आय-व्यय का लेखा-जोखा</strong> रखने लगा और <strong>महालेखा परीक्षक बजट (व्यय) का हिसाब</strong> रखने लगा। <strong>महालेखाकार की सहायता के लिए नाज़िर (निरीक्षक)</strong> नियुक्त किए गए थे। इसी प्रकार, <strong>महालेखा परीक्षक</strong> के लिए भी कुछ पदाधिकारी होते थे।</p>\r\n\r\n    <h3 class=\"atech\">दीवाने-ए-आरिज</h3>\r\n    <p>इसे सैन्य मंत्री अथवा सैन्य विभाग का महाप्रबंधक कहा जा सकता है। इसका मुख्य कार्य सैनिकों की भर्ती करना, सैनिकों और घोड़ों का हुलिया रखना और फौज का निरीक्षण करना था। क्योंकि सेना का महा सेनापति सुल्तान स्वयं होता था, इसलिए सामान्यतः आरिज-ए-मुमालिक को किसी विशेष फौजी अभियान का नेतृत्व नहीं करना पड़ता था। परंतु कभी-कभी सुल्तान उसे किसी भाग का नेतृत्व दे दिया करता था।</p>\r\n    <p>इसका मुख्य कार्य फौज के अनुशासन, साज-सज्जा, सैनिकों की रसद (भोजन) की व्यवस्था और युद्ध क्षेत्र में उनके कार्यों का निरीक्षण करना था। यह विभाग इतना महत्वपूर्ण था कि कभी-कभी सुल्तान स्वयं इससे संबंधित अनेक कार्य किया करता था। उदाहरण के लिए, सुल्तान अलाउद्दीन खिलजी सेना के संगठन और प्रशिक्षण में निजी तौर पर रुचि रखता था।</p>\r\n    \r\n    <h3 class=\"atech\">दीवाने-ए-इंसा</h3>\r\n    <p>यह सही पत्राचार विभाग का प्रधान हुआ करता था। उसकी सहायता के लिए अनेक दबीर अथवा लेखक रहते थे, जो लेखन शैली में दक्ष होने के कारण इस विभाग में नियुक्त किए जाते थे। सुल्तान का अन्य राज्यों के शासकों, महत्वपूर्ण अधीनस्थ सामंतों और राज्य के पदाधिकारियों से जो पत्राचार(पत्रव्यवहार) होता था, और जिसका बहुत कुछ अंस गुप्त रखा जाता था, वह सब इसी विभाग द्वारा लिखा जाता था। सुल्तान के महत्वपूर्ण आदेशों के प्रारूप इसी विभाग में तैयार किए जाते थे, तत्पश्चात वे सुल्तान की स्वीकृति के लिए भेजा जाता था। अंत में, उनकी प्रतिलिपियाँ बनाई जाती थीं और मुद्रांकित करके यथास्थान भेज दी जाती थीं।</p>\r\n    <p>इस विभाग का कार्य अत्यंत गोपनीय था, अतः इसका अध्यक्ष एक अत्यंत विश्वसनीय व्यक्ति होता था।</p>\r\n    \r\n    <h3 class=\"atech\">दीवाने रासलत</h3>\r\n    <p>इस मंत्री के कार्यों के संबंध में इतिहासकारों में मतभेद है। <strong>डॉ० IH कुरैशी</strong> के मतानुसार, इसका संबंध धार्मिक विषयों से था। विद्वानों और धार्मिक व्यक्तियों को जो वजीफे दिए जाते थे, उसका भार भी इसी पर था। इसके विपरीत, <strong>डॉ० हबीबुल्लाह</strong> का मत है कि यह विदेश मंत्री था। इसके अधिकार क्षेत्र में कूटनीतिक पत्र व्यवहार तथा विदेशों को भेजे जाने वाले और वहां से सल्तनत में आने वाले राजदूतों का भार भी इसी पर था।</p>\r\n    <p>ऐसा प्रतीत होता है कि डॉ० हबीबुल्लाह का मत अधिक तर्कसंगत है, क्योंकि सल्तनत काल में एक ही कार्य के लिए दो मंत्रियों की संभावना कम थी। धार्मिक कार्यों के लिए पहले से ही सद्र-ए-सुदूर कार्यरत था। दीवाने रासलत एक अत्यंत महत्वपूर्ण पदाधिकारी था, क्योंकि सुल्तान केवल देशी रियासतों के साथ-साथ मध्य एशियाई देशों के साथ भी कूटनीतिक संबंध बनाए रखने का इच्छुक रहता था। विदेशों के साथ कूटनीतिक संबंध स्थापित करने में दीवाने रासलत की महत्वपूर्ण भूमिका थी।</p>\r\n\r\n    <h3 class=\"atech\">सद्र-ए-सुदूर</h3>\r\n    <p>यह धार्मिक विभाग का अध्यक्ष होता था। इसी प्रकार <strong>काजी-उल-कुजात</strong> न्याय विभाग का अध्यक्ष होता था। अक्सर इन दोनों विभागों के अध्यक्ष पद पर एक ही व्यक्ति की नियुक्ति की जाती थी, क्योंकि ये दोनों विभाग एक-दूसरे से संबंधित थे।</p>\r\n    <p>सल्तनत काल में धर्म और न्याय विभाग एक साथ कार्य करते थे। मुख्यतः <strong>सद्र-ए-सुदूर</strong> का कार्य इस्लामी नियमों एवं उपनियमों को लागू करना तथा यह देखना था कि मुसलमान अपने दैनिक जीवन में उनका पालन कर रहे हैं या नहीं। दान के रूप में पात्रों के बीच धन का वितरण करना, उलेमा, विद्वानों और धार्मिक व्यक्तियों के जीवन-निर्वाह के लिए भत्ते मंजूर करना आदि का भार भी इसी पर था। न्याय विभाग का अध्यक्ष काजी-उल-कुजात होता था तथा इस्लामी कानून के अनुसार राज्य में न्याय प्रणाली का निरीक्षण करना उसका दायित्व था।</p>\r\n    \r\n    <h3 class=\"atech\">मजलिस-ए-खलवत</h3>\r\n    <p>यह सुल्तान की मंत्री परिषद के लिए प्रयुक्त होता था। हालांकि, सभी मंत्रियों के पद और स्थिति समान नहीं थी। वजीर की हैसियत अन्य मंत्रियों से अधिक थी, जबकि अन्य पांच मंत्रियों की स्थिति लगभग सुल्तान के सचिव जैसी थी। सुल्तान सभी मंत्रियों को एक साथ मंत्रणा के लिए नहीं बुलाता था। वह अपनी इच्छा अनुसार मंत्रियों की नियुक्ति और पदावनति कर सकता था। साथ ही, वह उनमें से किसी की भी सलाह मानने के लिए बाध्य नहीं था। इसके अलावा, सुल्तान के सलाहकारों में कुछ गैर-सरकारी लोग भी शामिल होते थे। इन सभी को मिलाकर मजलिस-ए-खलवत कहा जाता था।</p>\r\n    \r\n    <h3 class=\"atech\">अन्य विभाग</h3>\r\n    <p>उपरोक्त वर्णित मंत्रियों के अतिरिक्त, राज्यधानी में सुल्तान की सहायता के लिए अनेक विभागों के अध्यक्ष भी होते थे। इन पर महत्वपूर्ण कार्यों का भार था। प्रमुख विभाग इस प्रकार थे-</p>\r\n    <ol>\r\n        <li><p><strong>बारिद-ए-मुमालिक</strong> - यह डाक एवं गुप्तचर विभाग का अध्यक्ष था।</p></li>\r\n        <li><p><strong>दीवाने-ए-अमीर-कोही</strong> - मोहम्मद बिन तुगलक द्वारा स्थापित कृषि विभाग।</p></li>\r\n        <li><p><strong>दीवाने-ए-मुस्तखराज</strong> - अलाउद्दीन खिलजी द्वारा स्थापित यह विभाग किसानों एवं कलेक्टर से बकाया कर की वसूली करता था।</p></li>\r\n        <li><p><strong>दीवाने-ए-रिश्ते</strong> - यह पेंशन विभाग था।</p></li>\r\n    </ol>    \r\n\r\n    <h3 class=\"atech\">शाही गृह प्रबंधन</h3>\r\n    <p>यद्यपि सैद्धांतिक दृष्टि से सुल्तान के गृह विभाग का अध्यक्ष केवल आंतरिक मामलों की देखरेख करता था, किंतु उसका शासन पर भी काफी प्रभाव था। शाही अंगरक्षक (सर-ए-जांदार) तथा गुलामी का विभाग (दीवान-ए-बंदगान) इसी के अधीन था। सुल्तान और अन्य विभागों की आवश्यकताओं की पूर्ति के लिए कई शाही कारखाने होते थे, जो शाही गृह प्रबंधक के अधीन कार्य करते थे। इतने व्यापक दायित्वों के निर्वहन के कारण उसे दरबार में उच्च स्थान प्राप्त था।</p>\r\n\r\n    <h2>निष्कर्ष</h2>\r\n    <p>इस प्रकार, उपर्युक्त विवेचनाओं से स्पष्ट है कि सल्तनत कालीन प्रशासनिक व्यवस्था की धुरी स्वयं सुल्तान हुआ करता था। जब-जब सत्ता के केंद्र में शक्तिशाली शासक आए, प्रशासनिक व्यवस्था सुचारू रूप से चली। और जब-जब कमजोर सुल्तान गद्दी पर बैठे, केंद्रीय प्रशासन में अमीरों का प्रभाव बढ़ गया। सुल्तान के शक्तिशाली होने पर मंत्रिपरिषद केवल निजी सचिवों की संस्था बनकर रह गई, जबकि सुल्तान के कमजोर होने पर मंत्रिपरिषद की ताकत बढ़ी। कई बार मंत्रियों ने \"सुल्तान निर्माता\" की भूमिका भी निभाई।</p>',45,'2025-06-03 05:35:53','2025-06-03 06:41:37','','Publish',0,'open',19,125),('मराठा साम्राज्य में भू-राजस्व प्रणाली','land-revenue-system-in-maratha-empire',2,'<p><strong><i>मराठा साम्राज्य (17वीं से 19वीं शताब्दी)</i></strong> भारत का एक शक्तिशाली और प्रभावशाली साम्राज्य था, जिसकी शक्ति का एक प्रमुख स्तंभ उसकी <strong>सुदृढ़ और संगठित भू-राजस्व व्यवस्था</strong> थी। यह व्यवस्था न केवल राज्य की आय का मूल स्रोत थी, बल्कि <i>प्रशासनिक दक्षता, कृषक हित संरक्षण</i> और <i>भूमि के उपयोग में स्थायित्व</i> लाने में भी सहायक सिद्ध हुई। इस व्यवस्था की जड़ें <strong>शिवाजी महाराज</strong> के समय में पड़ीं और आगे चलकर पेशवाओं द्वारा इसे और भी अधिक व्यवस्थित और प्रभावी बनाया गया।</p>\r\n\r\n<h2>राजस्व का स्वरूप और स्रोत</h2>\r\n<p>मराठा काल की राजस्व आय का प्रमुख स्रोत <strong>कृषि भूमि से प्राप्त मालगुजारी</strong> (land revenue) थी। यह आमतौर पर किसान की उपज का एक तिहाई से आधा भाग होता था। राज्य ने उपज का अनुमान लगाकर या कभी-कभी प्रत्यक्ष निरीक्षण के द्वारा <i>भूमि की उत्पादकता के आधार पर</i> कर की दर निर्धारित की। भूमि से अतिरिक्त आय अन्य करों जैसे <i>व्यापारिक शुल्क, चराई कर, गौ-कर, सिंचाई कर</i> आदि से भी होती थी।</p>\r\n\r\n<h2>भू-राजस्व व्यवस्था की शुरुआत</h2>\r\n<p>मराठा साम्राज्य की भू-राजस्व व्यवस्था की नींव <strong>शिवाजी महाराज</strong> के शासनकाल में पड़ी थी। शिवाजी ने सत्ता प्राप्ति के बाद न केवल युद्धों में विजयी होने का प्रयास किया, बल्कि <strong>राज्य की आंतरिक व्यवस्था को भी सुदृढ़ करने</strong> के लिए कई प्रशासनिक सुधार किए। उनका उद्देश्य था कि <i>राज्य के सभी स्रोतों से राजस्व का संग्रहण सुनिश्चित</i> हो और इसका समुचित उपयोग राज्य के विकास में किया जा सके।</p>\r\n<p>शिवाजी ने अपने शासनकाल में एक ऐसी प्रणाली विकसित की, जिसमें <strong>भूमि की उपज के आधार पर कर लिया जाता था</strong>। यह प्रणाली बाद में मराठा साम्राज्य के अन्य क्षेत्रों में भी लागू की गई। वे विशेष रूप से उन क्षेत्रों में राजस्व एकत्र करते थे, जहाँ <i>कृषि प्रमुख आर्थिक गतिविधि</i> थी। उनकी भूमि व्यवस्था में <i>जमीन के आकार, उपज, और कृषि उत्पादन</i> को देखते हुए करों का निर्धारण किया जाता था।</p>\r\n\r\n<h2>मालगुज़ारी (Land Revenue) प्रणाली</h2>\r\n<p>मराठा साम्राज्य में भू-राजस्व का मुख्य रूप <strong>मालगुज़ारी</strong> था, जो किसानों से उनकी कृषि उपज के आधार पर लिया जाता था। सामान्यत: यह कर उपज के एक तिहाई हिस्से के बराबर होता था, हालांकि यह विभिन्न क्षेत्रों में भिन्न हो सकता था। किसी भी भूमि से होने वाली उपज पर कर की दर निर्धारण करते समय, यह सुनिश्चित किया जाता था कि <i>भूमि से अधिकतम उत्पादन प्राप्त हो</i>। मालगुज़ारी की यह दर <strong>सम्राट के आदेश से</strong> तय की जाती थी और इसे <i>स्थानीय प्रशासनिक अधिकारियों</i> के माध्यम से लागू किया जाता था।</p>\r\n<p>मालगुज़ारी का संग्रहण मुख्यतः <strong>जमींदारों और स्थानीय अधिकारियों</strong> द्वारा किया जाता था। वे किसानों से कर एकत्र करते थे और इसे राज्य को भेजते थे। इस प्रक्रिया में अगर किसी किसान से अधिक कर लिया जाता था, तो राज्य के अधिकारी उसे <i>पुनः प्राप्त करने के लिए सक्रिय</i> होते थे।</p>\r\n\r\n<h2>भू-राजस्व प्रणाली का प्रशासन</h2>\r\n<p>मराठा साम्राज्य में भू-राजस्व संग्रहण की व्यवस्था को प्रभावी बनाने के लिए एक <strong>सशक्त प्रशासनिक ढांचा</strong> था। यह प्रशासनिक तंत्र <i>ग्रामीण स्तर से लेकर साम्राज्य के केंद्रीय स्तर</i> तक विस्तारित था। भूमि के संबंधित रिकॉर्ड रखने और राजस्व संग्रहण के कार्य में विभिन्न प्रकार के अधिकारी होते थे।</p>\r\n\r\n<h3 class=\"atech\">पटवारी</h3>\r\n<p>ये अधिकारी <strong>स्थानीय स्तर पर भूमि रिकॉर्ड रखने</strong> और राजस्व संग्रहण का कार्य करते थे। वे <i>भूमि के मालिकों और किसानों</i> के बीच संपर्क में रहते थे और भूमि के बारे में सभी जानकारी रखते थे।</p>\r\n\r\n<h3 class=\"atech\">तहसीलदार</h3>\r\n<p><strong>तहसीलदार क्षेत्रीय अधिकारियों</strong> का कार्य करते थे और पटवारियों के माध्यम से जमीन से जुड़े मामलों का निपटान करते थे। वे <i>राजस्व संग्रहण की प्रक्रिया को सुव्यवस्थित और पारदर्शी</i> बनाने के लिए जिम्मेदार होते थे।</p>\r\n\r\n<h3 class=\"atech\">पाटील</h3>\r\n<p><strong>पाटील का कार्य ग्राम स्तर पर प्रशासन को संभालना</strong> और राजस्व संग्रहण में सहायता करना था। वे गांवों के प्रमुख होते थे और <i>राजस्व से संबंधित मामलों का हल</i> करते थे।</p>\r\n\r\n<h2>लेखाधिकारी</h2>\r\n<p>मराठा साम्राज्य में <strong>भूमि रिकॉर्ड का रखरखाव</strong> एक महत्वपूर्ण कार्य था, जिसे मुख्य रूप से <strong>कुलकर्णी</strong> नामक अधिकारी द्वारा किया जाता था। कुलकर्णी का कार्य था <i>भूमि के आकार, उत्पादन, और मालिकों</i> की जानकारी का रिकॉर्ड रखना। वे यह सुनिश्चित करते थे कि <strong>सभी भूमि रिकॉर्ड सही और अद्यतन</strong> रहें, ताकि किसी भी प्रकार की <i>गलतफहमी या विवाद</i> से बचा जा सके।</p>\r\n<p><i>भूमि के रिकॉर्ड में यह निर्धारित किया जाता था कि किसी विशेष क्षेत्र में कितनी भूमि पर कृषि की जा रही है और उस पर कितना मालगुज़ारी लिया जाएगा।</i> इसके अलावा, कुलकर्णी <strong>भूमि के स्वामित्व के बारे में भी जानकारी</strong> रखते थे, जिससे किसी प्रकार की भूमि विवादों को सुलझाने में मदद मिलती थी।</p>\r\n\r\n<h2>रैयतवाड़ी प्रणाली</h2>\r\n<p>मराठा साम्राज्य में <strong>रैयतवाड़ी प्रणाली</strong> भी एक प्रमुख हिस्सा थी, जिसमें <i>किसानों को भूमि का उपयोग करने का अधिकार</i> मिलता था, लेकिन इसके बदले उन्हें उस भूमि पर उपज के आधार पर कर चुकाना होता था। इस प्रणाली के तहत किसानों को <strong>भूमि का मालिकाना अधिकार नहीं</strong> होता था, लेकिन वे उससे लाभ उठा सकते थे, और राज्य से सीधे तौर पर कर चुकाते थे।</p>\r\n<p>रैयतवाड़ी प्रणाली के तहत, <strong>राज्य ने भूमि के बंटवारे को नियंत्रित</strong> किया और किसानों से सीधे कर लिया। यह प्रणाली मराठा साम्राज्य के तहत <i>किसानों को अधिक स्वतंत्रता देती थी</i>, लेकिन साथ ही यह सुनिश्चित करती थी कि राज्य को राजस्व प्राप्त हो।</p>\r\n\r\n<h2>जमींदारी व्यवस्था</h2>\r\n<p><strong>जमींदारी व्यवस्था</strong> मराठा साम्राज्य में भू-राजस्व संग्रहण का एक महत्वपूर्ण हिस्सा थी। <strong>जमींदार</strong>, जो स्थानीय अधिकारियों होते थे, भूमि के मालिक होते थे और वे <i>भूमि पर कृषि के आधार पर</i> राजस्व एकत्र करते थे। वे अपने क्षेत्र में <strong>किसानों से मालगुज़ारी वसूलते थे</strong> और इसे राज्य को भेजते थे। जमींदारों का कार्य सिर्फ राजस्व वसूलना नहीं था, बल्कि वे <strong>स्थानीय प्रशासन के महत्वपूर्ण अंग</strong> भी थे, जो <i>कानून-व्यवस्था बनाए रखने में मदद</i> करते थे।</p>\r\n<p>जमींदारों के <strong>अधिकारों और कर्तव्यों का निर्धारण</strong> राज्य के प्रशासन द्वारा किया जाता था। वे <i>किसानों से भूमि कर वसूलने</i> के साथ-साथ प्रशासनिक कार्यों में भी सक्रिय रूप से शामिल होते थे। <strong>जमींदारों का कार्य महत्वपूर्ण</strong> था, क्योंकि वे राज्य की आय का प्रमुख स्रोत होते थे।</p>\r\n\r\n<h2>अन्य करों का संग्रहण</h2>\r\n<p>मराठा साम्राज्य में केवल <strong>मालगुज़ारी</strong> ही नहीं, बल्कि अन्य प्रकार के करों का भी संग्रहण किया जाता था। इनमें <strong>व्यापारिक कर, पशु कर (गस्ती कर)</strong>, और अन्य शुल्क शामिल थे। इन करों का उद्देश्य <i>राज्य की विभिन्न गतिविधियों को वित्तीय समर्थन</i> देना था।</p>\r\n<p><strong>व्यापारिक करों</strong> के तहत व्यापारियों से <i>उनके व्यापार पर कर</i> लिया जाता था, जो साम्राज्य के विभिन्न क्षेत्रों में व्यापार करने वाले लोगों से वसूला जाता था। <strong>गस्ती कर</strong>, जिसे <i>पशु कर</i> भी कहा जाता था, विशेष रूप से <strong>पशुपालन से संबंधित</strong> था और इसे किसानों और पालतू पशु रखने वालों से लिया जाता था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>मराठा साम्राज्य की भू-राजस्व व्यवस्था</strong> ने न केवल <strong>राज्य की आय को सुनिश्चित</strong> किया, बल्कि <i>प्रशासनिक दक्षता और पारदर्शिता</i> को भी बढ़ावा दिया। इस व्यवस्था ने <strong>कृषि आधारित अर्थव्यवस्था को सशक्त</strong> किया और <i>राजस्व संग्रहण की प्रक्रिया को सरल और प्रभावी</i> बनाया। <strong>भूमि रिकॉर्ड, राजस्व संग्रहण, और जमींदारी प्रणाली</strong> जैसे तंत्रों ने साम्राज्य को एक <i>मजबूत प्रशासनिक और आर्थिक ढांचा</i> प्रदान किया। इस व्यवस्था ने मराठा साम्राज्य को एक <strong>सशक्त और समृद्ध राज्य</strong> बनाने में महत्वपूर्ण भूमिका निभाई।</p>\r\n',35,'2025-06-04 13:59:42','2025-06-04 14:14:10','','Publish',0,'open',19,126),('मराठा साम्राज्य की सैनिक प्रशासन व्यवस्था','sainik-administration-of-maratha-empire',2,'<p><strong>मराठा साम्राज्य की सैनिक प्रशासन व्यवस्था</strong> <i>अत्यधिक संगठित और प्रभावी</i> थी। इसकी नींव <strong>छत्रपति शिवाजी महाराज</strong> ने 17वीं शताब्दी में रखी थी, जिन्होंने एक <i>अनुशासित और रणनीतिक सैन्य प्रणाली</i> विकसित की।</p>\r\n\r\n<p>साम्राज्य <strong>1674</strong> में <i>छत्रपति शिवाजी महाराज के राज्याभिषेक</i> से शुरू हुआ और <strong>1761</strong> में <i>पानीपत के तीसरे युद्ध</i> के बाद धीरे-धीरे कमजोर हो गया। <i>ब्रिटिश ईस्ट इंडिया कंपनी</i> के भारतीय उपमहाद्वीप पर नियंत्रण पाने से पहले, <strong>मुग़ल साम्राज्य को समाप्त करने</strong> का श्रेय मुख्य रूप से <strong>मराठों</strong> को दिया जाता है।</p>\r\n\r\n<h2>सैनिक प्रशासन में सुधार</h2>\r\n<p>शिवाजी महाराज ने मराठा सेना की नींव <i>बड़ी समझदारी और व्यवहारिक सोच</i> के साथ रखी थी। उस समय की <strong>पुरानी और कमजोर सामंती सैन्य व्यवस्था</strong> को समाप्त कर उन्होंने एक <i>वफादार और अनुशासित सेना</i> का गठन किया।</p>\r\n\r\n<h3 class=\"atech\">सामंती व्यवस्था का अंत</h3>\r\n<p>शिवाजी से पहले <i>मराठा सरदारों की निजी सेनाएँ</i> होती थीं, जो सिर्फ आवश्यकता पड़ने पर राजा की सहायता करती थीं। शिवाजी ने इस <strong>अविश्वसनीय प्रणाली</strong> को समाप्त कर <i>राज्य के अधीन वेतनभोगी सेना</i> स्थापित की। इससे <strong>राजा के प्रति निष्ठा</strong> और अनुशासन बढ़ा।</p>\r\n\r\n<h3 class=\"atech\">भर्ती प्रक्रिया</h3>\r\n<p>शिवाजी ने <i>शारीरिक रूप से योग्य</i> लोगों की भर्ती की और <strong>जाति और धर्म से ऊपर उठकर</strong> सभी वर्गों को मौका दिया। <i>मावले</i>, जो <strong>पहाड़ी इलाकों</strong> से आते थे, उन्हें पैदल सेना में शामिल किया गया।</p>\r\n\r\n<h3 class=\"atech\">सैनिकों का प्रशिक्षण</h3>\r\n<p>सैनिकों को <strong>तलवार, भाला, तीर-कमान</strong> और <i>पर्वतीय युद्ध कौशल</i> में प्रशिक्षित किया जाता था। <i>घुड़सवार सैनिकों</i> को तेज हमले और गति पर विशेष प्रशिक्षण दिया जाता था।</p>\r\n\r\n<h3 class=\"atech\">हथियार और उपकरण</h3>\r\n<p>शिवाजी ने <i>स्थानीय शस्त्रागार</i> बनवाए जहाँ <strong>तलवार, भाले, धनुष-बाण</strong> और बाद में <i>तोपें</i> भी बनती थीं। सैनिकों को <i>युद्ध-सामग्री समय पर</i> दी जाती थी।</p>\r\n\r\n<h3 class=\"atech\">सैन्य अनुशासन</h3>\r\n<p>शिवाजी की सेना में <strong>कड़ा अनुशासन</strong> था। यदि कोई <i>नियम तोड़ता</i>, तो उसे <strong>सख्त सजा</strong> मिलती थी। शिवाजी के युद्ध नियम अत्यंत नैतिक थे:</p>\r\n<ul>\r\n    <li><i>आम जनता को नुकसान न पहुँचाना</i></li>\r\n    <li><i>धार्मिक स्थलों और ग्रंथों को सम्मान देना</i></li>\r\n    <li><i>लूट को राज्यकोष में जमा करना</i></li>\r\n</ul>\r\n\r\n<h2>मराठा सैनिक प्रशासन की संरचना</h2>\r\n<p>शिवाजी महाराज ने एक <strong>सुसंगठित सैन्य ढाँचा</strong> खड़ा किया। <i>छत्रपति</i> सर्वोच्च पद था, जबकि <strong>सर-ए-नौबत</strong> (सेनापति) सेना का <i>कार्यकारी प्रमुख</i> होता था।</p>\r\n\r\n<h3>सैन्य इकाइयाँ</h3>\r\n<ul>\r\n    <li><strong>नायक</strong> – <i>5–10 सैनिकों</i> का नेता</li>\r\n    <li><strong>हवलदार</strong> – <i>लगभग 25 सैनिकों</i> का प्रभारी</li>\r\n    <li><strong>जुमलादार</strong> – <i>100 सैनिकों</i> का कमांडर</li>\r\n    <li><strong>हजारी</strong> – <i>1000 सैनिकों</i> का कमांडर</li>\r\n    <li><strong>पंचहजारी</strong> – <i>5000 सैनिकों</i> का कमांडर</li>\r\n    <li><strong>सरनौबत</strong> – <i>समग्र क्षेत्रीय सेना</i> का प्रभारी</li>\r\n</ul>\r\n<p><strong>सैन्य पदक्रम</strong>: <i>हवलदार → जुमलादार → हजारी → पंचहजारी → सरनौबत</i></p>\r\n\r\n<h3>घुड़सवार सेना का संगठन</h3>\r\n<h4 class=\"atech\">शिलेदार (अस्थायी घुड़सवार)</h4>\r\n<p>ये <i>स्वयं के घोड़े और हथियार</i> लाते थे। इन्हें <strong>लूट में हिस्सा</strong> मिलता था और <i>स्वतंत्रता से कार्य</i> करते थे।</p>\r\n\r\n<h4 class=\"atech\">बारगीर (स्थायी घुड़सवार)</h4>\r\n<p>राज्य द्वारा <strong>नियुक्त और वेतनभोगी</strong>। इन्हें <i>राज्य से घोड़े और हथियार</i> मिलते थे। ये <strong>अनुशासित और लड़ाई के लिए सदैव तैयार</strong> रहते थे।</p>\r\n\r\n<h3 class=\"atech\">पैदल सेना</h3>\r\n<p><strong>पैदल सैनिक</strong> युद्ध के <i>मुख्य आधार</i> थे। इनमें शामिल थे:</p>\r\n<ul>\r\n    <li><strong>मावले</strong> – <i>पर्वतीय क्षेत्रों</i> से, <strong>कुशल और साहसी</strong></li>\r\n    <li><strong>धनुर्धर</strong> – <i>तीरंदाजी</i> में निपुण</li>\r\n    <li><strong>तलवारबाज</strong> – <i>तलवार और ढाल</i> से लड़ने वाले</li>\r\n    <li><strong>भालाधारी</strong> – <i>भाले चलाने</i> में निपुण</li>\r\n    <li><strong>बंदूकधारी (हेतकरी)</strong> – <i>आधुनिक हथियारों</i> से लैस</li>\r\n</ul>\r\n<p><i>मावले</i> <strong>शिवाजी के अंगरक्षक</strong> भी होते थे।</p>\r\n\r\n<h3 class=\"atech\">तोपखाना विभाग</h3>\r\n<p>प्रारंभिक काल में सीमित था, पर <strong>पेशवाओं</strong> के समय <i>फ्रांसीसी और पुर्तगाली तोपचियों</i> की मदद से <strong>विकसित और संगठित</strong> किया गया।</p>\r\n\r\n<h3 class=\"atech\">रसद विभाग</h3>\r\n<p><i>युद्ध सामग्री, भोजन, और हथियारों</i> की आपूर्ति सुनिश्चित करता था। यह <strong>सैनिक अभियानों की रीढ़</strong> था।</p>\r\n\r\n<h3 class=\"atech\">खुफिया विभाग</h3>\r\n<p>शिवाजी की <i>गुप्तचर प्रणाली</i> अत्यंत प्रभावी थी। <strong>शत्रु की गतिविधियों की जानकारी</strong> पहले से मिलने पर शिवाजी <i>रणनीति तय</i> करते थे।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>मराठा सैन्य प्रशासन</strong> भारतीय इतिहास में <i>साहस, अनुशासन, और रणनीति</i> का प्रतीक है। <strong>छत्रपति शिवाजी महाराज</strong> के नेतृत्व में विकसित यह व्यवस्था <strong>18वीं सदी तक</strong> प्रभावशाली रही। यद्यपि <i>आंतरिक संघर्ष और ब्रिटिश हस्तक्षेप</i> के कारण मराठा साम्राज्य का पतन हुआ, फिर भी इसकी <i>सैन्य संरचना और रणनीतियाँ</i> आज भी <strong>अध्ययन और प्रेरणा</strong> का विषय हैं।</p>\r\n',54,'2025-06-04 13:59:42','2025-06-04 14:25:21','','Publish',0,'open',68,127),('मुगल कालीन मनसबदारी प्रणाली','mughal-carpet-mansabdari-system',2,'<p><strong>मनसबदारी व्यवस्था</strong> <i>मुगल बादशाहों द्वारा स्थापित एक प्रशासनिक और सैन्य संरचना</i> थी, जिसका उद्देश्य उनके कुलीन वर्ग और सेना को संगठित करना था। इसका महत्व इस बात में निहित है कि इसने किस तरह <strong>कुशल शासन, राजस्व संग्रह और सैन्य संगठन</strong> को सक्षम बनाया, जिससे <i>मुगल साम्राज्य की स्थिरता और विस्तार</i> में योगदान मिला।</p>\r\n\r\n<p><strong>\'मनसब\'</strong> शब्द <i>अरबी भाषा</i> से आया है, जिसका अर्थ है \"पद\", \"स्थिति\" या \"रैंक\"। मनसब जितना ऊंचा होगा, <strong>अधिकारी का वेतन, दर्जा और पद</strong> भी उतना ही ऊंचा होगा। यद्यपि प्रशासनिक अभिलेखों में मनसबदारों की 66 श्रेणियाँ थीं, किन्तु व्यवहार में केवल 33 मनसब ही थे। भारत में इस प्रणाली की शुरुआत <strong>अकबर</strong> ने की थी। यद्यपि पहले के शासकों ने भी सैन्य अधिकारियों को रैंक दिए थे, परंतु <i>अकबर ने इसे एक संगठित और केंद्रीकृत व्यवस्था</i> का रूप दिया।</p>\r\n\r\n<h2>मनसबदारी प्रणाली</h2>\r\n<p>मनसबदारी प्रणाली के अंतर्गत <strong>रैंक (मनसब)</strong> दो भागों में विभाजित थे- <strong>ज़ात</strong> और <strong>सवार</strong>, <strong>ज़ात</strong> शब्द का अर्थ है <i>व्यक्तिगत</i>। यह <strong>व्यक्ति की स्थिति और उसे मिलने वाला वेतन</strong> तय करता था। <strong>सवार</strong> रैंक से यह पता चलता था कि एक व्यक्ति को <strong>कितने घुड़सवार सैनिक रखने</strong> होते थे। </p>\r\n\r\n<p>प्रत्येक मनसब में तीन श्रेणियाँ थीं</p>\r\n<ul>\r\n    <li><p><strong>प्रथम श्रेणी</strong> - वह व्यक्ति जिसे अपनी जात रैंक के बराबर सवार रखने की आवश्यकता होती थी।</p></li>\r\n    <li><p><strong>दूसरी श्रेणी</strong> - वह व्यक्ति जो अपनी जात रैंक के रूप में आधे या उससे अधिक सवार रखता था।</p></li>\r\n    <li><p><strong>तीसरी श्रेणी</strong> - यदि वह अपने जात पद के आधे से भी कम सवारों को रखता है।</p></li>\r\n</ul>\r\n<p>राज्य के लिए सवारों का बड़ा कोटा बनाए रखने वालों को पुरस्कृत करने के लिए <strong>जाट के वेतन में दो रुपये</strong> का अतिरिक्त भत्ता जोड़ा गया। किसी भी व्यक्ति का सवार कोटा <strong>उसकी जात रैंक से अधिक नहीं</strong> हो सकता था।</p>\r\n\r\n<h2>मनसबदारों की नियुक्ति</h2>\r\n<p><i>मुगल काल में</i> मनसबदारों की नियुक्ति <strong>सम्राट द्वारा</strong> की जाती थी। नियुक्ति में व्यक्ति की <strong>योग्यता, वफादारी, कार्यकुशलता, वंश</strong>, और <i>राजनीतिक परिस्थितियों</i> को ध्यान में रखा जाता था। सम्राट योग्य व्यक्ति को \"<strong>सनद</strong>\" (आदेशपत्र) जारी करता था जिसमें उसका <strong>जात और सवार रैंक</strong> निर्धारित होता था। इसके साथ उसे <strong>घुड़सवार सैनिक रखने, वेतन प्राप्त करने और कभी-कभी जागीर का प्रबंधन</strong> करने की जिम्मेदारी दी जाती थी। नियुक्त मनसबदारों का <i>समय-समय पर स्थानांतरण और पदोन्नति</i> भी होती थी ताकि वे अत्यधिक शक्तिशाली न बन जाएँ। यह प्रणाली <strong>सम्राट के केंद्रीकृत नियंत्रण</strong> को बनाए रखने में सहायक थी।</p>\r\n\r\n<h2>मनसबदारों का वेतन</h2>\r\n<p><i>मुगल काल में</i> मनसबदारों का वेतन <strong>उनके जात रैंक</strong> के अनुसार तय होता था। उच्च जात रैंक वाले मनसबदारों को <strong>अधिक वेतन</strong> मिलता था। वेतन दो प्रकार से दिया जाता था:</p>\r\n<ul>\r\n    <li><p><strong>नकद वेतन (नक़दाना)</strong> - कुछ मनसबदारों को <i>राजकोष से सीधे नकद वेतन</i> दिया जाता था। नकद वेतन अपेक्षाकृत कम दिया जाता था और वह भी <strong>प्रमुख या भरोसेमंद अधिकारियों</strong> को ही मिलता था।</p></li>\r\n    <li><p><strong>जागीर के रूप में वेतन</strong> - अधिकतर मनसबदारों को <i>जागीर दी जाती</i> थी, जिसका अर्थ था कि वे <strong>एक निश्चित क्षेत्र से कर (राजस्व) वसूल</strong> सकते थे। यह जागीर <i>स्थायी नहीं होती थी</i> और सम्राट जब चाहे इसे <strong>बदल</strong> सकता था।</p></li>\r\n</ul>\r\n<p>मनसबदारों को अपने <strong>सवारों, घोड़ों और हथियारों</strong> का प्रबंध स्वयं करना होता था, इसलिए उनका वेतन अपेक्षाकृत अधिक होता था। वेतन का उपयोग न केवल <strong>सैन्य खर्चों</strong> में बल्कि <i>दरबारी जीवनशैली</i> बनाए रखने में भी होता था।</p>\r\n\r\n<p><strong>औरंगज़ेब</strong> के शासनकाल में मनसबदारों की संख्या में भारी वृद्धि हुई, लेकिन <strong>जागीरों की सीमितता</strong> के कारण अधिकारियों में असंतोष फैला। औरंगज़ेब ने <i>धार्मिक कट्टरता</i> के चलते कुछ <strong>हिंदू मनसबदारों को पदोन्नति</strong> से वंचित रखा, जिससे प्रशासनिक ढांचे में <strong>सामुदायिक असंतुलन</strong> पैदा हुआ।</p>\r\n\r\n<h2>मनसबदारी प्रणाली के कार्य</h2>\r\n<p><strong>मनसबदार के मुख्य कार्य</strong> निम्नलिखित थे:</p>\r\n<ul>\r\n    <li><p><strong>सैन्य प्रबंधन</strong> - मनसबदारों को अपने अधीन सैनिकों की संख्या और प्रबंधन करना होता था। वे <strong>अपने क्षेत्र में सेना</strong> की ताकत को नियंत्रित करते थे और <i>युद्ध में भाग</i> लेते थे।</p></li>\r\n    <li><p><strong>कर वसूली</strong> - वे <i>अपने क्षेत्र से कर वसूलने</i> और उसे <strong>केंद्र सरकार तक पहुँचाने</strong> के लिए जिम्मेदार होते थे।</p></li>\r\n    <li><p><strong>शासनिक कार्य</strong> - मनसबदार <i>प्रशासन के अन्य कार्यों</i> में भी शामिल होते थे, जैसे <strong>न्याय व्यवस्था की देखरेख</strong> और <i>राज्य की नीतियों</i> का पालन करना।</p></li>\r\n    <li><p><strong>स्थानीय सुरक्षा</strong> - वे अपने क्षेत्र की <strong>सुरक्षा सुनिश्चित</strong> करते थे और किसी भी <i>बाहरी या आंतरिक संकट</i> का मुकाबला करते थे।</p></li>\r\n    <li><p><strong>नियुक्तियाँ और भर्ती</strong> - मनसबदारों को <i>सैनिकों की भर्ती और उनके प्रशिक्षण</i> का कार्य सौंपा जाता था।</p></li>\r\n    <li><p><strong>राजकीय आदेशों का पालन</strong> - मनसबदारों को <strong>सम्राट के आदेशों को लागू</strong> करने और साम्राज्य की <i>संप्रभुता की रक्षा</i> करने का दायित्व होता था।</p></li>\r\n</ul>\r\n\r\n<h2>मनसबदारी प्रणाली में भ्रष्टाचार</h2>\r\n<p><strong>मनसबदारी प्रणाली</strong> का उद्देश्य प्रशासनिक और सैन्य व्यवस्थाओं को मजबूत करना था, लेकिन इसके साथ कुछ <strong>भ्रष्टाचार</strong> भी जुड़े थे:</p>\r\n<ul>\r\n    <li><p>कुछ मनसबदार <i>अधिक घुड़सवारों और सैनिकों की संख्या</i> दिखाकर <strong>वेतन में अधिक लाभ</strong> उठाने की कोशिश करते थे।</p></li>\r\n    <li><p>कुछ मनसबदार <strong>नकली सैनिक दिखाकर</strong> राज्य से अधिक धन प्राप्त करते थे।</p></li>\r\n    <li><p>मनसबदारों को दी गई <strong>जागीरों का प्रबंधन कई बार उचित</strong> तरीके से नहीं किया जाता था।</p></li>\r\n    <li><p>कभी-कभी मनसबदारों की <strong>नियुक्ति और पदोन्नति</strong> केवल <i>राजनीतिक विश्वास और वफादारी</i> के आधार पर होती थी।</p></li>\r\n    <li><p>मनसबदारी प्रणाली ने सम्राट के हाथों में <strong>अत्यधिक शक्ति संकेंद्रित</strong> की, जिससे <strong>स्थानीय प्रशासन कमजोर</strong> पड़ा।</p></li>\r\n</ul>\r\n<p>इन भ्रष्टाचारों ने अंततः <strong>मनसबदारी प्रणाली की प्रभावशीलता</strong> को प्रभावित किया, जिससे बाद में <strong>साम्राज्य में असंतोष और विघटन</strong> बढ़ा।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>मुगल कालीन मनसबदारी प्रणाली</strong> <i>भारतीय प्रशासनिक इतिहास का एक महत्वपूर्ण हिस्सा</i> थी, जिसका उद्देश्य सम्राट के नियंत्रण को बनाए रखना और <strong>सेना तथा प्रशासन को सशक्त बनाना</strong> था।</p>\r\n<p>हालांकि, इस प्रणाली ने प्रशासन को <strong>केंद्रीकृत</strong> किया और <i>सैन्य ताकत को बढ़ावा</i> दिया, लेकिन इसमें कुछ <strong>बस्ताचार और भ्रष्टाचार</strong> के कारण इसकी प्रभावशीलता में कमी आई।</p>\r\n<p>इसके बावजूद, <strong>मनसबदारी प्रणाली</strong> ने <strong>मुगलों के शासन को कुछ हद तक स्थिर</strong> बनाए रखा, लेकिन इसके कमजोरियों के कारण यह प्रणाली <i>समय के साथ समाप्त</i> हो गई। इसने <strong>भारतीय प्रशासन के विकास</strong> में महत्वपूर्ण योगदान दिया, और इसके तत्वों का प्रभाव <i>बाद के समयों में</i> भी देखा गया।</p>\r\n',43,'2025-06-04 13:59:42','2025-06-04 14:41:01','','Publish',0,'open',5,128),('मुगलकालीन सैन्य एवं न्याय व्यवस्था का वर्णन करें','mughal-military-and-judicial-system',2,'<p><strong>मुगल साम्राज्य</strong> भारत के इतिहास का एक ऐसा कालखंड है जो <strong>प्रशासनिक, सैन्य और न्यायिक दृष्टिकोण</strong> से अत्यंत संगठित और प्रभावशाली था। <i>बाबर द्वारा 1526 में स्थापित</i> यह साम्राज्य धीरे-धीरे भारत के अधिकांश भूभाग पर अपना अधिकार स्थापित कर सका। मुगलों ने शासन को सुचारू रूप से चलाने के लिए जिन प्रमुख व्यवस्थाओं को विकसित किया, उनमें <strong>सैन्य और न्यायिक व्यवस्था</strong> का विशेष महत्व था। इन व्यवस्थाओं ने न केवल मुगलों की सत्ता को स्थायित्व प्रदान किया, बल्कि राज्य की एकता और अनुशासन को बनाए रखने में भी बड़ी भूमिका निभाई।</p>\r\n\r\n<h2>मुगलकालीन सैन्य व्यवस्था</h2>\r\n\r\n<p>मुगल साम्राज्य की स्थायित्व और विस्तार की नींव उसकी <strong>सुदृढ़ सैन्य व्यवस्था</strong> पर आधारित थी। यह व्यवस्था मुख्यतः <strong>मंसबदारी प्रणाली, घुड़सवार सेना, तोपखाना,</strong> तथा <strong>रणनीतिक कूटनीति</strong> पर आधारित थी।</p>\r\n\r\n<h3 class=\"atech\">मंसबदारी प्रणाली</h3>\r\n\r\n<p><strong>अकबर</strong> ने मंसबदारी प्रणाली की शुरुआत की, जो मुगल सेना का मेरुदंड बन गई। \'<i>मंसब</i>\' का अर्थ है <i>पद, दर्जा या रैंक</i>। यह व्यवस्था प्रशासनिक और सैन्य दोनों उद्देश्यों के लिए बनाई गई थी। मंसबदारों को दोहरे रैंक दिए जाते थे</p>\r\n<ul>\r\n    <li><p><strong>जात</strong> – <i>कुल सैनिकों की संख्या</i></p></li>\r\n    <li><p><strong>सवार</strong> – <i>व्यक्तिगत रूप से रखे गए घुड़सवारों की संख्या</i></p></li>\r\n</ul>\r\n<p>हर मंसबदार को अपने पद के अनुसार सैनिकों की व्यवस्था करनी होती थी, जिनका निरीक्षण सम्राट द्वारा किया जाता था। मंसबदारों को <strong>नकद वेतन या जागीरें</strong> दी जाती थीं, जिनसे वे अपने सैनिकों का निर्वाह कर सकते थे।</p>\r\n\r\n<h3 class=\"atech\">सेना का विभाजन</h3>\r\n<p>मुगल सेना कई अंगों में विभाजित थी – <strong>घुड़सवार सेना, पैदल सेना, तोपखाना, हाथी-दल</strong> और <strong>ऊँट-दल</strong>। इनमें से <strong>घुड़सवार सेना</strong> को सबसे अधिक महत्व प्राप्त था क्योंकि यह तीव्र गति और आक्रमण की दृष्टि से सबसे उपयोगी थी। पैदल सेना की भूमिका सीमित थी, और वह प्रायः <i>किलों की रक्षा या शत्रु की घेराबंदी</i> में प्रयुक्त होती थी। <strong>बाबर के समय</strong> से ही तोपखाने का प्रयोग आरंभ हुआ था, जो समय के साथ और प्रभावशाली बना। यह तोपखाना युद्धों में <strong>निर्णायक भूमिका</strong> निभाता था। इसके अलावा युद्ध के सामान और रसद के परिवहन हेतु <strong>ऊँटों और हाथियों</strong> का भी उपयोग किया जाता था।</p>\r\n\r\n<h3 class=\"atech\">भर्ती और वेतन प्रणाली</h3>\r\n<p>मुगलकालीन सैन्य व्यवस्था में कोई <strong>स्थायी या केंद्रीय सेना</strong> नहीं थी। अधिकांश सैनिक <strong>मानसबदारों</strong> के अधीन नियुक्त किए जाते थे। सम्राट के पास केवल एक सीमित <strong>निजी अंगरक्षक सेना</strong> होती थी। सैनिकों और अधिकारियों को वेतन प्रायः <strong>नकद और जागीर</strong> दोनों रूपों में दिया जाता था। जागीर व्यवस्था के अंतर्गत मानसबदारों को राज्य के किसी क्षेत्र की आय एक निश्चित अवधि के लिए दी जाती थी, जिससे वे अपने सैनिकों का भरण-पोषण कर सकें। यद्यपि यह व्यवस्था व्यावहारिक थी, परंतु इसके अंतर्गत <i>भ्रष्टाचार</i> की संभावना भी बनी रहती थी।</p>\r\n\r\n<h2>मुगलकालीन न्याय व्यवस्था</h2>\r\n<p>मुगलकालीन भारत में <strong>न्याय व्यवस्था</strong> एक संगठित और विधिपूर्ण ढांचे पर आधारित थी, जिसका उद्देश्य <strong>राज्य की स्थिरता</strong> बनाए रखना और <strong>जनता को न्याय</strong> प्रदान करना था। यह व्यवस्था मुख्यतः <strong>इस्लामी शरीअत</strong> पर आधारित थी, लेकिन <i>बहुधार्मिक समाज</i> की प्रकृति को ध्यान में रखते हुए कई बार व्यवहारिक लचीलापन भी अपनाया गया। मुगल शासकों, विशेषकर <strong>अकबर और जहाँगीर</strong>, ने न्याय को शासन का एक प्रमुख आधार माना और इसे प्रभावी बनाने के लिए कई प्रयास किए।</p>\r\n\r\n<p>मुगलकालीन न्याय व्यवस्था मुख्यतः <strong>इस्लामी शरीअत कानून</strong> पर आधारित थी। शरीअत के स्रोत <i>कुरान, हदीस, इज्मा</i> (सम्मति) और <i>कियास</i> (तर्क पर आधारित निर्णय) थे। मुगलों ने इस्लामी विधि को <strong>न्याय का मूल आधार</strong> बनाया, लेकिन <i>हिंदू बहुल समाज</i> को ध्यान में रखते हुए कुछ मामलों में लचीलेपन का परिचय भी दिया। विशेष रूप से <strong>अकबर और जहाँगीर</strong> जैसे सम्राटों ने न्याय को <strong>धर्मनिरपेक्ष और सर्वसुलभ</strong> बनाने का प्रयास किया।</p>\r\n\r\n<p>मुगलकालीन न्याय व्यवस्था में विभिन्न स्तरों पर <strong>न्यायिक अधिकारी</strong> नियुक्त किए जाते थे। सर्वोच्च न्यायिक अधिकारी <strong>‘काज़ी-उल-कुज़ात’</strong> कहलाता था, जो पूरे साम्राज्य का प्रधान न्यायाधीश होता था। प्रत्येक सूबे में एक <strong>‘काज़ी’</strong> नियुक्त होता था, जो <i>दीवानी (सिविल) और फौजदारी (अपराध)</i> मामलों की सुनवाई करता था। <strong>मुहतसिब</strong> नामक अधिकारी <strong>बाज़ार और नैतिकता</strong> की देखरेख करता था। न्याय प्रणाली में <strong>‘सदर’</strong> नामक अधिकारी <strong>धार्मिक मामलों</strong> और धार्मिक अनुदानों की देखरेख करता था। इसके अलावा <strong>सूबेदार और फौजदार</strong> जैसे प्रशासनिक अधिकारी भी <i>स्थानीय न्यायिक शक्तियों</i> का प्रयोग करते थे।</p>\r\n\r\n<p>मुगलकालीन न्याय व्यवस्था को दो प्रमुख वर्गों में बाँटा गया था – <strong>दीवानी</strong> और <strong>फौजदारी</strong>। दीवानी न्यायालय में <i>संपत्ति, उत्तराधिकार, विवाह, कर</i> संबंधी विवादों की सुनवाई की जाती थी। वहीं फौजदारी न्यायालय <i>हत्या, डकैती, बलात्कार, विद्रोह और चोरी</i> जैसे गंभीर अपराधों की सुनवाई करता था। <strong>फौजदारी मामलों में दंड</strong> बहुत कठोर होते थे, जैसे <i>अंग भंग करना, कोड़े लगाना, और मृत्युदंड</i> देना। हालाँकि <strong>न्यायाधीशों</strong> को यह स्वतंत्रता थी कि वे परिस्थितियों के अनुसार <i>दया</i> का प्रयोग कर सकें।</p>\r\n\r\n<p>मुगलकालीन व्यवस्था में <strong>न्याय के लिए अपील</strong> का अधिकार था। यदि कोई व्यक्ति निचली अदालत से असंतुष्ट होता था, तो वह <strong>उच्च न्यायालय</strong> या अंततः <strong>सम्राट की अदालत</strong> में अपील कर सकता था। सम्राट <strong>सर्वोच्च न्यायिक प्राधिकारी</strong> होता था, और विशेष मामलों में स्वयं निर्णय देता था। <strong>जहाँगीर</strong> ने न्याय सुलभ बनाने के लिए अपने महल में <strong>‘झंजीर-ए-अदल’</strong> नामक एक <i>सुनहरी श्रृंखला</i> लगवाई थी, जिसे खींचकर आम नागरिक न्याय की मांग कर सकता था। यह <strong>न्यायप्रियता और जनहित</strong> की भावना का प्रतीक बन गया।</p>\r\n\r\n<p>यद्यपि न्याय प्रणाली <strong>शरीअत</strong> पर आधारित थी, फिर भी <strong>हिंदू प्रजा</strong> के <i>पारिवारिक, सामाजिक और धार्मिक</i> मामलों में <strong>हिंदू विधि</strong> के अनुसार निर्णय लिए जाते थे। इस कार्य में <strong>पंडितों और धर्मशास्त्रियों</strong> की सहायता ली जाती थी। <i>विवाह, उत्तराधिकार और गोत्र-जाति</i> से संबंधित मामलों में <strong>स्थानीय प्रथाओं</strong> और <strong>धार्मिक ग्रंथों</strong> को प्राथमिकता दी जाती थी। <strong>अकबर</strong> जैसे सम्राटों ने <strong>धार्मिक सहिष्णुता</strong> की नीति अपनाई और <strong>बहुधार्मिक समाज</strong> के हित में न्याय प्रणाली को <strong>लचीला</strong> बनाया। जबकि <strong>औरंगजेब</strong> के शासनकाल में न्याय प्रणाली में <strong>इस्लामी कट्टरता</strong> की प्रवृत्ति दिखाई देती है।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>मुगलकालीन सैन्य और न्याय व्यवस्था</strong> ने भारत के मध्यकालीन इतिहास को <strong>स्थायित्व और अनुशासन</strong> प्रदान किया। <strong>सैन्य प्रणाली, विशेष रूप से मानसबदारी</strong>, ने एक <strong>केंद्रीकृत लेकिन लचीला ढांचा</strong> प्रस्तुत किया, जिससे विशाल सेना का संचालन संभव हो सका। <strong>न्याय व्यवस्था</strong>, यद्यपि शरीअत पर आधारित थी, फिर भी उसमें <strong>धर्मनिरपेक्षता और व्यवहारिकता</strong> के लक्षण दिखाई देते हैं, विशेषकर <strong>अकबर और जहाँगीर</strong> जैसे सम्राटों के काल में। हालाँकि समय के साथ इन व्यवस्थाओं में <i>शिथिलता, भ्रष्टाचार और पक्षपात</i> बढ़ता गया, जिसने मुगल शासन की नींव को कमजोर किया। फिर भी, इन व्यवस्थाओं की <strong>परिकल्पना और उनका व्यावहारिक क्रियान्वयन</strong> उस कालखंड की <strong>प्रशासनिक कुशलता</strong> का प्रमाण हैं।</p>\r\n',67,'2025-06-04 13:59:42','2025-06-04 14:50:47','','Publish',0,'open',5,129),('मुगलों का राजस्व प्रशास','mughals-revenue-administration',2,'<p>मुगल कालीन राज्य को प्रशासन की स्थापना के साथ-साथ <strong>भू राशियों</strong> का प्रश्न अत्यंत महत्वपूर्ण हो गया क्योंकि <strong>राष्ट्र</strong> वहीं राज्य की आय का प्रधान स्रोत था। भारत युगों से एक <strong>कृषि प्रधान देश</strong> रहा है। मुगल काल में भी भूमि की <i>कष्टकारी कारखाने</i> पहले से ही रही रहा था। वास्तव में मुगल कालीन भूमि व्यवस्था <i>मुस्लिम विचारधारा</i> और पूर्व प्रचलित देसी संस्थाओं का मिश्रण भी सामान्य रूप से <i>तुर्कों</i> ने <i>इस्लाम अर्थव्यवस्था</i> संबंधित सिद्धांतों को अपनाया। यह व्यवस्था मुख्यतः बगदाद के प्रसिद्ध ग्रंथ <i>\"किताब-उल-खराज\"</i> पर आधारित थी। भूमि कर को <i>\"खराज\"</i> कहा जाता था, जो विशेष रूप से गैर-मुस्लिम (मुख्यतः हिंदू) किसानों और जमींदारों से वसूला जाता था।</p>\r\n\r\n<ul>\r\n    <li><p><strong>प्राकृतिक सिंचाई वाली भूमि:</strong> उपज का 1/10 भाग कर के रूप में लिया जाता था।</p></li>\r\n    <li><p><strong>कृत्रिम सिंचाई वाली भूमि:</strong> उपज का 1/5 भाग कर के रूप में वसूला जाता था।</p></li>\r\n</ul>\r\n\r\n<p>हालांकि <i>खराज</i> की कोई निश्चित दर नहीं थी, फिर भी सामान्यतः यह उपज का 1/3 भाग से अधिक नहीं होता था। केवल <strong>अलाउद्दीन खिलजी</strong> और <strong>मोहम्मद बिन तुगलक</strong> के समय में उपज का 1/2 भाग तक वसूला गया था।</p>\r\n\r\n<p><strong>राज्य को आय</strong> (कमाई) कई तरीकों से होती थी</p>\r\n<ul>\r\n    <li><p>युद्ध में लूटी गई चीजों से एक हिस्सा <i>‘बेखम’</i> नाम से लिया जाता था।</p></li>\r\n    <li><p>हिंदुओं से धार्मिक कर <i>‘जजिया’</i> और मुसलमानों से <i>‘जकात’</i> वसूला जाता था।</p></li>\r\n    <li><p>व्यापार पर टैक्स, उपहार, लावारिस संपत्ति, <i>नमक कर</i> और उद्योगों से भी सरकार को पैसा मिलता था।</p></li>\r\n    <li><p>गांव और कस्बों में रहने वाली आम जनता से छोटे-छोटे स्थानीय टैक्स भी लिए जाते थे।</p></li>\r\n</ul>\r\n\r\n<h2>खेती और जमीन से आय</h2>\r\n<p>मुगल सरकार की सबसे बड़ी आमदनी <strong>खेती की जमीन</strong> से होती थी। <strong>अकबर</strong> के समय में लगभग सारी जमीन को <strong>जागीरों</strong> में बांट दिया गया था। <strong>शेरशाह सूरी</strong> ने पहले एक अच्छी <strong>लगान व्यवस्था</strong> बनाई थी, लेकिन उसके बेटे की मृत्यु के बाद वह खत्म हो गई। जब अकबर ने दोबारा दिल्ली पर राज किया, तो उसने पुरानी <strong>जागीरदारी व्यवस्था</strong> को फिर से शुरू किया।</p>\r\n\r\n<h3>मुगल काल में भूमि के प्रकार और राजस्व</h3>\r\n<p>मुगल शासन में ज़मीन को कई प्रकारों में बाँटा गया था, ताकि <strong>राजस्व (टैक्स)</strong> वसूली सही ढंग से की जा सके।</p>\r\n\r\n<h4 class=\"atech\">खालसा भूमि</h4>\r\n<p><strong>खालसा भूमि</strong> वो ज़मीन होती थी जो सीधे <strong>मुगल बादशाह</strong> के नियंत्रण में रहती थी। इस ज़मीन से जो भी पैसा (टैक्स) वसूला जाता था, वो सीधे राजा के खजाने में जाता था। इस पैसे का इस्तेमाल राजा अपने निजी खर्चों में करता था – जैसे <i>शाही परिवार</i> की देखभाल, अंगरक्षकों और निजी सैनिकों की तनख्वाह, और युद्ध की तैयारियों में।</p>\r\n<p>पूरे मुगल साम्राज्य की लगभग 20% ज़मीन <strong>खालसा भूमि</strong> के अंतर्गत आती थी। 1573 ई. में <strong>अकबर</strong> ने फैसला किया कि जागीरों की ज़मीनें कम करके <strong>खालसा भूमि</strong> बढ़ाई जाए। <strong>जहाँगीर</strong> ने बाद में इसे थोड़ा घटा दिया। <strong>शाहजहाँ</strong> ने फिर से इसे बढ़ा दिया। लेकिन <strong>औरंगज़ेब</strong> के शासन के आखिरी समय में <strong>खालसा ज़मीन</strong> को फिर से जागीरदारों को बाँटना शुरू कर दिया गया।</p>\r\n\r\n<h4 class=\"atech\">जागीर भूमि</h4>\r\n<p>यह ज़मीन मुगलों के <strong>अधिकारियों</strong>, <strong>सेनापतियों</strong> या <strong>अमीरों</strong> को तनख़्वाह (वेतन) के बदले दी जाती थी। वे इस ज़मीन से टैक्स वसूलते थे, लेकिन मालिक नहीं होते थे। जब उनका काम या सेवा खत्म हो जाती, तो ज़मीन वापस ले ली जाती थी।</p>\r\n<p>जब यह ज़मीन केंद्र सरकार के सीधे नियंत्रण में वापस आती थी, तो उसे <i>‘पायबाकी’</i> कहा जाता था। इसका मतलब होता था कि अब वह ज़मीन फिर से सरकार के पास लौट गई है।</p>\r\n<p><strong>जागीरदारों पर नजर रखने</strong> के लिए एक खास विभाग होता था, जिसका नाम था <i>‘सावानिहनिगार’</i>। यह विभाग जागीरदारों की गतिविधियों और जानकारी को केंद्र सरकार को भेजता था, ताकि उन पर निगरानी रखी जा सके।</p>\r\n\r\n<h4 class=\"atech\">इन्हाम भूमि (इनामी ज़मीन)</h4>\r\n<p>यह ज़मीन किसी <strong>विद्वान</strong>, <strong>धर्मगुरु</strong> या खास व्यक्ति को इनाम के रूप में दी जाती थी। इस पर टैक्स नहीं लिया जाता था। यह दान या पुरस्कार के रूप में दी जाती थी।</p>\r\n\r\n<h4 class=\"atech\">वक़्फ़ भूमि</h4>\r\n<p>यह ज़मीन धार्मिक या सामाजिक कार्यों के लिए तय की जाती थी (जैसे <i>मस्जिद</i>, <i>मदरसे</i>, <i>दरगाह</i> आदि)। इस प्रकार की भूमि को <i>\'मदद-ए-माश\'</i> भी कहा जाता था। इससे होने वाली आय धार्मिक संस्थाओं या समाज सेवा में लगती थी। इस पर टैक्स नहीं लिया जाता था। इस भूमि को <i>‘मिल्क’</i> भी कहा जाता था।</p>\r\n\r\n<p><strong>अकबर</strong> ने 1580 में एक नई योजना शुरू की जिसे <i>‘आईन-ए-दहसाला’</i> कहा जाता है। इसमें हर क्षेत्र की 10 साल की औसत उपज के हिसाब से लगान तय किया जाता था। इससे हर साल नए सिरे से लगान तय करने की जरूरत नहीं पड़ती थी।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>इस प्रकार, मुगल काल में भूमि व्यवस्था अत्यंत संगठित और विविध थी, जो शासन के <strong>वित्तीय</strong>, <strong>सामाजिक</strong> और <strong>धार्मिक</strong> उद्देश्यों की पूर्ति के लिए बनाई गई थी। <strong>खालसा भूमि</strong> वह ज़मीन थी जो सीधे मुग़ल बादशाह के नियंत्रण में रहती थी और इसका राजस्व सीधे राजा के खजाने में जाता था। <strong>जागीर भूमि</strong> अधिकारियों और सैनिकों को सेवा के बदले दी जाती थी, जबकि <strong>इन्हाम भूमि</strong> विशेष व्यक्तियों को इनाम के रूप में दी जाती थी। <strong>वक़्फ़ भूमि</strong> का उपयोग धार्मिक और समाज सेवा कार्यों के लिए किया जाता था और इससे होने वाली आय का उपयोग धार्मिक संस्थाओं में होता था। इन विभिन्न प्रकार की भूमि प्रणालियों ने मुगल प्रशासन को सशक्त किया और समाज में संतुलन बनाए रखा। <strong>मुगल कालीन भूमि व्यवस्था</strong> ने न केवल <strong>कर वसूली</strong> को प्रभावी बनाया, बल्कि <strong>सामाजिक</strong> और <strong>धार्मिक गतिविधियों</strong> को भी प्रोत्साहित किया, जिससे <strong>समृद्ध और स्थिर साम्राज्य</strong> का निर्माण हुआ।</p>\r\n',58,'2025-06-04 13:59:42','2025-06-04 15:02:12','','Publish',0,'open',5,130),('विजयनगर साम्राज्य की केंद्रीय प्रशासनिक व्यवस्था का वर्णन कीजिए','central-administrative-system-of-vijayanagara-empire',2,'<p><strong>विजयनगर साम्राज्य (1336–1646 ई.)</strong> <i>दक्षिण भारत</i> का एक शक्तिशाली एवं संगठित साम्राज्य था जिसकी स्थापना <strong>हरिहर और बुक्का</strong> ने की थी। इस साम्राज्य की सफलता का एक प्रमुख कारण इसकी <strong>सुदृढ़ केंद्रीय प्रशासनिक व्यवस्था</strong> थी, जो न केवल शासन को सुचारू रूप से चलाने में सहायक थी, बल्कि विशाल क्षेत्र पर नियंत्रण बनाए रखने में भी सक्षम थी। यह प्रशासन एक <i>मध्यकालीन हिन्दू राजतंत्र</i> की उत्तम मिसाल है, जिसमें <strong>राजा सर्वोच्च सत्ता</strong> का धारक होता था, परंतु उसे अपने <strong>मंत्रिपरिषद</strong> और <strong>सैन्य अधिकारियों</strong> का सहयोग भी लेना पड़ता था।</p>\r\n\r\n<h2>राजा</h2>\r\n<p>विजयनगर साम्राज्य में <strong>राजा को ‘धर्म और न्याय का संरक्षक’</strong> माना जाता था। वह न केवल <strong>प्रशासनिक प्रमुख</strong> होता था बल्कि <strong>धार्मिक और सैन्य मामलों</strong> में भी अंतिम निर्णय वही करता था। राजा का कार्यक्षेत्र निम्नलिखित था-</p>\r\n<ul>\r\n    <li><p><strong>सैन्य संचालन</strong> एवं <strong>युद्धों का नेतृत्व</strong></p></li>\r\n    <li><p><strong>न्यायिक निर्णय लेना</strong></p></li>\r\n    <li><p><strong>भूमि अनुदान</strong> देना और <strong>कर प्रणाली का नियंत्रण</strong></p></li>\r\n    <li><p><strong>धार्मिक अनुष्ठानों</strong> का संचालन</p></li>\r\n</ul>\r\n<p>राज्य को कई हिस्सों में बाँटा गया था – सबसे बड़े हिस्से को <strong>मंडलम (प्रांत)</strong> कहा जाता था। उसके बाद <strong>नाडु (जिला)</strong>, <strong>स्थल (तहसील)</strong> और <strong>ग्राम (गाँव)</strong> का क्रम आता था। इन क्षेत्रों पर अलग-अलग अधिकारियों की नियुक्ति होती थी, जो <i>स्थानीय स्तर</i> पर शासन चलाते थे। <strong>प्रांतों का प्रशासन</strong> <i>प्रधानी</i> नामक अधिकारी संभालता था, जिसे अक्सर शाही परिवार से या सैन्य अधिकारियों में से चुना जाता था।</p>\r\n<p>प्रसिद्ध विजयनगर सम्राटों में <strong>कृष्णदेव राय</strong>, <strong>देवराय प्रथम</strong> और <strong>अच्युतदेव राय</strong> प्रमुख थे, जिन्होंने प्रशासन को कुशलता से चलाया।</p>\r\n\r\n<h2>मंत्रिपरिषद</h2>\r\n<p>राजा के परामर्श के लिए एक <strong>मंत्रिपरिषद</strong> होती थी, जिसमें विभिन्न विभागों के मंत्री शामिल होते थे। इस परिषद का कार्य <strong>सलाह देना</strong> और <strong>शासन को कार्यान्वित करना</strong> था। मुख्य मंत्री पद इस प्रकार थे:</p>\r\n<ul>\r\n    <li><p><strong>प्रधानमंत्री (महा प्रभु या महामात्य)</strong> - राजा का प्रमुख सलाहकार</p></li>\r\n    <li><p><strong>दंडनायक</strong> - पुलिस और न्याय व्यवस्था का प्रमुख</p></li>\r\n    <li><p><strong>सैनापति</strong> - सेना का संचालन एवं सुरक्षा व्यवस्था का प्रमुख</p></li>\r\n    <li><p><strong>कोषाध्यक्ष (महाकर्णिक)</strong> - राजकोष और राजस्व व्यवस्था का प्रमुख</p></li>\r\n    <li><p><strong>विदेश मंत्री (संधिविग्रहिक)</strong> - कूटनीति एवं बाह्य संबंधों का प्रभारी</p></li>\r\n</ul>\r\n\r\n<h2>प्रशासनिक विभाग</h2>\r\n<p><strong>केंद्रीय प्रशासन</strong> को सुचारू रूप से चलाने के लिए विभिन्न विभाग बनाए गए थे। हर विभाग के प्रमुख मंत्री होते थे और वे अपने क्षेत्र में <strong>पूर्णतः उत्तरदायी</strong> होते थे।</p>\r\n<p><strong>प्रमुख विभाग</strong></p>\r\n<ul>\r\n    <li><p><strong>राजस्व विभाग</strong> - भूमि कर, व्यापार कर और अन्य करों की वसूली करता था।</p></li>\r\n    <li><p><strong>सैन्य विभाग</strong> - सेना की भर्ती, वेतन, अस्त्र-शस्त्र की व्यवस्था करता था।</p></li>\r\n    <li><p><strong>न्याय विभाग</strong> - कानून व्यवस्था बनाए रखने और अपराधों की सुनवाई करता था।</p></li>\r\n    <li><p><strong>वाणिज्य विभाग</strong> - व्यापार, मेला, बाजार और आयात-निर्यात की निगरानी करता था।</p></li>\r\n</ul>\r\n\r\n<h2>राजस्व व्यवस्था</h2>\r\n<p>विजयनगर साम्राज्य की <strong>केंद्रीय व्यवस्था</strong> में <strong>राजस्व व्यवस्था</strong> का विशेष स्थान था। शासन की <strong>आर्थिक नींव भूमि कर</strong> पर आधारित थी। राजस्व दो प्रकार का होता था:</p>\r\n<ul>\r\n    <li><p><strong>स्थायी कर</strong> - यह भूमि पर लगाया जाता था और <i>उपज के 1/3 भाग</i> तक वसूला जाता था।</p></li>\r\n    <li><p><strong>अस्थायी कर</strong> - यह युद्ध, अकाल या अन्य संकटों के समय लगाया जाता था।</p></li>\r\n</ul>\r\n<p>राजस्व वसूली की व्यवस्था <strong>एकदम संगठित</strong> थी। <strong>भूमि की माप, वर्गीकरण</strong> और <strong>मूल्यांकन</strong> के आधार पर कर निर्धारण होता था। <i>पटवारी</i> और <i>लेखपाल</i> जैसे अधिकारी गाँव स्तर पर कार्य करते थे।</p>\r\n\r\n<h2>सैन्य संगठन</h2>\r\n<p>राजा का एक प्रमुख सहायक <strong>सेनापति</strong> होता था जो <strong>केंद्रीय सेना की देखरेख</strong> करता था। विजयनगर की सेना में <strong>पैदल सैनिक, घुड़सवार, हाथी</strong> और <strong>नौसेना</strong> शामिल थी। सेना के संचालन में अनेक प्रमुख <strong>सरदारों (नायकों)</strong> की भूमिका होती थी जो राजा के प्रति <i>वफादार</i> रहते थे। <strong>कृष्णदेव राय</strong> के काल में सेना अत्यंत संगठित और शक्तिशाली थी, जिसने <strong>बहमनी, गोलकुंडा</strong> और <strong>बीजापुर</strong> जैसे मुस्लिम राज्यों के विरुद्ध सफलता प्राप्त की।</p>\r\n\r\n<h2>न्यायिक व्यवस्था</h2>\r\n<p><strong>राजा सर्वोच्च न्यायाधीश</strong> होता था। न्यायिक प्रणाली <strong>वेद, धर्मशास्त्र, मनुस्मृति</strong> और <strong>स्थानीय परंपराओं</strong> पर आधारित थी। न्यायालय <strong>चार स्तरों</strong> पर कार्य करते थे- <strong>केंद्रीय न्यायालय, प्रांतीय न्यायालय, जिला न्यायालय, ग्राम न्यायालय</strong>।</p>\r\n<p>अपराधों के लिए <strong>कड़ी सजाएं</strong> होती थीं जैसे – <i>अंग भंग, मृत्युदंड, संपत्ति की जब्ती</i> आदि। सामाजिक अपराधों में <strong>बहिष्कार</strong> का भी प्रावधान था।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p><strong>विजयनगर साम्राज्य की केंद्रीय प्रशासनिक व्यवस्था</strong> एक संगठित और <strong>परिष्कृत प्रणाली</strong> थी। इसमें <strong>राजा सर्वोच्च</strong> था, परंतु शासन को प्रभावी ढंग से चलाने के लिए <strong>मंत्रिपरिषद, विभागीय व्यवस्था, न्यायिक संस्थान</strong> और एक <strong>मजबूत सैन्य ढांचा</strong> विकसित किया गया था। यह प्रशासनिक संरचना ही विजयनगर साम्राज्य को लगभग <strong>तीन शताब्दियों</strong> तक स्थायित्व देने में सफल रही।</p>\r\n',206,'2025-06-05 14:34:07','2025-06-05 14:41:00','','Publish',0,'open',19,131),('विजयनगर साम्राज्य की स्थानीय प्रशासनिक व्यवस्था (1336-1646)','local-administrative-system-of-vijayanagara-empire',2,'<p><strong>विजयनगर साम्राज्य</strong>, जो <i>दक्षिण भारत में 14वीं से लेकर 17वीं शताब्दी</i> तक एक शक्तिशाली साम्राज्य था, अपनी <i>प्रशासनिक व्यवस्था</i> के लिए प्रसिद्ध था। यह साम्राज्य <strong>हिंदू संस्कृति को बढ़ावा देने</strong>, <i>शानदार इमारतें बनाने</i> और <strong>उत्तर भारत से आने वाले हमलावरों</strong> का सामना करने के लिए जाना जाता है। यह जगह <strong>राजनीति, संस्कृति और व्यापार</strong> का एक बड़ा केंद्र बन गई थी।</p> <p> <strong>विजयनगर साम्राज्य की स्थापना</strong> <i>1336 ई.</i> में <strong>हरिहर प्रथम</strong> और उनके भाई <strong>बुक्का राय प्रथम</strong> ने <i>विद्यारण्य</i> के समर्थन से की थी। अंततः <strong>विजयनगर साम्राज्य</strong> को <i>1565 ई.</i> में <strong>दक्कनी सल्तनतों</strong> की संयुक्त सेना के विरूद्ध <strong>तालीकोटा की लड़ाई</strong> में एक बड़ी हार का सामना करना पड़ा, जिसके कारण विजयनगर साम्राज्य का पतन हो गया।</p> <p><strong>विजयनगर साम्राज्य के महानतम शासक</strong> <i>कृष्णदेव राय</i> ने अपनी पुस्तक \'<i>अमुक्तमाल्यद</i>\' में <strong>राजत्व की स्थिति</strong> के बारे में बताते हुए कहा कि <i>राजा को अपने आसपास राज्य कला में कुशल लोगों को इकट्ठा करना चाहिए और प्रशासन में उनकी सलाह और मदद लेनी चाहिए</i>। वे आगे लिखते हैं, \"<i>एक ताज पहने हुए राजा को हमेशा धर्म की ओर ध्यान रखते हुए शासन करना चाहिए</i>\"।</p> <p><strong>विजयनगर साम्राज्य का प्रशासन</strong> मुख्यतः <strong>तीन प्रमुख स्तरों</strong> पर काम करता था—<strong>केंद्र, क्षेत्रीय और स्थानीय</strong>। इन तीन स्तरों के तहत राज्य के विभिन्न हिस्सों में प्रशासन को प्रभावी तरीके से संचालित किया जाता था। <strong>स्थानीय प्रशासन</strong> में <i>ग्राम, नगर, और जिले</i> जैसी इकाइयों का महत्व था, और इन इकाइयों के माध्यम से साम्राज्य के भीतर विभिन्न प्रशासनिक कार्यों को सहज और प्रभावी ढंग से लागू किया गया। इस व्यवस्था के तहत हर स्तर पर <strong>अधिकारियों की नियुक्ति</strong> की गई थी, जो अपने-अपने क्षेत्रों में शासन व्यवस्था को सही तरीके से चलाने के लिए जिम्मेदार थे।</p> <h2>ग्राम प्रशासन</h2> <p><strong>ग्राम प्रशासन</strong> को सबसे नीचले स्तर पर रखा जाता था। यहाँ पर <strong>ग्राम प्रमुख (ग्रामपति या ग्रामाधिकारी)</strong> का कार्य था। ग्राम प्रमुख का कार्य <i>गाँव के प्रशासन, न्याय, और कर वसूलने</i> का था। इसके अलावा, <i>गाँव के सशस्त्र बलों</i> का नेतृत्व भी ग्राम प्रमुख द्वारा किया जाता था। प्रत्येक गाँव में <strong>पंचायत</strong> का गठन किया जाता था, जिसमें <i>गाँव के बुजुर्ग और प्रमुख व्यक्ति</i> शामिल होते थे। पंचायत का कार्य <i>भूमि विवाद, आपराधिक मामले, और अन्य सामाजिक समस्याओं</i> का निपटारा करना था। ग्राम प्रशासन में निम्नलिखित अधिकारी होते थे:</p> <ul> <li><p><strong>ग्राम प्रधान</strong> – <i>गाँव का प्रमुख प्रशासक</i></p></li> <li><p><strong>कणकपाल</strong> – <i>राजस्व संग्रहकर्ता</i></p></li> <li><p><strong>दंडनायक</strong> – <i>न्यायिक अधिकारी</i></p></li> <li><p><strong>अयंगार</strong> – <i>विभिन्न प्रशासनिक कार्यों को संभालने वाले अधिकारी</i></p></li> </ul> <h2>ज़िला प्रशासन</h2> <p><strong>विजयनगर साम्राज्य में तालुका और ज़िला प्रशासन</strong> में भी एक <i>सुव्यवस्थित संरचना</i> थी। प्रत्येक ज़िले का प्रशासनिक प्रमुख एक अधिकारी होता था, जिसे <strong>\"मंडलिक\" या \"मंडलधिपति\"</strong> कहा जाता था। ये अधिकारी <i>ज़िले के प्रशासन, न्याय, और कर संग्रहण</i> के लिए जिम्मेदार होते थे। तालुका स्तर पर, <strong>\"शंकर\"</strong> या <strong>\"तहसीलदार\"</strong> के रूप में अधिकारी कार्यरत होते थे, जो ज़िले के भीतर कई गाँवों का प्रशासन संभालते थे। ये अधिकारी <i>स्थानीय भूमि कर, व्यापार और समाजिक व्यवस्था</i> के रखरखाव में सहायता करते थे।</p> <h2>नगर प्रशासन</h2> <p><strong>नगरों का प्रशासन</strong> <i>शहर के आकार और महत्व</i> के अनुसार विभिन्न स्तरों पर किया जाता था। बड़े शहरों, जैसे कि <strong>राजधानी विजयनगर</strong> में <i>नगर प्रशासन का अधिक विस्तृत ढांचा</i> था। यहाँ <strong>नगर प्रमुख</strong> की नियुक्ति की जाती थी, जिसका उद्देश्य <i>व्यापार, कानून व्यवस्था, कर संग्रह</i> और <i>बुनियादी सुविधाओं</i> का संचालन करना था। <strong>नगरपालिकाओं</strong> का कार्य <i>व्यापारिक गतिविधियों को बढ़ावा देना, सार्वजनिक सुविधाओं का ध्यान रखना</i> और <i>स्थानीय समस्याओं का समाधान</i> करना था।</p> <h2>राजस्व-व्यवस्था</h2> <p><strong>विजयनगर साम्राज्य की राजस्व व्यवस्था</strong> अत्यंत <i>विस्तृत और संगठित</i> थी, जिसमें <strong>भूमिकर (शिष्ट)</strong> प्रमुख स्रोत था। भूमिकर की वसूली <i>नकद और उपज दोनों रूपों</i> में होती थी। <i>भूमि की उर्वरता, सिंचाई की उपलब्धता और फसल के प्रकार</i> के अनुसार कर दर तय होती थी। उपज का <strong>1/6 से लेकर 1/2</strong> तक हिस्सा <i>कर के रूप</i> में लिया जाता था। <strong>विशेष भूमि</strong> जैसे <i>ब्राह्मणों और मंदिरों की भूमि</i> पर <i>कम कर</i> लिया जाता था।</p> <p><strong>सिंचाई कर</strong> भी एक महत्वपूर्ण स्रोत था, जो <i>नहरों और बाँधों से सिंचाई करने वाले किसानों</i> से वसूला जाता था। इसके अलावा <strong>चुंगी, बिक्री कर, संपत्ति कर, पुलिस कर, विवाह कर</strong>, और <i>विशेष सेवा कर</i> जैसे दर्जनों अन्य कर भी थे। <strong>प्रायः कर संग्रह स्थानीय स्वायत्त संस्थाओं</strong> द्वारा होता था, लेकिन कहीं-कहीं <i>ठेकेदारी पद्धति</i> भी अपनाई जाती थी। <strong>कर संग्रह हेतु दो कोषागार</strong> होते थे—<i>एक दैनिक जरूरतों के लिए</i> और <i>दूसरा आपात स्थिति के लिए</i> सुरक्षित।</p> <p>राजस्व से प्राप्त धन का उपयोग <i>राजप्रासाद, सेना, धर्म कार्यों</i> और <i>संकट कालीन कोष</i> के लिए होता था। करों की दर यद्यपि कुछ अधिक थी, पर <strong>आपात स्थिति में राज्य करों में छूट</strong> भी देता था। यह व्यवस्था <i>राज्य की सैन्य और धार्मिक आवश्यकताओं</i> को ध्यान में रखकर बनाई गई थी।</p> <h2>न्यायिक प्रशासन</h2> <p><strong>विजयनगर साम्राज्य में न्याय व्यवस्था</strong> भी <i>सुव्यवस्थित</i> थी। <strong>स्थानीय स्तर</strong> पर <strong>ग्राम सभाएँ</strong> <i>छोटे-मोटे विवादों</i> को सुलझाने का कार्य करती थीं। <strong>गंभीर मामलों</strong> को <i>प्रांतीय न्यायालयों</i> में भेजा जाता था, और <strong>अंतिम निर्णय राजा</strong> द्वारा लिया जाता था। और यह <strong>अधिकारियों के माध्यम</strong> से कार्यान्वित होती थी। <strong>मंदिरों का भी न्यायिक कार्यों में महत्वपूर्ण योगदान</strong> था, क्योंकि <i>धार्मिक और सामाजिक विवादों</i> का समाधान अक्सर मंदिरों में किया जाता था। कुल मिलाकर, <strong>न्यायिक प्रशासन</strong> का मुख्य उद्देश्य <i>साम्राज्य में शांति, समानता और सामाजिक न्याय</i> सुनिश्चित करना था।</p> <h2>निष्कर्ष</h2> <p><strong>विजयनगर साम्राज्य की स्थानीय प्रशासनिक व्यवस्था</strong> एक <i>संगठित, सामाजिक और आर्थिक रूप से व्यावहारिक प्रणाली</i> थी, जिसमें <i>शासन, समाज और धर्म</i> के ताने-बाने को कुशलता से जोड़ा गया था। <strong>ग्रामसभा की स्वायत्तता</strong>, <strong>नायक प्रथा की स्थानीय भागीदारी</strong>, <strong>मंदिरों की सक्रियता</strong> और <strong>कर व्यवस्था की स्पष्टता</strong> इस शासन प्रणाली की विशेषताएँ थीं। यह व्यवस्था <i>उस समय की भारत की सबसे प्रभावशाली प्रशासनिक व्यवस्थाओं</i> में से एक थी, जिसने विजयनगर को <strong>लंबे समय तक एक शक्तिशाली साम्राज्य</strong> के रूप में बनाए रखा।</p>',210,'2025-06-05 14:34:07','2025-06-05 14:46:01','','Publish',0,'open',19,132),('दिल्ली सल्तनत के अधीन सैन्य व्यवस्था पर प्रकाश डालें','delhi-sultanate-military-system',2,'<p><strong>दिल्ली सल्तनत</strong> एक नव स्थापित मुस्लिम राज्य था, अधिकांश प्रजा <i>हिंदू</i> थी। स्थानीय राजपूत शासक सल्तनत के लिए चुनौती थे। इल्तुतमिश के शासनकाल में ही मंगोल (मंगल) भी नव स्थापित राज्य के लिए चुनौती बने हुए थे। ऐसी स्थिति में दिल्ली सल्तनत के अस्तित्व के लिए एक <strong>मजबूत सेना</strong> की आवश्यकता थी। दिल्ली के सुल्तानों ने सैन्य व्यवस्था को सुधारने के लिए <strong>व्यवस्थित सैन्य प्रशासन</strong> पर ध्यान दिया।</p>\r\n\r\n<h2>सेना की संरचना</h2>\r\n<p>सामान्यतः सुल्तान <strong>सैन्य प्रशिक्षण प्राप्त कुशल सेनानायक</strong> होते थे। सेना का प्रधान सेनापति था और सैनिक पदाधिकारी की नियुक्ति, उनकी परीक्षा और स्थानांतरण सुल्तान की इच्छा पर निर्भर था। यद्यपि सैद्धांतिक दृष्टि से सभी मुसलमान सैनिक माने जाते थे, परंतु वास्तव में सेना का गठन <strong>व्यावसायिक सैनिकों</strong> से हुआ था। सल्तनत काल में साधारणतः चार प्रकार के सैनिक होते थे</p>\r\n<ul>\r\n    <li><p>सुल्तान के सीधे नियंत्रण में रहने वाले <strong>नियाम सैनिक</strong></p></li>\r\n    <li><p>वे सैनिक जो प्रतिदिन सुवेदारों और अमीरों की सेवा के लिए स्थानीय रूप से भर्ती किए जाते थे</p></li>\r\n    <li><p>वे सैनिक जो मुख्यतः युद्ध के लिए समय विशेष भर्ती किए जाते थे</p></li>\r\n    <li><p>मुसलमान स्वयंसेवक, जो <i>जिहाद</i> अथवा धर्म युद्ध लड़ने के लिए सेवा में शामिल हो जाते थे</p></li>\r\n</ul>\r\n<h2>सुल्तान की केन्द्रीय सेना</h2>\r\n<p>दिल्ली में स्थित सुल्तान की सेना \'<strong>हश्म-ए-कल्ब</strong>\' (केन्द्रीय सेना) या \'<strong>कल्ब-ए-सुल्तानी</strong>\' कहलाती थीं जिसमें दो प्रकार के सैनिक होते थे- 1. सुल्तान के निजी सैनिक, 2.दिल्ली में निवास करने वाले दरबारी मंत्रियों और अन्य पदाधिकारियों के सैनिक</p>\r\n<p>सुल्तान के सैनिक \"<i>खास खेल</i>\" कहे जाते थे, और इनमें साही गुलाम तथा रक्षक शामिल होते थे। सल्तनत के इतिहास में पहली बार एक <strong>स्थाई सेना</strong> की नीव डाली गई थी, जिसे केंद्रीय सरकार द्वारा भारती किया जाता था और वेतन दिया जाता था, तथा इसकी पदाधिकारी भी उसी की अधीनता में कार्य करते थे। इस विशाल सेना में पदाति सैनिकों के अतिरिक्त लगभग <strong>415,000 घुड़सवार सैनिक</strong> थे। इस तरह के सैनिक मोहम्मद-बिन-तुगलक के समय तक कायम रहे। फिरोज-शाह-तुगलक ने उसे सामंती संगठन में परिवर्तन किया, जिसमें लोधी, करमाली, लोहानी, सूत और अन्य अफगान कबीले के लोग सम्मिलित थे। यह सेना दुर्बल थी, और इसका संगठन भी अव्यवस्थित था।</p>\r\n<h2>दशमलव प्रणाली</h2>\r\n<p>अलाउद्दीन खिलजी ने सेना का संगठन तुर्की ढंग से किया। सैनिकों का विभाजन <strong>दशमलव प्रणाली</strong> पर आधारित था। बर्नी द्वारा उल्लेखित बुगरा खा और केकूबाद के वार्तालाप से सल्तनत कालीन सैन्य संगठन पर पूर्ण प्रकाश पड़ता था। इस दशमलव व्यवस्था के अनुसार, एक सरखल में 10 घुड़सवार होते थे, एक सिपहसालार के पास 10 सरखल, एक अमीर के पास 10 सिपहसालार और एक मालिक के पास 10 अमीर होते थे, और एक खान के पास 10 मलिक होते थे। इस प्रकार, खान एक लाख सैनिकों का सेनापति होता था।</p>\r\n<h2>घुड़सवार, पैदल और हाथी सेना तथा वेतन और भत्ते</h2>\r\n<p>सल्तनत कालीन सेना में तत्कालीन आवश्यकता एवं अनुभव के आधार पर प्रमुख रूप से घुड़सवार, हाथी, पैदल और अग्नि शास्त्र सैनिकों का समावेश था। इसमें कोई संदेह नहीं है कि तुर्कों की भारत विजय में <strong>अश्वनी सेना</strong> का सर्वाधिक योगदान रहा। इन सैनिकों के बल पर ही मंगोलों के आक्रमण का सफलतापूर्वक सामना किया जा सका। प्रत्येक घुड़सवार के पास दो तलवारें, एक भाला, एक धनुष और कई बाण होते थे। कभी-कभी वह गद्दा भी धारण करते थे। सैनिक कवच पहनते थे और घोड़े को सजाया जाता था। वास्तव में अश्वरोही सैनिक निम्न श्रेणियों में विभक्त होते थे</p>\r\n<ul>\r\n    <li><p><strong>मुर्तास्त</strong> (या अस्पा यस)- एक सामान्य सैनिक था जिसके पास एक घोड़ा होता था। अलाउद्दीन के शासनकाल में इसका वेतन 234 टका प्रति वर्ष था।</p></li>\r\n    <li><p>दो अस्पा - इन सैनिकों के पास दो घोड़े होते थे और इन्हें 75 टका अतिरिक्त प्रतिवर्ष दिया जाता था।</p></li>\r\n</ul> \r\n<p>सेना का एक अन्य महत्वपूर्ण अंग <strong>हाथी सेना</strong> थी, जिसे \'<i>हस्ती</i>\' कहा जाता था। हाथी सेना पर सुल्तान को काफी भरोसा था। कहा जाता है कि बलवंत युद्ध में एक हाथी को 50 घुड़सवारों के बराबर माना जाता था। मोहम्मद बिन तुगलक के पास 3000 हाथी थे। फिरोज शाह तुगलक के पास भी लगभग उतने ही थे। हाथियों को रखना सुल्तान का विशेष अधिकार माना जाता था, लेकिन कभी-कभी कुछ अमीरों को भी हाथी रखने की अनुमति दी जाती थी।</p>\r\n<p>सेना का दूसरा महत्वपूर्ण अंग <strong>पैदल सैनिक</strong> था, जिन्हें \'<i>पायक</i>\' कहा जाता था। उनमें से अधिकांश भारतीय मुसलमान, हिंदू और गुलाम होते थे। वे तलवार, भाला और धनुषधारी होते थे। निम्न श्रेणी के सैनिक होने के बावजूद, ये कभी-कभी महत्वपूर्ण भूमिका निभाते थे। उदाहरण स्वरूप, अव्वल खान के नेतृत्व में पैदल सैनिकों ने अलाउद्दीन खिलजी की रक्षा की थी।</p>\r\n<p>सैनिक पदाधिकारियों को भू-राजश्व के रूप से वेतन मिलता था। हालांकि, कुछ सुल्तानों ने नगद वेतन भी दिया। अलाउद्दीन खिलजी के शासनकाल में एक सुसज्जित सैनिक का वेतन 234 टका प्रति वर्ष था, जबकि मोहम्मद बिन तुगलक के समय यह 500 टका तक हो गया था। युद्ध के समय सिपाहियों को भोजन, वस्त्र और आवास मुफ्त में दिए जाते थे। वेतन समय-समय पर घटता-बढ़ता रहता था, और इसके साथ ही उनके अधीन सैनिकों का वेतन भी शामिल होता था।</p>\r\n<p>अनियमित सैनिक, जिन्हें <i>गैर-वजही</i> कहा जाता था, उन्हें थोड़े समय के लिए भर्ती किया जाता था। वे नगद वेतन प्राप्त करते थे, जिसे कभी-कभी केंद्रीय राजकोष से भी दिया जाता था। फिरोज तुगलक के शासनकाल में सैनिकों को भू-राजस्व के रूप में वेतन देने की प्रथा प्रचलित थी।</p>\r\n\r\n<h2>तोपखाना और युद्ध तकनीक</h2>\r\n<p>सल्तनत काल में आधुनिक ढंग का <strong>तोपखाना</strong> नहीं था, किंतु युद्ध में ज्वलनशील, बानो वर्धा और ज्वलनशील पदार्थ से भरे हुए पत्रों का प्रयोग किया जाता था। इसके अतिरिक्त, मैंगनीक अथवा मगोल नामक मशीन भी होती थी, जिसके द्वारा बड़े पत्थर के टुकड़े और चट्टानें दुश्मनों पर फेंकी जाती थीं। सुल्तान के अधिकार में नावों का एक विशाल बेड़ा भी होता था, जिसका प्रयोग सामान ढोने और नदियों के युद्ध में किया जाता था।</p>\r\n\r\n<h2>सैन्य प्रशासन और सुधार</h2>\r\n<p> बलबन के समय तक सेना के अधिकांश सैनिक वंशानुगत हो गए थे। युद्ध के अवसर पर सैनिक अपने प्रतिनिधियों को भेज देते थे। अलाउद्दीन खिलजी ने इस भ्रष्टाचार को दूर करने के प्रयास किए। उसने घोड़े की निरीक्षण प्रथा शुरू की, ताकि निरीक्षण के समय एक ही घोड़े को दो बार प्रस्तुत न किया जा सके। उसने एक रजिस्टर में सैनिक का <i>हुलिया</i> (विवरण) लिखवा लिया जाता था, ताकि कोई सैनिक या अधिकारी अपने स्थान पर किसी दूसरे व्यक्ति को न भेज सके। इस सुधार से अनुशासन की पुनर्स्थापना हुई। फिरोज शाह तुगलक के समय में इन नियमों की अपेक्षा किया गया और सैनिक को अपने स्थान पर अपना प्रतिनिधि भेजने की इजाजत दी गई। सिकंदर लोदी के काल में सेना में अनुशासन कायम किया गया और उसने दाग और चेहरा प्रथा को सख्ती से लागू किया। सैनिकों को नकद वेतन दिया जाता था, लेकिन फिरोज शाह तुगलक ने भू-राजस्व के रूप में वेतन देना शुरू किया।</p>\r\n\r\n<h2>युद्ध नीति और संरचना</h2>\r\n\r\n<p>सेना के कुछ हिस्से सामरिक महत्व वाले स्थानों पर तैनात होते थे। सामान्य किलों की रक्षा के लिए अनुभवी सैनिक रखे जाते थे। किलों में रसद और पशुओं की समुचित व्यवस्था होती थी, और यह प्रबंधन किलेदार या किले के अध्यक्ष द्वारा किया जाता था।</p>\r\n<p>सुल्तान युद्ध नीति में दक्ष होते थे और छिपकर एवं सहसा आक्रमण की रणनीति का बहुत प्रयोग किया जाता था। युद्ध क्षेत्र में सैनिकों को विभिन्न भागों में बांटा जाता था, जैसे अग्रगामी दल, केंद्र, वामपर्श, दक्षणपार्श, रिर्जवदन  आदि। युद्ध क्षेत्र में हाथियों को खड़ा किया जाता था और उनके आगे घुड़सवारों को तैनात किया जाता था। पानीपत की पहली लड़ाई में इब्राहीम लोदी की सेना में यह व्यवथा अनुपस्थित थी, जबकि बाबर की सेना में यह थी, यही कारण था कि इब्राहीम की पराजय हुई। सैनिकों के साथ स्थानीय भेदियों का भी प्रयोग किया जाता था, जो शत्रु की गतिविधियों का निरीक्षण कर, संबंधित समाचार सेनापति को देते थे।</p>\r\n\r\n<h2>प्रांतीय और सामंती सैनिक</h2>\r\n<p>केंद्र की सेना पर सुल्तान का नियंत्रण होता था, लेकिन प्रांतीय सेना और अमीरों के सैनिकों पर नियंत्रण कम होता था। फिरोज शाह तुगलक के समय <strong>सामंतीकरण</strong> हुआ और जिसमें लोधी, करमाली, लोहानी, सूत और अन्य अफगान कबीले के लोगो को सेना में शामिल किया गया।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n<p>उपरोक्त विवेचना से यह स्पष्ट है कि सुल्तानों के शासनकाल में सैनिक प्रशासन की दक्षता में बढ़ोतरी हुई, जबकि अंतिम समय में प्रशासन भ्रष्टाचार का शिकार हो गया। अलाउद्दीन खिलजी के शासनकाल में सैनिक विभाग का भ्रष्टाचार न्यूनतम स्तर पर था, और उसने सैनिकों को नगद वेतन दिया। फिरोज तुगलक के समय में सैनिकों को नगद वेतन देने की प्रथा समाप्त कर दी गई, और उन्हें उनके हिस्से के राजस्व का वितरण किया जाने लगा। सेना विभाग सुलतान के अस्तित्व के लिए अत्यंत महत्वपूर्ण था, और एक मजबूत सेना के सहारे ही सुल्तान अपनी सत्ता कायम रख सकते थे। इसलिए सभी सुल्तानों ने सैनिक प्रशासन पर ध्यान दिया और उसे अपने नियंत्रण में रखने का प्रयास किया।</p>\r\n',248,'2025-06-05 14:34:07','2025-06-05 14:54:39','','Publish',0,'open',19,133),('ज़मींदारी उन्मूलन अधिनियम','zamindari-eradication-act',70,'<p><strong><i>ज़मींदारी प्रथा</i></strong> भारत में ब्रिटिश शासन द्वारा शुरू की गई एक व्यवस्था थी, जिसमें <i>ज़मींदार किसानों से लगान वसूलते थे और स्वयं खेती नहीं करते थे</i>। इससे <strong>किसानों का शोषण</strong> होता था और वे <strong>भूमि के स्वामी नहीं</strong> होते थे।</p>\r\n\r\n<p><i>स्वतंत्रता प्राप्ति</i> के बाद सरकार ने किसानों को भूमि का मालिक बनाने और शोषण को समाप्त करने के लिए <strong>ज़मींदारी उन्मूलन अधिनियम</strong> लागू किए। सबसे पहले <strong>1951 में उत्तर प्रदेश</strong> ने यह कानून बनाया, इसके बाद अन्य राज्यों ने भी इसका पालन किया।</p>\r\n\r\n<p>इस अधिनियम के तहत <i>ज़मींदारों से भूमि छीनकर</i> उसे सरकार ने अधिग्रहित किया और <strong>वास्तविक किसानों को मालिकाना हक</strong> दिया गया। इससे <strong>किसानों की स्थिति में सुधार</strong> हुआ, <i>सामाजिक समानता बढ़ी</i> और <strong>कृषि विकास को प्रोत्साहन</strong> मिला।</p>\r\n\r\n<p><strong>ज़मींदारी प्रथा का उन्मूलन</strong> स्वतंत्र भारत में <i>सामाजिक न्याय और आर्थिक सुधार</i> की दिशा में एक <strong>ऐतिहासिक कदम</strong> था। इसने <strong>किसानों को सशक्त</strong> बनाया, <i>कृषि उत्पादन को बढ़ाया</i> और <strong>भूमि के स्वामित्व को न्यायसंगत</strong> बनाया। हालांकि <i>क्रियान्वयन में कुछ चुनौतियाँ</i> थीं, फिर भी यह एक <strong>बड़ी सामाजिक क्रांति</strong> साबित हुई।</p>\r\n\r\n<p>यदि <i>ज़मींदारी प्रथा को समय रहते समाप्त न किया गया होता</i>, तो भारत का <strong>कृषि क्षेत्र और भी अधिक असमानता व शोषण</strong> का शिकार हो सकता था। आज भी <i>भूमि सुधार की प्रक्रिया अधूरी</i> है, और <strong>ज़मींदारी उन्मूलन अधिनियम</strong> इसकी एक <strong>मजबूत नींव</strong> के रूप में देखा जाता है।</p>\r\n',21,'2025-06-06 02:19:36','2025-06-06 02:31:44','','Publish',0,'open',0,134),('भूमि सीमा अधिनियम','land-limit-act',70,'<p><strong><i>भूमि सीमा अधिनियम</i></strong> (Land Ceiling Act), जिसे <i>कृषि भूमि सीमा (ALC) अधिनियम</i> भी कहा जाता है, <strong>1960 के दशक</strong> में बड़े भूमिधारकों से <i>भूमि पुनर्वितरित</i> करने के लिए लागू किया गया था। इसका उद्देश्य था कि <strong>एक व्यक्ति या परिवार के पास ज्यादा भूमि न हो</strong> और <i>अतिरिक्त भूमि भूमिहीन और छोटे किसानों में बांटी जाए</i>।</p>\r\n\r\n<p><i>स्वतंत्रता प्राप्ति के समय</i> भारतीय समाज में <strong>भूमि का अत्यधिक असमान वितरण</strong> था। बहुत से <i>जमींदारों के पास विशाल भूमि क्षेत्र</i> थे, जबकि <strong>किसानों और भूमिहीन व्यक्तियों के पास भूमि नहीं</strong> थी। इस <i>असमान वितरण को सुधारने</i> के लिए <strong>भूमि हदबंदी अधिनियम</strong> को लागू किया गया, ताकि ज़मींदारों के पास अधिक भूमि नहीं रह जाए और उसे <strong>छोटे किसानों को वितरित</strong> किया जा सके।</p>\r\n\r\n<p>भारत में <strong>भूमि हदबंदी का पहला कदम</strong> <i>1950 के दशक</i> में उठाया गया। विभिन्न राज्यों ने अपने-अपने स्तर पर <strong>भूमि हदबंदी कानूनों</strong> को लागू किया। यह कानून मुख्य रूप से <i>ज़मींदारों और बड़े किसानों के पास भूमि की अधिकता</i> को सीमित करने के लिए था। <strong>भारतीय संविधान के अनुच्छेद 39(b) और (c)</strong> ने इस प्रकार के <i>भूमि सुधारों को बढ़ावा</i> दिया, ताकि <strong>समाज में असमानता को कम</strong> किया जा सके।</p>\r\n',23,'2025-06-06 02:19:36','2025-06-06 02:35:20','','Publish',0,'open',0,135),('झारखंड की आदिवासी महिलाओं की शिक्षा','education-of-tribal-women-of-jharkhand',2,'<p><strong>झारखंड की जनजातियाँ अपनी समृद्ध संस्कृति और परंपराओं के लिए विख्यात हैं।</strong> यहाँ की <strong>आदिवासी महिलाएँ समाज की आत्मा</strong> मानी जाती हैं। वे खेतों में कार्य करती हैं, घर-परिवार का पालन-पोषण करती हैं, धार्मिक अनुष्ठानों का संचालन करती हैं तथा <em>लोकगीत व लोकनृत्य के माध्यम से संस्कृति</em> को पीढ़ी दर पीढ़ी आगे बढ़ाती हैं।</p>\r\n\r\n<p>हालाँकि, <strong>शिक्षा के दृष्टिकोण से इन महिलाओं की स्थिति लंबे समय तक चिंताजनक रही है।</strong> किंतु वर्तमान समय में कई <em>आदिवासी महिलाएँ न केवल शिक्षित हो रही हैं</em>, बल्कि समाज में <strong>नेतृत्व और परिवर्तन का प्रतीक</strong> भी बन रही हैं।</p>\r\n\r\n<p><strong>शिक्षा वह साधन है</strong> जिसके माध्यम से व्यक्ति न केवल <em>अपना जीवन संवारता</em> है, बल्कि <em>समाज और राष्ट्र के विकास में भी</em> सक्रिय भागीदारी निभाता है। यदि <strong>आदिवासी महिलाओं की शिक्षा पिछड़ी</strong> रहेगी तो <em>समाज के समग्र विकास की कल्पना अधूरी</em> रह जाएगी।</p>\r\n\r\n<p>झारखंड के आदिवासी समाज का <strong>प्रकृति से गहरा लगाव</strong> रहा है। बच्चे बचपन से ही खेतों में कार्य करना, जंगलों से औषधीय पौधों की पहचान करना, बाँस की वस्तुएँ बनाना, नृत्य और गीत सीखना प्रारंभ कर देते हैं। <em>महिलाओं की शिक्षा धारा यहाँ विशिष्ट</em> है, क्योंकि वे <strong>नृत्य और गीतों के माध्यम से सामाजिक मूल्यों की शिक्षा</strong> देती हैं।</p>\r\n\r\n<p>परंपरागत रूप से, आदिवासी समुदाय में <strong>लड़कियों की पढ़ाई को आवश्यक नहीं</strong> माना गया। <em>शिक्षा की आवश्यकता को पर्याप्त महत्व नहीं</em> दिया गया। उनका मानना था कि <strong>लड़कियों को घरेलू कार्य और जीवन निर्वाह</strong> के लिए तैयार करना अधिक महत्वपूर्ण है।</p>\r\n\r\n<p>ब्रिटिश शासन के आगमन के साथ ही <strong>झारखंड की प्राकृतिक संपदा का शोषण</strong> शुरू हुआ। वहीं, <em>ईसाई मिशनरियों ने भी यहाँ प्रवेश किया</em>। 19वीं शताब्दी में उन्होंने <strong>धर्म प्रचार के साथ-साथ जनजातीय समुदाय को शिक्षित</strong> करने के उद्देश्य से कई मिशनरी विद्यालय खोले।</p>\r\n\r\n<p><strong>1840 के बाद</strong>, छोटानागपुर क्षेत्र में <strong>जर्मन मिशनरियों और आयरिश पादरियों</strong> ने लड़कियों के लिए प्राथमिक विद्यालय शुरू किए। हालाँकि, यह शिक्षा सीमित स्तर तक ही पहुँच सकी क्योंकि <em>आदिवासी परिवार अपनी बेटियों को स्कूल भेजने में हिचकिचाते थे।</em></p>\r\n\r\n<p>इसके पीछे कई कारण थे — जैसे, <em>लड़कियों का घरेलू और खेत का काम</em>, <strong>बाल विवाह की प्रथा</strong>, मिशनरी शिक्षा का <em>स्थानीय परंपराओं से भिन्न होना</em>, <strong>भाषायी अंतर</strong> आदि। फिर भी, जो महिलाएँ <em>मिशन स्कूलों से शिक्षित हुईं</em>, वे आगे चलकर <strong>शिक्षिका, नर्स और समाज सुधारक</strong> बनीं।</p>\r\n\r\n<p><strong>1947 में स्वतंत्रता प्राप्ति</strong> के पश्चात भारत सरकार ने <strong>शिक्षा को विकास का आधार</strong> माना। आदिवासी क्षेत्रों के लिए विशेष योजनाएँ बनाई गईं। उस समय <em>झारखंड बिहार का हिस्सा</em> था। <strong>आदिवासी बालिका छात्रावास</strong>, <strong>छात्रवृत्ति योजनाएँ</strong> और <em>निःशुल्क शिक्षा</em> जैसी नीतियाँ लागू की गईं।</p>\r\n\r\n<p>गुमला, संथाल परगना और पलामू जैसे क्षेत्रों में <strong>बालिका विद्यालय</strong> खोले गए। <strong>1960 के दशक में स्थापित कस्तूरबा गांधी विद्यालय</strong> ने भी <em>बालिकाओं की शिक्षा में महत्त्वपूर्ण भूमिका</em> निभाई।</p>\r\n\r\n<p>हालाँकि, कई <strong>चुनौतियाँ अब भी बनी रहीं</strong> — जैसे <em>गरीबी, खेतिहर जीवनशैली, परिवहन की समस्या</em>, <strong>दूरस्थ गाँवों से विद्यालय तक पहुँच की कठिनाई</strong>, और यह <em>सामाजिक धारणा कि लड़कियों का कार्य घर-परिवार संभालना है</em>।</p>\r\n\r\n<p><strong>सन् 2000 में झारखंड को बिहार से अलग</strong> कर नया राज्य बनाया गया। इसके बाद राज्य सरकार ने <strong>आदिवासी शिक्षा, विशेषकर बालिका शिक्षा पर विशेष ध्यान</strong> दिया। <strong>2004 के बाद</strong> से <em>कस्तूरबा गांधी आवासीय विद्यालय</em> और <strong>नवोदय विद्यालय</strong> जैसी संस्थाओं ने <em>आदिवासी बालिकाओं को माध्यमिक एवं उच्च माध्यमिक शिक्षा</em> तक पहुँच प्रदान की।</p>\r\n\r\n<p><strong>1951 में आदिवासी महिलाओं की साक्षरता दर</strong> मात्र <em>8-10%</em> थी, जबकि <strong>2011 की जनगणना</strong> के अनुसार यह लगभग <em>45%</em> तक पहुँच चुकी थी। <strong>2021 के नवीनतम आँकड़े</strong> दर्शाते हैं कि यह दर अब <em>55% से अधिक</em> हो चुकी है, यद्यपि यह अब भी <strong>राष्ट्रीय औसत से काफी कम</strong> है।</p>\r\n\r\n<p>पिछले दो दशकों में <strong>आदिवासी समाज में व्यापक परिवर्तन</strong> देखने को मिला है। कई बालिकाएँ <em>शिक्षा प्राप्त कर नर्सिंग, शिक्षण, खेलकूद और सरकारी सेवाओं</em> में सफलता प्राप्त कर रही हैं।</p>\r\n\r\n<p><strong>हॉकी खिलाड़ी निक्की प्रधान</strong>, <strong>तीरंदाज दीपिका कुमारी</strong>, और अन्य कई <em>आदिवासी महिलाएँ शिक्षा और खेल दोनों में प्रेरणास्रोत</em> बन चुकी हैं।</p>\r\n\r\n<h2>निष्कर्ष</h2>\r\n\r\n<p>उपरोक्त अध्ययन से स्पष्ट होता है कि <strong>झारखंड की आदिवासी महिलाओं की शिक्षा का इतिहास एक लंबा संघर्ष</strong> रहा है। <em>परंपरागत समाज, गरीबी और अज्ञानता</em> ने इन्हें लंबे समय तक शिक्षा से दूर रखा।</p>\r\n\r\n<p>लेकिन <strong>झारखंड राज्य के गठन</strong> के बाद <em>शिक्षा के क्षेत्र में सुधार</em> हुए और अब <strong>आदिवासी महिलाएँ न केवल पढ़-लिख रही हैं</strong>, बल्कि <em>समाज में नेतृत्व और परिवर्तन की प्रतीक</em> बन रही हैं।</p>\r\n\r\n<p>फिर भी, <strong>आदिवासी महिलाओं तक शिक्षा की पूर्ण पहुँच</strong> अब भी एक चुनौती है। <em>विद्यालयों में शिक्षकों की कमी, भाषाई समस्याएँ, विद्यालय की दूरी</em> आदि प्रमुख बाधाएँ बनी हुई हैं। सरकार को इन समस्याओं पर <strong>गंभीरता से ध्यान देना चाहिए</strong>, ताकि <em>झारखंड की प्रत्येक आदिवासी महिला तक शिक्षा की किरण पहुँच सके</em>।</p>\r\n',32,'2025-10-01 05:41:29','2025-10-01 05:41:31','','Publish',0,'open',9,136);
